// WO-423: the typed `grblBackend` reference is GONE. Both things it existed
// for are contract members now - `loadPreparedJob` is the interface's own
// optional member, and contract v3's ControllerEvents carries the job, alarm,
// offset, settings, homing, accessory and ready channels. Nothing above the
// backends reaches past the interface any more.
let controller: MachineController | null = null
// WO-2316: setMachinePosition is synchronous and the simulator publishes its
// datum through onHomed too. Keep that state reconciliation, but distinguish
// its acknowledgement from a completed homing cycle's console announcement.
let settingMachinePosition = false
let activeBackendDefinition: MachineBackendDefinition | null = null
/** Every installed backend owns one event generation. Event closures retain
 * this scope, so a replaced backend cannot mutate the new session or read
 * state back from the new controller. A reconnect on the same backend mints a
 * fresh generation when its connecting edge begins. */
interface BackendEventScope {
  controller: MachineController | null
  generation: number
  phase: ConnectionPhase
  connectStarted: boolean
  workOffsetConnectReconcileComplete: boolean
  controllerReopenRestoreSequence: number
  /** Wording only: the axes in this home, independent of any existing datum. */
  homeAnnouncement?: { requested: ControlAxis[]; remaining: Set<ControlAxis>; sawHome: boolean }
  /** WO-2670: a bridge "clamped" note waiting for the board's settled
   *  readback. On the scope so a newer press on the channel retires it. */
  overrideClamps: Map<OverrideChange['kind'], PendingOverrideClamp>
  /** WO-2670: the bridge `setOverride` calls sent and not yet answered, by
   *  call seq. Bridge.cs writes a call's note just before its reply, so a
   *  note answers the oldest of these on its channel. Null until the bridge
   *  link is tapped (`tapBridgeOverrideCalls`); other backends send no note. */
  overrideCallsInFlight: Map<number, OverrideChange['kind']> | null
}
/** The bridge's immediate readback said the board holds `held`, not
 *  `requested`. Judged only against status frames, see
 *  `buildContractEvents`. */
interface PendingOverrideClamp {
  requested: number
  held: number
  notedAtMs: number
  lastReadback: number | null
  /** Values earlier presses on the channel asked for, noted within
   *  OVERRIDE_CLAMP_SETTLE_MS before this one. The board may still be
   *  landing them, so a readback at one proves nothing about `requested`. */
  earlierAsks: number[]
}
/** How long a readback still showing the value from before the press may lag
 *  the press. Hardware 2026-10-07: the feed override was held ~0.3 s after
 *  each click; the bridge's own readback and the next 40 Hz frame are both
 *  often taken before that. */
const OVERRIDE_CLAMP_SETTLE_MS = 1000
/** WO-2670: tie each bridge clamp note to the call it answers. The note
 *  rides the socket ahead of its own reply, and the operator's next press can
 *  be sent before either arrives, so nothing in the note itself says which
 *  press it describes. Watching this link's own setOverride calls and replies
 *  does: while a later call on the channel is still unanswered, the note is
 *  about a press the operator already replaced. Nothing sent changes. */
function tapBridgeOverrideCalls(transport: BridgeTransport, scope: BackendEventScope): void {
  const inFlight = new Map<number, OverrideChange['kind']>()
  scope.overrideCallsInFlight = inFlight
  const send = transport.send.bind(transport)
  transport.send = (message) => {
    if (message.m === 'setOverride') {
      const kind = (message.a.change as OverrideChange | undefined)?.kind
      if (kind !== undefined) {
        // A newer press retires any note still waiting on its channel.
        scope.overrideClamps.delete(kind)
        inFlight.set(message.seq, kind)
      }
    }
    send(message)
  }
  const start = transport.start.bind(transport)
  transport.start = (events) => {
    inFlight.clear()
    return start({
      ...events,
      onMessage: (message) => {
        if (message.t === 'reply') inFlight.delete(message.seq)
        events.onMessage(message)
      },
    })
  }
}
let backendGenerationSequence = 0
let activeBackendScope: BackendEventScope | null = null
let connectionAttemptSequence = 0
let controlMachineSelectionSequence = 0
let controlMachineSelectionDisconnect: Promise<void> | null = null

function createBackendEventScope(): BackendEventScope {
  return {
    controller: null,
    generation: 0,
    phase: 'disconnected',
    connectStarted: false,
    workOffsetConnectReconcileComplete: false,
    controllerReopenRestoreSequence: 0,
    overrideClamps: new Map(),
    overrideCallsInFlight: null,
  }
}

function beginBackendGeneration(scope: BackendEventScope): void {
  scope.generation = ++backendGenerationSequence
  scope.homeAnnouncement = undefined
  scope.workOffsetConnectReconcileComplete = false
  scope.controllerReopenRestoreSequence = 0
  // A replacement backend invalidates the old generation's write just as an
  // in-place physical reopen does. Release its stale slot before any work can
  // be issued to the replacement controller.
  openWorkOffsetWrite = null
  setWorkOffsetWriteInFlight(controlMachineId(), false)
  activeBackendScope = scope
  resetBackendSessionState(scope.controller)
}

/** Operational modes and telemetry knowledge belong to one backend generation.
 * Set the controller first, then publish the render snapshot, so no subscriber
 * can observe Single Block ON beside a controller that has already reset it. */
function resetBackendSessionState(target: MachineController | null): void {
  activeSpindleCommand = null
  target?.setSingleBlockMode(false)
  store().resetControllerSessionState()
}

function acceptsBackendEvent(scope?: BackendEventScope): boolean {
  return scope === undefined || (
    scope === activeBackendScope
    && scope.controller !== null
    && scope.controller === controller
  )
}

interface BackendGenerationToken {
  controller: MachineController
  generation: number
}

function captureBackendGeneration(target: MachineController): BackendGenerationToken | null {
  const scope = activeBackendScope
  return scope?.controller === target ? { controller: target, generation: scope.generation } : null
}

function backendGenerationIsCurrent(token: BackendGenerationToken | null): boolean {
  // Exported receipt helpers are also exercised with standalone controller
  // fakes that were never installed into the singleton session. They have no
  // generation to go stale; installed production backends always do.
  return token === null || (
    activeBackendScope?.controller === token.controller
    && activeBackendScope.generation === token.generation
    && controller === token.controller
  )
}

interface BackendReceiptToken {
  backend: BackendGenerationToken | null
  revision: number
}

function captureBackendReceipt(target: MachineController): BackendReceiptToken {
  return { backend: captureBackendGeneration(target), revision: connectionRevision }
}

/** One predicate for every awaited backend continuation. Standalone injected
 * test controllers have no installed generation and retain their old behavior;
 * every production controller is bound to both its backend generation and the
 * physical-session revision current when the request crossed the boundary. */
function receiptIsCurrent(token: BackendReceiptToken): boolean {
  return token.backend === null || (
    token.revision === connectionRevision
    && backendGenerationIsCurrent(token.backend)
  )
}
/** WO-416/WO-433: the connected SimulatedController, when the current
 *  connection is the simulator - null against real hardware or before
 *  connect. Lets the Diagnostics panel reach the virtual-part pass-through
 *  without the rest of the app knowing the controller is simulated. */
let simulatedController: SimulatedController | null = null
/**
 * WO-1323: A SETUP BOUNDARY INSIDE ONE PROGRAM'S PART LIST.
 *
 * A capacity boundary is invisible: the same setup continues in the same frame
 * and the operator is told a part number. A SETUP boundary is not - the tool
 * has retracted clear, the next setup runs at a different zero, and on a real
 * two-setup part the work has to be turned over before anything else happens.
 * So this records what the session must do there, and `clearMachineZ` is the
 * one number that keeps the frame from changing while the tool is still down.
 */
interface ProgramSetupBoundary {
  /** The setup whose last part has just finished. */
  finishedName: string
  /** The setup the program continues into. */
  nextName: string
  /** The work frame held by the part that just finished. */
  fromWcs: WcsId
  /** The frame the controller must hold before the next setup's first move. */
  wcs: WcsId
  /** Machine Z the tool must have REPORTED reaching before the frame changes,
   *  or null when the outgoing setup declared no retract height. */
  clearMachineZ: number | null
  /** WO-1335: what the operator is told at this hold, when the boundary is not
   *  between two SETUPS. A posted file's boundary is between two sections of a
   *  file (or an M0 in one), and "Set up Setup 2" would name something the
   *  operator is not looking at. Absent on every setup boundary, which keeps
   *  WO-1323's sentence the one they get. */
  holdMessage?: string
  /** The posted-file macro call that caused this boundary, when there is one.
   *  WO-1652: the machine's macro bound to that code runs here; a code with no
   *  macro keeps the generic hold. `toolChange` (WO-1652 tightening): the tool
   *  the reader counted for a macro whose body calls `toolChange()` - its
   *  tool-change hold follows the macro however it ends. */
  macro?: { line: number; code: number; toolChange?: number }
  /** WO-1652: what the macro API's `toolChange()` fits at this macro boundary -
   * the tool in the spindle for the finished section, the file's last `T`
   * before the macro's line, and the incoming section's spindle. Read only
   * when the bound macro calls `toolChange()`, which then fills `toolChange`
   * and `m6` below so the programmed tool change runs from there, unchanged. */
  macroToolChange?: { from: number | null; to: number | null; spindle: ProgramSpindle | null }
  /** WO-1652 fix round 4: the file's own M6 at this boundary (text route),
   *  with or without a tool-change park. A macro bound to M6 runs here as a
   *  PRELUDE, and the tool-change hold follows however it ends. */
  postedM6?: { line: number; tool: number }
  /**
   * WO-1329, Operator at the machine 2026-09-11: "What if I want to run directly
   * from the G54 setup into G55 without stopping?" When the operator loaded the
   * program with "Continue through the setups" on - which is the default - and
   * the tool does not change, this boundary is CROSSED rather than held: the
   * retract-clear readback, the frame selection and the next stage's start all
   * happen here, in the order they always did, with the CYCLE START the
   * operator would have pressed pressed by the program.
   *
   * Absent on every posted-file boundary (WO-1335), which is between two
   * sections of a file and stays a hold.
   */
  runThrough?: boolean
  /**
   * WO-1330: THIS BOUNDARY CHANGES TOOL, so it is a tool-change SEQUENCE and
   * never a run-through, whatever the operator ticked (Operator at the machine,
   * 2026-09-11). Present only on a boundary whose two stages cut with
   * different tools; `runThrough` is false wherever this is set.
   *
   * `spindle` is the INCOMING stage's speed and direction, which is what the
   * up-to-speed gate arms for when the hold is released. A program spanning
   * setups otherwise carries one spindle intent - that rule relaxes here and
   * only here, because the tool that intent belongs to has just changed.
   */
  toolChange?: {
    /** The tool coming out of the spindle, in plain words. */
    leaving: string
    /** The tool to fit, in plain words. */
    fit: string
    spindle: ProgramSpindle | null
  }
  /** WO-1369: an M6 from a posted file, rather than a tool difference inferred
   * from two LienCAM setups. It runs the fixed-pad macro when this boundary is
   * reached; ordinary setup tool-change holds keep their existing manual flow. */
  m6?: { line: number; tool: number; code?: number }
}

/** WO-1335: one spindle word of a posted file, at the part it falls due. */
interface GcodeSpindleWord {
  /** True for M3/M4 (the file starts the spindle again), false for M5. */
  on: boolean
  /** The line that commanded it - which is where the operator looks. */
  line: number
  /** THE SPEED AND DIRECTION THE MOVES AFTER IT RUN AT, null for a stop. It
   *  travels with the word rather than being read off one program-wide intent,
   *  because the architect's re-scope allows a file to change speed: the
   *  up-to-speed gate re-arms on every release, so a second speed is honoured
   *  by the same mechanism that honours the first. */
  intent: { rpm: number; direction: 'cw' | 'ccw' } | null
}

/** WO-1335 re-scope: one coolant word of a posted file, at the part it falls
 *  due. A machine whose record states the channel gets it COMMANDED here; one
 *  that does not was told at load time that this file wants coolant and that
 *  the machine has no output for it. */
interface GcodeCoolantWord extends GcodeCoolantState {
  line: number
}

interface ProgramPartsRun {
  controller: MachineController
  parts: MachineProgram[]
  partIndex: number
  completedMoves: number
  totalMoves: number
  completionSignaled: boolean
  advancing: boolean
  heldBetweenParts: boolean
  started: boolean
  /** WO-1323: keyed by the index of the part that STARTS a new setup. Absent
   *  on every single-setup program, which is why those take an unchanged path
   *  through the whole parts machinery. */
  boundaries?: Map<number, ProgramSetupBoundary>
  /** WO-1329: the operator-responsibility line a run-through program printed at
   *  load, kept so CYCLE START can say it again when the load scrolled away.
   *  Absent unless this program runs through its setup boundaries. */
  continuation?: { line: string; saidAtMs: number }
  /** WO-1335: the FILE'S OWN M3/M5, keyed by the index of the part its motion
   *  starts at - the inverter is commanded in the gap before that part is
   *  released. Absent on every toolpath program, which carries one spindle
   *  intent for its whole length and no way to write a second word. */
  spindleWords?: Map<number, GcodeSpindleWord>
  /** WO-1335 re-scope: the file's own M7/M8/M9, keyed the same way. */
  coolantWords?: Map<number, GcodeCoolantWord>
  /** WO-1335 fix round 3: the coolant state this run has actually COMMANDED so
   *  far, which is what decides whether the next word changes anything. It
   *  starts at the first section's own coolant, so a file whose preamble
   *  switches flood on does not re-command it at its second section. */
  coolantApplied?: GcodeCoolantState
  /** The file's FIRST spindle intent. Each word carries the intent its own
   *  moves run at; this is kept only for the sentences that name the program's
   *  speed. Null when the file commands no spindle at all. */
  spindleIntent?: { rpm: number; direction: 'cw' | 'ccw' } | null
  /** Whether this connection can actually drive that intent (machine record AND
   *  live controller both declare the VFD path). When it cannot, the file's
   *  spindle words are still SAID at the moment they fall due - the operator is
   *  the one driving the spindle. */
  spindleDriven?: boolean
  /** The boundary part index whose hold has already been announced, so the
   *  operator's CYCLE START releases it instead of re-holding at it. */
  announcedBoundary?: number
  /** WO-1677: the part as it must be staged NOW - the file's `G43 H` lengths
   *  answered against the tool table and the length in force at this moment,
   *  not at load (a guided M6 at the hold measures and applies a tool). A
   *  string when the file can no longer be resolved. Absent: stage as built. */
  restage?: (part: MachineProgram) => MachineProgram | string
  /** WO-2580: the parts that are only a stop-only section's zero-second dwell
   *  (an M0 right after `T# M6`). They run and hold like any part; the part a
   *  held program names is counted without them. */
  unlistedParts?: ReadonlySet<number>
}
let programPartsRun: ProgramPartsRun | null = null

/** WO-2580: the parts of a run before `index` that the operator counts. */
function countedPartsBefore(run: ProgramPartsRun, index: number): number {
  let unlisted = 0
  for (const part of run.unlistedParts ?? []) if (part < index) unlisted++
  return index - unlisted
}
/** One-shot attribution for a reset invoked through the operator Stop/Reset
 * control. Controller-originated reset state (including an E-STOP edge) does
 * not set it and therefore cannot be mislabeled as that control. */
let stopResetRequestedForProgramParts = false

// ---- WO-1663: a user Stop is a stop, not a failed cycle ----
//
// Board, 2026-09-17: Operator stopped his own 110,615-move file 337 moves in and
// the header read "The cycle failed. Resolve the error first. A toolpath
// program has no re-arm control", CYCLE START greyed, progress back to 1.
// Nothing had failed. A file loaded through the toolpath door has no program
// TEXT, so the text door's "Re-arm from start" is not on the screen; the one
// way back to the top is loading the same file again. So that is what an
// operator's own Stop now does, once the machine is back at Idle: the file is
// staged again from its first line - nothing moves, CYCLE START runs it - and
// the header and progress say where the operator stopped it until they do.

/** What the file door needs to stage the same file again. */
interface ToolpathProgramReload {
  controller: MachineController
  name: string
  text: string
  publishListing: boolean
  /** File line of a staged step id, for "stopped at line N". */
  lineOfStep: (stepId: number) => number | undefined
  /** WO-1640: the work offsets the file was read against when it was staged. */
  offsets: ReaderWorkOffsets
  /** WO-1791: the live work position used to resolve initial modal and G91
   *  coordinates. A first release from another position reads the file again. */
  position: GcodeReaderPoint
  /** WO-2047: the file's LienCAM context, so a re-read keeps its stock. */
  context: ProgramContextV1 | null
  /** WO-2437: see `GcodeTextLoadOptions.runThroughOffsetChanges`; a re-read keeps it. */
  runThroughOffsetChanges: boolean
  /** WO-2598: execution is a prelude + remainder; identity and Stop use text. */
  runFrom?: { text: string; numbering: FileNumbering }
}
let toolpathProgramReload: ToolpathProgramReload | null = null

/** The file the file door staged and still names as the loaded program, or
 *  null (a text-door program, another controller, another load). An MDI line
 *  staged over the file leaves it the loaded program - `fileUnderMdiLine`. */
function currentFileDoorProgram(): ToolpathProgramReload | null {
  const reload = toolpathProgramReload
  const s = store()
  if (!reload) return fileUnderMdiLine()
  if (!reload.publishListing || reload.controller !== controller) return null
  if (s.programText !== null || s.job.name !== reload.name) return null
  return reload
}

/**
 * WO-2141: AN MDI LINE DOES NOT UNLOAD THE FILE.
 *
 * Rehearsal 2026-09-28 step 12: mesh.nc loaded on the UCCNC bridge, an MDI
 * move to the mesh start, then Z surface - "Load a program to derive the
 * active cutting area." The bridge runs a typed motion line as a one-line
 * program through the file door (`stageMdiMotion`), and that load dropped the
 * door's record of the file. UCCNC keeps its loaded program through MDI; so
 * does this: the file the line was staged over is still the loaded program
 * for as long as the board holds that line (or a later one typed after it).
 * Any other load - a file, a text-door program, a posted setup - renames the
 * job or sets the door's own record, and this stops answering on its own.
 *
 * WO-2234: AND THE SCREEN AND CYCLE START KEEP IT TOO. Operator at the machine,
 * 2026-09-29: "why would an mdi move ever unload a program ... An MDI move
 * should not behave different than a jog move". With the operator's own MDI
 * (`keepsFile`) the line is staged without renaming the job, the listing, the
 * preview, the readiness or the operator's stop report - the loaded program
 * stays the loaded program on screen - and when the line ends (`ended`:
 * completed, stopped, failed, never started) the program is put back exactly
 * as it was before the first line (`before`), as if the move had been a jog
 * (`settleProgramAfterMdiLine`): a file that was armed on the board (a fresh
 * load, or WO-1663's re-stage after a Stop) is staged again from its first
 * line, never started; one that was not (completed, failed, or WO-1980's file
 * still waiting for its work offset) is not armed by this - only its screen
 * state comes back. A line a held program's own macro sends keeps the old
 * WO-2141 record only.
 */
let programUnderMdiLine: {
  controller: MachineController
  label: string
  /** The loaded program's name, which the job keeps. */
  name: string
  /** The file door's record of it; null for a file waiting for its work
   *  offsets (WO-1980), which is not on the board to begin with. */
  reload: ToolpathProgramReload | null
  keepsFile: boolean
  ended: boolean
  /** The file's load is under way (a bridge stages after its frame receipt). */
  restaging: boolean
  /** The screen state was put back (a program that was not armed). */
  restored: boolean
  /** The loaded program as it stood before the first MDI line over it. */
  before: { job: ReturnType<typeof store>['job']; readiness: ReturnType<typeof store>['programReadiness']; armed: boolean } | null
} | null = null

function fileUnderMdiLine(): ToolpathProgramReload | null {
  const under = programUnderMdiLine
  if (!under || under.reload === null) return null
  if (under.keepsFile) return mdiLineOverLoadedProgram(controller) ? under.reload : null
  const s = store()
  if (toolpathProgramReload !== null || under.reload.controller !== controller || s.programText !== null) return null
  if (mdiStagedLine !== under.label || s.job.name !== under.label) return null
  return under.reload
}

/** WO-2234: the operator's MDI line typed over the loaded program is what the
 *  board holds, and no other load has taken the screen since. */
function mdiLineOverLoadedProgram(ctrl: MachineController | null): boolean {
  const under = programUnderMdiLine
  if (!under || !under.keepsFile || ctrl === null || under.controller !== ctrl) return false
  const s = store()
  if (s.programText !== null || s.job.name !== under.name) return false
  return under.reload !== null
    ? toolpathProgramReload === null
    : programAwaitingOffsets?.controller === ctrl && programAwaitingOffsets.name === under.name
}

/** WO-2234: the MDI line over the loaded program has ended (or will never
 *  run); put the program back as soon as the board has settled. */
function endMdiLineOverFile(ctrl: MachineController | null): void {
  if (!mdiLineOverLoadedProgram(ctrl)) return
  programUnderMdiLine!.ended = true
  // Never inside the edge that ended it: the stop wrapper, a job event or the
  // MDI door's own load are still running.
  void Promise.resolve().then(() => {
    if (ctrl) settleProgramAfterMdiLine(ctrl)
  })
}

/**
 * WO-2234: put the loaded program back as it stood before the MDI line, once
 * the line has ended and the machine is at a settled Idle with nothing running
 * (the same moment WO-1663's Stop waits for). A file that was armed is staged
 * again from its first line through the file door - read against the offsets
 * and position now in force, so its listing, preview, mesh compensation and Z
 * surface are the file's - and never started. One that was not armed gets its
 * screen state back and nothing else.
 *
 * `release` is CYCLE START itself: the board still holds the ended line, so the
 * file is staged and the start follows the staging (as WO-1640's re-read
 * does) - CYCLE START never runs the line. Null when nothing was done now.
 */
function settleProgramAfterMdiLine(
  ctrl: MachineController,
  release?: () => boolean,
): boolean | null {
  const under = programUnderMdiLine
  if (!under || !under.keepsFile || !under.ended || under.controller !== ctrl) return null
  // Another load since the line owns the screen (including this file's own
  // re-stage, once it is on the board).
  if (!mdiLineOverLoadedProgram(ctrl)) {
    programUnderMdiLine = null
    return null
  }
  const settled = !under.restaging
    && ctrl.connectionPhase() === 'connected'
    && !ctrl.hasActiveJob()
    && !ctrl.resetInProgress()
    && ctrl.machineState() === 'idle'
    && !estopNeedsReset()
  const reload = under.reload
  if (!under.before?.armed || reload === null) {
    if (settled && !under.restored && under.before) {
      under.restored = true
      useMachineControl.setState({ job: under.before.job, programReadiness: under.before.readiness })
    }
    // A file still waiting for its offsets answers CYCLE START itself.
    if (!release || reload === null) return null
  }
  if (!settled) {
    if (!release) return null
    // CYCLE START before the board has settled after the line: the board still
    // holds the line, and starting it would run the line, not the file.
    store().pushConsole(
      'tx',
      `Cycle Start: "${under.name}" goes back on the board once the machine is at Idle after the `
        + 'MDI line - press CYCLE START then. Nothing moved.',
      'error',
    )
    return false
  }
  under.restaging = true
  // The operator's stop report (WO-1663) describes this file; it stays.
  rearmingAfterOperatorStop = true
  let outcome: { ok: boolean }
  try {
    outcome = loadGcodeTextToolpathProgram(reload!.name, reload!.text, {
      publishListing: reload!.publishListing,
      context: reload!.context,
      runThroughOffsetChanges: reload!.runThroughOffsetChanges,
      loadLine: () => {
        if (programUnderMdiLine === under) programUnderMdiLine = null
        // WO-2237: a kept stop's CYCLE START goes back to the pause point.
        const kept = liveKeptStop(ctrl)
        if (kept !== null && kept.resumed === null) {
          return `"${reload!.name}" is loaded again after the MDI line. ${keptStopCycleStartSentence(kept)}`
        }
        return `"${reload!.name}" is staged again from its first line after the MDI line. `
          + 'CYCLE START runs it from the start.'
      },
      ...(release ? { fileReread: true, onStaged: release } : {}),
    })
  } finally {
    rearmingAfterOperatorStop = false
  }
  // A refused load said why on the console; nothing is pending any more.
  if (!outcome.ok && programUnderMdiLine === under) programUnderMdiLine = null
  return outcome.ok
}

/**
 * WO-2104: THE LOADED PROGRAM'S G-CODE, WHICHEVER DOOR TOOK IT.
 *
 * Rehearsal 2026-09-27: on the UCCNC bridge the Probing screen's Z surface
 * said "Load a program to derive the active cutting area" with mesh.nc loaded.
 * The bridge has no text route, so the file went through the file door, which
 * stores no program text - and the mesh planned from the store's text alone.
 * The file door keeps the file it staged; this answers with it.
 */
/** WO-2651: whether the loaded program (through the file door) runs through its
 *  work-offset changes - an edit applied to it keeps that choice, every time. */
export function loadedProgramRunsThroughOffsetChanges(): boolean {
  return currentFileDoorProgram()?.runThroughOffsetChanges === true
}

export function loadedProgramText(): string | null {
  return store().programText ?? currentFileDoorProgram()?.text ?? null
}

/** The simulator's start-time travel refusal (simulatedController.ts). */
const TRAVEL_REFUSAL_PREFIX = "This program would move outside the machine's declared travel"

/**
 * Machine session 2026-10-08 (Full Suite Setup 4 in G57, G57 never set): the travel
 * refusal said only "No re-home needed", which hid why. Name the work offset
 * the program runs in when its zero is unset, and the control that fixes it.
 */
function travelRefusalNextStep(): string {
  const text = loadedProgramText() ?? ''
  const named = [...new Set(text.toUpperCase().match(/\bG5[4-9](?:\.\d)?(?![\d.])/g) ?? [])]
  const frames = named.length > 0 ? named : [store().activeWcs ?? 'G54']
  const offsets = store().offsets
  const unset = frames.filter((wcs) => (offsets[wcs] ?? [0, 0, 0]).every((v) => v === 0))
  if (unset.length > 0) {
    const list = unset.join(', ')
    return ` The program runs in ${list}, whose zero is not set (0, 0, 0). Set the ${list} zero on the Offsets tab, then press CYCLE START.`
  }
  return ' Check the program\'s work zero on the Offsets tab, then press CYCLE START.'
}

/** WO-2104: stage the loaded program again through the door that took it,
 *  with whatever surface mesh is armed for it compiled in (both doors do that
 *  themselves). False when no program is loaded. */
export function restageLoadedProgram(): boolean {
  const s = store()
  if (s.programText !== null) {
    loadMachineProgram(s.job.name ?? 'program', s.programText)
    return true
  }
  const file = currentFileDoorProgram()
  if (!file) return false
  return loadGcodeTextToolpathProgram(file.name, file.text, {
    publishListing: true,
    context: file.context,
    runThroughOffsetChanges: file.runThroughOffsetChanges,
  }).ok
}

/**
 * WO-2104: THE SURFACE MESH ON THE FILE DOOR - the text door's rule
 * (`loadTextProgram`), for a controller that runs staged moves. WO-2283: the
 * mesh belongs to its WORK SYSTEM, not to a file: any file whose moves run in
 * it is read compensated, every time the door reads it (a load, the
 * operator's Stop, a Cycle Start after an offset edit, an alarm's re-stage),
 * and a file run in another work system reads plain. Another file no longer
 * ends the mesh.
 */
function meshCompensatedFileText(text: string): {
  text: string
  sourceLineOf: ((line: number) => number | undefined) | null
  compensatedBlocks: number | null
  /** The compiler's reason when a file that runs in the mesh's work system
   *  cannot be compensated: the text door's "Mesh compensation refused". */
  refusal: string | null
} {
  const plain = { text, sourceLineOf: null, compensatedBlocks: null, refusal: null }
  // WO-2267: the text door's rule - a re-zero ends the mesh, the file reads plain.
  endSurfaceMeshIfReZeroed(false)
  meshStagedStartWcs = store().activeWcs
  const compiled = compileUnderAppliedMesh(text)
  if (!compiled) return plain
  // Fail closed, as the text door does: a file run where the mesh applies is
  // never quietly staged uncorrected, and the mesh stays with its work system.
  if (!compiled.ok) return { ...plain, refusal: compiled.reason }
  return {
    text: compiled.lines.map((line) => line.text).join('\n'),
    sourceLineOf: (line) => compiled.lines[line - 1]?.sourceLine,
    compensatedBlocks: compiled.generatedMotionLines,
    refusal: null,
  }
}

/** WO-2283: the work system the loaded program was last staged to start in -
 *  what its compensated stream was compiled for. */
let meshStagedStartWcs: string | null = null

/** WO-2283: what a program text runs as under the applied mesh when it starts
 *  in `startWcs`: the compensated stream, the compiler's refusal, or null - it
 *  runs as written (no mesh is applied, or none of its moves runs in the
 *  mesh's work system). */
function compileUnderAppliedMesh(
  text: string,
  startWcs: string | null = store().activeWcs,
): SurfaceMeshCompileResult | null {
  const mesh = store().surfaceMesh
  if (!mesh?.active) return null
  const compiled = compileSurfaceCompensatedProgram(text, mesh, { startWcs })
  return compiled.ok && compiled.generatedMotionLines === 0 ? null : compiled
}

/** WO-2283: the loaded text program runs compensated (Run from line and Step
 *  Back keep their mesh refusals for it; a program run plain beside an
 *  applied mesh in another work system is not compensated and gets neither). */
function loadedTextRunsCompensated(programText: string): boolean {
  return compileUnderAppliedMesh(programText, meshStagedStartWcs) !== null
}

/**
 * WO-2047: THE LIENCAM CONTEXT OF A STAGED PROGRAM.
 *
 * Operator ruling 2026-09-26: Setup 1 posted and loaded on his LienCNC, and Control read
 * "Intended stock - NONE" with no stock box. His controller runs staged
 * programs, so every load - the posted file, the same file reopened, the setup
 * itself - goes through the program door, and that door stores NO program
 * text (a staged program has none; `programText` null is what closes every
 * text-only path). The store binds a context only together with its text
 * (`setProgram`'s contract), so the door passed null and the envelope the post
 * wrote after M30 was read, verified and thrown away.
 *
 * The store contract stays as it is. The door keeps the verified context here,
 * with the LienCAM-posted text it was verified against, tied to the exact
 * listing object it published: any later load publishes another listing (or
 * none), and the record stops answering on its own. Advisory, like the text
 * route's context: it never changes a staged move.
 */
interface StagedProgramContext {
  listing: StagedProgramView
  context: ProgramContextV1
  /** The posted text the context's motion digest and spans were verified on. */
  text: string
  /** File line of a staged step id (the program door's cursor is a step id). */
  lineOfStep: (stepId: number) => number | undefined
}
let stagedProgramContextValue: StagedProgramContext | null = null

/** The context and posted text of the program currently staged through the
 *  program door, or null (nothing staged, a file with no LienCAM context, or
 *  a text-door program - whose context is the store's own). */
export function stagedProgramContext(): Omit<StagedProgramContext, 'listing'> | null {
  const bound = stagedProgramContextValue
  const s = store()
  if (!bound || s.programText !== null || s.stagedProgram !== bound.listing) return null
  return { context: bound.context, text: bound.text, lineOfStep: bound.lineOfStep }
}

/** The loaded program's context whichever door took it. */
function loadedProgramContext(): ProgramContextV1 | null {
  return store().programContext ?? stagedProgramContext()?.context ?? null
}

/** A context handed to the program door, checked against the text it came
 *  with before anything is staged. It is advisory: a context that does not
 *  match its program is dropped with one console line, and the program still
 *  loads (rule 11) - it just shows no intended stock. */
function verifiedStagedContext(
  name: string,
  text: string,
  context: ProgramContextV1 | null | undefined,
): ProgramContextV1 | null {
  if (!context) return null
  try {
    assertProgramContextMatchesProgram(context, text)
    return freezeProgramContext(context)
  } catch (err) {
    console.error('[program-context] staged program context refused:', err)
    store().pushConsole(
      'rx',
      `"${name}": its LienCAM setup information does not match the program, so it is loaded without it.`,
      'warn',
    )
    return null
  }
}

/** WO-2047: a setup's context as Control's text route binds it - posted with
 *  the machine's declared dialect as one combined program, the context built
 *  from that same post - for the program door's setup loads. Null when the
 *  setup cannot be posted: the program still loads, with no intended stock. */
function postedSetupContext(
  project: Project,
  setup: Setup,
  dialect: PostConfig,
  posted: ReturnType<typeof postProject>,
): { context: ProgramContextV1; text: string } | null {
  if (!posted.ok || !posted.combined?.operationSpans) return null
  try {
    const context = buildProgramContext(project, setup, dialect, posted.combined.gcode, posted.combined.operationSpans)
    return { context, text: posted.combined.gcode }
  } catch (err) {
    console.error('[program-context] setup context could not be built:', err)
    return null
  }
}

/** What the operator is shown after their own Stop, until CYCLE START. */
interface OperatorStopState {
  boundary?: string
  name: string
  /** Moves the program had finished when Stop was pressed. */
  ackedMoves: number
  totalMoves: number
  /** WO-2256: the same count as the controller counted the staged program -
   *  `ackedMoves` is the file's (a resumed run's remainder counts from 0). */
  stagedAckedMoves?: number
  /** File line of the move that was running, when the file says. */
  line: number | null
  /** True once the file is staged again from its first line. */
  rearmed: boolean
}
let operatorStopPending: (OperatorStopState & { controller: MachineController }) | null = null
let operatorStopValue: (OperatorStopState & { controller: MachineController }) | null = null
const operatorStopListeners = new Set<() => void>()
/** The session's own stops (spindle fault, Step Back, tool change park) are
 *  not the operator's Stop button, and never read as one. */
let sessionStopInProgress = false
let rearmingAfterOperatorStop = false

function setOperatorStop(next: (OperatorStopState & { controller: MachineController }) | null): void {
  operatorStopValue = next
  for (const listener of operatorStopListeners) listener()
}

/** The operator's last Stop of this program, or null. Stable between changes
 *  so it can back a `useSyncExternalStore`. */
export function operatorStopState(): OperatorStopState | null {
  const stop = operatorStopValue
  if (!stop || stop.controller !== controller) return null
  return stop
}

export function subscribeOperatorStop(listener: () => void): () => void {
  operatorStopListeners.add(listener)
  return () => operatorStopListeners.delete(listener)
}

function clearOperatorStop(): void {
  operatorStopPending = null
  if (operatorStopValue !== null) setOperatorStop(null)
}

/** The operator's sentence for a stop: where it stopped, and what CYCLE START
 *  does next. Plain words, no "failed", no "resolve". */
export function describeOperatorStop(stop: OperatorStopState): string {
  if (stop.boundary !== undefined) return `Stopped at line ${stop.line} (${stop.boundary}). Restart the program or run from a line.`
  const where = stop.line !== null
    ? `at line ${stop.line} (move ${stop.ackedMoves} of ${stop.totalMoves})`
    : `at move ${stop.ackedMoves} of ${stop.totalMoves}`
  return stop.rearmed
    ? `Stopped by the operator ${where}. CYCLE START runs the program again from the start.`
    : `Stopped by the operator ${where}.`
}

/** Called by the Stop wrapper BEFORE the controller is told: the controller
 *  zeroes its cursors on stop, so the count the operator saw is read here. */
function noteOperatorStop(target: MachineController): void {
  operatorStopPending = null
  if (sessionStopInProgress) return
  const reload = toolpathProgramReload
  const s = store()
  if (!reload || reload.controller !== target) return
  if (s.programText !== null || s.job.name !== reload.name) return
  const running = target.hasActiveJob() || (programPartsRun?.controller === target && programPartsRun.started)
  if (!running) return
  operatorStopPending = {
    controller: target,
    name: reload.name,
    ackedMoves: s.job.ackedLines,
    totalMoves: s.job.totalLines,
    stagedAckedMoves: stagedJobCounts().ackedLines,
    line: reload.lineOfStep(s.job.ackedSourceLine) ?? null,
    rearmed: false,
  }
}

/** WO-2240: the operator's Stop ends a paused program on a board that runs
 *  staged moves (the AXBB-E bridge) - read BEFORE the stop, which clears the
 *  job and lets the board read Idle. That board keeps its feed hold through
 *  StopJob (Machine.cs StopJob: StopWithDeccel, no release): SimUC100 stays
 *  held, and the real board reads Idle while it drops every move it is given
 *  (measured 2026-08-24). UCCNC's Stop and LinuxCNC's abort both end a pause.
 *  The tool-change flow answers for its own hold (WO-2240 HARD LIMIT), and an
 *  E-STOP is not a Stop. */
function stopEndsBoardHold(target: MachineController): boolean {
  if (target.capabilities.gcodeText === true || estopNeedsReset()) return false
  if (!target.hasActiveJob()) return false
  if (target.machineState() !== 'hold' && store().job.phase !== 'paused') return false
  return toolChangeHold === null && store().toolChange === null && !programGuidedToolChangeBlocksCycleStart(target)
}

/** WO-2240: after that Stop, the kept stop's release (takeKeptStop): the
 *  bridge's Stop/Reset - Stop() empties the queue, THEN SetFeedHold(false), so
 *  nothing buffered can run. At rest (the pause has settled) it goes in the
 *  same breath as the stop, so a jog or MDI pressed next reaches the board
 *  after it. A Stop pressed while the Feed Hold is still decelerating keeps
 *  the controlled stop it always had (StopWithDeccel; Reset's Stop() is
 *  abrupt): the release goes on the first status at rest, from the store's
 *  own update, before the panels can re-enable. A program-parts run it ends is
 *  ended by Stop/Reset, and says so. */
function releaseBoardHoldAtRest(target: MachineController): void {
  // The release writes the store itself; once is once.
  let done = false
  const release = (): boolean => {
    if (done) return true
    if (controller !== target || target.connectionPhase() !== 'connected' || estopNeedsReset()) return (done = true)
    if (MOVING_STATES.has(target.machineState())) return false
    done = true
    stopResetRequestedForProgramParts = programPartsRun?.controller === target
    void target.resetToIdle()
    return true
  }
  if (release()) return
  const off = useMachineControl.subscribe(() => {
    if (!release()) return
    off()
    clearTimeout(timer)
  })
  const timer = setTimeout(off, 8000)
}

function stopJobForSession(target: MachineController): void {
  sessionStopInProgress = true
  try {
    target.stopJob()
  } finally {
    sessionStopInProgress = false
  }
}

/** The session's own Reset (Step Back, a tool change's controlled stop) is not
 *  the operator's Stop/Reset either (WO-2041). */
function resetForSession(target: MachineController): void {
  sessionStopInProgress = true
  try {
    target.reset()
  } finally {
    sessionStopInProgress = false
  }
}

// ---- WO-2041: a Stop during a crossing is the operator's Stop ----
//
// Board, 2026-09-26 (session finding F11): Stop/Reset pressed during a Measure
// crossing halted the machine in ~0.16 s and Z held at 128.1 - and the console
// then read "THE MOVE WAS TRUNCATED AND IT REPORTED SUCCESS ... The usual cause
// is a SOFT LIMIT". The bridge's WO-934 shortfall check compares what a move
// asked for with what it did once motion settles; it cannot know WHY the move
// ended early. The session can: it told the board to stop. So a shortfall (or
// WO-933's never-ran report) about the very move that was in flight when the
// operator pressed Stop/Reset is said as the operator's stop. Any other report
// reaches the console word for word, as before.
//
// Which move a report is about is read from the report itself (architect
// re-scope, 2026-09-26): the bridge arms its one move watch on Jog, JogToWorkXY
// and JogToMachineZ (Machine.cs WatchMove) with the move's own description -
// "a jog of -5 mm on Z at 600 mm/min", "an absolute XY move to X730 Y50",
// "an absolute Z move to Z128.1" - and both reports carry it.

/** The bridge reports a shortfall once the counter has sat still for its
 *  500 ms settle; a stopped move decelerates in well under a second. A report
 *  later than this is about a later move. */
const OPERATOR_STOP_REPORT_WINDOW_MS = 3000
/** Group 1 is the watched move's description, as the bridge wrote it. WO-2533:
 *  a bridge that knows the move was stopped says THE MOVE STOPPED SHORT and
 *  names the stop; after the operator's own Stop/Reset that is still his. */
const BRIDGE_STOPPED_MOVE_REPORT =
  /^\[bridge\] (?:THE MOVE WAS TRUNCATED AND IT REPORTED SUCCESS|THE MOVE STOPPED SHORT|THE MACHINE ACCEPTED A MOVE AND DID NOT MAKE IT)\. (.+?) (?:asked for|was accepted by the controller) /
export const OPERATOR_STOP_HALTED_NOTICE =
  'Stopped by the operator: the machine halted and is holding where it stopped.'
/** A Stop names only the move it stopped: once the machine has come to rest
 *  after it, the next motion is a new move and its report is its own. */
const MOVING_STATES: ReadonlySet<MachineState> = new Set<MachineState>(['run', 'jog', 'home'])

/** A watched move the session sent, named as the bridge will name it. `moved`
 *  and `finished` follow the status frames after it left: a move seen moving
 *  and then at rest has finished, and a Stop pressed after that did not halt
 *  it (WO-2041 audit 5). A move not yet seen moving is still in flight. */
interface SentWatchedMove {
  readonly controller: MachineController
  readonly move: string
  moved: boolean
  finished: boolean
}
/** Newest last. A report is judged within seconds of its Stop, so a short
 *  memory is enough; an entry pushed out of it can no longer be named. */
const SENT_WATCHED_MOVES_KEPT = 32
let sentWatchedMoves: SentWatchedMove[] = []
let lastOperatorMotionStop: {
  controller: MachineController
  atMs: number
  atRest: boolean
  /** The move in flight at the press: the last watched move sent before it. */
  inFlight: SentWatchedMove | null
} | null = null

/** A number as both sides write it: the bridge prints a C# double, the app
 *  sends a JS number, so they are compared as numbers, not as text. */
function moveNumber(value: number | string): string | null {
  const n = typeof value === 'number' ? value : Number(value)
  return Number.isFinite(n) ? n.toFixed(6) : null
}

function jogMove(axis: string, deltaMm: number | string, feedMmMin: number | string): string | null {
  const delta = moveNumber(deltaMm)
  const feed = moveNumber(feedMmMin)
  // Identity keys for matching a report to its move - never shown to anyone,
  // so they are not position sentences (WO-1667's formatter rule).
  return delta === null || feed === null ? null : `jog|${axis.toUpperCase()}|${delta}|${feed}`
}

function workXYMove(x: number | string, y: number | string): string | null {
  const wx = moveNumber(x)
  const wy = moveNumber(y)
  return wx === null || wy === null ? null : `xy|${wx}|${wy}`
}

function machineZMove(z: number | string): string | null {
  const mz = moveNumber(z)
  return mz === null ? null : `z|${mz}`
}

/** The move a bridge report is about, or null when its words are not one of
 *  the three the bridge arms its watch with. */
function reportedMove(description: string): string | null {
  let m = /^a jog of (\S+) mm on ([A-Za-z]) at (\S+) mm\/min$/.exec(description)
  if (m) return jogMove(m[2], m[1], m[3])
  m = /^an absolute XY move to X(\S+) Y(\S+)$/.exec(description)
  if (m) return workXYMove(m[1], m[2])
  m = /^an absolute Z move to Z(\S+)$/.exec(description)
  if (m) return machineZMove(m[1])
  return null
}

function lastSentWatchedMove(target: MachineController, move?: string): SentWatchedMove | null {
  for (let i = sentWatchedMoves.length - 1; i >= 0; i--) {
    const sent = sentWatchedMoves[i]
    if (sent.controller === target && (move === undefined || sent.move === move)) return sent
  }
  return null
}

/** Remember every watched move as it leaves, so a Stop can say which move it
 *  stopped. A move the controller refuses is not in flight: a synchronous
 *  false is never kept, and a promise that resolves anything but true, or
 *  rejects, is forgotten. */
function recordWatchedMoves(next: MachineController): void {
  const record = (move: string | null, sent: boolean | Promise<boolean> | null) => {
    if (move === null || sent === false || sent === null) return
    const entry: SentWatchedMove = { controller: next, move, moved: false, finished: false }
    sentWatchedMoves.push(entry)
    if (sentWatchedMoves.length > SENT_WATCHED_MOVES_KEPT) sentWatchedMoves.shift()
    if (sent === true) return
    const forget = () => { sentWatchedMoves = sentWatchedMoves.filter((kept) => kept !== entry) }
    sent.then((ok) => { if (ok !== true) forget() }, forget)
  }
  const jog = next.jog.bind(next)
  next.jog = (axis, deltaMm, feedMmMin) => {
    const sent = jog(axis, deltaMm, feedMmMin)
    record(jogMove(axis, deltaMm, feedMmMin), sent)
    return sent
  }
  const jogToWorkXY = next.jogToWorkXY.bind(next)
  next.jogToWorkXY = (x, y, feedMmMin) => {
    const sent = jogToWorkXY(x, y, feedMmMin)
    if (sent && activeProbeCycle?.controller === next) activeProbeCycle.resumeMove = () => next.jogToWorkXY(x, y, feedMmMin)
    record(workXYMove(x, y), sent)
    return sent
  }
  const jogToMachineZ = next.jogToMachineZ.bind(next)
  next.jogToMachineZ = (z, feedMmMin) => {
    const sent = jogToMachineZ(z, feedMmMin)
    if (sent && activeProbeCycle?.controller === next) activeProbeCycle.resumeMove = () => next.jogToMachineZ(z, feedMmMin)
    record(machineZMove(z), sent)
    return sent
  }
  if (next.jogToWorkXYAwait) {
    const jogToWorkXYAwait = next.jogToWorkXYAwait.bind(next)
    next.jogToWorkXYAwait = (x, y, feedMmMin) => {
      const sent = jogToWorkXYAwait(x, y, feedMmMin)
      record(workXYMove(x, y), sent)
      return sent
    }
  }
  if (next.jogToMachineZAwait) {
    const jogToMachineZAwait = next.jogToMachineZAwait.bind(next)
    next.jogToMachineZAwait = (z, feedMmMin) => {
      const sent = jogToMachineZAwait(z, feedMmMin)
      record(machineZMove(z), sent)
      return sent
    }
  }
}

function noteOperatorMotionStop(target: MachineController): void {
  if (sessionStopInProgress) return
  const last = lastSentWatchedMove(target)
  lastOperatorMotionStop = {
    controller: target,
    atMs: sessionElapsedNowMs(),
    atRest: !MOVING_STATES.has(target.machineState()),
    // A move that already moved and came to rest on its own is not what this
    // Stop halted; its own report keeps its own diagnosis.
    inFlight: last !== null && !last.finished ? last : null,
  }
}

/** Status after the operator's Stop: a stopped move still decelerating keeps
 *  the stop; motion that starts after the machine was at rest is a new move,
 *  and the stop no longer speaks for any report. The backstop for motion that
 *  did not leave through this session. */
function followOperatorMotionStop(target: MachineController | null, state: MachineState): void {
  const latest = target === null ? null : lastSentWatchedMove(target)
  if (latest !== null && !latest.finished) {
    if (MOVING_STATES.has(state)) latest.moved = true
    else if (latest.moved) latest.finished = true
  }
  const stop = lastOperatorMotionStop
  if (stop === null || stop.controller !== target) return
  if (!MOVING_STATES.has(state)) stop.atRest = true
  else if (stop.atRest) lastOperatorMotionStop = null
}

/** The operator's sentence for a bridge move report that their own Stop/Reset
 *  caused, or null when the report stands as the bridge wrote it. It is the
 *  Stop's only when the report names the move that was in flight at the press
 *  and that same move has not been asked for again since - then the report
 *  could be the later one's. One stop halts one move, so the stop is spent on
 *  the first move report after it. */
function operatorStopForBridgeReport(target: MachineController | null, text: string): string | null {
  const stop = lastOperatorMotionStop
  if (stop === null || stop.controller !== target) return null
  const report = BRIDGE_STOPPED_MOVE_REPORT.exec(text)
  if (report === null) return null
  lastOperatorMotionStop = null
  if (sessionElapsedNowMs() - stop.atMs > OPERATOR_STOP_REPORT_WINDOW_MS) return null
  const move = reportedMove(report[1])
  if (move === null || stop.inFlight === null || stop.inFlight.move !== move) return null
  if (lastSentWatchedMove(stop.controller, move) !== stop.inFlight) return null
  return OPERATOR_STOP_HALTED_NOTICE
}

/** The operator's Stop has landed as a 'stopped' edge: publish it, and stage
 *  the same file again from its first line once the machine is at Idle. */
function takeOperatorStop(target: MachineController): void {
  const pending = operatorStopPending
  operatorStopPending = null
  if (!pending || pending.controller !== target) return
  const stop = { ...pending }
  setOperatorStop(stop)
  const reload = toolpathProgramReload
  if (!reload || reload.controller !== target) return
  void waitForMachine(
    () => target.connectionPhase() === 'connected'
      && !target.hasActiveJob()
      && !target.resetInProgress()
      && target.machineState() === 'idle',
    8000,
  ).then((settled) => {
    if (operatorStopValue !== stop || controller !== target || toolpathProgramReload !== reload) return
    // Anything else in between - an alarm, the E-STOP, another load, a
    // disconnect - owns the screen; the stop stays reported and nothing is
    // staged behind it.
    if (!settled || estopNeedsReset()) return
    const s = store()
    if (s.programText !== null || s.job.name !== stop.name) return
    rearmingAfterOperatorStop = true
    try {
      loadGcodeTextToolpathProgram(reload.name, reload.text, {
        publishListing: reload.publishListing,
        context: reload.context,
        runThroughOffsetChanges: reload.runThroughOffsetChanges,
        loadLine: () => {
          if (operatorStopValue === stop) setOperatorStop({ ...stop, rearmed: true })
          return `"${stop.name}" is staged again from its first line. CYCLE START runs it from the start.`
        },
      })
    } finally {
      rearmingAfterOperatorStop = false
    }
  })
}

/** A clamp pause opened by a program's macro (WO-1652: its `clampPause()`) at
 * an already-proven program boundary. Its
 * Continue action releases that exact next part; it must not use the text
 * run-from-line path because the AXBB-E wire deliberately accepts no text. */
let programClampPause: {
  run: ProgramPartsRun
  boundaryIndex: number
  /** Where it parked (WO-2437 fix round): CYCLE START or Continue goes back
   *  here first when the operator moved the machine at the stop. */
  park?: { park: ParkPosition; safeZMachine: number | null }
} | null = null

/** An M6-owned guided card releases this exact geometry-program boundary after
 * its probe and offset receipt. It must never fall through the text
 * run-from-line path: the AXBB-E deliberately accepts geometry, not text. */
let programGuidedToolChange: { run: ProgramPartsRun; boundaryIndex: number } | null = null

/** WO-1996, readiness walk 2026-09-25: a guided tool measure that misses keeps
 * the flow at its M6 - the card offers Retry measure and, once this flow has
 * measured the tool, Continue from the M6. A missed G38.2 alarms the controller
 * (GRBL ALARM:5, and the simulator copies it); that alarm is the measure's own
 * answer, so while it is the only alarm it must not retire the held geometry
 * program the M6 belongs to. `probing` covers the window before the probe
 * reports; `missAlarm` the wait after it. Any later alarm, an E-STOP trip or a
 * lost position is a real fault and ends the program exactly as before. */
let guidedMeasure: { probing: boolean; missAlarm: boolean; measured: boolean } | null = null
/** The initial park supplies safe Z before the measured change finishes. */
let guidedToolChangePark: { park: ParkPosition; safeZMachine: number | null | undefined } | null = null

/** The held program boundary whose alarm belongs to the guided measure. */
function guidedMeasureOwnsAlarm(run: ProgramPartsRun): boolean {
  return guidedMeasure !== null
    && (guidedMeasure.probing || guidedMeasure.missAlarm)
    && programGuidedToolChange?.run === run
    && run.heldBetweenParts
    && !estopNeedsReset()
    && store().alarm?.positionLost !== true
}

/** Whether the guided tool change on screen missed its measure (Retry is live)
 * and whether a later retry measured the tool (Continue from the M6 is live). */
export function guidedToolMeasureState(): { missed: boolean; measured: boolean } | null {
  return guidedMeasure === null ? null : { missed: !guidedMeasure.measured, measured: guidedMeasure.measured }
}

function clearProgramClampPauseForRun(run: ProgramPartsRun): void {
  if (programClampPause?.run === run) programClampPause = null
}

/** WO-1652: the held program boundary whose M-code's macro is running now.
 * While it runs, CYCLE START does not release the boundary (it continues the
 * macro at a `hold()` instead), the macro's own lines pass the MDI lockout,
 * and its `clampPause()` opens the clamp pause on this boundary. */
let programBoundaryMacro: {
  run: ProgramPartsRun
  boundary: ProgramSetupBoundary
  boundaryIndex: number
  /** A macro bound to M6, run before the program's own tool change. */
  m6Prelude: boolean
  /** Its `toolChange()` reached the tool-change hold (the plain one, on a
   *  machine with no tool-change park): the "has finished" row is not said. */
  toolChangeHeld: boolean
  /** WO-1652 tightening: the tool the reader counted for this macro (its body
   *  calls `toolChange()`). When the macro ends without having entered the
   *  tool-change hold itself, that hold follows for this tool, as it follows
   *  the M6 prelude. Absent on a macro the reader did not mark. */
  markedToolChange?: number
} | null = null

/** True only around one send of the boundary macro's own line. */
let programBoundaryMacroSending = false

/** The boundary macro, while its boundary is still the one held. */
function currentProgramBoundaryMacro(): NonNullable<typeof programBoundaryMacro> | null {
  const pending = programBoundaryMacro
  if (
    pending === null
    || pending.run !== programPartsRun
    || !pending.run.heldBetweenParts
    || pending.run.announcedBoundary !== pending.boundaryIndex
  ) return null
  return pending
}

function programBoundaryMacroBlocksCycleStart(ctrl: MachineController): boolean {
  const pending = currentProgramBoundaryMacro()
  return pending !== null && pending.run.controller === ctrl && activeMacroRun() !== null
}

/** The clamp card owns release of its held boundary: CYCLE START never
 * reaches either multipart resume door past it. WO-2437 fix round: once it has
 * parked, CYCLE START is the card's Continue (`continueClampPauseByCycleStart`). */
function programClampPauseBlocksCycleStart(ctrl: MachineController): boolean {
  return programClampPause?.run === programPartsRun
    && programClampPause.run.controller === ctrl
}

function programGuidedToolChangeBlocksCycleStart(ctrl: MachineController): boolean {
  return programGuidedToolChange?.run === programPartsRun
    && programGuidedToolChange.run.controller === ctrl
}

/** WO-2031: who owns the held program's release, as `cycleResume` and
 * `stepJob` decide it below - the same checks in the same order, so the
 * transport header and CYCLE START show the door the session opens:
 * - 'clamp-card': the clamp card's Continue releases it, and once it has
 *   parked CYCLE START and the step do the same (WO-2437 fix round).
 * - 'boundary-macro': the step is refused; CYCLE START continues the macro
 *   only while it waits at hold() (`continueHeldMacro`).
 * - 'tool-change-card': both refused; the guided card's Continue releases it.
 * - 'probe-cycle' (WO-2103): a Feed Hold inside a running probe routine;
 *   CYCLE START releases that hold and the routine carries on.
 * - 'controller-tool-change' (WO-2239): the controller waits at an M6 the
 *   operator typed in a kept stop (LinuxCNC's own tool change); CYCLE START
 *   answers it, as it answers a program's (WO-2100).
 * - 'tool-change-park' (WO-2259): a Feed Hold on a guided flow's park move;
 *   CYCLE START releases that hold and the park carries on.
 * A guided change typed in a kept stop is 'tool-change-card' too, and so is
 * one typed with no program running while a program is loaded (WO-2521).
 * 'typed-tool-change' (WO-2533): the same card, typed with no program loaded -
 * the card's Continue finishes the typed change; CYCLE START is dark.
 * Null when none of them owns the hold. */
export type ProgramHoldCycleStartDecision =
  | { owner: 'clamp-card' }
  | { owner: 'boundary-macro'; macro: string; macroWaiting: boolean }
  | { owner: 'tool-change-card' }
  | { owner: 'probe-cycle'; routine: string }
  | { owner: 'controller-tool-change'; tool: number; canAnswer: boolean }
  | { owner: 'tool-change-park' }
  | { owner: 'typed-tool-change' }

export function programHoldCycleStartDecision(): ProgramHoldCycleStartDecision | null {
  const ctrl = controller
  if (ctrl === null) return null
  const waiting = keptStopControllerToolChange(ctrl)
  if (waiting !== null) return { owner: 'controller-tool-change', tool: waiting.tool, canAnswer: waiting.canAnswer }
  if (guidedParkPausedByOperator(ctrl)) return { owner: 'tool-change-park' }
  if (keptStopGuidedChangeOpen(ctrl)) return { owner: 'tool-change-card' }
  // WO-2521: a typed change parked over a loaded program - its card goes first.
  // WO-2533: over only the MDI line's own finished job, its words name the typed change.
  if (mdiGuidedChangeOpen(ctrl) && store().job.phase !== 'empty') {
    return programLoadedUnderTypedChange(ctrl) ? { owner: 'tool-change-card' } : { owner: 'typed-tool-change' }
  }
  if (probeCycleHeldByOperator(ctrl)) return { owner: 'probe-cycle', routine: activeProbeCycle?.routine ?? 'The probe routine' }
  if (programClampPauseBlocksCycleStart(ctrl)) return { owner: 'clamp-card' }
  if (programBoundaryMacroBlocksCycleStart(ctrl)) {
    const macro = activeMacroRun()!
    return { owner: 'boundary-macro', macro: macro.name, macroWaiting: macro.phase === 'held' }
  }
  if (programGuidedToolChangeBlocksCycleStart(ctrl)) return { owner: 'tool-change-card' }
  return null
}

/** How far below a declared retract height the machine may report and still be
 *  called clear. A machine reports Z to a few thousandths; a stricter number
 *  would refuse a retract that actually happened. */
const SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM = 0.05

/**
 * WO-1330: THE PROGRAM IS PAUSED AT A TOOL CHANGE, AND THAT HOLD PERMITS TWO
 * THINGS A PAUSED PROGRAM OTHERWISE DOES NOT - jog, and the Z work zero for
 * the tool being fitted.
 *
 * It is a SESSION fact and not a store field for the same reason the
 * offset-write latch and the soft-limit latch are: the run it belongs to lives
 * here, and the panels that need it already read session facts through
 * `useSyncExternalStore`. Exactly one is ever live, because exactly one program
 * runs.
 */
interface ToolChangeHold {
  /** The setup that has just finished. */
  finishedName: string
  /** The setup the program continues into. */
  nextName: string
  /** The frame the incoming setup runs in - the one whose Z zero is being set. */
  wcs: WcsId
  /** The tool coming out, in plain words. */
  leaving: string
  /** The tool to fit, in plain words. */
  fit: string
}
let toolChangeHold: ToolChangeHold | null = null
const toolChangeHoldListeners = new Set<() => void>()

/** The tool-change hold the program is presently sitting at, or null. */
export function activeToolChangeHold(): ToolChangeHold | null {
  return toolChangeHold
}

/** Panels ask this one question: may jog and the new tool's Z zero be used
 *  right now even though a program is loaded and paused? The tool-change hold,
 *  and (WO-2437 fix round) a program's clamp pause once it has parked: the
 *  board is idle between parts there, as at the tool change, and the operator
 *  screwing down the part may need to move the spindle out of the way. */
export function toolChangeHoldActive(): boolean {
  return toolChangeHold !== null || programClampPauseLendsJog()
}

/** A program's clamp pause, parked and waiting for the operator (its card at
 *  'awaiting-swap'), on the run and controller it belongs to. */
function programClampPauseLendsJog(): boolean {
  const pending = programClampPause
  const tc = store().toolChange
  return pending !== null
    && pending.run === programPartsRun
    && pending.run.controller === controller
    && pending.run.heldBetweenParts
    && tc?.mode === 'clampPause'
    && tc.step === 'awaiting-swap'
}

/** WO-2437 fix round 4: MDI works at a program's clamp pause once it has
 *  parked - the board is idle between parts, as for the jog it lends. */
export function programClampPauseTakesMdi(): boolean {
  return programClampPauseLendsJog()
    && controller !== null
    && !controller.hasActiveJob()
    && controller.machineState() === 'idle'
}

export function subscribeToolChangeHold(listener: () => void): () => void {
  toolChangeHoldListeners.add(listener)
  return () => { toolChangeHoldListeners.delete(listener) }
}

/** ENTERED AT THE HOLD, LEFT ON EVERY EDGE THAT ENDS IT. A hold that outlived
 *  its program would leave jog enabled against a running one, so the clearing
 *  call sits on the lifecycle edge rather than on any one caller's good
 *  manners. */
function setToolChangeHold(next: ToolChangeHold | null): void {
  if (toolChangeHold === next) return
  toolChangeHold = next
  for (const listener of toolChangeHoldListeners) listener()
}

/**
 * WO-1330 fix round: THE SEQUENCE OUTLIVES ITS PERMISSIONS BY ONE STEP.
 *
 * `toolChangeHold` is what the panels read, and it has to end the instant
 * CYCLE START is accepted - before the incoming spindle is commanded, so
 * nobody can jog or re-zero Z while it ramps. The program, however, is still
 * standing at the boundary until the up-to-speed gate releases stage 2. This
 * is that longer-lived fact: which hold it was, and whether the machine has
 * CONFIRMED a Z work zero for the incoming frame since the hold opened. The
 * frame never switches without that receipt (the work order's order:
 * "the frame switches after the operator's Z zero is confirmed on the board").
 */
interface PendingToolChange {
  controller: MachineController
  hold: ToolChangeHold
  zZeroConfirmed: boolean
  /** The incoming spindle the release starts and gates on, or null when this
   *  connection cannot drive the spindle and the operator starts it. Decided
   *  ONCE, at the hold, by the same answer that decided the stop there. */
  spindle: ProgramSpindle | null
  /** The controller session CYCLE START released the hold in, or null while
   *  the hold is open. See `toolChangeStageTwoReceipts`. */
  releasedRevision: number | null
  /** The "waiting for the offsets" line is said once per release. */
  saidAwaitingReceipts: boolean
}
let pendingToolChange: PendingToolChange | null = null

/** Every edge that ends the program at, or carries it past, the boundary. */
function endToolChangeSequence(): void {
  pendingToolChange = null
  setToolChangeHold(null)
}

/**
 * MAY A WORK OFFSET BE WRITTEN RIGHT NOW? ALWAYS. THE ANSWER IS THE OPERATOR'S.
 *
 * This used to refuse every write during a tool-change hold except the incoming
 * frame's Z. **Nobody asked for that.** Operator ruling 2026-09-13:
 *
 *   "who said a user can't change the work coordinate offsets they want part
 *    way through it's on them... The user would maybe want to move his work
 *    offset 1 mm to the right if he started a cut and it didn't do what he
 *    wanted. So stop imparting your own unrequested safety checks on things
 *    that aren't required."
 *
 * That is the standing rule of this project (LIENCAM rule 11, and the
 * no-safety-nanny ruling behind it): the software refuses only what it CANNOT
 * do. It can plainly write a work offset during a hold, so it does, and the
 * consequences are the operator's to own. Five audit rounds pushed this
 * restriction wider and wider; every one of them was elaborating a requirement
 * that never existed.
 *
 * Kept as a function returning null so the call sites stay one-line and a real
 * cannot - if one is ever found - has an obvious home. Do not put a
 * may-not here.
 */
export function workOffsetWriteRefusal(
  _wcs: WcsId | null,
  _axes: readonly ControlAxis[],
  _kind: 'operator' | 'restore' = 'operator',
): string | null {
  return null
}

/** A BOARD RECEIPT for a Z work zero, and the only thing that satisfies the
 *  hold. Counted only while the hold's permissions are open and only for the
 *  frame the incoming setup runs in - a G54 Z, or a write the machine did not
 *  confirm, zeroes nothing about the tool being fitted. */
function noteToolChangeZReceipt(wcs: WcsId | null, axis: ControlAxis, revision: number): void {
  const pending = pendingToolChange
  if (
    pending === null
    || axis !== 'Z'
    || revision !== connectionRevision
    || toolChangeHold !== pending.hold
    || wcs !== pending.hold.wcs
  ) return
  pending.zZeroConfirmed = true
}

/** CYCLE START AT A TOOL-CHANGE HOLD. Returns false - with nothing sent and the
 *  hold still open - until the incoming frame's Z zero has a receipt AND no
 *  write the hold accepted is still waiting for one (audit, seventh round: a
 *  write in flight is not a write applied, and the hold's permissions must not
 *  end with a frame change still on its way to the board). Once both hold, the
 *  hold's permissions end HERE, before the caller commands the spindle; the
 *  pending sequence stays until stage 2 is released. */
function releaseToolChangeHold(ctrl: MachineController): boolean {
  const pending = pendingToolChange
  if (pending === null || pending.controller !== ctrl || toolChangeHold !== pending.hold) return true
  // Every accepted offset route either holds this machine's one write slot
  // until its receipt (the shared writer, the DRO/pendant zero, a restore) or
  // runs inside a probe cycle that awaits its `G10 L20` acknowledgement.
  const awaiting = machineWorkOffsetWriteInFlight(controlMachineId())
    ? 'a work offset write'
    : probeCycleActive ? 'the probe cycle and its work zero' : null
  if (awaiting !== null) {
    store().pushConsole(
      'tx',
      `Cycle Start: refused - ${awaiting} is still waiting for the machine to confirm it, so the spindle `
        + `was not started and "${pending.hold.nextName}" was not started. Press CYCLE START again once `
        + 'the machine has answered.',
      'error',
    )
    return false
  }
  if (!pending.zZeroConfirmed) {
    const { hold } = pending
    store().pushConsole(
      'tx',
      `Cycle Start: refused - the machine has not confirmed a ${hold.wcs} Z work zero since the tool `
        + `change, so the spindle was not started and "${hold.nextName}" was not started. Set the `
        + `${hold.wcs} Z zero for ${hold.fit}, then press CYCLE START.`,
      'error',
    )
    return false
  }
  setToolChangeHold(null)
  pending.releasedRevision = connectionRevision
  pending.saidAwaitingReceipts = false
  // THE SPINDLE THE HOLD STOPPED IS THE SPINDLE THIS RELEASE STARTS. Whatever
  // has touched the program's intent since the hold, the caller's
  // `runWithGeometryProgramSpindle` commands and gates exactly this one.
  if (pending.spindle !== null && geometryProgramSpindle?.controller !== ctrl) {
    geometryProgramSpindle = {
      ...pending.spindle,
      controller: ctrl,
      running: false,
      saidNoSpindleLink: false,
      commandedAgainstStatus: null,
    }
  }
  return true
}

/** THE RAMP'S HALF OF ROW 5 (audit, eighth round). CYCLE START released the
 *  hold with every receipt in, but stage 2 is released later, by the
 *  up-to-speed gate - and a controller reopen in between replaces the board
 *  those receipts came from. So that release asks again, and answers:
 *  - `wait` while any work-offset write (the reopen restore) is still on its
 *    way to the board;
 *  - `release` when nothing is on its way and either no reopen happened since
 *    CYCLE START, or the reopened session has confirmed the incoming frame;
 *  - `handed-back` when the reopened board never confirmed that frame: the
 *    spindle stops and the hold opens again, and the operator's Z receipt from
 *    the ended session no longer counts. */
function toolChangeStageTwoReceipts(ctrl: MachineController): 'release' | 'wait' | 'handed-back' {
  const pending = pendingToolChange
  if (pending === null || pending.controller !== ctrl || toolChangeHold !== null) return 'release'
  if (machineWorkOffsetWriteInFlight(controlMachineId())) {
    if (!pending.saidAwaitingReceipts) {
      pending.saidAwaitingReceipts = true
      store().pushConsole(
        'rx',
        `Spindle at speed; "${pending.hold.nextName}" waits until the machine confirms the work offsets `
          + 'it is still writing. Stop, Feed Hold and E-STOP all work while it waits.',
        'info',
      )
    }
    return 'wait'
  }
  if (pending.releasedRevision === connectionRevision) return 'release'
  const { wcs } = pending.hold
  const confirmed = (['X', 'Y', 'Z'] as const).every((axis) =>
    reportedWorkOffsetRevision[wcs][axis] === connectionRevision
    || workZeroRevision[wcs][axis] === connectionRevision)
  if (confirmed) return 'release'
  cancelSpindleSpeedWait()
  stopGeometryProgramSpindle(ctrl)
  pending.zZeroConfirmed = false
  reopenToolChangeHold(ctrl)
  store().pushConsole(
    'rx',
    `Cycle Start: cancelled - the controller reopened while the spindle was coming up to speed and has `
      + `not confirmed the ${wcs} work offset since, so the spindle was stopped and "${pending.hold.nextName}" `
      + `was not started. Set the ${wcs} Z zero for ${pending.hold.fit}, then press CYCLE START.`,
    'error',
  )
  return 'handed-back'
}

/** What the console says when Stop/Reset ends a multi-part program. At a tool
 *  change it names the setup that did not start and how to run it again. */
function programPartsStopResetReason(ctrl: MachineController): string {
  const pending = pendingToolChange
  if (pending === null || pending.controller !== ctrl) {
    return 'Program parts stopped by Stop/Reset; no later part was loaded.'
  }
  return `Program stopped by Stop/Reset at the tool change; "${pending.hold.nextName}" was not `
    + 'started and nothing is loaded. Load the program again to run it.'
}

/** The release did not get as far as a running spindle (the start was refused,
 *  or a Feed Hold dropped the ramp), and the program is still held at the
 *  boundary with the spindle stopped - so the operator is back at the tool
 *  change, with the Z zero they already set still counted. */
function reopenToolChangeHold(ctrl: MachineController): void {
  const pending = pendingToolChange
  const run = programPartsRun
  if (pending === null || pending.controller !== ctrl) return
  if (!run || run.controller !== ctrl || !run.heldBetweenParts) return
  if (geometryProgramSpindle?.running === true) return
  setToolChangeHold(pending.hold)
}

/** The spindle intent belonging to the currently staged geometry program.
 * Motion remains in the controller's queue; these action frames are executed
 * through commandSpindle so they never consume one of the board's move slots. */
interface GeometryProgramSpindle extends ProgramSpindle {
  controller: MachineController
  running: boolean
  /** WO-1275: the "this connection cannot answer the up-to-speed question"
   *  note is worth saying, and worth saying ONCE per loaded program. */
  saidNoSpindleLink: boolean
  /** WO-1275: the status snapshot that was current when this speed was
   *  COMMANDED. `MachineStatus` is replaced whole on every frame, so while
   *  `status()` is still this object the machine has not spoken since we
   *  asked - and its `upToSpeed` was computed against whatever was commanded
   *  BEFORE. See `heardSinceCommanded`. */
  commandedAgainstStatus: MachineStatus | null
}
let geometryProgramSpindle: GeometryProgramSpindle | null = null
/** WO-2157: the program spindle words a loaded probe already kept off and said
 *  so for, so a resume of the same part does not say it again. */
const probeSpindleSaid = new WeakSet<GeometryProgramSpindle>()
/** Geometry controllers have no G43.1 text door. Keep the last equivalent
 * delta so the next tool replaces it instead of accumulating it in WCS Z. */
let geometryToolLengthOffset: {
  controller: MachineController
  wcs: WcsId
  deltaMm: number
} | null = null
/** WO-2522: the work offset's Z write the last `applyToolLengthOffset` queued,
 *  so the measure's console line can say what the offset itself got. */
let lastToolLengthWorkZWrite: ToolLengthWorkZWrite | null = null

/** The unscaled speed behind the active VFD command. UC100's SRO is only a
 * reported percentage; this is the state needed to turn that percentage into
 * a fresh Modbus setpoint without compounding successive button presses. */
interface ActiveSpindleCommand {
  controller: MachineController
  baseRpm: number
  direction: 'cw' | 'ccw'
  overridePercent: number
  maximumNoticeSaid: boolean
}
let activeSpindleCommand: ActiveSpindleCommand | null = null

/** A call-driven spindle that the motion controller does not own is an
 * external setpoint. Its override must therefore be reapplied to that call;
 * changing only the motion controller's SRO would not change shaft speed. */
function spindleOverrideUsesExternalSetpoint(target: MachineController): boolean {
  return target.capabilities.spindleCommands && !target.capabilities.ownsSpindle
}

function applyLiveSpindleOverride(
  target: MachineController,
  sendOverride: (change: OverrideChange) => void,
  change: OverrideChange,
): void {
  const active = activeSpindleCommand
  if (
    !spindleOverrideUsesExternalSetpoint(target)
    || !active
    || active.controller !== target
    || change.kind !== 'spindle'
    || !target.spindleOn
  ) {
    sendOverride(change)
    return
  }

  const maximumRpm = controlMachine(useCamStore.getState()).maxSpindleRpm
  if (maximumRpm === undefined) {
    let requestedPercent: number
    if (change.to === 'reset') requestedPercent = 100
    else if (change.to === 'percent') requestedPercent = change.percent
    else requestedPercent = active.overridePercent + change.direction * (change.coarse ? 10 : 1)
    if (!Number.isFinite(active.baseRpm) || active.baseRpm <= 0 || !Number.isFinite(requestedPercent)) {
      sendOverride(change)
      return
    }
    sendOverride({ kind: 'spindle', to: 'percent', percent: requestedPercent })
    target.spindleOn(active.direction, active.baseRpm * requestedPercent / 100)
    active.overridePercent = requestedPercent
    return
  }
  const resolved = routeLiveSpindleOverride({
    baseRpm: active.baseRpm,
    maximumRpm,
    currentPercent: active.overridePercent,
    direction: active.direction,
    maximumNoticeSaid: active.maximumNoticeSaid,
    sendOverride,
    sendSpindle: (direction, rpm) => target.spindleOn!(direction, rpm),
    announce: (sentence) => store().pushConsole('rx', sentence, 'warn'),
  }, change)
  if (resolved === null) return
  active.overridePercent = resolved.appliedPercent
  if (resolved.clamped) active.maximumNoticeSaid = true
}

/** Any spindle stop invalidates the retained command before OFF is sent. This
 * includes UccncController's internal VFD safety stop, so a later override
 * gesture cannot reinterpret stale command state as authority to restart. */
export function installLiveSpindleOverrideRouting(target: MachineController): void {
  const setOverride = target.setOverride.bind(target)
  target.setOverride = (change) => applyLiveSpindleOverride(target, setOverride, change)
  if (!target.spindleOff) return
  const spindleOff = target.spindleOff.bind(target)
  target.spindleOff = () => {
    if (activeSpindleCommand?.controller === target) activeSpindleCommand = null
    spindleOff()
  }
}

function stopGeometryProgramSpindle(target: MachineController): void {
  const spindle = geometryProgramSpindle
  if (!spindle || spindle.controller !== target) return
  spindle.running = false
  // Nothing gates a stop. Calling OFF is also the cleanup after a partially
  // accepted or externally failed start, where local state cannot prove what
  // the inverter did.
  commandGeometryProgramSpindle('off', 0, target)
}

function startGeometryProgramSpindle(target: MachineController): boolean {
  const spindle = geometryProgramSpindle
  if (!spindle || spindle.controller !== target || spindle.running) return true
  // WO-2157: the program runs on with the spindle off while a probe is the
  // loaded tool - said once for this spindle word, never a held program.
  const probe = controlLoadedProbe()
  if (probe !== null) {
    if (!probeSpindleSaid.has(spindle)) {
      probeSpindleSaid.add(spindle)
      sayProbeKeepsSpindleOff(probe)
    }
    return true
  }
  const result = commandGeometryProgramSpindle(spindle.direction, spindle.rpm, target)
  if (result.ok) {
    spindle.running = true
    // WO-1275: everything the machine has said so far was said about the speed
    // it was running BEFORE this call. Remember which frame that was.
    spindle.commandedAgainstStatus = target.status()
    return true
  }
  stopGeometryProgramSpindle(target)
  store().pushConsole('tx', `Cycle Start: refused - ${result.reason}`, 'error')
  return false
}

/** Speak the spindle word that belongs to the loaded file without opening the
 * operator's MDI door. Call-routed controllers still receive only the typed
 * spindle call: commandSpindle evaluates the text callback lazily. Text-routed
 * controllers receive the standard word the reader already interpreted from
 * this file, rather than an empty action that can never change spindle status.
 */
function commandGeometryProgramSpindle(
  direction: 'cw' | 'ccw' | 'off',
  rpm: number,
  target: MachineController,
): SpindleCommandResult {
  const alreadyProgramOwned = programOwnActionInFlight
  programOwnActionInFlight = true
  try {
    return commandSpindle(
      direction,
      rpm,
      () => direction === 'off'
        ? ['M5']
        : [`${direction === 'ccw' ? 'M4' : 'M3'} S${rpm}`],
      target,
    )
  } finally {
    programOwnActionInFlight = alreadyProgramOwned
  }
}

function runWithGeometryProgramSpindle(target: MachineController, run: () => boolean): boolean {
  // WO-1335 fix round 3: the file's PREAMBLE coolant, at the instant the
  // operator releases the first staged motion. This wrapper is every release
  // door there is, and the pending word is cleared as it is applied, so it
  // happens once per loaded program and never on a resume.
  applyPendingGeometryProgramCoolant(target)
  if (!startGeometryProgramSpindle(target)) return false
  // WO-1637: and after the spindle, an output's on-delay (M8ondelay ...).
  const started = releaseMotionWhenUpToSpeed(
    target,
    () => releaseAfterOutputOnDelay(target, run, () => stopGeometryProgramSpindle(target)),
  )
  if (!started) stopGeometryProgramSpindle(target)
  return started
}

// ---- WO-1275: motion begins only once the spindle is at speed -------------
//
// MEASURED ON THE MACHINE 2026-09-07 (`src/tests/evidence/SHAKEDOWN-2026-09-07/
// spindle/`): the first program this product ever ran with its own spindle
// issued the spindle command and the motion together, and the third emitted
// move was a CUT. A 9.52 mm cutter entered the work at about 2,000 RPM on an
// 18,000 RPM operation; full speed arrived roughly fifteen seconds later.
// Everything needed to notice already existed - the tolerance is a validated
// definition field, the comparison is `UccncController.vfdUpToSpeed`, and the
// panel already renders "up to speed" / "ramping". Nothing consulted it.
//
// WHERE THIS SITS, AND WHAT IT HOLDS - WHICH IS THE CUT AND NOT THE APPROACH.
// A geometry program is STAGED ON THE BOARD and released by `startJob`; the app
// never sees move N complete before move N+1 begins, so the instants at which
// this software can decide anything are the instants it releases staged motion:
// `startJob` / `resumeJob` / `cycleResume` / `stepJob`, the wrapper above.
//
// That alone would hold the whole program, approach included - which is exactly
// what Operator's clauses forbid ("moving TO POSITION below speed is ALLOWED", and
// the spindle is to spin up DURING the approach). So the program is STAGED IN
// TWO PIECES at load time: everything up to the first cutting move, and the
// rest. `splitApproachFromFirstCut` does that with the program-parts machinery
// WO-1054 already runs on this board - same ids, same index, same progress
// accounting, one extra rapid-boundary handoff. Cycle Start then commands the
// spindle and releases the APPROACH immediately, ungated, so the spin-up
// happens while the machine is travelling; the cut is a separate staged part,
// and THAT is what this gate holds.
//
// `stagedMotionCuts` is the one fact the release consults: does the motion
// presently on the board contain a move that cuts? If it does not, there is
// nothing here to protect and the release goes through.
//
// WHAT IS NOT GATED, EVER: jog, Goto, park, MDI, probing, homing and a G-code
// TEXT program. None of them pass through this function - `geometryProgramSpindle`
// is null for all of them - so Operator's first clause ("moving TO POSITION below
// speed is ALLOWED") holds by construction rather than by a check that could be
// got wrong.
//
// WHAT IS NOT GATED, EVER, PART TWO: A STOP. `cancelSpindleSpeedWait` clears one
// local timer, makes no call and cannot fail, and every stop door calls it
// FIRST. The wait additionally re-asks the E-STOP latch, the alarm state and the
// connection before it releases anything, so a stop that arrived by any route -
// button, hardware input, alarm, disconnect - drops the pending motion instead
// of being queued behind it.

/**
 * DOES THIS STAGED MOVE CUT?
 *
 * A rapid is the product's own declaration that a move is POSITIONING and not
 * cutting (`QueuedMove.rapid`, ADR-0043 section 3, and the same flag the
 * capacity plan's boundary rule already trusts). An arc is never a rapid, so an
 * arc always cuts. A dwell moves nothing and a marker is not motion at all.
 */
function moveCuts(move: QueuedMove): boolean {
  if (move.kind === 'line') return move.rapid !== true
  return move.kind === 'arc'
}

function programCuts(program: MachineProgram): boolean {
  return program.steps.some((step) => isStagedMove(step) && moveCuts(step))
}

/** A half-open range of one staged program's steps, carrying only the index
 *  entries those steps own - the same shape `buildProgramParts` materialises,
 *  so a part made here is indistinguishable from a part made there. */
function sliceStagedProgram(program: MachineProgram, start: number, end: number): MachineProgram {
  const steps = program.steps.slice(start, end)
  const index: MachineProgram['index'] = {}
  for (const step of steps) {
    if (!isStagedMove(step)) continue
    const entry = program.index[step.id]
    if (entry !== undefined) index[step.id] = entry
  }
  return { frame: program.frame, units: program.units, steps, index }
}

/**
 * STAGE THE APPROACH SEPARATELY FROM THE FIRST CUT (WO-1275 clauses 1 and 3).
 *
 * The lead-in rapids and the first cut arrive from the builder as one staged
 * list, and a board runs a staged list from end to end once started. Holding
 * that list for the spindle holds the approach with it - which gates
 * positioning, and leaves the spindle spinning up while the machine stands
 * still instead of while it travels. Both are outcomes this order forbids.
 *
 * So the first part is CUT IN TWO at the first cutting move: part one is
 * approach, part two begins with the plunge. The pieces are the same moves in
 * the same order with the same ids - nothing is re-ordered, merged or invented,
 * and the whole-program progress accounting adds up exactly as before.
 *
 * THE BOUNDARY IS SAFE, and it is the one place a boundary is safest: the
 * machine sits idle at the end of a positioning move, at the point the cut is
 * about to start, having cut nothing. That is the same "leave the tool where
 * the toolpath had already lifted it" argument the capacity rule makes, applied
 * to the one boundary the toolpath itself declares.
 *
 * NOT SPLIT: a program whose very first move cuts (there is no approach to
 * release, so the gate holds all of it), a program that never cuts, and any
 * program with no spindle intent of ours - those stage byte-for-byte as before.
 */
function splitApproachFromFirstCut(parts: MachineProgram[]): MachineProgram[] {
  const first = parts[0]
  if (first === undefined) return parts
  const firstCut = first.steps.findIndex((step) => isStagedMove(step) && moveCuts(step))
  if (firstCut <= 0) return parts
  return [
    sliceStagedProgram(first, 0, firstCut),
    sliceStagedProgram(first, firstCut, first.steps.length),
    ...parts.slice(1),
  ]
}

/**
 * Does the motion PRESENTLY STAGED on the board contain a cutting move?
 *
 * Written where the program is staged and read where motion is released, so
 * the gate asks about the moves that are actually about to run rather than
 * about the program they came from. It starts `true` because that is the
 * conservative answer: an unknown staged list is treated as a cut and waits.
 */
let stagedMotionCuts = true
/** Supersedes an older receipt-bearing geometry load when a newer valid load
 * reaches the WCS-selection boundary on the same controller session. */
let geometryProgramLoadRevision = 0

/** How long the app waits for the spindle to reach its commanded speed before
 *  it gives up, stops the spindle and refuses to begin the cut.
 *
 *  The longest spin-up this project has ever MEASURED is about fifteen seconds
 *  (zero to 18,000 RPM, 2026-09-07). Sixty seconds is four times that. It is
 *  not here to hurry the operator: it is here so an inverter that never reports
 *  a speed cannot leave a cutter turning over the work indefinitely. */
export const SPINDLE_UP_TO_SPEED_TIMEOUT_MS = 60_000
/** A `vfd` push already re-raises `onStatus`, which polls this too, so in
 *  practice the release happens on the frame that reports arrival. This timer
 *  is what makes the wait survive frames stopping entirely. */
const SPINDLE_UP_TO_SPEED_POLL_MS = 250

/** The operator-facing sentences this gate can produce. Exported so the tests
 *  asserting them and the code emitting them stay one string - the rule
 *  SPINDLE_REFUSAL and ACTION_REFUSAL already follow. */
export const SPINDLE_SPEED_GATE = {
  waiting: (rpm: number): string =>
    `Waiting for the spindle to reach ${rpm} RPM before the cut begins. `
    + 'Stop, Feed Hold and E-STOP all work while it waits.',
  released: (rpm: number): string => `Spindle at ${rpm} RPM; the program's motion starts now.`,
  timedOut: (rpm: number): string =>
    `Cycle Start: refused - the spindle did not reach ${rpm} RPM within `
    + `${Math.round(SPINDLE_UP_TO_SPEED_TIMEOUT_MS / 1000)} seconds. The cut was not started and `
    + 'the spindle was stopped.',
  cancelled: (why: string): string =>
    `Cycle Start: cancelled - ${why} while the spindle was coming up to speed. Nothing was cut.`,
  noLink:
    'This bridge reports no inverter link, so LienCAM cannot tell when the spindle is up to '
    + 'speed. The program runs without that check.',
} as const

/**
 * The three answers this gate can get, and there is no fourth.
 *
 * THE NULL DECISION, WHICH IS THE WHOLE JUDGEMENT OF WO-1275. `upToSpeed` is
 * deliberately three-valued and deliberately refuses to guess. The two ways to
 * get it wrong are named in the order: treating null as "at speed" reinstates
 * the defect, and treating null as "never at speed" bricks a machine that has
 * no VFD telemetry - a legitimate configuration.
 *
 * They are only in tension if you ask ONE question. There are two:
 *
 *  1. CAN this connection answer at all? That is `status().spindle`, which the
 *     contract requires every backend to state: an object when a spindle link
 *     exists, `null` when "the whole concept does not apply to this
 *     connection". GRBL and the simulator-without-a-link answer null, and so
 *     does a bridge started without `--vfd`. Those machines are NOT gated -
 *     there is nothing to wait for and waiting would brick them.
 *
 *  2. Given that it CAN answer, HAS it said yes? That is `spindle.upToSpeed`,
 *     and here only literal `true` is proof. `false` is "ramping"; `null` is
 *     "this link cannot presently prove it" - most often the ordinary transient
 *     between commanding the spindle and the first `vfd` push. Neither is
 *     evidence that a cutter may enter the work, so both WAIT. Null is bounded
 *     by SPINDLE_UP_TO_SPEED_TIMEOUT_MS rather than believed.
 *
 * So null never becomes a guessed true, and never becomes a permanent no.
 */
type SpindleSpeedVerdict = 'no-spindle-link' | 'at-speed' | 'below-speed'

export function spindleSpeedVerdict(ctrl: MachineController): SpindleSpeedVerdict {
  const spindle = ctrl.status().spindle
  if (spindle === null) return 'no-spindle-link'
  return spindle.upToSpeed === true ? 'at-speed' : 'below-speed'
}

/**
 * Has the machine said ANYTHING since this speed was commanded?
 *
 * `upToSpeed` is a comparison the backend recomputes when a frame lands, and
 * `status()` hands back the last frame it built - so immediately after
 * `spindleOn` the published answer is still the one computed against the
 * PREVIOUS commanded speed. Believing it is a real way to plunge: finish an
 * operation at 12,000 with the inverter reporting "up to speed", load the next
 * one at 18,000, and that stale `true` would release the cut at 12,000.
 *
 * A frame is a whole new `MachineStatus` object every time, so identity is the
 * honest test for "the machine has spoken since we asked". This costs at most
 * one status frame (the keepalive polls at 750 ms, and a `vfd` push arrives
 * sooner) against a spin-up measured in seconds.
 */
function heardSinceCommanded(ctrl: MachineController, against: MachineStatus | null): boolean {
  return against === null || ctrl.status() !== against
}

/** Elapsed-time clock for every in-memory session interval.
 *
 * Production always uses the browser's monotonic clock, so an NTP or operator
 * wall-clock correction cannot shorten or stretch a machine wait. Vitest's
 * fake Date carries this Sinon marker; using its single harness clock keeps
 * older tests that model operator time with `setSystemTime` on the same clock
 * as tests that advance timers. The WO-1991 clock-jump test leaves Date real
 * and spies only Date.now, so it still exercises the production branch. */
function sessionElapsedNowMs(): number {
  const clockDate = Date as DateConstructor & { isFake?: boolean }
  return clockDate.isFake === true ? Date.now() : performance.now()
}

interface SpindleSpeedWait {
  controller: MachineController
  rpm: number
  /** The staged motion this session has NOT yet released to the board. */
  release: () => boolean
  /** See `heardSinceCommanded`. */
  commandedAgainstStatus: MachineStatus | null
  deadline: number
  timer: ReturnType<typeof setInterval> | null
}
let spindleSpeedWait: SpindleSpeedWait | null = null

/** The commanded RPM this session is presently holding motion for, or null.
 *  A read, for tests and for anything that wants to say what is happening. */
export function spindleSpeedWaitRpm(): number | null {
  return spindleSpeedWait?.rpm ?? null
}

/** DROP a pending release. One cleared timer and one nulled field: no call, no
 *  await, no failure mode, so this can never delay or swallow the stop that
 *  calls it. That is the reason it is written as its own function and called
 *  FIRST by every stop door. */
function cancelSpindleSpeedWait(): void {
  // WO-1637: motion held for an output's on-delay is armed motion too, dropped
  // on every edge that drops this wait - and the on-delay window with it, so a
  // stop, pause or E-STOP that interrupts it leaves nothing to hold a later,
  // unrelated release (audit 2026-09-17). The next switch arms its own.
  cancelOutputOnDelayHold()
  outputOnDelayUntilMs = 0
  clearSpindleSpeedWait()
}

/** The spindle wait alone, for the two places that REPLACE or FIRE it inside
 *  one release (`releaseMotionWhenUpToSpeed`, `pollSpindleSpeedWait`). The
 *  output on-delay window survives them: the release they lead to still owes it. */
function clearSpindleSpeedWait(): void {
  cancelOutputOnDelayHold()
  const wait = spindleSpeedWait
  if (!wait) return
  spindleSpeedWait = null
  if (wait.timer !== null) clearInterval(wait.timer)
}

function abandonSpindleSpeedWait(
  wait: SpindleSpeedWait,
  message: string,
  event: 'stopped' | 'failed',
): void {
  cancelSpindleSpeedWait()
  stopGeometryProgramSpindle(wait.controller)
  // WO-1275: the held release can be the CUT of a program whose approach has
  // already run - a running multipart program with nothing left in flight. End
  // it, or the operator is left watching a program that reports "streaming"
  // while the board sits idle holding a part that will never be started.
  const run = programPartsRun
  if (run && run.controller === wait.controller && run.started) {
    endProgramParts(
      message,
      event,
      event === 'failed' ? { code: null, message, line: null, moveId: null } : null,
      'error',
    )
    return
  }
  store().pushConsole('rx', message, 'error')
}

function releaseMotionWhenUpToSpeed(
  target: MachineController,
  release: () => boolean,
): boolean {
  const spindle = geometryProgramSpindle
  // This motion is not a cut whose speed this session commanded, so there is
  // nothing to compare it against and nothing to hold.
  if (!spindle || spindle.controller !== target) return release()
  // WO-2157: a probe kept this spindle off, so there is no speed to wait for.
  if (!spindle.running && controlLoadedProbe() !== null) return release()

  // OPERATOR'S FIRST CLAUSE, IN THE PLACE THAT CAN HONOUR IT: "moving TO POSITION
  // below speed is ALLOWED". The staged approach carries no cutting move, so
  // it goes NOW - with the spindle already commanded a few lines above, which
  // is clause 3: it spins up while the machine travels, not afterwards.
  if (!stagedMotionCuts) return release()

  const verdict = spindleSpeedVerdict(target)
  if (verdict === 'no-spindle-link') {
    // Reachable in practice: the bridge ran with --vfd (so `spindleCommands` is
    // true and a program spindle intent exists) while its definition name is
    // one this build cannot compile, so no reading is decoded. Say it plainly,
    // once, and RUN - a machine that cannot report speed must still cut.
    if (!spindle.saidNoSpindleLink) {
      spindle.saidNoSpindleLink = true
      store().pushConsole('rx', SPINDLE_SPEED_GATE.noLink, 'warn')
    }
    return release()
  }
  if (verdict === 'at-speed' && heardSinceCommanded(target, spindle.commandedAgainstStatus)) {
    return release()
  }

  // NOT REFUSED - HELD. The condition clears itself in seconds, so waiting is
  // the honest answer and refusing would be the nanny Operator ruled out on
  // 2026-09-07. The check is re-run on EVERY release, never cached against a
  // speed it passed once, which is what re-arms it after a speed change
  // between operations - and what would have caught WO-1276's part-boundary
  // spindle loss instead of dragging a dry cutter through 2,459 moves.
  clearSpindleSpeedWait()
  const wait: SpindleSpeedWait = {
    controller: target,
    rpm: spindle.rpm,
    release,
    commandedAgainstStatus: spindle.commandedAgainstStatus,
    deadline: sessionElapsedNowMs() + SPINDLE_UP_TO_SPEED_TIMEOUT_MS,
    timer: null,
  }
  spindleSpeedWait = wait
  store().pushConsole('rx', SPINDLE_SPEED_GATE.waiting(spindle.rpm), 'info')
  wait.timer = setInterval(pollSpindleSpeedWait, SPINDLE_UP_TO_SPEED_POLL_MS)
  // THE CYCLE WAS ACCEPTED. The operator's gesture worked, the spindle is
  // spinning up and the motion is armed behind it. Reporting false here would
  // make every caller read an accepted start as a refusal and stop the spindle
  // this call just started.
  return true
}

function pollSpindleSpeedWait(): void {
  const wait = spindleSpeedWait
  if (!wait) return

  // EVERY WAY THE MACHINE CAN HAVE BEEN STOPPED, RE-ASKED BEFORE RELEASING.
  // The stop doors already cancel this wait outright; these are the routes that
  // do not pass through them - a hardware E-STOP input arming the latch from a
  // status frame, a controller alarm, a reset in flight, a connection that went
  // away. A pending release must never outlive any of them.
  if (wait.controller !== controller || wait.controller.connectionPhase() !== 'connected') {
    abandonSpindleSpeedWait(
      wait,
      SPINDLE_SPEED_GATE.cancelled('the machine connection changed'),
      'failed',
    )
    return
  }
  if (estopNeedsReset()) {
    abandonSpindleSpeedWait(wait, SPINDLE_SPEED_GATE.cancelled('the E-STOP was set'), 'stopped')
    return
  }
  if (wait.controller.resetInProgress()) {
    abandonSpindleSpeedWait(wait, SPINDLE_SPEED_GATE.cancelled('the machine was reset'), 'stopped')
    return
  }
  if (wait.controller.machineState() === 'alarm') {
    abandonSpindleSpeedWait(wait, SPINDLE_SPEED_GATE.cancelled('the machine raised an alarm'), 'failed')
    return
  }

  const verdict = spindleSpeedVerdict(wait.controller)
  const answered = verdict === 'no-spindle-link'
    || (verdict === 'at-speed' && heardSinceCommanded(wait.controller, wait.commandedAgainstStatus))
  if (answered) {
    // WO-1330: the spindle has answered; the frame at a tool change may not
    // have. A write still on its way keeps this wait polling - the timeout
    // below is about the spindle, which is at speed.
    if (toolChangeStageTwoReceipts(wait.controller) !== 'release') return
    clearSpindleSpeedWait()
    store().pushConsole('rx', SPINDLE_SPEED_GATE.released(wait.rpm), 'info')
    if (!wait.release()) stopGeometryProgramSpindle(wait.controller)
    return
  }

  if (sessionElapsedNowMs() >= wait.deadline) {
    abandonSpindleSpeedWait(wait, SPINDLE_SPEED_GATE.timedOut(wait.rpm), 'failed')
  }
}

/** Operator-facing state for the controller-idle handoff between two parts.
 * The job remains one running program; this snapshot only gives transport UI
 * enough context to name the next part without exposing the mutable run. */
interface ProgramPartsTransportState {
  completedPart: number
  nextPart: number
  totalParts: number
  held: boolean
}

export function programPartsTransportState(): ProgramPartsTransportState | null {
  const run = programPartsRun
  if (
    !run
    || !run.started
    || !run.completionSignaled
    || run.partIndex >= run.parts.length - 1
  ) return null

  // WO-2256: a resumed run's parts are the file's last ones; its way back
  // is the part it carries on in.
  const numbering = store().stagedNumbering
  const filePart = (index: number): number => (numbering === null
    ? index
    : numbering.partsBefore + Math.max(0, index - numbering.stagedPartsBefore))
  // WO-2580: a stop-only part is never counted; held after one, the program
  // names the counted part before it.
  const counted = countedPartsBefore(run, run.partIndex + 1)
  return {
    completedPart: filePart(Math.max(0, counted - 1)) + 1,
    nextPart: filePart(counted) + 1,
    totalParts: filePart(countedPartsBefore(run, run.parts.length)),
    held: run.heldBetweenParts,
  }
}

/** WO-2562: name the file's M0 boundary, not the last geometric move.
 * The boundary survives clearing the console and uses original file lines
 * after a run-from-line restart. This is a readout; release/MDI authority stays. */
export function programM0HoldLine(): number | null {
  const run = programPartsRun
  if (!run || !run.heldBetweenParts || !run.completionSignaled) return null
  const boundary = run.boundaries?.get(run.partIndex + 1)
  const m0 = /stopped at the M0 on line (\d+)/.exec(boundary?.holdMessage ?? '')
  return m0 ? Number(m0[1]) : null
}

/** True for the lifetime of a program loaded through the combined-setup door.
 * Unlike programPartsTransportState(), this includes the ready state and each
 * normally running stage; the setup boundaries distinguish this route from
 * capacity-split and opened-file multipart programs. */
export function combinedSetupProgramActive(): boolean {
  const run = programPartsRun
  return run?.controller === controller && run.boundaries !== undefined
}
/** A status/reset edge can terminate the operator's multipart program before
 * the backend raises its matching terminal job event/progress. Preserve the
 * whole-program terminal snapshot and suppress that one later lifecycle edge
 * so one operator program keeps one terminal state and one cycle-log edge. */
interface ProgramPartsTerminalState {
  controller: MachineController
  progress: StreamerProgress
  suppressNextControllerTerminal: boolean
}
let programPartsTerminal: ProgramPartsTerminalState | null = null
// WO-415: source line up to which streamed lines have been scanned for a
// G54..G59 word. A G5x inside a streamed program never passes through the
// MDI path, and $G cannot be asked for mid-stream (sendCommand is refused
// while a job is active), so the acknowledged line itself is the evidence.
let wcsScanSourceLine = 0
let wcsScanText: string | null = null
let wcsScanLines: string[] = []
// Monotonic session boundary. A Step Back controlled stop awaits timers and
// status reports; if disconnect/reconnect occurs during that await, the old
// transaction must not publish authority into the replacement session.
let connectionRevision = 0
// WO-1554: `machineDatumRevokedAxes` is persisted, so a fresh app session can
// open with a datum already revoked by an earlier one. The console line that
// says the datum "remains revoked after reconnect" describes a RECONNECT in
// THIS session; a first connect has no earlier connection to reconnect to, and
// the page's not-homed state already carries the fact. Keyed per machine and
// reset on page load (module lifetime).
const bridgeConnectedThisSession = new Set<string>()
// WO-1017: a work offset value can survive a controller restart, but on a
// switchless machine that number has no physical meaning until the operator
// establishes zero in the current connection session. Each successful
// (work-offset, axis) write carries the same session stamp used by Step Back;
// a connection phase change makes every older stamp stale without copying
// this fact into the persisted machine-control store.
const workZeroRevision: Record<WcsId, Record<ControlAxis, number>> = {
  G54: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G55: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G56: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G57: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G58: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G59: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
}
// A profile-less bridge constructs an all-zero row for every slot. That exact
// row is not provenance; any non-zero row is controller state even without a
// profile. A profile-backed row or a write receipt reports every finite axis.
const reportedWorkOffsetRevision: Record<WcsId, Record<ControlAxis, number>> = {
  G54: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G55: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G56: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G57: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G58: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
  G59: { X: -1, Y: -1, Z: -1, A: -1, B: -1, C: -1 },
}
const WCS_SLOTS: WcsId[] = ['G54', 'G55', 'G56', 'G57', 'G58', 'G59']

/**
 * THE ONE DOOR INTO THE DURABLE WORK-OFFSET STORE, and the whole rule about
 * who may walk through it. Every caller below is one row of this table; there
 * are no others, and a new one is a change to this table first.
 *
 * | source                                                   | axes written        | value             | state                  |
 * |----------------------------------------------------------|---------------------|-------------------|------------------------|
 * | `zeroWorkAxis` receipt carrying `offset` (bridge or sim)  | ONLY the named axis | `receipt.offset`  | `sent`                 |
 * | `setWorkOffset` receipt `ok:true`                         | ONLY the axes sent  | `receipt.offset`  | `sent`                 |
 * | the operator typing a value in the Offsets panel          | the axis typed      | typed             | `not-sent` until receipt |
 * | connect adoption: `profile` present AND `current==profile`| all three           | `profile`         | `adopted-from-profile` |
 * | a connect RESTORE that the bridge accepted                | as stored           | as stored         | `restored`             |
 * | a `zeroWorkAxis` receipt WITHOUT `offset` (old bridge), a |                     |                   |                        |
 * | refusal, a timeout, a disconnect, A STATUS FRAME, a       | NOTHING             | -                 | unchanged (`unknown`   |
 * | profile-less bridge's defaults, anything else             |                     |                   | if empty)              |
 *
 * THE LAST ROW IS THE POINT. Ten audit rounds of this order died inside code
 * that tried to work out a work offset from a `MachineStatus`: the bridge
 * samples status on its own loop and enqueues it there, so a frame describing
 * the world BEFORE a zero can arrive after that zero's receipt, and no
 * comparison of floating-point coordinates can tell the two apart. WO-1083 gave
 * the zero receipt the echo the set receipt always had, so the value now comes
 * from the thread that applied the write. There is deliberately NO path from
 * `applyContractStatus` to this function - `workOffsetPersistence.wo1042`
 * asserts it by feeding fifty arbitrary frames across a zero.
 *
 * `hello.workOffsets` is read ONCE, at connect, by `reconcileWorkOffsets`, and
 * only as the discriminator that decides which row above applies.
 */
/** WHOSE offsets these are. `controlMachine(state)` is the one resolver for
 *  every Control-side reader (WO-1065), and the connect restore already keys
 *  off it - so a write path that keyed off `project.machine` instead would
 *  store an operator's zero under the CAM setup's machine while driving a
 *  different one, and the next connect would restore the wrong numbers. */
function controlMachineId(): string {
  return controlMachine(useCamStore.getState()).id
}

/** Persisted datum authority belongs only to a physical-machine session. A
 * simulator cycle must never rehabilitate a real machine after position loss.
 * A UCCNC bridge normally is physical, but CNCdrive's non-positive board ids
 * are its demo controller: useful for exercising commands, never authority to
 * clear WO-1145's durable record for the real machine. */
function physicalMachineConnection(): boolean {
  if (store().connectionKind === null
    || !controller
    || activeBackendDefinition?.capabilities.physicalConnection !== true) return false
  return activeBackendDefinition.isPhysicalConnection?.(controller) ?? true
}

/**
 * WO-1705 (Operator, binding 2026-09-19: "if a user changes the length of the
 * axis, it forces a rehome. We don't want to start moving positions on a
 * user."). An axis's TRAVEL (its length - the Machine Library's Travel field)
 * was changed on `machineId`. When that is the machine this session is
 * connected to, each named axis loses its homed state through the SAME
 * revocation a position-lost alarm uses (`onAlarm` above): the durable
 * revocation on a physical link, the controller's own `invalidateDatum`, and
 * the store's aggregate re-read from the controller. One plain console row
 * says so. Nothing else: the live position is not rewritten, and no gate is
 * added - every existing "home first" gate then applies as it already does.
 *
 * Deliberately untouched:
 *   - a machine that is not the connected one (its record changed, the live
 *     session did not);
 *   - a switchless machine (`machineHasNoHomeSwitches` - there is nothing to
 *     rehome; never force homing, STATUS.md);
 *   - a one-end soft-limit trim - its callers never call this.
 */
export function noteAxisTravelChanged(
  machineId: string,
  changes: readonly { axis: JogAxis; fromMm: number; toMm: number }[],
): void {
  if (changes.length === 0 || !controller) return
  if (controller.connectionPhase() !== 'connected') return
  if (controlMachineId() !== machineId) return
  const machine = useCamStore.getState().machineLibrary.find((m) => m.id === machineId)
    ?? controlMachine(useCamStore.getState())
  if (machineHasNoHomeSwitches(machine)) return
  const axes = changes.map((change) => change.axis)
  if (physicalMachineConnection()) useCamStore.getState().revokeMachineDatum(machineId, axes)
  controller.invalidateDatum?.(axes)
  store().setHomed(controller.homedThisSession() === true)
  const what = changes
    .map((change) => `${change.axis} travel changed from ${machineLengthText(change.fromMm)} to ${machineLengthText(change.toMm)}`)
    .join('; ')
  store().pushConsole('rx', `${what} - home ${describeAxisList(axes)} again before moving to machine coordinates.`, 'warn')
}

function storeWorkOffset(
  machineId: string,
  wcs: WcsId,
  offset: Partial<MachinePosition>,
  state: WorkOffsetSyncState,
): void {
  useCamStore.getState().setMachineWorkOffset(machineId, wcs, offset, state)
}

// ---------------------------------------------------------------------------
// WO-1042 - ONE IN-FLIGHT WORK-OFFSET WRITE PER MACHINE
// ---------------------------------------------------------------------------
//
// Four audit rounds died on one shape: two writes into a single WCS record in
// flight together, receipts landing in either order with opposite verdicts, and
// a rollback that had to guess which of them still had authority. Rollback is
// the wrong tool. The rule WO-1053 proved for the spindle link removes the
// shape instead of arbitrating it, and it is stated HERE, once:
//
//   While an offset write awaits its receipt, this machine takes no second one.
//
//  - THE SLOT IS PER MACHINE and is held by ONE OPERATION, which may name
//    several axes of ONE work offset. `zeroWorkAxes(['X','Y','Z'])` is one
//    operation. So is a probe or pendant confirmation: `applyProbeZero`
//    (`pendantMachine.ts`), `ProbeRoutineRunPanel` and `ProbingPanel` each set
//    two or three axes of one WCS in a single synchronous pass, and those axes
//    JOIN one `setWorkOffset` intent - the intent has always been
//    `{wcs, x?, y?, z?}`, so one call carries them all. They are not a second
//    write and they are not queued: nothing has been sent when they join.
//  - A WRITE THAT ARRIVES WHILE THE SLOT IS HELD IS REFUSED - one console line
//    and `false` to its caller, never queued behind the receipt.
//  - THE STORE IS WRITTEN BY THE RECEIPT, NEVER OPTIMISTICALLY. An accepted
//    receipt writes only the axes the operation named, as `sent`. A refusal -
//    including a timeout, and a receipt from a connection that has since died -
//    writes NOTHING: value and state stand exactly as they were. A number the
//    machine rejected therefore never becomes a durable value a later connect
//    would push back onto the machine, and there is nothing to roll back
//    because nothing was ever put there to begin with.
//  - THE CONNECT-TIME RESTORE TAKES THE SAME SLOT and skips, with one console
//    line, when an operator write already holds it.
//
// The UI reads `machineWorkOffsetWriteInFlight` and disables every offset
// control while it is true, so the refusal above is the backstop for the
// same-render window rather than the operator's normal experience.

const workOffsetWritesInFlight = new Set<string>()
const workOffsetWriteListeners = new Set<() => void>()

// WORK_OFFSET_WRITE_BUSY lives in operatorAuthority.ts (WO-1992).

export function machineWorkOffsetWriteInFlight(machineId: string): boolean {
  return workOffsetWritesInFlight.has(machineId)
}

export function subscribeMachineWorkOffsetWrite(listener: () => void): () => void {
  workOffsetWriteListeners.add(listener)
  return () => {
    workOffsetWriteListeners.delete(listener)
  }
}

function setWorkOffsetWriteInFlight(machineId: string, inFlight: boolean): void {
  if (workOffsetWritesInFlight.has(machineId) === inFlight) return
  if (inFlight) workOffsetWritesInFlight.add(machineId)
  else workOffsetWritesInFlight.delete(machineId)
  for (const listener of workOffsetWriteListeners) listener()
}

function refuseOverlappingWorkOffsetWrite(): void {
  store().pushConsole('tx', WORK_OFFSET_WRITE_BUSY, 'error')
}

function refusedWorkOffsetWrite(wcs: WcsId, reason: string): void {
  store().pushConsole('rx', `The machine would not set the ${wcs} work offset - ${reason}.`, 'error')
}

interface AuthoritativeReportedWorkOffset {
  receiptToken: BackendReceiptToken
  offset: MachinePosition
}

const authoritativeReportedWorkOffsets = new Map<string, AuthoritativeReportedWorkOffset>()

function reportedWorkOffsetKey(machineId: string, wcs: WcsId): string {
  return `${machineId}:${wcs}`
}

function rememberAuthoritativeReportedWorkOffset(
  machineId: string,
  wcs: WcsId,
  offset: MachinePosition,
  receiptToken: BackendReceiptToken,
): void {
  authoritativeReportedWorkOffsets.set(reportedWorkOffsetKey(machineId, wcs), {
    receiptToken,
    offset: { ...offset },
  })
}

/** UCCNC raises a successful offset receipt through the live-report event
 * before the awaiting session continuation can reject stale authority. Undo
 * that publication when its controller session was replaced, but preserve a
 * row already confirmed by a newer physical session. */
function clearStaleReportedWorkOffset(machineId: string, wcs: WcsId): void {
  const authority = authoritativeReportedWorkOffsets.get(reportedWorkOffsetKey(machineId, wcs))
  if (authority && receiptIsCurrent(authority.receiptToken)) {
    store().applyOffset({
      label: wcs,
      values: machinePositionValues(authority.offset),
    })
    return
  }
  useMachineControl.setState((state) => {
    const offsets = { ...state.offsets }
    delete offsets[wcs]
    return { offsets }
  })
}

function offsetAxisKey(axis: ControlAxis): keyof MachinePosition {
  return axis.toLowerCase() as keyof MachinePosition
}

/** The operation that has taken the slot but has not been sent yet. It lives
 *  for one tick only, which is exactly long enough for the axes of one
 *  synchronous multi-axis pass to land in one intent. */
interface OpenWorkOffsetWrite {
  machineId: string
  wcs: WcsId
  controller: MachineController
  /** true when this backend has no typed intent and takes G-code text. */
  text: boolean
  values: Partial<MachinePosition>
  axes: ControlAxis[]
  revision: number
  generation: BackendGenerationToken | null
  /** WO-2042: told once how the receipt ended - true only when the machine
   *  took the values. A caller that recorded something against the write
   *  (a tool length, the Ref's new reading) takes it back on false. */
  settled: Array<(accepted: boolean) => void>
}

let openWorkOffsetWrite: OpenWorkOffsetWrite | null = null
/** WO-2042: while set, told of every write `requestWorkOffsetValue` opens or
 *  joins - how the guided M6 measure learns which receipt its apply awaits. */
let workOffsetWriteWatch: ((write: OpenWorkOffsetWrite) => void) | null = null

/** Join the operation this tick already opened, or open one and take this
 *  machine's single offset-write slot. `null` = the slot is held; refuse. */
function joinOrOpenWorkOffsetWrite(
  machineId: string,
  wcs: WcsId,
  axis: ControlAxis,
  value: number,
  controller: MachineController,
  text: boolean,
): OpenWorkOffsetWrite | null {
  const open = openWorkOffsetWrite
  if (open) {
    const joinable = open.machineId === machineId
      && open.wcs === wcs
      && open.controller === controller
      && open.revision === connectionRevision
      && backendGenerationIsCurrent(open.generation)
    if (!joinable) return null
    open.values[offsetAxisKey(axis)] = value
    if (!open.axes.includes(axis)) open.axes.push(axis)
    return open
  }
  if (machineWorkOffsetWriteInFlight(machineId)) return null
  const write: OpenWorkOffsetWrite = {
    machineId,
    wcs,
    controller,
    text,
    values: { [offsetAxisKey(axis)]: value },
    axes: [axis],
    revision: connectionRevision,
    generation: captureBackendGeneration(controller),
    settled: [],
  }
  openWorkOffsetWrite = write
  setWorkOffsetWriteInFlight(machineId, true)
  queueMicrotask(() => { void sendWorkOffsetWrite(write) })
  return write
}

/** The typed intent (WO-1041). The receipt echoes the whole WCS, so only the
 *  axes this operation named take provenance from it - the others may be a
 *  profile-less bridge's defaults. */
async function sendWorkOffsetIntent(
  write: OpenWorkOffsetWrite,
): Promise<Partial<MachinePosition> | null> {
  const receipt = await write.controller.setWorkOffset!(write.wcs, write.values)
  if (write.revision !== connectionRevision || !backendGenerationIsCurrent(write.generation)) {
    if (receipt.ok && receipt.offset) clearStaleReportedWorkOffset(write.machineId, write.wcs)
    return null
  }
  if (!receipt.ok || !receipt.offset) {
    refusedWorkOffsetWrite(write.wcs, receipt.reason ?? 'the bridge returned no offset receipt')
    return null
  }
  rememberAuthoritativeReportedWorkOffset(
    write.machineId,
    write.wcs,
    receipt.offset,
    { backend: write.generation, revision: write.revision },
  )
  // The echo is the whole WCS as the bridge now holds it, read on the same
  // thread that applied the write. Only the axes THIS operation named may take
  // provenance from it, which is what the caller selects below.
  return selectOffsetAxes(receipt.offset, write.values)
}

/** The compatibility route for a backend with no typed intent: ONE acknowledged
 *  `G10 L2` line carrying every axis of this operation. */
async function sendWorkOffsetText(
  write: OpenWorkOffsetWrite,
): Promise<Partial<MachinePosition> | null> {
  const p = WCS_SLOTS.indexOf(write.wcs) + 1
  const words = write.axes
    .map((axis) => `${axis}${Number(write.values[offsetAxisKey(axis)]!.toFixed(4))}`)
    .join(' ')
  // WO-1611: write.values are mm; with no units word this line is read in the
  // operator's held units, same defect class as the TLO's G43.1. G21 prefixes
  // the line and G20 restores after, whether or not the write is acknowledged.
  const inch = store().parserModal?.units === 'inch'
  const pending = sendAppCommandAwait(`${inch ? 'G21 ' : ''}G10 L2 P${p} ${words}`, write.controller)
  if (!pending) {
    refusedWorkOffsetWrite(write.wcs, 'the controller would not take the offset command')
    return null
  }
  const ack = await pending
  if (inch) sendAppCommand('G20', write.controller)
  if (write.revision !== connectionRevision || !backendGenerationIsCurrent(write.generation)) return null
  if (!ack.ok) {
    refusedWorkOffsetWrite(write.wcs, ack.message ?? 'the controller did not acknowledge it')
    return null
  }
  // An acknowledged line is the controller saying it took these values; there
  // is no echo to read on this route, so the acknowledged values are it.
  return { ...write.values }
}

/** Send the operation and let its RECEIPT be the only thing that writes the
 *  store. The slot is released however it ends. */
async function sendWorkOffsetWrite(write: OpenWorkOffsetWrite): Promise<void> {
  if (openWorkOffsetWrite === write) openWorkOffsetWrite = null
  let took = false
  if (write.revision !== connectionRevision || !backendGenerationIsCurrent(write.generation)) {
    settleWorkOffsetWrite(write, took)
    return
  }
  try {
    const accepted = write.text
      ? await sendWorkOffsetText(write)
      : await sendWorkOffsetIntent(write)
    if (!accepted) return
    storeWorkOffset(write.machineId, write.wcs, accepted, 'sent')
    for (const axis of write.axes) {
      markConfirmedWorkZero(write.wcs, axis, write.revision)
    }
    took = true
    write.controller.refreshState()
  } catch (error) {
    if (write.revision !== connectionRevision || !backendGenerationIsCurrent(write.generation)) return
    refusedWorkOffsetWrite(write.wcs, error instanceof Error ? error.message : 'the write failed')
  } finally {
    if (write.revision === connectionRevision && backendGenerationIsCurrent(write.generation)) {
      setWorkOffsetWriteInFlight(write.machineId, false)
    }
    settleWorkOffsetWrite(write, took)
  }
}

function settleWorkOffsetWrite(write: OpenWorkOffsetWrite, accepted: boolean): void {
  const listeners = write.settled.splice(0)
  for (const listener of listeners) listener(accepted)
}

/** Record a controller-confirmed work-zero write without letting an async
 * write from an old connection authorize its replacement session. */
function markWorkZeroSet(
  wcs: WcsId | null,
  axis: ControlAxis,
  revision = connectionRevision,
): void {
  if (wcs && revision === connectionRevision) {
    workZeroRevision[wcs][axis] = revision
    if (axis === 'Z') workZeroZSetAt.set(workZeroZSetKey(controlMachineId(), wcs), { at: Date.now(), revision })
    scheduleAwaitedOffsetsCheck()
  }
}

/** A work zero the MACHINE CONFIRMED for an operator action: it arms WO-1017's
 *  goto gate and it is the tool-change hold's Z receipt, both at once. Every
 *  confirmed operator zero records here - the shared writer, the DRO and
 *  pendant zero, the pad cycle and the mesh cycle - so a route the hold lends
 *  the incoming Z to cannot write it and leave CYCLE START refusing it. */
function markConfirmedWorkZero(wcs: WcsId | null, axis: ControlAxis, revision: number): void {
  markWorkZeroSet(wcs, axis, revision)
  noteToolChangeZReceipt(wcs, axis, revision)
}

/** WO-2061: when each work offset's Z0 was last set (markWorkZeroSet), and
 *  in which connection - "which Z0 it will use and when it was set". Keyed by
 *  machine AND offset: Machine A's G54 is not Machine B's G54. */
const workZeroZSetAt = new Map<string, { at: number; revision: number }>()

function workZeroZSetKey(machineId: string, wcs: WcsId): string {
  return `${machineId}:${wcs}`
}

export interface WorkZeroZSetRecord {
  machineId: string
  wcs: WcsId
  /** Epoch ms the machine confirmed the write. */
  at: number
  /** False once the connection it was set in has ended. */
  thisConnection: boolean
}

/** WO-2061: the last confirmed work Z0 write for `wcs` on `machineId` (every
 *  confirmed route - Probe work Z0 on either screen, the DRO and pendant zero,
 *  the mesh), or null when none was confirmed on that machine since the page
 *  loaded. `thisConnection` is true only while that machine is the one
 *  connected, in the connection that wrote it. */
export function workZeroZSetRecord(machineId: string, wcs: WcsId | null): WorkZeroZSetRecord | null {
  const record = wcs ? workZeroZSetAt.get(workZeroZSetKey(machineId, wcs)) : undefined
  if (!wcs || !record) return null
  return {
    machineId,
    wcs,
    at: record.at,
    thisConnection: record.revision === connectionRevision && controlMachineId() === machineId,
  }
}

/** Refuse a semantic work-coordinate goto ONLY when it has no physical
 * destination: no machine datum on a commanded axis (WO-1017's switchless rule
 * inside that branch), or no active WCS at all. WO-1182 (Operator ruling 2026-09-03,
 * watching the screen): "if they're there, you obey them" - the value the
 * controller reports is the value obeyed. There is no "has not reported" and
 * no live-vs-retained "disagree" refusal any more; the reconcile at connect
 * pushes this software's number and says so in the console. Ordinary jogs
 * deliberately never call this: jogging is how the operator reaches the place
 * they intend to zero. */
export function workGotoZeroRefusal(axes: readonly ControlAxis[]): string | null {
  const datum = currentResolvedMachineMotion().datum.axes
  const wcs = store().activeWcs
  const missingDatum = axes.filter(
    (axis) => {
      const key = axis.toLowerCase()
      return (key === 'x' || key === 'y' || key === 'z') && !datum[key].known
    },
  )
  if (missingDatum.length > 0) {
    // Switched machines retain the established homing refusal downstream.
    // A truly switchless machine may still work after setting these axes in
    // this connection, as WO-1017 requires.
    if (!activeMachineHasNoHomeSwitches()) return null
    if (!wcs) return `select the active work offset and set the work zero for ${describeAxisList(axes)} here first.`
    const missingSessionZero = axes.filter(
      (axis) => workZeroRevision[wcs][axis] !== connectionRevision,
    )
    if (missingSessionZero.length > 0) {
      return `set the ${wcs} work zero for ${describeAxisList(missingSessionZero)} here first.`
    }
    return null
  }

  if (!wcs) return 'select the active work offset first.'
  return null
}

interface RunFromReviewSnapshot {
  revision: number
  source: 'step-back' | null
  plan: RunFromLinePlan | null
  error: string | null
}

let runFromReviewValue: RunFromReviewSnapshot = {
  revision: 0,
  source: null,
  plan: null,
  error: null,
}
const runFromReviewListeners = new Set<() => void>()
let stepBackInProgressValue = false
const stepBackInProgressListeners = new Set<() => void>()

/** External run-from review state lets transport-row actions reuse the
 * Program panel's canonical plan/error surfaces without moving that state
 * into the broad machine store. */
export function runFromReview(): RunFromReviewSnapshot {
  return runFromReviewValue
}

export function subscribeRunFromReview(listener: () => void): () => void {
  runFromReviewListeners.add(listener)
  return () => runFromReviewListeners.delete(listener)
}

/** True for the entire Step Back authority window, including Hold settle,
 * reset, Idle verification, final cursor planning, and re-arm. Transport
 * gestures and Single Block mode changes fail closed while this is true. */
export function stepBackInProgress(): boolean {
  return stepBackInProgressValue
}

export function subscribeStepBackInProgress(listener: () => void): () => void {
  stepBackInProgressListeners.add(listener)
  return () => stepBackInProgressListeners.delete(listener)
}

function setStepBackInProgress(inProgress: boolean): void {
  if (stepBackInProgressValue === inProgress) return
  stepBackInProgressValue = inProgress
  for (const listener of stepBackInProgressListeners) listener()
}

function publishRunFromReview(
  source: RunFromReviewSnapshot['source'],
  plan: RunFromLinePlan | null,
  error: string | null,
): void {
  runFromReviewValue = {
    revision: runFromReviewValue.revision + 1,
    source,
    plan,
    error,
  }
  for (const listener of runFromReviewListeners) listener()
}

function clearRunFromReview(): void {
  chosenStartLostAtEpoch = null
  if (runFromReviewValue.source === null && !runFromReviewValue.plan && !runFromReviewValue.error) return
  publishRunFromReview(null, null, null)
}

function store() {
  return useMachineControl.getState()
}

/** WO-2686: the arm epoch at which a connection boundary destroyed a start the
 *  operator chose - a Step Back review (or one in flight), a kept stop, a held
 *  program, a run from line N armed and not yet run. Null when none was lost. */
let chosenStartLostAtEpoch: number | null = null
/** WO-2686: the arm epoch at which the controller held the program or a run
 *  from line N was armed, until the next job event; null when neither stands.
 *  Session facts, not the store's job phase a test or a late progress report
 *  can repaint. */
let chosenStartAtEpoch: number | null = null

/** WO-2686: a loaded program runs from line 1 on CYCLE START "unless I have
 *  told it to do otherwise" (the operator, 10-08). When the operator HAD told it
 *  otherwise and a disconnect/reconnect destroyed that choice, CYCLE START
 *  does not put line 1 in its place: the program reads unarmed exactly as
 *  before WO-2686 until he loads, re-arms or chooses a line again. */
export function operatorChosenStartLost(): boolean {
  return chosenStartLostAtEpoch !== null && chosenStartLostAtEpoch === armEpochValue
}

function operatorHasChosenStart(): boolean {
  return runFromReviewValue.source === 'step-back' || stepBackInProgressValue || keptStop !== null
    || chosenStartAtEpoch === armEpochValue
}

/** One snapshot of the authority pinned by WO-1147 and the live backend facts
 * published by the current controller. Every non-React motion guard reads this
 * function instead of choosing an envelope source for itself. */
export function currentResolvedMachineMotion(): ResolvedMachineMotion {
  const control = store()
  const controllerDatum = controller?.homedThisSession()
    ? true
    : controller?.homedAxesThisSession?.()
  return resolveMachineMotion({
    machine: controlMachine(useCamStore.getState()),
    connectionKind: control.connectionKind,
    settings: control.settings,
    datumKnown: controllerDatum ?? control.homed,
  })
}

type JobLifecycleEvent = 'started' | 'paused' | 'resumed' | 'stopped' | 'completed' | 'failed'

function applyJobLifecycleEvent(event: JobLifecycleEvent, fault: JobFault | null): void {
  // WO-1275: a job that paused, stopped, failed or finished has no staged
  // motion left worth releasing. Dropping the pending release first means the
  // gate can never start a cut on the far side of a terminal edge.
  if (event !== 'started' && event !== 'resumed') cancelSpindleSpeedWait()
  // WO-1330: the tool-change hold is entered by the boundary itself, AFTER
  // this call raises `paused`; every other edge ends it. Resumed, started,
  // stopped, failed and completed all mean the operator is no longer standing
  // at a stopped spindle with a tool in their hand, so jog and the Z zero go
  // back behind the paused-program rule they were lent from.
  if (event !== 'paused') endToolChangeSequence()
  if (controller && event === 'paused') stopGeometryProgramSpindle(controller)
  if (controller && (event === 'completed' || event === 'stopped' || event === 'failed')) {
    // WO-2668: a program's end can switch outputs the file never named.
    scheduleOutputPinRefresh()
    stopGeometryProgramSpindle(controller)
    geometryProgramSpindle = null
    // A program that ended never releases its first motion again, so its
    // preamble coolant is retired with it rather than left armed.
    geometryProgramCoolant = null
  }
  // WO-2521: the T words a program ran select, for a later bare M6.
  if (controller) selectToolWordsTheProgramRan(controller, event)
  if (event === 'started') publishNonProgramActionStatus(null)
  store().applyJobEvent(event, fault)
  // WO-2237: a return from a kept stop that has run to its end, or failed, is
  // spent; the program ends as any program does.
  if ((event === 'completed' || event === 'failed') && keptStop?.resumed && keptStop.controller === controller) {
    keptStop = null
  }
  const mdiOverProgram = mdiLineOverLoadedProgram(controller)
  if (mdiOverProgram) {
    // WO-2234: the job name still reads as the loaded program; the cycle log
    // row is the MDI line's, named as the line and in no operation of the file.
    const label = programUnderMdiLine!.label
    useMachineControl.setState((s) => ({
      cycleEvents: s.cycleEvents.map((row, i) => (
        i === s.cycleEvents.length - 1 ? { ...row, name: label, operation: null } : row
      )),
    }))
    if (event === 'completed' || event === 'stopped' || event === 'failed') endMdiLineOverFile(controller)
  }
  // WO-1663: a start or a fault ends the operator-stop report; the operator's
  // own Stop publishes it and stages the file again from the top. WO-2234: an
  // MDI line's start or fault is not the program's, as a jog's is not.
  if (!mdiOverProgram && (event === 'started' || event === 'failed')) clearOperatorStop()
  if (event === 'stopped' && controller) takeOperatorStop(controller)
  if (event === 'started') beginPathFidelityRun()
  if (event === 'completed' || event === 'stopped' || event === 'failed') {
    finishPathFidelityRun()
  }
  if (event === 'started' || event === 'stopped') clearRunFromReview()
  // WO-2686: a hold is a start the operator will resume; every other edge ends it.
  chosenStartAtEpoch = event === 'paused' ? armEpochValue : null
  if (event === 'started') wcsScanSourceLine = 0
}

/** WO-2256: the job's counts and cursor as the controller reported them for
 *  the staged program. The store's `job` reads a resumed run's remainder as
 *  the file (`StagedNumbering`); progress handed back to the controller's own
 *  bookkeeping is built from these, never from the file's. */
function stagedJobCounts(): StagedJobCounts {
  const s = store()
  return s.stagedNumbering === null ? s.job : s.stagedJob
}

function wholeProgramProgress(progress: StreamerProgress): StreamerProgress {
  if (programPartsTerminal?.controller === controller) {
    // A ready/running phase can only belong to a newly loaded controller job.
    // This also keeps direct contract callers from inheriting a prior parts
    // run's terminal snapshot when they bypass the two session load doors.
    if (progress.phase === 'ready' || progress.phase === 'streaming' || progress.phase === 'paused') {
      programPartsTerminal = null
      return progress
    }
    return programPartsTerminal.progress
  }
  const run = programPartsRun
  if (!run || run.controller !== controller) return progress
  const betweenParts = run.started && (
    progress.phase === 'ready'
    || progress.phase === 'empty'
    || (progress.phase === 'complete' && run.partIndex < run.parts.length - 1)
  )
  const previous = stagedJobCounts()
  // WO-1662: a whole-queue backend (UCCNC's geometry queue) reports a freshly
  // loaded, not-yet-started part as fully sent at once (`sentLines` and
  // `totalLines` are the same field on that backend's own jobProgress() before
  // its first press) - the proof operatorTransport's noBlockInFlight reads
  // that nothing is executing. Rescaling only `sentLines` to the WHOLE
  // program's total here left it stuck at the current part's own count, so
  // that proof failed for every part but the last: CYCLE START read a
  // just-loaded part as "a block still in flight" and stayed greyed under
  // Single Block before the first press, on any program long enough to split.
  // Scoped to `phase === 'ready'` (not yet started) only: a part actually
  // streaming reports the same sent-equals-total shape throughout on this
  // backend (WO-1662: `jobProgress()`'s normal branch, not only its ready
  // one), and forcing the whole-program figure there erased the
  // acked-catches-sent edge `publishJobProgress` uses to push a part-boundary
  // jump past its render throttle - the regression an earlier version of this
  // fix caused in WO-1267's part-boundary test.
  const partReadyAndFullySent = progress.phase === 'ready' && progress.sentLines === progress.totalLines
  return {
    ...progress,
    phase: betweenParts ? (run.heldBetweenParts ? 'paused' : 'streaming') : progress.phase,
    totalLines: run.totalMoves,
    sentLines: partReadyAndFullySent
      ? run.totalMoves
      : Math.min(run.totalMoves, run.completedMoves + progress.sentLines),
    ackedLines: Math.min(run.totalMoves, run.completedMoves + progress.ackedLines),
    ackedSourceLine:
      run.completedMoves > 0 && progress.ackedSourceLine === 0
        ? previous.ackedSourceLine
        : progress.ackedSourceLine,
    sentSourceLine:
      run.completedMoves > 0 && progress.sentSourceLine === 0
        ? previous.sentSourceLine
        : progress.sentSourceLine,
  }
}

/**
 * WO-1273: translate the geometry controller's live move id into the
 * line-shaped progress the Program panel already renders.
 *
 * The bridge hands the whole queue over at load time, so its pushed count is
 * not execution progress. `executingMoveId` is execution truth: staged moves
 * run in order, and the loaded part preserves the program's ids. The executing
 * move itself is not complete, hence its zero-based position is the number of
 * completed moves. At the bridge-declared terminal edge every move in this
 * part is complete; that same terminal value is also used by the part-advance
 * gate below so the readout and the splitter cannot disagree.
 *
 * A missing or foreign id returns null. The caller then leaves the last proven
 * count standing instead of fabricating motion from a buffer value.
 */
/** Board, 2026-09-14 (WO-1530): Single Block on a geometry bridge sends no
 *  jobEvent between blocks, so the only proof a stepped block FINISHED is a
 *  `run` frame after the step followed by rest. Keyed to the armed program so a
 *  new load starts clean; cleared at every start and step. */
const geometryStepMotionSeen = new WeakMap<object, boolean>()

function geometryPartProgress(
  ctrl: MachineController,
  status: MachineStatus | null,
  terminal: boolean,
): StreamerProgress | null {
  if (
    ctrl !== controller
    || ctrl.capabilities.gcodeText
    || ctrl.capabilities.executingMoveId !== true
    || pathFidelityArmed?.kind !== 'geometry'
  ) return null

  const run = programPartsRun?.controller === ctrl ? programPartsRun : null
  // The lifecycle channel already reconciles a geometry job to N/N when the
  // bridge declares it completed. Its independently polled status channel can
  // arrive afterward with Idle plus the final executing id still present. That
  // id means "the final move was the last one observed", not "the final move is
  // still in flight"; translating it again would regress COMPLETE 158/158 to
  // READY 157/158. A newly loaded or started job first replaces the store phase
  // with ready/streaming, so this protects only the terminal snapshot. Multipart
  // boundaries remain streaming through wholeProgramProgress and still advance.
  if (!terminal && ((!run && store().job.phase === 'complete') || run?.completionSignaled)) return null
  const part = run?.parts[run.partIndex]
  const moves = part ? part.steps.filter(isStagedMove) : pathFidelityArmed.moves
  const base = ctrl.jobProgress()
  if (terminal) {
    return {
      ...base,
      phase: 'complete',
      totalLines: moves.length,
      sentLines: moves.length,
      ackedLines: moves.length,
    }
  }

  const executingId = status?.executingMoveId
  if (executingId === null || executingId === undefined || executingId === 0) return null
  // WO-1549 (board 2026-09-14, item 8): AN EXECUTING ID IS NOT EXECUTION
  // PROGRESS UNTIL THIS PROGRAM HAS ACTUALLY MOVED.
  //
  // Move ids are minted per program (buildMachineProgram numbers a 6-move
  // program 1..6), and the board keeps its last executing id until new motion.
  // So the first status frame after a load still carries the PREVIOUS job's
  // id, and looked up in the new program's move list it repaints that many
  // moves as done - the "5/6 (83%)" the operator saw before any press, which
  // only reset on the first Single Block step. The controller's own
  // `jobProgress()` already answers 0/N for a loaded, unstarted job (WO-1530
  // build 3); this translation was the second door around it.
  //
  // `geometryStepMotionSeen` is this program's own witness (set on a `run`
  // frame, cleared at every start/step and by the fresh arming object a load
  // installs): until it is true the frame's id says nothing about the new
  // program, so defer to the controller's counters and translate nothing.
  if (geometryStepMotionSeen.get(pathFidelityArmed) !== true) return null
  // WO-1323 readout follow-up (measured on the board 2026-09-11: stage 2 of a
  // two-setup program read 159/311 for its whole run, then jumped to 311/311).
  // A part's index numbers its moves from the part's OWN start for a
  // multi-setup stage (multiSetupProgram.ts resets sectionStart per stage) and
  // from the WHOLE program's start for a capacity-split part (WO-1054). The
  // ordinal is therefore only a shortcut: it is trusted when it lands on the
  // move that carries this id, and the part's own step list decides otherwise.
  const indexed = part?.index[executingId]
  const byOrdinal = indexed && 'moveOrdinal' in indexed && run
    ? indexed.moveOrdinal - run.completedMoves
    : -1
  const executingIndex = byOrdinal >= 0 && moves[byOrdinal]?.id === executingId
    ? byOrdinal
    : moves.findIndex((move) => move.id === executingId)
  if (executingIndex < 0) return null
  // The executing id names the move in flight while the board runs. Under
  // Single Block, once the step has actually run (a `run` frame since the step)
  // and the board is back at rest with an empty buffer, that move is DONE - the
  // board frames showed idle/buffer 0/exec 6 after the last block, which read
  // 5 of 6 and kept offering a block that stepJob then refused.
  const stepFinished = ctrl.singleBlockMode()
    && (status?.state === 'idle' || status?.state === 'hold')
    && status?.buffer?.moves === 0
    && geometryStepMotionSeen.get(pathFidelityArmed) === true
  return {
    ...base,
    totalLines: moves.length,
    sentLines: moves.length,
    ackedLines: stepFinished ? Math.min(moves.length, executingIndex + 1) : executingIndex,
    ackedSourceLine: executingId,
    sentSourceLine: executingId,
  }
}

function endProgramParts(
  reason: string,
  event: 'stopped' | 'failed',
  fault: JobFault | null,
  consoleSeverity: 'info' | 'error',
  suppressNextControllerTerminal = true,
  progressBeforeStop?: StreamerProgress,
): void {
  const run = programPartsRun
  if (!run) return
  // WO-1663: THE OPERATOR'S OWN STOP is not a failed cycle. It keeps the count
  // they saw when they pressed it (the controller has zeroed its own by now)
  // and says so; every other end - a fault, an alarm, a reset nobody asked
  // for, the E-STOP - still ends in 'failed' as before.
  const operatorStop = event === 'stopped' && operatorStopPending?.controller === run.controller
    ? operatorStopPending
    : null
  const terminalProgress = operatorStop
    ? {
        phase: 'empty' as const,
        totalLines: run.totalMoves,
        sentLines: operatorStop.stagedAckedMoves ?? operatorStop.ackedMoves,
        ackedLines: operatorStop.stagedAckedMoves ?? operatorStop.ackedMoves,
        ackedSourceLine: stagedJobCounts().ackedSourceLine,
        sentSourceLine: stagedJobCounts().sentSourceLine,
        bytesInFlight: 0,
      }
    : wholeProgramProgress(progressBeforeStop ?? run.controller.jobProgress())
  clearProgramClampPauseForRun(run)
  programPartsRun = null
  programPartsTerminal = {
    controller: run.controller,
    progress: {
      ...terminalProgress,
      phase: operatorStop ? 'empty' : 'failed',
      totalLines: run.totalMoves,
      bytesInFlight: 0,
    },
    suppressNextControllerTerminal,
  }
  const said = operatorStop ? describeOperatorStop(operatorStop) : reason
  store().setProgramReadiness({ ready: false, reason: said })
  // Lifecycle and operator severity are separate decisions: a safety refusal
  // can end the lifecycle as "stopped" while its console row must remain red.
  // WO-2563: the stop/reset that makes room for a command in a pause ends
  // this staging, not the operator's program. Keep its lifecycle and re-arm
  // unchanged; takeKeptStop announces the kept place instead. Operator Stop
  // clears the taking state first, and faults/refusals still speak here.
  const keepingPause = event === 'stopped' && consoleSeverity === 'info'
    && operatorStop === null && keptStopTakingFor(run.controller)
  if (!keepingPause) store().pushConsole('rx', said, consoleSeverity)
  store().applyJobProgress(programPartsTerminal.progress)
  applyJobLifecycleEvent(event, fault)
}

function failProgramParts(reason: string): void {
  const run = programPartsRun
  if (!run) return
  const completed = run.completedMoves
  clearProgramClampPauseForRun(run)
  programPartsRun = null
  store().setProgramReadiness({ ready: false, reason })
  store().pushConsole('rx', reason, 'error')
  const terminalProgress: StreamerProgress = {
    phase: 'failed',
    totalLines: run.totalMoves,
    sentLines: completed,
    ackedLines: completed,
    ackedSourceLine: stagedJobCounts().ackedSourceLine,
    sentSourceLine: stagedJobCounts().sentSourceLine,
    bytesInFlight: 0,
  }
  programPartsTerminal = {
    controller: run.controller,
    progress: terminalProgress,
    suppressNextControllerTerminal: false,
  }
  store().applyJobProgress(terminalProgress)
  applyJobLifecycleEvent('failed', { code: null, message: reason, line: null, moveId: null })
}

/**
 * WO-1874: A PROGRAM THE BOARD REFUSED IS NEVER RUN AS THE OLD PROGRAM.
 *
 * The bridge answers `loadMoves` with `{ok, reason}` and refuses WITHOUT
 * touching what it has staged - so a refused load leaves the PREVIOUS program
 * on the board. The app used to discard that answer entirely (`fireAndForget`),
 * arm the NEW program's cuts and parts, and let Cycle Start run whatever was
 * staged before (WO-1835 Finding 1, motion hazard, docs/audits/
 * CONTROL-PATH-ADMISSION-2026-09-22.md).
 *
 * WHY THIS IS A CONTINUATION RATHER THAN AN AWAITED LOAD. The staging paths
 * hand the program over synchronously and every backend's `loadProgram` answers
 * synchronously; the board's answer arrives a moment later on the same socket
 * the status frames use. Waiting for it would make an UNANSWERED load - a link
 * that goes quiet, an older bridge that says nothing about this call - mean
 * "not loaded", which is a refusal the software would be inventing (rule 11)
 * and which is not what this order is for: it exists to stop the app ignoring a
 * refusal THE BOARD ALREADY MADE. So the arm happens as it always did, and an
 * explicit refusal takes it back. On the wire the bridge answers this call in
 * the same round trip it receives it - it stages in-process and replies - so
 * the take-back lands long before an operator's hand reaches Cycle Start, and
 * readiness is false from that moment on.
 */
interface BoardLoadVerdictSource {
  stagedLoadVerdict(): Promise<{ ok: boolean; reason: string | null }> | null
}

/** Read structurally rather than through `MachineController`: the verdict is a
 *  bridge-backend fact and `controller.ts` is outside this order's owned paths.
 *  A backend without one simply has no board answer to wait for. */
function boardLoadVerdict(
  ctrl: MachineController,
): Promise<{ ok: boolean; reason: string | null }> | null {
  const candidate = ctrl as Partial<BoardLoadVerdictSource>
  return typeof candidate.stagedLoadVerdict === 'function' ? candidate.stagedLoadVerdict() : null
}

/**
 * Watch the board's answer to the load just armed, and hand an explicit refusal
 * to `takeBack`. `stillOurs` is the caller's own "is this arm still the one I
 * made" question - a later load, a disconnect or a backend swap must not have
 * an older program's refusal reach in and disarm it.
 */
function watchBoardLoadRefusal(
  ctrl: MachineController,
  stillOurs: () => boolean,
  takeBack: (reason: string) => void,
): void {
  const verdict = boardLoadVerdict(ctrl)
  if (verdict === null) return
  const receiptToken = captureBackendReceipt(ctrl)
  void verdict.then((answer) => {
    if (answer.ok) return
    if (!receiptIsCurrent(receiptToken) || !stillOurs()) return
    takeBack(answer.reason ?? 'the controller refused this program without giving a reason.')
  })
}

/**
 * TAKE BACK AN ARM THE BOARD REFUSED (WO-1874).
 *
 * Nothing here is a new gate: it undoes the arming the staging path had already
 * done on the strength of "accepted for sending". The board is still holding
 * whatever it held, so the session holds no cuts, no parts, no spindle or
 * coolant intent and no path check for the program that never arrived, the
 * store stops naming it as loaded, and readiness carries the bridge's own words
 * - which is what refuses Cycle Start (`deriveOperatorTransport`).
 */
function disarmRefusedProgramLoad(ctrl: MachineController, reason: string): void {
  if (programPartsRun?.controller === ctrl) programPartsRun = null
  if (programPartsTerminal?.controller === ctrl) programPartsTerminal = null
  // Back to the conservative answer: an unknown staged list waits for the
  // spindle (see `stagedMotionCuts`).
  stagedMotionCuts = true
  geometryProgramSpindle = null
  geometryProgramCoolant = null
  clearPathFidelity()
  const said = `The machine refused this program, so it is NOT loaded: ${reason} `
    + 'The board is still holding whatever it held before.'
  store().setProgram(null, null, [], null)
  store().applyJobProgress(ctrl.jobProgress())
  store().setProgramReadiness({ ready: false, reason: said })
  sayLoadRefusedOnce(reason, said)
  bumpArmEpoch()
  // WO-2655: the board refused because the job before is still executing. That
  // job's end is the only thing that settles the screen now, and the arming that
  // would have published it was the refused program's - so watch for it here.
  jobUnderRefusedLoad = ctrl.hasActiveJob() ? { controller: ctrl } : null
}

/** WO-2655: ONE console line for one refused load. The bridge controller has
 *  already written the call's own row (`loadMoves: <reason>`); the session's
 *  plain sentence takes that row's place rather than repeating it beneath. */
function sayLoadRefusedOnce(reason: string, said: string): void {
  const callRow = `loadMoves: ${reason}`
  const last = store().consoleLines.at(-1)
  if (last?.dir !== 'rx' || last.text !== callRow) {
    store().pushConsole('rx', said, 'error')
    return
  }
  const merged = 'The machine refused this program, so it is NOT loaded and the board still holds '
    + `what it held before. ${callRow}`
  useMachineControl.setState((s) => ({
    consoleLines: s.consoleLines.map((row) => (row.id === last.id ? { ...row, text: merged, severity: 'error' } : row)),
  }))
}

/**
 * WO-2655: THE JOB A REFUSED LOAD LEFT RUNNING, until it ends.
 *
 * Rehearsal row z2c (2026-10-07): an MDI line's status read stalled, Load passed
 * `controllerJobReallyRuns` on the stale idle frame, and the bridge refused it -
 * "the board is still cutting the previous part". The take-back republished the
 * controller's progress for that still-active line (streaming, 1/1) and cleared
 * the refused program's arming, which was the only channel a geometry job's
 * terminal edge publishes its phase through. The line then completed and
 * nothing moved the store off streaming: Control read Running, the MDI box
 * locked and 99% for 8 minutes over an idle machine with nothing loaded.
 */
let jobUnderRefusedLoad: { controller: MachineController } | null = null

/** The job a refused load left running has ended: the store reads the board's
 *  own answer for it, never streaming over a controller with no active job.
 *
 *  Fix round (machine-seat kit row zhs, 10-07): the held frames flushed AFTER
 *  the refusal and carried that same MDI line's own `started` edge. A `started`
 *  is therefore not a new job, and it leaves the watch for the job's terminal edge.
 *
 *  Fix round 2 (audit 10-07 11:25): the watch no longer retires on an arm-epoch
 *  bump - a second Load the SESSION refuses (soft limit, unknown word, empty
 *  file, bad arc) bumps the epoch with nothing sent, and the job's completion
 *  then left Control on Running. A newer job cannot be overwritten here: the
 *  settle acts only while the store reads streaming/paused AND the controller
 *  reports no active job, which a newer armed or running job never does. */
function settleJobUnderRefusedLoad(ctrl: MachineController, event: JobLifecycleEvent): void {
  const watch = jobUnderRefusedLoad
  if (watch?.controller !== ctrl) return
  if (event !== 'completed' && event !== 'stopped' && event !== 'failed') return
  jobUnderRefusedLoad = null
  const phase = store().job.phase
  if ((phase !== 'streaming' && phase !== 'paused') || ctrl.hasActiveJob()) return
  const progress = ctrl.jobProgress()
  store().applyJobProgress(
    event === 'completed' && progress.totalLines > 0
      ? { ...progress, phase: 'complete', ackedLines: progress.totalLines }
      : progress,
  )
}

/** WO-2655 fix round (machine-seat kit row zhs, 10-07): Control read Running
 *  over a controller that reported no active job, and Stop/Reset sent its reset
 *  and changed nothing on screen. Read at the press, before the board is told:
 *  a run the controller itself has (or a parts run the session ends on the
 *  reset) is not stale and keeps its own ending. */
function runReadsOverIdleController(ctrl: MachineController): boolean {
  const phase = store().job.phase
  return (phase === 'streaming' || phase === 'paused')
    && !ctrl.hasActiveJob()
    && programPartsRun?.controller !== ctrl
}

/** Stop/Reset over such a stale run: the store takes the controller's own
 *  answer, unless the session's own stop handling already published one. */
function endStaleRunAtStopReset(ctrl: MachineController): void {
  if (!runReadsOverIdleController(ctrl)) return
  if (jobUnderRefusedLoad?.controller === ctrl) jobUnderRefusedLoad = null
  store().applyJobProgress(ctrl.jobProgress())
}

/**
 * WO-2667: THE BOARD'S OWN END OF A JOB SETTLES THE SCREEN.
 *
 * Machine seat 10-07 8:00 PM: Stop/Reset during the "Park 4" macro's Z leg. The
 * bridge sent `stopped` and then Idle, yet Control stayed Running, MDI locked,
 * until a second press. A geometry job's phase leaves streaming only through
 * `geometryPartProgress`, which needs a status frame naming one of the job's
 * moves after this job was seen moving; a stop that lands before the first run
 * frame (or a board that reports no executing id after it) never gets one, and
 * `stopped`/`failed` themselves publish no phase. So at the board's terminal
 * edge, a store still reading streaming/paused over a controller with no active
 * job takes the controller's own answer - the answer Stop/Reset over a stale
 * run already takes (`endStaleRunAtStopReset`). Read after the lifecycle edge,
 * which logs the job's last cursor. A parts run ends through
 * `handleProgramPartJobEvent` before this is reached, and a kept stop re-arms
 * its own program, so both keep their own ending.
 */
function settleRunAtTerminalEdge(ctrl: MachineController, event: JobLifecycleEvent): void {
  if (event !== 'stopped' && event !== 'failed' && event !== 'completed') return
  if (ctrl !== controller || keptStopTakingFor(ctrl) || !runReadsOverIdleController(ctrl)) return
  // Only the phase is the controller's: the counts stay the last ones proven
  // (WO-1273 - an operator-stopped job keeps reading 2/4, not 0/4).
  const current = stagedJobCounts()
  const complete = event === 'completed' && current.totalLines > 0
  store().applyJobProgress({
    phase: complete ? 'complete' : ctrl.jobProgress().phase,
    totalLines: current.totalLines,
    sentLines: current.sentLines,
    ackedLines: complete ? current.totalLines : current.ackedLines,
    ackedSourceLine: current.ackedSourceLine,
    sentSourceLine: current.sentSourceLine,
    bytesInFlight: 0,
  })
}

/**
 * AN ALARM THAT TOOK THE ARMED PROGRAM WITH IT (WO-2022).
 *
 * 8 AM rehearsal, 2026-09-26: two probes alarmed on the simulator with a
 * program loaded and not started. The simulator empties a staged program on
 * any alarm (`abandonProgram`), and for one that never started it raises no
 * job event and no progress - nothing ran, so there is no 'failed' edge. The
 * store went on reading 'ready' 0/N, the header said "CYCLE START begins the
 * program", and Cycle Start asked a controller that held nothing. The
 * controller's own job is the truth, so it is read here, at the alarm edge,
 * and the console says once where the program went and the way back.
 *
 * A file-door program is the session's to stage again: it still holds the
 * file (`toolpathProgramReload`), so it stages it itself - never "load it
 * again" (rule 11). Not while the alarm stands: at the first Idle after it
 * (`restageProgramDroppedByAlarm`), exactly as the operator's own Stop does.
 *
 * GRBL and the machine bridge keep an unstarted program through an alarm and
 * still report 'ready', so for them this reads 'ready' and changes nothing.
 */
function publishProgramDroppedByAlarm(
  ctrl: MachineController,
  publish: (progress: StreamerProgress) => void,
): void {
  const s = store()
  if (s.job.phase !== 'ready') return
  if (ctrl.hasActiveJob() || ctrl.jobProgress().phase !== 'empty') return
  if (programPartsRun?.controller === ctrl && !programPartsRun.started) programPartsRun = null
  publish(ctrl.jobProgress())
  // WO-2234: what the alarm cleared was an MDI line over the loaded program,
  // not the program - which is put back at the first Idle after the alarm.
  if (mdiLineOverLoadedProgram(ctrl)) {
    endMdiLineOverFile(ctrl)
    return
  }
  const name = s.job.name ?? 'the program'
  const reload = toolpathProgramReload
  const fileDoor = s.programText === null && reload !== null && reload.controller === ctrl && reload.name === s.job.name
  programDroppedByAlarm = fileDoor ? { controller: ctrl, reload } : null
  const wayBack = s.programText !== null
    ? 'so it is not armed - CYCLE START arms it again from line 1 and runs it'
    : fileDoor
      ? 'so the file is staged again from its first line as soon as the machine is back at Idle'
      : 'so it is not armed, and this session keeps no copy of it to stage again - send it to the machine again to run it'
  store().pushConsole(
    'rx',
    `The alarm cleared "${name}" from the controller before it started, ${wayBack}.`,
    'error',
  )
}

/** A file-door program an alarm cleared before it started, waiting for Idle. */
let programDroppedByAlarm: { controller: MachineController; reload: ToolpathProgramReload } | null = null

/** WO-2022: the first Idle after the alarm stages the cleared file again from
 *  its first line - the same file, read against the offsets and position now
 *  in force. Anything that happened in between (another load, a disconnect, a
 *  program on the board) owns the screen and nothing is staged. */
function restageProgramDroppedByAlarm(ctrl: MachineController): void {
  const dropped = programDroppedByAlarm
  if (!dropped || dropped.controller !== ctrl) return
  // An Idle the machine cannot take a program at yet leaves it pending: the
  // E-STOP reset reports Idle before its latch clears, and the next Idle
  // after the latch clears is the one that stages it.
  if (
    ctrl.connectionPhase() !== 'connected'
    || ctrl.resetInProgress()
    || ctrl.machineState() !== 'idle'
    || estopNeedsReset()
  ) return
  programDroppedByAlarm = null
  const reload = dropped.reload
  const s = store()
  if (toolpathProgramReload !== reload || ctrl.hasActiveJob()) return
  if (s.programText !== null || s.job.name !== reload.name || s.job.phase !== 'empty') return
  loadGcodeTextToolpathProgram(reload.name, reload.text, {
    publishListing: reload.publishListing,
    runThroughOffsetChanges: reload.runThroughOffsetChanges,
    loadLine: () => `"${reload.name}" is staged again from its first line. CYCLE START runs it from the start.`,
  })
}

/** WO-2008: A PROGRAM REALLY RUNS, or it does not. The controller's active flag
 *  can outlive a job whose 'completed' edge never reached us; the board then
 *  reads idle with every move acknowledged, and "the program is still running"
 *  is false. Only that exact picture (idle AND every move done, motion seen)
 *  is a leftover - a job in Hold, mid-buffer or just started is running. */
function controllerJobReallyRuns(ctrl: MachineController): boolean {
  if (!ctrl.hasActiveJob()) return false
  if (ctrl.machineState() !== 'idle') return true
  const progress = ctrl.jobProgress()
  return !(progress.totalLines > 0 && progress.ackedLines >= progress.totalLines)
}

/** The controller's active flag drops between staged parts even though the
 * operator's program is still running. Manual command doors must treat that
 * controller-idle handoff as part of the same job. */
function hasActiveProgramJob(ctrl: MachineController): boolean {
  return ctrl.hasActiveJob()
    || (programPartsRun?.controller === ctrl && programPartsRun.started)
}

/** Feed Hold can arrive after a part has reported complete but before the next
 * controller-sized part is loaded. The controller is idle in that window, so
 * its ordinary feedHold() has nothing to pause. Keep the operator's one program
 * paused in the session instead; Cycle Resume releases this exact boundary. */
function holdProgramPartsBetweenParts(ctrl: MachineController): boolean {
  const run = programPartsRun
  if (
    !run
    || run.controller !== ctrl
    || !run.completionSignaled
    || run.advancing
    || run.heldBetweenParts
    || ctrl.connectionPhase() !== 'connected'
    || ctrl.resetInProgress()
    || ctrl.machineState() !== 'idle'
  ) return false

  run.heldBetweenParts = true
  store().applyJobProgress({ ...wholeProgramProgress(ctrl.jobProgress()), phase: 'paused' })
  applyJobLifecycleEvent('paused', null)
  return true
}

function resumeProgramPartsBetweenParts(ctrl: MachineController): boolean {
  const run = programPartsRun
  if (!run || run.controller !== ctrl || !run.heldBetweenParts) return false
  if (
    ctrl.connectionPhase() !== 'connected'
    || ctrl.resetInProgress()
    || ctrl.machineState() !== 'idle'
  ) return false

  run.heldBetweenParts = false
  store().applyJobProgress({ ...wholeProgramProgress(ctrl.jobProgress()), phase: 'streaming' })
  applyJobLifecycleEvent('resumed', null)
  advanceProgramPartIfComplete()
  return true
}

/** Single Block at a held boundary means the first line of the next part is
 * the next block. Release the session hold, load that part, and enter it
 * through the controller's step door so no later line streams past the mode. */
function stepProgramPartsBetweenParts(ctrl: MachineController): boolean {
  const run = programPartsRun
  if (!run || run.controller !== ctrl || !run.heldBetweenParts) return false
  if (
    ctrl.connectionPhase() !== 'connected'
    || ctrl.resetInProgress()
    || ctrl.machineState() !== 'idle'
  ) return false

  run.heldBetweenParts = false
  store().applyJobProgress({ ...wholeProgramProgress(ctrl.jobProgress()), phase: 'streaming' })
  applyJobLifecycleEvent('resumed', null)
  return advanceProgramPartIfComplete('single-block')
}

/** Advance only after the controller has independently reported both halves
 * of completion: the part lifecycle ended, and status/progress say idle with
 * every staged move acknowledged. */
function advanceProgramPartIfComplete(startMode: 'continuous' | 'single-block' = 'continuous'): boolean {
  const run = programPartsRun
  if (
    !run
    || run.controller !== controller
    || !run.completionSignaled
    || run.advancing
  ) return false
  if (run.controller.resetInProgress()) {
    const reason = stopResetRequestedForProgramParts
      ? 'Program parts stopped by Stop/Reset; no later part was loaded.'
      : 'Program parts ended; the controller was not ready to load the next part.'
    stopResetRequestedForProgramParts = false
    endProgramParts(reason, 'stopped', null, 'info')
    return false
  }
  if (run.controller.machineState() === 'alarm') {
    // WO-1996: the alarm a missed M6 measure raised is that measure's answer;
    // the program stays held at its M6 for Retry measure.
    if (guidedMeasureOwnsAlarm(run)) return false
    const reason = 'Program parts ended because the controller entered an alarm; no later part was loaded.'
    endProgramParts(reason, 'failed', { code: null, message: reason, line: null, moveId: null }, 'error')
    return false
  }
  if (run.controller.connectionPhase() !== 'connected') {
    const reason = 'Program parts ended because the controller disconnected; no later part was loaded.'
    endProgramParts(reason, 'failed', { code: null, message: reason, line: null, moveId: null }, 'error')
    return false
  }
  // A hold pauses motion; it must never hide a terminal machine edge. The
  // reset/alarm/disconnect checks above therefore deliberately outrank it.
  if (run.heldBetweenParts) return false
  if (run.controller.machineState() !== 'idle') return false
  if (programPartsRun !== run || run.heldBetweenParts) return false
  const progress = geometryPartProgress(run.controller, null, true) ?? run.controller.jobProgress()
  if (programPartsRun !== run || run.controller.resetInProgress() || run.heldBetweenParts) return false
  const currentCount = run.parts[run.partIndex].steps.length
  if (progress.totalLines !== currentCount || progress.ackedLines !== currentCount) return false

  // WO-1323: A SETUP BOUNDARY IS NOT A CAPACITY BOUNDARY, and the program says
  // so out loud. The outgoing setup's last move was a retract to the program's
  // global safe height, the next setup runs at a different zero, and between
  // two setups of one part the work itself has to be moved. So the program
  // HOLDS here, names both setups and the frame the next one runs in, and the
  // frame changes on the operator's next CYCLE START - not on this edge.
  //
  // EVERYTHING THE HOLD ASKS FOR IS AVAILABLE WHILE PAUSED: re-fixture the
  // work, press CYCLE START. It never asks for a tool change or a work-zero
  // edit, because a paused program disables jog and refuses live offset edits -
  // a program needing either is refused at load time instead of held here.
  //
  // WO-1329 MADE THAT HOLD OPTIONAL AND OFF BY DEFAULT, on Operator's ruling from
  // the machine: "An operator would not like to have to hit cycle start twice
  // for every multi-setup program run." When the program was loaded to continue
  // through, the boundary is crossed HERE instead - every check below happens
  // in the same order, only the waiting for a human is gone. A tool change is
  // never run through whatever the operator asked for: that program does not
  // load at all.
  const boundary = run.boundaries?.get(run.partIndex + 1)

  // WO-1330: A TOOL-CHANGE BOUNDARY IS A SEQUENCE, AND THIS IS ITS FIRST STEP.
  //
  // Operator at the machine, 2026-09-11: "If it does change tool, even if I check
  // the box saying continue through, it should NOT continue through - it should
  // be initiating a tool change sequence." So the box is not consulted here at
  // all, and three things happen in this order:
  //
  //  1. THE RETRACT-CLEAR CHECK, with the OUTGOING tool's retract height, which
  //     is the last instant that number describes the thing in the spindle. It
  //     runs HERE rather than at the release, because after the change the
  //     operator has jogged and re-zeroed and that height means nothing.
  //  2. The spindle stops - `applyJobLifecycleEvent('paused')` does it, the
  //     same call that stops it at WO-1323's hold - before the hold sentence
  //     invites anyone near the tool.
  //  3. The hold is entered and NAMED, and the two things it permits (jog, and
  //     the new tool's Z zero in the incoming frame) go live in the panels.
  if (
    boundary?.toolChange !== undefined
    && run.announcedBoundary !== run.partIndex + 1
  ) {
    const refusal = boundaryClearRefusal(run.controller, boundary)
    if (refusal !== null) {
      run.advancing = false
      failProgramParts(refusal)
      return false
    }
    run.announcedBoundary = run.partIndex + 1
    run.heldBetweenParts = true
    store().applyJobProgress({ ...wholeProgramProgress(progress), phase: 'paused' })
    // WO-1652 fix round 4: THE PROGRAM'S M6 ALWAYS IS THE TOOL CHANGE. A macro
    // bound to M6 runs first, as a prelude, with the hold already entered
    // (spindle stopped, Z-zero gate armed); the guided change starts when the
    // macro ends, however it ends. With no macro the hold is main's, unchanged.
    const prelude = boundary.postedM6 === undefined ? null : boundMacro(6)
    enterProgramToolChangeHold(run, boundary, run.partIndex + 1, true, prelude === null)
    if (prelude !== null) runM6Prelude(run, boundary, run.partIndex + 1, prelude)
    return false
  }

  if (
    boundary !== undefined
    && boundary.runThrough !== true
    && run.announcedBoundary !== run.partIndex + 1
  ) {
    run.announcedBoundary = run.partIndex + 1
    run.heldBetweenParts = true
    // The finished stage's count is the stage's whole move count (`progress`
    // above is the terminal geometry progress), not the controller's own
    // acked counter, which read one short at the hold on the board (158 of
    // 159; 2026-09-11).
    store().applyJobProgress({
      ...wholeProgramProgress(progress),
      phase: 'paused',
    })
    store().pushConsole('rx', boundary.holdMessage ?? describeSetupBoundaryHold(boundary), 'info')
    applyJobLifecycleEvent('paused', null)
    if (boundary.macro !== undefined) runProgramBoundaryMacro(run, boundary, run.partIndex + 1)
    else if (boundary.postedM6 !== undefined) {
      // A posted M6 on a machine with no tool-change park: the plain hold
      // above IS its tool change (main's), and a macro on M6 runs first.
      const prelude = boundMacro(6)
      if (prelude !== null) runM6Prelude(run, boundary, run.partIndex + 1, prelude)
    }
    return false
  }

  // WO-1329: A RUN-THROUGH BOUNDARY IS NOT A STOP, AND THE READOUT MUST NOT SAY
  // ONE. The controller's own progress for the part that just ended reads
  // COMPLETE, and on a held boundary the hold above overwrites it with `paused`.
  // Nothing overwrote it here, so the operator watched a running program report
  // "complete" at every boundary. Same count correction as the hold - the
  // finished stage's whole move count, taken before the counters move on - with
  // the phase that is actually true: still streaming.
  if (boundary !== undefined && boundary.runThrough === true) {
    store().applyJobProgress({ ...wholeProgramProgress(progress), phase: 'streaming' })
  }

  run.completedMoves += currentCount
  run.partIndex += 1
  run.completionSignaled = false
  run.advancing = true
  if (boundary !== undefined) return crossSetupBoundary(run, boundary, startMode)
  return loadAndStartCurrentPart(run, startMode)
}

/** WO-1652: A PROGRAM'S M-CODE RUNS THE MACRO THAT CARRIES IT, at any number.
 * The boundary is already held and announced; the machine's macro bound to the
 * code runs here, through the same runtime its button and a typed code use.
 * The program stays held: CYCLE START runs the rest once the macro has
 * finished, or the clamp card's Continue when its body opened a clamp pause.
 * A code with no macro keeps the generic hold it always had. */
function runProgramBoundaryMacro(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
): void {
  const code = boundary.macro?.code
  const macro = code === undefined ? null : boundMacro(code)
  if (macro === null) return
  const marked = boundary.macro?.toolChange
  runBoundaryMacro(run, boundary, boundaryIndex, macro, false, (entry, started) => {
    // WO-1652 tightening: TEXT MAY ONLY ADD A HOLD. The reader counted this
    // macro as a tool change (its body calls `toolChange()`), so the load line
    // said the program runs that tool. However the macro ended - finished,
    // could not start, refused a line, errored, its own Stop - if it did not
    // enter the tool-change hold itself, that hold follows now, as it follows
    // the M6 prelude. Reached already: exactly one hold, no second.
    if (marked !== undefined) {
      if (entry.toolChangeHeld || boundary.toolChange !== undefined || programGuidedToolChange?.run === run) return
      store().pushConsole(
        'rx',
        `Macro "${macro.name}" (M${code}) has ended without reaching its tool change - the tool change to T${marked} `
          + 'follows.',
        'info',
      )
      enterBoundaryMacroToolChange(entry, marked)
      return
    }
    if (!started) return
    // A clamp pause or a tool change the body opened owns the boundary now.
    if (programClampPause?.run === run || programGuidedToolChange?.run === run || entry.toolChangeHeld) return
    store().pushConsole(
      'rx',
      `Macro "${macro.name}" (M${code}) has finished - press CYCLE START to run the rest of the program.`,
      'info',
    )
  })
}

/** WO-1652 fix round 4: A MACRO BOUND TO M6 IS A PRELUDE, NEVER A STAND-IN.
 * The program's M6 is held and its tool-change hold already entered (spindle
 * stopped, the new tool's Z-zero gate armed); the macro runs first (dust shoe
 * off, a move out of the way), and when it ends - finished, refused, errored,
 * stopped by its own Stop, or cut short by its `toolChange()` - the ONE tool
 * change follows: the guided fixed-pad change where the machine has a
 * tool-change park, main's plain hold otherwise. Nothing the macro does or
 * says can skip it. A Stop/Reset or E-STOP that ends the program ends the
 * prelude with it, exactly as it ends a posted M6's hold. */
function runM6Prelude(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
  macro: MachineMacro,
): void {
  const m6 = boundary.postedM6
  if (m6 === undefined) return
  runBoundaryMacro(run, boundary, boundaryIndex, macro, true, () => {
    if (boundary.m6 !== undefined && boundary.toolChange !== undefined) {
      store().pushConsole(
        'rx',
        `Macro "${macro.name}" (M6) has ended - the tool change on line ${m6.line} follows.`,
        'info',
      )
      beginProgramM6ToolChange(run, boundary, boundaryIndex)
      return
    }
    store().pushConsole(
      'rx',
      `Macro "${macro.name}" (M6) has ended - the tool change on line ${m6.line} follows: fit T${m6.tool}, `
        + 'set its Z zero, then press CYCLE START to run the rest.',
      'info',
    )
  })
}

/** Run `macro` at the held boundary through the one macro runtime, and call
 * `ended` once when it ends (or could not start) while that boundary is still
 * the one held - a Stop/Reset or E-STOP that ended the program ends it too. */
function runBoundaryMacro(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
  macro: MachineMacro,
  m6Prelude: boolean,
  ended: (entry: NonNullable<typeof programBoundaryMacro>, started: boolean) => void,
): void {
  const marked = m6Prelude ? undefined : boundary.macro?.toolChange
  const entry: NonNullable<typeof programBoundaryMacro> = {
    run, boundary, boundaryIndex, m6Prelude, toolChangeHeld: false,
    ...(marked === undefined ? {} : { markedToolChange: marked }),
  }
  programBoundaryMacro = entry
  let done = false
  const finish = (started: boolean): void => {
    if (done) return
    done = true
    if (programBoundaryMacro === entry) programBoundaryMacro = null
    if (programPartsRun !== run || !run.heldBetweenParts || run.announcedBoundary !== boundaryIndex) return
    ended(entry, started)
  }
  if (!runUserMacro(macro)) {
    finish(false)
    return
  }
  const off = subscribeMacroRun(() => {
    if (activeMacroRun() !== null) return
    off()
    finish(true)
  })
  if (activeMacroRun() === null) {
    off()
    finish(true)
  }
}

/** WO-1652: one line of the running boundary macro, through the MDI door
 * that is otherwise locked while a program is held between parts. */
export function sendFromProgramBoundaryMacro<T>(send: () => T): T {
  if (currentProgramBoundaryMacro() === null) return send()
  programBoundaryMacroSending = true
  try {
    return send()
  } finally {
    programBoundaryMacroSending = false
  }
}

/** WO-1652: the macro API's `clampPause()` - the clamp pause the session has
 * always run at a program's park-and-clamp code, opened on the held boundary
 * whose macro is running. It ENDS the macro: from here the clamp card owns
 * the boundary and its Continue runs the rest of the program. Null when it
 * opened; the reason when no program is held at this macro's code, so there
 * is no program to pause and resume. */
export function clampPauseFromMacro(): string | null {
  const pending = currentProgramBoundaryMacro()
  if (pending === null) {
    return "no program is held at this macro's M-code, so there is no program to pause and resume - "
      + 'it runs where a program calls the macro'
  }
  if (pending.m6Prelude) {
    return "this macro runs before the program's M6, and the tool change owns this hold - it follows now"
  }
  // WO-1652 tightening: a macro the load counted as a tool change owns a
  // tool-change hold; a clamp card's Continue would run the next section with
  // the old tool. The refusal ends the macro and the tool change follows.
  if (pending.markedToolChange !== undefined) {
    return 'this macro runs the tool change at this M-code, and the tool change owns this hold - it follows now'
  }
  void beginProgramClampPause(pending.run, pending.boundary, pending.boundaryIndex)
  return null
}

/** WO-1652: the macro API's `toolChange(tool?)` - the programmed tool change
 * (`T2 M6`), run on the held boundary whose macro is running: the same
 * tool-change hold and the same guided park / swap / probe / resume a posted
 * M6 runs, with nothing copied. The tool is the argument, or the file's last
 * `T` before the macro's M-code. It ENDS the macro: the tool-change hold owns
 * the boundary from here.
 *
 * Fix round 4: ONCE REACHED, THE HOLD FOLLOWS. Nothing here leaves the
 * program able to run on without a tool change: a machine with no tool-change
 * park, or no tool known, gets main's plain M6 hold (fit the tool, set its Z
 * zero, CYCLE START). In the macro bound to M6 itself (the prelude) it starts
 * no second change: it ends the prelude, and the program's one M6 hold
 * follows. Null when the hold is entered; the reason only when no program is
 * held at the macro's code, or the retract check ends the program (as it ends
 * a posted M6). */
export function toolChangeFromMacro(tool?: unknown): string | null {
  const pending = currentProgramBoundaryMacro()
  if (pending === null) {
    return "no program is held at this macro's M-code, so there is no program to change the tool in and resume - "
      + 'it runs where a program calls the macro'
  }
  // The prelude of a posted M6: the program's own tool change follows it.
  if (pending.m6Prelude) return null
  return enterBoundaryMacroToolChange(pending, tool)
}

/** The tool-change hold at a held macro boundary - reached by the macro's own
 * `toolChange()`, or (WO-1652 tightening) after a macro the reader counted as
 * a tool change ended without reaching it. One path, one hold. */
function enterBoundaryMacroToolChange(
  pending: NonNullable<typeof programBoundaryMacro>,
  tool: unknown,
): string | null {
  const { run, boundary, boundaryIndex } = pending
  const code = boundary.macro?.code
  const line = boundary.macro?.line ?? 1
  if (boundary.toolChange !== undefined) return null
  const validTool = typeof tool === 'number' && Number.isInteger(tool) && tool > 0 ? tool : null
  if (tool !== undefined && validTool === null) {
    store().pushConsole(
      'rx',
      `M${code} on line ${line}: toolChange(${String(tool)}) names no whole tool number - the file's own tool is used.`,
      'warn',
    )
  }
  const to = validTool ?? boundary.macroToolChange?.to ?? null
  if (to === null || configuredToolChangePark() === null) {
    // Main's M6 hold on a machine with no tool-change park: the boundary is
    // already held and the spindle stopped; the operator fits the tool.
    pending.toolChangeHeld = true
    const fit = to === null ? 'the next tool' : describeGcodeTool(to, useCamStore.getState().toolLibrary)
    store().pushConsole(
      'rx',
      `M${code} on line ${line} runs the tool change. The spindle is stopped and the tool is where the file left `
        + `it: fit ${fit}, set its Z zero, then press CYCLE START to run the rest.`,
      'info',
    )
    return null
  }
  // The retract-clear check a programmed M6 runs at its hold, with the
  // OUTGOING tool's height, before the change - and its refusal the same.
  const refusal = boundaryClearRefusal(run.controller, boundary)
  if (refusal !== null) {
    run.advancing = false
    failProgramParts(refusal)
    return refusal
  }
  const library = useCamStore.getState().toolLibrary
  const from = boundary.macroToolChange?.from ?? null
  boundary.toolChange = {
    leaving: from === null ? 'the tool in the spindle' : describeGcodeTool(from, library),
    fit: describeGcodeTool(to, library),
    spindle: boundary.macroToolChange?.spindle ?? null,
  }
  boundary.m6 = { line, tool: to, ...(code === undefined ? {} : { code }) }
  enterProgramToolChangeHold(run, boundary, boundaryIndex, false)
  return null
}

/** The clamp pause at a held program boundary: park, then let the operator
 * screw down the material. The park is `workholdingStopPark` - the one answer
 * the posted operator stop parks at too (WO-2437) - and the safe height comes
 * from this machine's definition; no coordinate is invented. */
function beginProgramClampPause(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
): Promise<boolean> {
  const machine = parkCarrierMachine(useCamStore.getState())
  const config = useMachineActions.getState().configFor(machine?.id ?? 'default')
  const park = workholdingStopPark(machine, config)
  const code = boundary.macro === undefined ? 'The clamp pause' : `M${boundary.macro.code}`
  if (park === null) {
    store().pushConsole(
      'rx',
      `${code} could not park because this machine has no park macro marked for this; `
      + 'make one in the Macros panel (Edit macros). '
      + 'The program stays held so you can park and screw down the material yourself.',
      'warn',
    )
    return Promise.resolve(false)
  }

  const safeZMachine = machineSafeZValue(machine, config)
  const pending = { run, boundaryIndex, park: { park, safeZMachine } }
  programClampPause = pending
  // WO-2437 fix round 4: the clamp pause owns the machine as a tool-change
  // hold does - its park and the operator's jogs are not the program's path.
  openPathFidelityExcursion(run, boundaryIndex)
  // A failed park leaves the clamp card and its held program boundary in place.
  // Keep this owner until Continue succeeds or an explicit cleanup ends it so
  // CYCLE START cannot resume cutting behind the failed card.
  return beginClampPause({
    resumeLine: Math.max(2, (boundary.macro?.line ?? 1) + 1),
    park,
    safeZMachine,
    awaitingMessage:
      `Parked at "${park.label}". Screw down the material without moving its zero, then press `
      + 'CYCLE START or Continue to run the rest.',
  })
}

/** WO-1330/1369: THE TOOL-CHANGE HOLD at a held program boundary - the spindle
 * stops, the hold is named, jog and the incoming Z zero go live, and an M6
 * runs the fixed-pad guided tool change. One copy: a programmed M6 reaches it
 * at the completion edge, and (WO-1652) a macro's `toolChange()` at the
 * boundary its M-code holds. `pauseJob` is false only for the macro, whose
 * boundary hold already raised `paused`. */
function enterProgramToolChangeHold(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
  pauseJob: boolean,
  startGuided = true,
): void {
  const toolChange = boundary.toolChange
  if (toolChange === undefined) return
  // ONE AUTHORITY FOR BOTH ENDS OF THE SPINDLE (audit, fourth round). This
  // answer decides whether the hold says "the spindle is stopped", and the
  // same answer decides whether CYCLE START starts the incoming spindle and
  // gates on its speed. A controller that takes spindle calls has an inverter
  // this app stops here and starts at the release; one that does not has
  // nothing this app can switch, so the operator gets both ends - off at the
  // hold, on at the new tool's speed before CYCLE START - and CYCLE START is
  // their word that it is running. The machine record is not asked: a record
  // that names no link must not leave a spindle we stopped standing still.
  const spindleStops = spindleRoute(run.controller) === 'calls'
  // WO-2025: when the guided change will measure the tool, the hold must not tell
  // the operator to set the work Z zero - following that re-zeroes G54 Z and cuts
  // at the wrong depth. Not gated on startGuided: an M6-bound macro prelude also
  // ends in the guided change.
  const measuredAtSetter = boundary.m6 !== undefined && guidedChangeWillMeasure()
  const holdSaid = describeToolChangeHold({
    finishedName: boundary.finishedName,
    nextName: boundary.nextName,
    wcs: boundary.wcs,
    leaving: toolChange.leaving,
    fit: toolChange.fit,
  }, spindleStops, toolChange.spindle, measuredAtSetter)
  store().pushConsole('rx', measuredAtSetter ? referenceRemeasureHold(holdSaid, boundary) : holdSaid, 'info')
  // STOPS THE SPINDLE. Everything after this line runs with the inverter
  // commanded off, which is the state the operator's hands are entitled to.
  // (A macro's `toolChange()` arrives at a boundary whose hold already did.)
  if (pauseJob) applyJobLifecycleEvent('paused', null)
  // That call stops only a spindle THIS PROGRAM commanded. A program with no
  // spindle intent of its own - the machine record names no link, or the
  // connection has none - still reaches the tool change, so its stop is sent
  // here. Nothing gates a stop: the bridge takes it with or without a link.
  if (geometryProgramSpindle?.controller !== run.controller) {
    commandSpindle('off', 0, () => [], run.controller)
  }
  // THE NEW TOOL'S SPEED IS WHAT CYCLE START ARMS FOR. WO-1329's one-intent
  // rule relaxes at a tool-change boundary and only there, so the gate the
  // release runs through is re-pointed at the incoming stage's intent before
  // anything can press it.
  const nextSpindle = spindleStops ? toolChange.spindle : null
  geometryProgramSpindle = nextSpindle === null
    ? null
    : {
        ...nextSpindle,
        controller: run.controller,
        running: false,
        saidNoSpindleLink: false,
        commandedAgainstStatus: null,
      }
  const hold: ToolChangeHold = {
    finishedName: boundary.finishedName,
    nextName: boundary.nextName,
    wcs: boundary.wcs,
    leaving: toolChange.leaving,
    fit: toolChange.fit,
  }
  // WO-2033: from here until the resumed program has placed the tool again,
  // the path check does not score the machine - see `PathFidelityExcursion`.
  openPathFidelityExcursion(run, boundaryIndex)
  // No Z zero yet: one written before this line was for the tool that left.
  pendingToolChange = {
    controller: run.controller,
    hold,
    zZeroConfirmed: false,
    spindle: nextSpindle,
    releasedRevision: null,
    saidAwaitingReceipts: false,
  }
  setToolChangeHold(hold)
  // A macro bound to M6 runs between the hold and the guided change
  // (`runM6Prelude`), which starts it when the macro ends.
  if (boundary.m6 !== undefined && startGuided) {
    beginProgramM6ToolChange(run, boundary, boundaryIndex)
  }
}

/** A reference tool has been measured on this machine, so a guided change can
 * turn a fresh measure into a length offset. */
/**
 * WO-2106: FITTING THE REFERENCE TOOL MOVES THE WORK ZERO, AND THE HOLD SAYS SO.
 *
 * Rehearsal 2026-09-27 (T19, T1, T19 with T19 the reference): the hold before
 * T19 went back in read "the G54 Z work zero is not changed", and the measure
 * that followed moved it +0.029 mm - re-measuring the reference moves the work
 * zero with its new reading (WO-2042, ProgramPanel's guided measure). Any other
 * tool keeps the sentence as it is.
 */
function referenceRemeasureHold(said: string, boundary: ProgramSetupBoundary): string {
  const tool = boundary.m6?.tool
  if (tool === undefined) return said
  const table = useMachineToolTable.getState().tableFor(controlMachine(useCamStore.getState()).id)
  if (table.reference !== tool || typeof findTool(table, tool)?.probedMachineZ !== 'number') return said
  return said.replace(
    `the ${boundary.wcs} Z work zero is not changed; the new tool is measured at the setter.`,
    `T${tool} is the reference tool: it is measured at the setter, and the ${boundary.wcs} Z work zero moves `
      + 'with its new reading so every other tool keeps its offset.',
  )
}

function guidedChangeHasReference(): boolean {
  const machine = controlMachine(useCamStore.getState())
  // WO-2016: the same answer Load gives (`referenceToolMeasuredIn`).
  return referenceToolMeasuredIn(useMachineToolTable.getState().tableFor(machine.id))
}

/** True when an M6 hold will run the guided change that measures the tool. */
function guidedChangeWillMeasure(): boolean {
  if (!guidedChangeHasReference() || configuredToolChangePark() === null) return false
  // Same gate beginProgramM6ToolChange applies: without a safe Z the change refuses.
  const machine = controlMachine(useCamStore.getState())
  const config = useMachineActions.getState().configFor(machine.id)
  return machineSafeZValue(parkCarrierMachine(useCamStore.getState()), config) !== null
}

/** WO-1369: an M6 is the program invoking the machine's configured tool-change
 * macro. The outgoing part is already complete and the controller is idle, so
 * the shared guided flow performs only its verified park, swap and probe work;
 * the pending geometry boundary below remains the resume authority. */
function beginProgramM6ToolChange(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  boundaryIndex: number,
): void {
  const m6 = boundary.m6
  if (m6 === undefined) return
  // WO-2521: the program's M6 names its tool - the selected tool now.
  selectToolWord(run.controller, m6.tool)
  const machine = controlMachine(useCamStore.getState())
  const config = useMachineActions.getState().configFor(machine.id)
  const park = configuredToolChangePark()
  if (!guidedChangeHasReference()) {
    store().pushConsole(
      'rx',
      `M${m6.code ?? 6} on line ${m6.line} cannot run the fixed-pad tool change because no reference tool has been measured. `
        + `Fit T${m6.tool}, set its Z work zero, then press CYCLE START; the program remains held.`,
      'warn',
    )
    return
  }
  programGuidedToolChange = { run, boundaryIndex }
  const fail = (message: string): void => {
    setToolChange({
      step: 'failed',
      mode: 'toolChange',
      tool: m6.tool,
      resumeLine: m6.line + 1,
      message,
      warnings: [],
    })
    store().pushConsole('rx', `M${m6.code ?? 6} on line ${m6.line}: ${message}`, 'error')
  }
  if (park === null) {
    fail('The machine has no tool-change park position, so it cannot move over the fixed probe pad. The program remains held.')
    return
  }
  const safeZMachine = machineSafeZValue(parkCarrierMachine(useCamStore.getState()), config)
  if (safeZMachine === null) {
    fail('The machine has no safe Z for the tool-change park move. The program remains held.')
    return
  }
  void beginGuidedToolChange({
    tool: m6.tool,
    resumeLine: m6.line + 1,
    park,
    safeZMachine,
    alreadyStoppedAtProgramBoundary: true,
  })
  store().pushConsole(
    'rx',
    `M${m6.code ?? 6} on line ${m6.line}: moving to "${park.label}". Fit T${m6.tool}; Continue will probe it, apply `
      + 'its measured length and resume the program.',
    'info',
  )
}

/** Continue a clamp-pause boundary whose outgoing part was already proven complete
 * before the park. The park is a separate controller motion, so re-checking
 * the controller's current job counters would inspect the park instead of the
 * completed file part; release the already-announced boundary directly. */
function canContinueProgramClampPause(pending: NonNullable<typeof programClampPause>): boolean {
  const { run, boundaryIndex } = pending
  return !(
    programPartsRun !== run
    || run.controller !== controller
    || !run.heldBetweenParts
    || run.announcedBoundary !== boundaryIndex
    || run.partIndex + 1 !== boundaryIndex
    || run.controller.connectionPhase() !== 'connected'
    || run.controller.resetInProgress()
    || run.controller.machineState() !== 'idle'
  ) && run.boundaries?.has(boundaryIndex) === true
}

function continueProgramClampPause(
  pending: NonNullable<typeof programClampPause>,
  startMode: 'continuous' | 'single-block' = 'continuous',
): boolean {
  if (!canContinueProgramClampPause(pending)) return false
  const { run, boundaryIndex } = pending
  const boundary = run.boundaries!.get(boundaryIndex)!

  run.heldBetweenParts = false
  const heldProgress = stagedJobCounts()
  store().applyJobProgress({
    phase: 'streaming',
    totalLines: heldProgress.totalLines,
    sentLines: heldProgress.sentLines,
    ackedLines: heldProgress.ackedLines,
    ackedSourceLine: heldProgress.ackedSourceLine,
    sentSourceLine: heldProgress.sentSourceLine,
    bytesInFlight: 0,
  })
  applyJobLifecycleEvent('resumed', null)
  run.completedMoves += run.parts[run.partIndex].steps.length
  run.partIndex += 1
  run.completionSignaled = false
  run.advancing = true
  return crossSetupBoundary(run, boundary, startMode)
}

/** The machine stands where its clamp pause parked (the park's own Z, else
 *  the safe Z it parked at). */
function atClampPausePark(at: { park: ParkPosition; safeZMachine: number | null }): boolean {
  const m = controller?.status().machinePos
  if (!m) return false
  const z = typeof at.park.z === 'number' && Number.isFinite(at.park.z) ? at.park.z : at.safeZMachine
  const near = (a: number, b: number) => Math.abs(a - b) <= SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM
  return near(m.x, at.park.x) && near(m.y, at.park.y) && (z === null || near(m.z, z))
}

/** Back to the clamp pause's park - the same park move, Z first - then the
 *  rest of the program, as Continue runs it from the park. A park that does
 *  not finish leaves the card saying so, and the program held. */
async function returnToClampParkThenContinue(
  pending: NonNullable<typeof programClampPause>,
  at: { park: ParkPosition; safeZMachine: number | null },
  startMode: 'continuous' | 'single-block',
): Promise<boolean> {
  const tc = store().toolChange
  if (tc === null) return false
  const base = { mode: tc.mode, tool: tc.tool, resumeLine: tc.resumeLine, warnings: [] as string[] }
  const ctrl = pending.run.controller
  setToolChange({ ...base, step: 'parking', message: `Back to "${at.park.label}" before the rest of the program...` })
  const parked = await parkForGuidedStop(ctrl, at.park, at.safeZMachine)
  if (programClampPause !== pending) return false
  if (!parked.ok) {
    setToolChange({ ...base, step: 'failed', message: parked.reason })
    return false
  }
  if (!canContinueProgramClampPause(pending)) {
    setToolChange({ ...base, step: 'awaiting-swap', message: tc.message })
    return false
  }
  programClampPause = null
  setToolChange(null)
  return continueProgramClampPause(pending, startMode)
}

/** WO-2437 fix round (rehearsal 2026-10-02): CYCLE START at a program's clamp
 * pause. Parked and waiting, it is the card's Continue - the operator stop's
 * own words are "press Cycle Start" - and the card's Continue stays. While the
 * park still moves, or after it failed, the card answers as before. */
function continueClampPauseByCycleStart(startMode: 'continuous' | 'single-block'): boolean {
  const tc = store().toolChange
  if (tc?.mode !== 'clampPause' || tc.step !== 'awaiting-swap') return false
  return continueClampPause(startMode)
}

/** WO-2437 fix round (rehearsal 2026-10-02): the operator's Stop/Reset at a
 * program's clamp pause ends it, as Stop ends the program at any other pause
 * (WO-2240, WO-1326: the run ends, it does not rewind). The card goes, the
 * program ends as the operator's stop, and jog, MDI and a new run are the
 * operator's again. A park still moving answers for itself: the Stop stops its
 * move, the card says the park did not finish, and Stop/Reset then ends it. */
function endProgramClampPauseByOperatorStop(target: MachineController): void {
  const pending = programClampPause
  if (sessionStopInProgress || pending === null) return
  if (pending.run.controller !== target || programPartsRun !== pending.run) return
  const tc = store().toolChange
  if (tc?.mode === 'clampPause' && (tc.step === 'stopping' || tc.step === 'parking')) return
  if (operatorStopPending?.controller !== target) noteOperatorStop(target)
  programClampPause = null
  if (tc?.mode === 'clampPause') setToolChange(null)
  endProgramParts(programPartsStopResetReason(target), 'stopped', null, 'info')
}

/** WO-2599: the operator's Reset ends an M0/M6 program hold. Other setup
 * boundaries keep their existing continuation, and session resets stay private. */
function endProgramHoldByOperatorStop(target: MachineController): void {
  const run = programPartsRun
  if (sessionStopInProgress || !run || run.controller !== target || !run.heldBetweenParts) return
  const boundary = run.boundaries?.get(run.partIndex + 1)
  const m6 = boundary?.m6 ?? boundary?.postedM6
  const m0 = /stopped at the M(0) on line (\d+)/.exec(boundary?.holdMessage ?? '')
  if (!m0 && !(m6 && store().toolChange?.mode === 'toolChange')) return
  noteOperatorStop(target)
  const line = m0 ? Number(m0[2]) : m6!.line
  const label = m0 ? `M${m0[1]} hold` : `T${m6!.tool} change`
  if (operatorStopPending) operatorStopPending = { ...operatorStopPending, line, boundary: label }
  cancelGuidedToolChange()
  endProgramParts(`Stopped at line ${line} (${label}). Restart the program or run from a line.`, 'stopped', null, 'info')
}

export function programToolChangeCanStop(): boolean {
  return programGuidedToolChange !== null && store().toolChange?.mode === 'toolChange'
}

function programM6ResumeRefusal(
  pending: NonNullable<typeof programGuidedToolChange>,
): string | null {
  const { run, boundaryIndex } = pending
  if (programPartsRun !== run) return 'the held multipart program is no longer current'
  if (run.controller !== controller) return 'the machine connection changed'
  if (!run.heldBetweenParts) return 'the program is no longer held between parts'
  if (run.announcedBoundary !== boundaryIndex) return 'the held boundary changed'
  if (run.partIndex + 1 !== boundaryIndex) return 'the program part changed'
  if (run.controller.connectionPhase() !== 'connected') return 'the controller disconnected'
  if (run.controller.resetInProgress()) return 'the controller is resetting'
  if (run.controller.machineState() !== 'idle') return 'the controller is not idle'
  if (run.boundaries?.get(boundaryIndex)?.m6 === undefined) return 'the held boundary is no longer an M6'
  return null
}

function canContinueProgramM6(pending: NonNullable<typeof programGuidedToolChange>): boolean {
  return programM6ResumeRefusal(pending) === null
}

/** The probe and controller offset are complete. Release the geometry boundary
 * that owns this M6 and start its next part; Continue is the operator's
 * go-ahead for both the probe motion and this resume. */
function continueProgramM6ToolChange(
  pending: NonNullable<typeof programGuidedToolChange>,
): boolean {
  if (!canContinueProgramM6(pending)) return false
  const { run, boundaryIndex } = pending
  const boundary = run.boundaries!.get(boundaryIndex)!
  if (pendingToolChange?.controller !== run.controller) return false
  pendingToolChange.zZeroConfirmed = true
  if (!releaseToolChangeHold(run.controller)) return false

  programGuidedToolChange = null
  run.heldBetweenParts = false
  const heldProgress = stagedJobCounts()
  store().applyJobProgress({
    phase: 'streaming',
    totalLines: heldProgress.totalLines,
    sentLines: heldProgress.sentLines,
    ackedLines: heldProgress.ackedLines,
    ackedSourceLine: heldProgress.ackedSourceLine,
    sentSourceLine: heldProgress.sentSourceLine,
    bytesInFlight: 0,
  })
  applyJobLifecycleEvent('resumed', null)
  run.completedMoves += run.parts[run.partIndex].steps.length
  run.partIndex += 1
  run.completionSignaled = false
  run.advancing = true
  const resumed = crossSetupBoundary(run, boundary, 'continuous')
  if (resumed) setToolChange(null)
  return resumed
}

/**
 * IS THE TOOL CLEAR OF THE WORK AT THIS BOUNDARY? (WO-1323's agenda FAIL #3.)
 *
 * The outgoing stage's last move was a retract to the program's global safe
 * height, but "the program asked for a retract" is not evidence the tool is
 * clear - the readback is. Returns the operator's sentence when it is not, and
 * null when the machine has reported being at or above that height.
 *
 * WO-1330 SPLIT THIS OUT of `crossSetupBoundary` so it can be asked at the
 * completion edge instead: a tool-change boundary must be proven clear BEFORE
 * its spindle stops and its hold invites the operator in, and by the time that
 * hold is released the height belongs to a tool that is no longer fitted.
 */
function boundaryClearRefusal(
  ctrl: MachineController,
  boundary: ProgramSetupBoundary,
): string | null {
  if (boundary.clearMachineZ === null) return null
  const reached = ctrl.status().machinePos?.z ?? null
  if (reached === null || !Number.isFinite(reached)) {
    return `The machine did not report where Z is after ${boundary.finishedName} retracted, so `
      + `${boundary.wcs} was not selected and "${boundary.nextName}" was not started. Nothing moved.`
  }
  if (reached < boundary.clearMachineZ - SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM) {
    return `The tool is at ${formatPosition({ machine: { z: reached }, format: machineLengthText })} and `
      + `${boundary.finishedName} retracts clear `
      + `at ${formatPosition({ machine: { z: boundary.clearMachineZ }, format: machineLengthText })}, so it is not clear of the work. `
      + `${boundary.wcs} was not selected and "${boundary.nextName}" was not started. Nothing moved.`
  }
  return null
}

/**
 * WO-1323: THE FRAME CHANGES HERE AND NOWHERE ELSE.
 *
 * Three things happen in this order, and the order is the point:
 *
 *  1. THE MACHINE IS ASKED WHERE Z IS. The outgoing setup's part ended on a
 *     retract to the program's global safe height, but "the program asked for
 *     a retract" is not evidence the tool is clear - the readback is. A machine
 *     reporting Z below that height gets no frame change and no next setup.
 *  2. THE FRAME IS SELECTED AND CONFIRMED, through WO-1312's `selectWcsAwait`
 *     receipt where the backend has one. There is no second frame-selection
 *     mechanism here: this is the same call the single-setup load makes.
 *  3. ONLY THEN is the next setup's first part staged and started.
 *
 * A Z move at the new offset before the tool is clear is the failure this
 * whole order exists to prevent, and it is prevented by never reaching step 3
 * with step 1 unanswered.
 *
 * WHEN THE TOOL IS THE SAME ON BOTH SIDES, the outgoing stage's retract height
 * still describes the thing in the spindle and step 1's readback means what it
 * says. WO-1330's tool-change boundary asks step 1 EARLIER - at the completion
 * edge, before the spindle stops and the hold opens - because after the change
 * the operator has jogged and set a new Z zero, and the old tool's retract
 * height is no longer a fact about anything. Step 2 and step 3 are unchanged
 * either way.
 *
 * WO-1329: THIS IS ALSO THE RUN-THROUGH PATH, UNCHANGED. Whether the program
 * waited for a human at the boundary decides only WHEN this runs, never what it
 * does - the Z readback, the frame receipt and the staging happen in the same
 * order, and a machine that cannot prove the tool is clear stops the program
 * here exactly as it would have after a hold.
 */
function crossSetupBoundary(
  run: ProgramPartsRun,
  boundary: ProgramSetupBoundary,
  startMode: 'continuous' | 'single-block',
): boolean {
  const ctrl = run.controller
  const stopBoundary = (reason: string): boolean => {
    run.advancing = false
    failProgramParts(reason)
    return false
  }

  // WO-1330: A TOOL-CHANGE BOUNDARY WAS ALREADY ASKED THIS, at the completion
  // edge, before the hold and while the retract height still described the tool
  // in the spindle. Asking again here would measure the NEW tool against the
  // OLD tool's number, after the operator has deliberately jogged and set a
  // fresh Z zero - an invented refusal of the very sequence this order exists
  // to allow, and never a fact about where the tool is.
  if (boundary.toolChange === undefined) {
    const refusal = boundaryClearRefusal(ctrl, boundary)
    if (refusal !== null) return stopBoundary(refusal)
  }

  const staged = (selectionStartedAtMs: number): boolean => {
    const firstMove = run.parts[run.partIndex]?.steps.find(isStagedMove)
    if (
      firstMove !== undefined
      && boundary.fromWcs !== boundary.wcs
      && pathFidelitySamples !== null
      && pathFidelityArmed?.kind === 'geometry'
      && pathFidelityArmed.frame === 'work'
    ) {
      // Preserve the instant BEFORE the selection crossed the controller
      // boundary. UCCNC can publish a status in the new frame before its
      // receipt resolves, so a receipt timestamp cannot identify the last
      // outgoing-frame sample. The analyzer finds the observed offset change
      // after this lower bound; no stored G54/G55 value enters the measurement.
      pathFidelityFrameChanges.push({
        atMs: selectionStartedAtMs,
        firstMoveId: firstMove.id,
        fromFrame: boundary.fromWcs,
        toFrame: boundary.wcs,
      })
    }
    store().setActiveWcs(boundary.wcs)
    store().pushConsole(
      'rx',
      `${boundary.wcs} is selected and the tool is clear - running "${boundary.nextName}" in `
      + `${boundary.wcs}.`,
      'info',
    )
    return loadAndStartCurrentPart(run, startMode)
  }

  if (typeof ctrl.selectWcsAwait === 'function') {
    const receiptToken = captureBackendReceipt(ctrl)
    const selectionStartedAtMs = Date.now()
    const receipt = ctrl.selectWcsAwait(boundary.wcs)
    if (receipt === null) {
      return stopBoundary(
        `The controller would not select ${boundary.wcs}, so "${boundary.nextName}" was not started. `
        + 'Nothing moved.',
      )
    }
    void receipt.then((confirmed) => {
      if (!receiptIsCurrent(receiptToken) || programPartsRun !== run) return
      if (!confirmed) {
        stopBoundary(
          `The controller did not confirm ${boundary.wcs}, so "${boundary.nextName}" was not started. `
          + 'Nothing moved.',
        )
        return
      }
      staged(selectionStartedAtMs)
      ctrl.refreshState()
    }).catch((error) => {
      if (!receiptIsCurrent(receiptToken) || programPartsRun !== run) return
      const detail = error instanceof Error ? error.message : String(error)
      stopBoundary(
        `The controller did not confirm ${boundary.wcs} (${detail}), so "${boundary.nextName}" was `
        + 'not started. Nothing moved.',
      )
    })
    // ACCEPTED, NOT FINISHED. `run.advancing` stays set until the receipt
    // arrives, which is what keeps a second completion edge out of here while
    // the controller sits idle waiting for its frame.
    return true
  }

  const selectionStartedAtMs = Date.now()
  if (!ctrl.selectWcs(boundary.wcs)) {
    return stopBoundary(
      `The controller would not select ${boundary.wcs}, so "${boundary.nextName}" was not started. `
      + 'Nothing moved.',
    )
  }
  return staged(selectionStartedAtMs)
}

/** Stage the part `run.partIndex` now points at and release it. The tail of
 *  `advanceProgramPartIfComplete`, split out by WO-1323 so a setup boundary
 *  reaches the controller through the same load-and-start it always did. */
function loadAndStartCurrentPart(
  run: ProgramPartsRun,
  startMode: 'continuous' | 'single-block',
): boolean {
  const restaged = run.restage?.(run.parts[run.partIndex]) ?? run.parts[run.partIndex]
  if (typeof restaged === 'string') {
    run.advancing = false
    failProgramParts(`Program stopped after part ${countedPartsBefore(run, run.partIndex)} of ${countedPartsBefore(run, run.parts.length)}: ${restaged}`)
    return false
  }
  run.parts[run.partIndex] = restaged
  const next = restaged
  // WO-1335: THE FILE'S OWN M3/M5 FALLS DUE HERE, before the part it governs is
  // even staged. This gap - the board idle between two staged parts - is the
  // only instant a geometry route has to command an inverter, so it is where
  // the word is honoured rather than dropped. A STOP goes out first and cannot
  // fail; a START is only ARMED here, because the call that makes it is the one
  // WO-1275's gate holds the motion behind, below.
  const spindleWord = run.spindleWords?.get(run.partIndex)
  if (spindleWord !== undefined) applyGcodeSpindleWord(run, spindleWord)
  const coolantWord = run.coolantWords?.get(run.partIndex)
  if (coolantWord !== undefined) {
    const previous = run.coolantApplied ?? { flood: false, mist: false }
    run.coolantApplied = coolantWord.outputs === undefined
      ? { flood: coolantWord.flood, mist: coolantWord.mist }
      : { flood: coolantWord.flood, mist: coolantWord.mist, outputs: coolantWord.outputs }
    applyGcodeCoolantWord(coolantWord, previous, run.spindleIntent?.rpm ?? 0)
  }
  const outcome = run.controller.loadProgram?.(next)
  if (!outcome?.ok) {
    run.advancing = false
    failProgramParts(
      `Program stopped after part ${countedPartsBefore(run, run.partIndex)} of ${countedPartsBefore(run, run.parts.length)}: `
      + `${outcome?.reason ?? 'the controller refused the next part without giving a reason.'}`,
    )
    return false
  }
  // WO-1275: this is now the board's staged motion, and the next line is what
  // releases it - so the gate must be told what it is releasing BEFORE the
  // start door is touched. Part two of a split program is the cut.
  stagedMotionCuts = programCuts(next)
  // WO-1874: the next part is handed over on "accepted for sending" too, and a
  // board that refuses it goes on holding the part that just finished. This run
  // is over the moment the board says so - the same stop a synchronous refusal
  // above produces, from the answer that used to be discarded.
  const advancingPart = run.partIndex
  watchBoardLoadRefusal(
    run.controller,
    () => programPartsRun === run && run.partIndex === advancingPart,
    (reason) => {
      run.advancing = false
      failProgramParts(
        `Program stopped after part ${countedPartsBefore(run, advancingPart)} of ${countedPartsBefore(run, run.parts.length)}: ${reason}`,
      )
    },
  )
  // The operator can arm Single Block during the automatic handoff as well as
  // at an explicit between-parts hold. In either case, part N+1 enters through
  // the step door so its first line is the only line allowed to execute.
  const releasePart = (): boolean => (
    startMode === 'single-block' || run.controller.singleBlockMode()
      ? run.controller.stepJob()
      : run.controller.startJob()
  )
  // An M3 re-arms WO-1275's gate for the motion behind it, exactly as CYCLE
  // START does: the file said "spin up, then cut", and the cut waits.
  const started = spindleWord?.on === true
    ? runWithGeometryProgramSpindle(run.controller, releasePart)
    : releasePart()
  if (!started) {
    run.advancing = false
    failProgramParts(
      `Program stopped after part ${countedPartsBefore(run, run.partIndex)} of ${countedPartsBefore(run, run.parts.length)}: `
      + 'the controller refused to start the next part.',
    )
    return false
  }
  run.advancing = false
  return true
}

/**
 * WO-1335: HONOUR ONE SPINDLE WORD OF A POSTED FILE.
 *
 * The first round of this order accepted M5 and threw it away, so a file that
 * stopped its spindle and then retracted ran that retract with the inverter
 * still commanded on. The word is executed HERE, in the gap between the part
 * that ends at it and the part its motion starts - the board holds the moves,
 * so this gap is the only instant the app can speak in.
 *
 * ON A MACHINE WITH NO SPINDLE LINK NOTHING IS COMMANDED AND THE WORD IS STILL
 * SAID. The load line already told the operator the spindle is theirs to drive;
 * saying nothing at the line where the file changes it is the silent drop this
 * fix exists to remove.
 */
function applyGcodeSpindleWord(run: ProgramPartsRun, word: GcodeSpindleWord): void {
  const intent = word.intent ?? run.spindleIntent ?? null
  if (intent === null) return
  // THE SPEED THE RUN IS AT NOW, not the one it started at. `run.spindleIntent`
  // was the program's FIRST intent for the whole file, and a configured coolant
  // action line carrying `{rpm}` is substituted from it - so after a permitted
  // second speed the machine was handed the stale first one. A start word moves
  // it; a stop leaves it, because the speed the machine was last running at is
  // what an action line asking for one means.
  if (word.on) run.spindleIntent = { rpm: intent.rpm, direction: intent.direction }
  const name = word.on ? (intent.direction === 'ccw' ? 'M4' : 'M3') : 'M5'
  if (!word.on) {
    if (run.spindleDriven === true) {
      stopGeometryProgramSpindle(run.controller)
      // The intent is RETIRED, not paused: nothing later in this program may
      // re-command it. An M3 further down the file restores it below.
      geometryProgramSpindle = null
      store().pushConsole(
        'rx',
        `Line ${word.line}: ${name} - the spindle is stopped before the next move.`,
        'info',
      )
      return
    }
    store().pushConsole(
      'rx',
      `Line ${word.line}: ${name} - the file stops the spindle here, and this machine has no link to `
      + 'stop it. Stop it at the machine.',
      'warn',
    )
    return
  }
  if (run.spindleDriven === true) {
    geometryProgramSpindle = {
      rpm: intent.rpm,
      direction: intent.direction,
      controller: run.controller,
      running: false,
      saidNoSpindleLink: false,
      commandedAgainstStatus: null,
    }
    // WO-2157: with a probe loaded this word does not start it (the release
    // asks again, fresh, and runs on); the line says so instead.
    const probe = controlLoadedProbe()
    if (probe !== null) {
      probeSpindleSaid.add(geometryProgramSpindle)
      store().pushConsole('rx', `Line ${word.line}: ${name} - ${probeSpindleRefusal(probe)}`, 'info')
      return
    }
    store().pushConsole(
      'rx',
      `Line ${word.line}: ${name} - the spindle is commanded at ${intent.rpm} RPM `
      + `${intent.direction.toUpperCase()}, and the next move waits for it.`,
      'info',
    )
    return
  }
  // NO LINK. The program is ALREADY HELD at this word - the load door made the
  // boundary a hold precisely because the operator has to do this by hand (the
  // audit's second blocking finding: saying "start it at the machine" and then
  // releasing the cut in the same breath is an instruction nobody can carry
  // out). So this line confirms what they were asked to do rather than asking
  // again after the fact.
  store().pushConsole(
    'rx',
    `Line ${word.line}: ${name} - the file runs the next moves at ${intent.rpm} RPM `
    + `${intent.direction.toUpperCase()}, and this machine has no link to start the spindle. Running `
    + 'on with the spindle you started.',
    'warn',
  )
}

/**
 * WO-1335 fix round 3: HONOUR ONE COOLANT WORD OF A POSTED FILE, THROUGH THE
 * COOLANT PATH THIS APP ALREADY HAS.
 *
 * The architect, 2026-09-11T04:23Z, correcting round 2: "SpindlePanel commands
 * Mist/Flood through `runMachineAction`, and it only shows those buttons on a
 * machine that declares the outputs ... So M7/M8/M9 from a file take THAT SAME
 * PATH when the machine record declares the output, and print one console line
 * naming what the file asked for when it does not." Round 2 said there was no
 * non-MDI coolant channel and stopped at the console line; that reasoning was
 * about the BRIDGE PROTOCOL, and the coolant route was never a bridge message -
 * it is the machine's own configured action lines, which is what the button
 * sends.
 *
 * SO THE FILE SENDS WHAT THE BUTTON SENDS. The lines are resolved exactly as
 * SpindlePanel resolves them - this operator's override for this machine, else
 * its declared controller's default - so a flood valve wired to a custom code
 * answers a file the same way it answers the button. Nothing here invents a
 * code and nothing here is hardcoded.
 *
 * THE RECORD DECIDES WHETHER THERE IS ANYTHING TO COMMAND, on Operator's rule for
 * the buttons ("If they do not, don't even show the buttons ... I have no
 * coolant at all"): a channel the machine record does not STATE has no output
 * to switch, so the word is named as the operator's to do and nothing is sent.
 *
 * AND IT IS NAMED EITHER WAY, at the line that states it. A coolant change is
 * the whole reason a section ends where it does; a section that ends for a
 * reason nobody is told about is the silent drop this route exists to remove.
 */
function applyGcodeCoolantWord(
  word: GcodeCoolantWord,
  previous: GcodeCoolantState,
  rpm: number,
): void {
  const asked = describeCoolantAsk(word)
  const outputsNow = word.outputs ?? []
  const outputsBefore = previous.outputs ?? []
  const off = !word.flood && !word.mist && outputsNow.length === 0
  // WHAT THIS WORD CHANGES, not what it restates. An `M8` under a running flood
  // commands nothing a second time; an `M9` stops the channels that were on.
  const changed = COOLANT_WORD_ACTIONS.filter(([channel]) =>
    (off ? previous[channel] : word[channel] && !previous[channel]))
  const machine = controlMachine(useCamStore.getState())
  // WO-1650: THE MACHINE'S OWN LISTED OUTPUTS (a pump on M10, air on M11) go
  // out by their own words, through the one resolver the typed word uses. The
  // shared off word below stops them with everything else.
  if (!off) {
    const turnedOn = outputsNow.filter((code) => !outputsBefore.includes(code))
    const turnedOff = outputsBefore.filter((code) => !outputsNow.includes(code))
    if (turnedOn.length > 0 || turnedOff.length > 0) {
      applyProgramListedOutputs(word.line, machine, turnedOn, turnedOff)
      if (changed.length === 0) return
    }
  }
  // 2026-09-17 at the machine (finding h): on Operator's real definition the file's
  // M7 was told "this machine states no such output" while typed M7 switched
  // pin 16. A controller that switches pins BY CALL answers a file's word the
  // way it answers the typed word - through the one resolver the definition
  // feeds (WO-1637) - not through the HAS IT capability flag, which is a
  // different, older model of the same fact. Text controllers keep the action
  // lines below.
  if (switchProgramOutputWord(word, off, changed.map(([channel]) => channel))) return
  const stated = changed.filter(([channel]) => statedCoolantCapability(machine, channel) === true)
  // An M9 that stops only listed outputs still goes out as the shared stop.
  const stopsListedOutputs = off && outputsBefore.length > 0
  if (stated.length === 0 && !stopsListedOutputs) {
    store().pushConsole(
      'rx',
      `Line ${word.line}: the file switches ${asked} here, and this machine states no such output - `
      + 'switch it at the machine.',
      'warn',
    )
    return
  }
  // M9 IS THE ONLY PHYSICAL STOP and it stops every channel at once - the same
  // rule WO-1058 keeps on the panel - so an off word is ONE `coolantOff`
  // action, never one per channel.
  const actions: BuiltinActionId[] = off
    ? ['coolantOff']
    : stated.map(([, action]) => action)
  const sent: string[] = []
  const refusals: string[] = []
  for (const action of actions) {
    const lines = coolantActionLines(machine, action, rpm)
    if (lines === null) {
      refusals.push(UNDECLARED_CONTROLLER_COOLANT_REASON)
      continue
    }
    const outcome = runProgramOwnAction(lines, action)
    if (outcome.ok) sent.push(lines.join(' then '))
    else refusals.push(outcome.reason)
  }
  if (refusals.length === 0) {
    store().pushConsole(
      'rx',
      `Line ${word.line}: the file switches ${asked} here - sent as ${sent.join(' then ')}.`,
      'info',
    )
    return
  }
  // REFUSED, AND THE REASON THE SESSION GAVE - never an inference, and never a
  // silence. The operator is the fallback, so they are told to be.
  store().pushConsole(
    'rx',
    `Line ${word.line}: the file switches ${asked} here, and it could not be sent `
    + `(${refusals.join('; ')}) - switch it at the machine.`,
    'warn',
  )
}

/**
 * WO-1650: A FILE'S OWN LISTED OUTPUT WORDS, at the line that states them.
 *
 * `turnedOn` / `turnedOff` name outputs by their on word's number. On a
 * controller that switches pins by call, each word is resolved through the
 * definition's one list (`resolveMachineOutputWord`) exactly as the typed word
 * is, and the pins it names are switched. On a text controller the word is
 * the controller's own and goes out as written.
 */
function applyProgramListedOutputs(
  line: number,
  machine: MachineConfig | null | undefined,
  turnedOn: readonly number[],
  turnedOff: readonly number[],
): void {
  const outputs = machine?.controllerDefinition?.outputs ?? []
  const offWordOf = (onCode: number): number | null => {
    const listed = outputs.find((output) => output.onCode === `M${onCode}` && output.offCode !== null)
    const code = listed ? Number(listed.offCode!.slice(1)) : NaN
    return Number.isInteger(code) ? code : null
  }
  const codes = [
    ...turnedOn,
    ...turnedOff.map(offWordOf).filter((code): code is number => code !== null),
  ]
  if (codes.length === 0) return
  const ctrl = getMachineController()
  if (!ctrl.capabilities.gcodeText && typeof ctrl.setOutput === 'function') {
    const said: string[] = []
    for (const code of codes) {
      const resolved = resolveMachineOutputWord(machine, code)
      if (resolved === null) continue
      if (resolved.kind === 'unassigned') {
        store().pushConsole(
          'rx',
          `Line ${line}: the file switches ${resolved.name} with ${resolved.word}, and no pin is assigned to it - `
          + `set ${resolved.setting}, or switch it at the machine.`,
          'warn',
        )
        continue
      }
      for (const sw of resolved.switches) {
        const receipt = switchOutputPin(ctrl, sw)
        if (sw.on && sw.delayMs > 0) holdMotionForOutputOnDelay(sw.delayMs)
        said.push(`${resolved.word} ${describeOutputSwitch(sw)}`)
        void receipt?.then((r) => {
          if (!r.ok && !r.superseded) {
            store().pushConsole('rx', `Line ${line}: ${describeOutputSwitch(sw)} was refused: ${r.reason}`, 'warn')
          }
        })
      }
    }
    if (said.length > 0) store().pushConsole('rx', `Line ${line}: the file switches ${said.join('; ')}.`, 'info')
    return
  }
  const lines = codes.map((code) => `M${code}`)
  const outcome = runProgramOwnAction(lines)
  store().pushConsole(
    'rx',
    outcome.ok
      ? `Line ${line}: the file switches its listed outputs here - sent as ${lines.join(' then ')}.`
      : `Line ${line}: the file switches its listed outputs here, and ${lines.join(' then ')} could not be sent `
        + `(${outcome.reason}) - switch them at the machine.`,
    outcome.ok ? 'info' : 'warn',
  )
}

/** WO-1650: run-from-line and Step Back restore the outputs the ACTIVE
 *  machine's one list names, as well as the dialect's coolant words. */
/** WO-1989: the run-from prelude lifts to this machine's safe Z before any X/Y
 *  move - a G53 machine coordinate, so it is offered only when Z has a datum
 *  this session. Without one the planner lifts to the program's own
 *  clearance height instead. */
export function runFromLineMachineOptions(): { outputs: MachineOutputDefinition[]; safeZMachine: number | null } {
  const machine = controlMachine(useCamStore.getState())
  const config = useMachineActions.getState().configFor(machine?.id ?? 'default')
  const safeZ = machineSafeZValue(parkCarrierMachine(useCamStore.getState()), config)
  const ctrl = getMachineController()
  const zDatum = typeof ctrl.homedThisSession === 'function' && unhomedAxes(ctrl, ['Z']).length === 0
  return {
    outputs: machine?.controllerDefinition?.outputs ?? [],
    safeZMachine: zDatum ? safeZ : null,
  }
}

/** WO-1989 fix round: load a run-from slice, planned with the machine's safe
 *  Z when there is one. That lift is a G53 move, and not every text door
 *  takes G53 inside a loaded program - the native simulator's interpreter
 *  accepts only the words its post emits and refuses the slice. When the
 *  controller refuses the slice that carries the lift, the same start is
 *  planned again with the program's own clearance lift (still before any
 *  X/Y), and the plan returned - the one the card shows - is the one that was
 *  actually loaded.
 *  Audit 3 finding 3: the retry is taken only when the refusal names G53, and
 *  its own result is read. Any refusal that stands - another cause, or a
 *  retry the controller also refuses - comes back as a refusal, so nothing
 *  reports a start armed that the controller never loaded. */
/** WO-2256: the text door's whole program as the controller counted it, so a
 *  slice of it (Run from line, Step Back, a kept stop's return) reads as it. */
let textProgramWhole: { controller: MachineController; programText: string; total: number } | null = null

function loadRunFromSlice(
  ctrl: MachineController,
  programText: string,
  planned: RunFromLinePlan,
  options: RunFromLineOptions,
  replan: (options: RunFromLineOptions) => RunFromLineResult,
  answeredM6Line?: number,
): { ok: true; plan: RunFromLinePlan } | { ok: false; reason: string } {
  // WO-2157: the slice keeps a loaded probe's spindle off from its first line
  // on, and so does the prelude, which restores the spindle before motion.
  let staged = stageRunningM6Holds(programText, planned.startLine)
  if (answeredM6Line !== undefined) {
    const lines = staged.split(/\r?\n/)
    // Send the file's own stop at its original source line, without staging
    // another tool change. Its modal prefix was restored by the prelude.
    lines[answeredM6Line - 1] = stripGcodeComments(programText.split(/\r?\n/)[answeredM6Line - 1])
      .replace(/(?:^|\s)(?:T\d+|M0?6)(?=\s|$)/gi, ' ').trim()
    staged = lines.join('\n')
  }
  const probe = controlLoadedProbe()
  const preludeOf = (plan: RunFromLinePlan): string[] => probe === null
    ? plan.prelude
    : plan.prelude.map((line) => (lineStartsSpindle(line) ? withoutSpindleStart(line) : line))
      .filter((line) => !lineIsEmptyCode(line))
  const refused = (reason: string) => ({
    ok: false as const,
    reason: `The controller would not load the program from line ${planned.startLine}: ${reason}`,
  })
  // Operator's ruling 2026-09-26: what the prelude could not set up is told on
  // the console once the start is armed - information, never a block.
  const armed = (plan: RunFromLinePlan) => {
    answeredTextM6.clear()
    const change = plan.resumeAt?.toolChange
    if (answeredM6Line !== undefined) answeredTextM6.add(answeredM6Line)
    if (change?.done && plan.resumeAt?.line === change.on) answeredTextM6.add(change.on)
    // WO-2256: the slice is counted by the controller from its own first
    // line; the cursor is already the file's line.
    const whole = textProgramWhole
    store().setStagedNumbering(
      whole !== null && whole.controller === ctrl && whole.programText === store().programText
        ? { stagedTotal: ctrl.jobProgress().totalLines, fileTotal: whole.total, stepOf: null, partsBefore: 0, stagedPartsBefore: 0 }
        : null,
    )
    for (const line of plan.notSetUp) store().pushConsole('rx', line, 'warn')
    if (probe !== null && plan.prelude.some(lineStartsSpindle)) sayProbeKeepsSpindleOff(probe)
    return { ok: true as const, plan }
  }
  const outcome = ctrl.loadJobFrom(applyResumeMotion(staged, planned), planned.startLine, preludeOf(planned))
  if (outcome?.ok !== false) return armed(planned)
  const liftRefused = options.safeZMachine != null
    && /\bG0*53\b/i.test(outcome.reason)
    && planned.prelude.some((line) => /\bG0*53\b/i.test(line))
  if (!liftRefused) return refused(outcome.reason)
  const clearanceLift = replan({ ...options, safeZMachine: null })
  if (!clearanceLift.ok) return refused(outcome.reason)
  const retry = ctrl.loadJobFrom(
    applyResumeMotion(staged, clearanceLift.plan),
    clearanceLift.plan.startLine,
    preludeOf(clearanceLift.plan),
  )
  if (retry?.ok === false) return refused(retry.reason)
  return armed(clearanceLift.plan)
}

/** SAFETY (WO-006): a refused (re-)arm must not leave a previously armed
 *  sliced job sendable behind the canonical CYCLE START. Restore the full
 *  program - the same state Cancel produces. When the streamer holds no ready
 *  job (e.g. a guided flow after a controlled stop) nothing is armed, so
 *  nothing is restored. */
function restoreFullProgramIfArmed(ctrl: MachineController, programText: string): void {
  if (ctrl.jobProgress().phase !== 'ready') return
  // WO-1997: the same M6 holds the load staged, or every later M6 runs by.
  ctrl.loadJob(stageRunningM6Holds(programText))
  answeredTextM6.clear()
  textJobFirstLine = 1
  store().setStagedNumbering(null)
  store().applyJobProgress(ctrl.jobProgress())
}

/** The M word each coolant channel is switched by on a pin-switching controller.
 *  WO-1649: the machine's one output list says it - a flood listed on M108 is
 *  M108 - and the standard M7/M8 answers only a machine that lists neither. */
const STANDARD_COOLANT_WORD: Readonly<Record<'flood' | 'mist', number>> = { flood: 8, mist: 7 }
function coolantChannelWord(machine: OutputMachine | null | undefined, channel: 'flood' | 'mist'): number {
  const listed = machineOutputWithRole(machine, channel)
  const code = listed === null ? NaN : Number(listed.onCode.slice(1))
  return Number.isInteger(code) ? code : STANDARD_COOLANT_WORD[channel]
}

/**
 * A file's coolant word on a controller that switches pins by call: the same
 * pins, the same resolver and the same console shape as the typed word
 * (`runMdiOutputWords`). Returns true when this route owned the word (sent, or
 * refused by name because the definition assigns no pin); false hands it to
 * the text-controller action lines. Null from the resolver means the machine
 * names no output for the word at all - also handed on, so the existing
 * "states no such output" sentence stays for that case only.
 */
function switchProgramOutputWord(
  word: GcodeCoolantWord,
  off: boolean,
  channels: readonly ('flood' | 'mist')[],
): boolean {
  const ctrl = getMachineController()
  if (ctrl.capabilities.gcodeText || typeof ctrl.setOutput !== 'function') return false
  const machine = controlMachine(useCamStore.getState())
  const codes = off ? [9] : channels.map((channel) => coolantChannelWord(machine, channel))
  const resolved = codes.map((code) => resolveMachineOutputWord(machine, code))
  // Only a word the definition gives a PIN for is owned here. A UCCNC record
  // with no relay keys resolves M7/M8 as "unassigned"; that machine may still
  // switch its coolant through a configured action line (the WO-1335 route,
  // the operator's own M64 P2 for instance), so it is handed on unchanged.
  if (resolved.length === 0 || !resolved.every((r) => r !== null && r.kind === 'switch')) return false
  // the operator 2026-10-08 (card): the line names the machine's own output and the
  // word that switched it - "Line 5: Vacuum on (M7, port 3 pin 16)." - never
  // the G-code's generic "mist coolant" when this machine's M7 is a vacuum.
  const switches = resolved.flatMap((r, i) => (r && r.kind === 'switch'
    ? r.switches.map((sw) => ({ sw, code: codes[i] }))
    : []))
  const said: string[] = []
  for (const { sw, code } of switches) {
    const receipt = switchOutputPin(ctrl, sw)
    if (sw.on && sw.delayMs > 0) holdMotionForOutputOnDelay(sw.delayMs)
    said.push(describeOutputSwitch(sw, code))
    void receipt?.then((r) => {
      if (!r.ok && !r.superseded) {
        store().pushConsole('rx', `Line ${word.line}: ${describeOutputSwitch(sw)} was refused: ${r.reason}`, 'warn')
      }
    })
  }
  store().pushConsole('rx', `Line ${word.line}: ${said.join('; ')}.`, 'info')
  return true
}

/** The channels a coolant word can switch, paired with the action that switches
 *  each one, in the order the operator reads them. */
const COOLANT_WORD_ACTIONS: readonly (readonly ['flood' | 'mist', BuiltinActionId])[] = [
  ['flood', 'coolantFlood'],
  ['mist', 'coolantMist'],
]

function describeCoolantAsk(word: { flood: boolean; mist: boolean }): string {
  if (word.flood && word.mist) return 'flood and mist coolant on'
  if (word.flood) return 'flood coolant on'
  if (word.mist) return 'mist coolant on'
  return 'coolant off'
}

/** A machine with no declared controller has no default lines to fall back on -
 *  the same answer SpindlePanel gives its own buttons, for the same reason. */
const UNDECLARED_CONTROLLER_COOLANT_REASON =
  'this machine declares no controller, so there is no coolant line to send'

/** THE LINES THE CONTROL PAGE'S OWN BUTTON WOULD SEND for this machine and this
 *  action: the operator's override for this machine, else its declared
 *  controller's default, with the same `{rpm}` substitution the panel applies.
 *  Null when nothing can be resolved without guessing a controller. */
function coolantActionLines(
  machine: MachineConfig | null | undefined,
  action: BuiltinActionId,
  rpm: number,
): string[] | null {
  const config = useMachineActions.getState().configFor(machine?.id ?? 'default')
  const override = config.overrides[action]
  if (override && override.length > 0) return substituteActionLines(override, { rpm })
  const resolution = resolveDeclaredController(machine)
  if (!resolution.ok) return null
  // WO-1649: the machine's own output list decides the word, so a file's
  // coolant line is answered with what THIS machine switches coolant with.
  return substituteActionLines(resolveBuiltinLines(config, resolution.controller, action, machine), { rpm })
}

/**
 * TRUE ONLY WHILE THE RUNNING PROGRAM'S OWN ACCESSORY WORD IS SPEAKING.
 *
 * `sendMdiLine` locks MDI out for the whole length of a running program so the
 * operator cannot type text into a stream. This is neither of those things: the
 * board is IDLE between two staged parts - the same instant
 * `applyGcodeSpindleWord` commands the inverter in - and the line is one the
 * LOADED FILE ITSELF states, resolved from the machine's own wiring. Without
 * this window the file's coolant word would be answered with "A program is
 * running - MDI is locked out" at every coolant line of every file, which is
 * the lockout refusing the program its own words.
 *
 * The window is opened around exactly ONE `runMachineAction` call and closed in
 * a `finally`, so nothing else can travel through it and a throw cannot leave
 * it open. The operator's own MDI is unchanged and still locked out.
 */
let programOwnActionInFlight = false

function runProgramOwnAction(lines: string[], action?: BuiltinActionId): MachineActionResult {
  programOwnActionInFlight = true
  try {
    return runMachineAction(lines, action === undefined ? {} : { action })
  } finally {
    programOwnActionInFlight = false
  }
}

/**
 * THE COOLANT THE FILE HAS ALREADY COMMANDED WHEN ITS FIRST MOVE RUNS - the
 * `M8` in the preamble, which is where every real post puts it.
 *
 * It is not a change BETWEEN two parts, so it does not travel in
 * `coolantWords`; it falls due at the instant the operator releases the first
 * staged motion, which is the only instant at which "coolant on before the cut"
 * means anything. Never at load: a machine sitting loaded is not a machine that
 * should be wet.
 */
let geometryProgramCoolant:
  | { controller: MachineController; word: GcodeCoolantWord; rpm: number }
  | null = null

function applyPendingGeometryProgramCoolant(target: MachineController): void {
  const pending = geometryProgramCoolant
  if (!pending || pending.controller !== target) return
  // ONCE. Cleared before the word is applied so a resume, a step or a second
  // Cycle Start cannot switch the same channel again.
  geometryProgramCoolant = null
  applyGcodeCoolantWord(pending.word, { flood: false, mist: false }, pending.rpm)
}

/**
 * WO-1677: THE TOOL-LENGTH STATE A LOADED FILE ASKS FOR, RESOLVED AGAINST THE
 * MACHINE'S OWN TOOL TABLE. `toolOffsetLine` is the one piece of reference
 * math the tool-length measure and the guided tool change already use: the
 * offset for tool n is its probed length difference to the reference tool,
 * which is what G43.1 applies. A tool the table does not hold, or holds with
 * no measured length, applies ZERO - what UCCNC's and LinuxCNC's tables
 * answer for an unmeasured row - never a refusal.
 */
function resolveG43ToolLengthMm(h: number): { deltaMm: number; measured: boolean } {
  const machine = controlMachine(useCamStore.getState())
  const table = useMachineToolTable.getState().tableFor(machine.id)
  const resolved = toolOffsetLine(table, h)
  return resolved.ok
    ? { deltaMm: resolved.deltaMm, measured: true }
    : { deltaMm: 0, measured: false }
}

/**
 * WO-1677: THE TOOL LENGTH THIS CONTROLLER ALREADY HOLDS IN FORCE IN `wcs`.
 * A geometry controller keeps it folded into that frame's Z offset
 * (`applyGeometryToolLengthOffset`), which the board adds to every staged
 * move - so a loaded file's `G43 H<n>` fold is taken net of it, exactly as a
 * real controller's G43 H replaces an active offset instead of stacking on it.
 */
function toolLengthInForceMm(c: MachineController, wcs: string): number {
  // WO-2037: a G-code-text controller holds it in its own G43.1 register (the
  // TLO row it reports), which it adds to every work Z in every frame.
  if (c.capabilities.gcodeText === true) return c === controller ? (store().tlo ?? 0) : 0
  const applied = geometryToolLengthOffset
  return applied !== null && applied.controller === c && applied.wcs === wcs ? applied.deltaMm : 0
}

/** Return true when an intermediate lifecycle edge was deliberately hidden:
 * the operator owns one program, not one job row per controller-sized part. */
function handleProgramPartJobEvent(event: JobLifecycleEvent, fault: JobFault | null): boolean {
  const run = programPartsRun
  if (
    !run
    && programPartsTerminal?.controller === controller
    && programPartsTerminal.suppressNextControllerTerminal
    && (event === 'stopped' || event === 'failed')
  ) {
    programPartsTerminal.suppressNextControllerTerminal = false
    return true
  }
  if (!run || run.controller !== controller) return false
  if (event === 'started') {
    // WO-2560: a same-frame section may start without crossSetupBoundary.
    // The controller's started event refreshes the collapsed console; an
    // accepted start request alone is not confirmation. The boundary receipt remains
    // in its history rather than masquerading as the current section.
    const first = run.parts[run.partIndex]?.steps[0]?.id
    const listing = store().stagedProgram
    if (first !== undefined && listing && listing.setups.length > 1) {
      const file = currentFileDoorProgram()
      const sourceSection = file?.runFrom?.numbering.sectionOf?.(
        file.lineOfStep(first) ?? file.runFrom.numbering.startLine,
      )
      const listedFirst = store().stagedNumbering?.stepOf?.(first) ?? first
      const firstIndex = listing.program.steps.findIndex((step) => step.id === listedFirst)
      const section = sourceSection === undefined || sourceSection === null ? listing.setups.reduce((current, candidate) =>
        listing.program.steps.findIndex((step) => step.id === candidate.firstStepId)
          <= firstIndex ? candidate : current) : listing.setups[sourceSection]
      store().pushConsole('rx', `${section.setupName} (${section.wcs}) started.`, 'info')
    }
    const intermediate = run.started
    run.started = true
    return intermediate
  }
  if (event === 'completed' && run.partIndex < run.parts.length - 1) {
    run.completionSignaled = true
    advanceProgramPartIfComplete()
    return true
  }
  if (event === 'completed') {
    clearProgramClampPauseForRun(run)
    programPartsRun = null
    programPartsTerminal = null
    return false
  }
  if (event === 'stopped' || event === 'failed') {
    const reason = event === 'failed'
      ? `Program parts ended on a controller fault: ${fault?.message ?? 'no reason was reported.'}`
      : 'Program parts ended; no later part was loaded.'
    endProgramParts(reason, event, fault, event === 'stopped' ? 'info' : 'error', false)
    return true
  }
  return false
}

// ---- WO-415: active work offset follows acknowledged G5x words ----

const WCS_WORD = /\bG0*5([4-9])(?![.\d])/gi

/** The LAST G54..G59 word on one g-code line (comments stripped), or null. */
export function wcsWordInLine(line: string): WcsId | null {
  const text = stripGcodeComments(line)
  let found: WcsId | null = null
  for (const m of text.matchAll(WCS_WORD)) found = `G5${m[1]}` as WcsId
  return found
}

function programLinesForWcsScan(): string[] {
  const text = store().programText
  if (text !== wcsScanText) {
    wcsScanText = text
    wcsScanLines = text ? text.split(/\r?\n/) : []
  }
  return wcsScanLines
}

/** Scan the program lines acknowledged since the last call (cursor ->
 *  ackedSourceLine) and mirror the last G5x word into activeWcs. Prelude lines
 *  of a run-from arm carry sourceLine 0; the program text up to the start
 *  line is what that prelude re-established, so it is scanned as a whole. */
function followStreamedWcs(ackedSourceLine: number): void {
  if (ackedSourceLine <= 0) return
  if (ackedSourceLine < wcsScanSourceLine) wcsScanSourceLine = 0
  if (ackedSourceLine === wcsScanSourceLine) return
  const lines = programLinesForWcsScan()
  let wcs: WcsId | null = null
  for (let i = wcsScanSourceLine; i < ackedSourceLine && i < lines.length; i++) {
    const w = wcsWordInLine(lines[i])
    if (w) wcs = w
  }
  wcsScanSourceLine = ackedSourceLine
  if (wcs) store().setActiveWcs(wcs)
}

/**
 * Send one manual (MDI / macro) line. Same refusals as the controller's
 * sendCommand; when the line carries a G54..G59 word, its ack flips
 * activeWcs so the Position chip and Work Offsets table follow a typed G5x
 * exactly as they follow the Work Offsets "Select" button.
 */
export function sendMdiLine(text: string, typedRowId?: number): boolean {
  publishNonProgramActionStatus(null)
  // WO-2263: the Control page already put this submission above its replies.
  // Scope dedupe to this dispatch, including a later kept-stop dispatch: two
  // separately typed identical lines must retain their own rows and sends.
  const beforeId = store().consoleLines.at(-1)?.id ?? -1
  // WO-2519: a line typed in a kept stop reads as the MDI line it is.
  if (controller !== null) nameKeptStopCommand(controller, 'MDI')
  const sent = dispatchMdiLine(text, typedRowId)
  if (typedRowId !== undefined && store().consoleLines.some((row) => row.id === typedRowId)) {
    useMachineControl.setState((s) => ({
      consoleLines: s.consoleLines.filter((row) =>
        row.id <= beforeId || row.dir !== 'tx' || row.text !== text,
      ),
    }))
  }
  return sent
}

function dispatchMdiLine(text: string, typedRowId?: number): boolean {
  const ctrl = getMachineController()
  // WO-1635 safety round 2: THE E-STOP DOOR. See `mdiLineMayPassEstopLatch`.
  if (estopNeedsReset() && !mdiLineMayPassEstopLatch(text, ctrl)) {
    return refuseMdiLine(text, ESTOP_BLOCKS_MOTION)
  }
  // WO-2002: THE ALARM DOOR. See `mdiLineRefusedByAlarm`.
  if (mdiLineRefusedByAlarm(text, ctrl)) return refuseMdiLine(text, MDI_ALARM_REFUSAL)
  // WO-2146: THE PROBE DOOR. See `mdiLineWaitsForProbeCycle`.
  if (mdiLineWaitsForProbeCycle(text, ctrl)) return holdMdiLineForProbeCycle(text)
  // WO-2437 fix round 4 (desk kit rehearsal): a controller with no text
  // interpreter runs MDI as a staged program, which replaced the program held
  // at the clamp pause. There the line runs as the controller's own calls -
  // the route the park itself takes - and the held program stays.
  if (ctrl === controller && programClampPauseTakesMdi() && !ctrl.capabilities.gcodeText) {
    const unsent = appCommandUnsentHere(ctrl, text)
    if (unsent !== null) return refuseMdiLine(text, unsent)
    return sendAppCommandAwait(text, ctrl) !== null
  }
  // WO-1335 fix round 3: the LOADED FILE'S OWN accessory word is not the
  // operator typing into a stream - see `programOwnActionInFlight`, which is
  // open only around one action call in the idle gap between two staged parts.
  if ((hasActiveProgramJob(ctrl) || keptStopTakingFor(ctrl)) && !programOwnActionInFlight && !programBoundaryMacroSending
    && !(ctrl === controller && programClampPauseTakesMdi())) {
    // WO-2237: in a pause the line runs - after the pause becomes a kept stop.
    if (commandThroughKeptStop(ctrl, 'MDI', () => { sendMdiLine(text, typedRowId) })) return true
    store().pushConsole('tx', 'A program is running - MDI is locked out.', 'error')
    return false
  }
  let mdiWords = tokenizeLine(text, 1).words
  // WO-1680: an M-code bound to one of the user's macros runs that macro's
  // body - typed, or from another line - the same body its button runs.
  const macro = mdiBoundMacro(mdiWords)
  if (macro !== null) {
    store().pushConsole('tx', text, 'info')
    return runUserMacro(macro)
  }
  // WO-2657: a macro hidden from the Macros panel is off - one line says so,
  // and the code goes on as if no macro were bound (M8 to the controller).
  // A code that is ONLY a macro call (M2010 on UCCNC) stops at that one line:
  // falling through drew a second, false refusal - "this route does not run
  // macros" - right after the shown macro had run (machine seat zk, 10-07).
  const hiddenMacro = mdiHiddenMacro(mdiWords)
  if (hiddenMacro !== null) {
    const table = mdiWordTable()
    const onlyAMacro = table !== null && hiddenMacro.mCode !== undefined && isGcodeMacroMCode(table, hiddenMacro.mCode)
    store().pushConsole('rx', `${hiddenMacroNotRunText(hiddenMacro)}${onlyAMacro ? ' Nothing on this line was sent.' : ''}`, 'info')
    if (onlyAMacro) return false
  }
  // WO-2239: a tool line typed in a kept stop - the return cuts with that tool.
  const typedTool = typedToolChange(mdiWords)
  const toolStop = keptStopForTypedTool(ctrl, typedTool)
  if (toolStop !== null && typedTool !== null && !ctrl.capabilities.gcodeText) {
    const taken = runKeptStopToolChangeOnBoard(text, ctrl, toolStop, typedTool)
    if (taken !== null) return taken
  }
  // WO-2521: the same tool line with no program to stop (10-03 F9) - the same
  // park, prompt, measure and offset. Never a line a program sends itself.
  // A G-code text controller takes only the typed M6 here (the desk simulator,
  // Operator ruling 10-06 7:20 PM): the session already runs a program's M6 there. A typed
  // T or M61 Q on a text controller still goes to the controller, as before.
  if (toolStop === null && typedTool !== null && (!ctrl.capabilities.gcodeText || typedTool.kind === 'm6')
    && !hasActiveProgramJob(ctrl) && !programOwnActionInFlight && !programBoundaryMacroSending) {
    const taken = runIdleToolChangeOnBoard(text, ctrl, typedTool, mdiWords)
    if (taken !== null) return taken
  }
  // WO-2157: THE SPINDLE-ON WORD, WITH A PROBE LOADED. Typed, a macro's line, a
  // configured spindle action or the pendant - every one arrives here. The
  // M3/M4 (and its S) is not sent and one line says why; the rest of the line
  // still runs, and a line that was only the spindle start is done.
  if (lineStartsSpindle(text)) {
    const probe = controlLoadedProbe()
    if (probe !== null) {
      sayProbeKeepsSpindleOff(probe)
      text = withoutSpindleStart(text, { speed: true })
      if (lineIsEmptyCode(text)) return true
      mdiWords = tokenizeLine(text, 1).words
    }
  }
  // GRBL owns its G30 register and reports it through $#; preserve the text
  // route it had before WO-1362. UCCNC has no such register, and the simulator
  // exercises that app-owned workflow, so those backends still resolve/store
  // the machine-definition point here.
  const controllerOwnsG30 = supportsGrblSettings(ctrl)
  if (!controllerOwnsG30 && mdiCodes(mdiWords, 'G').includes(30.1)) {
    return storeG30ReferencePoint(text, mdiWords, ctrl)
  }
  if (!controllerOwnsG30 && mdiCodes(mdiWords, 'G').includes(30)) {
    return runMdiGeometryLine(text, ctrl)
  }
  // WO-1336: A CONTROLLER WHOSE WIRE TAKES NO TEXT STILL OBEYS AN MDI LINE.
  // Everything below this branch is the TEXT route and is unchanged; a
  // geometry controller takes the line through the interpreter instead, which
  // is the only difference between a box labelled MDI that works and one that
  // answers every line with "this controller takes geometry, not G-code text".
  //
  // WO-1635: CONFIGURED MACHINE ACTIONS TOO. A macro button's line and the
  // Flood / Mist buttons used to keep the text path here, so on UCCNC every
  // one of them was refused by a wire that can never take text - a refusal
  // that was ours, not the controller's (rule 11). They now take the same
  // translation as a typed line; a word the board has no call for is refused
  // BY WORD, naming what it would take. A text controller never reaches here.
  if (!ctrl.capabilities.gcodeText) {
    return runMdiGeometryLine(text, ctrl)
  }
  // WO-1677: A PURE TYPED `G43 H<n>` IS APP-OWNED ON A TEXT CONTROLLER TOO.
  // The table it indexes is the machine's own store - GRBL-class controllers
  // keep no controller-side tool table, so the controller's own vocabulary
  // refuses the word - and the app answers it through the same Apply call the
  // TLO panel uses, exactly as G30.1 is app-owned above. A line carrying
  // anything more (`G43 H3 G0 Z10`) stays with the controller's own reader.
  if (isPureG43HLine(mdiWords)) return runMdiWords(text, mdiWords, ctrl)
  const wcs = wcsWordInLine(text)
  if (!wcs) return noteKeptStopToolTyped(ctrl, toolStop, typedTool, ctrl.sendCommand(text))
  const pending = ctrl.sendCommandAwait(text)
  if (!pending) return false
  const receiptToken = captureBackendReceipt(ctrl)
  void pending.then((ack) => {
    if (!receiptIsCurrent(receiptToken)) return
    if (ack.ok) store().setActiveWcs(wcs)
  })
  return true
}

/** The user macro a lone typed M-code is bound to, or null (WO-1680; WO-1681:
 *  a park is one of these macros, so a bound M-code resolves through this
 *  one list - there is no separate park lookup any more). */
function mdiBoundMacro(words: readonly GcodeWord[]): MachineMacro | null {
  const code = mdiLoneMCode(words)
  return code === null ? null : boundMacro(code)
}

/** WO-2657: the hidden macro a lone typed M-code would have run, or null. */
function mdiHiddenMacro(words: readonly GcodeWord[]): MachineMacro | null {
  const code = mdiLoneMCode(words)
  return code === null ? null : hiddenBoundMacro(code)
}

function mdiLoneMCode(words: readonly GcodeWord[]): number | null {
  const said = words.filter((w) => w.letter !== 'N')
  if (said.length !== 1 || said[0].letter !== 'M' || Number.isNaN(said[0].value)) return null
  return said[0].value
}

/** WO-1680: resolve once the machine reports Idle with no job - on the NEXT
 *  status report, never a cached one, so a line just sent has had its chance
 *  to start moving. False when the connection or controller is gone or the
 *  machine alarms. A user macro waits on this between its lines. */
export async function awaitMachineSettled(): Promise<boolean> {
  const ctrl = getMachineController()
  const gone = () => controller !== ctrl || ctrl.connectionPhase() !== 'connected'
  while (!gone()) {
    const state = await nextMachineState(1000)
    if (gone() || state === 'alarm') return false
    if (state === 'idle' && !ctrl.hasActiveJob()) return true
  }
  return false
}

/** WO-2255 (B-3): resolve true once `reached()` holds on a report that reads Idle with no job; false once the machine
 *  has read Idle with no job, NOT at the target, for `graceMs` without a report of motion in between (a move that
 *  starts a poll late resets the clock), or when the connection or controller is gone or the machine alarms. */
export async function awaitMachineArrived(reached: () => boolean, graceMs: number): Promise<boolean> {
  const ctrl = getMachineController()
  const gone = () => controller !== ctrl || ctrl.connectionPhase() !== 'connected'
  let idleAwaySince: number | null = null
  while (!gone()) {
    const state = await nextMachineState(Math.min(graceMs, 1000))
    if (gone() || state === 'alarm') return false
    const idle = ctrl.machineState() === 'idle' && !ctrl.hasActiveJob()
    if (idle && reached()) return true
    if (!idle || (state !== null && state !== 'idle')) { idleAwaySince = null; continue }
    const now = Date.now()
    if (idleAwaySince === null) idleAwaySince = now
    else if (now - idleAwaySince >= graceMs) return false
  }
  return false
}

/** The macro list with its first position macro moved to `point` (its name
 *  and M-code kept), or a new "Park 1" position macro made at the front when
 *  the list has none yet (WO-1681, replacing WO-1670's park-list version). */
function withFirstPositionMacroAt(macros: readonly MachineMacro[], point: MachineReferencePosition): MachineMacro[] {
  const index = macros.findIndex((macro) => parsePositionMacroBody(macro.body) !== null)
  if (index === -1) {
    return [
      { id: `park-${Date.now().toString(36)}`, name: 'Park 1', body: positionMacroBody({ ...point, zFirst: true }) },
      ...macros,
    ]
  }
  const fields = parsePositionMacroBody(macros[index].body)!
  return macros.map((macro, i) => (
    i === index ? { ...macro, body: positionMacroBody({ ...fields, ...point }) } : macro
  ))
}

/** G30.1 is an app-owned machine-definition write. UCCNC exposes no G30
 * register, so forwarding the word would claim a point was stored when the
 * controller has nowhere to keep it. The reported machine position is the
 * value; the active machine record is the durable carrier. */
function storeG30ReferencePoint(
  text: string,
  words: readonly GcodeWord[],
  ctrl: MachineController,
): boolean {
  store().pushConsole('tx', text, 'info')
  const lexical = mdiLexicalRefusal(text)
  if (lexical !== null) return refuseMdiLine(text, lexical)
  const conflict = mdiCategoryConflict(words)
  if (conflict !== null) return refuseMdiLine(text, conflict)
  const unaccounted = words.filter((word) => !(
    (word.letter === 'N' && !Number.isNaN(word.value))
    || (word.letter === 'G' && word.value === 30.1)
  ))
  if (unaccounted.length > 0) {
    const spelled = mdiSpelling(unaccounted[0])
    return refuseMdiLine(
      text,
      `${spelled} cannot be combined with G30.1. G30.1 stores point 1 only, at the current machine position; nothing was stored.`,
    )
  }
  if (ctrl.connectionPhase() !== 'connected') {
    return refuseMdiLine(text, 'not connected to a machine, so point 1 was not stored.')
  }
  const home = homingRefusal(
    ctrl,
    ['X', 'Y', 'Z'],
    'G30.1 cannot store a machine-frame point until every axis has a datum.',
  )
  if (home !== null) return refuseMdiLine(text, home)
  const position = ctrl.status().machinePos
  if (!position || ![position.x, position.y, position.z].every(Number.isFinite)) {
    return refuseMdiLine(
      text,
      'the controller has not reported a complete current machine position, so point 1 was not stored.',
    )
  }

  const cam = useCamStore.getState()
  const active = controlMachine(cam)
  const carrier = cam.machineLibrary.find((machine) => machine.id === active.id)
    ?? (cam.project.machine.id === active.id ? cam.project.machine : null)
  if (carrier === null) {
    return refuseMdiLine(text, `the active machine ${active.name} has no editable definition record, so point 1 was not stored.`)
  }
  const point: MachineReferencePosition = { x: position.x, y: position.y, z: position.z }
  // WO-1681: on a machine with a macro list, point 1 IS its first position
  // macro, so G30.1 moves that macro (or makes one) rather than a point the
  // list hides.
  const update: Partial<MachineConfig> = carrier.macros !== undefined
    ? { macros: withFirstPositionMacroAt(carrier.macros, point) }
    : { referencePositions: { ...machineReferencePositions(carrier), 1: point } }
  if (cam.machineLibrary.some((machine) => machine.id === active.id)) {
    cam.updateMachineInLibrary(active.id, update)
  }
  if (cam.project.machine.id === active.id) {
    cam.setProjectMachine({ ...cam.project.machine, ...update })
  }
  mdiSaid(
    text,
    `stored reference point 1 at ${formatPosition({ machine: point })}.`,
    'info',
  )
  return true
}

// ---- WO-1336: MDI runs a line of G-code on a geometry controller ----------
//
// Operator, at the machine 2026-09-11: "Have we ever tested MDI to confirm the
// controller obeys g-code sent via the MDI?" The same minute, typing `M5` into
// the MDI box on his AXBB-E answered:
//
//   [RED] sendCommand: This controller takes geometry, not G-code text -
//   nothing was loaded. Refused text: M5
//
// That refusal was WO-1021's, and it was honest about the WIRE: the UC100 API
// takes segments and the bridge has no interpreter. It is not what an operator
// expects from a box labelled MDI, and it is no longer necessary, because
// WO-1335 built the interpreter that turns posted text into the staged program
// this board already runs.
//
// AN MDI LINE IS A ONE-LINE PROGRAM. The same dialect, the same refusals by
// word, the same geometry queue, the same gates. Nothing is special-cased for
// MDI except that it is one line and it runs on Enter:
//
//  - MOTION goes through `loadGcodeTextToolpathProgram` - WO-1335's own door,
//    not a copy of it - so the travel check, the arc-extent check, the board's
//    move ceiling, the frame receipt and the up-to-speed gate are the SAME code
//    a posted file passes through, and `startMachineJob` applies the homing
//    refusal every program start already obeys. There is no second interpreter
//    and no second set of gates that could drift.
//  - A FRAME WORD selects through `selectWcsAwait`, with the receipt, and the
//    active-WCS chip follows it - WO-1312's mechanism, the same one the Work
//    Offsets "Select" button uses.
//  - A SPINDLE WORD goes through `commandSpindle`, the same call the program
//    route uses, so the inverter runs at the definition's own setpoint word and
//    the quiet-stop watchdog watches it.
//  - ANYTHING ELSE is refused BY WORD, on the console, in one line.
//
// A LINE RUNS WHOLE OR NOT AT ALL, and the rule that produces that is NOT an
// enumeration of bad pairs. Two audits failed this route on the same class
// because it listed the conflicts it knew about - a start combined with a stop,
// two frames - and every unlisted pair fell through into dispatch, which then
// picked CCW for `M3 M4` and the FIRST speed for `M3 S1000 S2000`: a spindle
// turning the opposite way from the word the operator typed. An enumeration of
// bad pairs is never complete. The question is not "is this pair in conflict?"
// but "DOES THIS LINE STATE EACH THING AT MOST ONCE?", which is complete by
// construction because every word the tokenizer can produce belongs to exactly
// one category (`mdiCategoryOf` - a known group, or a category of its own):
//
//   spindle direction  M3 M4 M5      at most one of them
//   spindle speed      S<n>          at most one, or identical repeats
//   coolant            M7 M8 M9      at most one
//   work offset        G54-G59       at most one
//   ... and every other category the line can carry, by the same test.
//
// Two words of one category that are not the same word refuse the WHOLE line,
// naming both words and the category, BEFORE anything is dispatched - at the
// one place the line is accepted, not inside dispatch, because a check that
// runs after the first word has gone is not this rule. Identical repeats state
// one thing twice and are accepted (`S1000 S1000`).
//
// Two further refusals sit beside it, and neither is a same-category pair:
//  - A word this route will not ACT ON refuses the whole line (`M3 S18000 M8`
//    would otherwise start the spindle and drop the coolant word; `M5 S1000`
//    would stop the spindle and drop the speed), because the operator reads one
//    green console row for a line half of which never happened.
//  - A frame word WITH a spindle word: each alone is honoured, together they
//    cannot be, because the frame is only confirmed by the controller after the
//    spindle word would already have gone.
//
// A motion line passes the same category test and then goes to the shared
// reader, which reads the whole block and refuses an unsupported word itself.
//
// WO-1636: MODAL STATE IS HELD FROM LINE TO LINE, as a controller holds it.
// G20/G21/G90/G91 (and the fixed G17/G40/G80/G94) are the same modal state the
// app-command translator holds per controller (`appCommandModal`); a motion
// line is read against it, so `G91` then `G0 X10` moves 10 from where the tool
// is. G10 L2/L20 and G43.1/G49 go to the offsets table's and the TLO panel's
// own calls - see `runMdiControllerCall`.

/** The motion words this route stages. Anything else carrying an axis word
 *  reaches the interpreter anyway and is refused there, by word and by line. */
const MDI_MOTION_G: ReadonlySet<number> = new Set([0, 1, 2, 3])

/** What a category of words IS, for the sentence that refuses a line stating it
 *  twice. `key` is the identity two words are grouped by. */
interface MdiCategory {
  key: string
  /** Completes "<A> and <B> ...". */
  verb: string
  /** Completes "Type one ... per line." */
  noun: string
}

/** WO-1644: WHICH WORDS ARE ONE QUESTION is the word table's modal group. This
 *  map only says each group in a sentence; a group it does not name is said
 *  from the table's own group name. */
const MDI_GROUP_SENTENCES: ReadonlyMap<string, Omit<MdiCategory, 'key'>> = new Map([
  ['spindle', { verb: 'each command the spindle direction', noun: 'spindle direction word' }],
  ['coolant', { verb: 'each set the coolant', noun: 'coolant word' }],
  ['program flow', { verb: 'each end or pause the program', noun: 'program-flow word' }],
  ['motion', { verb: 'each select a motion mode', noun: 'motion word' }],
  ['work offset', { verb: 'each select a work offset', noun: 'work offset' }],
  ['distance', { verb: 'each set the distance mode', noun: 'distance-mode word' }],
  ['plane', { verb: 'each select a plane', noun: 'plane word' }],
  ['units', { verb: 'each set the units', noun: 'units word' }],
  ['feed rate', { verb: 'each set the feed-rate mode', noun: 'feed-rate-mode word' }],
  ['tool length offset', { verb: 'each set the tool length offset', noun: 'tool-length-offset word' }],
])

/** The word table of the dialect the machine declares - the same table, read
 *  the same way, as the file door's reader reads. Null when the machine
 *  declares no controller this app has a table for. */
function mdiWordTable(): GcodeWordTable | null {
  const machine = useCamStore.getState().project.machine
  const dialect = gcodeTableDialectOf(machine?.controller)
  return dialect === null ? null : gcodeWordTableForMachine(gcodeWordTable(dialect), machine)
}

/** The modal group a G or M word belongs to in the table, as a category. */
function mdiTableCategory(word: GcodeWord): MdiCategory | null {
  if ((word.letter !== 'G' && word.letter !== 'M') || Number.isNaN(word.value)) return null
  const table = mdiWordTable()
  const entry = table === null ? null : gcodeWordEntry(table, word.letter, word.value)
  if (entry === null || entry.modalGroup === null) return null
  const said = MDI_GROUP_SENTENCES.get(entry.modalGroup)
    ?? { verb: `each set the ${entry.modalGroup}`, noun: `${entry.modalGroup} word` }
  return { key: `${entry.letter}:${entry.modalGroup}`, ...said }
}

/** Letters that name one quantity each, so a second one of them is a second
 *  answer regardless of what the line is doing. */
const MDI_CATEGORY_LETTERS: ReadonlyMap<string, Omit<MdiCategory, 'key'>> = new Map([
  ['S', { verb: 'each set the spindle speed', noun: 'S speed' }],
  ['F', { verb: 'each set the feed rate', noun: 'F feed rate' }],
  ['T', { verb: 'each select a tool', noun: 'T tool number' }],
  ['N', { verb: 'each number this line', noun: 'N line number' }],
])

/** A word as the operator spelled it, normalised so `S1000` and `S1000.0` are
 *  the SAME statement and not a conflict. */
function mdiSpelling(word: GcodeWord): string {
  return Number.isNaN(word.value) ? word.letter : `${word.letter}${mdiNumber(word.value)}`
}

/**
 * THE CATEGORY A WORD BELONGS TO - total, so no word can fall through.
 *
 * A known group, a letter that names one quantity, or a category of the word's
 * own, in which case only an IDENTICAL repeat can collide with it. That last
 * fallback is what makes the rule complete: a word nobody listed still gets
 * tested, it simply only conflicts with itself.
 */
function mdiCategoryOf(word: GcodeWord): MdiCategory {
  const spelling = mdiSpelling(word)
  const group = mdiTableCategory(word)
  if (group !== null) return group
  const byLetter = MDI_CATEGORY_LETTERS.get(word.letter)
  if (byLetter !== undefined) return { key: word.letter, ...byLetter }
  if (word.letter === 'G' || word.letter === 'M') {
    // A G or M word nobody grouped is keyed by its own spelling, so the only
    // thing that can share its category is an identical repeat - which states
    // one thing twice and is accepted. The sentence is therefore never reached;
    // it exists so the category is total rather than optional.
    return { key: spelling, verb: 'are the same word', noun: `${spelling}` }
  }
  // "an X value", "a Y value" - by how the LETTER is said, not how it is spelt.
  const article = 'AEFHILMNORSX'.includes(word.letter) ? 'an' : 'a'
  return {
    key: word.letter,
    verb: `each give this line ${article} ${word.letter} value`,
    noun: `${word.letter} word`,
  }
}

/**
 * ONE UNAMBIGUOUS COMMAND PER CATEGORY, OR THE LINE IS REFUSED.
 *
 * Returns the refusal sentence for the FIRST category this line states twice
 * with two different words, or null if every category it carries is stated at
 * most once. Nothing is dispatched until this has returned null.
 */
function mdiCategoryConflict(words: readonly GcodeWord[]): string | null {
  const seen = new Map<string, GcodeWord>()
  for (const word of words) {
    const category = mdiCategoryOf(word)
    const first = seen.get(category.key)
    if (first === undefined) {
      seen.set(category.key, word)
      continue
    }
    if (mdiSpelling(first) === mdiSpelling(word)) continue
    return `${mdiSpelling(first)} and ${mdiSpelling(word)} ${category.verb}, and only one of them `
      + `could be obeyed, so nothing on this line was sent. Type one ${category.noun} per line.`
  }
  return null
}

/** The G or M codes on one typed line, in the order they were typed. */
function mdiCodes(words: readonly GcodeWord[], letter: 'G' | 'M'): number[] {
  return words.filter((w) => w.letter === letter && !Number.isNaN(w.value)).map((w) => w.value)
}

/** A number as the operator typed it rather than as a float prints: `10`, not
 *  `10.000`, and `-1.5` still `-1.5`. */
function mdiNumber(value: number): string {
  return Number(value.toFixed(4)).toString()
}

/** One console row for what the line BECAME. The row above it is the line as
 *  typed, pushed before anything reaches the wire. */
function mdiSaid(text: string, became: string, severity: 'info' | 'error'): void {
  store().pushConsole(severity === 'error' ? 'tx' : 'rx', `MDI ${text}: ${became}`, severity)
}

function refuseMdiLine(text: string, became: string): false {
  mdiSaid(text, became, 'error')
  return false
}

/** The linter's findings that judge a PROGRAM or a BLOCK rather than the
 *  characters typed: whether it ends, whether it opens with a motion mode,
 *  whether the spindle was started before the first feed, whether an arc
 *  carries its centre. A typed line is one block and not a program - MDI
 *  supplies the `M30` itself in `stageMdiMotion` - and what a block MEANS is
 *  the shared reader's to say, not this list's. Only the lexical verdict is
 *  taken, which is why this names what to DROP rather than what to keep: a
 *  lexical check added to `lintGcode` tomorrow guards MDI the same day. */
const MDI_PROGRAM_SHAPED_LINT = new Set([
  'NO_PROGRAM_END',
  'NO_INITIAL_MOTION_MODE',
  'COORD_WITHOUT_MOTION_MODE',
  'SPINDLE_NOT_STARTED',
  'ARC_NO_CENTER',
  'ARC_R_AND_IJK',
])

/** Is every character of this typed line g-code the shared linter can read? If
 *  not, the sentence saying so; a valid parenthesised comment is code and reads
 *  clean. `paren` is the comment style of every dialect this project posts
 *  (base, GRBL, UCCNC), and is the style the program door lints against. */
function mdiLexicalRefusal(text: string): string | null {
  const finding = lintGcode(text, { commentStyle: 'paren' }).find(
    (f) => f.level === 'error' && !MDI_PROGRAM_SHAPED_LINT.has(f.code),
  )
  if (finding === undefined) return null
  return `${finding.message} A typed line is read by the same linter as a loaded program, and part of `
    + 'this one is not g-code at all. Nothing on this line was sent.'
}

/**
 * ONE TYPED LINE, ON A CONTROLLER WHOSE WIRE TAKES GEOMETRY.
 *
 * The line as typed is echoed first, so the console shows what was asked for
 * even when the answer is a refusal; the second row says what it became.
 */
function runMdiGeometryLine(text: string, ctrl: MachineController): boolean {
  store().pushConsole('tx', text, 'info')
  if (ctrl.connectionPhase() !== 'connected') {
    return refuseMdiLine(text, 'not connected to a machine, so nothing was sent.')
  }

  const words = tokenizeLine(text, 1).words

  // ONE UNAMBIGUOUS COMMAND PER CATEGORY, OR THE LINE IS REFUSED. This is the
  // one place the line is ACCEPTED, so it is the one place the test can run:
  // after this, every category the line carries is stated at most once, and no
  // dispatch below can silently drop a second answer to a question the operator
  // already answered. It runs before the motion branch too - `G0 G1 X10` and
  // `G0 X10 X20` are as ambiguous as `M3 M4`.
  const conflict = mdiCategoryConflict(words)
  if (conflict !== null) return refuseMdiLine(text, conflict)

  // WO-1644: A WORD THE DIALECT'S TABLE DOES NOT CARRY is refused before
  // anything is sent, with the table's own sentence - the one the file door's
  // reader gives the same word.
  const unknown = mdiTableRefusal(words)
  if (unknown !== null) return refuseMdiLine(text, unknown)

  // WO-1644: A MIXED LINE RUNS WORD BY WORD, IN CONTROLLER ORDER. A line that
  // moves is one block for the shared reader, which already applies its words
  // in that order; a line that does not is split into the calls its words go
  // to and each runs as a line of its own.
  const parts = mdiControllerOrderParts(words)
  if (parts !== null) {
    const lexical = mdiLexicalRefusal(text)
    if (lexical !== null) return refuseMdiLine(text, lexical)
    return runMdiParts(text, parts, ctrl)
  }
  return runMdiWords(text, words, ctrl)
}

/**
 * WO-1644: THE ORDER A CONTROLLER APPLIES ONE BLOCK'S WORDS IN (RS-274NGC, as
 * UCCNC and LinuxCNC run it): spindle, then coolant and outputs, then plane /
 * units / distance and the other held modes, then tool length offset, then
 * the work offset, then an offset write.
 */
const MDI_PART_ORDER = ['spindle', 'outputs', 'modal', 'tlo', 'frame', 'offset-write'] as const
type MdiPart = typeof MDI_PART_ORDER[number]

/** The parts a non-motion line splits into, in controller order - or null when
 *  it is one part, moves (the reader orders a motion block), or carries a word
 *  no part owns (the whole line is then judged, and refused, as before). */
function mdiControllerOrderParts(words: readonly GcodeWord[]): string[] | null {
  const gs = mdiCodes(words, 'G').map(mdiG)
  const offsetWrite = gs.includes(10)
  const dynamicTlo = gs.includes(43.1)
  if (offsetWrite && dynamicTlo) return null
  if (!offsetWrite && mdiWordsStageAProgram(words)) return null
  if (offsetWrite && gs.some((g) => MDI_MOTION_G.has(g) || g === 28 || g === 30 || g === 4)) return null
  const machine = controlMachine(useCamStore.getState())
  const byPart = new Map<MdiPart, GcodeWord[]>()
  for (const word of words) {
    if (word.letter === 'N') continue
    if (Number.isNaN(word.value)) return null
    let part: MdiPart | null = null
    if (word.letter === 'S') part = 'spindle'
    else if (word.letter === 'M') {
      if (MDI_SPINDLE_M.has(word.value)) part = 'spindle'
      else if (resolveMachineOutputWord(machine, word.value) !== null) part = 'outputs'
    } else if (word.letter === 'G') {
      const g = mdiG(word.value)
      if (g === 10) part = 'offset-write'
      else if (g === 43.1 || g === 49) part = 'tlo'
      else if (Number.isInteger(g) && g >= 54 && g <= 59) part = 'frame'
      else if (APP_COMMAND_HELD_G.has(g)) part = 'modal'
    } else if (offsetWrite && 'LPXYZABC'.includes(word.letter)) part = 'offset-write'
    else if (dynamicTlo && word.letter === 'Z') part = 'tlo'
    if (part === null) return null
    byPart.set(part, [...(byPart.get(part) ?? []), word])
  }
  if (byPart.size <= 1) return null
  return MDI_PART_ORDER
    .filter((part) => byPart.has(part))
    .map((part) => byPart.get(part)!.map(mdiSpelling).join(' '))
}

/** Run each part as a line of its own, in order; the first that is refused
 *  stops the rest, and the row says what had already gone. */
function runMdiParts(text: string, parts: readonly string[], ctrl: MachineController): boolean {
  // BETWEEN TWO PARTS OF A RUNNING PROGRAM a frame or offset change is refused
  // (see `runMdiWords`); that refusal is asked FIRST, so nothing earlier in
  // the line has gone when it comes.
  // The same for an output word with no pin assigned, or no output call to
  // switch one with: known before anything is sent, so asked before anything is.
  const preflight = parts.filter((part) => {
    if (programOwnActionInFlight && /^G(?:5[4-9]|10|43\.1|49)(?:\s|$)/.test(part)) return true
    const outputs = mdiOutputResolutions(tokenizeLine(part, 1).words)
    return outputs !== null
      && (outputs.some((r) => r.kind === 'unassigned') || typeof ctrl.setOutput !== 'function')
  })
  for (const blocked of preflight) {
    if (!runMdiWords(blocked, tokenizeLine(blocked, 1).words, ctrl)) {
      mdiSaid(text, `stopped at ${blocked}; nothing on this line was sent.`, 'error')
      return false
    }
  }
  const ran: string[] = []
  for (const part of parts) {
    if (!runMdiWords(part, tokenizeLine(part, 1).words, ctrl)) {
      const already = ran.length === 0
        ? 'nothing on this line was sent'
        : `${ran.join(', then ')} had already been sent`
      mdiSaid(text, `stopped at ${part}; ${already}.`, 'error')
      return false
    }
    ran.push(part)
  }
  mdiSaid(text, `run word by word in controller order: ${parts.join(', then ')}.`, 'info')
  return true
}

/** WO-1644: the table's sentence for the first G or M word on the line the
 *  dialect's table does not carry - null when it carries every one (a word the
 *  machine definition points at an output that is not one of the dialect's own
 *  standard words, a user macro in the table's range, and the numbered
 *  digital-output words, which have a sentence of their own, are not the
 *  table's to refuse). */
function mdiTableRefusal(words: readonly GcodeWord[]): string | null {
  const table = mdiWordTable()
  if (table === null) return null
  const machine = controlMachine(useCamStore.getState())
  for (const word of words) {
    if ((word.letter !== 'G' && word.letter !== 'M') || Number.isNaN(word.value)) continue
    if (word.letter === 'M' && (MDI_OUTPUT_WORDS.has(word.value)
      || (resolveMachineOutputWord(machine, word.value) !== null
        && gcodeWordEntry(builtInGcodeWordTable(table.dialect), 'M', word.value) === null))) continue
    const sentence = gcodeWordRefusalIfAbsent(table, word.letter, word.value)
    if (sentence !== null) return `${sentence} Nothing on this line was sent.`
  }
  return null
}

/** One typed line (or one part of one), after the whole line was accepted. */
function runMdiWords(text: string, words: readonly GcodeWord[], ctrl: MachineController): boolean {
  const gs = mdiCodes(words, 'G')
  const ms = mdiCodes(words, 'M')

  // WO-1636: a work-offset write, a tool-length offset, or a line of modal
  // words alone - each goes to the call that already carries it.
  const call = runMdiControllerCall(text, words, gs, ctrl)
  if (call !== null) return call

  if (mdiWordsStageAProgram(words)) {
    const between = programOwnActionBetweenParts(text)
    if (between !== null) return between
    return stageMdiMotion(text, text)
  }

  // EVERY CHARACTER THE OPERATOR TYPED IS READ, NOT ONLY THE WORDS.
  //
  // `tokenizeLine` RECORDS address words and silently IGNORES every other
  // character, so `M5 #` arrives below as the single word `M5`: the accounting
  // sees nothing left over, stops the spindle, and never mentions the `#`. That
  // is the same half-executed line, through a door the word accounting cannot
  // see.
  //
  // A MOTION LINE IS ALREADY READ CHARACTER BY CHARACTER, by the shared reader
  // it goes to above: `tokenizeStrict` refuses `token "#" is not understood`
  // before a move is built (`reader.ts:275`), which is why this gate sits BELOW
  // the motion branch rather than above it. Putting it above would make the
  // linter a second authority on a line the reader already judges, and the two
  // do not agree in every corner (the reader carries `H` and reads `;` as a
  // comment). Below the motion branch there is no reader at all - that is the
  // hole, and `lintGcode` is asked for the lexical verdict it already gives the
  // program door: a stray character, an unknown address letter, a letter with
  // no number, or an unbalanced comment refuses the LINE.
  const lexical = mdiLexicalRefusal(text)
  if (lexical !== null) return refuseMdiLine(text, lexical)

  // WO-1637: OUTPUT WORDS - M7/M8/M9 and every word the machine definition
  // points at an output - switch the pins the definition names.
  const outputs = runMdiOutputWords(text, words, ctrl)
  if (outputs !== null) return outputs

  // THE WHOLE LINE IS ACCOUNTED FOR, WORD BY WORD, BEFORE ANYTHING IS SENT.
  // A motion line goes to the shared reader above, which reads the WHOLE block
  // and refuses an unsupported word by name. Below it there is no reader, so
  // the accounting is done here: every word the line carries must be one the
  // dispatch below will actually act on. Otherwise the line is refused ENTIRE.
  // Executing the word that was recognised and dropping the rest is the one
  // outcome this route must never have - the operator reads one green row and
  // reasonably believes the line they typed ran.
  const frames = gs.filter((g) => Number.isInteger(g) && g >= 54 && g <= 59)
  const spindleMs = ms.filter((m) => m === 3 || m === 4 || m === 5)
  // A SPEED BELONGS TO A START. `M5 S1000` stops the spindle and the S is not
  // acted on by anything - the same silent drop, so the same whole-line refusal.
  const starts = spindleMs.some((m) => m === 3 || m === 4)
  const unaccounted = words.filter((w) => !mdiWordIsActedOn(w, frames.length > 0, spindleMs.length > 0, starts))
  if (unaccounted.length > 0) return refuseMdiWord(text, unaccounted)

  // Two frames and a start-plus-stop are same-category conflicts, refused by
  // `mdiCategoryConflict` above. A frame and a spindle word on one line never
  // reach here (WO-1644): they are split and run in controller order, spindle
  // first, by `runMdiParts`.

  // WO-1635 safety: BETWEEN TWO PARTS OF A RUNNING PROGRAM, NO FRAME CHANGE.
  // The next part was read in the frame the file selected; a configured action
  // the program asked for (its own coolant word) must not re-frame it. The
  // spindle words below stay allowed there, as before.
  if (frames.length > 0 && programOwnActionInFlight) {
    return refuseMdiLine(
      text,
      mdiFrameBetweenPartsMessage(mdiNumber(frames[0])),
    )
  }

  const wcs = frames.length === 1 ? wcsWordInLine(text) : null
  if (wcs !== null) return selectMdiWcs(text, wcs, ctrl)

  if (spindleMs.length > 0) return commandMdiSpindle(text, spindleMs, words, ctrl)

  // ANYTHING ELSE, BY WORD. The first word this route cannot honour is the one
  // the operator has to change, so it is the one named.
  if (words.length === 0) return refuseMdiLine(text, 'carries no G-code word at all.')
  return refuseMdiWord(text, words)
}

/** Is this word one the dispatch below will ACT ON? `N` is a line number the
 *  shared reader also carries and ignores. Everything else has to be a word of
 *  the category actually being dispatched - an `S` speed belongs to a spindle
 *  start, and on a line with no spindle word it is not acted on by anything. */
function mdiWordIsActedOn(
  word: GcodeWord,
  hasFrame: boolean,
  hasSpindle: boolean,
  hasSpindleStart: boolean,
): boolean {
  if (word.letter === 'N' && !Number.isNaN(word.value)) return true
  if (hasFrame && word.letter === 'G' && Number.isInteger(word.value)
    && word.value >= 54 && word.value <= 59) return true
  if (hasSpindle && word.letter === 'M'
    && (word.value === 3 || word.value === 4 || word.value === 5)) return true
  // A SPEED IS ONLY ACTED ON BY A START. `M5` does not carry one anywhere.
  if (hasSpindleStart && word.letter === 'S' && !Number.isNaN(word.value)) return true
  return false
}

/** WO-1635: the numbered digital-output words. A machine definition points an
 *  output at an M-code, never at a number, so these are refused by name rather
 *  than by the generic sentence. `{pin}` is the line's own P word. (M7/M8/M9
 *  and every defined output word are switched - `runMdiOutputWords`.) */
const MDI_OUTPUT_WORDS: ReadonlyMap<number, string> = new Map([
  [62, 'switches digital output{pin} on with the next move'],
  [63, 'switches digital output{pin} off with the next move'],
  [64, 'switches digital output{pin} on'],
  [65, 'switches digital output{pin} off'],
])

/** The spindle words stay the spindle call's; their relays (when a profile
 *  assigns them) are switched beside it, never instead of it. */
const MDI_SPINDLE_M: ReadonlySet<number> = new Set([3, 4, 5])

/** WO-1637: this line's output words, resolved against the active machine -
 *  null unless every significant word is an M word the definition makes an
 *  output word (N words aside). Spindle words are never taken here. */
function mdiOutputResolutions(words: readonly GcodeWord[]) {
  const significant = words.filter((w) => w.letter !== 'N')
  if (significant.length === 0) return null
  if (!significant.every((w) => w.letter === 'M' && !MDI_SPINDLE_M.has(w.value))) return null
  const machine = controlMachine(useCamStore.getState())
  const resolved = significant.map((w) => resolveMachineOutputWord(machine, w.value))
  if (resolved.some((r) => r === null)) return null
  return resolved.filter((r) => r !== null)
}

/** WO-1637, the E-STOP door: a line whose every word switches outputs OFF is a
 *  stop (M9, an accessory's own off word), and passes the latch like M5/M9. */
function mdiLineOnlySwitchesOutputsOff(text: string): boolean {
  const bare = text.replace(/\([^()]*\)/g, '').replace(/;.*$/, '')
  if (/[^A-Za-z0-9.\s-]/.test(bare)) return false
  const resolved = mdiOutputResolutions(tokenizeLine(bare, 1).words)
  return resolved !== null
    && resolved.every((r) => r.kind === 'switch' && r.switches.every((s) => !s.on))
}

/**
 * WO-1637: ONE LINE OF OUTPUT WORDS, ON A CONTROLLER THAT SWITCHES PINS BY CALL.
 *
 * The pins come from `resolveMachineOutputWord` and from nowhere else. A word
 * whose use case has no pin assigned refuses the WHOLE line, naming the setting
 * to fill in, before anything is sent. Otherwise every pin goes out through the
 * controller's one `setOutput`, and the board's readback is reported. An ON
 * word's on-delay holds the next motion release (`releaseAfterOutputOnDelay`),
 * as UCCNC waits before motion resumes.
 */
function runMdiOutputWords(
  text: string,
  words: readonly GcodeWord[],
  ctrl: MachineController,
): boolean | null {
  const resolved = mdiOutputResolutions(words)
  if (resolved === null) return null
  const unassigned = resolved.find((r) => r.kind === 'unassigned')
  if (unassigned !== undefined && unassigned.kind === 'unassigned') {
    return refuseMdiLine(
      text,
      `${unassigned.word} switches ${unassigned.name}, and this machine definition assigns it no pin - `
      + `fill in ${unassigned.setting}. Nothing on this line was sent.`,
    )
  }
  const switches = resolved.flatMap((r) => (r.kind === 'switch' ? r.switches : []))
  if (typeof ctrl.setOutput !== 'function') {
    return refuseMdiLine(text, 'this controller has no output call to switch a pin with. Nothing was sent.')
  }
  const pending: Array<Promise<string | null>> = []
  for (const sw of switches) {
    const receipt = switchOutputPin(ctrl, sw)
    if (receipt === null) {
      pending.push(Promise.resolve(`${describeOutputSwitch(sw)} was not sent - not connected`))
      continue
    }
    pending.push(receipt.then((r) => {
      if (!r.ok) return r.superseded ? null : `${describeOutputSwitch(sw)} was refused: ${r.reason}`
      if (r.confirmation === 'superseded') return null
      if (r.confirmation === 'confirmed') return `${describeOutputSwitch(sw)} (controller readback confirmed)`
      if (r.readback === null || r.readback.on === null) {
        return `${describeOutputSwitch(sw)} (write accepted; the controller could not confirm the requested state)`
      }
      return `${describeOutputSwitch(sw)} (write accepted; controller readback remained `
        + `${r.readback.on ? 'on' : 'off'}, so the requested state is unconfirmed)`
    }))
  }
  const delayMs = switches.reduce((most, sw) => (sw.on ? Math.max(most, sw.delayMs) : most), 0)
  if (delayMs > 0) holdMotionForOutputOnDelay(delayMs)
  const receiptToken = captureBackendReceipt(ctrl)
  void Promise.all(pending).then((results) => {
    if (!receiptIsCurrent(receiptToken)) return
    const said = results.filter((line): line is string => line !== null)
    if (said.length === 0) return
    const failed = said.some((line) => / was refused: | was not sent - |, but the board reads it /.test(line))
    const wait = delayMs > 0 ? `; motion waits ${mdiNumber(delayMs)} ms (the definition's on-delay)` : ''
    mdiSaid(text, `${said.join('; ')}${failed ? '' : wait}.`, failed ? 'error' : 'info')
  })
  return true
}

/**
 * WO-2668: EVERY OUTPUT THIS SESSION SWITCHES GOES OUT HERE, AND ITS READBACK
 * IS KEPT HERE - the one source a Control button lights from. Found at the
 * machine 2026-10-07: MDI M7 read back "Vacuum on ... (controller readback
 * confirmed)" while the Vacuum button stayed dark, because the button lit from
 * its own remembered press. The button, MDI, a macro, a program line and a
 * spindle relay all switch through this, so whoever switched the pin, the
 * state is the board's answer: confirmed is the requested state; unconfirmed is
 * whatever the board last read (unknown when it could not say); superseded
 * leaves it to the newer command; a refused write changed nothing we know.
 */
const outputPinWrites = new Map<string, number>()

function switchOutputPin(ctrl: MachineController, sw: MachineOutputSwitch): Promise<OutputSwitchReceipt> | null {
  const receipt = ctrl.setOutput?.({ port: sw.pin.port, pin: sw.pin.pin, on: sw.on, negate: sw.pin.negate ?? false }) ?? null
  if (receipt === null) return null
  const key = outputPinKey(sw.pin)
  outputPinWrites.set(key, (outputPinWrites.get(key) ?? 0) + 1)
  const token = captureBackendReceipt(ctrl)
  void receipt.then((r) => {
    if (!receiptIsCurrent(token) || !r.ok || r.confirmation === 'superseded') return
    store().setOutputPin(key, r.confirmation === 'confirmed' ? sw.on : r.readback?.on ?? null)
  })
  return receipt
}

/**
 * WO-2668: READ BACK THE PINS A CONTROL BUTTON SHOWS, after an edge that may
 * have switched outputs without this session sending the word: a new
 * connection, Stop/Reset, an E-STOP trip or its reset, a job's end. Only pins a
 * mounted button watches are read (`watchOutputPins`) - nothing on screen asks,
 * nothing goes on the wire. A read that crosses a newer write to its pin is
 * dropped: the write's own receipt owns that pin. Debounced so one edge that
 * fires several hooks reads once, after the controller has had its moment.
 * The watch registry is `outputPinWatch.ts`; this is its reader.
 */
const OUTPUT_PIN_REFRESH_DELAY_MS = 250
let outputPinRefreshTimer: ReturnType<typeof setTimeout> | null = null

function scheduleOutputPinRefresh(): void {
  if (watchedOutputPins().length === 0) return
  if (outputPinRefreshTimer !== null) clearTimeout(outputPinRefreshTimer)
  outputPinRefreshTimer = setTimeout(() => {
    outputPinRefreshTimer = null
    readOutputPins(watchedOutputPins())
  }, OUTPUT_PIN_REFRESH_DELAY_MS)
}

function readOutputPins(pins: readonly PinRef[]): void {
  const ctrl = getMachineController()
  if (!canReadOutputPins(ctrl) || ctrl.connectionPhase() !== 'connected') return
  const token = captureBackendReceipt(ctrl)
  for (const pin of pins) {
    const key = outputPinKey(pin)
    const writes = outputPinWrites.get(key) ?? 0
    const pending = ctrl.readOutput({ port: pin.port, pin: pin.pin, negate: pin.negate ?? false })
    void pending?.then((readback) => {
      if (!receiptIsCurrent(token) || (outputPinWrites.get(key) ?? 0) !== writes) return
      store().setOutputPin(key, readback?.on ?? null)
    })
  }
}

setOutputPinReader(readOutputPins)

function describeOutputSwitch(sw: MachineOutputSwitch, mWord?: number): string {
  const word = mWord === undefined ? '' : `M${mWord}, `
  return `${sw.name} ${sw.on ? 'on' : 'off'} (${word}port ${sw.pin.port} pin ${sw.pin.pin}${sw.pin.negate ? ', inverted' : ''})`
}

/** WO-1637: WHEN AN OUTPUT'S ON-DELAY LETS MOTION GO. One timestamp, one timer:
 *  a release asked for before it passes waits for it. Both are cleared with the
 *  spindle's up-to-speed wait (`cancelSpindleSpeedWait`), which every stop,
 *  pause, E-STOP, disconnect and terminal job edge already calls. */
let outputOnDelayUntilMs = 0
let outputOnDelayTimer: ReturnType<typeof setTimeout> | null = null

function holdMotionForOutputOnDelay(delayMs: number): void {
  outputOnDelayUntilMs = Math.max(outputOnDelayUntilMs, sessionElapsedNowMs() + delayMs)
}

function cancelOutputOnDelayHold(): void {
  if (outputOnDelayTimer !== null) clearTimeout(outputOnDelayTimer)
  outputOnDelayTimer = null
}

function releaseAfterOutputOnDelay(
  target: MachineController,
  release: () => boolean,
  onLateRefusal: () => void,
): boolean {
  const waitMs = outputOnDelayUntilMs - sessionElapsedNowMs()
  if (waitMs <= 0) return release()
  cancelOutputOnDelayHold()
  store().pushConsole('rx', `Motion waits ${Math.ceil(waitMs)} ms for the output on-delay the machine definition sets.`, 'info')
  outputOnDelayTimer = setTimeout(() => {
    outputOnDelayTimer = null
    // RE-ASKED AT THE MOMENT OF RELEASE: a latched E-STOP or a lost link since
    // the switch releases nothing.
    if (estopNeedsReset() || getMachineController() !== target || target.connectionPhase() !== 'connected') {
      store().pushConsole('rx', 'The motion held for the output on-delay was not released.', 'warn')
      onLateRefusal()
      return
    }
    if (!release()) onLateRefusal()
  }, waitMs)
  return true
}

/** WO-1635 safety round 2 - THE ONE RULE AT THE MDI DOOR UNDER A LATCHED E-STOP.
 *  Operator ruling 2026-09-14: every E-STOP forces CLEAR; ALL motion is off and refused
 *  until CLEAR. While `estopNeedsReset()`, a line - typed MDI or any unit of a
 *  configured action, on every controller - leaves only if it holds nothing but
 *  stop words: M5, M9, S0, N words, comments and whitespace. It is an ALLOWLIST
 *  read off the raw text, deliberately not a list of move words: G28, G55, G20,
 *  T1 M6 and any word no reader knows are all "something else".
 *
 *  One exception, text controllers only (architect ruling on this round): a
 *  GRBL `$` line or `?` that cannot move the machine - `$$`, `$#`, `$G`, `$I`,
 *  `$N`, `$X`, `$C`, `$SLP`, `$RST=` - still goes; refusing a read or an unlock
 *  is a refusal the software does not need (rule 11). `$H` / `$Hx` (homing)
 *  and `$J=` (jog) move, and are refused. */
function mdiLineMayPassEstopLatch(text: string, ctrl: MachineController): boolean {
  const bare = text
    .replace(/\([^()]*\)/g, '')
    .replace(/;.*$/, '')
    .replace(/\s+/g, '')
    .toUpperCase()
  if (/^(?:N\d+|M0*[59]|S(?:0+(?:\.0*)?|\.0+))*$/.test(bare)) return true
  if (!ctrl.capabilities.gcodeText) return mdiLineOnlySwitchesOutputsOff(text)
  if (bare === '?') return true
  return bare.startsWith('$') && !/^\$[HJ]/.test(bare)
}

/** WO-2146 - THE PROBE DOOR. Operator ruling 2026-09-28 (card "MDI typed during a tool
 *  measure"): "Yes - hold MDI until the measure finishes". Pin rehearsal that
 *  morning: `G53 G0 Z110` typed during Tools > Measure T19 went out during the
 *  measure's last lift, the machine went to Z 110 instead of the crossing
 *  height, a red Path check followed and T19 was not recorded.
 *
 *  While a probe routine holds the probe lock - a tool measure (Tools > Measure,
 *  Probing > Tool Z, the guided M6), a Z0, an edge or feature cycle, a routine,
 *  a surface mesh - from its first move to its last lift, a line through the
 *  MDI door (typed, a macro's, a configured button's) is not sent: the routine
 *  owns the machine until it ends. The routine's own lines never come here
 *  (`probeCycleSend` / the controller's probe and jog calls). A line holding
 *  nothing but stop words (M5, M9, S0, an output switched off) still goes - it
 *  cannot move the machine, and a stop is never held back. */
function mdiLineWaitsForProbeCycle(text: string, ctrl: MachineController): boolean {
  if (!probeCycleActive) return false
  const bare = text
    .replace(/\([^()]*\)/g, '')
    .replace(/;.*$/, '')
    .replace(/\s+/g, '')
    .toUpperCase()
  if (/^(?:N\d+|M0*[59]|S(?:0+(?:\.0*)?|\.0+))*$/.test(bare)) return false
  return ctrl.capabilities.gcodeText || !mdiLineOnlySwitchesOutputsOff(text)
}

/** One plain line, not red: the routine is still running, nothing was sent. */
function holdMdiLineForProbeCycle(text: string): false {
  const routine = activeProbeCycle?.routine ?? 'A probe routine'
  store().pushConsole(
    'tx',
    `MDI ${text}: not sent - ${routine} is still running, its last lift included. `
      + 'Nothing was sent or queued; send the line again once it has finished.',
    'warn',
  )
  return false
}

export const MDI_ALARM_REFUSAL = 'the machine is in alarm, so the controller cannot run this line now. '
  + 'Nothing was sent or queued, and nothing will run on Unlock. Clear the alarm, then send the line again.'

/** WO-2002 - THE ONE RULE AT THE MDI DOOR DURING AN ALARM.
 *
 *  Readiness walk, 2026-09-25: on the simulator a `G0` typed during a limit
 *  alarm was accepted - the simulator queued the move behind the alarm - and it
 *  RAN when the operator pressed Unlock. On the UCCNC bridge the same line
 *  went out as `loadMoves` + `startJob` to a board in alarm and the row said
 *  "staged and started". A controller in alarm cannot run a line; GRBL answers
 *  one with error:9 and UCCNC holds the board in reset. So while the connected
 *  controller reports `alarm`, a line that MOVES or STARTS anything is refused
 *  at once, by name, and nothing of it is sent, staged or queued:
 *    - any motion, dwell, probe, homing-reference or canned-cycle G word;
 *    - any axis word not read as a register value (G10 / G92 / G43.1 / G28.1 /
 *      G30.1) - `X10` alone moves in the held motion mode;
 *    - a spindle start (M3 / M4) or a non-zero S;
 *    - every M word except M5 and M9 and an output's own OFF word (M6, M7, M8,
 *      an output ON word, M0/M1/M2/M30 and any other code the door does not
 *      know is harmless);
 *    - on a text controller, a `$J=` jog.
 *  Everything else ACTS NOW and cannot run later, so it still goes: the stop
 *  words, units / distance / plane / frame / offset words, F, T, a `?`, and
 *  every other `$` line - `$X` and `$H` are GRBL's own ways out of an alarm.
 *  Refusing those would be a refusal the software does not need (rule 11).
 *
 *  A latched E-STOP is also an alarm; the E-STOP door is asked first and names
 *  the latch. A macro bound to an M-code runs line by line through this same
 *  door, so its first line that moves is refused and the macro ends there. */
function mdiLineRefusedByAlarm(text: string, ctrl: MachineController): boolean {
  if (ctrl.connectionPhase() !== 'connected' || ctrl.machineState() !== 'alarm') return false
  const bare = text
    .replace(/\([^()]*\)/g, '')
    .replace(/;.*$/, '')
    .replace(/\s+/g, '')
    .toUpperCase()
  if (ctrl.capabilities.gcodeText && (bare === '?' || bare.startsWith('$'))) return /^\$J/.test(bare)
  const words = tokenizeLine(text, 1).words
  const gs = mdiCodes(words, 'G').map(mdiG)
  if (gs.some((g) => MDI_MOTION_G.has(g) || g === 4 || g === 28 || g === 30
    || (g >= 38 && g < 39) || (g >= 73 && g <= 89 && g !== 80))) return true
  const axesAreValues = gs.some((g) => g === 10 || g === 92 || g === 43.1 || g === 28.1 || g === 30.1)
  for (const word of words) {
    if (Number.isNaN(word.value)) continue
    if (!axesAreValues && 'XYZABCUVWIJKR'.includes(word.letter)) return true
    if (word.letter === 'S' && word.value !== 0) return true
    if (word.letter === 'M' && word.value !== 5 && word.value !== 9
      && !mdiLineOnlySwitchesOutputsOff(`M${mdiNumber(word.value)}`)) return true
  }
  return false
}

/** Does this line stage a PROGRAM on a geometry controller - a move (motion
 *  word, G30 or any axis word) or a G4 dwell? Everything else is dispatched as
 *  a call of its own or refused by word. */
function mdiWordsStageAProgram(words: readonly GcodeWord[]): boolean {
  if (mdiCodes(words, 'G').some((g) => MDI_MOTION_G.has(g) || g === 28 || g === 30 || g === 4)) return true
  return words.some((w) => 'XYZABCIJKR'.includes(w.letter) && !Number.isNaN(w.value))
}

/** A configured action the running program itself asked for (its own coolant
 *  word, between two staged parts) may not stage a program: the board holds
 *  ONE, and staging this would replace the part that is running. */
function programOwnActionBetweenParts(label: string): false | null {
  if (!programOwnActionInFlight) return null
  return refuseMdiLine(
    label,
    MDI_ACTION_BETWEEN_PARTS_MESSAGE,
  )
}


const mdiG = (value: number): number => Math.round(value * 10) / 10

/** A line whose every significant word is `G43` and its H index - a
 *  tool-length call of its own. One carrying anything else (`G43 H3 G0 Z10`)
 *  is a motion block and stays with the route that reads motion. */
function isPureG43HLine(words: readonly GcodeWord[]): boolean {
  const significant = words.filter((w) => w.letter !== 'N')
  const codes = significant.filter((w) => w.letter === 'G').map((w) => mdiG(w.value))
  return codes.includes(43) && !codes.includes(43.1)
    && significant.length > 0
    && significant.every((w) =>
      (w.letter === 'G' && mdiG(w.value) === 43) || (w.letter === 'H' && !Number.isNaN(w.value)))
}

/**
 * WO-1636: A TYPED WORD WHOSE CALL ALREADY EXISTS GOES TO THAT CALL.
 *
 *  - modal words alone      -> the held modal state (`appCommandModal`), which
 *                              the modal chip reads and every later MDI move is
 *                              read against;
 *  - `G10 L2` / `G10 L20`   -> `readWorkOffsetLine` + `runWorkOffsetLine`, the
 *                              native `setWorkOffset` write every app-issued
 *                              offset line takes;
 *  - `G43.1 Z..` / `G49`    -> `applyToolLengthOffset` / `clearToolLengthOffset`,
 *                              the TLO panel's own Apply / Clear calls;
 *  - `G43 H<n>` alone       -> the same Apply call, with the length the
 *                              machine's tool table holds for tool n
 *                              (WO-1677 - the file route resolves the same
 *                              word against the same table).
 *
 * Null when the line is none of these, so the caller carries on.
 */
function runMdiControllerCall(
  text: string,
  words: readonly GcodeWord[],
  gs: readonly number[],
  ctrl: MachineController,
): boolean | null {
  const codes = gs.map(mdiG)
  const offsetWrite = codes.includes(10)
  const significant = words.filter((w) => w.letter !== 'N')
  const lengthOffset = codes.includes(43.1) || codes.includes(49) || isPureG43HLine(words)
  const modalOnly = significant.length > 0
    && significant.every((w) => w.letter === 'G' && APP_COMMAND_HELD_G.has(w.value))
  if (!offsetWrite && !lengthOffset && !modalOnly) return null

  const lexical = mdiLexicalRefusal(text)
  if (lexical !== null) return refuseMdiLine(text, lexical)

  if (modalOnly) {
    const outcome = reportAppCommand(ctrl, translateAppCommand(ctrl, significant.map(mdiSpelling).join(' ')))
    if (!outcome.ok) return refuseMdiLine(text, outcome.message ?? 'the modal state was not changed.')
    const modal = outcome.modal ?? appCommandModal(ctrl)
    mdiSaid(
      text,
      `held - ${modal.units === 'inch' ? 'inch (G20)' : 'millimetres (G21)'}, `
      + `${modal.distanceMode === 'incremental' ? 'incremental (G91)' : 'absolute (G90)'} for the lines `
      + 'that follow. Nothing moves.',
      'info',
    )
    return true
  }

  // BETWEEN TWO PARTS OF A RUNNING PROGRAM the next part was read against the
  // offsets as they stand - the same reason a frame change is refused there.
  if (programOwnActionInFlight) {
    return refuseMdiLine(
      text,
      'this line changes a work or tool length offset, and it was asked for between two parts of the '
      + 'running program - the next part was read against the offsets as they stand. Nothing on this '
      + 'line was sent.',
    )
  }
  if (offsetWrite && lengthOffset) {
    return refuseMdiLine(
      text,
      'G10 writes a work offset and G43.1/G49 sets the tool length offset; MDI runs one of those at a '
      + 'time. Nothing on this line was sent; type them on separate lines.',
    )
  }
  return offsetWrite
    ? runMdiWorkOffsetWrite(text, ctrl)
    : runMdiToolLengthOffset(text, significant, codes, ctrl)
}

/** `G10 L2` / `G10 L20` - the one native offset write app-issued lines take. */
function runMdiWorkOffsetWrite(text: string, ctrl: MachineController): boolean {
  const plan = readWorkOffsetLine(ctrl, text)
  if (plan === null) return refuseMdiLine(text, 'not connected to a machine, so nothing was sent.')
  if ('refusal' in plan) {
    const reason = plan.refusal.startsWith(`${text}: `) ? plan.refusal.slice(text.length + 2) : plan.refusal
    return refuseMdiLine(text, reason)
  }
  if (plan.write === null && plan.select === null) {
    return refuseMdiLine(text, 'G10 names no X, Y, Z, A, B or C value, so there is no offset to write. Nothing was sent.')
  }
  const write = plan.write
  void runWorkOffsetLine(ctrl, text, plan).then((outcome) => {
    // A refusal is already on the console, naming the line (`reportWorkOffsetLine`).
    if (!outcome.ok) return
    const values = write === null
      ? ''
      : `${write.wcs} ${(Object.keys(write.values) as Array<keyof MachinePosition>)
        .map((axis) => `${axis.toUpperCase()} ${axis === 'x' || axis === 'y' || axis === 'z' ? machineLengthText(write.values[axis]!) : mdiNumber(write.values[axis]!)}`).join(' ')} written`
    const selected = plan.select === null ? '' : `${plan.select} is the active work offset`
    mdiSaid(text, `${[values, selected].filter((part) => part !== '').join('; ')}.`, 'info')
  })
  return true
}

/** `G43.1 Z..` / `G49` - the TLO panel's Apply / Clear calls. The Z is in the
 *  held units, as it would be on a controller that reads the line itself.
 *  `G43 H<n>` resolves tool n's length from the machine's tool table and goes
 *  to the same Apply call (WO-1677). */
function runMdiToolLengthOffset(
  text: string,
  words: readonly GcodeWord[],
  codes: readonly number[],
  ctrl: MachineController,
): boolean {
  const apply = codes.includes(43.1)
  const applyH = !apply && codes.includes(43)
  const stray = words.find((w) => !(
    (w.letter === 'G' && (mdiG(w.value) === 43.1 || mdiG(w.value) === 49 || mdiG(w.value) === 43))
    || (apply && w.letter === 'Z' && !Number.isNaN(w.value))
    || (applyH && w.letter === 'H' && !Number.isNaN(w.value))
  ))
  if (stray !== undefined) {
    return refuseMdiLine(
      text,
      `${mdiSpelling(stray)} cannot be combined with ${apply ? 'G43.1' : applyH ? 'G43' : 'G49'}; this line sets the tool `
      + 'length offset and nothing else. Nothing on this line was sent.',
    )
  }
  if (applyH) {
    const h = words.find((w) => w.letter === 'H' && !Number.isNaN(w.value))?.value
    if (h === undefined || !Number.isInteger(h) || h <= 0) {
      return refuseMdiLine(text, 'G43 needs a positive integer H tool-table index (G43 H3). Nothing on this line was sent.')
    }
    const resolved = resolveG43ToolLengthMm(h)
    if (!applyToolLengthOffset(resolved.deltaMm)) {
      return refuseMdiLine(
        text,
        'the tool length offset was not applied - it is written into the active work offset\'s Z, and '
        + 'no active work offset with a known Z could take it now. Nothing was changed.',
      )
    }
    mdiSaid(
      text,
      resolved.measured
        ? `tool ${h}'s measured length on this machine applied - tool length offset ${machineLengthText(resolved.deltaMm)}.`
        : `tool ${h} has no measured length on this machine - a tool length offset of zero is applied, `
          + 'exactly as the controller\'s own table answers.',
      'info',
    )
    return true
  }
  if (apply) {
    const z = words.find((w) => w.letter === 'Z' && !Number.isNaN(w.value))
    if (z === undefined) {
      return refuseMdiLine(text, 'G43.1 needs a Z length offset (G43.1 Z1.5). Nothing on this line was sent.')
    }
    const deltaMm = appCommandModal(ctrl).units === 'inch' ? z.value * 25.4 : z.value
    if (!applyToolLengthOffset(deltaMm)) {
      return refuseMdiLine(
        text,
        'the tool length offset was not applied - it is written into the active work offset\'s Z, and '
        + 'no active work offset with a known Z could take it now. Nothing was changed.',
      )
    }
    mdiSaid(text, `tool length offset ${machineLengthText(deltaMm)} applied.`, 'info')
    return true
  }
  if (geometryToolLengthOffset?.controller !== ctrl) {
    mdiSaid(text, 'no tool length offset is applied, so there is nothing to clear. Nothing was sent.', 'info')
    return true
  }
  if (!clearToolLengthOffset()) {
    return refuseMdiLine(text, 'the tool length offset was not cleared - the work offset write did not go out.')
  }
  mdiSaid(text, 'tool length offset cleared.', 'info')
  return true
}

/** Refuse the whole line, naming the first word it cannot honour - a G or M
 *  word by preference, because that is the word the operator has to change. */
function refuseMdiWord(text: string, candidates: readonly GcodeWord[]): false {
  const offending = candidates.find((w) => w.letter === 'G' || w.letter === 'M') ?? candidates[0]
  const spelled = mdiSpelling(offending)
  const output = offending.letter === 'M' ? MDI_OUTPUT_WORDS.get(offending.value) : undefined
  if (output !== undefined) {
    const pin = candidates.find((w) => w.letter === 'P' && !Number.isNaN(w.value))
    const what = output.replace('{pin}', pin === undefined ? '' : ` P${mdiNumber(pin.value)}`)
    return refuseMdiLine(
      text,
      mdiOutputByNumberMessage(spelled, what),
    )
  }
  if (offending.letter === 'M' && resolveMachineOutputWord(controlMachine(useCamStore.getState()), offending.value) !== null) {
    return refuseMdiLine(
      text,
      `${spelled} switches an output, and this line also carries other words - an output word runs on a `
      + 'line of its own so the line either ran whole or did not run at all. Nothing on this line was sent.',
    )
  }
  if (offending.letter === 'S') {
    return refuseMdiLine(
      text,
      `${spelled} sets a spindle speed and this line has no M3 or M4 to run at it, so the speed `
      + 'would have been dropped. Nothing on this line was sent.',
    )
  }
  // WO-2521: a typed M6 runs (`T19 M6`), so the table's "runs inside a loaded
  // program" is not the reason this line did not.
  if (offending.letter === 'M' && offending.value === 6) {
    const tool = candidates.find((w) => w.letter === 'T')
    if (tool !== undefined && !(Number.isInteger(tool.value) && tool.value >= 0)) {
      return refuseMdiLine(text, `${mdiSpelling(tool)} names no whole tool number, so M6 has no tool to fit. Nothing on this line was sent.`)
    }
    if (candidates.every((w) => w === offending || w.letter === 'N')) return refuseMdiLine(text, MDI_M6_NAMES_NO_TOOL)
    return refuseMdiLine(
      text,
      'M6 changes the tool on a line of its own with its T word (T19 M6), and this line also carries other '
      + 'words - a line runs whole or not at all. Nothing on this line was sent.',
    )
  }
  // WO-1644: THE SENTENCE IS THE TABLE'S. A word the table does not carry was
  // refused before dispatch (`mdiTableRefusal`); what reaches here is a word
  // it does carry, said by what the table says it does.
  const table = mdiWordTable()
  const isCode = offending.letter === 'G' || offending.letter === 'M'
  const entry = table !== null && isCode ? gcodeWordEntry(table, offending.letter, offending.value) : null
  if (entry !== null) {
    return refuseMdiLine(
      text,
      `${spelled} ${entry.meaning}, and this controller has no call for it on a typed line - it runs `
      + 'inside a loaded program. Nothing on this line was sent.',
    )
  }
  if (table !== null && offending.letter === 'M' && isGcodeMacroMCode(table, offending.value)) {
    return refuseMdiLine(text, `${gcodeMacroRefusal(table, offending.value)}. Nothing on this line was sent.`)
  }
  return refuseMdiLine(
    text,
    isCode
      ? `${spelled} has no call on this controller on a typed line. Nothing on this line was sent.`
      : `${spelled} has no G or M word on this line to act on it. Nothing on this line was sent.`,
  )
}

/** A FRAME WORD - WO-1312's mechanism, with the receipt. The chip follows the
 *  controller's confirmation and never the typing. */
function selectMdiWcs(text: string, wcs: WcsId, ctrl: MachineController): boolean {
  if (typeof ctrl.selectWcsAwait === 'function') {
    const receiptToken = captureBackendReceipt(ctrl)
    const receipt = ctrl.selectWcsAwait(wcs)
    if (receipt === null) return refuseMdiLine(text, `the controller would not select ${wcs}.`)
    void receipt.then((confirmed) => {
      if (!receiptIsCurrent(receiptToken)) return
      if (!confirmed) {
        mdiSaid(
          text,
          `the controller did not confirm ${wcs}, so the active work offset is unchanged.`,
          'error',
        )
        return
      }
      store().setActiveWcs(wcs)
      ctrl.refreshState()
      mdiSaid(text, `${wcs} is the active work offset.`, 'info')
    }).catch((error: unknown) => {
      if (!receiptIsCurrent(receiptToken)) return
      const detail = error instanceof Error ? error.message : String(error)
      mdiSaid(text, `the controller did not confirm ${wcs} (${detail}).`, 'error')
    })
    return true
  }
  if (!ctrl.selectWcs(wcs)) return refuseMdiLine(text, `the controller would not select ${wcs}.`)
  store().setActiveWcs(wcs)
  ctrl.refreshState()
  mdiSaid(text, `${wcs} is the active work offset.`, 'info')
  return true
}

/** A SPINDLE WORD - `commandSpindle`, the same call the program route uses, so
 *  the inverter runs at this definition's own setpoint word and the quiet-stop
 *  watchdog watches it. A start with no S speed is refused: a speed is never
 *  invented here, and MDI has no previous line to inherit one from. */
function commandMdiSpindle(
  text: string,
  ms: readonly number[],
  words: readonly GcodeWord[],
  ctrl: MachineController,
): boolean {
  if (ms.includes(5)) {
    // NOTHING GATES A STOP, here least of all: `M5` is the exact line Operator
    // typed when he found the refusal this order removes.
    const stop = commandSpindle('off', 0, () => [], ctrl)
    if (!stop.ok) return refuseMdiLine(text, stop.reason)
    mdiSaid(text, 'the spindle is commanded off.', 'info')
    return true
  }
  // ONE direction word and ONE speed, guaranteed: a line carrying two of either
  // was refused whole by `mdiCategoryConflict` before reaching any dispatch, so
  // "the one M3/M4 on the line" and "the one S on the line" are the operator's
  // words and not a pick between rivals.
  const direction = ms.includes(4) ? 'ccw' : 'cw'
  const word = direction === 'ccw' ? 'M4' : 'M3'
  const speed = words.find((w) => w.letter === 'S' && !Number.isNaN(w.value))
  if (speed === undefined || !(speed.value > 0)) {
    return refuseMdiLine(
      text,
      `${word} starts the spindle with no S speed to run at, and MDI has no previous line to inherit `
      + `one from. A speed is never invented here - type it on the line (${word} S12000).`,
    )
  }
  const started = commandSpindle(direction, speed.value, () => [], ctrl)
  if (!started.ok) return refuseMdiLine(text, started.reason)
  mdiSaid(
    text,
    `the spindle is commanded to ${mdiNumber(speed.value)} RPM ${direction.toUpperCase()}.`,
    'info',
  )
  return true
}

/**
 * MOTION - WO-1335'S OWN DOOR, NOT A COPY OF IT.
 *
 * The typed line goes in as a one-line program, so the frame receipt, the
 * travel check, the arc-extent check, the board's move ceiling and every
 * refusal by word are the same code a posted file passes through; `onStaged`
 * then starts it, which is the only thing MDI adds - Enter runs the line.
 *
 * THE STAGED PROGRAM IS REPLACED, AND THAT IS SAID. There is ONE queue on this
 * board, so an MDI move necessarily takes the place of whatever was loaded.
 * The door already rewrites the program identity, the readiness and the armed
 * path to the line that is actually staged; the sentence below is what stops an
 * operator pressing CYCLE START next and expecting their file.
 */
/** The MDI line whose moves are presently staged on the board, so a SECOND
 *  MDI move does not report that it replaced "the program" - the thing it
 *  replaced was the operator's own previous line, which they watched run. */
let mdiStagedLine: string | null = null
/** The standalone typed line still owns this job; a listing-less internal
 * program (guided recovery among them) is not inferred to be MDI. */
export function standaloneMdiJob(): boolean {
  const s = store()
  return mdiStagedLine !== null && s.job.name === mdiStagedLine
    && s.programText === null && s.stagedProgram === null
}

/** WO-2234: true only around the MDI door's own start of its staged line. */
let startingMdiLine = false

/** WO-2153 - A BUSY BOARD'S ANSWER DECIDES WHETHER THE LINE RAN.
 *
 *  Pin rehearsal 2026-09-28: a line typed while a probe ran printed "... staged
 *  and started." and THEN the bridge's red "startJob: refusing to move: a probe
 *  is running". `startJob()` returning true on a bridge means "sent", and the
 *  bridge answers one round trip later - `started` then ok (Bridge.cs), or an
 *  error reply and no job event. So when the board reads busy at the start (a
 *  probe, a tool measure, a jog or homing it has not finished) and the start
 *  was not confirmed in the same turn, the row waits here for the answer:
 *  written on the `started` job event, dropped on the controller's own
 *  `startJob:` error line - that line already says why nothing ran - or on any
 *  other job edge or a new connection. An idle board, a simulator (it confirms
 *  inside `startJob`) and a text controller (it raises no job events) write the
 *  row at once, exactly as before. */
let mdiRowAwaitingStart: { controller: MachineController; row: string } | null = null

/** Every `started` job event the session has taken, so the MDI door can tell a
 *  start the controller confirmed inside `startJob()` from one still in flight. */
let jobStartedEvents = 0

const MDI_BOARD_BUSY_STATES: ReadonlySet<MachineState> = new Set(['run', 'hold', 'jog', 'home'])

/** WO-2153: the board answered (or the session ended) - write the held row
 *  only if what came back was the start. */
function settleMdiRowAwaitingStart(ctrl: MachineController | null, started: boolean): void {
  const held = mdiRowAwaitingStart
  if (held === null || held.controller !== ctrl) return
  mdiRowAwaitingStart = null
  if (started) store().pushConsole('rx', held.row, 'info')
}

/** WO-1665: the feed a typed line last staged, held across MDI submissions the
 *  same way `appCommandModal` holds units and distance mode - each MDI line is
 *  its own one-line program to the shared reader, so nothing about a PREVIOUS
 *  line survives into it unless this door puts it back. mm/min, canonical,
 *  read off the moves the interpreter actually built (so it is always the real
 *  post-conversion value, whatever units that line was typed in). */
const mdiHeldFeedMmMin = new WeakMap<MachineController, number>()

function resetMdiHeldFeed(ctrl: MachineController): void {
  mdiHeldFeedMmMin.delete(ctrl)
}

function stageMdiMotion(label: string, text: string): boolean {
  const loaded = store().job.name
  const replaced = loaded !== null && loaded !== mdiStagedLine
  // THE PROGRAM END THE TYPED LINE DOES NOT CARRY. The shared reader requires
  // an M2/M30 - a file that stops without one was truncated, and refusing it is
  // right. A typed line is a WHOLE one-line program by definition, so the end
  // is supplied here rather than relaxing that rule for files. Nothing else is
  // added: `M30` is read and ignored by the interpreter, and an operator who
  // types `M30` themselves never reaches this door (it names no motion, so it
  // is refused by word above).
  //
  // WO-1636: THE HELD MODAL STATE IS WHAT THE LINE IS READ AGAINST. A `G20` or
  // `G91` typed on an earlier line still holds, so the words it left behind
  // lead the first line - only for a category that line does not state itself,
  // and on the same line, so a refusal still names line 1. Afterwards the
  // state is whatever the staged lines left it at.
  const ctrl = getMachineController()
  const held = appCommandModal(ctrl)
  const lines = text.split('\n')
  const firstWords = tokenizeLine(lines[0], 1).words
  const firstGs = mdiCodes(firstWords, 'G')
  // WO-1665: F IS HELD EXACTLY LIKE G20/G91 ABOVE, and read the same way -
  // scanned off the typed words, never off what the interpreter later builds
  // (its callbacks run on the controller's own reply, which lands after this
  // function has already returned). A controller runs a typed arc (or any
  // feed move) with no F of its own at whatever feed the operator last set,
  // and only a session with no feed EVER set still has none to lead with.
  const heldFeedMmMin = mdiHeldFeedMmMin.get(ctrl)
  const firstHasF = firstWords.some((w) => w.letter === 'F' && !Number.isNaN(w.value))
  const blockInch = firstGs.includes(20) ? true : firstGs.includes(21) ? false : held.units === 'inch'
  const lead = [
    held.units === 'inch' && !firstGs.some((g) => g === 20 || g === 21) ? 'G20' : null,
    held.distanceMode === 'incremental' && !firstGs.some((g) => g === 90 || g === 91) ? 'G91' : null,
    !firstHasF && heldFeedMmMin !== undefined ? `F${blockInch ? heldFeedMmMin / 25.4 : heldFeedMmMin}` : null,
  ].filter((word) => word !== null)
  if (lead.length > 0) lines[0] = `${lead.join(' ')} ${lines[0]}`
  let startAwaitsBoard = false
  // WO-2141: the file this line is staged over stays the loaded program.
  const fileUnder = currentFileDoorProgram()
  // WO-2234: for the operator's own line the loaded program stays the loaded
  // program - a file on the board, or WO-1980's file waiting for its work
  // offset (the operator often MDIs to the corner to set exactly that). A held
  // program's macro line keeps the WO-2141 record only.
  const s = store()
  const waiting = fileUnder === null && programAwaitingOffsets?.controller === ctrl
    && s.programText === null && s.job.name === programAwaitingOffsets.name
    ? programAwaitingOffsets
    : null
  const keepsFile = (fileUnder !== null || waiting !== null) && !hasActiveProgramJob(ctrl)
  // The program as it stood before the FIRST line typed over it: a second line
  // before the first was put back keeps that first picture.
  const previous = programUnderMdiLine
  const before = keepsFile && previous?.before && mdiLineOverLoadedProgram(ctrl)
    ? previous.before
    : { job: s.job, readiness: s.programReadiness, armed: fileUnder !== null && s.job.phase === 'ready' }
  const loadedName = s.job.name
  const readinessBefore = s.programReadiness
  const outcome = loadGcodeTextToolpathProgram(label, `${lines.join('\n')}\nM30\n`, {
    keepsLoadedProgram: keepsFile,
    loadLine: (program, started) => {
      const row = describeMdiMotion(label, program, replaced && !keepsFile, started, keepsFile)
      if (!startAwaitsBoard) return row
      mdiRowAwaitingStart = { controller: ctrl, row }
      return null
    },
    onStaged: () => {
      mdiStagedLine = label
      mdiRowAwaitingStart = null
      programUnderMdiLine = keepsFile
        ? {
            controller: ctrl,
            label,
            name: loadedName!,
            reload: fileUnder,
            keepsFile: true,
            ended: false,
            restaging: false,
            restored: false,
            before,
          }
        : fileUnder
          ? {
              controller: fileUnder.controller,
              label,
              name: label,
              reload: fileUnder,
              keepsFile: false,
              ended: false,
              restaging: false,
              restored: false,
              before: null,
            }
          : null
      // THE GATES ARE THE PROGRAM'S, SO THEY MAY REFUSE HERE. A staged line
      // that Cycle Start refused is not a line that ran, and this boolean is
      // what stops the row above saying it did. `startMachineJob` has already
      // written WHY on the console; the row that follows says what that left.
      const busy = !ctrl.capabilities.gcodeText && MDI_BOARD_BUSY_STATES.has(ctrl.machineState())
      const confirmedBefore = jobStartedEvents
      // WO-2234: a file waiting for its offset waits; this line is not it.
      startingMdiLine = true
      let started: boolean
      try {
        started = startMachineJob()
      } finally {
        startingMdiLine = false
      }
      // WO-2153: sent to a busy board and not yet confirmed - its answer decides.
      startAwaitsBoard = started && busy && jobStartedEvents === confirmedBefore
      // WO-2234: a line Cycle Start refused never runs; the file goes back.
      if (!started) endMdiLineOverFile(ctrl)
      return started
    },
  })
  // WO-2234: a refused line changed nothing on the board - the file is still
  // staged there, and still ready.
  if (keepsFile && !outcome.ok) store().setProgramReadiness(readinessBefore)
  if (outcome.ok) {
    const modalWords = text.split('\n')
      .flatMap((line) => mdiCodes(tokenizeLine(line, 1).words, 'G'))
      .filter((g) => g === 20 || g === 21 || g === 90 || g === 91)
    if (modalWords.length > 0) {
      reportAppCommand(ctrl, translateAppCommand(ctrl, modalWords.map((g) => `G${g}`).join(' ')))
    }
    // The lead-injected F (if any) counts the same as one the operator typed:
    // it is what the line actually staged at, and what the NEXT line inherits.
    const lastF = lines
      .flatMap((line) => tokenizeLine(line, 1).words)
      .filter((w) => w.letter === 'F' && !Number.isNaN(w.value))
      .at(-1)
    if (lastF !== undefined) mdiHeldFeedMmMin.set(ctrl, blockInch ? lastF.value * 25.4 : lastF.value)
  }
  return outcome.ok
}

/** What the line BECAME, in one row: how many moves, in which frame, where the
 *  tool ends up in that frame's work coordinates, and whether it is running.
 *
 *  THE LAST CLAUSE IS OBSERVED, NOT ASSUMED. Staging and starting are two
 *  events and the gates sit between them: on a machine with an unhomed axis the
 *  line stages and Cycle Start refuses it, and a row that said "started"
 *  regardless would be the readout claiming motion the wire never carried. */
function describeMdiMotion(
  text: string,
  program: GcodeInterpretedProgram,
  replacedProgram: boolean,
  started: boolean,
  overLoadedFile = false,
): string {
  const moveCount = program.moveCount === 1 ? 'one move' : `${program.moveCount} moves`
  // WO-1635: a G4 is staged as the board's own dwell step, so the row says so.
  const dwells = program.stages.flatMap((stage) => stage.dwells)
  const dwelling = dwells.length === 0
    ? ''
    : dwells.length === 1
      ? `a ${mdiNumber(dwells[0].seconds)} s dwell`
      : `${dwells.length} dwells`
  const moves = dwelling === ''
    ? moveCount
    : program.moveCount === 0 ? dwelling : `${moveCount} and ${dwelling}`
  // WO-1667: WHERE IT ENDS, IN BOTH FRAMES. The work value names its WCS; the
  // machine value sits beside it whenever the line rapids, homes, references
  // or moves in machine coordinates - `G28 Z18` ending at "Z-110" was machine
  // Z 0, the bottom of travel, and the row did not say so.
  const lastStage = program.stages.at(-1)
  const last = lastStage?.moves.at(-1)
  const ends = last === undefined || lastStage === undefined
    ? ''
    : `, ending at ${describeMdiEnd(program, lastStage.wcs, last)}`
  const spindle = program.spindle === null
    ? ''
    : ` The line commands ${program.spindle.rpm} RPM ${program.spindle.direction.toUpperCase()}.`
  const replaced = replacedProgram
    ? ' The program that was staged has been replaced by this move - load it again before CYCLE START.'
    : ''
  // WO-2234: over a loaded file the refused line does not stay on the board -
  // the file is staged again, so CYCLE START runs the file.
  const ran = started
    ? 'staged and started.'
    : 'staged, and NOT started - Cycle Start refused it for the reason above. '
      + (overLoadedFile ? 'Nothing moved.' : 'The move is on the board: clear that, then press CYCLE START.')
  return `MDI ${text}: ${moves} in ${program.frames.join(', then ')}${ends}, `
    + `${ran}${spindle}${replaced}`
}

/** Display only: the controller and all motion calculations keep their mm values. */
function machineDisplayUnits() {
  const override = useUiPrefs.getState().machineDisplayUnits
  return override === 'default' ? useCamStore.getState().appSettings.displayUnits : override
}

function machineLengthText(mm: number): string {
  const units = machineDisplayUnits()
  return `${fmtMachineLength(mm, units)} ${unitLabel(units)}`
}

function formatPosition(position: FramedPosition): string {
  return framedPosition({ ...position, format: position.format ?? machineLengthText })
}

/** WO-1667: a MACHINE-coordinate position for a row, through the one formatter:
 *  the active work frame's value first when the controller has reported that
 *  frame's offset, the machine value beside it - "G54 Z -105 (machine Z 5)". */
function machinePositionText(machine: Partial<MachineVec3>, format?: (mm: number) => string): string {
  return formatPosition({ ...activeWorkFrame(), machine, format })
}

/** WO-1667: the active work frame and its reported offset (machine = work +
 *  offset), or nulls when the controller has not reported it this session. */
interface ActiveWorkFrame {
  wcs: string | null
  offset: PositionPoint | null
}

function activeWorkFrame(): ActiveWorkFrame {
  const wcs = store().activeWcs ?? null
  const offset = wcs === null ? null : currentWorkOffsets().byWcs[wcs as WcsId] ?? null
  return { wcs: offset === null ? null : wcs, offset }
}

/** The end of a typed line, through the one position formatter: the axes the
 *  line moved, in the frame the last move ran in, with machine coordinates
 *  beside it for a rapid or a machine-coordinate (G53/G28/G30) move. */
function describeMdiEnd(program: GcodeInterpretedProgram, wcs: string, last: GcodeReaderMove): string {
  const start = getMachineController().status().workPos
  const points = [
    ...(start ? [{ x: start.x, y: start.y, z: start.z }] : []),
    ...program.stages.flatMap((stage) => stage.moves),
  ]
  const machineMove = program.stages.some((stage) => stage.moves.some((move) => move.machineAbsolute !== undefined))
  const offset = currentWorkOffsets().byWcs[wcs as WcsId] ?? null
  // WO-2215: under a rotated work system the machine point is O + Rot(R)(work),
  // not work + offset - so it is stated, and the formatter adds nothing to it.
  const degrees = controllerRotationDeg(wcs)
  const ox = offset?.x
  const oy = offset?.y
  const oz = offset?.z
  const turned = degrees === 0 || typeof ox !== 'number' || typeof oy !== 'number' ? null : rotateXY(degrees, last.x, last.y)
  // Turned, one work axis moving moves both machine axes, so X and Y go together.
  const moved = movedAxes(points)
  const axes = turned !== null && (moved.includes('x') || moved.includes('y'))
    ? (['x', 'y', 'z'] as const).filter((axis) => axis !== 'z' || moved.includes('z'))
    : moved
  return formatPosition({
    wcs,
    work: last,
    offset,
    ...(turned === null ? {} : {
      machine: { x: ox! + turned.x, y: oy! + turned.y, ...(typeof oz === 'number' ? { z: last.z + oz } : {}) },
    }),
    axes,
    withMachine: machineMove || last.type === 'rapid',
  })
}

type GrblSettingWriteResult =
  | { ok: true; key: number; value: string }
  | { ok: false; reason: string }

type GrblSettingsController = MachineController & Required<Pick<
  MachineController,
  'readSettings' | 'writeSetting'
>>

/** GRBL-style settings are a controller surface, not a controller identity.
 * Requiring both halves keeps read, write, G30 ownership, and lazy backend
 * reuse on one declared capability. */
function supportsGrblSettings(target: MachineController | null): target is GrblSettingsController {
  return typeof target?.readSettings === 'function' && typeof target.writeSetting === 'function'
}

const GRBL_SETTING_READBACK_TIMEOUT_MS = 8_000
const grblSettingReadbackWaiters = new Map<number, Set<(value: string) => void>>()

function publishGrblSettingReadback(key: number, value: string): void {
  const waiters = grblSettingReadbackWaiters.get(key)
  if (!waiters) return
  grblSettingReadbackWaiters.delete(key)
  for (const resolve of waiters) resolve(value)
}

function waitForGrblSettingReadback(
  key: number,
  querySettings: () => boolean,
  timeoutMs = GRBL_SETTING_READBACK_TIMEOUT_MS,
): Promise<string | null> {
  return new Promise((resolve) => {
    const finish = (value: string | null): void => {
      clearTimeout(timeout)
      const waiters = grblSettingReadbackWaiters.get(key)
      waiters?.delete(onValue)
      if (waiters?.size === 0) grblSettingReadbackWaiters.delete(key)
      resolve(value)
    }
    const onValue = (value: string): void => finish(value)
    const waiters = grblSettingReadbackWaiters.get(key) ?? new Set<(value: string) => void>()
    waiters.add(onValue)
    grblSettingReadbackWaiters.set(key, waiters)
    const timeout = setTimeout(() => finish(null), timeoutMs)

    // Install the waiter BEFORE asking for $$: the simulator and a fast test
    // transport can answer synchronously, and that answer is still proof.
    if (!querySettings()) finish(null)
  })
}

interface GrblSettingWriteTestOptions {
  controller?: MachineController
  waitForReadback?: (
    key: number,
    querySettings: () => boolean,
  ) => Promise<string | null>
}

/**
 * Write one setting through GRBL's text path, then prove it by reading `$$`.
 * The command acknowledgement is only permission to ask again; it is never
 * returned as the value. Callers display `result.value`, which came through
 * `onSetting`, or leave their previous snapshot untouched on every refusal.
 */
export async function writeGrblSettingAndReadBack(
  key: number,
  rawValue: string,
  testOptions: GrblSettingWriteTestOptions = {},
): Promise<GrblSettingWriteResult> {
  if (!Number.isInteger(key) || key < 0) {
    return { ok: false, reason: 'The GRBL setting number is invalid.' }
  }
  const value = rawValue.trim()
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value)) {
    return { ok: false, reason: `GRBL setting $${key} needs a numeric value.` }
  }

  const ctrl = testOptions.controller ?? getMachineController()
  if (typeof ctrl.hasActiveJob === 'function' && hasActiveProgramJob(ctrl)) {
    const reason = `A program is running - GRBL setting $${key} was not sent.`
    store().pushConsole('tx', reason, 'error')
    return { ok: false, reason }
  }
  const receiptToken = captureBackendReceipt(ctrl)
  // WO-1545: the settings line goes through the translator like every other
  // app-issued line; a controller with no equivalent names the line.
  const acknowledgement = supportsGrblSettings(ctrl)
    ? ctrl.writeSetting(key, value)
    : sendAppCommandAwait(`$${key}=${value}`, ctrl)
  if (!acknowledgement) {
    return { ok: false, reason: `GRBL refused the $${key} write.` }
  }
  const ack = await acknowledgement
  if (!receiptIsCurrent(receiptToken)) {
    return { ok: false, reason: `GRBL $${key} receipt belongs to a replaced machine session.` }
  }
  if (!ack.ok) {
    return { ok: false, reason: ack.message ?? `GRBL refused the $${key} write.` }
  }

  const waitForReadback = testOptions.waitForReadback ?? waitForGrblSettingReadback
  const reported = await waitForReadback(key, () => ctrl.querySettings())
  if (!receiptIsCurrent(receiptToken)) {
    return { ok: false, reason: `GRBL $${key} readback belongs to a replaced machine session.` }
  }
  if (reported === null) {
    return {
      ok: false,
      reason: `GRBL accepted the $${key} write, but refused or did not answer the $$ re-read.`,
    }
  }
  return { ok: true, key, value: reported }
}

interface GrblSettingDifference {
  id: number
  stored: string
  controller: string | null
}

function compareGrblSettings(
  stored: GrblSettingsRecord | undefined,
  reported: ReadonlyMap<number, string> | GrblSettingsRecord,
): GrblSettingDifference[] {
  const map = reported as ReadonlyMap<number, string>
  const record = reported as GrblSettingsRecord
  const read = typeof map.get === 'function'
    ? (id: number) => map.get(id) ?? null
    : (id: number) => record[id] ?? null
  return Object.entries(stored ?? {})
    .map(([id, value]) => ({ id: Number(id), stored: value, controller: read(Number(id)) }))
    .filter((row) => Number.isSafeInteger(row.id) && row.controller !== row.stored)
    .sort((left, right) => left.id - right.id)
}

/** Read GRBL's complete settings transaction through the installed serial
 * backend. Every row still crosses the ordinary onSetting event into the
 * machine-control store; this promise supplies the transaction boundary. */
export async function readConnectedGrblSettings(
  target: MachineController = getMachineController(),
): Promise<Map<number, string>> {
  if (!supportsGrblSettings(target)) {
    throw new Error('Connect a GRBL serial controller before reading its settings.')
  }
  return target.readSettings()
}

async function reconcileGrblSettingsOnConnect(
  machineId: string,
  target: GrblSettingsController,
  accepts: () => boolean = () => true,
): Promise<GrblSettingDifference[]> {
  const reported = await target.readSettings()
  if (!accepts()) return []
  const stored = machineRecord(machineId)?.grblSettings
  const differences = compareGrblSettings(stored, reported)
  if (!stored || Object.keys(stored).length === 0) {
    store().pushConsole('rx', `GRBL settings read: ${reported.size} rows; this machine has no stored copy yet.`, 'info')
  } else if (differences.length === 0) {
    store().pushConsole('rx', `GRBL settings read: ${reported.size} rows; the stored copy agrees.`, 'info')
  } else {
    store().pushConsole(
      'rx',
      `GRBL settings read: ${reported.size} rows; ${differences.length} stored setting${differences.length === 1 ? '' : 's'} differ. Nothing was sent.`,
      'info',
    )
    for (const row of differences) {
      store().pushConsole(
        'rx',
        `$${row.id} differs - controller ${row.controller ?? 'did not report it'}, stored ${row.stored}.`,
        'info',
      )
    }
  }
  return differences
}

/** Explicitly send only stored values that differ from the current controller
 * snapshot. writeGrblSettingAndReadBack proves every individual write with a
 * following $$ before the next id is considered. */
export async function applyStoredGrblSettings(
  stored: GrblSettingsRecord,
  target: MachineController = getMachineController(),
  reported: GrblSettingsRecord = useMachineControl.getState().settings,
): Promise<GrblSettingWriteResult[]> {
  if (typeof target.hasActiveJob === 'function' && hasActiveProgramJob(target)) {
    const reason = 'A program is running - stored GRBL settings were not sent.'
    store().pushConsole('tx', reason, 'error')
    return [{ ok: false, reason }]
  }
  const results: GrblSettingWriteResult[] = []
  for (const row of compareGrblSettings(stored, reported)) {
    // A stored-only row is still a useful reconciliation difference, but it is
    // not write authority: this controller did not prove that setting exists.
    if (row.controller === null) continue
    const result = await writeGrblSettingAndReadBack(row.id, row.stored, { controller: target })
    results.push(result)
    if (!result.ok) {
      store().pushConsole('rx', `GRBL setting $${row.id} was not applied: ${result.reason}`, 'error')
    }
  }
  return results
}

/**
 * The connection-boundary work every backend triggers, wired to whichever
 * event channel that backend has. Unchanged from the GRBL-only version - it
 * only moved out of the events literal so the bridge's ControllerEvents can
 * call the same code.
 */
/**
 * WO-1031 (audit rounds 5-6) - A CONTROLLER SESSION BOUNDARY RE-READS THE
 * CONTROLLER; IT DOES NOT CARRY THE LAST SESSION'S ANSWER FORWARD.
 *
 * The geometry door below keeps NO app-side "a program is staged" flag - the
 * controller owns that fact. But the store still held a job/readiness snapshot
 * TAKEN FROM THE PREVIOUS CONTROLLER SESSION, and nothing refreshed it when the
 * connection changed. On the simulator that was harmless (`SimulatedController.
 * startJob` refuses with an empty queue), but `UccncController.startJob`
 * (uccncController.ts:969) has NO such gate - it checks only that motion is
 * allowed, then sends the frame. So a bridge load, a disconnect and a reconnect
 * left the store still reporting `phase: 'ready'` with readiness ready, the
 * operator's own CYCLE START still derived `start`, and a start frame could
 * reach a bridge process this client session never loaded a program into. If
 * that process still held the earlier staged queue, the frame starts it: a
 * START WITHOUT A FRESH LOAD, which is the hazard every attempt of this order
 * has been chasing.
 *
 * The fix keeps the "one source of truth" shape instead of re-introducing a
 * flag: at every connection transition the app RE-READS the controller's own
 * job progress and publishes that. A fresh controller reports an empty job, so
 * the verdict that gates CYCLE START (`deriveOperatorTransport`, which only
 * reaches `start` from `job.phase === 'ready'`) stops deriving it and no frame
 * is sent - the app never assumes a gate the backend does not have. A
 * controller that really does still hold a staged program reports it, and
 * nothing is taken away. And when the controller says it holds nothing, the
 * readiness sentence stops claiming otherwise: a stale "program loaded" line is
 * the same lie one surface further up.
 *
 * IT ASKS NO CAPABILITY QUESTION FIRST, and audit round 6 is why. Round 5
 * scoped this to backends declaring `machineProgram` and returned early
 * otherwise - but an UN-UPDATED bridge is exactly such a destination (its
 * `hello` carries no `machineProgram` at all), so a simulator load followed by
 * connecting that bridge - a SWAP, which publishes no `disconnected`, so the
 * store's own reset never runs - left the app claiming `ready` over a fresh
 * `UccncController`, and a start frame went out for a program that board never
 * received. Measured on the wire: PROBE startJob frames = 1.
 *
 * THE CAPABILITY WAS THE WRONG QUESTION. What makes the app's claim stale is
 * that THE CONTROLLER CHANGED, not what the new controller can do - and a
 * controller with no program route holds no program by definition, which is the
 * strongest possible reason to stop claiming it holds one. So this runs on
 * every backend, and what it publishes is always the LIVE controller's own
 * answer.
 *
 * It is still not a second opinion about the text path. It only ever REPLACES
 * the app's account with the controller's, and a backend that really is still
 * holding its prepared job reports exactly that and keeps it - a GRBL session
 * that loads a program and then connects is the same object, still holding it,
 * so nothing is taken away. `loadMachineProgram` is byte-identical to `main`.
 *
 * It sends NOTHING to any controller. No disarm, no frame - a boundary that
 * transmitted would be a boundary that could move a machine.
 */
function adoptControllerJobStateAtBoundary(): void {
  const ctrl = controller
  if (!ctrl) return
  const progress = ctrl.jobProgress()
  store().applyJobProgress(progress)
  if (progress.phase === 'empty' && store().programReadiness.ready) {
    store().setProgramReadiness({
      ready: false,
      reason:
        'The machine connection changed and this controller holds no program - '
        + 'load the program again before CYCLE START.',
    })
    bumpArmEpoch()
  }
}

/** WO-1072: one cache/profile report per bridge connection, even though the
 *  production bridge announces `connected` once after the controller already
 *  raised it from hello. The controller identity is the session latch. */
let definitionDriftNoticeSentFor: MachineController | null = null
/** The console keeps history across disconnects. This latch makes the line
 * separating that history from the live session exactly once per controller,
 * even when a bridge also sends its redundant `phase: connected` frame. */
let connectionBoundarySentFor: MachineController | null = null

/** WO-1109: the bridge's buffered-motion soft-limit latch, kept separately
 * from MachineState because the bridge reports it as an independent fact. */
let lastReportedSoftLimitLatched = false
const softLimitLatchListeners = new Set<() => void>()

export const SOFT_LIMIT_TRIPPED_NOTICE =
  'Soft limit tripped - buffered moves are refused until you press Unlock.'
export const SOFT_LIMIT_CLEARED_NOTICE = 'Soft limit cleared.'
export const SOFT_LIMIT_UNLOCK_TITLE = 'Clears the soft-limit latch and restores motion.'

/** Snapshot/subscription pair for React's useSyncExternalStore. */
export function softLimitLatchActive(): boolean {
  return lastReportedSoftLimitLatched
}

export function subscribeSoftLimitLatch(listener: () => void): () => void {
  softLimitLatchListeners.add(listener)
  return () => softLimitLatchListeners.delete(listener)
}

function publishSoftLimitLatch(next: boolean, announce: boolean): void {
  if (next === lastReportedSoftLimitLatched) return
  lastReportedSoftLimitLatched = next
  for (const listener of [...softLimitLatchListeners]) listener()
  if (!announce) return
  store().pushConsole(
    'rx',
    next ? SOFT_LIMIT_TRIPPED_NOTICE : SOFT_LIMIT_CLEARED_NOTICE,
    next ? 'error' : 'info',
  )
}

/**
 * WO-2187: the work rotations the CONTROLLER reports (docs/design/WCS-ROTATION.md).
 * The rotation lives in the controller - LinuxCNC's `G10 L2 Pn R`, the AXBB-E
 * bridge's offset table - and this is only what it last said: re-read on every
 * status frame and connection edge, never set from what the app asked for, so
 * a rotation saved in the controller shows the moment the app connects. Only
 * the rotated systems are kept (0 = none), so no rotation = the empty object.
 */
const NO_WORK_ROTATIONS: WcsRotations = Object.freeze({})
let reportedWorkRotations: WcsRotations = NO_WORK_ROTATIONS
const workRotationListeners = new Set<() => void>()

/** Snapshot/subscription pair for React's useSyncExternalStore. */
export function workRotations(): WcsRotations {
  return reportedWorkRotations
}

export function subscribeWorkRotations(listener: () => void): () => void {
  workRotationListeners.add(listener)
  return () => workRotationListeners.delete(listener)
}

/** "G54 rotated 0.73 deg" - the operator's words for one rotated system. */
export function describeWorkRotation(wcs: string, degrees: number): string {
  const shown = Math.abs(degrees) >= 0.001 ? Number(degrees.toFixed(3)) : Number(degrees.toPrecision(2))
  return `${wcs} rotated ${String(shown)} deg`
}

function refreshWorkRotations(): void {
  const live = store().connectionPhase === 'connected' ? controller?.wcsRotations?.() ?? null : null
  const next: Record<string, number> = {}
  for (const [wcs, degrees] of Object.entries(live ?? {})) if (degrees !== 0) next[wcs] = degrees
  const keys = Object.keys(next)
  const same = keys.length === Object.keys(reportedWorkRotations).length
    && keys.every((wcs) => reportedWorkRotations[wcs] === next[wcs])
  if (same) return
  reportedWorkRotations = keys.length === 0 ? NO_WORK_ROTATIONS : Object.freeze(next)
  for (const listener of [...workRotationListeners]) listener()
  // WO-2219: the soft-limit check measures a program turned by this rotation,
  // so a changed rotation re-judges it, as a changed offset does.
  runTransferCheck()
}

/**
 * WO-2187: set (or, with 0, clear) one work system's rotation in the
 * controller - the one app call for both routes. The controller rotates what
 * runs in that system itself; the app never rotates a program as well. The
 * indicator follows the controller's report, not this request.
 */
export async function setWorkRotation(wcs: string, degrees: number): Promise<SetWcsRotationResult> {
  const ctrl = controller
  if (!ctrl?.setWcsRotation || store().connectionPhase !== 'connected') {
    const reason = ctrl && store().connectionPhase === 'connected'
      ? 'this controller cannot rotate a work offset.'
      : 'the machine is not connected.'
    store().pushConsole('rx', `${wcs} rotation not changed - ${reason}`, 'warn')
    return { ok: false, reason, rotationDeg: null, offset: null, outcome: 'refused' }
  }
  const result = await ctrl.setWcsRotation(wcs, degrees)
  if (ctrl !== controller) return result
  refreshWorkRotations()
  if (result.ok) {
    const held = result.rotationDeg ?? degrees
    store().pushConsole('rx', held === 0 ? `${wcs} rotation cleared.` : `${describeWorkRotation(wcs, held)}.`, 'info')
  } else if (result.outcome === 'unknown') {
    // WO-1983: no answer is neither a refusal nor a change - the indicator
    // shows whatever the controller reports next.
    store().pushConsole('rx', `${wcs} rotation: ${result.reason ?? 'the controller did not answer.'} It may have changed; the controller's next report shows it.`, 'warn')
  } else {
    store().pushConsole('rx', `${wcs} rotation not changed - ${result.reason ?? 'the controller did not say why.'}`, 'warn')
  }
  return result
}

/** WO-2187: the indicator's Clear - rotation 0 in the controller. */
export function clearWorkRotation(wcs: string): Promise<SetWcsRotationResult> {
  return setWorkRotation(wcs, 0)
}

const DEFINITION_FIELD_LABELS: Readonly<Record<string, string>> = {
  enabled: 'enabled',
  stepsPerUnit: 'steps per unit',
  maxVelocity: 'maximum velocity',
  acceleration: 'acceleration',
  softLimitMin: 'negative soft limit',
  softLimitMax: 'positive soft limit',
  enableDelayMs: 'enable delay',
  'backlash.enabled': 'backlash enabled',
  'backlash.distance': 'backlash distance',
  slaveAxis: 'slave axis',
  stepPin: 'step pin',
  dirPin: 'direction pin',
  homePin: 'home pin',
  limitMinusPin: 'negative limit pin',
  limitPlusPin: 'positive limit pin',
  enablePin: 'enable pin',
  'homing.direction': 'homing direction',
  'homing.fastSpeed': 'fast homing speed',
  'homing.slowSpeed': 'slow homing speed',
  'homing.backOff': 'homing back-off',
  'homing.homingValue': 'homing value',
}

function definitionDriftLabel(key: string): string {
  const axis = /^axes\.([^.]+)\.(.+)$/.exec(key)
  if (axis) return `${axis[1]} ${DEFINITION_FIELD_LABELS[axis[2]] ?? axis[2]}`
  const io = /^io\.(.+)$/.exec(key)
  if (io) {
    if (io[1] === 'estop') return 'E-stop input'
    if (io[1] === 'probe') return 'probe input'
    if (io[1] === 'probe2') return 'second probe input'
  }
  return key
}

function definitionDriftDetail(entry: BridgeDefinitionDriftEntry): string {
  const values = `  ${definitionDriftLabel(entry.key)}: cache ${entry.cache}, profile ${entry.profile}`
  if (!entry.kept) return `${values} - refused, no one accounts for it`
  return `${values} - kept (${entry.kind ?? 'unknown'}: ${entry.source ?? 'no source'})`
}

/** WO-1094: say which startup authority actually configured the board. This is
 * separate from the drift detail below: source answers whether a file was
 * opened at all, while drift describes any value disagreement the bridge can
 * account for. Legacy `cache` remains a distinct, honest answer because those
 * bridge builds may still have opened the profile while reconciling it. */
type BridgeHelloController = MachineController & Required<Pick<MachineController, 'bridgeHello'>>
type WorkOffsetController = MachineController & Required<Pick<MachineController, 'setWorkOffset'>>

function publishesBridgeHello(
  target: MachineController | null,
): target is BridgeHelloController {
  return typeof target?.bridgeHello === 'function'
}

function publishedBridgeHello(target: MachineController | null): ControllerBridgeHello | null {
  return publishesBridgeHello(target) ? target.bridgeHello() : null
}

function supportsWorkOffsetWrites(
  target: MachineController | null | undefined,
): target is WorkOffsetController {
  return typeof target?.setWorkOffset === 'function'
}

function reportBridgeDefinitionSource(target: BridgeHelloController): void {
  const source = target.bridgeHello()?.definitionSource
  const report = source === 'cache-baseline'
    ? { text: "Machine configured from this computer's data (the .pro was not opened).", severity: 'info' as const }
    : source === 'profile'
      ? { text: 'Machine configured from the .pro, once - the first start under this bridge; apply the definition to make this computer the source.', severity: 'warn' as const }
      : source === 'none'
        ? { text: 'The bridge holds no definition - nothing configured; apply one.', severity: 'warn' as const }
        : source === 'cache'
          ? { text: 'Machine configured from the bridge cache; its start-up source was not distinguished.', severity: 'warn' as const }
          : { text: 'This older bridge did not say what configured the machine at start-up.', severity: 'warn' as const }
  store().pushConsole('rx', report.text, report.severity)
}

function reportBridgeDefinitionDrift(target: BridgeHelloController): void {
  const drift = target.bridgeHello()?.definitionDrift
  if (drift === undefined) {
    store().pushConsole(
      'rx',
      "This bridge did not check its cached settings against the profile (older build) - values on the board may not be the profile's.",
      'warn',
    )
    return
  }
  if (drift.length === 0) {
    store().pushConsole(
      'rx',
      'Bridge start-up check: cached settings agree with the profile on every key.',
      'info',
    )
    return
  }
  const kept = drift.filter((entry) => entry.kept).length
  store().pushConsole(
    'rx',
    `Bridge start-up check: ${drift.length} cached settings differ from the profile - ${kept} kept, ${drift.length - kept} sent back to the profile's value.`,
    'warn',
  )
  for (const entry of drift) {
    store().pushConsole('rx', definitionDriftDetail(entry), entry.kept ? 'info' : 'warn')
  }
}

function handleConnectionPhase(
  phase: ConnectionPhase,
  detail: string | null,
  previousPhase = store().connectionPhase,
): void {
  // WO-2686: read before anything below lets the controller's account in.
  const choseStart = operatorChosenStartLost() || operatorHasChosenStart()
  store().setConnection(phase, detail)
  // A repeated transport notification may carry fresher detail, but it is not
  // a new physical session. Do not invalidate receipts, reviews or reset
  // authority a second time for the same phase in the same generation.
  if (phase === previousPhase) {
    if (phase === 'connected') {
      store().setBridgeHello(publishedBridgeHello(controller))
    }
    refreshWorkRotations()
    return
  }
  // WO-2187: the controller's own rotations from its first report (hello /
  // status); every other phase has none to show.
  refreshWorkRotations()

  // A connect attempt owns one revision from its first real edge. The later
  // connecting -> connected edge establishes the same session; a backend that
  // skips connecting still gets its boundary on disconnected -> connected.
  const beginsSession = phase === 'connecting'
    || (phase === 'connected' && previousPhase === 'disconnected')
  const endsSession = phase === 'disconnected'
  const sessionBoundary = beginsSession || endsSession
  if (sessionBoundary) connectionRevision++
  // A waiting macro belongs to the session it started in, and EVERY session
  // boundary ends it - not just a disconnect. A SWAP (connecting a bridge over
  // a live simulator) publishes no `disconnected` at all: it goes connected ->
  // connecting -> connected. Stopping only on `disconnected` therefore left a
  // macro holding at hold() or on a question across the swap, and answering it
  // afterwards resumed the old run against the NEW controller - which is this
  // order's outcome exactly ("nothing it would have sent reaches a later
  // connection"), and the same shape as the stale-program hazard
  // adoptControllerJobStateAtBoundary() below was written for.
  if (sessionBoundary) stopUserMacroForSessionBoundary(endsSession)
  if (phase !== 'connected') setSpindleStopTitle(null)
  // WO-1275: motion held for a spindle that is no longer reachable is motion
  // nothing may release. Dropped on the phase edge, not left to the poll.
  if (phase !== 'connected') cancelSpindleSpeedWait()
  // WO-1637: an on-delay belongs to the connection whose output switched.
  if (phase !== 'connected') outputOnDelayUntilMs = 0
  // WO-2668: a pin read in one session says nothing about the next; the new
  // connection's own pins are read as soon as it is up.
  if (sessionBoundary) {
    outputPinWrites.clear()
    useMachineControl.setState({ outputPins: {} })
  }
  if (phase === 'connected') scheduleOutputPinRefresh()
  if (phase === 'disconnected') {
    programClampPause = null
    // No receipt from the ended physical session can retain ownership of the
    // shared work-offset slot. Its async continuation is revision-gated and
    // therefore must not be responsible for releasing the disconnected UI.
    openWorkOffsetWrite = null
    setWorkOffsetWriteInFlight(controlMachineId(), false)
    useCamStore.getState().setControlSessionMachine(null)
    simulatedController = null
    // A latch belongs to one live bridge session. Disconnect removes the
    // stale UI fact silently; only a status-frame falling edge says cleared.
    publishSoftLimitLatch(false, false)
    runTransferCheck()
  }
  if (phase !== 'connected' && programPartsRun) {
    const reason = `Program parts ended because the machine connection changed${detail ? `: ${detail}` : '.'} `
      + 'No later part was loaded.'
    endProgramParts(reason, 'failed', { code: null, message: reason, line: null, moveId: null }, 'error')
  }
  // Connection transitions are session boundaries. The controller tears
  // down its streamer on disconnect, and a reconnect is a new controller
  // session; neither may inherit a Step Back review from the previous session
  // (or a refusal published while disconnected).
  // WO-2686: a choice the boundary destroys is remembered as lost, below.
  const chosenStartLost = sessionBoundary && choseStart
  if (sessionBoundary) clearRunFromReview()
  // WO-1031: ...and neither may it inherit the PREVIOUS session's account of
  // what the controller has staged. See adoptControllerJobStateAtBoundary above:
  // the app re-reads the controller rather than carrying its own answer across
  // a boundary, so CYCLE START can never be derived against a controller that
  // never received the program.
  if (sessionBoundary) adoptControllerJobStateAtBoundary()
  if (chosenStartLost) chosenStartLostAtEpoch = armEpochValue
  // WO-328: every connection transition - a fresh connect (a new session,
  // exactly like a fresh page load - nothing has confirmed the E-STOP
  // circuit clear yet) AND a disconnect (no further status report can ever
  // answer a pending reset check, so fail it closed now rather than let it
  // time out) - forces the E-STOP back to needs-reset. Unconditional on
  // purpose: there is no connection phase in which "still armed" is safe.
  if (sessionBoundary) {
    armEstopNeedsReset(false)
  }
  // ...and the hardware-e-stop edge is per-session too. A disconnect while the
  // button was IN would otherwise leave this true, so the next connection with
  // the button still in would see no rising edge and never arm.
  if (sessionBoundary) lastReportedHardwareEstop = false
  // WO-448: hello.readOnly / hello.vfd only ever come from a bridge session -
  // read them fresh off the controller the moment the phase says connected,
  // and clear them on every other transition (disconnect, a fresh connect
  // attempt, a non-bridge backend) so a stale reading can never survive a
  // disconnect/reconnect or outlive the session that reported it.
  store().setBridgeHello(
    phase === 'connected' ? publishedBridgeHello(controller) : null,
  )
  if (phase === 'connected') {
    if (controller && connectionBoundarySentFor !== controller) {
      connectionBoundarySentFor = controller
      const sessionMachine = controlMachine(useCamStore.getState())
      const machineName = sessionMachine.name
      const declaredProtocol = sessionMachine.controller === 'grblhal'
        ? `: ${controllerDisplayName(sessionMachine.controller)} (declared) via GRBL 1.1 protocol`
        : ''
      store().pushConsole(
        'rx',
        `--- connected to ${machineName}${declaredProtocol} at ${new Date().toISOString()} ---`,
        'info',
      )
    }
    // First reads a fresh session needs: modal state, offsets, settings.
    controller?.refreshState()
    controller?.querySettings()
    // ONCE PER CONNECTION, NOT ONCE PER `connected` CALLBACK. A real bridge
    // session reaches this branch TWICE: `UccncController.connect()` consumes
    // the hello and calls `setPhase('connected', ...)` itself
    // (uccncController.ts:447), and the shipped bridge ALSO sends an
    // unsolicited `phase: connected` frame (Bridge.cs, right after it installs
    // the live console), which `handleMessage` forwards straight to this
    // callback (uccncController.ts:'phase'). Both are legitimate - neither side
    // is wrong to say it - so the de-duplication belongs here, at the one place
    // that decides to speak. The latch is the CONTROLLER ITSELF, not a boolean:
    // it answers "has this connection already been told?", so a second frame
    // from the same session is silent while a different backend gets its own
    // line even if a phase transition were ever missed.
    if (publishesBridgeHello(controller) && definitionDriftNoticeSentFor !== controller) {
      definitionDriftNoticeSentFor = controller
      reportBridgeDefinitionSource(controller)
      reportBridgeDefinitionDrift(controller)
    }
  } else {
    // Any phase that is not `connected` ends the session the notice belonged
    // to, so the NEXT connect says it again. `connect()` always passes through
    // 'connecting' (uccncController.ts:418) and `disconnect()` always publishes
    // 'disconnected' (uccncController.ts:1560), so a reconnect - even on the
    // very same controller object - can never inherit a spent latch.
    // WO-1545: a new connection starts from the power-on modal state.
    if (controller) {
      resetAppCommandModal(controller)
      resetGeometryMotionModal(controller)
      resetMdiHeldFeed(controller)
      settleMdiRowAwaitingStart(controller, false)
      // WO-2234: a lost link ends the line; the file goes back at the first
      // settled Idle once connected again.
      if (mdiLineOverLoadedProgram(controller)) programUnderMdiLine!.ended = true
      // WO-2237: a lost link ends a kept stop and whatever waited for one -
      // what the machine did while it was gone is not known here.
      dropCommandsWaitingForKeptStop(controller)
      keptStopTaking = null
      keptStop = null
    }
    definitionDriftNoticeSentFor = null
    connectionBoundarySentFor = null
  }
}

export function getMachineController(): MachineController {
  if (controller) return controller
  return installGrblBackend()
}

// ---------------------------------------------------------------------------
// WO-1545 - EVERY APP-ISSUED G-CODE LINE GOES THROUGH THE TRANSLATOR
// ---------------------------------------------------------------------------
//
// The bridge declares `capabilities.gcodeText: false` (the UC100 path has no
// interpreter). That is a fact about the WIRE, never a reason to refuse a
// command: `src/lib/gcode/appCommand.ts` translates every line the app itself
// issues, and these two functions are the only doors to it. GRBL and the
// simulator still get the line as text through the same doors.
// ---------------------------------------------------------------------------

/** Send one app-issued G-code line through the translator, fire and forget. */
export function sendAppCommand(line: string, injected?: MachineController): AppCommandOutcome {
  const ctrl = injected ?? getMachineController()
  const offsetLine = readWorkOffsetLine(ctrl, line)
  if (offsetLine && 'refusal' in offsetLine) return reportWorkOffsetLine(ctrl, unsentOffsetLine(offsetLine.refusal))
  if (offsetLine) {
    // The controller answers later; a refusal still reaches the console naming the line.
    void runWorkOffsetLine(ctrl, line, offsetLine)
    return { ok: true, message: null, sent: true, translated: null, modal: null }
  }
  const geometryLine = readGeometryLine(ctrl, line)
  if (geometryLine && 'refusal' in geometryLine) {
    return reportWorkOffsetLine(ctrl, unsentOffsetLine(geometryLine.refusal))
  }
  if (geometryLine) {
    // The move finishes later; a refusal or a missed target still reaches the console naming the line.
    void runGeometryLine(ctrl, line, geometryLine)
    return { ok: true, message: null, sent: true, translated: null, modal: null }
  }
  return reportAppCommand(ctrl, translateAppCommand(ctrl, line))
}

/** Send one app-issued G-code line through the translator and await it. */
export function sendAppCommandAwait(
  line: string,
  injected?: MachineController,
): Promise<AppCommandOutcome> | null {
  const ctrl = injected ?? getMachineController()
  const offsetLine = readWorkOffsetLine(ctrl, line)
  if (offsetLine && 'refusal' in offsetLine) {
    return Promise.resolve(reportWorkOffsetLine(ctrl, unsentOffsetLine(offsetLine.refusal)))
  }
  if (offsetLine) return runWorkOffsetLine(ctrl, line, offsetLine)
  const geometryLine = readGeometryLine(ctrl, line)
  if (geometryLine && 'refusal' in geometryLine) {
    return Promise.resolve(reportWorkOffsetLine(ctrl, unsentOffsetLine(geometryLine.refusal)))
  }
  if (geometryLine) return runGeometryLine(ctrl, line, geometryLine)
  return translateAppCommandAwait(ctrl, line)?.then((outcome) => reportAppCommand(ctrl, outcome)) ?? null
}

// ---------------------------------------------------------------------------
// WO-1547 - WORK OFFSETS AND WCS SELECT RUN AS CONTROLLER CALLS
// ---------------------------------------------------------------------------
//
// WO-1545 slice 3. On a controller that takes no text, `G10 L2`, `G10 L20` and
// `G54`-`G59` become `setWorkOffset` and the WCS select call, carrying the
// values the line means. This sits at the two doors above rather than in the
// pure translator because only the session holds what such a line leaves
// implicit: the active frame (`P0`) and where the machine stands (`L20`).
// GRBL and the simulator still get the line as text.
//
// L20 ON A GEOMETRY CONTROLLER: "the current point reads V" makes the register
// machine position - V. This controller's tool-length offset is already folded
// into that register (`applyToolLengthOffset`), so it is not subtracted again.
// ---------------------------------------------------------------------------

interface WorkOffsetLinePlan {
  write: { wcs: WcsId; values: Partial<MachinePosition> } | null
  select: WcsId | null
}

const OFFSET_LINE_MODAL_G = new Set([20, 21, 90, 91])
const OFFSET_LINE_AXES = new Set<ControlAxis>(['X', 'Y', 'Z', 'A', 'B', 'C'])

const isFrameWord = (g: number) => Number.isInteger(g) && g >= 54 && g <= 59

/** What a work-offset line becomes on a controller without text; null when it
 *  is not one, or the controller takes text. The line's own units and distance
 *  words apply first, as they would in an interpreter. */
function readWorkOffsetLine(
  ctrl: MachineController,
  line: string,
): WorkOffsetLinePlan | { refusal: string } | null {
  if (ctrl.capabilities.gcodeText || ctrl.connectionPhase() !== 'connected') return null
  const words = tokenizeLine(line, 1).words.filter((w) => w.letter !== 'N')
  const gs = words.filter((w) => w.letter === 'G').map((w) => Math.round(w.value * 10) / 10)
  const g10 = gs.includes(10)
  const frame = gs.filter(isFrameWord).at(-1)
  if (!g10 && frame === undefined) return null
  const refuse = (why: string) => ({ refusal: `${line}: ${why} - nothing was sent.` })
  const stray = words.find((w) => {
    if (w.letter !== 'G') {
      return !(g10 && (w.letter === 'L' || w.letter === 'P'
        || OFFSET_LINE_AXES.has(w.letter as ControlAxis)))
    }
    const g = Math.round(w.value * 10) / 10
    return !(g === 10 || isFrameWord(g) || OFFSET_LINE_MODAL_G.has(g))
  })
  if (stray) return refuse(`${stray.letter}${stray.value} has no call on this controller beside a work-offset command`)
  const plan: WorkOffsetLinePlan = { write: null, select: frame === undefined ? null : (`G${frame}` as WcsId) }
  if (g10) {
    const l = words.find((w) => w.letter === 'L')?.value
    if (l !== 2 && l !== 20) {
      return refuse(`G10 L${l ?? ''} has no call on this controller; G10 L2 and G10 L20 set a work offset`)
    }
    const p = words.find((w) => w.letter === 'P')?.value
    if (p === undefined || !Number.isInteger(p) || p < 0 || p > WCS_SLOTS.length) {
      return refuse(`P${p ?? ''} names no work offset (P0 is the active one, P1-P6 are G54-G59)`)
    }
    const wcs = p === 0 ? store().activeWcs : WCS_SLOTS[p - 1]
    if (!wcs) return refuse('P0 means the active work offset, and none is selected yet')
    if (!ctrl.setWorkOffset) return refuse('this controller has no work-offset call')
    const lineUnits = gs.filter((g) => g === 20 || g === 21).at(-1)
    const inch = lineUnits === undefined ? appCommandModal(ctrl).units === 'inch' : lineUnits === 20
    const position = ctrl.status().machinePos
    const values: Partial<MachinePosition> = {}
    for (const word of words.filter((w) => OFFSET_LINE_AXES.has(w.letter as ControlAxis))) {
      const axis = word.letter as ControlAxis
      const key = offsetAxisKey(axis)
      const value = inch && (axis === 'X' || axis === 'Y' || axis === 'Z')
        ? word.value * 25.4
        : word.value
      let register = value
      if (l === 20) {
        const at = position?.[key]
        if (typeof at !== 'number' || !Number.isFinite(at)) {
          return refuse(`the controller has not reported its machine ${word.letter} position, which G10 L20 sets from`)
        }
        register = at - value
      }
      values[key] = Number(register.toFixed(4))
    }
    if (Object.keys(values).length > 0) plan.write = { wcs, values }
  }
  const modal = gs.filter((g) => OFFSET_LINE_MODAL_G.has(g))
  if (modal.length > 0) reportAppCommand(ctrl, translateAppCommand(ctrl, modal.map((g) => `G${g}`).join(' ')))
  return plan
}

function unsentOffsetLine(message: string): AppCommandOutcome {
  return { ok: false, message, sent: false, translated: null, modal: null }
}

/** A work-offset line that did not run goes to the console naming the line. */
function reportWorkOffsetLine(ctrl: MachineController, outcome: AppCommandOutcome): AppCommandOutcome {
  if (ctrl === controller && !outcome.ok && outcome.message) {
    store().pushConsole(outcome.sent ? 'rx' : 'tx', outcome.message, 'error')
  }
  return outcome
}

/** Issue the calls, and let the controller's reply be the outcome. */
async function runWorkOffsetLine(
  ctrl: MachineController,
  line: string,
  plan: WorkOffsetLinePlan,
): Promise<AppCommandOutcome> {
  const receiptToken = captureBackendReceipt(ctrl)
  const done = (ok: boolean, message: string | null) =>
    reportWorkOffsetLine(ctrl, { ok, message, sent: true, translated: null, modal: null })
  if (plan.write) {
    const { wcs, values } = plan.write
    let receipt: SetWorkOffsetResult
    try {
      receipt = await ctrl.setWorkOffset!(wcs, values)
    } catch (error) {
      receipt = { ok: false, reason: error instanceof Error ? error.message : String(error), offset: null }
    }
    if (!receiptIsCurrent(receiptToken)) {
      return done(false, `${line}: the machine connection changed before setWorkOffset answered.`)
    }
    if (!receipt.ok || !receipt.offset) {
      return done(false, `${line}: the controller refused setWorkOffset ${wcs} - ${receipt.reason ?? 'it returned no offset'}`)
    }
    if (ctrl === controller) {
      // WO-1042's table: an accepted receipt writes only the axes this line sent.
      const machineId = controlMachineId()
      rememberAuthoritativeReportedWorkOffset(machineId, wcs, receipt.offset, receiptToken)
      storeWorkOffset(machineId, wcs, selectOffsetAxes(receipt.offset, values), 'sent')
    }
  }
  if (plan.select) {
    let confirmed = false
    let reason = 'it did not confirm the selection'
    if (typeof ctrl.selectWcsAwait === 'function') {
      try {
        const pending = ctrl.selectWcsAwait(plan.select)
        confirmed = pending ? await pending : false
      } catch (error) {
        reason = error instanceof Error ? error.message : String(error)
      }
    } else {
      confirmed = ctrl.selectWcs(plan.select)
    }
    if (!receiptIsCurrent(receiptToken)) {
      return done(false, `${line}: the machine connection changed before selectWcs answered.`)
    }
    if (!confirmed) return done(false, `${line}: the controller refused selectWcs ${plan.select} - ${reason}`)
    if (ctrl === controller) store().setActiveWcs(plan.select)
  }
  return done(true, null)
}

// ---------------------------------------------------------------------------
// WO-1548 - MOVES, DWELLS AND TOOL LENGTH RUN AS GEOMETRY
// ---------------------------------------------------------------------------
//
// WO-1545 slice 4. On a controller that takes no text, an app-issued move line
// (park, safe Z, the fit trace, probe positioning) becomes the controller's own
// machine-Z and work-XY moves, `G4 P` waits here, and `G43.1`/`G49` change the
// tool-length offset this controller folds into the active work offset's Z
// (`applyToolLengthOffset`). The awaited door resolves when the board reports
// idle AT THE TARGET, never on the call's receipt alone. GRBL and the simulator
// still get the line as text.
//
// FRAMES. `G53` words are machine coordinates. Other words are work
// coordinates, converted with the controller's own simultaneous machine/work
// readback - the same conversion the guided park uses - so an offset the board
// holds (a work offset, a folded tool length) is the offset the move gets.
//
// One line moves Z or XY, never both: this controller has one verb for each,
// and running them one after the other would be a different path from the
// straight line the text names. No app sender issues such a line.
// ---------------------------------------------------------------------------

type GeometryAxisKey = 'x' | 'y' | 'z'

/**
 * WO-2203: THE ROTATION OF THE WORK SYSTEM A STATUS FRAME WAS READ IN.
 *
 * The AXBB-E bridge rotates its active work system about its origin
 * (WO-2186, docs/design/WCS-ROTATION.md) and says by how much in the SAME
 * status frame as the machine and work positions - `workRotation`, degrees,
 * CCW seen from +Z. Its `jogToWorkXY` takes a work point and turns it:
 * machine = O + Rot(R)(work). 0 when the frame carries none (every other
 * controller, and a bridge older than WO-2186).
 */
function statusWorkRotation(status: Pick<MachineStatus, 'machinePos' | 'workPos'>): number {
  const degrees = (status as { workRotation?: unknown }).workRotation
  return typeof degrees === 'number' && Number.isFinite(degrees) ? degrees : 0
}

/**
 * WO-2212: THE ROTATION A CONTROLLER TURNS THE APP'S OWN XY LINES BY.
 *
 * LinuxCNC turns a G91 X Y, and a G90 X Y in the active work system, by that
 * system's `G10 L2 Pn R` (measured on the WO-1982 simulator, WO-2204) and
 * reports the rotation in its status block, not in the frame - so on a
 * controller that takes text it is the controller's report for the active
 * work system (LinuxCNC's power-on G54 before the app has seen a G5x). A
 * frame that carries its own rotation (the AXBB-E bridge, WO-2203) keeps it.
 */
function controllerWorkRotation(
  ctrl: MachineController,
  status: Pick<MachineStatus, 'machinePos' | 'workPos'>,
): number {
  const framed = statusWorkRotation(status)
  if (framed !== 0 || !ctrl.capabilities.gcodeText) return framed
  const degrees = ctrl.wcsRotations?.()?.[store().activeWcs ?? 'G54']
  return typeof degrees === 'number' && Number.isFinite(degrees) ? degrees : 0
}

/** WO-2212: one G-code axis word for the wire ("X12.5") - controller text, not a
 *  position sentence for the operator (WO-1667's formatter covers those). */
function gcodeAxisWord(axis: 'X' | 'Y' | 'Z', mm: number): string {
  return axis + String(mm)
}

/**
 * WO-2212: THE G91 X Y WORDS THAT MOVE (dx, dy) ALONG THE MACHINE AXES on a
 * controller that turns an incremental X Y by `degrees`: it runs the words as
 * Rot(R)(x, y), so they are Rot(-R)(dx, dy) - LinuxCncController.probe()'s
 * own conversion (WO-2204).
 */
function machineStepXYWords(degrees: number, dx: number, dy: number, n: (mm: number) => number): string {
  const step = rotateXY(-degrees, dx, dy)
  return `${gcodeAxisWord('X', n(step.x))} ${gcodeAxisWord('Y', n(step.y))}`
}

/** Rot(deg)(x, y) = (x cos a - y sin a, x sin a + y cos a) - the bridge's own. */
function rotateXY(degrees: number, x: number, y: number): { x: number; y: number } {
  const a = (degrees * Math.PI) / 180
  const c = Math.cos(a)
  const s = Math.sin(a)
  return { x: x * c - y * s, y: x * s + y * c }
}

/**
 * WO-2203: THE WORK XY THAT LANDS ON MACHINE XY (tx, ty) through a
 * controller whose XY verb takes work coordinates (`jogToWorkXY`).
 *
 * A machine position - a park, a G53 line, the setter, a probe cycle's own
 * positioning - is a place on the machine and never turns with a work
 * rotation (LinuxCNC: G53, G28/G30 stored points and jogs are not rotated).
 * Unrotated, the work point is the machine point less the offset the frame
 * shows (machine - work), exactly as before. Rotated by R, that difference
 * is not one offset but changes with the position, so the work point is
 * where the frame stands in work plus the machine step turned back by R:
 * work = work_now + Rot(-R)(target - machine_now), which the bridge turns
 * into O + Rot(R)(work) = target.
 */
function workXYForMachineXY(
  status: Pick<MachineStatus, 'machinePos' | 'workPos'>,
  tx: number,
  ty: number,
  round: (mm: number) => number = (mm) => mm,
  degrees: number = statusWorkRotation(status),
): { x: number; y: number } {
  const machine = status.machinePos!
  const work = status.workPos!
  if (degrees === 0) return { x: round(tx - (machine.x - work.x)), y: round(ty - (machine.y - work.y)) }
  // Not rounded: a rounded work point lands off the machine point by that
  // rounding turned through R.
  const step = rotateXY(-degrees, tx - machine.x, ty - machine.y)
  return { x: work.x + step.x, y: work.y + step.y }
}

type GeometryLinePlan =
  | {
      kind: 'move'
      machineFrame: boolean
      incremental: boolean
      /** Null: the line names no G0/G1 and none is held yet. */
      motion: 0 | 1 | null
      /** mm/min from this line's F word, already in mm. */
      feedMmMin: number | null
      /** mm, already converted from the line's units. */
      axes: Partial<Record<GeometryAxisKey, number>>
    }
  | { kind: 'dwell'; seconds: number }
  /** `deltaMm` null: G49. `h`: a `G43 H<n>`, resolved against the machine's
   *  tool table when the line runs (WO-1677) - the same table and the same
   *  reference math the file route and the TLO panel use. */
  | { kind: 'toolLength'; deltaMm: number | null; h?: number }

interface GeometryMotionModal {
  motion: 0 | 1 | null
  feedMmMin: number | null
}

const geometryMotionModal = new WeakMap<MachineController, GeometryMotionModal>()

const GEOMETRY_LINE_MODAL_G = new Set([20, 21, 90, 91])
const GEOMETRY_LINE_G = new Set([0, 1, 4, 43, 43.1, 49, 53])
const GEOMETRY_TARGET_TOLERANCE_MM = 0.01

/** A new connection starts with no motion mode and no feed held. */
function resetGeometryMotionModal(ctrl: MachineController): void {
  geometryMotionModal.delete(ctrl)
}

/** What a move, dwell or tool-length line becomes on a controller without
 *  text; null when it is none of those (or the controller takes text), so the
 *  work-offset reader or the translator answers it. Reads only. */
function readGeometryLine(
  ctrl: MachineController,
  line: string,
): GeometryLinePlan | { refusal: string } | null {
  if (ctrl.capabilities.gcodeText || ctrl.connectionPhase() !== 'connected') return null
  const words = tokenizeLine(line, 1).words.filter((w) => w.letter !== 'N')
  const gs = words.filter((w) => w.letter === 'G').map((w) => Math.round(w.value * 10) / 10)
  // Probe touches and work offsets have their own doors.
  if (gs.some((g) => Math.floor(g) === 38 || g === 10 || isFrameWord(g))) return null
  const refuse = (why: string) => ({ refusal: `${line}: ${why} - nothing was sent.` })
  const toolLength = gs.find((g) => g === 43 || g === 43.1 || g === 49)
  const dwell = gs.includes(4)
  const motionG = gs.filter((g) => g === 0 || g === 1).at(-1) as 0 | 1 | undefined
  const machineFrame = gs.includes(53)
  const hasAxis = words.some((w) => w.letter === 'X' || w.letter === 'Y' || w.letter === 'Z')
  // G43.1's Z is the offset, not a destination.
  const moves = motionG !== undefined || machineFrame || (hasAxis && toolLength === undefined)
  if (toolLength === undefined && !dwell && !moves) return null

  const stray = words.find((w) => {
    if (w.letter !== 'G') return !['X', 'Y', 'Z', 'F', 'P', 'H'].includes(w.letter)
    const g = Math.round(w.value * 10) / 10
    return !(GEOMETRY_LINE_MODAL_G.has(g) || GEOMETRY_LINE_G.has(g))
  })
  if (stray) return refuse(`${stray.letter}${stray.value} has no call on this controller beside a move`)
  if ([toolLength !== undefined, dwell, moves].filter(Boolean).length > 1) {
    return refuse('this controller runs a move, a dwell and a tool-length change as separate calls, one per line')
  }
  const lineUnits = gs.filter((g) => g === 20 || g === 21).at(-1)
  const inch = lineUnits === undefined ? appCommandModal(ctrl).units === 'inch' : lineUnits === 20
  const mm = (value: number) => (inch ? value * 25.4 : value)
  const word = (letter: string) => words.filter((w) => w.letter === letter).at(-1)?.value

  if (toolLength !== undefined) {
    if (words.some((w) => w.letter === 'X' || w.letter === 'Y' || w.letter === 'F' || w.letter === 'P')) {
      return refuse('a tool-length offset names only its Z')
    }
    if (toolLength === 43.1) {
      const z = word('Z')
      if (z === undefined) return refuse('G43.1 needs the Z it offsets by')
      return { kind: 'toolLength', deltaMm: mm(z) }
    }
    if (word('Z') !== undefined) return refuse(`G${toolLength} takes no Z word`)
    // WO-1677: `G43 H<n>` applies the length the machine's tool table holds
    // for tool n, resolved where the line runs - what UCCNC reads its own
    // table for at this word, and never a silent zero the app could have
    // resolved. A tool with no measured length applies zero, as the
    // controller's own table answers.
    const h = word('H')
    if (toolLength === 43 && h !== undefined) {
      if (!Number.isInteger(h) || h <= 0) return refuse('G43 needs a positive integer H tool-table index')
      return { kind: 'toolLength', deltaMm: null, h }
    }
    return { kind: 'toolLength', deltaMm: null }
  }
  if (dwell) {
    const p = word('P')
    if (p === undefined || !Number.isFinite(p) || p < 0) return refuse('G4 needs P, the dwell in seconds')
    if (words.some((w) => w.letter !== 'G' && w.letter !== 'P')) return refuse('a dwell names only its P')
    return { kind: 'dwell', seconds: p }
  }
  const extra = words.find((w) => w.letter === 'P' || w.letter === 'H')
  if (extra) return refuse(`${extra.letter}${extra.value} has no meaning on a move`)
  const lineDistance = gs.filter((g) => g === 90 || g === 91).at(-1)
  const incremental = lineDistance === undefined
    ? appCommandModal(ctrl).distanceMode === 'incremental'
    : lineDistance === 91
  if (machineFrame && incremental) return refuse('G53 moves are absolute machine coordinates, and G91 is active')
  const motion = motionG ?? geometryMotionModal.get(ctrl)?.motion ?? null
  if (motion === null && hasAxis) return refuse('no motion mode is active yet (G0 or G1)')
  const axes: Partial<Record<GeometryAxisKey, number>> = {}
  for (const w of words) {
    if (w.letter === 'X' || w.letter === 'Y' || w.letter === 'Z') {
      axes[w.letter.toLowerCase() as GeometryAxisKey] = mm(w.value)
    }
  }
  if (axes.z !== undefined && (axes.x !== undefined || axes.y !== undefined)) {
    return refuse('this controller moves Z and XY with separate calls, so one straight XYZ move cannot run as written')
  }
  const f = word('F')
  return {
    kind: 'move',
    machineFrame,
    incremental,
    motion,
    feedMmMin: f === undefined ? null : mm(f),
    axes,
  }
}

/** Run one move, dwell or tool-length line; the outcome is what the board did. */
async function runGeometryLine(
  ctrl: MachineController,
  line: string,
  plan: GeometryLinePlan,
): Promise<AppCommandOutcome> {
  const receiptToken = captureBackendReceipt(ctrl)
  const done = (ok: boolean, message: string | null, sent = true) =>
    reportWorkOffsetLine(ctrl, { ok, message, sent, translated: null, modal: null })
  const modal = tokenizeLine(line, 1).words
    .filter((w) => w.letter === 'G' && GEOMETRY_LINE_MODAL_G.has(w.value))
    .map((w) => `G${w.value}`)
  if (modal.length > 0) reportAppCommand(ctrl, translateAppCommand(ctrl, modal.join(' ')))

  if (plan.kind === 'toolLength') {
    const ok = plan.h !== undefined
      ? applyGeometryToolLengthOffset(ctrl, resolveG43ToolLengthMm(plan.h).deltaMm)
      : plan.deltaMm === null
        ? clearGeometryToolLengthOffset(ctrl)
        : applyGeometryToolLengthOffset(ctrl, plan.deltaMm)
    return ok
      ? done(true, null)
      : done(false, `${line}: the tool-length offset could not be written to the work offset's Z - nothing was sent.`, false)
  }
  if (plan.kind === 'dwell') {
    await new Promise((resolve) => setTimeout(resolve, plan.seconds * 1000))
    if (!receiptIsCurrent(receiptToken)) return done(false, `${line}: the machine connection changed during the dwell.`)
    return done(true, null)
  }

  const held = geometryMotionModal.get(ctrl) ?? { motion: null, feedMmMin: null }
  const next: GeometryMotionModal = {
    motion: plan.motion ?? held.motion,
    feedMmMin: plan.feedMmMin ?? held.feedMmMin,
  }
  geometryMotionModal.set(ctrl, next)
  const named = Object.keys(plan.axes) as GeometryAxisKey[]
  if (named.length === 0) return done(true, null)

  let feed: number
  if (next.motion === 0) {
    feed = controlMachine(useCamStore.getState()).rapidRate
    if (!(Number.isFinite(feed) && feed > 0)) {
      return done(false, `${line}: this machine declares no rapid rate, so the rapid has no speed to run at - nothing was sent.`, false)
    }
  } else {
    if (next.feedMmMin === null || !(Number.isFinite(next.feedMmMin) && next.feedMmMin > 0)) {
      return done(false, `${line}: G1 needs a feed (F) and none is set yet - nothing was sent.`, false)
    }
    feed = next.feedMmMin
  }

  // A frame from after everything this session already wrote: an offset or
  // tool-length receipt changes work position on the board's NEXT frame, and a
  // target resolved from the frame before it would miss by that change.
  const status = await freshGeometryStatus(ctrl)
  if (!receiptIsCurrent(receiptToken)) return done(false, `${line}: the machine connection changed before the move.`, false)
  if (status === null) {
    return done(false, `${line}: the controller did not report its position, so the move's target cannot be resolved - nothing was sent.`, false)
  }
  const machine = status.machinePos
  const work = status.workPos
  const axes: GeometryAxisKey[] = named.includes('z') ? ['z'] : ['x', 'y']
  const reads = (v: MachineVec3 | null, axis: GeometryAxisKey) => v !== null && Number.isFinite(v[axis])
  // Machine position always; work position for a work-frame target and for the
  // XY verb, which takes work coordinates.
  const needsWork = (axis: GeometryAxisKey) => axis !== 'z' || (!plan.machineFrame && !plan.incremental)
  if (axes.some((axis) => !reads(machine, axis) || (needsWork(axis) && !reads(work, axis)))) {
    return done(
      false,
      `${line}: the controller has not reported both machine and work position, so the move's target cannot be resolved - nothing was sent.`,
      false,
    )
  }
  const m = machine!
  const offset = (axis: GeometryAxisKey) => m[axis] - work![axis]
  const target: Partial<MachineVec3> = {}
  // WO-2203: under a work rotation (the XY verb only - Z never turns) a G53
  // target stays the machine point it names, a work target turns about the
  // work origin and an incremental step turns with the work axes (LinuxCNC's
  // G91), so neither is "value + one offset" any more.
  const degrees = axes[0] === 'z' ? 0 : statusWorkRotation(status)
  let workTarget: { x: number; y: number } | null = null
  if (degrees === 0) {
    for (const axis of axes) {
      const value = plan.axes[axis]
      const machineValue = value === undefined
        ? m[axis]
        : plan.incremental
          ? m[axis] + value
          : plan.machineFrame ? value : value + offset(axis)
      target[axis] = Number(machineValue.toFixed(4))
    }
  } else if (plan.machineFrame) {
    target.x = Number((plan.axes.x ?? m.x).toFixed(4))
    target.y = Number((plan.axes.y ?? m.y).toFixed(4))
  } else {
    const w = work!
    // An axis the line does not name keeps its WORK value (absolute) or does
    // not step (incremental) - under a rotation both machine axes still move.
    workTarget = plan.incremental
      ? null
      : { x: plan.axes.x ?? w.x, y: plan.axes.y ?? w.y }
    const step = workTarget === null
      ? rotateXY(degrees, plan.axes.x ?? 0, plan.axes.y ?? 0)
      : rotateXY(degrees, workTarget.x - w.x, workTarget.y - w.y)
    target.x = Number((m.x + step.x).toFixed(4))
    target.y = Number((m.y + step.y).toFixed(4))
  }

  const verb = axes[0] === 'z' ? 'jogToMachineZ' : 'jogToWorkXY'
  // Checked at the last moment before each move: a park or fit trace issues
  // no further move once the E-STOP latch needs reset.
  if (estopNeedsReset()) return done(false, `${line}: ${ESTOP_BLOCKS_MOTION}`, false)
  let accepted: boolean | null
  try {
    if (verb === 'jogToMachineZ') {
      const pending = ctrl.jogToMachineZAwait
        ? ctrl.jogToMachineZAwait(target.z!, feed)
        : Promise.resolve(ctrl.jogToMachineZ(target.z!, feed))
      accepted = pending ? await pending : null
    } else {
      const sendWork = degrees === 0
        ? { x: Number((target.x! - offset('x')).toFixed(4)), y: Number((target.y! - offset('y')).toFixed(4)) }
        : workTarget ?? workXYForMachineXY(status, target.x!, target.y!)
      const wx = sendWork.x
      const wy = sendWork.y
      // WO-1670: a G53 XY is a MACHINE position; this board's XY call takes
      // work coordinates, so say the arithmetic that turned one into the other.
      if (plan.machineFrame) {
        const turned = rotateXY(degrees, work!.x, work!.y)
        const origin = degrees === 0
          ? { x: offset('x'), y: offset('y') }
          : { x: Number((m.x - turned.x).toFixed(4)), y: Number((m.y - turned.y).toFixed(4)) }
        store().pushConsole(
          'tx',
          `${line}: ${formatPosition({ machine: { x: target.x, y: target.y } })} sent as `
            + `${formatPosition({ wcs: 'work', work: { x: wx, y: wy }, withMachine: false })} `
            + `(the work origin the board reported is at ${formatPosition({ machine: origin })}`
            + `${degrees === 0 ? '' : `, rotated ${String(degrees)} deg`}).`,
          'info',
        )
      }
      const pending = ctrl.jogToWorkXYAwait
        ? ctrl.jogToWorkXYAwait(wx, wy, feed)
        : Promise.resolve(ctrl.jogToWorkXY(wx, wy, feed))
      accepted = pending ? await pending : null
    }
  } catch (error) {
    if (!receiptIsCurrent(receiptToken)) return done(false, `${line}: the machine connection changed before ${verb} answered.`)
    return done(false, `${line}: the controller refused ${verb} - ${error instanceof Error ? error.message : String(error)}`)
  }
  if (!receiptIsCurrent(receiptToken)) return done(false, `${line}: the machine connection changed before ${verb} answered.`)
  if (accepted === null) return done(false, `${line}: the controller would not take ${verb} - nothing was sent.`, false)
  if (!accepted) return done(false, `${line}: the controller refused ${verb}.`)

  const distance = Math.hypot(...axes.map((axis) => target[axis]! - m[axis]))
  const timeoutMs = 10_000 + Math.ceil((distance / feed) * 60_000 * 3)
  const arrived = await waitForGeometryMoveArrival(ctrl, target, timeoutMs)
  if (!receiptIsCurrent(receiptToken)) return done(false, `${line}: the machine connection changed during the move.`)
  if (!arrived) {
    const where = ctrl.status().machinePos
    const to = axes.map((axis) => `${axis.toUpperCase()}${machineLengthText(target[axis]!)}`).join(' ')
    const at = where ? axes.map((axis) => `${axis.toUpperCase()}${machineLengthText(where[axis])}`).join(' ') : 'no position'
    return done(false, `${line}: the machine did not report idle at machine ${to}; it last reported ${at}.`)
  }
  return done(true, null)
}

/** The next status frame the controller reports after asking; null when none
 *  arrives within the timeout. */
async function freshGeometryStatus(ctrl: MachineController, timeoutMs = 1000): Promise<MachineStatus | null> {
  const before = ctrl.status()
  const deadline = sessionElapsedNowMs() + timeoutMs
  ctrl.queryStatus()
  while (sessionElapsedNowMs() < deadline) {
    const now = ctrl.status()
    if (now !== before) return now
    await new Promise((resolve) => setTimeout(resolve, 20))
  }
  return null
}

/** Idle AT the target, read twice in a row, within the timeout. */
async function waitForGeometryMoveArrival(
  ctrl: MachineController,
  target: Partial<MachineVec3>,
  timeoutMs: number,
): Promise<boolean> {
  const receiptToken = captureBackendReceipt(ctrl)
  const deadline = sessionElapsedNowMs() + timeoutMs
  let settled = 0
  while (sessionElapsedNowMs() < deadline) {
    ctrl.queryStatus()
    await new Promise((resolve) => setTimeout(resolve, 50))
    if (!receiptIsCurrent(receiptToken)) return false
    if (ctrl.connectionPhase() !== 'connected' || ctrl.machineState() === 'alarm') return false
    const position = ctrl.status().machinePos
    const atTarget = position !== null && (Object.keys(target) as GeometryAxisKey[]).every(
      (axis) => Math.abs(position[axis] - target[axis]!) <= GEOMETRY_TARGET_TOLERANCE_MM,
    )
    settled = ctrl.verifiedIdle() && atTarget ? settled + 1 : 0
    if (settled >= 2) return true
  }
  return false
}

/** Why `line` would not run on this controller, without running it - null
 *  when it would. The session's answer: moves, dwells and tool length run here
 *  although the pure translator cannot run them. */
function appCommandUnsentHere(ctrl: MachineController, line: string): string | null {
  const geometryLine = readGeometryLine(ctrl, line)
  if (geometryLine && 'refusal' in geometryLine) return geometryLine.refusal
  if (geometryLine) return null
  return appCommandUnsent(ctrl, line)
}

/** Why a cycle's probe touch (`G38.2` text) would not run here - null when it
 *  would. A controller with the native probe call runs the touch through it
 *  (WO-1546), so only a controller with neither text nor that call is refused. */
function probeTouchUnsentHere(ctrl: MachineController, touchLine: string): string | null {
  return nativeProbeRoute(ctrl) ? null : appCommandUnsentHere(ctrl, touchLine)
}

/** Fold a tool-length delta into the active work offset's Z, replacing the
 *  delta this controller last applied rather than adding to it. WO-2042: a
 *  `workZeroShiftMm` moves the work zero itself in the same one write - it is
 *  not a tool length, so it is never taken back out by the next tool or G49. */
function applyGeometryToolLengthOffset(c: MachineController, deltaMm: number, workZeroShiftMm = 0): boolean {
  if (!Number.isFinite(deltaMm) || !Number.isFinite(workZeroShiftMm)) return false
  const wcs = pendingToolChange?.hold.wcs ?? store().activeWcs
  if (wcs === null) return false
  const currentZ = store().offsets[wcs]?.[2]
  if (typeof currentZ !== 'number' || !Number.isFinite(currentZ)) return false
  const previousDelta = geometryToolLengthOffset?.controller === c && geometryToolLengthOffset.wcs === wcs
    ? geometryToolLengthOffset.deltaMm
    : 0
  const targetZ = currentZ - previousDelta + deltaMm + workZeroShiftMm
  // WO-2267: a tool length folded into Z moves the tool, not the surface.
  noteToolLengthZShift(wcs, targetZ)
  const write = requestWorkOffsetValue(wcs, 'Z', targetZ, c)
  if (!write) return false
  lastToolLengthWorkZWrite = { wcs, fromZ: currentZ, toZ: targetZ, toolLengthPartMm: deltaMm - previousDelta }
  // WO-2042: the length is in force only if the machine takes the write. A
  // refused receipt leaves G54 Z as it was, so the length it holds is the old one.
  const previous = geometryToolLengthOffset
  const next = { controller: c, wcs, deltaMm }
  geometryToolLengthOffset = next
  write.settled.push((accepted) => {
    if (!accepted && geometryToolLengthOffset === next) geometryToolLengthOffset = previous
  })
  return true
}

/** G49 on a geometry controller: take the folded delta back out of the work
 *  offset it went into. With none applied there is nothing to take out. */
function clearGeometryToolLengthOffset(c: MachineController): boolean {
  const applied = geometryToolLengthOffset
  if (!applied || applied.controller !== c) return true
  const currentZ = store().offsets[applied.wcs]?.[2]
  if (typeof currentZ !== 'number' || !Number.isFinite(currentZ)) return false
  noteToolLengthZShift(applied.wcs, currentZ - applied.deltaMm)
  const ok = setWorkOffsetValue(applied.wcs, 'Z', currentZ - applied.deltaMm, c)
  if (ok) geometryToolLengthOffset = null
  return ok
}

/** Mirror locally held modal state into the store (the Control page chip and
 *  the pendant read it there), and put a line that did not run in the console
 *  naming the command. */
function reportAppCommand(ctrl: MachineController, outcome: AppCommandOutcome): AppCommandOutcome {
  if (ctrl !== controller) return outcome
  const modal = outcome.modal
  if (modal) {
    useMachineControl.setState((s) => ({
      parserModal: {
        units: modal.units,
        distanceMode: modal.distanceMode,
        motionMode: s.parserModal?.motionMode ?? null,
      },
    }))
  }
  if (outcome.translated !== null && outcome.translated !== 'modal' && outcome.message) {
    store().pushConsole('tx', outcome.message, 'error')
  }
  return outcome
}

/** The reason an outcome did not run, when it never reached the controller -
 *  so a caller reports THAT, never a probe miss or a failed move. */
function unsentReason(outcome: AppCommandOutcome | null): string | null {
  return outcome && !outcome.ok && !outcome.sent ? outcome.message : null
}

/**
 * Can this connection run G-code TEXT (`sendCommand`, `sendCommandAwait`,
 * `loadJob`, `loadJobFrom`)?
 *
 * NO BACKEND INSTALLED MEANS YES, and deliberately so. This is called from
 * render, and `getMachineController()` INSTALLS a GRBL backend when there is
 * none - a render must never have that side effect. It is also the honest
 * answer: with nothing connected there is no controller to have refused
 * anything, and every control in question is already disabled by
 * `connectionPhase`, so a `false` here would only mislabel why.
 */
export function controllerTakesGcodeText(injected?: MachineController): boolean {
  const ctrl = injected ?? controller
  if (!ctrl) return true
  return ctrl.capabilities.gcodeText
}

/**
 * GRBL's event channel. WO-423 made almost all of it the CONTRACT's
 * `ControllerEvents`; WO-426 (contract v4) closes the last gap: `inputs` now
 * decodes the same six lamps the Control page renders (see
 * `grbl/controller.ts` `status()`), and `ConsoleEntry.severity` is the union
 * of both vocabularies, so `onConsole` needs no override at all here - GRBL's
 * own echo severity (info/command/error) is a subset of the contract's, and
 * `shared.onConsole` (typed to accept the wider union) satisfies it directly.
 *
 * `onStatus` still needs a thin wrapper - not because the CONTRACT is short
 * anything now, but because `GrblControllerEvents.onStatus` (in
 * `grbl/controller.ts`) still emits the raw parsed report + derived position,
 * not a `MachineStatus`. That raw shape is exercised directly by
 * grblController.test.ts / grblSimulator.test.ts / accessoryState.test.ts,
 * none of which are owned or in-slice for WO-426, so this wrapper leaves it
 * be and instead uses the callback purely as a "new report arrived" signal:
 * it reads the authoritative `MachineStatus` back off the controller (which
 * now carries the full six-input decode) and runs it through the exact same
 * handler every other backend uses.
 */
function buildGrblEvents(scope: BackendEventScope) {
  const shared = buildContractEvents(scope)
  return {
    ...shared,
    // No return-type annotation on this function on purpose: overriding
    // `onStatus` with a zero-arg function here (rather than widening it back
    // to `ControllerEvents`'s `(status: MachineStatus) => void`) is what lets
    // this object structurally satisfy `GrblControllerEvents.onStatus`'s
    // `(report, derived) => void` shape without importing that type name -
    // a function that ignores its arguments is assignable to a caller that
    // passes more of them.
    onStatus: () => {
      if (acceptsBackendEvent(scope) && scope.controller) {
        shared.onStatus?.(scope.controller.status())
      }
    },
  }
}

/**
 * The CONTRACT's event channel - what EVERY backend raises. WO-423 (contract
 * v3) added the job-progress, job-lifecycle, alarm, offset, settings, homing,
 * accessory and ready members that were missing, so this is now the whole
 * wiring rather than the subset a non-GRBL backend had to make do with; GRBL
 * builds on top of it for the two members that could not cross honestly.
 *
 * A backend that cannot raise one of these simply never calls it. Nothing here
 * invents an event on a controller's behalf.
 */
/** Exported so a harness can deliver a status frame exactly the way a backend
 *  does. WO-1042's fifty-frame test proves there is NO path from a
 *  `MachineStatus` into the durable offset store, and the only honest way to
 *  prove that is to drive the real handler rather than to read the source. */
export function buildContractEvents(scope?: BackendEventScope): ControllerEvents {
  let programFinished = false
  const accepts = () => acceptsBackendEvent(scope)
  const announceHome = (axes: ControlAxis[] | null): void => {
    if (settingMachinePosition) return
    const homedAxes = scope?.homeAnnouncement?.requested ?? axes
    if (scope) scope.homeAnnouncement = undefined
    if (store().homed) {
      store().pushConsole('rx', 'Homed - machine coordinates set.', 'info')
    } else if (homedAxes?.length) {
      store().pushConsole('rx', `Homed ${homedAxes.join(', ')} - machine coordinates set for those axes.`, 'info')
    }
  }
  // UCCNC applies an override asynchronously. Its immediate SetFRO/GetFRO
  // round trip can therefore report the value from before the press and emit
  // a false clamp notice. Hold that candidate for the status frames, which are
  // the same readback authority the panel uses.
  // WO-2670: the NEXT frame is no better. At 40 Hz it is often sampled before
  // the board applied the press too (quick Feed -10/+10 clicks printed eight
  // false lines, 2026-10-07). A frame still showing the value from before the
  // press proves nothing until OVERRIDE_CLAMP_SETTLE_MS has passed; a frame
  // that left that value has seen the press, and two such frames agreeing
  // away from the request are the board's answer. A frame showing the request
  // ends it silently, and a newer press on the channel retires it (see
  // `tapBridgeOverrideCalls`).
  const pendingOverrideClamps = scope?.overrideClamps ?? new Map<OverrideChange['kind'], PendingOverrideClamp>()
  const recentOverrideAsks = new Map<OverrideChange['kind'], Array<{ asked: number; atMs: number }>>()
  const overrideClampNotice = /^the controller clamped the (feed|rapid|spindle) override to (-?\d+(?:\.\d+)?)% \(asked for (-?\d+(?:\.\d+)?)%\)$/
  const resolveOverrideClampNotices = (status: MachineStatus): void => {
    for (const [kind, pending] of pendingOverrideClamps) {
      const reported = status.overrides?.[kind]
      if (typeof reported !== 'number') continue
      const { requested } = pending
      if (Math.abs(reported - requested) <= 0.51) {
        pendingOverrideClamps.delete(kind)
        continue
      }
      // WO-2670 review: a readback at a value an earlier press asked for may
      // be that press landing while this one is still on its way, so it waits
      // like the old value does.
      const sawPress = Math.abs(reported - pending.held) > 0.51
        && !pending.earlierAsks.some((asked) => Math.abs(reported - asked) <= 0.51)
      const settled = sawPress
        ? pending.lastReadback !== null && Math.abs(reported - pending.lastReadback) <= 0.51
        : sessionElapsedNowMs() - pending.notedAtMs >= OVERRIDE_CLAMP_SETTLE_MS
      pending.lastReadback = reported
      if (!settled) continue
      pendingOverrideClamps.delete(kind)
      // A board refusing `requested` holds a value from `held` toward it. A
      // readback past the request, or behind `held`, answers another press.
      const low = Math.min(pending.held, requested)
      const high = Math.max(pending.held, requested)
      if (reported < low - 0.51 || reported > high + 0.51) continue
      const held = reported.toFixed(1).replace(/\.0$/, '')
      const asked = requested.toFixed(1).replace(/\.0$/, '')
      store().pushConsole(
        'rx',
        `the controller clamped the ${kind} override to ${held}% (asked for ${asked}%)`,
        'warn',
      )
    }
  }
  // Throttling belongs to this backend event scope. A replacement connection
  // must never inherit the prior controller's phase/timestamp and suppress its
  // first live progress frame.
  let progressEmitAt = 0
  let progressPhase = ''
  let progressAcked = -1
  let progressTimer: ReturnType<typeof setTimeout> | null = null
  let pendingProgress: StreamerProgress | null = null
  let pendingProgressJob: ReturnType<typeof store>['job'] | null = null
  let pendingProgressAt = 0
  const emitProgress = (progress: StreamerProgress, receivedAt = sessionElapsedNowMs()): void => {
    progressPhase = progress.phase
    progressEmitAt = receivedAt
    progressAcked = progress.ackedLines
    store().applyJobProgress(progress)
  }
  const publishJobProgress = (progress: StreamerProgress): void => {
    if (!accepts()) return
    progress = wholeProgramProgress(progress)
    followStreamedWcs(progress.ackedSourceLine)
    const now = sessionElapsedNowMs()
    const isEdge =
      progress.phase !== progressPhase
      || progress.ackedLines >= progress.totalLines
      // Single Block's next Step and WO-051 Back are both gated on the
      // acked cursor. A fast ok commonly arrives inside the 100ms render
      // throttle; when it catches the one sent line, that settled boundary
      // must render immediately or both controls remain falsely disabled.
      || (progress.ackedLines > 0 && progress.ackedLines === progress.sentLines)
      // The same boundary on a controller that queues the whole program
      // (sent === total from load): under Single Block every change in the
      // done count is a finished block. Board 2026-09-14 (WO-1530): the idle
      // frame that finished a block landed 94 ms after the last run frame and
      // was throttled away, leaving the transport a block behind.
      || (scope?.controller?.singleBlockMode() === true && progress.ackedLines !== progressAcked)
    if (!isEdge && now - progressEmitAt < 100) {
      pendingProgress = progress
      pendingProgressJob = store().job
      pendingProgressAt = now
      if (progressTimer === null) progressTimer = setTimeout(() => {
        progressTimer = null
        const latest = pendingProgress
        const stillCurrent = store().job === pendingProgressJob
        pendingProgress = null
        pendingProgressJob = null
        // A kept stop or a new load can restore its own job without another
        // backend edge. A delayed old progress value cannot take it back.
        // Use receipt time for the window: publishing later is not new data.
        if (latest && stillCurrent && accepts()) emitProgress(latest, pendingProgressAt)
      }, 100 - (now - progressEmitAt))
      return
    }
    if (progressTimer !== null) clearTimeout(progressTimer)
    progressTimer = null
    pendingProgress = null
    pendingProgressJob = null
    emitProgress(progress)
  }
  return {
    onConnectionPhase: (phase, detail) => {
      if (!accepts()) return
      if (phase !== 'connected') {
        if (progressTimer !== null) clearTimeout(progressTimer)
        progressTimer = null
        pendingProgress = null
        pendingProgressJob = null
      }
      if (scope && phase !== 'connected') scope.homeAnnouncement = undefined
      if (phase !== 'connected') {
        pendingOverrideClamps.clear()
        recentOverrideAsks.clear()
        // A call unanswered on a link that dropped is never answered.
        scope?.overrideCallsInFlight?.clear()
      }
      const previousPhase = scope?.phase ?? store().connectionPhase
      if (scope && phase === 'connecting' && previousPhase === 'disconnected') {
        if (scope.connectStarted) beginBackendGeneration(scope)
        else {
          scope.connectStarted = true
          // Initial installation already minted and reset this generation.
          // A message backend's transport is not started at this edge, so its
          // explicit synchronization must wait for the connected edge below.
        }
      }
      if (scope && phase === 'connected' && previousPhase !== 'connected') {
        // The controller is reset before the store publishes connected
        // controls, but only after message transports can actually carry the
        // OFF frame. In particular, the UCCNC bridge process outlives this
        // client session and must receive the value rather than merely have
        // the local controller flag reset.
        scope.controller?.setSingleBlockMode(false)
      }
      if (scope) scope.phase = phase
      handleConnectionPhase(phase, detail, previousPhase)
    },
    onReady: (version) => {
      if (accepts()) store().setWelcome(version)
    },
    onStatus: (status) => {
      if (!accepts()) return
      // WO-2517: first, so a probe touching outside a touch stops the move on this frame.
      watchProbeInput(scope?.controller ?? null, status)
      followOperatorMotionStop(scope?.controller ?? null, status.state)
      applyContractStatus(status)
      const announcement = scope?.homeAnnouncement
      if (announcement) {
        if (status.state === 'home') announcement.sawHome = true
        // Some controllers publish Cartesian homed pushes only, then settle
        // the entire call (including rotary axes) from home to idle. A full
        // named completion is handled by onHomed on every backend instead.
        const missingRotaryOnly = [...announcement.remaining].every((axis) => (
          axis === 'A' || axis === 'B' || axis === 'C'
        ))
        const driveFault = (status as MachineStatus & { driveFault?: { latched?: unknown } }).driveFault
        if (status.state === 'alarm' || status.inputs?.estop === true || driveFault?.latched === true) {
          if (scope) scope.homeAnnouncement = undefined
        } else if (announcement.sawHome && missingRotaryOnly && status.state === 'idle') {
          announceHome(announcement.requested)
        }
      }
      refreshWorkRotations()
      resolveOverrideClampNotices(status)
      if (status.state === 'run' && pathFidelityArmed) geometryStepMotionSeen.set(pathFidelityArmed, true)
      const liveGeometryProgress = scope?.controller
        ? geometryPartProgress(scope.controller, status, false)
        : null
      if (liveGeometryProgress) publishJobProgress(liveGeometryProgress)
      // WO-1275: a `vfd` push re-raises this event as soon as the inverter
      // reports a new speed, so the cut is released on the frame that says
      // "arrived" rather than on the next tick of the gate's own timer.
      pollSpindleSpeedWait()
      advanceProgramPartIfComplete()
      if (scope?.controller) restageProgramDroppedByAlarm(scope.controller)
      // WO-2234: the first settled Idle after an MDI line over the file.
      if (scope?.controller) settleProgramAfterMdiLine(scope.controller)
      // WO-2519: a finished command in a kept stop gives up its name.
      if (scope?.controller) settleKeptStopCommand(scope.controller)
      // WO-2580: the way back is over once the program part runs.
      if (scope?.controller) settleKeptStopReturn(scope.controller)
    },
    onParserState: (state) => {
      if (accepts()) store().applyParserState(state)
    },
    // Contract v4 (WO-426): ConsoleEntry.severity (info/command/warn/error) is
    // the union of every backend's vocabulary and the store now carries all
    // four - straight through, no more collapsing 'warn' into 'error'.
    onConsole: (entry) => {
      if (!accepts()) return
      if (scope && entry.severity === 'error' && /^(homeAxes|home): /.test(entry.text)) {
        scope.homeAnnouncement = undefined
      }
      // WO-2153: the controller's own word that the start failed is the whole
      // story; a typed line's held "staged and started" row is never written.
      if (entry.severity === 'error' && entry.text.startsWith('startJob: ')) {
        settleMdiRowAwaitingStart(scope?.controller ?? null, false)
        // WO-2234: the board turned the line away - it never runs.
        endMdiLineOverFile(scope?.controller ?? null)
      }
      const clamp = entry.dir === 'rx' && entry.severity === 'warn'
        ? overrideClampNotice.exec(entry.text)
        : null
      if (clamp !== null) {
        const kind = clamp[1] as OverrideChange['kind']
        const requested = Number(clamp[3])
        const held = Number(clamp[2])
        const notedAtMs = sessionElapsedNowMs()
        const asks = (recentOverrideAsks.get(kind) ?? [])
          .filter((ask) => notedAtMs - ask.atMs < OVERRIDE_CLAMP_SETTLE_MS)
        const earlierAsks = asks.map((ask) => ask.asked)
        asks.push({ asked: requested, atMs: notedAtMs })
        recentOverrideAsks.set(kind, asks)
        // WO-2670 review: the note answers the oldest unanswered call on its
        // channel. If a later one is also unanswered, the operator has already
        // replaced the press it describes; it says nothing about the board
        // refusing the current one (see `tapBridgeOverrideCalls`).
        let unanswered = 0
        for (const callKind of scope?.overrideCallsInFlight?.values() ?? []) {
          if (callKind === kind) unanswered += 1
        }
        if (unanswered > 1) return
        pendingOverrideClamps.set(kind, {
          requested,
          held,
          notedAtMs,
          lastReadback: null,
          earlierAsks,
        })
        return
      }
      const operatorStop = entry.dir === 'rx'
        ? operatorStopForBridgeReport(scope?.controller ?? null, entry.text)
        : null
      if (operatorStop !== null) {
        store().pushConsole('rx', operatorStop, 'info')
        return
      }
      if (holdGuardedProbeMiss(scope?.controller ?? null, entry)) return
      store().pushConsole(entry.dir, entry.text, entry.severity)
      const target = scope?.controller
      if (
        supportsWorkOffsetWrites(target)
        && scope !== undefined
        && scope.phase === 'connected'
        && scope.workOffsetConnectReconcileComplete
        && entry.dir === 'rx'
        && entry.text.startsWith('[bridge] THE CONTROLLER IS OPEN AGAIN')
      ) {
        // A reopen is a new physical controller session even though the
        // websocket stayed up. Any old receipt is therefore stale, including
        // one holding the shared work-offset slot. Advance the same receipt
        // boundary used by disconnect/connect, discard a not-yet-sent intent,
        // and let this reopen own the slot immediately.
        const machineId = controlMachineId()
        connectionRevision++
        if (openWorkOffsetWrite?.machineId === machineId) openWorkOffsetWrite = null
        setWorkOffsetWriteInFlight(machineId, false)
        const reopenGeneration = scope.generation
        const reopenSequence = ++scope.controllerReopenRestoreSequence
        void restoreWorkOffsetsAfterControllerReopen(machineId, target)
          .catch((error) => {
            if (
              !accepts()
              || scope.generation !== reopenGeneration
              || scope.controllerReopenRestoreSequence !== reopenSequence
              || target.connectionPhase() !== 'connected'
            ) return
            store().pushConsole(
              'rx',
              `Work zeros could not be restored after the controller reopened: ${error instanceof Error ? error.message : String(error)}`,
              'error',
            )
          })
      }
    },
    onClose: (reason) => {
      if (!accepts()) return
      if (reason) store().pushConsole('rx', reason, 'error')
    },
    onAlarm: (code, message, positionLost) => {
      if (!accepts()) return
      if (scope) scope.homeAnnouncement = undefined
      // WO-1996: only the alarm raised while the guided measure probes is its
      // own miss. One after that is a fault, and a held program ends on it.
      if (guidedMeasure !== null && !guidedMeasure.probing) guidedMeasure.missAlarm = false
      const machineId = controlMachineId()
      if (positionLost && physicalMachineConnection()) {
        useCamStore.getState().revokeMachineDatum(machineId, null)
      }
      // Alarm-capable backends revoke their own datum before publishing this
      // event. Mirror that authority before publishing the alarm banner, so
      // no UI subscriber can observe "position lost" beside a homed gate.
      store().setHomed(controller?.homedThisSession() === true)
      store().setAlarm({ code, message, positionLost })
      // AND to the console, because that is where this machine's messages go.
      // Operator's standing rule, given four times now: reuse an existing surface,
      // never a new element, and never one that shifts the layout when it
      // appears. Until 2026-08-23 the alarm text existed ONLY inside a block
      // in the Machine panel, so deleting that block would have deleted the
      // information - this line is what makes removing it safe.
      //
      // WO-1352: `positionLost: false` says the position COUNTER is still
      // trusted. It does not say nothing moved, and this line used to read
      // "Position was retained." directly under a trip after which X had
      // travelled 13.5 mm. The readout is the measurement; point at it.
      store().pushConsole(
        'rx',
        `Alarm${code === null ? '' : ' ' + code}: ${message}${
          positionLost
            ? ' Machine position may be lost - home again before moving.'
            : message.startsWith(TRAVEL_REFUSAL_PREFIX)
              ? travelRefusalNextStep()
              : ' No re-home needed - the position readout shows where the machine is now.'
        }`,
        'error',
      )
      if (scope?.controller) publishProgramDroppedByAlarm(scope.controller, publishJobProgress)
    },
    // Spindle/coolant, only when `capabilities.ownsSpindle` - a backend that
    // does not own them (the AXBB-E's is on a separate Modbus link) simply
    // never calls this. WO-426: previously unwired, so `applyContractStatus`
    // hardcoded the store's reportedAccessories to all-off on every status
    // poll; now it is set here, on its own channel, and status polls leave it
    // alone.
    onAccessories: (state) => {
      if (accepts()) store().setReportedAccessories(state)
    },
    // Acks can arrive at hundreds per second on dense programs; throttle the
    // store (and thus React) to 10Hz, but never skip a phase change or the
    // final ack.
    onJobProgress: (progress) => {
      publishJobProgress(progress)
    },
    // WO-1008. The session raises this on its own channel too - see
    // `finishPathFidelityRun` - so a backend that computes fidelity itself and
    // the session's own monitor land in exactly one place.
    onPathFidelity: (report) => {
      if (accepts()) reportPathFidelity(report)
    },
    onJobEvent: (event, fault) => {
      if (!accepts()) return
      // A lifecycle edge can arrive without another progress callback. Keep
      // its last cursor, then let that edge own the phase; no old timer may
      // put a stopped or paused job back into streaming.
      if (progressTimer !== null) clearTimeout(progressTimer)
      progressTimer = null
      const latest = pendingProgress
      const stillCurrent = store().job === pendingProgressJob
      pendingProgress = null
      pendingProgressJob = null
      if (latest && stillCurrent) emitProgress(latest, pendingProgressAt)
      // Capture ownership before applyJobLifecycleEvent retires an MDI line.
      const programEvent = !mdiLineOverLoadedProgram(scope?.controller ?? null) && !standaloneMdiJob()
      if (event === 'started' && programEvent) programFinished = false
      if (event === 'stopped' || event === 'completed' || event === 'failed') terminalJobEventsSeen += 1
      // WO-2153: the board's answer to a typed line's start, written before the
      // run's own lifecycle rows so the line reads first.
      if (event === 'started') jobStartedEvents += 1
      // WO-2651 item 11: a new job's first frames may still name the last one's move.
      if (event === 'started') retainedMoveIdUnproven = lastProgramMoveIdReported
      settleMdiRowAwaitingStart(scope?.controller ?? null, event === 'started')
      if (
        (event === 'started' || event === 'paused' || event === 'resumed')
        && scope?.controller
        && !scope.controller.capabilities.gcodeText
        && scope.controller.capabilities.executingMoveId === true
        && pathFidelityArmed?.kind === 'geometry'
      ) {
        // Geometry bridges report lifecycle and execution identity on separate
        // channels. Started must retire ready on the board's own event, too:
        // K4 read "checks passed" until the first executing-id status poll.
        // Preserve the last proven count; the next id owns its advancement.
        const current = stagedJobCounts()
        store().applyJobProgress({
          phase: event === 'paused' ? 'paused' : 'streaming',
          totalLines: current.totalLines,
          sentLines: current.sentLines,
          ackedLines: current.ackedLines,
          ackedSourceLine: current.ackedSourceLine,
          sentSourceLine: current.sentSourceLine,
          bytesInFlight: scope.controller.jobProgress().bytesInFlight,
        })
      }
      if (event === 'completed' && scope?.controller) {
        const terminalGeometryProgress = geometryPartProgress(scope.controller, null, true)
        if (terminalGeometryProgress) publishJobProgress(terminalGeometryProgress)
      }
      // WO-2655: a job a refused load left running ends on the board's own edge.
      if (scope?.controller) settleJobUnderRefusedLoad(scope.controller, event)
      if (handleProgramPartJobEvent(event, fault)) return
      applyJobLifecycleEvent(event, fault)
      // WO-2667: and so does any job's terminal edge the store has not followed.
      if (scope?.controller) settleRunAtTerminalEdge(scope.controller, event)
      if (event === 'completed' && store().stagedProgram && programEvent && !programFinished) {
        programFinished = true
        store().pushConsole('rx', `${store().job.name ?? 'Program'} finished.`, 'info')
      }
    },
    onOffset: (entry) => {
      if (accepts()) store().applyOffset(entry)
    },
    // Contract v3 keys a setting however its controller keys them - a string.
    // The store's settings table is a GRBL `$N` dump by construction (the
    // travel envelope reads $130/$131/$132/$23/$27 back out of it by number),
    // so a numeric key crosses exactly and anything else is DROPPED rather
    // than coerced to NaN and filed under a key nothing can look up. Recorded
    // as a WO-423 finding: the store's table is narrower than the contract.
    onSetting: (key, value) => {
      if (!accepts()) return
      const numeric = Number(key)
      if (!Number.isInteger(numeric)) return
      store().applySetting(numeric, value)
      publishGrblSettingReadback(numeric, value)
    },
    onHomed: (axes) => {
      if (!accepts()) return
      if (physicalMachineConnection()) {
        const revokedAxes = axes?.filter((axis): axis is JogAxis => (
          axis === 'X' || axis === 'Y' || axis === 'Z'
        )) ?? null
        useCamStore.getState().clearMachineDatumRevocation(controlMachineId(), revokedAxes)
      }
      // WO-930: the store's `homed` is a WHOLE-MACHINE boolean (the envelope
      // and the probe-readiness chips read it), and it used to be set true by
      // any completed cycle - so homing Z alone claimed a datum for X and Y
      // here too. Ask the controller, which now answers about every gate axis.
      // Strictly less permissive than the unconditional `true` it replaces.
      store().setHomed(controller?.homedThisSession() === true)
      // WO-2520: an already-known datum does not finish this Home All.
      // Keep per-axis reconciliation and refreshes; only the words wait.
      const announcement = scope?.homeAnnouncement
      if (announcement && !settingMachinePosition) {
        if (axes === null) announcement.remaining.clear()
        else for (const axis of axes) announcement.remaining.delete(axis)
      }
      if (!settingMachinePosition && (!announcement || announcement.remaining.size === 0)) announceHome(axes)
      // Position semantics changed - re-read modal state and offsets.
      controller?.refreshState()
    },
  }
}

/**
 * MachineStatus -> the store's snapshot. One field cannot cross honestly and
 * is a WO-422 finding, unchanged by WO-426:
 *  - `overrides` is per-channel nullable in the contract (the AXBB-E has no
 *    rapid override at all) but all-or-nothing in the store, so a partial set
 *    is passed as null - the store then keeps its previous value rather than
 *    showing an invented rapid percentage.
 *
 * `inputs` (WO-426, contract v4) now carries the full six-lamp decode and
 * crosses straight through. Accessories do NOT cross here - they arrive on
 * their own `onAccessories` channel (see `buildContractEvents`), which fires
 * only for a backend that owns them; passing the store's own current value
 * back through `applyStatus` on every poll is a deliberate no-op rather than
 * a second, competing source of truth for the same field.
 */
/**
 * The last HARDWARE e-stop reading we acted on, so the latch arms on the
 * rising edge only.
 *
 * Level-triggering this would be a bug with teeth: `armEstopNeedsReset()`
 * bumps the epoch and clears the pending status waiters, so re-arming on
 * every frame while the button is held would supersede every reset attempt
 * the operator makes - the machine would refuse to clear forever, and the
 * refusal would blame motion. The keepalive polls status every 750 ms, so
 * "every frame" is not hypothetical.
 */
let lastReportedHardwareEstop = false

/** WO-2651 item 11: A RETAINED CurrentID IS NOT THIS JOB'S MOVE. The AXBB-E
 *  board keeps its CurrentID after a job ends (Machine.cs section 12.3), and the
 *  bridge's guard against it is armed only for jobs over 4095 moves
 *  (Machine.cs:9976); a smaller job uses its moves' own ids on the wire, so the
 *  last job's final id names a live move of the next one - after an edit is
 *  applied, a DIFFERENT line - until the board reaches the new job's first
 *  move. The bridge's own rule for paced jobs (Machine.cs:10681) is used for
 *  every job here: the id last reported before this job is credited only once
 *  a different id proves the job has advanced. Unknown is null (WO-2564), so
 *  the listing and the 3D view show no move rather than the wrong one. Only a
 *  program-door controller (no G-code text route) reports board-local ids. */
let lastProgramMoveIdReported: number | null = null
let retainedMoveIdUnproven: number | null = null

function provenExecutingMoveId(ctrl: MachineController | null, id: number | null): number | null {
  if (!ctrl || ctrl.capabilities.gcodeText === true || ctrl.capabilities.executingMoveId !== true) return id
  if (!ctrl.hasActiveJob()) {
    // Between jobs (and on the next job's 'started' edge, which arms it too):
    // whatever the board names next is unproven until it changes.
    retainedMoveIdUnproven = lastProgramMoveIdReported
    return id
  }
  if (id === null) return null
  if (retainedMoveIdUnproven !== null) {
    if (id === retainedMoveIdUnproven) return null
    retainedMoveIdUnproven = null
  }
  lastProgramMoveIdReported = id
  return id
}

function applyContractStatus(status: MachineStatus): void {
  // Pass the per-channel nulls straight through. This used to collapse the
  // WHOLE object to null if any single channel was null, and the store then
  // kept its previous value - so on a controller with no rapid override (the
  // AXBB-E) the feed and spindle overrides it DOES report were discarded and
  // the panel sat frozen at 100%.
  const overrides = status.overrides
  store().applyStatus(
    status.state,
    status.subState,
    status.machinePos,
    status.workPos,
    status.feedMmMin,
    status.spindleRpm,
    overrides,
    status.inputs,
    store().reportedAccessories,
  )
  // WO-2234: the listing on screen is the file's, and an MDI line's move ids
  // are not its steps - no file line is highlighted while the line runs.
  store().setExecutingMoveId(
    mdiLineOverLoadedProgram(controller) ? null : provenExecutingMoveId(controller, status.executingMoveId ?? null),
  )
  // WO-1671: the PROBING lamp reads the controller's own cycle flag from the
  // frame. A frame without the field (GRBL, the simulator) is "not reported".
  store().setProbeCycle(typeof status.probeCycle === 'boolean' ? status.probeCycle : null)
  // WO-1125: the controller has already adopted this frame before raising
  // onStatus, so the store derives its aggregate from the same resolver every
  // motion gate and DRO glow asks. The push/apply writes remain immediate
  // responses; every later frame is allowed to revise that pessimism or edge.
  store().setHomed(controller?.homedThisSession() === true)

  // WO-1109: literal true is the only latched wire value. BridgeTransport has
  // already normalised current/older bridge frames, while every other backend
  // simply has no such key and therefore remains false. This reports edges;
  // repeated keepalive frames stay silent.
  const softLimitLatched = (status as MachineStatus & { softLimitLatched?: unknown })
    .softLimitLatched === true
  publishSoftLimitLatch(softLimitLatched, true)

  // A PHYSICAL E-STOP IS AN E-STOP. Operator's requirement, at the machine
  // 2026-08-23: "the e-stop on the machine in the software should know if I
  // hit the physical stop", and his ruling on what it should then do - the
  // same as a software E-STOP, because the machine IS stopped and clearing it
  // must be a deliberate act.
  //
  // Until the bridge fix of the same day this could not be written at all:
  // GetStatus returns UC100_ESTOP while the button is in, and the bridge
  // turned that into state 'unknown' with the whole inputs block nulled, so
  // `inputs.estop` never once arrived as true. Nothing in src/ read it.
  //
  // NOT emergencyStop(): the machine has already stopped itself, and on this
  // backend that call reaches UC100.SetEstopState(), which the UC100 API
  // offers no way to undo. Arming the latch is the whole action.
  const hardwareEstop = status.inputs?.estop === true
  if (hardwareEstop && !lastReportedHardwareEstop) {
    armEstopNeedsReset()
    // Same debounce a software trigger gets: a stop the operator did not
    // initiate deserves the same protection from an accidental double-tap
    // clearing it the instant it appears.
    startEstopResetDebounce()
  }
  lastReportedHardwareEstop = hardwareEstop

  // WO-1008/1353: every status frame of a running job is one sample of the path
  // the machine ACTUALLY flew. Each sample crosses to the analysis worker now,
  // while the job is streaming; the terminal operator action only sends the
  // worker a finish message and never walks the recording on this thread.
  recordPathFidelitySample(status)

  notifyEstopStatusWaiters(status.state)
}

// ---------------------------------------------------------------------------
// PATH FIDELITY (WO-1008) - the product's own check that the machine flew the
// path it was given.
//
// A dropped block of moves passes every instrument we had: the surviving arcs
// stay round, the feed reads honest, the buffer never starves, `loadMoves`
// returns ok, the job COMPLETES, and the machine ends exactly where the program
// said it should - because a skip is a shortcut between two points that are
// both correct. Only comparing the reported path against the commanded path
// finds it, so the session records one sample per status frame while a job runs
// and hands the two to `analysePathFidelity` when the job ends.
//
// IT REPORTS. It never gates a run, never blocks a stop, and nothing in this
// block can refuse anything - the rule WO-944 carries.
// ---------------------------------------------------------------------------

/**
 * WHAT THE NEXT JOB WILL COMMAND, ARMED BY THE LOAD THAT PREPARED IT.
 *
 * TWO DOORS, BECAUSE THE PRODUCT HAS TWO PROGRAM ROUTES AND ONLY ONE OF THEM
 * IS TEXT. `loadJob` takes G-code and `loadMoves` takes id-tagged geometry
 * (`controller.ts`: "the AXBB-E has no interpreter of its own, so its only
 * program route is `loadMoves`"), and attempt 1 of this order armed from the
 * TEXT route alone. `loadMachineProgram` returns early for any controller
 * without `capabilities.gcodeText`, which is the AXBB-E permanently, so on the
 * one backend this detector was designed for the arming never ran at all and
 * the audit was right to fail it.
 *
 * So the `geometry` door is back, and this time it is not speculative: it is
 * where a geometry job WILL arrive. The route itself does not exist yet -
 * measured across `src/`, nothing calls `loadMoves` and nothing builds a
 * `QueuedMove`, which is WO-1019 and is explicitly not this order's to build.
 * What this order owes is that when WO-1019 wires that route, arming the check
 * is one call at the call site and NOTHING here changes. Meanwhile the
 * geometry door is not dead code: the simulator declares `geometryQueue: true`
 * and `executingMoveId: true`, so a run through this door exercises the real
 * comparison against a real backend rather than a stub.
 *
 * AND UNTIL THAT ROUTE EXISTS, A GEOMETRY BACKEND GETS A REFUSAL THAT NAMES
 * WHY. Loading a program on a controller that takes no text used to arm
 * nothing, and "nothing armed" and "nothing wrong" look identical from the
 * outside - which is this project's signature defect wearing the check's own
 * uniform. It now says, in the operator's console, that the product cannot
 * send this program to this machine at all and that WO-1019 owes it.
 *
 * `frame` is carried rather than assumed: a program is written in WORK
 * coordinates, so it is compared against `status.workPos`, which takes the
 * work offset off both sides at once - no offset table is read here and no
 * G54 lookup can go stale between load and run.
 *
 * The `program` door derives its move list at the END of the run rather than
 * at load, and only because of the start point: a program's first blocks
 * routinely constrain one axis (`G0 Z5`), so the unconstrained axes carry from
 * wherever the machine already was, and the honest seed is the machine's own
 * position when the job started rather than the origin a drawing convention
 * assumes.
 */
type PathFidelityArming =
  | { kind: 'program'; frame: 'work'; text: string; rapidFeedMmMin: number }
  /** A job handed over as GEOMETRY - the `loadMoves` route. No derivation is
   *  needed and none is done: these ARE the commanded moves, with the ids the
   *  controller will report back in `status.executingMoveId`. */
  | {
      kind: 'geometry'
      frame: 'work' | 'machine'
      moves: readonly QueuedMove[]
      /** Modal seed for a sparse text-program queue. The queue keeps omitted
       * axes off the wire, while preview/fit still needs the endpoint those
       * omissions hold at execution time. */
      startPosition?: MachineVec3
      /** Scoring can be refused without retiring the queue's execution ids.
       * Geometry progress and multipart completion still require these ids. */
      refusal?: string
    }
  /** A load the check knows it cannot score, IN ITS OWN WORDS. Silence would
   *  be indistinguishable from "nobody wired this up", which is the finding
   *  this arming exists to close. */
  | { kind: 'refused'; frame: 'machine'; refusal: string }

let pathFidelityArmed: PathFidelityArming | null = null
let pathFidelitySamples: PathFidelitySample[] | null = null
let pathFidelityAnalysis: PathFidelityStreamingAnalysis | null = null
let pathFidelityRunRefusal: string | null = null
let pathFidelitySampleCount = 0
let pathFidelityFrameChanges: PathFidelityFrameChange[] = []
let pathFidelityTruncated = false
let lastPathFidelityReport: PathFidelityReport | null = null

/**
 * WO-2033: A TOOL CHANGE IS NOT PART OF THE COMMANDED PATH, AND NEITHER IS THE
 * WAY BACK FROM IT.
 *
 * Between two parts of a program the tool-change hold owns the machine: the
 * guided park, the setter trip, the measure and the rise are this software's
 * own moves, and a manual hold's jogs are the operator's. Scoring them printed
 * "THE MACHINE LEFT THE COMMANDED PATH - up to 504.70 mm off" at the end of
 * every multi-tool program. So is the move back: the resumed program's first
 * moves leave any axis they do not name where the change left it (WO-1791),
 * while the commanded path models them from where the previous part ended. The
 * WO-2025 audit reproduced a false RED on exactly that, 72.64 mm over 38 frames
 * of a slow (F600) return.
 *
 * WHERE SCORING RESUMES IS DECIDED BY THE PROGRAM, NEVER BY THE MACHINE. From
 * the resumed part's first move, the first move whose START the program itself
 * has placed - it has named X, Y and Z again since the change - is where the
 * commanded path is once more exactly what the controller was told to fly.
 * Every frame from that move on is scored as before. A departure cannot extend
 * the exclusion (a "wait until it looks right again" rule would let a machine
 * that never rejoins hide the rest of the part), and the frames excluded are
 * counted and said in the report's limits.
 *
 * The frame's executing id says when that move is running. An id shown while
 * the hold owned the machine can still be on the board after it (UCCNC keeps
 * its last id until new motion, and the change's own staged moves are numbered
 * from 1 like any program), so such an id resumes nothing until the controller
 * has reported a different one.
 */
interface PathFidelityExcursion {
  /** Armed-move index by staged move id. */
  indexById: Map<number, number>
  /** Armed index of the first move the resumed program places by itself; null
   *  when nothing after the change does. */
  rejoinIndex: number | null
  /** Executing ids reported while the hold owned the machine. */
  heldIds: Set<number | null>
  /** A frame after the hold has reported an id the hold never showed. */
  fresh: boolean
}
let pathFidelityExcursion: PathFidelityExcursion | null = null
let pathFidelityExcursionFrames = 0

/** The armed index of the first move, at or after `first`, whose start the
 * program has placed on every axis by its own words - null when none does. A
 * G53 line does not count: its work endpoint is baked against the offset the
 * load saw, which a measured tool length has since changed. */
function pathFidelityRejoinIndex(moves: readonly QueuedMove[], first: number): number | null {
  const placed = { x: false, y: false, z: false }
  for (let index = first; index < moves.length; index++) {
    const move = moves[index]
    if (move.kind === 'arc') {
      placed.x = placed.y = placed.z = true
    } else if (move.kind === 'line' && (move as { machineAbsolute?: true }).machineAbsolute !== true) {
      for (const axis of ['x', 'y', 'z'] as const) if (move.to[axis] !== undefined) placed[axis] = true
    }
    if (placed.x && placed.y && placed.z) return index + 1 < moves.length ? index + 1 : null
  }
  return null
}

/** The tool-change hold at the boundary into part `incomingPartIndex` has just
 * taken the machine. Nothing moves before this call. */
function openPathFidelityExcursion(run: ProgramPartsRun, incomingPartIndex: number): void {
  const armed = pathFidelityArmed
  if (pathFidelitySamples === null || armed?.kind !== 'geometry') return
  const indexById = new Map<number, number>()
  armed.moves.forEach((move, index) => indexById.set(move.id, index))
  const firstId = run.parts[incomingPartIndex]?.steps.find(isStagedMove)?.id
  const first = firstId === undefined ? undefined : indexById.get(firstId)
  pathFidelityExcursion = {
    indexById,
    rejoinIndex: first === undefined ? null : pathFidelityRejoinIndex(armed.moves, first),
    heldIds: new Set(),
    fresh: false,
  }
}

/** True when this frame belongs to a tool change or the return from it. */
function pathFidelityExcursionOwns(status: MachineStatus): boolean {
  const excursion = pathFidelityExcursion
  if (excursion === null) return false
  const id = status.executingMoveId ?? null
  if (pendingToolChange !== null || programClampPause !== null) {
    excursion.heldIds.add(id)
    return true
  }
  if (id !== null && !excursion.heldIds.has(id)) excursion.fresh = true
  const index = id === null ? undefined : excursion.indexById.get(id)
  if (!excursion.fresh || excursion.rejoinIndex === null || index === undefined
    || index < excursion.rejoinIndex) return true
  pathFidelityExcursion = null
  return false
}

/** The report's own words for the frames a tool change took out of it. */
function pathFidelityExcursionLimit(frames: number, rejoined: boolean): string {
  return `${frames} status frame(s) around the tool change were not scored: the park, the setter, `
    + 'the measure and the rise are this software\'s own moves, and the move back into the program '
    + 'starts from wherever they left the machine. '
    + (rejoined
      ? 'Scoring resumed at the first move the program places on X, Y and Z by itself.'
      : 'The run ended before the program had placed X, Y and Z by itself again, so nothing after '
        + 'the change was scored.')
}

/**
 * The controller's configured path tolerance, mm - UCCNC's `Linearerror`.
 *
 * NULL until something reads it back off the machine, and that is the honest
 * default: with `Constantvelocitymode=True` the controller cuts corners on
 * purpose, so a guessed threshold near the machine's own designed error fires
 * on every corner of every program. No tolerance means the verdict is UNKNOWN,
 * never a guess.
 */
let pathToleranceMm: number | null = null

/** A job cannot record forever. ~30 minutes at a 32 ms poll. */
const PATH_FIDELITY_SAMPLE_CAP = 60_000

/**
 * ARM THE CHECK FROM THE PROGRAM THE PRODUCT JUST LOADED.
 *
 * Called by `loadMachineProgram` on every load that armed something, which is
 * what makes this a PRODUCT assertion rather than a harness: a person opening
 * a file and pressing Cycle Start gets the check, with no test and no
 * instrument involved. The text is kept rather than the derived moves - see
 * `PathFidelityArming` for why the derivation waits for the run's own start
 * position.
 */
function armPathFidelityFromProgram(text: string): void {
  pathFidelityArmed = {
    kind: 'program',
    frame: 'work',
    text,
    // A G0 block carries no F word. This only ever sizes the attribution
    // window, never the threshold.
    rapidFeedMmMin: controlMachine(useCamStore.getState()).rapidRate ?? 3000,
  }
}

/**
 * ARM THE CHECK FROM A JOB HANDED OVER AS GEOMETRY - the `loadMoves` route.
 *
 * THIS IS THE DOOR THE AXBB-E WILL COME THROUGH, and it is the half of this
 * order the audit found missing. That controller has no G-code interpreter, so
 * `loadMachineProgram` refuses it before any text arming is reached; its only
 * program route is `loadMoves`, and a job sent that way arrives here instead.
 *
 * Call it beside the `loadMoves` call, with the same array: one line at the
 * call site and the whole check comes with it. Nothing in this module needs to
 * change when WO-1019 wires that route, which is the point of the door
 * existing before the route does.
 *
 * NO DERIVATION HAPPENS HERE, and that is the difference between the two
 * doors. The text door has to interpret G-code and can refuse a program it
 * cannot model; these moves ARE the commanded path, already in LienCAM's own
 * terms and already carrying the ids the controller reports back in
 * `status.executingMoveId`, so the comparison is exact by construction.
 *
 * `frame` IS THE CALLER'S TO STATE AND IS NOT GUESSED. Whoever built the
 * queue knows whether it is in work or machine coordinates; this module
 * cannot know, and reading it wrong scores the entire work offset as a
 * deviation. There is no default for the same reason.
 *
 * The start point is taken from the run's own first status frame, exactly as
 * the text door does - one mechanism, and it stays right when a job starts
 * from somewhere other than where the last one ended.
 */
export function armPathFidelityFromMoves(
  moves: readonly QueuedMove[],
  frame: 'work' | 'machine',
  startPosition?: MachineVec3,
): void {
  pathFidelityArmed = {
    kind: 'geometry',
    frame,
    moves,
    ...(startPosition === undefined ? {} : { startPosition: { ...startPosition } }),
  }
  // THE SAME RE-READ THE TEXT DOOR DOES, AND FOR THE SAME REASON: the
  // threshold comes off this project's machine and the project can change
  // between two loads. Leaving it out would not fail loudly - it would leave
  // every geometry run reading UNKNOWN for want of a tolerance nobody
  // remembered to fetch, which is a trap laid for WO-1019 rather than a door
  // handed to it.
  refreshPathToleranceFromMachine()
}

/**
 * The path currently staged through the geometry route, expressed in the
 * viewport's native move vocabulary without parsing or re-deriving G-code.
 * These endpoints, arc centres, ids and rapid/feed roles come from the exact
 * queue handed to the controller. `moveLines` intentionally carries move ids:
 * geometry progress publishes the executing id as its cursor, so the marker
 * highlight and the drawn segment describe the same staged move.
 */
export function stagedGeometryProgramPath(): {
  moves: ToolpathMove[]
  moveLines: number[]
  /** WO-1630: per-axis MACHINE-coordinate range of any one-shot G53 target
   *  among the staged moves. `step.to` (above) is this frame's own WORK-
   *  coordinate bookkeeping value for a machineAbsolute line - baked against
   *  whatever work offset was active when the line was built - and a later
   *  G54..G59 edit must never move a G53 target's verdict. The envelope fit
   *  check (`fitProgramToEnvelope`) UNIONS this with `workBounds` below for
   *  exactly the axes a G53 line addressed, rather than reading `moves`. */
  machineAxisRanges: Partial<Record<'x' | 'y' | 'z', { min: number; max: number }>>
  /** WO-1630 audit follow-up: the WORK-coordinate bounds of the staged moves,
   *  EXCLUDING every machineAbsolute (G53) line's point. `moves` above keeps
   *  those points (path fidelity - the drawn path must still show where the
   *  tool actually went); but that point is `step.to`, the WORK-coordinate
   *  value baked in against whatever offset was active when the line was
   *  built, not a real work-frame move. Folding it into the fit check's work
   *  bounds re-shifts a stale bake by whatever offset is active NOW - exactly
   *  the false "Z: program 171.4..171.4" arithmetic from the finding
   *  (128 baked against G54 Z 66.57 -> 61.43, then re-shifted by the edited
   *  110 -> 171.43). null when no step yields a work-coordinate point.
   *
   *  WO-2219: by the WO-1639 rule `buildPreviewModel` uses - an axis joins
   *  these bounds only once a staged work step has itself commanded it. A
   *  value held from the arming start position (a first `G0 Z20` leaves X and
   *  Y to the controller) is where the tool happened to be, read in whatever
   *  frame was active at load, not a place this program sends it: judged as a
   *  point of the program's own offset it raised a false PARTLY OUTSIDE. An
   *  axis no work step ever commands keeps its held value, as before. */
  workBounds: Bounds3 | null
  /** WO-2219: the XY work points behind `workBounds` (the same rule: only
   *  once the program has commanded X and Y), so a fit in a rotated offset
   *  turns the program's real points rather than its box. */
  workXYPoints: Array<{ x: number; y: number }>
  /** WO-2219: the staged XY arcs that start once X and Y are commanded, whole,
   *  so that fit measures a TURNED bulge exactly (an arc end is not its
   *  extent). */
  workArcs: WorkArcForFit[]
} | null {
  if (pathFidelityArmed?.kind !== 'geometry') return null
  const moves: ToolpathMove[] = []
  const moveLines: number[] = []
  const machineAxisRanges: Partial<Record<'x' | 'y' | 'z', { min: number; max: number }>> = {}
  const workPoints: Array<{
    x: number
    y: number
    z: number
    addressed: ReadonlyArray<'x' | 'y' | 'z'>
    arc?: WorkArcForFit
  }> = []
  let modalPosition: MachineVec3 | null = pathFidelityArmed.startPosition
    ? { ...pathFidelityArmed.startPosition }
    : null
  for (const step of pathFidelityArmed.moves) {
    if (step.kind === 'line') {
      const isMachineAbsolute = (step as { machineAbsolute?: true }).machineAbsolute === true
      const machineTarget = isMachineAbsolute
        ? (step as { machineTarget?: Partial<{ x: number; y: number; z: number }> }).machineTarget
        : undefined
      if (machineTarget) {
        for (const axis of ['x', 'y', 'z'] as const) {
          const value = machineTarget[axis]
          if (value === undefined) continue
          const range = machineAxisRanges[axis]
          machineAxisRanges[axis] = range
            ? { min: Math.min(range.min, value), max: Math.max(range.max, value) }
            : { min: value, max: value }
        }
      }

      // WO-1791 keeps a line's omitted axes off the wire so the controller
      // holds its execution-time position. Reconstruct that same modal result
      // only for geometry consumers: never write the held values back into
      // `step.to`, and read an explicit G53 target above even when the display
      // endpoint cannot yet be completed.
      const x = step.to.x ?? modalPosition?.x
      const y = step.to.y ?? modalPosition?.y
      const z = step.to.z ?? modalPosition?.z
      if (x === undefined || y === undefined || z === undefined) continue
      modalPosition = { x, y, z }
      moves.push({
        type: step.rapid ? 'rapid' : 'feed',
        role: step.rapid ? 'rapid' : 'cut',
        x,
        y,
        z,
        ...(step.rapid ? {} : { feed: step.feedMmMin }),
      })
      moveLines.push(step.id)
      if (!isMachineAbsolute) {
        const addressed = (['x', 'y', 'z'] as const).filter((axis) => step.to[axis] !== undefined)
        workPoints.push({ x, y, z, addressed })
      }
    } else if (step.kind === 'arc') {
      const arcFrom = modalPosition
      modalPosition = { x: step.to.x, y: step.to.y, z: step.to.z }
      moves.push({
        type: step.clockwise ? 'arc_cw' : 'arc_ccw',
        role: 'cut',
        x: step.to.x,
        y: step.to.y,
        z: step.to.z,
        cx: step.centre.x,
        cy: step.centre.y,
        feed: step.feedMmMin,
      })
      moveLines.push(step.id)
      // An arc is never a machineAbsolute (G53) step - see reader.ts, which
      // refuses G53 with anything but an active G0/G1 motion mode.
      workPoints.push({
        x: step.to.x,
        y: step.to.y,
        z: step.to.z,
        addressed: ['x', 'y', 'z'],
        ...(arcFrom && step.plane === 'xy'
          ? { arc: { from: { x: arcFrom.x, y: arcFrom.y }, to: { x: step.to.x, y: step.to.y }, centre: { x: step.centre.x, y: step.centre.y }, clockwise: step.clockwise } }
          : {}),
      })
    }
  }
  const everAddressed = new Set(workPoints.flatMap((point) => point.addressed))
  const addressedSoFar = new Set<'x' | 'y' | 'z'>()
  const axisRanges: Partial<Record<'x' | 'y' | 'z', { min: number; max: number }>> = {}
  const workXYPoints: Array<{ x: number; y: number }> = []
  const workArcs: WorkArcForFit[] = []
  for (const point of workPoints) {
    // An arc that starts from a held (not yet commanded) X or Y is judged by
    // its end alone, like any other point there.
    if (point.arc && (!everAddressed.has('x') || addressedSoFar.has('x')) && (!everAddressed.has('y') || addressedSoFar.has('y'))) {
      workArcs.push(point.arc)
    }
    for (const axis of point.addressed) addressedSoFar.add(axis)
    const real = (axis: 'x' | 'y' | 'z') => !everAddressed.has(axis) || addressedSoFar.has(axis)
    for (const axis of ['x', 'y', 'z'] as const) {
      if (!real(axis)) continue
      const range = axisRanges[axis]
      axisRanges[axis] = range
        ? { min: Math.min(range.min, point[axis]), max: Math.max(range.max, point[axis]) }
        : { min: point[axis], max: point[axis] }
    }
    if (real('x') && real('y')) workXYPoints.push({ x: point.x, y: point.y })
  }
  const workBounds: Bounds3 | null = axisRanges.x && axisRanges.y && axisRanges.z
    ? {
        min: { x: axisRanges.x.min, y: axisRanges.y.min, z: axisRanges.z.min },
        max: { x: axisRanges.x.max, y: axisRanges.y.max, z: axisRanges.z.max },
      }
    : null
  // WO-1668: the FIT subject is withdrawn once the staged program has run its
  // course. The envelope fit exists to warn about a program that can still be
  // started; a completed or failed staged program cannot be (the geometry door
  // has no re-arm control), yet on 2026-09-17 an offset push after the crashed
  // one-move `G28 Z18` MDI re-judged that finished move against the new G54 Z
  // and printed OUTSIDE for a program that was never going to run again. The
  // DRAWN path is untouched - `moves`/`moveLines` still show where the tool
  // went; only the fit inputs (`workBounds`/`machineAxisRanges`) go empty, so
  // ProgramPreview's recompute on the offset change finds no subject and
  // publishes nothing. A stopped program lands in 'empty', NOT here: the
  // re-arm offer keeps it a start candidate, and its fit stays live.
  const jobPhase = store().job.phase
  const finished = jobPhase === 'complete' || jobPhase === 'failed'
  return {
    moves,
    moveLines,
    machineAxisRanges: finished ? {} : machineAxisRanges,
    workBounds: finished ? null : workBounds,
    workXYPoints: finished ? [] : workXYPoints,
    workArcs: finished ? [] : workArcs,
  }
}

/** Arm a REFUSAL: this run cannot be scored, and here is why in one sentence. */
function refusePathFidelity(refusal: string): void {
  pathFidelityArmed = { kind: 'refused', frame: 'machine', refusal }
}

const RUN_FROM_LINE_NOT_CHECKED =
  'this run was started part way through the program, so what the machine was given is a '
  + 'prelude plus a slice rather than the program that was loaded, and the path check has '
  + 'no commanded path for it.'

/** Forget any armed queue - a new program, or a backend swap. */
export function clearPathFidelity(): void {
  pathFidelityArmed = null
  pathFidelityAnalysis?.dispose()
  pathFidelityAnalysis = null
  pathFidelityRunRefusal = null
  pathFidelitySamples = null
  pathFidelitySampleCount = 0
  pathFidelityFrameChanges = []
  pathFidelityTruncated = false
  pathFidelityExcursion = null
  pathFidelityExcursionFrames = 0
}

/** The machine's configured path tolerance, mm; null clears it back to unknown. */
export function setPathToleranceMm(mm: number | null): void {
  pathToleranceMm = mm !== null && Number.isFinite(mm) && mm > 0 ? mm : null
}

/**
 * THE CONFIGURED TOLERANCE, READ OFF THE MACHINE THIS PROJECT DESCRIBES.
 *
 * Requirement 2 says the threshold comes from the machine's own tolerance and
 * that an unknown tolerance is an UNKNOWN verdict rather than a guessed
 * constant. The value exists in the product already: importing a UCCNC `.pro`
 * reads `[Generalsettings] Linearerror` (0.03 on Operator's profile), so this
 * reads the machine's own number rather than inventing one.
 *
 * IT IS READ FROM TWO CONTAINERS, and that is one fact asked of both places it
 * can live rather than two facts. WO-947 filed every key this software could
 * not SEND into `MachineConfig.unsentSettings` as text, and this was one of
 * them. WO-1039 moved every key this software can MODEL onto the definition,
 * typed - `Linearerror` among them - and narrowed the text container to the
 * keys no model can take. Asking only the text container therefore returns
 * null for every real machine and silently downgrades every path-fidelity
 * verdict to UNKNOWN; asking only the typed one loses a machine whose profile
 * this software could not model. The typed answer is preferred because it is
 * the one an edit on the definition page writes to.
 *
 * Both readers are keyed by the CONTROLLER'S vocabulary, so a machine of
 * another kind simply has no such key and the verdict stays UNKNOWN. That is
 * the honest answer, not a fallback: GRBL has no linear-error setting, and a
 * number borrowed from a different controller would be a made-up machine fact.
 * WO-2277: when no configured value exists, the connected native simulator
 * states its own numerical path tolerance. The simulator reference is cleared
 * at disconnect and on every hardware route; hardware never gets this value.
 */
const UCCNC_LINEAR_ERROR_KEY = 'Generalsettings.Linearerror'

export function refreshPathToleranceFromMachine(): void {
  const machine = controlMachine(useCamStore.getState())
  const typed = machine
    ? controllerSettingNumber(
      machine.controllerDefinition?.settings, machine.controller, UCCNC_LINEAR_ERROR_KEY,
    )
    : null
  const raw = machine && typed === null
    ? unsentSettingValue(machine.unsentSettings, machine.controller, UCCNC_LINEAR_ERROR_KEY)
    : null
  const value = typed ?? (raw === null ? Number.NaN : Number(raw))
  setPathToleranceMm(Number.isFinite(value) ? value : simulatedController?.pathToleranceMm ?? null)
}

export function pathToleranceMmValue(): number | null {
  return pathToleranceMm
}

/** The last job's path report, or null if no job has produced one. */
export function pathFidelityReport(): PathFidelityReport | null {
  return lastPathFidelityReport
}

function beginPathFidelityRun(): void {
  pathFidelityAnalysis?.dispose()
  pathFidelityAnalysis = null
  pathFidelityRunRefusal = null
  pathFidelitySamples = []
  pathFidelitySampleCount = 0
  pathFidelityFrameChanges = []
  pathFidelityTruncated = false
  pathFidelityExcursion = null
  pathFidelityExcursionFrames = 0
  // WHERE THE MACHINE IS THE INSTANT THE JOB STARTS, as its own first sample.
  // The `program` door needs a start point for the first block (see
  // `CommandedPathOptions.startPos`), and the first POLLED frame arrives up to
  // a poll interval late, by which time the machine has already left it. This
  // is the same `MachineStatus` a poll would deliver, read one call earlier.
  const start = controller?.status()
  if (start !== undefined) recordPathFidelitySample(start)
}

function recordPathFidelitySample(status: MachineStatus): void {
  if (pathFidelitySamples === null) return
  if (pathFidelityExcursionOwns(status)) {
    pathFidelityExcursionFrames++
    return
  }
  if (pathFidelitySampleCount >= PATH_FIDELITY_SAMPLE_CAP) {
    pathFidelityTruncated = true
    return
  }
  const sample: PathFidelitySample = {
    atMs: Date.now(),
    // BOTH POSITIONS FROM ONE CONTROLLER FRAME. Their difference is the active
    // work offset the controller actually held for this sample. The path check
    // never substitutes the project's stored G54..G59 value here.
    machinePos: status.machinePos,
    workPos: status.workPos,
    executingMoveId: status.executingMoveId,
  }
  // WO-2215: and the rotation that work position was read in. Under it machine
  // less work is not the offset; the check needs it only to find the origin.
  const rotation = controller ? controllerWorkRotation(controller, status) : statusWorkRotation(status)
  if (rotation !== 0) sample.workRotationDeg = rotation
  pathFidelitySampleCount++
  if (pathFidelityAnalysis === null) {
    pathFidelitySamples.push(sample)
    startPathFidelityAnalysis(false)
  } else {
    pathFidelityAnalysis.addSample(sample)
  }
}

/**
 * THE COMMANDED PATH FOR THE RUN THAT JUST ENDED, from whichever door armed it.
 *
 * The `program` door derives here rather than at load because the derivation
 * needs the machine's position when the first block ran, and the honest source
 * of that is the run's own first recorded frame - not the origin, and not a
 * position read at some other moment. Every refusal is carried out in words:
 * an empty move list with no reason is the "cannot assess" nobody trusts.
 */
function resolveCommandedPath(
  armed: PathFidelityArming | null,
  samples: readonly PathFidelitySample[],
): CommandedPath {
  const nowhere: MachineVec3 = { x: 0, y: 0, z: 0 }
  if (armed === null) {
    return {
      moves: [],
      startPos: nowhere,
      unmodelledMoveIds: [],
      refusal: 'no program was armed for this run, so there is nothing to compare against.',
    }
  }
  if (armed.kind === 'refused' || (armed.kind === 'geometry' && armed.refusal !== undefined)) {
    return { moves: [], startPos: nowhere, unmodelledMoveIds: [], refusal: armed.refusal ?? null }
  }
  const firstPosition = (sample: PathFidelitySample): MachineVec3 | null =>
    armed.frame === 'work' ? (sample.workPos ?? null) : sample.machinePos
  const first = samples.map(firstPosition).find((position) => position !== null)
  if (first === undefined || first === null) {
    return {
      moves: [],
      startPos: nowhere,
      unmodelledMoveIds: [],
      refusal:
        'no status frame during this job carried a work position, so the program could not '
        + 'be placed against what the machine did.',
    }
  }
  if (armed.kind === 'geometry') {
    // NOTHING TO DERIVE. These are the commanded moves themselves, with the
    // controller's own ids on them; there is no text to interpret and so no
    // block this door can fail to model. `unmodelledMoveIds` is empty for that
    // reason and not as a shrug.
    return {
      moves: [...armed.moves],
      startPos: first,
      unmodelledMoveIds: [],
      refusal: null,
    }
  }
  return commandedPathFromProgram(armed.text, {
    rapidFeedMmMin: armed.rapidFeedMmMin,
    startPos: first,
  })
}

function pathFidelityPhysicalCeilingMmMin(): number | null {
  const machine = controlMachine(useCamStore.getState())
  const rates: number[] = []
  for (const axis of machine?.controllerDefinition?.axes ?? []) {
    if (axis.enabled && Number.isFinite(axis.maxVelocity) && axis.maxVelocity > 0) {
      rates.push(axis.maxVelocity)
    }
  }
  if (rates.length === 0 && Number.isFinite(machine?.rapidRate) && (machine?.rapidRate ?? 0) > 0) {
    rates.push(machine!.rapidRate!)
  }
  // Simultaneous axis travel can exceed every individual axis rate. The
  // Euclidean resultant is therefore the physical ceiling for a 3D sample.
  return rates.length === 0 ? null : Math.hypot(...rates)
}

/**
 * Start the worker as soon as the first usable position places the commanded
 * path. Before that, only the handful of positionless opening frames remain on
 * the renderer. At a terminal event `force` produces the same honest refusal
 * the old batch path did when no position ever arrived.
 */
function startPathFidelityAnalysis(force: boolean): void {
  const pending = pathFidelitySamples
  if (pending === null || pathFidelityAnalysis !== null) return
  const armed = pathFidelityArmed
  if (!force && (armed?.kind === 'program' || armed?.kind === 'geometry')) {
    const hasStartPosition = pending.some((sample) =>
      armed.frame === 'work' ? sample.workPos != null : sample.machinePos !== null)
    if (!hasStartPosition) return
  }

  const commanded = resolveCommandedPath(armed, pending)
  pathFidelityRunRefusal = commanded.refusal
  pathFidelityAnalysis = createPathFidelityStreamingAnalysis({
    moves: commanded.moves,
    startPos: commanded.startPos,
    unmodelledMoveIds: commanded.unmodelledMoveIds,
    ...(commanded.restartsAt ? { restartsAt: commanded.restartsAt } : {}),
    reportsExecutingMoveId: controller?.capabilities.executingMoveId === true,
    toleranceMm: pathToleranceMm,
    commandedFrame: armed?.frame ?? 'machine',
    // WO-1667: positions in the report name the work frame they are in.
    workFrame: store().activeWcs ?? null,
    // The simulator advances an interpolated arc on fake-timer ticks and is
    // not physical telemetry. Apply the impossible-speed instrument only to a
    // controller whose status frames came from hardware.
    maxPhysicalTravelMmMin: controller?.statusFramesAreSynthetic?.() === true
      ? null
      : pathFidelityPhysicalCeilingMmMin(),
  })
  for (const sample of pending) pathFidelityAnalysis.addSample(sample)
  pending.length = 0
}

function finishPathFidelityRun(): void {
  if (pathFidelitySamples === null) return
  startPathFidelityAnalysis(true)
  const analysis = pathFidelityAnalysis
  const refusal = pathFidelityRunRefusal
  const frameChanges = pathFidelityFrameChanges
  const truncated = pathFidelityTruncated
  const excursionLimit = pathFidelityExcursionFrames > 0
    ? pathFidelityExcursionLimit(pathFidelityExcursionFrames, pathFidelityExcursion === null)
    : null
  // WO-1660: captured HERE, beside the run it belongs to - `pathFidelityArmed`
  // can be replaced by a later load before the analysis answers.
  const brief = briefPathFidelityRun()
  pathFidelitySamples = null
  pathFidelityAnalysis = null
  pathFidelityRunRefusal = null
  pathFidelitySampleCount = 0
  pathFidelityFrameChanges = []
  pathFidelityTruncated = false
  pathFidelityExcursion = null
  pathFidelityExcursionFrames = 0
  if (analysis === null) return

  // The lifecycle callback ends here. The unchanged full analysis runs in the
  // worker, and reporting resumes only after its result comes back.
  void analysis.finish(frameChanges).catch((error) => pathFidelityCannotAssess(
    'the path analysis failed ('
      + (error instanceof Error ? error.message : String(error))
      + '), so this run was not measured.',
  )).then((scored) => {
    const analysed: PathFidelityReport = excursionLimit === null
      ? scored
      : { ...scored, limits: [...scored.limits, excursionLimit] }
    const report: PathFidelityReport =
      refusal === null || analysed.verdict !== 'unknown'
        ? analysed
        : {
            ...analysed,
            reason: refusal,
            headline: 'Path check: CANNOT ASSESS - ' + refusal,
          }
    // A TRUNCATED RECORDING MAY NOT READ AS CLEAN (truncatedPathFidelityReport).
    reportPathFidelity(
      truncated ? truncatedPathFidelityReport(report, PATH_FIDELITY_SAMPLE_CAP) : report,
      brief,
    )
  })
}

/**
 * WO-1660: A BRIEF RUN IS ONE COMMANDED MOVE, AND ITS PATH CHECK EARNS ITS ROWS.
 *
 * A typed MDI line is ONE move. The path check exists to catch a SUSTAINED
 * departure on a real program; over one move its standing threshold
 * documentation (the poll cadence, the invisible short gap, the id/position
 * skew) is pure noise, and on the board it printed a "Path check" row plus FIVE
 * "limit:" rows for a `G53 G0 Z128` that plainly went where it was told. Operator's
 * console rule: no notice, no banner, and every row must earn its place.
 *
 * So a run armed from a single commanded move prints AT MOST ONE row:
 *   - nothing, when the move flew as commanded and stayed inside travel;
 *   - one row naming the travel limit, when the move ended at a declared soft
 *     limit - the "limit actually approached" the operator is owed;
 *   - otherwise the report's own headline, when the check has something to say
 *     (a divergence or a cannot-assess).
 * The documentation limits are never printed for a brief run. A run with more
 * than one commanded move keeps the existing report unchanged - a long
 * program's clean verdict (WO-1629) is not this order's to remove.
 */
interface BriefPathFidelityRun {
  /** The axes this one move ends at a declared travel limit, in machine
   *  coordinates. Empty when it stays inside, or no limit is stated. */
  atTravelLimit: Array<{ axis: 'X' | 'Y' | 'Z'; value: number; min: number; max: number }>
}

/** The brief-run facts for the run just armed, or null when it is not a single
 *  commanded move. Called at finish time, before a later load can replace the
 *  armed queue. */
function briefPathFidelityRun(): BriefPathFidelityRun | null {
  const armed = pathFidelityArmed
  if (armed?.kind !== 'geometry') return null
  const motion = armed.moves.filter((move) => move.kind === 'line' || move.kind === 'arc')
  if (motion.length !== 1) return null
  const move = motion[0]
  const envelope = currentResolvedMachineMotion().envelope
  const offsets = currentWorkOffsets().byWcs
  const wcs = store().activeWcs as WcsId | null
  const offset = wcs === null ? undefined : offsets[wcs]
  const atTravelLimit: BriefPathFidelityRun['atTravelLimit'] = []
  const machineTarget = move.kind === 'line'
    ? (move as { machineTarget?: Partial<MachineVec3> }).machineTarget
    : undefined
  // WO-2215: a rotated system reaches machine XY through O + Rot(R)(work) -
  // both work axes are needed for either machine axis.
  const degrees = wcs === null ? 0 : controllerRotationDeg(wcs)
  const turned = degrees === 0 || move.to.x === undefined || move.to.y === undefined
    ? null
    : rotateXY(degrees, move.to.x, move.to.y)
  for (const key of ['x', 'y', 'z'] as const) {
    const env = envelope[key]
    if (!env) continue
    // A G53/G28 line carries its true machine target; an ordinary move is in
    // the commanded (work) frame and reaches machine coordinates only through
    // the active offset. An axis with neither is not compared.
    const value = machineTarget
      ? machineTarget[key]
      : degrees !== 0 && key !== 'z'
        ? turned !== null && offset !== undefined ? turned[key] + (offset[key] ?? 0) : undefined
        : move.to[key] !== undefined && offset !== undefined
          ? move.to[key]! + (offset[key] ?? 0)
          : undefined
    if (value === undefined || !Number.isFinite(value)) continue
    if (Math.abs(value - env.min) <= ENVELOPE_FIT_TOLERANCE_MM
      || Math.abs(value - env.max) <= ENVELOPE_FIT_TOLERANCE_MM) {
      atTravelLimit.push({ axis: key.toUpperCase() as 'X' | 'Y' | 'Z', value, min: env.min, max: env.max })
    }
  }
  return { atTravelLimit }
}

/** The one sentence a brief run owes when it ends at a travel limit. Plain
 *  millimetres, the axis, and the range it belongs to - no "warning". */
function describeBriefTravelLimit(limit: BriefPathFidelityRun['atTravelLimit'][number]): string {
  const atMax = Math.abs(limit.value - limit.max) <= Math.abs(limit.value - limit.min)
  const edge = atMax ? limit.max : limit.min
  const fmt = machineLengthText
  const key = limit.axis.toLowerCase() as PositionAxisKey
  // Travel limits are machine-frame facts; the one formatter names the frame.
  return `The move ends at the ${limit.axis} travel limit, `
    + `${formatPosition({ machine: { [key]: edge }, format: fmt })} (machine ${limit.axis} `
    + `${fmt(limit.min)}..${fmt(limit.max)}).`
}

/**
 * One place a path report reaches the operator, whoever computed it - the
 * session's own monitor or a backend raising `onPathFidelity`.
 *
 * It goes to the CONSOLE, which is where this machine's messages go (Operator's
 * standing rule: reuse an existing surface, never a new element, and never one
 * that shifts the layout when it appears). A divergence is an error; anything
 * else is a note, because a check that shouts about what it could not measure
 * gets turned off.
 *
 * WO-1660: a `brief` run (one commanded move) prints at most one row - see
 * `BriefPathFidelityRun`.
 */
function reportPathFidelity(
  report: PathFidelityReport,
  brief: BriefPathFidelityRun | null = null,
): void {
  lastPathFidelityReport = report
  // A MEASURED DEPARTURE IS AN ERROR WHATEVER THE VERDICT WORD IS. A run that
  // ALSO carried out-of-range move ids reads UNKNOWN - requirement 4 is
  // unconditional and outranks every other verdict - but the departure it
  // measured on the frames that DID name a queued move is still in `spans`, and
  // downgrading that to a quiet note would suppress a real fault through the
  // console instead of through the verdict. Anything with no measured span is a
  // note, because a check that shouts about what it could not measure gets
  // turned off.
  const lines = pathFidelityConsoleLines(report).map(line => ({
    ...line, text: fmtMachineDiagnostic(line.text, machineDisplayUnits()),
  }))
  if (brief !== null) {
    const limit = brief.atTravelLimit[0]
    if (report.verdict === 'clean' && limit !== undefined) {
      store().pushConsole('rx', `${fmtMachineDiagnostic(report.headline, machineDisplayUnits())} ${describeBriefTravelLimit(limit)}`, 'info')
    } else if (report.verdict !== 'clean' && lines[0] !== undefined) {
      store().pushConsole('rx', lines[0].text, lines[0].severity)
    }
    // A clean brief run with no limit reached prints NOTHING - the row would
    // not earn its place.
  } else if (lines[0] !== undefined) {
    // WO-2008: ONE summary line (COHESION-STANDARD 13.2). The per-span rows and
    // the standing "limit:" rows are detail; they stay in the report
    // (`pathFidelityReport()`), and the evidence JSON is saved only on request
    // (`savePathCheckEvidence`) - never auto-downloaded.
    store().pushConsole('rx', lines[0].text, lines[0].severity)
  }
}

/** Save the last path check's evidence JSON - on request only (WO-2008). */
export function savePathCheckEvidence(): { ok: boolean; filename: string | null } {
  const report = lastPathFidelityReport
  if (report?.evidence === undefined) return { ok: false, filename: null }
  if (typeof document === 'undefined' || typeof URL.createObjectURL !== 'function') {
    return { ok: false, filename: null }
  }
  const stamp = new Date().toISOString().replace(/[:.]/g, '-')
  const filename = `liencam-path-check-${stamp}.json`
  const blob = new Blob([pathFidelityEvidenceJson(report)], { type: 'application/json' })
  const href = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = href
  anchor.download = filename
  anchor.click()
  URL.revokeObjectURL(href)
  store().pushConsole('rx', `Path check evidence saved as ${filename}.`, 'info')
  return { ok: true, filename }
}

export function pathFidelityEvidenceJson(report: PathFidelityReport): string {
  const { evidence, ...summary } = report
  return JSON.stringify({
    format: 'liencam-path-fidelity-evidence',
    version: 1,
    capturedAt: new Date().toISOString(),
    report: summary,
    samples: evidence ?? [],
  }, null, 2)
}

/** Make GRBL the live backend. WO-433: the simulator no longer speaks GRBL -
 *  this is the 'serial' path (and the default/lazy backend before any
 *  connect() at all, per getMachineController() below) only now. */
function installGrblBackend(replaceDisconnected = false): MachineController {
  if (!replaceDisconnected && supportsGrblSettings(controller)) return controller
  const scope = createBackendEventScope()
  const next = new GrblController(buildGrblEvents(scope))
  installBackend(next, scope)
  return next
}

/**
 * WO-1329: A RUN-THROUGH PROGRAM SAYS WHOSE JOB THE ZEROS ARE, AGAIN, IF THE
 * OPERATOR LOADED IT LONG BEFORE PRESSING START.
 *
 * The line is printed once at load. A load followed straight away by CYCLE
 * START does not need it twice - the operator is looking at it. A program
 * loaded and left while the console filled with jogs, probes and offset edits
 * does: the one line saying this run will not stop between setups has scrolled
 * away by the time the button is pressed.
 *
 * DECIDE AND LOG: "long before" is a minute. Short enough that the reminder is
 * there for any real setup gap, long enough that a normal load-then-start is
 * not told the same thing twice in two seconds.
 */
const CONTINUATION_RESTATE_AFTER_MS = 60_000

function restateSetupContinuation(target: MachineController): void {
  const run = programPartsRun
  if (!run || run.controller !== target || run.started) return
  const notice = run.continuation
  if (notice === undefined) return
  if (sessionElapsedNowMs() - notice.saidAtMs < CONTINUATION_RESTATE_AFTER_MS) return
  notice.saidAtMs = sessionElapsedNowMs()
  store().pushConsole('rx', notice.line, 'info')
}

function installBackend(next: MachineController, scope: BackendEventScope): void {
  // WO-1275: a pending release belongs to the backend that armed it. A swap
  // leaves nothing to release into.
  cancelSpindleSpeedWait()
  controller = next
  scope.controller = next
  scope.phase = next.connectionPhase()
  beginBackendGeneration(scope)
  installLiveSpindleOverrideRouting(next)
  // WO-1349: homing is motion too. JogPanel calls these controller methods
  // directly, so enforce the session E-STOP latch here at the common backend
  // boundary. A clean idle status does not clear this latch; only the
  // operator's deliberate CLEAR does.
  const home = next.home.bind(next)
  next.home = () => {
    if (estopNeedsReset()) {
      store().pushConsole('tx', `Home All: refused - ${ESTOP_BLOCKS_MOTION}`, 'error')
      return false
    }
    return home()
  }
  if (next.homeAxes) {
    const homeAxes = next.homeAxes.bind(next)
    next.homeAxes = (axes) => {
      if (estopNeedsReset()) {
        store().pushConsole('tx', `Home ${axes.join(', ')}: refused - ${ESTOP_BLOCKS_MOTION}`, 'error')
        return false
      }
      const previous = scope.homeAnnouncement
      const announcement = { requested: [...axes], remaining: new Set(axes), sawHome: false }
      scope.homeAnnouncement = announcement
      const accepted = homeAxes(axes)
      if (!accepted && scope.homeAnnouncement === announcement) scope.homeAnnouncement = previous
      return accepted
    }
  }
  // Operator 2026-09-14 (WO-328 "across all locations"): while the E-STOP blinks,
  // jog is motion too. The jog buttons grey out, but a pendant or any other
  // caller reaches the controller directly, so refuse here as homing does.
  // jogHold and jogCancel stay open - they only keep or stop motion.
  let lastJogRefusalAtMs = 0
  const sayJogRefused = (what: string, reason: string = ESTOP_BLOCKS_MOTION) => {
    const now = sessionElapsedNowMs()
    if (now - lastJogRefusalAtMs < 1000) return
    lastJogRefusalAtMs = now
    store().pushConsole('tx', `${what}: refused - ${reason}`, 'error')
  }
  // WO-2022: the controller's own refusal (travel, alarm, homing) used to end
  // in silence - an enabled jog button moved nothing and said nothing. Every
  // caller (JogPanel step, burst fallback, pendant) reaches it through here.
  // WO-2237: in a pause every move below - the pendant's step jog included -
  // first turns the pause into a kept stop, then runs (`commandThroughKeptStop`).
  const refusePausedMove = (what: string): false => {
    store().pushConsole('tx', `${what}: refused - ${PAUSED_PROGRAM_JOG_LOCK}`, 'error')
    return false
  }
  const afterKeptStop = (what: string, run: () => Promise<boolean> | null): Promise<boolean> | null => {
    let answer!: (ok: boolean) => void
    const later = new Promise<boolean>((resolve) => { answer = resolve })
    const taken = commandThroughKeptStop(next, what, () => {
      const sent = run()
      if (sent === null) answer(false)
      else void sent.then(answer, () => answer(false))
    }, true, () => answer(false))
    return taken ? later : null
  }
  const jog = next.jog.bind(next)
  next.jog = (axis, deltaMm, feedMmMin) => {
    if (estopNeedsReset()) {
      sayJogRefused(`Jog ${axis}`)
      return false
    }
    if (commandThroughKeptStop(next, `Jog ${axis}`, () => { next.jog(axis, deltaMm, feedMmMin) }, true)) return true
    if (pausedProgramKeepsItsLock(next)) {
      sayJogRefused(`Jog ${axis}`, PAUSED_PROGRAM_JOG_LOCK)
      return false
    }
    if (jog(axis, deltaMm, feedMmMin)) return true
    sayJogRefused(`Jog ${axis}`, controllerJogRefusal(next, axis, deltaMm))
    return false
  }
  const jogCancel = next.jogCancel.bind(next)
  next.jogCancel = () => {
    dropCommandsWaitingForKeptStop(next, true)
    jogCancel()
  }
  if (next.jogStop) {
    const jogStop = next.jogStop.bind(next)
    next.jogStop = () => {
      dropCommandsWaitingForKeptStop(next, true)
      jogStop()
    }
  }
  if (next.jogStartContinuous) {
    const jogStartContinuous = next.jogStartContinuous.bind(next)
    next.jogStartContinuous = (...args: Parameters<NonNullable<MachineController['jogStartContinuous']>>) => {
      if (estopNeedsReset()) {
        sayJogRefused(`Jog ${String(args[0])}`)
        return Promise.resolve(false)
      }
      const later = afterKeptStop(`Jog ${String(args[0])}`, () => next.jogStartContinuous!(...args))
      if (later !== null) return later
      if (pausedProgramKeepsItsLock(next)) {
        sayJogRefused(`Jog ${String(args[0])}`, PAUSED_PROGRAM_JOG_LOCK)
        return Promise.resolve(false)
      }
      return jogStartContinuous(...args).then((ok) => {
        if (!ok) sayJogRefused(`Jog ${String(args[0])}`, controllerJogRefusal(next, args[0], null))
        return ok
      })
    }
  }
  // WO-1638: the same latch where programs start, resume and step, and where
  // the app-issued moves go out. Every button already checks it first; this is
  // the guarantee for any caller below the UI. Checked BEFORE anything else in
  // each wrapper, so a refused call releases no tool-change hold and starts no
  // spindle. Feed hold, stop, reset and E-STOP stay open - they only stop.
  const refuseUnderEstopLatch = (what: string): boolean => {
    if (!estopNeedsReset()) return false
    store().pushConsole('tx', `${what}: refused - ${ESTOP_BLOCKS_MOTION}`, 'error')
    return true
  }
  const jogToWorkXY = next.jogToWorkXY.bind(next)
  next.jogToWorkXY = (x, y, feedMmMin) => {
    if (refuseUnderEstopLatch('Move to work X Y')) return false
    if (commandThroughKeptStop(next, 'Move to work X Y', () => { next.jogToWorkXY(x, y, feedMmMin) }, true)) return true
    if (pausedProgramKeepsItsLock(next)) return refusePausedMove('Move to work X Y')
    return jogToWorkXY(x, y, feedMmMin)
  }
  const jogToMachineZ = next.jogToMachineZ.bind(next)
  next.jogToMachineZ = (z, feedMmMin) => {
    if (refuseUnderEstopLatch('Move to machine Z')) return false
    // Safe Z is this move.
    if (commandThroughKeptStop(next, 'Move to machine Z', () => { next.jogToMachineZ(z, feedMmMin) }, true)) return true
    if (pausedProgramKeepsItsLock(next)) return refusePausedMove('Move to machine Z')
    return jogToMachineZ(z, feedMmMin)
  }
  if (next.jogToWorkXYAwait) {
    const jogToWorkXYAwait = next.jogToWorkXYAwait.bind(next)
    next.jogToWorkXYAwait = (x, y, feedMmMin) => {
      if (refuseUnderEstopLatch('Move to work X Y')) return Promise.resolve(false)
      const later = afterKeptStop('Move to work X Y', () => next.jogToWorkXYAwait!(x, y, feedMmMin))
      if (later !== null) return later
      if (pausedProgramKeepsItsLock(next)) return Promise.resolve(refusePausedMove('Move to work X Y'))
      return jogToWorkXYAwait(x, y, feedMmMin)
    }
  }
  if (next.jogToMachineZAwait) {
    const jogToMachineZAwait = next.jogToMachineZAwait.bind(next)
    next.jogToMachineZAwait = (z, feedMmMin) => {
      if (refuseUnderEstopLatch('Move to machine Z')) return Promise.resolve(false)
      const later = afterKeptStop('Move to machine Z', () => next.jogToMachineZAwait!(z, feedMmMin))
      if (later !== null) return later
      if (pausedProgramKeepsItsLock(next)) return Promise.resolve(refusePausedMove('Move to machine Z'))
      return jogToMachineZAwait(z, feedMmMin)
    }
  }
  const startJob = next.startJob.bind(next)
  next.startJob = () => {
    if (refuseUnderEstopLatch('Cycle Start')) return false
    restateSetupContinuation(next)
    if (pathFidelityArmed) geometryStepMotionSeen.delete(pathFidelityArmed)
    return runWithGeometryProgramSpindle(next, () => {
      if (startJob()) return true
      // WO-2022: the controller's own refusal used to end in silence - the
      // rehearsal's Cycle Start sat 60 s at 0/N with no line saying why.
      store().pushConsole('tx', `Cycle Start: refused - ${controllerStartRefusal(next)}`, 'error')
      return false
    })
  }
  const pauseJob = next.pauseJob.bind(next)
  next.pauseJob = () => {
    cancelSpindleSpeedWait()
    pauseJob()
    stopGeometryProgramSpindle(next)
    reopenToolChangeHold(next)
  }
  // WO-1330 fix round: every release door asks the tool-change hold FIRST,
  // before `runWithGeometryProgramSpindle` commands the incoming spindle. No
  // confirmed Z zero: nothing is sent. Confirmed: jog and the Z cells close
  // here, and only then does the spindle start.
  const releaseThroughToolChange = (release: () => boolean): boolean => {
    // WO-1652: the boundary's macro (an M6 prelude too) is still running -
    // no door releases the program from under it.
    if (programBoundaryMacroBlocksCycleStart(next)) {
      store().pushConsole('tx', "Cycle Start: this hold's macro is still running - Stop it, or let it finish.", 'error')
      return false
    }
    if (programGuidedToolChangeBlocksCycleStart(next)) {
      store().pushConsole(
        'tx',
        'Cycle Start: the M6 tool change is waiting for the cutter to be fitted and Continue to run the fixed-pad probe.',
        'error',
      )
      return false
    }
    if (!releaseToolChangeHold(next)) return false
    // WO-2586: answering M6 cannot answer the M0 on that same source line.
    // Keep the controller's hold for a separate operator release.
    if (holdSameLineStopAfterM6(next)) return true
    const released = release()
    if (!released) reopenToolChangeHold(next)
    return released
  }
  const resumeJob = next.resumeJob.bind(next)
  next.resumeJob = () => {
    if (refuseUnderEstopLatch('Resume')) return false
    // WO-2259: a held tool-change park owns this press, whichever door it came by.
    if (guidedParkPausedByOperator(next)) return carryOnGuidedPark(next, cycleResume)
    if (programClampPauseBlocksCycleStart(next)) return continueClampPauseByCycleStart('continuous')
    return releaseThroughToolChange(() => runWithGeometryProgramSpindle(next, resumeJob))
  }
  const feedHold = next.feedHold.bind(next)
  next.feedHold = () => {
    // WO-1275: FIRST, before anything that touches the wire. Clearing one
    // local timer cannot fail, so a Feed Hold pressed during the up-to-speed
    // wait drops the armed motion and then holds exactly as it always did.
    cancelSpindleSpeedWait()
    if (!holdProgramPartsBetweenParts(next)) feedHold()
    stopGeometryProgramSpindle(next)
    reopenToolChangeHold(next)
  }
  const cycleResume = next.cycleResume.bind(next)
  next.cycleResume = () => {
    if (refuseUnderEstopLatch('Cycle Start')) return false
    // WO-2600: Main's CYCLE START also carries on this retained probe move.
    if (isProbeCyclePaused()) { resumeProbing(); return true }
    // WO-2239: the controller's own tool change, typed in a kept stop, is
    // answered - nothing of the program is released by this press.
    const waiting = keptStopControllerToolChange(next)
    if (waiting !== null) return answerKeptStopToolChange(next, waiting, cycleResume)
    // WO-2103: a probe routine held by Feed Hold owns this press. It releases
    // the hold and nothing else - no loaded program's spindle, coolant or part.
    if (probeCycleHeldByOperator(next)) return cycleResume()
    // WO-2259: so does a guided flow's park held by Feed Hold - the park
    // carries on and nothing of the program is released.
    if (guidedParkPausedByOperator(next)) return carryOnGuidedPark(next, cycleResume)
    // WO-2437 fix round: at a parked clamp pause CYCLE START is its Continue.
    if (programClampPauseBlocksCycleStart(next)) return continueClampPauseByCycleStart('continuous')
    // WO-1652: the boundary's macro is still running - CYCLE START continues
    // it at a hold() and never releases the program from under it.
    if (programBoundaryMacroBlocksCycleStart(next)) return continueHeldMacro()
    return releaseThroughToolChange(() => runWithGeometryProgramSpindle(
      next,
      () => resumeProgramPartsBetweenParts(next) || cycleResume(),
    ))
  }
  const stepJob = next.stepJob.bind(next)
  next.stepJob = () => {
    if (refuseUnderEstopLatch('Single block step')) return false
    // WO-1790: the first Single Block press is a program START and therefore
    // carries the same datum prerequisite as ordinary Cycle Start. Ask here,
    // before a reread, tool-change release or spindle command; later steps
    // remain valid because the same session datum is still present.
    const home = programHomingRefusal(next)
    if (home) {
      store().pushConsole('tx', `Single block step: refused - ${home}`, 'error')
      return false
    }
    // WO-2237: with Single Block on, the first step out of a kept stop is
    // the return's first block - never the re-armed program's top.
    const kept = startingKeptStopResume ? null : liveKeptStop(next)
    if (kept !== null && kept.resumed === null) return startFromKeptStop(next, kept, () => next.stepJob())
    restateSetupContinuation(next)
    if (programClampPauseBlocksCycleStart(next)) return continueClampPauseByCycleStart('single-block')
    if (programBoundaryMacroBlocksCycleStart(next)) return false
    const releaseStep = (): boolean => releaseThroughToolChange(() => runWithGeometryProgramSpindle(next, () => {
      const run = programPartsRun
      if (run?.controller === next && run.heldBetweenParts) return stepProgramPartsBetweenParts(next)
      if (pathFidelityArmed) geometryStepMotionSeen.delete(pathFidelityArmed)
      return stepJob()
    }))
    // The first Single Block press is a program START, just through the step
    // door. It must refresh a file staged before a home/jog exactly as ordinary
    // Cycle Start does; later steps are excluded by the active-job guard.
    const reread = rereadFileForExecutionChange(next, releaseStep)
    return reread ?? releaseStep()
  }
  recordWatchedMoves(next)
  const stopJob = next.stopJob.bind(next)
  next.stopJob = () => {
    scope.homeAnnouncement = undefined
    const staleRun = runReadsOverIdleController(next)
    const releaseHold = !sessionStopInProgress && stopEndsBoardHold(next)
    // WO-2071: a probe routine the Stop halts ends here, before the board is told.
    stopRunningProbeCycle()
    noteMotionStop('stop')
    noteOperatorStop(next)
    noteOperatorMotionStop(next)
    cancelSpindleSpeedWait()
    // WO-2237: the operator's Stop ends what waited for a kept stop, and a
    // return already under way - the Stop is a Stop, as in any program.
    if (!sessionStopInProgress) forgetKeptStopOnOperatorStop(next)
    endProgramClampPauseByOperatorStop(next)
    endProgramHoldByOperatorStop(next)
    stopJob()
    if (releaseHold) releaseBoardHoldAtRest(next)
    stopGeometryProgramSpindle(next)
    scheduleOutputPinRefresh()
    // WO-2234: a stopped MDI line over the file has ended.
    endMdiLineOverFile(next)
    if (staleRun) endStaleRunAtStopReset(next)
  }
  const reset = next.reset.bind(next)
  probeControllerResets.set(next, reset)
  if ('softReset' in next && typeof next.softReset === 'function') {
    const softReset = next.softReset.bind(next)
    next.softReset = () => {
      // resetToIdle's internal reset is a probe cancellation, not an operator
      // Stop/Reset. The public reset wrapper below still ends a paused cycle.
      if (probeControlledResets.has(next) && next.resetInProgress()) reset()
      else softReset()
    }
  }
  next.reset = () => {
    scope.homeAnnouncement = undefined
    const staleRun = runReadsOverIdleController(next)
    stopRunningProbeCycle()
    noteMotionStop('reset')
    noteOperatorMotionStop(next)
    cancelSpindleSpeedWait()
    if (!sessionStopInProgress) forgetKeptStopOnOperatorStop(next)
    endProgramClampPauseByOperatorStop(next)
    endProgramHoldByOperatorStop(next)
    stopResetRequestedForProgramParts = programPartsRun?.controller === next
    reset()
    stopGeometryProgramSpindle(next)
    scheduleOutputPinRefresh()
    // WO-2234: so does a reset one.
    endMdiLineOverFile(next)
    if (staleRun) endStaleRunAtStopReset(next)
    // WO-2599 supersedes the 09-13 ruling at explicit M0/M6 holds only:
    // Operator ruling 10-05 chose Reset ends the program, like UCCNC. Setup holds above
    // still retain the continuation authorized by that earlier ruling.
  }
  const emergencyStop = next.emergencyStop.bind(next)
  next.emergencyStop = () => {
    noteMotionStop('estop')
    cancelSpindleSpeedWait()
    forgetKeptStopOnOperatorStop(next)
    emergencyStop()
    stopGeometryProgramSpindle(next)
    scheduleOutputPinRefresh()
    // WO-2234: and the E-STOP's; the file waits for the reset and Idle.
    endMdiLineOverFile(next)
  }
  backendResetUnsubscribe?.()
  backendResetUnsubscribe = next.subscribeResetInProgress(() => {
    if (!acceptsBackendEvent(scope)) return
    for (const listener of resetInProgressListeners) listener()
    if (programPartsRun?.controller === next && next.resetInProgress()) {
      const reason = stopResetRequestedForProgramParts
        ? programPartsStopResetReason(next)
        : 'Program parts ended; the controller was not ready to load the next part.'
      stopResetRequestedForProgramParts = false
      endProgramParts(reason, 'stopped', null, 'info')
    }
  })
  for (const listener of resetInProgressListeners) listener()
}

/** WO-1681 safety round: EVERY STOP OF THE BOARD, told to whichever
 *  controller is current - Stop, Reset and E-STOP, from the transport bar or
 *  the session itself. Fired BEFORE the board is told, so a listener (a
 *  running user macro) has ended before the stopped board's Idle arrives and
 *  can read as a finished line. */
type MotionStopKind = 'stop' | 'reset' | 'estop'
const motionStopListeners = new Set<(kind: MotionStopKind) => void>()

function noteMotionStop(kind: MotionStopKind): void {
  for (const listener of [...motionStopListeners]) listener(kind)
}

export function subscribeMotionStop(listener: (kind: MotionStopKind) => void): () => void {
  motionStopListeners.add(listener)
  return () => motionStopListeners.delete(listener)
}

/** Reset-in-progress subscription that survives a backend swap: the SESSION
 *  keeps the listener list and re-attaches it to whichever controller is
 *  current, so a subscriber that mounted against the previous backend is not
 *  silently orphaned. */
const resetInProgressListeners = new Set<() => void>()
let backendResetUnsubscribe: (() => void) | null = null

export function subscribeControllerReset(listener: () => void): () => void {
  resetInProgressListeners.add(listener)
  return () => resetInProgressListeners.delete(listener)
}

export function controllerResetInProgress(): boolean {
  return controller?.resetInProgress() ?? false
}

/**
 * Leave the controller with NOTHING loaded (disarm). GRBL disarms by loading
 * an empty prepared stream; any other backend disarms by loading empty text,
 * which a controller without an interpreter refuses - and a refusal here
 * means the same thing: nothing is loaded.
 */
function loadNothing(ctrl: MachineController): void {
  // WO-423: `loadPreparedJob` is the contract's own optional member now, so
  // this asks the interface instead of reaching for a GRBL reference.
  if (ctrl.loadPreparedJob) ctrl.loadPreparedJob([])
  else ctrl.loadJob('')
  // WO-1008: nothing is loaded, so nothing is the commanded path. An armed
  // queue that outlived its program would score the next run against the
  // previous one - a divergence out of thin air.
  clearPathFidelity()
}

/** What the CONNECTED backend says it can do - null when nothing is connected.
 *  The UI asks this before offering a capability-gated control (ADR-0041
 *  rule 2: a false field is a statement about the controller). */
export function controllerCapabilities(): ControllerCapabilities | null {
  return controller && controller.connectionPhase() !== 'disconnected' ? controller.capabilities : null
}

type SetMachinePositionResult =
  | { ok: true }
  | { ok: false; reason: string }

/**
 * Establish a complete definition-enabled machine datum at the
 * operator-asserted physical position (WO-986/WO-1725). This is not a homing
 * bypass: a successful backend call gives every machine-coordinate gate the
 * same session truth a completed whole-machine home gives it.
 *
 * Every safety fact is read at commit time. The confirmation card may have
 * been open while a program started or the E-STOP latched, so render-time
 * disabled state is never authority.
 */
export function setMachinePosition(position: MachinePosition): SetMachinePositionResult {
  if (estopNeedsReset()) return { ok: false, reason: ESTOP_BLOCKS_MOTION }

  const ctrl = getMachineController()
  if (ctrl.connectionPhase() !== 'connected') {
    return { ok: false, reason: 'Connect to the machine before setting its position.' }
  }
  if (ctrl.hasActiveJob()) {
    return { ok: false, reason: 'A program is running - the machine position cannot be changed.' }
  }
  if (!ctrl.verifiedIdle()) {
    return { ok: false, reason: 'The machine is moving - wait for it to stop before setting its position.' }
  }
  const datumAxes = enabledControlAxes(activeMachineDefinition())
  const invalidAxes = datumAxes.filter((axis) => {
    const key = axis.toLowerCase() as Lowercase<ControlAxis>
    return !Number.isFinite(position[key])
  })
  if (invalidAxes.length > 0) {
    return {
      ok: false,
      reason: `Enter a finite number for ${describeAxisList(invalidAxes)}.`,
    }
  }
  if (!ctrl.setMachinePosition) {
    return {
      ok: false,
      reason: 'Setting the machine position is not wired on this controller backend yet.',
    }
  }
  const previousSettingMachinePosition = settingMachinePosition
  settingMachinePosition = true
  try {
    if (!ctrl.setMachinePosition(position)) {
      return { ok: false, reason: 'The controller refused to set the machine position.' }
    }
  } finally {
    settingMachinePosition = previousSettingMachinePosition
  }
  return { ok: true }
}

// ---- E-STOP reset interlock (WO-328, Operator's UCCNC-style model) ----
//
// The SAME control both TRIGGERS and CLEARS an emergency stop. It starts
// "needs reset" - on load, on every fresh connection, and again after every
// trip - and every motion-starting gesture this WO gates (Cycle Start, Step,
// and every machine-moving function in this module) stays refused until a
// SEPARATE, deliberate reset clears the latch.
//
// WO-469: THE CONTROL HAS TWO MODES, AND THE MODE DECIDES - NOT THE STATE.
// Operator's ruling, 2026-08-22, verbatim: "e-stop is one button and clear is a
// different button... once it's already in e-stop, you don't need an e-stop
// because it's already e-stopped."
//
//   armed   (latch clear) -> the control is an E-STOP. A click STOPS. Only
//                            stops. Unconditional, synchronous, never gated.
//   stopped (latch armed) -> the control is a CLEAR. A click CLEARS. Only
//                            clears, through resetEstop()'s own confirm.
//
// This REPLACES the pre-WO-469 pressEstop(), which was one entry point that
// had to GUESS whether a click meant stop or reset (`provenSafeBeforeClick`,
// built on ctrl.verifiedIdle()). That guess was the deadlock: emergencyStop()
// sets the state to 'alarm' and verifiedIdle() demands 'idle', so THE FIRST
// CLICK GUARANTEED THE ONE STATE THE SECOND CLICK WOULD NOT ACCEPT. Every
// later click took the trigger branch, re-armed the latch, restarted the
// debounce and answered ESTOP_RESET_REFUSAL.moving - so resetEstop(), which
// accepts 'idle' OR 'alarm' and would have cleared it, was never reached from
// the button at all. A mode is not a guess; the branch is deleted, not
// repaired.
//
// Attempt 2's substantiated finding ("the same click that stops the machine
// also cleared the interlock") is now closed BY CONSTRUCTION rather than by a
// pre-click evidence snapshot: a click in armed mode only ever stops, so no
// click can be both the stop and the reset. Every motion-starting path in
// this module is gated on the latch, so a machine that can be moving is a
// machine whose control is in ARMED mode - the stop is never behind the
// clear. The residual risk Operator accepted and named: an operator who stabs the
// flashing CLEAR meaning to stop will clear instead. Nothing starts moving
// when that happens, and triggerEmergencyStop() below remains an
// unconditional stop for any caller (a keyboard shortcut, a pendant) that
// knows its gesture is a trigger.
//
// This is a UI-level latch, NOT a stand-in for grbl's own alarm/$X unlock.
// grbl ALARM covers different faults (limit switch, probe miss, unhomed
// move) with its own existing recovery path (Stop/Reset, $X); folding the
// two together would let one click silently paper over a fault it never
// addressed. Our simulated transport cannot honestly assert a real E-stop
// circuit is physically clear, so this never claims to - it only tracks
// whether THIS software has seen a deliberate reset gesture, CONFIRMED SAFE
// by a status report GRBL sent since the session (or the last trip) began.
//
// Two substantiated audit findings shaped this design and both stay fixed
// here:
//  - attempt 1: resetEstop() must never trust a cached machineState - a
//    background poll can be up to ~1s stale. Fixed by asking fresh
//    (queryStatus()) and awaiting the SESSION's own next status report.
//  - attempt 2: a click on the TRIPPED button must never let its OWN stop's
//    resulting status report satisfy its OWN reset confirm - Operator's model
//    requires a SEPARATE, deliberate click, and "the same stab that stopped
//    it also re-armed it" is exactly the hazard this WO exists to prevent.
//    Fixed by pressEstop() below: it decides trigger-vs-reset from evidence
//    that existed strictly BEFORE this click ran, using the controller's own
//    verifiedIdle() (WO-087's "ask, do not assume" activity-generation
//    proof) snapshotted before emergencyStop() is ever called - so a click's
//    own stop can defend the machine, but can never be the reason a reset
//    succeeds.
const ESTOP_RESET_DEBOUNCE_MS = 600
// Bounds how long resetEstop() waits for the fresh status report it asks
// for. The protocol answers `?` in ~5-20ms (see grbl/controller.ts); this is
// generous headroom for a slow transport.
const ESTOP_CONFIRM_TIMEOUT_MS = 500

let estopNeedsResetValue = true
/** The fail-closed latch is armed at every connection boundary, but that does
 * not mean an E-STOP occurred. This stays true only from an actual software or
 * hardware trip until the latch is cleared or a new session begins. */
let estopTripNeedsResetValue = false
let estopResetDebounceActive = false
let estopResetDebounceTimer: ReturnType<typeof setTimeout> | null = null
/** True for the whole span of one resetEstop() call, from its fresh status
 *  request to its verdict - a second attempt during that window is refused
 *  the same way the post-trigger debounce is. */
let estopResetCheckInFlight = false
/** Bumped by every trip and every connection-phase change. A resetEstop()
 *  call snapshots this before it awaits a status report; if the value has
 *  moved on by the time that report arrives, a NEW trip (or session
 *  boundary) happened during the wait, so the report can no longer speak
 *  for the CURRENT trip and must not clear it. */
let estopEpoch = 0
const estopNeedsResetListeners = new Set<() => void>()
let pendingStatusWaiters: Array<(state: MachineState) => void> = []

export function estopNeedsReset(): boolean {
  return estopNeedsResetValue
}

/** True only after an actual software/hardware trip. The initial fail-closed
 * latch and the connect-only latch are safety gates, but neither claims an
 * E-STOP happened on the operator state chip. */
export function estopTripNeedsReset(): boolean {
  return estopNeedsResetValue && estopTripNeedsResetValue
}

export function subscribeEstopNeedsReset(listener: () => void): () => void {
  estopNeedsResetListeners.add(listener)
  return () => estopNeedsResetListeners.delete(listener)
}

/** Test isolation only. Production code must clear this latch through the
 * verified resetEstop() path above. Keeping this explicit prevents motion
 * tests from silently depending on another test file having reset E-STOP. */
export function __resetEstopInterlockForTest(): void {
  if (import.meta.env.MODE !== 'test') {
    throw new Error('__resetEstopInterlockForTest is available only in tests.')
  }
  clearEstopResetDebounce()
  pendingStatusWaiters = []
  estopResetCheckInFlight = false
  setEstopNeedsReset(false)
}

/** Test isolation only: arm the latch exactly as a trip or connection boundary
 * does. Tests that pin a specific trip may use this instead of relying on
 * connection setup as the cause of the armed state. */
export function __armEstopInterlockForTest(): void {
  if (import.meta.env.MODE !== 'test') {
    throw new Error('__armEstopInterlockForTest is available only in tests.')
  }
  armEstopNeedsReset()
}

function setEstopNeedsReset(needsReset: boolean): void {
  const tripChanged = !needsReset && estopTripNeedsResetValue
  if (!needsReset) estopTripNeedsResetValue = false
  if (estopNeedsResetValue === needsReset && !tripChanged) return
  estopNeedsResetValue = needsReset
  // WO-2668: a trip and its reset are edges the controller may switch outputs
  // on by itself; read them back rather than keep a pre-trip state.
  scheduleOutputPinRefresh()
  for (const listener of estopNeedsResetListeners) listener()
  notifyEstopControlMode()
}

function clearEstopResetDebounce(): void {
  if (estopResetDebounceTimer !== null) clearTimeout(estopResetDebounceTimer)
  estopResetDebounceTimer = null
  estopResetDebounceActive = false
  notifyEstopControlMode()
}

/** (Re)start the post-trigger debounce (hazard property 3): a stop followed
 *  instantly by an accidental second click must not immediately re-arm the
 *  machine - a reset attempt inside this window always refuses `tooSoon`.
 *
 *  WO-469 / Operator 2026-08-22: "put a time delay in between when the reset mode
 *  goes active so you couldn't accidentally double tap." The SAME window now
 *  also gates when the control PRESENTS itself as a clear - see
 *  estopControlMode() below. It is deliberately the same timer and the same
 *  constant, not a second one: a control that offered a clear the underlying
 *  rule would refuse is the WO-474 defect (a live-looking control that
 *  silently does nothing), and two timers could drift apart into exactly
 *  that. */
function startEstopResetDebounce(): void {
  estopResetDebounceActive = true
  if (estopResetDebounceTimer !== null) clearTimeout(estopResetDebounceTimer)
  estopResetDebounceTimer = setTimeout(() => {
    estopResetDebounceActive = false
    estopResetDebounceTimer = null
    notifyEstopControlMode()
  }, ESTOP_RESET_DEBOUNCE_MS)
}

function notifyEstopStatusWaiters(state: MachineState): void {
  if (pendingStatusWaiters.length === 0) return
  const waiters = pendingStatusWaiters
  pendingStatusWaiters = []
  for (const waiter of waiters) waiter(state)
}

/** Wait for the NEXT status report this session receives, however it was
 *  solicited - never a cached snapshot. Resolves null if none arrives before
 *  `timeoutMs`, which resetEstop() below treats as "could not confirm", not
 *  as safe (WO-328: "a fake interlock that reports safe when it does not
 *  know is worse than no interlock"). */
function nextMachineState(timeoutMs: number): Promise<MachineState | null> {
  return new Promise((resolve) => {
    let settled = false
    const waiter = (state: MachineState) => {
      if (settled) return
      settled = true
      clearTimeout(timer)
      resolve(state)
    }
    const timer = setTimeout(() => {
      if (settled) return
      settled = true
      pendingStatusWaiters = pendingStatusWaiters.filter((w) => w !== waiter)
      resolve(null)
    }, timeoutMs)
    pendingStatusWaiters.push(waiter)
  })
}

/** Force the "needs reset" latch armed - a fresh connection is a fresh
 *  session exactly like a fresh page load, a disconnect can never be
 *  answered by a report that will now never arrive, and a trip is a trip.
 *  Never starts the post-trigger debounce by itself; only a genuine trigger
 *  does that, because only a trip needs protecting from an instant
 *  accidental double-fire. */
function armEstopNeedsReset(tripped = true): void {
  const tripChanged = estopTripNeedsResetValue !== tripped
  estopTripNeedsResetValue = tripped
  const latchChanged = !estopNeedsResetValue
  estopEpoch++
  setEstopNeedsReset(true)
  // A trip can replace a fresh-connect interlock (or a connection boundary can
  // replace a prior trip) without changing the latch boolean. Subscribers must
  // still repaint the state chip when that cause changes.
  if (!latchChanged && tripChanged) {
    for (const listener of estopNeedsResetListeners) listener()
  }
  clearEstopResetDebounce()
  pendingStatusWaiters = []
}

/** The E-STOP button's TRIGGER half. Always live, never slowed, never
 *  confirmed - WO-328 explicitly forbids adding friction here. Tripping
 *  always re-arms the "needs reset" latch, even if it was already tripped,
 *  and (re)starts the debounce that stops an accidental second click from
 *  instantly re-arming the machine. Exported for direct use (e.g. a
 *  keyboard shortcut, or a caller that already knows this click is a
 *  trigger); the button itself goes through pressEstop() below, which
 *  decides trigger-vs-reset for an ambiguous click. */
export function triggerEmergencyStop(): void {
  getMachineController().emergencyStop()
  armEstopNeedsReset()
  startEstopResetDebounce()
}

/** The plain reasons a reset attempt is refused. Exported so the button that
 *  performs it and the tests asserting its text stay one string. */
export const ESTOP_RESET_REFUSAL = {
  notTripped: 'The E-STOP is already reset.',
  tooSoon: 'Wait a moment before resetting - this stops an accidental second click from re-arming the machine.',
  moving:
    'The machine could still be moving, or the controller has not confirmed it has stopped - it cannot be reset from here.',
  disconnected: 'Connect to the machine before resetting the E-STOP.',
  // WO-469: the confirm passed, but the controller would not confirm it came
  // back to a safe idle. The controller's own sentence is appended when it
  // gave one. The latch STAYS SET - WO-474: never show the affirmative state
  // of something that did not happen.
  notReleased: 'The controller did not confirm it returned to a safe idle, so the E-STOP stays set.',
  // WO-1550: the board's status frames carry the physical E-STOP INPUT
  // (`MachineStatus.inputs.estop`), and on 2026-09-14 the button was still
  // held while CLEAR was refused - yet the console never said so. When that
  // input is asserted it IS the reason the clear was refused, and it is the
  // one fact the operator can act on; "did not settle to idle" is not. Its
  // own capitalised sentence, so the row never reads as a run-on.
  buttonStillPressed:
    'The E-STOP button on the machine is still pressed - release it, then press CLEAR.',
} as const

/** Controller-supplied refusal reasons are written for a log, not for the
 *  space after a full stop. WO-1550: a refusal that appends one used to read
 *  as a run-on with a lower-case second sentence ("...stays set. the
 *  controller did not settle..."). Give it its capital and a terminal stop so
 *  it reads as the separate, proper sentence it is; never touch the rest of
 *  the wording the controller chose. */
function asSentence(text: string): string {
  if (!text) return text
  const capitalised = text[0].toUpperCase() + text.slice(1)
  return /[.!?]$/.test(capitalised) ? capitalised : `${capitalised}.`
}

// ESTOP_BLOCKS_MOTION lives in operatorAuthority.ts (WO-1992).

export type EstopResetResult = { ok: true } | { ok: false; reason: string }

/**
 * The E-STOP button's RESET half (WO-328). Never trusts the machineState a
 * background POLL happened to leave cached - that value can be up to one
 * idle-poll cycle (~1s) stale (attempt 1's substantiated audit finding).
 * Instead it asks fresh and waits for GRBL's own next answer - the same
 * "ask, do not assume" discipline resetToIdle() uses (WO-087) - and refuses,
 * never assumes safe, if that answer does not arrive in time.
 *
 * Still claims nothing about grbl's own ALARM. grbl ALARM covers different
 * faults (limit switch, probe miss, unhomed move) with its own existing
 * recovery path (Stop/Reset, $X), and folding the two together would let one
 * click silently paper over a fault it never addressed. So this deliberately
 * does NOT send $X.
 *
 * WO-469 - what it DOES now send. It was previously true that this sent
 * nothing at all, and that was the second half of the deadlock: the
 * simulator's own `estopTripped` is released ONLY by resetToIdle(), whose
 * sole non-test caller was armProgramFromTop() - a JOB action that refuses
 * without a loaded program AND refuses while alarmed, which is the only state
 * you can be in when you need it. Clearing an E-STOP is an OPERATOR-RECOVERY
 * action and must never be reachable only through a job action. So the
 * confirmed clear now performs the controller-side release itself, through
 * the interface method that already means exactly that:
 *
 *     ctrl.resetToIdle()  - "return to a VERIFIED idle" (WO-087).
 *
 * That is option (c) of the WO's list - a distinct explicit operator action -
 * and it needed no new controller method, because the action already existed
 * and only lacked an operator-facing caller. Deliberately NOT (a) reset() and
 * NOT (b) unlock(): both are OTHER controls (Stop/Reset, and JogPanel's $X),
 * and on this backend a raw jog is gated on the controller state alone, so
 * letting either release the E-STOP would let a control that is not the
 * E-STOP re-enable motion. GRBL-PROTOCOL is explicit that a soft reset
 * "PRESERVES alarm lock", so (a) would also make the simulator LESS faithful
 * than the machine it simulates. Only the E-STOP's own CLEAR releases an
 * E-STOP.
 *
 * Nothing resetToIdle() sends can start motion (0x21, 0x18, 0x3F are halt and
 * query bytes), it is awaited BEFORE the latch clears, and the epoch is
 * re-checked afterwards - so a trip landing during the release wins.
 *
 * Callable directly (tests, and any caller that already knows the gesture is
 * a deliberate, isolated clear). WO-469: this function is now the ONLY place
 * that decides whether a clear may happen - pressEstop() below no longer
 * carries a second, stricter copy of the rule.
 */
export async function resetEstop(): Promise<EstopResetResult> {
  if (!estopNeedsResetValue) return { ok: false, reason: ESTOP_RESET_REFUSAL.notTripped }
  if (estopResetDebounceActive || estopResetCheckInFlight) {
    return { ok: false, reason: ESTOP_RESET_REFUSAL.tooSoon }
  }
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  if (ctrl.connectionPhase() !== 'connected') {
    return { ok: false, reason: ESTOP_RESET_REFUSAL.disconnected }
  }
  // hasActiveJob() is exact and synchronous (set the instant a job starts or
  // stops, never poll-derived) - refuse on it before ever awaiting anything.
  if (ctrl.hasActiveJob()) return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }
  // WO-469: the three in-flight activities of OURS that a status report does
  // not describe. These used to live in pressEstop()'s pre-click snapshot;
  // they moved here so the whole rule is in ONE place (two copies of a safety
  // rule is the defect this order exists to remove) and so a direct caller
  // gets them too. A probe cycle / Step Back / fit trace can only be running
  // if the latch was clear when it started, so this catches the case where a
  // trip landed on top of one and its promise is still unwinding.
  if (isProbeCycleActive() || stepBackInProgressValue || store().fitTrace?.step === 'tracing') {
    return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }
  }

  const epoch = estopEpoch
  estopResetCheckInFlight = true
  try {
    // Register the waiter BEFORE sending the query: some transports (the
    // simulator) answer `?` synchronously, in the same call stack as
    // queryStatus() - calling queryStatus() first would let that reply (and
    // its notifyEstopStatusWaiters() call) fire into an empty waiter list,
    // losing it, and this would then time out on every real answer instead
    // of on a genuinely silent controller.
    const statePromise = nextMachineState(ESTOP_CONFIRM_TIMEOUT_MS)
    ctrl.queryStatus()
    const state = await statePromise
    if (!receiptIsCurrent(receiptToken)) {
      return { ok: false, reason: ESTOP_RESET_REFUSAL.disconnected }
    }
    if (epoch !== estopEpoch) {
      // Superseded: a new trip or a fresh connection happened while this
      // attempt was waiting - a report from before that cannot clear it.
      return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }
    }
    if (ctrl.connectionPhase() !== 'connected') {
      return { ok: false, reason: ESTOP_RESET_REFUSAL.disconnected }
    }
    if (state !== 'idle' && state !== 'alarm') {
      return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }
    }
    if (ctrl.hasActiveJob()) return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }

    // The confirm has passed. NOW release the controller side - see the note
    // above on why this is resetToIdle() and not reset() or unlock().
    const release = await ctrl.resetToIdle()
    if (!receiptIsCurrent(receiptToken)) {
      return { ok: false, reason: ESTOP_RESET_REFUSAL.disconnected }
    }
    if (!release.ok) {
      // WO-1550: name the physical button when the board's own status frames
      // say it is still held. This is checked AFTER the release attempt so
      // the freshest frame is read, and the latch still stays set either way -
      // only the sentence the operator sees changes.
      if (ctrl.status().inputs?.estop === true) {
        return { ok: false, reason: ESTOP_RESET_REFUSAL.buttonStillPressed }
      }
      return {
        ok: false,
        reason: release.reason
          ? `${ESTOP_RESET_REFUSAL.notReleased} ${asSentence(release.reason)}`
          : ESTOP_RESET_REFUSAL.notReleased,
      }
    }
    // The release can take a real controller most of a second (GRBL settles,
    // soft-resets and waits for its banner). Re-check everything that could
    // have moved underneath it: a NEW trip during the release must win, and
    // must leave the latch set.
    if (epoch !== estopEpoch) return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }
    if (ctrl.connectionPhase() !== 'connected') {
      return { ok: false, reason: ESTOP_RESET_REFUSAL.disconnected }
    }
    if (ctrl.hasActiveJob()) return { ok: false, reason: ESTOP_RESET_REFUSAL.moving }

    setEstopNeedsReset(false)
    return { ok: true }
  } finally {
    estopResetCheckInFlight = false
  }
}

type EstopPressResult = { ok: true } | { ok: false; reason: string | null }

/** WO-469 / Operator 2026-08-22: which control the E-STOP button currently IS.
 *  The mode decides what a click does; the click never has to guess.
 *
 *   'armed'    - it is an E-STOP. A click stops, unconditionally.
 *   'settling' - it has just stopped and is NOT YET a clear. See below.
 *   'stopped'  - it is flashing, it is a CLEAR, and a click clears.
 *
 *  'settling' is Operator's refinement of 2026-08-22, and it is binding: "put a
 *  time delay in between when the reset mode goes active so you couldn't
 *  accidentally double tap." It answers the one risk his two-mode design
 *  accepts - an operator who stabs the flashing control meaning to STOP
 *  clears instead. During the delay the control is neither a live E-STOP nor
 *  a live clear; it is visibly not-yet-ready and it SAYS so, because a guard
 *  that only refuses is the WO-474 defect all over again.
 *
 *  IT GATES A CLEAR, NEVER A STOP. 'settling' is only ever reachable with the
 *  latch already armed, which is to say with the machine already stopped and
 *  every motion entry point in this module already refusing. Nothing is
 *  waiting to be stopped, so nothing is being delayed. In 'armed' mode there
 *  is no delay of any kind.
 *
 *  The mode is derived from the needs-reset latch, not from the controller's
 *  reported state, on purpose: the latch is what every motion gate in this
 *  module already consults, so "the control is a CLEAR" and "nothing in this
 *  module will start motion" are guaranteed to be the same fact. The UI
 *  renders the mode; it must show a DIFFERENT LABEL, not merely a different
 *  colour, so a stab meant as a stop cannot land on a control that reads the
 *  same.
 *
 *  The mode is PRESENTATION. It never becomes a second copy of the safety
 *  rule: resetEstop() alone decides whether a clear may happen, and it
 *  refuses `tooSoon` on this very same debounce, so a click that somehow
 *  lands during 'settling' (a key press, a race with the timer) is refused
 *  by the rule rather than by the mode. */
export type EstopControlMode = 'armed' | 'settling' | 'stopped'

export function estopControlMode(): EstopControlMode {
  if (!estopNeedsResetValue) return 'armed'
  return estopResetDebounceActive ? 'settling' : 'stopped'
}

/** How long the control stays 'settling' after a stop. Exported so the UI
 *  can say how long the wait is without hard-coding a second number, and so
 *  tests advance exactly this far. Operator set the value; do not re-pin it
 *  inside this order. */
export const ESTOP_CLEAR_DELAY_MS = ESTOP_RESET_DEBOUNCE_MS

const estopControlModeListeners = new Set<() => void>()

function notifyEstopControlMode(): void {
  for (const listener of estopControlModeListeners) listener()
}

/** Subscribe to mode changes. Distinct from subscribeEstopNeedsReset because
 *  the mode also turns over when the settling delay elapses, which moves no
 *  latch - without this the control would sit on 'settling' until some
 *  unrelated render happened to wake it, showing a not-yet-ready control long
 *  after it was ready. */
export function subscribeEstopControlMode(listener: () => void): () => void {
  estopControlModeListeners.add(listener)
  return () => estopControlModeListeners.delete(listener)
}

/**
 * The E-STOP control's SINGLE entry point (WO-328), rebuilt on Operator's
 * two-mode ruling (WO-469). It does not decide anything about the machine -
 * it dispatches on estopControlMode() and nothing else:
 *
 *   armed   -> STOP. Synchronous, unconditional, first and only thing this
 *              call does. Never slower, never gated, never confirmed - the
 *              fastest control on the screen to hit, exactly as before. The
 *              latch is re-armed and the post-trigger debounce (re)starts, so
 *              an accidental second stab cannot immediately clear it.
 *   settling -> CLEAR, refused. It is not yet a clear (Operator's double-tap
 *              delay), and resetEstop() answers `tooSoon` so the control has
 *              a sentence to show instead of doing nothing. It sends no stop:
 *              the machine is already stopped, and a stop here would be the
 *              accidental double-tap the delay exists to absorb.
 *   stopped -> CLEAR. Delegates the WHOLE decision to resetEstop(): the
 *              debounce, the connection check, the active-job check, the
 *              fresh-status confirm, the epoch check that refuses a report
 *              from before a newer trip, and the verified controller release.
 *              It sends no stop, because there is nothing left to stop - and
 *              because a clear that also stopped would re-alarm the machine
 *              it just released.
 *
 * There is no third path and no condition shared between the two. See the
 * design note above for why the old evidence-snapshot guess was a deadlock
 * rather than a guard.
 */
export async function pressEstop(): Promise<EstopPressResult> {
  if (estopControlMode() === 'armed') {
    triggerEmergencyStop()
    return { ok: true }
  }
  return resetEstop()
}

export function webSerialSupported(): boolean {
  return WebSerialTransport.isSupported()
}

// Keep the long-standing control-surface type closed to its rendered choices.
// Registry clients use backendRegistry.MachineConnectionKind, which is open so
// a plugin can add a route without expanding this built-in UI.
export type MachineConnectionKind = 'bridge' | 'simulator' | 'serial' | 'gateway'

interface ApplySpindleLinkOutcome {
  ok: boolean
  stored: boolean
  sent: boolean
  error: string | null
  definition: MachineSpindleLinkDefinition | null
}

type SpindleDefinitionController = MachineController & {
  applyVfdDefinition?: (
    definition: MachineSpindleLinkDefinition,
    options?: { connectTimeSync?: boolean },
  ) => Promise<{
    ok: boolean
    error: string | null
    definition: VfdDefinition | null
  }>
  confirmVfdLinkRemoved?: () => void
}

function spindleLinkDefinitionSignature(definition: MachineSpindleLinkDefinition): string {
  return JSON.stringify(definition)
}

/** A spindle receipt has authority only inside the exact backend session and
 * for the exact definition object that crossed the wire. Machine id alone is
 * insufficient because reconnecting the same machine creates a new session. */
function spindleReceiptMatchesSession(
  target: MachineController,
  generation: BackendGenerationToken | null,
  sessionRevision: number,
  machineId: string,
  definition: MachineSpindleLinkDefinition,
  sentSignature: string,
): boolean {
  return backendGenerationIsCurrent(generation)
    && target === controller
    && connectionRevision === sessionRevision
    && store().connectionPhase === 'connected'
    && useCamStore.getState().control.sessionMachine?.id === machineId
    && spindleLinkDefinitionSignature(definition) === sentSignature
}

function machineRecord(machineId: string) {
  const state = useCamStore.getState()
  const active = controlMachine(state)
  return state.machineLibrary.find((machine) => machine.id === machineId)
    ?? (active.id === machineId ? active : null)
}

/** One persistence path for the spindle document's library carrier and active
 * project mirror, matching the rest of the machine definition editor. */
function storeSpindleLinkDefinition(
  machineId: string,
  definition: MachineSpindleLinkDefinition | null,
): boolean {
  const state = useCamStore.getState()
  const machine = machineRecord(machineId)
  if (!machine) return false
  const next = { ...machine, spindleLinkDefinition: definition }
  state.updateMachineInLibrary(machineId, next)
  if (state.project.machine.id === machineId) state.setProjectMachine(next)
  return true
}

function statedSpindleNumber(machine: MachineConfig, key: string): number | null {
  const text = unsentSettingValue(machine.unsentSettings, 'uccnc', `Spindlesetupsettings.${key}`)
  if (text === null || text.trim() === '') return null
  const value = Number(text)
  return Number.isFinite(value) ? value : null
}

function statedSpindleNegate(machine: MachineConfig): boolean | null {
  const text = unsentSettingValue(
    machine.unsentSettings, 'uccnc', 'Spindlesetupsettings.SpindlePWMoutpinnegate',
  )
  if (text === null) return null
  if (text.trim().toLowerCase() === 'true') return true
  if (text.trim().toLowerCase() === 'false') return false
  return null
}

/** Build the app-owned board mapping from the profile catalogue when it stated
 * one. A hand-built definition gets explicit unknowns, ready for the same
 * editor; no UCCNC default is promoted into a machine fact. */
export function boardSpeedSpindleDrive(
  machine: MachineConfig,
  signal: 'pwm' | 'analog-0-10v',
): MachineSpindleDriveDefinition {
  return {
    kind: 'board-speed',
    signal,
    output: {
      port: statedSpindleNumber(machine, 'SpindlePWMoutport') ?? 0,
      pin: statedSpindleNumber(machine, 'SpindlePWMoutpin') ?? 0,
      negate: statedSpindleNegate(machine),
    },
    frequencyHz: statedSpindleNumber(machine, 'SpindlePWMfrequency'),
    minimumRpm: statedSpindleNumber(machine, 'Spindleminvelocity'),
    maximumRpm: statedSpindleNumber(machine, 'Spindlemaxvelocity'),
    minimumPercent: statedSpindleNumber(machine, 'SpindlePWMminpercent'),
    maximumPercent: statedSpindleNumber(machine, 'SpindlePWMmaxpercent'),
  }
}

/** Undo only the optimistic stored drive word after its existing link
 * operation refused. This is compensation, not a second editor save path:
 * the panel still owns successful definition writes. */
export function restoreMachineSpindleDriveAfterRefusal(
  machineId: string,
  drive: MachineSpindleDriveDefinition | undefined,
): void {
  const machine = machineRecord(machineId)
  if (!machine) return
  const next = { ...machine }
  if (drive === undefined) delete next.spindleDrive
  else next.spindleDrive = drive
  const state = useCamStore.getState()
  state.updateMachineInLibrary(machineId, next)
  if (state.project.machine.id === machineId) state.setProjectMachine(next)
}

function spindleConsole(message: string, severity: 'info' | 'warning'): void {
  useCamStore.getState().addConsoleEvent({ severity, source: 'machine', message })
}

type SpindleStopSample = Pick<BridgeVfdPush['v'], 'running' | 'lastStopReason'>
type UnexpectedSpindleStopReason = Exclude<
  BridgeVfdPush['v']['lastStopReason'],
  'none' | 'commanded'
>

/** Plain operator language for bridge stop causes. The wire words stay at the
 * transport boundary; neither the console nor hover context exposes them. */
export const SPINDLE_STOP_REASON_TEXT: Readonly<Record<UnexpectedSpindleStopReason, string>> = {
  serialTimeout: 'Spindle stopped by the software: the inverter stopped answering.',
  clientGone:
    'Spindle stopped by the software: this app went quiet for too long (the bridge did not hear from it).',
  closing: 'Spindle stopped: the bridge is closing.',
  refused: 'Spindle stopped: the inverter refused the command.',
}

function unexpectedSpindleStopText(
  reason: BridgeVfdPush['v']['lastStopReason'],
): string | null {
  return reason === 'none' || reason === 'commanded'
    ? null
    : SPINDLE_STOP_REASON_TEXT[reason]
}

/** An unexpected bridge-owned spindle stop is a machine fault, not a request
 * to wait for speed or silently re-command the inverter. Stop staged/running
 * motion at the board first, then end the operator's program with the exact
 * cause the bridge reported. A clean `commanded` stop never reaches here, so
 * Feed Hold retains its existing re-arm-on-resume behaviour. */
function failProgramForUnexpectedSpindleStop(message: string): boolean {
  const spindle = geometryProgramSpindle
  if (!spindle || !spindle.running) return false

  const target = spindle.controller
  const progressBeforeStop = target.jobProgress()
  cancelSpindleSpeedWait()
  stopJobForSession(target)
  const fault = { code: null, message, line: null, moveId: null }
  const run = programPartsRun
  if (run?.controller === target) {
    endProgramParts(message, 'failed', fault, 'error', true, progressBeforeStop)
    return true
  }

  store().setProgramReadiness({ ready: false, reason: message })
  store().pushConsole('rx', message, 'error')
  store().applyJobProgress({ ...progressBeforeStop, phase: 'failed', bytesInFlight: 0 })
  applyJobLifecycleEvent('failed', fault)
  return true
}

/** The panel is the existing spindle control and is always mounted while the
 * Control page is open, including when its body is collapsed. Native `title`
 * supplies the requested hover context without adding another UI element. */
function setSpindleStopTitle(message: string | null): void {
  if (typeof document === 'undefined') return
  const panel = document
    .querySelector<HTMLElement>('[data-testid="control-spindle-toggle"]')
    ?.closest<HTMLElement>('.control-panel')
  if (!panel) return
  if (message === null) panel.removeAttribute('title')
  else panel.title = message
}

interface SpindleStopReasonEffects {
  warning: (message: string) => void
  title: (message: string | null) => void
}

/**
 * One watcher belongs to one bridge connection. The stop reason has no event
 * id or timestamp, so its edge is reconstructed from the two facts the frame
 * does carry: a changed reason, or a running -> stopped transition. That
 * second clause is what lets two separate quiet-link stops with the same wire
 * reason both speak while repeated stopped frames remain silent.
 */
export function createSpindleStopReasonWatcher(
  effects: SpindleStopReasonEffects = {
    warning: (message) => {
      spindleConsole(message, 'warning')
      store().pushConsole('rx', message, 'warn')
    },
    title: setSpindleStopTitle,
  },
  accepts: () => boolean = () => true,
): (sample: SpindleStopSample) => void {
  let previous: SpindleStopSample | null = null
  let commandedStopContext = false
  return (sample) => {
    if (!accepts()) return
    if (previous === null) {
      previous = {
        running: sample.running,
        lastStopReason: sample.lastStopReason,
      }
      effects.title(null)
      return
    }
    const message = unexpectedSpindleStopText(sample.lastStopReason)
    if (sample.running) commandedStopContext = false
    else if (previous?.running === true) commandedStopContext = true
    else if (message === null) commandedStopContext = false

    const actionable = spindleSafetyStopIsActionable(commandedStopContext)
    effects.title(actionable && !sample.running && message !== null ? message : null)

    const isNewUnexpectedStop = actionable
      && !sample.running
      && message !== null
      && (previous === null
        || previous.running
        || previous.lastStopReason !== sample.lastStopReason)
    if (isNewUnexpectedStop && !failProgramForUnexpectedSpindleStop(message)) {
      effects.warning(message)
    }

    previous = {
      running: sample.running,
      lastStopReason: sample.lastStopReason,
    }
  }
}

// The bridge apply outlives any panel that initiated it. Keep this authority
// with the machine session so leaving and reopening Definition cannot admit a
// second candidate built from the document that is still awaiting receipt.
const spindleLinkAppliesInFlight = new Set<string>()
const spindleLinkApplyListeners = new Set<() => void>()

export function machineSpindleLinkApplyInFlight(machineId: string): boolean {
  return spindleLinkAppliesInFlight.has(machineId)
}

export function subscribeMachineSpindleLinkApply(listener: () => void): () => void {
  spindleLinkApplyListeners.add(listener)
  return () => {
    spindleLinkApplyListeners.delete(listener)
  }
}

function setMachineSpindleLinkApplyInFlight(machineId: string, inFlight: boolean): void {
  if (spindleLinkAppliesInFlight.has(machineId) === inFlight) return
  if (inFlight) spindleLinkAppliesInFlight.add(machineId)
  else spindleLinkAppliesInFlight.delete(machineId)
  for (const listener of spindleLinkApplyListeners) listener()
}

/** A bridge receipt can replace operational values, but it cannot establish
 * inverter verification or rewrite where the app-owned document came from. */
function machineOwnedVfdReceipt(
  sent: MachineSpindleLinkDefinition,
  received: VfdDefinition,
): MachineSpindleLinkDefinition {
  const directionChoice = Object.prototype.hasOwnProperty.call(sent, 'directionInverted')
    ? {
        directionInverted: sent.directionInverted,
        ...(sent.directionInvertedProvenance === undefined
          ? {}
          : { directionInvertedProvenance: sent.directionInvertedProvenance }),
      }
    : {}
  // WO-1718: which keypad rows follow a link field is the definition's, not
  // the bridge's; a receipt that drops the marker keeps the sent one.
  const sentRows = sent.requiredParameters as VfdRequiredParameterRow[] | undefined
  const requiredParameters = Array.isArray(received.requiredParameters)
    ? received.requiredParameters.map((row, index): VfdRequiredParameterRow => {
        const follows = sentRows?.[index]?.parameter === row.parameter ? sentRows[index].follows : undefined
        return follows === undefined || 'follows' in row ? row : { ...row, follows }
      })
    : received.requiredParameters
  return withFollowedParameters({
    ...received,
    requiredParameters,
    verified: sent.verified,
    provenance: sent.provenance,
    ...directionChoice,
  })
}

/** WO-2009: a definition saved before WO-1721 has a run-state register and no
 * table saying what its values mean; the bridge cannot keep a link without
 * one. When the definition names a shipped template, the app fills the rows
 * from it (Operator, 09-25: "Fix it your damn self") - never the operator. Returns
 * the template's name when it filled, so the caller says so once. */
function completedSpindleLinkDefinition(
  definition: MachineSpindleLinkDefinition,
): { definition: MachineSpindleLinkDefinition; filledFrom: string | null } {
  return completeVfdRunStateValues(
    definition,
    VFD_MODEL_TEMPLATES.map((template) => template.definition),
  )
}

function runStateRowsFilledLine(definition: MachineSpindleLinkDefinition, template: string): string {
  const rows = (definition.registers.runState.values ?? [])
    .map((row) => `${row.value} ${row.meaning}`).join(', ')
  return `Spindle link: the run-state table was missing, so the ${template} rows were filled in (${rows}).`
}

/** Store a fully checked definition locally when there is no matching bridge.
 * With a matching bridge, stopped-state confirmation and its checked receipt
 * are the acceptance boundary: a refusal leaves the edit pending and unstored. */
export async function applyMachineSpindleLinkDefinition(
  machineId: string,
  edited: MachineSpindleLinkDefinition,
  options: { declaring?: boolean } = {},
): Promise<ApplySpindleLinkOutcome> {
  // WO-1718: a keypad row that follows a link field is restated from it here,
  // on every store - one fact, never a second copy that can disagree.
  const completion = completedSpindleLinkDefinition(withFollowedParameters(edited))
  const definition = completion.definition
  const filled = (outcome: ApplySpindleLinkOutcome): ApplySpindleLinkOutcome => {
    if (outcome.stored && completion.filledFrom !== null) {
      spindleConsole(runStateRowsFilledLine(definition, completion.filledFrom), 'info')
    }
    return outcome
  }
  if (machineSpindleLinkApplyInFlight(machineId)) {
    const error = 'waiting for the bridge to confirm the previous change'
    spindleConsole(`spindle link: ${error}`, 'info')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  const validation = validateVfdDefinition(definition as unknown as VfdDefinition)
  if (!validation.ok) {
    const error = validation.errors.map((fault) => `${fault.path}: ${fault.sentence}`).join(' ')
    spindleConsole(`Spindle link refused - ${error}`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  const link = vfdPortLinkState()
  if (link.connected && link.machineId === machineId && link.spindleTurning === true) {
    const error = 'The spindle is running. Stop it before changing the spindle link definition'
    spindleConsole(`Spindle link refused - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  if (!link.connected || link.machineId !== machineId) {
    const stored = storeSpindleLinkDefinition(machineId, definition)
    if (!stored) {
      const error = `machine ${machineId} is not in the machine library or active project`
      spindleConsole(`Spindle link refused - ${error}.`, 'warning')
      return { ok: false, stored: false, sent: false, error, definition: null }
    }
    return filled({ ok: true, stored: true, sent: false, error: null, definition })
  }
  const target = controller as SpindleDefinitionController | null
  if (typeof target?.applyVfdDefinition !== 'function') {
    const error = 'this connection cannot apply a spindle link definition'
    spindleConsole(`Spindle link refused - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }

  const sessionRevision = connectionRevision
  const generation = captureBackendGeneration(target)
  const sentSignature = spindleLinkDefinitionSignature(definition)
  const sessionAtSend = useCamStore.getState().control.sessionMachine
  if (!sessionAtSend || sessionAtSend.id !== machineId) {
    const error = 'this definition does not belong to the connected machine session'
    spindleConsole(`Spindle link refused - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }

  setMachineSpindleLinkApplyInFlight(machineId, true)
  try {
    // WO-1718: DECLARING a link on a bridge whose hello said it holds none
    // uses the controller's no-link creation path: there is no inverter on
    // that bridge to report a stopped spindle, so waiting for one would refuse
    // the only way to set a VFD up. The controller still applies its own
    // stopped-state gate whenever the bridge does hold a link.
    const reply = options.declaring === true
      ? await target.applyVfdDefinition(definition, { connectTimeSync: true })
      : await target.applyVfdDefinition(definition)
    if (!spindleReceiptMatchesSession(
      target, generation, sessionRevision, machineId, definition, sentSignature,
    )) {
      const error = 'the bridge receipt belongs to a replaced backend/session or a changed definition'
      spindleConsole(`Spindle link receipt ignored - ${error}.`, 'info')
      return { ok: false, stored: false, sent: true, error, definition: null }
    }
    if (!reply.ok || reply.definition === null) {
      const error = reply.error ?? 'the machine bridge did not confirm the definition it now holds'
      spindleConsole(`Spindle link refused - ${error}.`, 'warning')
      return { ok: false, stored: false, sent: true, error, definition: null }
    }
    const confirmed = machineOwnedVfdReceipt(definition, reply.definition)
    const stored = storeSpindleLinkDefinition(machineId, confirmed)
    if (!stored) {
      const error = `machine ${machineId} is not in the machine library or active project`
      spindleConsole(`Spindle link refused - ${error}.`, 'warning')
      return { ok: false, stored: false, sent: true, error, definition: null }
    }
    useCamStore.getState().confirmControlSessionSpindleLinkDefinition(machineId, confirmed)
    publishAppliedVfdDefinition(machineId, confirmed)
    spindleConsole('Spindle link sent - 12 fields, the bridge confirms.', 'info')
    return filled({ ok: true, stored: true, sent: true, error: null, definition: confirmed })
  } catch (error) {
    if (!spindleReceiptMatchesSession(
      target, generation, sessionRevision, machineId, definition, sentSignature,
    )) {
      spindleConsole(
        'Spindle link receipt ignored - the bridge receipt belongs to a replaced backend/session or a changed definition.',
        'info',
      )
      return { ok: false, stored: false, sent: true, error: 'stale backend receipt', definition: null }
    }
    throw error
  } finally {
    setMachineSpindleLinkApplyInFlight(machineId, false)
  }
}

/** WO-1718: DRIVE -> MODBUS VFD. Declares a complete link in `machineId`'s
 * definition from a named inverter model template; a bridge connected for
 * this machine is handed it through the same seam as any edit. A null id is
 * the Control machine - the record the Definition page edits. */
export async function declareMachineVfdLink(
  machineIdOrControl: string | null,
  templateId: string,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  const definition = vfdLinkFromTemplate(templateId, machineId)
  if (definition === null) {
    const error = `no inverter template named ${templateId}`
    spindleConsole(`Spindle link not declared - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  const outcome = await applyMachineSpindleLinkDefinition(machineId, definition, { declaring: true })
  if (outcome.stored) {
    spindleConsole(
      `Spindle link declared from the ${definition.name} template - edit any field below; `
        + 'not yet commissioned against the inverter.',
      'info',
    )
  }
  return outcome
}

/** WO-1718: DRIVE -> NONE. The definition stops holding a VFD link (an
 * explicit null, so no later connect can bring one back), and a bridge
 * connected for this machine is told to close it. */
export async function removeMachineVfdLink(
  machineIdOrControl: string | null,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  if (machineSpindleLinkApplyInFlight(machineId)) {
    const error = 'waiting for the bridge to confirm the previous change'
    spindleConsole(`spindle link: ${error}`, 'info')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  const link = vfdPortLinkState()
  if (link.connected && link.machineId === machineId && link.spindleTurning === true) {
    const error = 'The spindle is running. Stop it before removing the spindle link'
    spindleConsole(`Spindle link not removed - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  if (!storeSpindleLinkDefinition(machineId, null)) {
    const error = `machine ${machineId} is not in the machine library or active project`
    spindleConsole(`Spindle link not removed - ${error}.`, 'warning')
    return { ok: false, stored: false, sent: false, error, definition: null }
  }
  const told = clearVfdDefinitionOnBridge(machineId)
  if (told === null) {
    spindleConsole("Spindle link removed from this machine's definition.", 'info')
    return { ok: true, stored: true, sent: false, error: null, definition: null }
  }
  const target = controller as SpindleDefinitionController | null
  setMachineSpindleLinkApplyInFlight(machineId, true)
  try {
    const reply = await told
    if (reply.ok) {
      if (target === controller) target?.confirmVfdLinkRemoved?.()
      spindleConsole('Spindle link removed - the bridge closed it.', 'info')
      return { ok: true, stored: true, sent: true, error: null, definition: null }
    }
    spindleConsole(
      `Spindle link removed from this machine's definition; the bridge did not confirm it closed the link - ${reply.error}.`,
      'warning',
    )
    return { ok: true, stored: true, sent: true, error: reply.error, definition: null }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    spindleConsole(
      `Spindle link removed from this machine's definition; the bridge did not confirm it closed the link - ${message}.`,
      'warning',
    )
    return { ok: true, stored: true, sent: true, error: message, definition: null }
  } finally {
    setMachineSpindleLinkApplyInFlight(machineId, false)
  }
}

/** WO-1718: CHANGE THE LINK'S TRANSPORT (serial RTU <-> network TCP). The two
 *  are different documents, so the new link arrives whole - the Spindle area
 *  holds the new transport's fields until the operator has given them - and it
 *  goes through the same store-and-push as any other edit. */
export async function changeMachineVfdLinkTransport(
  machineIdOrControl: string | null,
  definition: MachineSpindleLinkDefinition,
  link: VfdLink,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  const outcome = await applyMachineSpindleLinkDefinition(machineId, {
    ...definition,
    link,
    verified: false,
    provenance: { kind: 'edited-here', source: `LienCAM machine ${machineId}` },
  } as MachineSpindleLinkDefinition)
  if (outcome.stored) {
    spindleConsole(
      `Spindle link transport changed to ${link.transport} - not yet commissioned against the inverter.`,
      'info',
    )
  }
  return outcome
}

/** WO-1718: ADD OR REMOVE A REQUIRED KEYPAD PARAMETER ROW. The rows are part
 *  of the definition like any other field, stored and pushed the same way. */
export async function setMachineVfdRequiredParameters(
  machineIdOrControl: string | null,
  definition: MachineSpindleLinkDefinition,
  rows: VfdRequiredParameterRow[],
  what: string,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  const outcome = await applyMachineSpindleLinkDefinition(machineId, {
    ...definition,
    requiredParameters: rows,
    verified: false,
    provenance: { kind: 'edited-here', source: `LienCAM machine ${machineId}` },
  } as MachineSpindleLinkDefinition)
  if (outcome.stored) spindleConsole(`Spindle link ${what}.`, 'info')
  return outcome
}

/** WO-1721: REPLACE THE RUN-STATE VALUE TABLE AS ONE DEFINITION EDIT. Add,
 * remove and meaning-choice controls cannot safely be expressed as scalar
 * paths: an absent table has no path to edit, while a bridge refusal must
 * leave the previously accepted rows intact. The common apply path validates
 * the whole candidate and stores only a local acceptance or matching bridge
 * receipt. */
export async function setMachineVfdRunStateValues(
  machineIdOrControl: string | null,
  definition: MachineSpindleLinkDefinition,
  rows: VfdRunStateValue[],
  what: string,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  const outcome = await applyMachineSpindleLinkDefinition(machineId, {
    ...definition,
    registers: {
      ...definition.registers,
      runState: { ...definition.registers.runState, values: rows },
    },
    verified: false,
    provenance: { kind: 'edited-here', source: `LienCAM machine ${machineId}` },
  } as MachineSpindleLinkDefinition)
  if (outcome.stored) spindleConsole(`Spindle link ${what}.`, 'info')
  return outcome
}

/** WO-1735: STATE, CHANGE OR CLEAR THE DRIVE'S OWN FAULT REGISTER AS ONE
 * DEFINITION EDIT. `undefined` clears it, which is a definition saying this
 * drive has no fault register and its fault is read from the operating-state
 * word, exactly as before this order. Like the run-state table this is not a
 * scalar path - an absent register has no path to edit - so the whole
 * candidate is validated and stored, or refused, together.
 *
 * WO-1065: the Control-machine fallback for an editor that was handed no
 * machine lives HERE with its four siblings, never in the editor. The spindle
 * editor resolves no machine identity of its own. */
export async function setMachineVfdFaultCodeRegister(
  machineIdOrControl: string | null,
  definition: MachineSpindleLinkDefinition,
  register: VfdFaultCodeRegister | undefined,
  what: string,
): Promise<ApplySpindleLinkOutcome> {
  const machineId = machineIdOrControl ?? controlMachine(useCamStore.getState()).id
  const registers = { ...definition.registers } as Record<string, unknown>
  if (register === undefined) delete registers.faultCode
  else registers.faultCode = register
  const outcome = await applyMachineSpindleLinkDefinition(machineId, {
    ...definition,
    registers,
    verified: false,
    provenance: { kind: 'edited-here', source: `LienCAM machine ${machineId} - ${what}` },
  } as unknown as MachineSpindleLinkDefinition)
  if (outcome.stored) spindleConsole(`Spindle link ${what}.`, 'info')
  return outcome
}

/** WHAT THE BRIDGE IS HOLDING, PER BRIDGE ENDPOINT.
 *
 * WO-1556. The bridge reports what it holds only in the readback of an
 * `applySkew` it answered, and nothing in hello carries it, so this is the
 * app's memory of that readback. `held: undefined` means nothing has been
 * confirmed held on this endpoint in this app session; a NUMBER is a
 * measurement the bridge confirmed; `null` is a confirmed clear.
 *
 * THIS MEMORY MUST NEVER GATE A CONNECT-TIME SEND. A bridge process outlives
 * both a machine selection and an app-window reload, so on connect the app
 * cannot trust what it "remembers" the bridge holding - it may hold a
 * measurement from a session this app instance never saw. A held architect
 * verdict (2026-09-15) caught exactly this: an app reload forgets the memory,
 * the skew is removed from the definition, and a connect that skips the clear
 * because the (fresh, empty) memory "matches" leaves a stale 0.12 mm on the
 * bridge for the next Home All to apply. So every connect sends the
 * definition's skew unconditionally - a measurement or a clear - and the
 * memory exists ONLY to dedupe a LIVE EDIT against a state already confirmed
 * this session (`onConnect` below).
 *
 * `inFlight` collapses the several store writes one edit makes into a single
 * push, and keeps the connect sync and an edit from doubling each other. */
interface SkewSyncState {
  held: number | null | undefined
  inFlight: boolean
}

type SkewController = MachineController & Required<Pick<MachineController, 'applySkew'>>

function supportsSkewApply(target: MachineController): target is SkewController {
  return typeof target.applySkew === 'function'
}

const skewSyncByBridge = new Map<string, SkewSyncState>()
/** The endpoint the live bridge session is on, and the machine it was opened
 *  for. Set when a bridge connect succeeds; only read while connected. */
let connectedBridgeKey: string | null = null
let connectedBridgeMachineId: string | null = null

function skewSyncState(bridgeKey: string): SkewSyncState {
  let state = skewSyncByBridge.get(bridgeKey)
  if (!state) {
    state = { held: undefined, inFlight: false }
    skewSyncByBridge.set(bridgeKey, state)
  }
  return state
}

/** True when the bridge's confirmed state already IS `desired`, so a push
 *  would change nothing. `null` and "never confirmed" are the same claim about
 *  the bridge: it holds no measurement. */
function skewMatchesHeld(state: SkewSyncState, desired: number | null): boolean {
  if (desired === null) return typeof state.held !== 'number'
  return typeof state.held === 'number' && state.held === desired
}

/** WO-1006 / WO-1556: HAND THE BRIDGE THIS MACHINE'S GANTRY SQUARING OFFSET.
 *
 * THIS IS THE WHOLE OF `src/`'S PART IN THE FEATURE. Operator ruling 2026-08-26: "once
 * applied you drive the axis like you always would because it IS NOW SQUARE."
 * The app holds the measurement and hands it over; the bridge applies it once
 * after homing. Nothing here applies anything, no toolpath is transformed, and
 * no per-move arithmetic exists anywhere to keep in step.
 *
 * EVERY CONNECT SENDS, ALWAYS - APPLY OR CLEAR. The first cut sent
 * `applySkew {offsetMm: null}` unconditionally and the bridge printed
 * "[bridge] gantry skew cleared" on every one, including a clear of a skew
 * that was never set - that is a `pendant/uccnc-bridge/Machine.cs` wording
 * problem (WO-1556: `SetGantrySkew` now stays quiet unless it was actually
 * holding something), not a reason for `src/` to guess when a clear is
 * needed. A second cut skipped the connect-time CLEAR when this app session's
 * memory of the endpoint already matched "nothing held" - and got HELD:
 * memory keyed by app session cannot know what a bridge that outlives an app
 * reload is actually holding, so it left a real stale skew on the board. The
 * endpoint memory (`skewSyncByBridge` above) is never consulted for a
 * connect-time send; it only dedupes a LIVE EDIT (`onConnect` false below)
 * against a state this session already confirmed, so an edit that changes
 * nothing does not push a redundant frame.
 *
 * AND THAT IS ALSO WHY AN OLD BRIDGE IS SILENT RATHER THAN NOISY. A bridge
 * that does not know `applySkew` cannot be holding a skew either, so a failed
 * CLEAR has changed nothing and has nothing to report. A failed APPLY is a
 * real thing the operator must know, and it says so.
 *
 * IT MUST NEVER HOLD THE CONNECTION DOOR SHUT, and it was written awaited at
 * first, which is how that gets discovered: a bridge that does not answer
 * `applySkew` leaves the caller sitting on the call timeout, and the connect
 * continuation behind it. Measured on this branch - `unitsSyncCapability`
 * passed on main and timed out here, for no reason of its own. The connection
 * is live either way, and the value is not needed until somebody homes, which
 * is an operator action minutes away. So the caller launches this and does not
 * wait, exactly as `reconcileGrblSettingsOnConnect` does one screen below and
 * for the same reason.
 */
async function syncSkewToBridge(
  machineId: string,
  target: SkewController,
  isCurrent: () => boolean,
  bridgeKey: string,
  onConnect = false,
): Promise<void> {
  const state = skewSyncState(bridgeKey)
  if (state.inFlight) return
  const machine = machineRecord(machineId)
  if (!machine) return
  const skew = machineSkew(machine)
  const desired = skew ? skew.offsetMm : null
  // WO-1556: on connect this NEVER skips - apply or clear, the definition's
  // skew is always handed over, because the endpoint memory cannot know what
  // a bridge that outlives an app reload actually holds. Off connect (a live
  // edit while already connected) the memory dedupes: if this session already
  // confirmed the bridge holds `desired`, pushing again would change nothing.
  const matchesHeld = skewMatchesHeld(state, desired)
  if (!onConnect && matchesHeld) return
  state.inFlight = true
  try {
    const reply = await target.applySkew(desired)
    // The reply can outlive the session it belongs to now that nothing waits
    // for it, so nothing is said - and nothing is remembered - about a
    // connection that has already been replaced.
    if (!isCurrent() || target.connectionPhase() !== 'connected') return
    if (reply.ok) {
      state.held = reply.set && reply.offsetMm !== null ? reply.offsetMm : null
      if (skew) {
        store().pushConsole(
          'rx',
          `Gantry skew ${machineLengthText(skew.offsetMm)} sent to the bridge - it is applied once, `
            + 'after the next homing cycle, to the slaved axis.',
          'info',
        )
      }
      return
    }
    if (!skew) return
    store().pushConsole(
      'rx',
      `Gantry skew was NOT sent - ${reply.error ?? 'the machine bridge did not confirm it'}. `
        + 'Homing will square the gantry exactly as it does today and nothing will be compensated.',
      'error',
    )
  } finally {
    state.inFlight = false
  }
}

/** WO-1556: A SKEW EDIT REACHES THE BRIDGE WHILE THE CONNECTION IS LIVE.
 *
 * WO-1006 sent the measurement only at connect, so a measurement set or
 * removed in the definition editor did not reach a bridge session that was
 * already running - the next homing used the old number. This watches the
 * connected machine's record and pushes the change through the same
 * `syncSkewToBridge` the connect path uses; the endpoint memory makes it
 * idempotent and collapses an edit's several store writes into one push. */
useCamStore.subscribe((state) => {
  const session = state.control.sessionMachine
  if (!session) return
  if (store().connectionPhase !== 'connected') return
  const bridgeKey = connectedBridgeKey
  if (bridgeKey === null || connectedBridgeMachineId !== session.id) return
  const controller = getMachineController()
  if (!supportsSkewApply(controller)) return
  const machine = state.machineLibrary.find((entry) => entry.id === session.id)
    ?? (state.project.machine.id === session.id ? state.project.machine : undefined)
  if (!machine) return
  const sync = skewSyncState(bridgeKey)
  if (skewMatchesHeld(sync, machineSkew(machine)?.offsetMm ?? null)) return
  const isCurrent = () => getMachineController() === controller
    && store().connectionPhase === 'connected'
  void syncSkewToBridge(session.id, controller, isCurrent, bridgeKey)
    .catch((error) => {
      if (!isCurrent()) return
      store().pushConsole(
        'rx',
        `Gantry skew could not be sent: ${error instanceof Error ? error.message : String(error)}`,
        'error',
      )
    })
})

/** WO-1718: the definition is the only source. Every connection is handed the
 * record's VFD link, or told there is none - nothing is read from the bridge. */
async function syncSpindleLinkOnConnect(
  machineId: string,
  target: UccncController,
): Promise<void> {
  const machine = machineRecord(machineId)
  if (!machine) return
  const link = vfdPortLinkState()
  if (link.machineId !== machineId) return
  if (machineSpindleLinkApplyInFlight(machineId)) {
    spindleConsole(
      'Spindle link connect sync skipped - an edit is already waiting for the bridge to confirm.',
      'info',
    )
    return
  }

  const stored = machine.spindleLinkDefinition
  if (stored === null || stored === undefined) {
    // No link in the definition. A bridge that says it holds none has nothing
    // to close; any other is told, and an older bridge that cannot hear it
    // is said once, quietly - it is still running whatever it was started with.
    if (!link.linkPresent) return
    if (link.spindleTurning === true) {
      spindleConsole(
        "Spindle link: this machine's definition has none, but the spindle is turning, so the bridge's link was left open. Stop the spindle and reconnect to close it.",
        'warning',
      )
      return
    }
    const told = clearVfdDefinitionOnBridge(machineId)
    if (told === null) return
    const reply = await told
    spindleConsole(
      reply.ok
        ? "Spindle link: this machine's definition has none, so the bridge closed its link."
        : `Spindle link: this machine's definition has none; the bridge did not confirm closing its own - ${reply.error}.`,
      'info',
    )
    return
  }

  // WO-2009: completed BEFORE the check and stored before it is sent, so the
  // record, the check, the bridge and the receipt all see one definition.
  const completion = completedSpindleLinkDefinition(stored)
  const definition = completion.definition
  if (completion.filledFrom !== null && storeSpindleLinkDefinition(machineId, definition)) {
    spindleConsole(runStateRowsFilledLine(definition, completion.filledFrom), 'info')
  }
  const validation = validateVfdDefinition(definition as unknown as VfdDefinition)
  if (!validation.ok) {
    spindleConsole(
      `Spindle link refused - ${validation.errors.map((fault) => `${fault.path}: ${fault.sentence}`).join(' ')}`,
      'warning',
    )
    return
  }

  // `controller` already names this same instance, but passing the target
  // makes the connect ordering explicit and keeps this helper testable.
  // Connect-time apply is safe after a same-connection stopped sample OR when
  // hello explicitly says there is no link yet. Only this sync path receives
  // the no-link creation exception; accepted UI edits still require stopped.
  setMachineSpindleLinkApplyInFlight(machineId, true)
  spindleConsole('spindle link: waiting for the bridge to confirm the previous change', 'info')
  const sessionRevision = connectionRevision
  const generation = captureBackendGeneration(target)
  const sentSignature = spindleLinkDefinitionSignature(definition)
  try {
    const reply = await target.applyVfdDefinition(definition, { connectTimeSync: true })
    if (!spindleReceiptMatchesSession(
      target, generation, sessionRevision, machineId, definition, sentSignature,
    )) {
      spindleConsole(
        'Spindle link connect receipt ignored - the backend/session or sent definition changed while the bridge was confirming it.',
        'info',
      )
      return
    }
    if (!reply.ok || reply.definition === null) {
      spindleConsole(
        `Spindle link refused - ${reply.error ?? 'the machine bridge did not confirm the definition it now holds'}.`,
        'warning',
      )
      return
    }
    const currentDefinition = machineRecord(machineId)?.spindleLinkDefinition
    if (
      currentDefinition === null
      || currentDefinition === undefined
      || spindleLinkDefinitionSignature(currentDefinition) !== sentSignature
    ) {
      spindleConsole(
        'Spindle link connect receipt ignored - the stored definition changed while the bridge was confirming it.',
        'info',
      )
      return
    }
    const confirmed = machineOwnedVfdReceipt(definition, reply.definition)
    storeSpindleLinkDefinition(machineId, confirmed)
    useCamStore.getState().confirmControlSessionSpindleLinkDefinition(machineId, confirmed)
    publishAppliedVfdDefinition(machineId, confirmed)
    spindleConsole('Spindle link sent - 12 fields, the bridge confirms.', 'info')
  } catch (error) {
    if (!spindleReceiptMatchesSession(
      target, generation, sessionRevision, machineId, definition, sentSignature,
    )) {
      spindleConsole(
        'Spindle link connect receipt ignored - the backend/session or sent definition changed while the bridge was confirming it.',
        'info',
      )
      return
    }
    throw error
  } finally {
    setMachineSpindleLinkApplyInFlight(machineId, false)
  }
}

/**
 * WO-422 / ADR-0041: the backend is chosen HERE, once, and everything above
 * this line talks to the interface.
 *
 *  - `serial`    -> GrblController over WebSerialTransport (a byte pipe).
 *    Must be called from a user gesture (browser Web Serial rule).
 *  - `simulator` -> WO-420/428/434/433: SimulatedController, pure software,
 *    no protocol underneath at all - the native simulator ADR-0041 exists to
 *    deliver. It declares BOTH `gcodeText` and `geometryQueue` true, carries
 *    its own G-code interpreter and MDI-line interpreter (probing, work-offset
 *    writes, TLO, safe-Z park, manual spindle/coolant), the WO-416 virtual
 *    part, and the full contract v3/v4 event set - so it uses
 *    `buildContractEvents()`, the same wiring the bridge uses, not GRBL's.
 *    `SimulatedGrblTransport` (the GRBL-protocol emulator this replaced) is
 *    deleted.
 *    WO-347: the simulator reports the ACTIVE machine profile's travel at
 *    $130/$131/$132, so a simulated connection describes the machine the
 *    operator actually selected instead of a placeholder nobody owns.
 *  - `bridge`    -> UccncController over BridgeTransport (a JSON message
 *    channel to the machine-local bridge driving an AXBB-E / UC100). No user
 *    gesture is needed - there is no browser permission on this path.
 *
 * `baudRate` is a SERIAL concern and is ignored by the other two kinds.
 */
/** WO-2692 follow-up: the simulated setter's top - the reference tool's
 *  measured contact in `table` (the same record the guided change measures
 *  against, `referenceToolMeasuredIn`) when it lies below the stated Z, else
 *  the stated Z. Simulator only; nothing a controller receives reads this. */
export function simulatedToolSetterTopZ(statedZ: number, table: MachineToolTable): number {
  const reference = table.reference === null ? undefined : findTool(table, table.reference)
  const measured = reference?.probedMachineZ
  return typeof measured === 'number' && Number.isFinite(measured) && measured < statedZ ? measured : statedZ
}

async function connectSimulatorRegistryBackend(context: BackendConnectContext): Promise<MachineController> {
  const cam = useCamStore.getState()
  const sessionMachine = context.machine
  // The simulator interprets typed commands and loaded text as the selected
  // machine would. Unknown legacy declarations keep the simulator's historical
  // UCCNC default instead of creating a new refusal at connect time.
  const declaredController = resolveDeclaredController(sessionMachine)
  // WO-2692: the machine's own setter stands on the simulated table, top at
  // its stated Z, so a measure on the simulator touches where it would on the
  // machine. A machine that states no setter gets none.
  // WO-2692 follow-up: a stated setter Z can be the measure's START height
  // (UCCNC FixedProbePos - LienCNC V2 says 120, its setter is touched near
  // 48.3). When this machine's table holds a measured reference tool whose
  // contact lies below the stated Z, the simulated top is that contact, so
  // the simulator touches where the real setter is. Simulator only.
  const setter = fixedToolSetterPosition(sessionMachine)
  const setterTopZ = setter
    ? simulatedToolSetterTopZ(setter.z, useMachineToolTable.getState().tableFor(sessionMachine.id))
    : null
  const simulatorMotion = resolveMachineMotion({
    machine: sessionMachine,
    connectionKind: 'simulator',
    settings: {},
    datumKnown: false,
  })
  const installed = context.install((events) => new SimulatedController(events, {
    dialect: declaredController.ok ? declaredController.dialect : undefined,
    cutTimeMotion: machineCutTimeMotion(sessionMachine),
    controlAxes: enabledControlAxes(sessionMachine.controllerDefinition),
    programHomeRequiredAxes: programHomeRequiredAxes(sessionMachine),
    motion: simulatorMotion,
    outputs: sessionMachine.controllerDefinition?.outputs ?? [],
    macros: { macroMCodeRange: sessionMachine.macroMCodeRange, macros: sessionMachine.macros },
    travelMm: sessionMachine.travel,
    homeConvention: machineHomeConvention(sessionMachine),
    limitWiring: Object.fromEntries((['X', 'Y', 'Z'] as const).map((axis) => {
      const definition = sessionMachine.controllerDefinition?.axes.find(
        (candidate) => candidate.axis === axis && candidate.enabled,
      )
      return [axis, {
        minus: definition ? isPinAssigned(definition.limitMinusPin) : false,
        plus: definition ? isPinAssigned(definition.limitPlusPin) : false,
      }]
    })),
    spindle: {
      minSpindleRpm: sessionMachine.minSpindleRpm,
      maxSpindleRpm: sessionMachine.maxSpindleRpm,
      spindleDirection: sessionMachine.spindleDirection,
      spindleLinkDefinition: sessionMachine.spindleLinkDefinition ?? null,
    },
    workOffsets: Object.fromEntries(WCS_SLOTS.map((wcs) => {
      const stored = cam.machineWorkOffsets[sessionMachine.id]?.[wcs]?.offset
      const fresh = wcs === 'G54' ? defaultSimulatorG54(sessionMachine.id, stored, simulatorMotion.envelope) : null
      return [wcs, fresh ?? stored ?? {}]
    })),
    toolSetter: setter && setterTopZ !== null
      ? { x: setter.x, y: setter.y, topZ: setterTopZ, diameter: SIMULATED_TOOL_SETTER_DIAMETER_MM }
      : null,
  }))
  simulatedController = installed.controller
  await installed.controller.connect({ kind: 'none' })
  if (installed.isCurrent()) runTransferCheck()
  return installed.controller
}

async function connectUccncRegistryBackend(context: BackendConnectContext): Promise<MachineController> {
  const cam = useCamStore.getState()
  const sessionMachine = context.machine
  const machineId = sessionMachine.id
  const datumRevokedAxes = cam.machineDatumRevokedAxes[machineId] ?? []
  const reconnectingThisSession = bridgeConnectedThisSession.has(machineId)
  const url = bridgeUrl(machineBridgePort(machineId))
  simulatedController = null
  let installed: InstalledRegistryBackend<UccncController>
  installed = context.install((events) => new UccncController(events, {
    directionInverted: () => installed?.isCurrent() === true
      && machineRecord(machineId)?.spindleLinkDefinition?.directionInverted === true,
    spindleDrive: () => {
      const current = machineRecord(machineId)
      if (current === null) return undefined
      if (current.spindleDrive !== undefined) return current.spindleDrive
      return current.spindleLinkDefinition != null ? { kind: 'modbus-vfd' } : undefined
    },
    datumRevokedAxes,
  }))
  const uccnc = installed.controller
  const watchSpindleStop = createSpindleStopReasonWatcher(undefined, installed.isCurrent)
  const transport = new BridgeTransport(url, machineId, watchSpindleStop)
  // `install` has just made this backend's scope the active one.
  if (activeBackendScope?.controller === uccnc) tapBridgeOverrideCalls(transport, activeBackendScope)
  await uccnc.connect({ kind: 'messages', transport })
  if (!installed.isCurrent()) return uccnc
  bridgeConnectedThisSession.add(machineId)
  if (reconnectingThisSession && datumRevokedAxes.length > 0) {
    store().pushConsole(
      'rx',
      'Machine datum remains revoked after reconnect - home again in LienCAM before moving.',
      'info',
    )
  }
  await reconcileWorkOffsetsOnConnect(machineId, uccnc)
  if (!installed.isCurrent()) return uccnc
  const scope = activeBackendScope
  if (scope?.controller === uccnc) scope.workOffsetConnectReconcileComplete = true
  await syncSpindleLinkOnConnect(machineId, uccnc)
  if (!installed.isCurrent()) return uccnc
  connectedBridgeKey = url
  connectedBridgeMachineId = machineId
  void syncSkewToBridge(machineId, uccnc, installed.isCurrent, url, true)
    .catch((error) => {
      if (!installed.isCurrent() || uccnc.connectionPhase() !== 'connected') return
      store().pushConsole(
        'rx',
        `Gantry skew could not be sent: ${error instanceof Error ? error.message : String(error)}`,
        'error',
      )
    })
  runTransferCheck()
  return uccnc
}

async function connectGrblRegistryBackend(context: BackendConnectContext): Promise<MachineController | void> {
  simulatedController = null
  const port = await WebSerialTransport.requestPort()
  if (!context.isCurrent()) return
  const transport = new WebSerialTransport(port, context.baudRate)
  let grbl!: GrblController
  const installed = context.install((events) => {
    grbl = new GrblController({
      ...events,
      onStatus: () => events.onStatus?.(grbl.status()),
    })
    return grbl
  })
  await grbl.connect({ kind: 'bytes', transport })
  if (!installed.isCurrent()) return grbl
  void reconcileGrblSettingsOnConnect(context.machine.id, grbl, installed.isCurrent)
    .catch((error) => {
      if (!installed.isCurrent() || grbl.connectionPhase() !== 'connected') return
      store().pushConsole(
        'rx',
        `GRBL settings could not be read: ${error instanceof Error ? error.message : String(error)}`,
        'error',
      )
    })
  runTransferCheck()
  return grbl
}

function attachBuiltInConnector(
  controllerId: string,
  connectionKind: RegistryConnectionKind,
  connect: MachineBackendDefinition['connect'],
  isPhysicalConnection?: MachineBackendDefinition['isPhysicalConnection'],
): void {
  const definition = backendDefinitionFor(controllerId, connectionKind)
  if (!definition) throw new Error(`Missing built-in backend metadata for ${controllerId}/${connectionKind}.`)
  registerMachineBackend({ ...definition, connect, isPhysicalConnection })
}

for (const controllerId of ['uccnc', 'grbl', 'grblhal', 'linuxcnc', 'generic']) {
  attachBuiltInConnector(controllerId, 'simulator', connectSimulatorRegistryBackend)
}
// WO-2066: the bridge is UCCNC's route only (backendRegistry.ts).
attachBuiltInConnector(
  'uccnc',
  'bridge',
  connectUccncRegistryBackend,
  (target) => typeof (target as UccncController).simulatedBoard !== 'function'
    || !(target as UccncController).simulatedBoard(),
)
for (const controllerId of ['grbl', 'grblhal']) {
  attachBuiltInConnector(controllerId, 'serial', connectGrblRegistryBackend)
}
// WO-1987: LinuxCNC's own route (backendRegistry.ts). Its offset registers
// live in LinuxCNC (its var file), so nothing is pushed into them on connect.
attachBuiltInConnector('linuxcnc', 'gateway', async (context) => {
  simulatedController = null
  const linuxcnc = await connectLinuxcncBackend(context)
  if (context.isCurrent()) runTransferCheck()
  return linuxcnc
})

export async function connectMachine(kind: RegistryConnectionKind, baudRate?: number): Promise<void> {
  publishNonProgramActionStatus(null)
  const connectionAttempt = ++connectionAttemptSequence
  // WO-1783: a replacement request is also cancellation of an initial bridge
  // handshake and its pending retry. End that transport before installing the
  // new generation so a stale socket/hello cannot attach to the old machine.
  const previousController = getMachineController()
  if (previousController.connectionPhase() === 'connecting') {
    await previousController.disconnect()
    if (connectionAttempt !== connectionAttemptSequence) return
  }
  let installedGeneration: BackendGenerationToken | null = null
  const continuationIsCurrent = () => connectionAttempt === connectionAttemptSequence
    && (installedGeneration === null || backendGenerationIsCurrent(installedGeneration))
  const cam = useCamStore.getState()
  const machine = controlMachine(cam)
  const definitionProblems = machine.controllerDefinition
    ? validateControllerDefinition(machine.controllerDefinition)
    : []
  if (definitionProblems.length > 0) {
    throw new Error(
      `Cannot connect ${machine.name}: its saved controller definition has `
      + `${definitionProblems.length} problem${definitionProblems.length === 1 ? '' : 's'}. `
      + definitionProblems.join(' '),
    )
  }
  const backendDefinition = backendDefinitionFor(machine.controller, kind)
  if (!backendDefinition?.connect) {
    throw new Error(
      `${String(machine.controller)} has no registered ${kind} connection backend.`,
    )
  }
  const sessionMachine: MachineConfig = {
    ...structuredClone(machine),
    controller: (backendDefinition.sessionController === 'declared'
      ? machine.controller
      : backendDefinition.sessionController) as MachineConfig['controller'],
  }
  cam.setControlSessionMachine(sessionMachine)
  useMachineControl.getState().setConnectionKind(kind as MachineConnectionKind)
  activeBackendDefinition = backendDefinition
  runTransferCheck()
  try {
    await backendDefinition.connect({
      machine: sessionMachine,
      baudRate,
      isCurrent: continuationIsCurrent,
      install: <T extends MachineController>(
        create: (events: ControllerEvents) => T,
      ): InstalledRegistryBackend<T> => {
        const scope = createBackendEventScope()
        const next = create(buildContractEvents(scope))
        installBackend(next, scope)
        installedGeneration = captureBackendGeneration(next)
        return { controller: next, isCurrent: continuationIsCurrent }
      },
    })

  } catch (error) {
    if (!continuationIsCurrent()) return
    useMachineControl.getState().setConnectionKind(null)
    useCamStore.getState().setControlSessionMachine(null)
    simulatedController = null
    activeBackendDefinition = null
    runTransferCheck()
    throw error
  }
}

function offsetAxes(offset: Partial<MachinePosition>): Array<keyof MachinePosition> {
  return (['x', 'y', 'z', 'a', 'b', 'c'] as const)
    .filter((axis) => offset[axis] !== undefined)
}

/** Session offset rows use the canonical X/Y/Z/A/B/C indexes. Rotary holes
 * before a sparse B or C are explicit zeros, never an index shift. */
function machinePositionValues(position: MachinePosition): number[] {
  const values = [position.x, position.y, position.z]
  const rotary = [position.a, position.b, position.c]
  let last = rotary.length - 1
  while (last >= 0 && rotary[last] === undefined) last -= 1
  for (let index = 0; index <= last; index += 1) values.push(rotary[index] ?? 0)
  return values
}

type BridgeWorkOffsetController = WorkOffsetController & BridgeHelloController

function markReportedWorkOffsetAxes(
  wcs: WcsId,
  offset: Partial<MachinePosition>,
  axes = offsetAxes(offset),
): void {
  for (const axis of axes) {
    if (Number.isFinite(offset[axis])) {
      reportedWorkOffsetRevision[wcs][axis.toUpperCase() as ControlAxis] = connectionRevision
    }
  }
  scheduleAwaitedOffsetsCheck()
}

/** Test seam for fixtures that exercise transfer-review recomputation while
 * retaining the simulator controller. Production bridge reports enter through
 * reconcileWorkOffsets(); this seam applies the same per-axis provenance. */
export function __reportWorkOffsetsForTest(
  offsets: Partial<Record<WcsId, MachinePosition>>,
): void {
  if (import.meta.env.MODE !== 'test') {
    throw new Error('__reportWorkOffsetsForTest is available only in tests.')
  }
  for (const [wcs, offset] of Object.entries(offsets) as Array<[WcsId, MachinePosition]>) {
    markReportedWorkOffsetAxes(wcs, offset)
    store().applyOffset({ label: wcs, values: machinePositionValues(offset) })
  }
}

function selectOffsetAxes(
  offset: MachinePosition,
  requested: Partial<MachinePosition>,
): Partial<MachinePosition> {
  const selected: Partial<MachinePosition> = {}
  for (const axis of offsetAxes(requested)) selected[axis] = offset[axis]
  return selected
}

function offsetsEqual(left: Partial<MachinePosition>, right: Partial<MachinePosition>): boolean {
  const axes = offsetAxes(left)
  return axes.length > 0 && axes.every((axis) => left[axis] === right[axis])
}

function offsetIsAllZero(offset: MachinePosition): boolean {
  return offsetAxes(offset).every((axis) => offset[axis] === 0)
}

function describeWorkOffset(offset: Partial<MachinePosition>): string {
  return offsetAxes(offset).map((axis) => `${axis.toUpperCase()}${offset[axis]}`).join(' ')
}

/** ONE restore send. The receipt is the only authority that puts the row back
 *  on the live card; a failure carries its reason so the caller decides whether
 *  to report it now (connect) or to spend another attempt first (reopen). */
async function attemptStoredWorkOffsetSend(
  machineId: string,
  wcs: WcsId,
  stored: StoredMachineWorkOffset,
  target: WorkOffsetController,
  via = '',
): Promise<{ sent: boolean; reason: string | null }> {
  // WO-1330: a restore asks the one question too; the table above
  // `workOffsetWriteRefusal` says why it is answered yes at a hold.
  const axes = offsetAxes(stored.offset).map((axis) => axis.toUpperCase() as ControlAxis)
  if (workOffsetWriteRefusal(wcs, axes, 'restore') !== null) return { sent: false, reason: null }
  storeWorkOffset(machineId, wcs, stored.offset, 'not-sent')
  const receiptToken = captureBackendReceipt(target)
  const receipt = await target.setWorkOffset(wcs, stored.offset)
  if (!receiptIsCurrent(receiptToken)) {
    if (receipt.ok && receipt.offset) clearStaleReportedWorkOffset(machineId, wcs)
    return { sent: false, reason: null }
  }
  if (!receipt.ok || !receipt.offset) {
    return { sent: false, reason: receipt.reason ?? 'the bridge returned no offset receipt' }
  }
  rememberAuthoritativeReportedWorkOffset(machineId, wcs, receipt.offset, receiptToken)
  // The bridge receipt echoes the full WCS. Only the requested axes have
  // provenance from this write; the other axes may be profile-less defaults.
  //
  // `restored`, NEVER `sent`: this software put a remembered number back on a
  // machine nobody re-established it on. WO-1017's switchless work-zero gate is
  // armed only by an operator action in THIS session, so the gate is
  // deliberately not touched here - "Goto work zero" keeps refusing until the
  // operator zeroes or sets the offset at this machine.
  storeWorkOffset(machineId, wcs, selectOffsetAxes(receipt.offset, stored.offset), 'restored')
  // WO-1184: the receipt echoes what the bridge now holds - that is the live
  // value the session table exists to carry.
  markReportedWorkOffsetAxes(wcs, receipt.offset, offsetAxes(stored.offset))
  store().applyOffset({ label: wcs, values: machinePositionValues(receipt.offset) })
  store().pushConsole(
    'rx',
    `Work zero restored from this computer${via}: ${wcs} ${describeWorkOffset(stored.offset)}`
      + ' - not re-established on this machine this session.',
    'info',
  )
  target.refreshState()
  return { sent: true, reason: null }
}

async function sendStoredWorkOffset(
  machineId: string,
  wcs: WcsId,
  stored: StoredMachineWorkOffset,
  target: WorkOffsetController,
  via = '',
): Promise<boolean> {
  const attempt = await attemptStoredWorkOffsetSend(machineId, wcs, stored, target, via)
  if (!attempt.sent && attempt.reason !== null) {
    store().pushConsole(
      'rx',
      `Work zero was not restored: ${wcs} - ${attempt.reason}.`,
      'error',
    )
  }
  return attempt.sent
}

/** WO-1668: sends one reopened-board restore frame gets before it is declared
 *  unrestored. A board that just reopened is still working through the
 *  definition re-application and the queued polls, so its answer lands tens of
 *  seconds after the call - recorded 2026-09-17 (the AXBB-E power cycle):
 *  G54's receipt took 67 s, G55's 53 s, G56's 37 s, all three past the
 *  controller's 8 s operator-gesture budget (`CALL_TIMEOUT_MS`), and the
 *  restore walked on leaving the card blank while the board held every value.
 *  A recovery the app itself started is not an operator gesture; a timed-out
 *  send is sent again (the board applies the same value twice at worst) until
 *  the board's answer lands. The recorded worst frame needed its sixth send
 *  against an exact 8 s budget; eight covers it with margin. */
const REOPEN_RESTORE_SEND_ATTEMPTS = 8

/** WO-1042: reconcile app-owned offsets once, after hello and before connect
 * returns. The profile copy distinguishes a fresh bridge seed from a work zero
 * an operator changed during this bridge session. */
export async function reconcileWorkOffsetsOnConnect(
  machineId: string,
  target: BridgeWorkOffsetController,
): Promise<void> {
  const receiptToken = captureBackendReceipt(target)
  // WO-1042, the one-in-flight rule: the restore takes the SAME slot every
  // operator write takes (as WO-1053's connect sync does), so a reconcile can
  // never race an offset the operator is setting right now. If that write holds
  // the slot the restore skips entirely and says so - it is not queued, and the
  // operator's own value is the newer truth anyway.
  if (machineWorkOffsetWriteInFlight(machineId)) {
    store().pushConsole(
      'rx',
      'Work zero restore skipped - an offset write is already waiting for the bridge to confirm.',
      'info',
    )
    return
  }
  setWorkOffsetWriteInFlight(machineId, true)
  try {
    await reconcileWorkOffsets(machineId, target)
    if (!receiptIsCurrent(receiptToken)) return
  } finally {
    if (receiptIsCurrent(receiptToken)) setWorkOffsetWriteInFlight(machineId, false)
  }
}

/** WO-1331: a bridge reopen is a new physical controller session without a
 * new websocket or Connect boundary. The old session rows therefore stop
 * being controller reports immediately, and every durable frame is written
 * sequentially so each receipt remains the only authority that puts its row
 * back on the live card. This deliberately does not consult the connect hello:
 * that hello described the board before the in-place power-cycle. */
async function restoreWorkOffsetsAfterControllerReopen(
  machineId: string,
  target: WorkOffsetController,
): Promise<void> {
  const storedByWcs = useCamStore.getState().machineWorkOffsets[machineId] ?? {}
  const storedFrames = WCS_SLOTS.flatMap((wcs) => {
    const stored = storedByWcs[wcs]
    return stored && offsetAxes(stored.offset).length > 0 ? [{ wcs, stored }] : []
  })
  if (storedFrames.length === 0) return

  useMachineControl.setState({ offsets: {} })
  // Mark every frame before the first await. A later row must not keep its old
  // wired marker while an earlier row is still waiting for its readback.
  for (const { wcs, stored } of storedFrames) {
    storeWorkOffset(machineId, wcs, stored.offset, 'not-sent')
  }

  const receiptToken = captureBackendReceipt(target)
  setWorkOffsetWriteInFlight(machineId, true)
  try {
    for (const { wcs, stored } of storedFrames) {
      // WO-1668: the reopened board answers late, not never - see
      // REOPEN_RESTORE_SEND_ATTEMPTS. The unrestored line prints only after
      // the budget is exhausted, never per attempt.
      let sent = false
      let reason: string | null = null
      for (let attempt = 0; attempt < REOPEN_RESTORE_SEND_ATTEMPTS && !sent; attempt += 1) {
        const result = await attemptStoredWorkOffsetSend(machineId, wcs, stored, target)
        sent = result.sent
        reason = result.reason
        if (!receiptIsCurrent(receiptToken)) return
      }
      if (!sent && reason !== null) {
        store().pushConsole(
          'rx',
          `Work zero was not restored: ${wcs} - ${reason}.`,
          'error',
        )
      }
      if (!receiptIsCurrent(receiptToken)) return
    }
  } finally {
    if (receiptIsCurrent(receiptToken)) setWorkOffsetWriteInFlight(machineId, false)
  }
}

async function reconcileWorkOffsets(
  machineId: string,
  target: BridgeWorkOffsetController,
): Promise<void> {
  const receiptToken = captureBackendReceipt(target)
  const storedByWcs = useCamStore.getState().machineWorkOffsets[machineId] ?? {}
  // WO-1042: `hello.workOffsets` is read ONCE, HERE, and only as the connect
  // discriminator. It never becomes a durable value by itself - see the write
  // table above `storeWorkOffset`.
  const statedOffsets = target.bridgeHello()?.workOffsets
  const recordUnknown = (wcs: WcsId, why: string) => {
    storeWorkOffset(machineId, wcs, {}, 'unknown')
    store().pushConsole(
      'rx',
      `${why} and this software has no stored zero for ${wcs} - set or zero the axis before cutting.`,
      'info',
    )
  }
  const publishCurrent = (wcs: WcsId, current: MachinePosition) => {
    markReportedWorkOffsetAxes(wcs, current)
    store().applyOffset({ label: wcs, values: machinePositionValues(current) })
  }
  // WO-1182: when the bridge holds a different number from ours, ours is
  // pushed (ADR-0044: this software's store is the truth after import) and
  // the console says what was replaced. A difference is information, not a
  // hazard, and Operator's ruling is that a value on screen is obeyed, not judged.
  const pushOurs = async (wcs: WcsId, stored: StoredMachineWorkOffset, current: MachinePosition) => {
    store().pushConsole(
      'rx',
      `${wcs} on the bridge was ${describeWorkOffset(current)}; sending this software's ${describeWorkOffset(stored.offset)}.`,
      'info',
    )
    await sendStoredWorkOffset(machineId, wcs, stored, target)
  }

  // An older hello has no current/profile discriminator. It can receive a
  // stored value, but it cannot supply one that this app may adopt as truth.
  if (!statedOffsets) {
    for (const wcs of WCS_SLOTS) {
      const stored = storedByWcs[wcs]
      if (stored && offsetAxes(stored.offset).length > 0) {
        await sendStoredWorkOffset(machineId, wcs, stored, target, ' through an older bridge')
        if (!receiptIsCurrent(receiptToken)) return
        continue
      }
      recordUnknown(wcs, 'This bridge is too old to say what work zeros it holds')
    }
    return
  }

  // A bridge started without --profile reports default-constructed zeros. They
  // are not evidence of a real work zero and must never enter the durable store
  // as a value a later connection could restore over the machine's profile.
  if (statedOffsets.profile === null) {
    for (const wcs of WCS_SLOTS) {
      const stored = storedByWcs[wcs]
      if (!stored || offsetAxes(stored.offset).length === 0) {
        recordUnknown(wcs, 'The bridge has no profile')
        const current = statedOffsets.current[wcs]
        // ZERO IS A WORK ZERO. The bridge reported this row, so every finite
        // axis is live even when there is no durable value to restore.
        if (current) publishCurrent(wcs, current)
        continue
      }
      // A hello that omits a slot says nothing about it; it is not a default.
      const current = statedOffsets.current[wcs]
      if (!current) continue
      if (offsetIsAllZero(current)) {
        await sendStoredWorkOffset(machineId, wcs, stored, target, ' through a profile-less bridge')
        if (!receiptIsCurrent(receiptToken)) return
        continue
      }
      await pushOurs(wcs, stored, current)
      if (!receiptIsCurrent(receiptToken)) return
    }
    return
  }

  const profileOffsets = statedOffsets.profile

  for (const wcs of WCS_SLOTS) {
    const current = statedOffsets.current[wcs]
    const profile = profileOffsets[wcs]
    if (!current) continue
    if (!profile) {
      publishCurrent(wcs, current)
      continue
    }
    const stored = storedByWcs[wcs]
    if (!stored || offsetAxes(stored.offset).length === 0) {
      if (offsetsEqual(current, profile)) {
        storeWorkOffset(machineId, wcs, current, 'adopted-from-profile')
        store().pushConsole('rx', `Work zero adopted from profile: ${wcs} ${describeWorkOffset(current)}.`, 'info')
      } else {
        // WO-1182: the controller has a value and this software has none -
        // use the controller's own value (Operator: "either load them because the
        // controller is already up... or put in the console").
        storeWorkOffset(machineId, wcs, current, 'restored')
        store().pushConsole('rx', `Work zero taken from the bridge: ${wcs} ${describeWorkOffset(current)}.`, 'info')
      }
      publishCurrent(wcs, current)
      continue
    }
    if (offsetsEqual(stored.offset, current)) {
      // Nothing is written and nothing is sent: the bridge already holds our
      // numbers. The badge becomes `restored` because "not yet sent" would be
      // false about a value the bridge demonstrably holds - and `restored`, like
      // a push, does not arm WO-1017's gate.
      storeWorkOffset(machineId, wcs, stored.offset, 'restored')
      store().pushConsole('rx', `Work zero agrees: ${wcs} ${describeWorkOffset(stored.offset)}.`, 'info')
      publishCurrent(wcs, current)
      continue
    }
    if (offsetsEqual(current, profile)) {
      await sendStoredWorkOffset(machineId, wcs, stored, target)
      if (!receiptIsCurrent(receiptToken)) return
      continue
    }
    await pushOurs(wcs, stored, current)
    if (!receiptIsCurrent(receiptToken)) return
  }
}

export async function disconnectMachine(): Promise<void> {
  connectionAttemptSequence++
  const target = getMachineController()
  const generation = captureBackendGeneration(target)
  try {
    await target.disconnect()
  } finally {
    if (backendGenerationIsCurrent(generation)) {
      useMachineControl.getState().setConnectionKind(null)
      useCamStore.getState().setControlSessionMachine(null)
      simulatedController = null
      activeBackendDefinition = null
      // WO-1556: no live session, no endpoint for a skew edit to reach. The
      // endpoint memory itself survives, because the bridge process does.
      connectedBridgeKey = null
      connectedBridgeMachineId = null
      // WO-1330: no connection, no hold. A hold that survived a disconnect
      // would leave the panels lending jog to a program that no longer exists.
      endToolChangeSequence()
      activeToolLengthDatumValue = null
      runTransferCheck()
    }
  }
}

/**
 * Change the Control machine through the same session boundary as an explicit
 * disconnect. Selection itself never connects or applies a definition.
 *
 * The request sequence is deliberately separate from the backend generation:
 * rapid B then C choices share any disconnect already in flight, but only C
 * may publish after it. The disconnect boundary remains the sole owner of
 * macro/question cancellation, job teardown, receipt invalidation and stale
 * socket/hello rejection.
 *
 * WO-2015 (Operator's 09-25 session): a record on the same controller and the same
 * bridge endpoint as the live link - whatever its record id - needs no new
 * connection, so the link and the loaded program stay and only the operator's
 * choice moves. The session keeps the definition it connected with; saved
 * edits still reach it only through a controller receipt, and a record with
 * another id takes over Control at the next connect. Every other switch goes
 * through the disconnect boundary exactly as before.
 */
export async function selectControlMachine(nextId: string | null): Promise<boolean> {
  const request = ++controlMachineSelectionSequence
  const before = useCamStore.getState()
  const currentSelection = controlMachineSelection(before)
  const currentId = currentSelection.mode === 'explicit' ? currentSelection.machine.id : null

  // Choosing the displayed row is a no-op, but it still supersedes an older
  // pending choice. This lets A -> B -> A cancel B without a late await
  // changing the selector after the operator returned it to A. On a live link
  // it also withdraws a same-endpoint choice still waiting for the next connect.
  if (nextId === currentId) {
    if (currentSelection.pinned && before.control.activeMachineId !== nextId) {
      useCamStore.setState((state) => ({
        control: { ...state.control, activeMachineId: nextId },
      }))
    }
    return true
  }
  const requestedMachine = nextId === null
    ? currentSelection.camMachine
    : before.machineLibrary.find((machine) => machine.id === nextId)
  if (!requestedMachine) return false

  if (
    currentSelection.pinned
    && controlMachineSelectionDisconnect === null
    && getMachineController().connectionPhase() === 'connected'
    && switchKeepsBridgeLink(requestedMachine)
  ) {
    const sameRecord = requestedMachine.id === currentSelection.machine.id
    useCamStore.setState((state) => ({
      control: sameRecord
        ? { ...state.control, activeMachineId: nextId, sessionActiveMachineId: nextId }
        : { ...state.control, activeMachineId: nextId },
    }))
    store().pushConsole(
      'tx',
      sameRecord
        ? `Control switched to ${nextId === null ? 'the CAM setup copy' : 'the library copy'} of `
          + `${requestedMachine.name} - same machine and controller, so the connection and `
          + 'the loaded program stay.'
        : `${requestedMachine.name} uses the same controller on the same port, so the connection `
          + `and the loaded program stay. Control keeps ${currentSelection.machine.name}'s settings `
          + `until you disconnect; ${requestedMachine.name} takes over at the next connect.`,
      'info',
    )
    return true
  }

  try {
    if (getMachineController().connectionPhase() !== 'disconnected') {
      const pending = controlMachineSelectionDisconnect ?? disconnectMachine()
      controlMachineSelectionDisconnect = pending
      try {
        await pending
      } finally {
        if (controlMachineSelectionDisconnect === pending) {
          controlMachineSelectionDisconnect = null
        }
      }
    }
  } catch (error) {
    if (request === controlMachineSelectionSequence) {
      const observed = controlMachineSelection(useCamStore.getState()).machine
      const phase = getMachineController().connectionPhase()
      store().pushConsole(
        'tx',
        `Machine switch to ${requestedMachine.name} did not complete: disconnect failed - `
          + `${error instanceof Error ? error.message : String(error)}. `
          + `Control remains on ${observed.name}; connection is ${phase}.`,
        'error',
      )
    }
    return false
  }

  if (request !== controlMachineSelectionSequence) return false
  const state = useCamStore.getState()
  state.setControlMachineId(nextId)
  return useCamStore.getState().control.activeMachineId === nextId
}

/** The live link is a bridge link, the requested record's controller resolves
 *  to the same registered backend, and the record would dial the same bridge
 *  endpoint (its saved port, or the default when none is saved). */
function switchKeepsBridgeLink(requested: MachineConfig): boolean {
  if (store().connectionKind !== 'bridge') return false
  if (connectedBridgeKey === null || activeBackendDefinition === null) return false
  if (backendDefinitionFor(requested.controller, 'bridge') !== activeBackendDefinition) return false
  return configuredBridgeUrl(requested.id) === connectedBridgeKey
}

/** The bridge URL a record would dial, read without `machineBridgePort`'s
 *  connect-boundary side effect. An invalid saved port matches nothing, so
 *  that record goes the disconnect way and meets the connect refusal later. */
function configuredBridgeUrl(machineId: string): string | null {
  const configured = useUiPrefs.getState().machineLinks[machineId]?.bridgePort
  if (configured === undefined) return bridgeUrl()
  if (!Number.isInteger(configured) || configured < 1 || configured > 65535) return null
  return bridgeUrl(configured)
}

// ---------------------------------------------------------------------------
// WO-1065 - SAYING SO WHEN THE CAM SETUP MOVES UNDER A LIVE SESSION
// ---------------------------------------------------------------------------
//
// A connection PINS the machine identity, so with Follow CAM selected the
// operator can change the CAM setup's machine and every Control reader
// correctly stays where the session is. Correct and, until this subscription,
// completely silent: the Setup screen said one machine, Control drove another,
// and nothing anywhere said why.
//
// ONE PLACE, ONE LINE. `camMovedTo` is a fact the resolver's own view already
// computes, so this cannot disagree with the dropdown's pinned text; the id
// latch makes it a line per transition rather than per store write (the store
// publishes on every jog, every DRO tick). A second move while still pinned
// names the new machine; releasing the pin resets the latch silently, because
// disconnecting has already put Control back on CAM and the header says so.
let camMovedNoticeMachineId: string | null = null
let transferObservedControlMachine = controlMachine(useCamStore.getState())

useCamStore.subscribe((state) => {
  const { machine, camMovedTo } = controlMachineSelection(state)
  if (machine !== transferObservedControlMachine) {
    transferObservedControlMachine = machine
    runTransferCheck()
  }
  if (camMovedTo === null) {
    camMovedNoticeMachineId = null
    return
  }
  if (camMovedNoticeMachineId === camMovedTo.id) return
  camMovedNoticeMachineId = camMovedTo.id
  store().pushConsole(
    'rx',
    `Control stays on ${machine.name} until you disconnect - `
      + `the CAM setup moved to ${camMovedTo.name}.`,
    'warn',
  )
})

/** Tests reset the store between cases; the latch is module state and would
 *  otherwise swallow the first notice of the next case. */
export function __resetCamMovedNoticeForTest(): void {
  camMovedNoticeMachineId = null
}

/** Test isolation only: the WO-1554 session latch is module state, so tests
 *  that each start from "nothing has connected yet" must clear it. */
export function __resetBridgeConnectedThisSessionForTest(): void {
  if (import.meta.env.MODE !== 'test') {
    throw new Error('__resetBridgeConnectedThisSessionForTest is available only in tests.')
  }
  bridgeConnectedThisSession.clear()
}

/** Test isolation only: the WO-1556 endpoint memory is module state, so tests
 *  that each start from "no bridge has confirmed anything" must clear it. */
export function __resetSkewSyncForTest(): void {
  if (import.meta.env.MODE !== 'test') {
    throw new Error('__resetSkewSyncForTest is available only in tests.')
  }
  skewSyncByBridge.clear()
  connectedBridgeKey = null
  connectedBridgeMachineId = null
}

// ---------------------------------------------------------------------------
// WO-928 - APPLY SENDS THE DEFINITION THE MACHINE ACTUALLY USES
// ---------------------------------------------------------------------------
//
// F16 was that `applyMachineDefinition` is fully implemented on this
// controller and on the bridge, rc-checked with a 23-field readback, and
// NOTHING in `src/` called it. There was no Apply.
//
// F17 is why it could not simply be called with whatever the editor happened
// to hold. CAM's `project.machine` may now differ deliberately; the Control
// selector is what `JogPanel` and Apply both read. Sending the editor draft
// while those readers resolve another record is this project's house failure
// mode - silent, self-consistent and wrong.
//
// THE RECONCILIATION IS A RULE, NOT A COMPARISON:
//
//   APPLY READS WHERE HOMING READS. `activeMachineDefinition()` below and
//   `JogPanel` both resolve through `controlMachine`. Apply never reads a
//   different active record, so there is nothing to drift or compare.
//
// The other half of the rule lives in `MachineLibraryModal.commitDraft`, which
// writes THROUGH to `project.machine` when the entry being saved IS the active
// machine. Save therefore cannot leave the copy the app homes with stale, and
// the case that cannot be reconciled - editing a machine that is NOT the
// active one - is REFUSED by name rather than resolved by guessing.

/**
 * The controller definition the app itself uses: the one `JogPanel` reads for
 * the homing order, and the one Apply sends. One expression, one reader.
 *
 * `JogPanel.tsx` still inlines the same expression (WO-927 owns that file);
 * pointing it at this accessor is a one-line follow-up, not a behaviour
 * change - the expression is identical today and the WO-928 test asserts the
 * two are the SAME OBJECT.
 */
export function activeMachineDefinition(): ControllerDefinition | null {
  return controlMachine(useCamStore.getState()).controllerDefinition ?? null
}

/**
 * Q3 IS CLOSED AND THIS SENTENCE IS PERMANENT - IT IS NOT A LEFTOVER CAVEAT.
 *
 * Operator ruled "not worth the risk - ship it as is" on testing whether the
 * controller USES a pin changed on a live connection. The bridge's readback
 * proves the value was STORED, never that it is in use. Nothing in this
 * product may say a live pin change takes effect. A later reader must not
 * tidy this away as uncertainty that was since resolved: it was not resolved,
 * it was CLOSED.
 */
export const APPLY_PIN_HEDGE =
  'Pin assignments were STORED. Whether the controller uses a pin changed on a '
  + 'live connection is not demonstrated - to check one, jog that axis and watch '
  + 'which axis moves.'

interface ApplyActiveDefinitionOutcome {
  /** True only when the controller answered, every value read back, and the
   * matched receipt promoted the definition into current runtime authority. */
  ok: boolean
  /**
   * The saved-intent definition object handed to the controller. It becomes
   * runtime authority only after the matched successful receipt; the store
   * isolates that confirmed runtime value from later saved edits with a clone.
   * Null when nothing was sent.
   */
  sent: ControllerDefinition | null
  /** Why nothing was sent. Null whenever a call was actually made. */
  refusal: string | null
  /** The controller's own reply, verbatim, line-by-line report included.
   *  Null when nothing was sent. */
  result: ApplyDefinitionResult | null
  /** A controller may answer after its backend/session was replaced. Such a
   * receipt is reported but never allowed to rewrite the replacement session. */
  authorityRefusal?: string | null
}

type DriftValue = boolean | number | string | null | PinRef

/**
 * The imported profile is a one-time seed, while `ControllerDefinition` is the
 * editable live document. Keep the small bridge-facing projection of that seed
 * on one of the definition's existing stated-key provenance records so Save
 * cannot replace the only baseline we have. A fresh profile import replaces
 * `stated` wholesale and therefore cannot inherit an older profile's baseline.
 *
 * This is metadata on a provenance record, not another controller setting. The
 * bridge ignores `stated`, the exporter walks the catalogue rather than these
 * object properties, and JSON persistence retains it across app restarts.
 */
const PROFILE_DRIFT_VALUES = 'liencamProfileDriftValues'
/** The provenance counterpart of `PROFILE_DRIFT_VALUES`, keyed the same way
 * `uccncProfileImport.ts` reads it back for the profile-import preview
 * (`liencamProfileDriftProvenance`) - one persisted record, two readers. */
const PROFILE_DRIFT_PROVENANCE = 'liencamProfileDriftProvenance'
/** The raw drift values as of the LAST successful apply - distinct from
 * `PROFILE_DRIFT_VALUES`, which is the one-time profile-import seed and never
 * moves. A Save without an Apply can rewrite `profile`'s own raw values (the
 * commit path below persists the draft unconditionally), so comparing a new
 * Apply against `profile` reads an edited-then-saved value as "unchanged" and
 * restates the value it REPLACED. Comparing against this last-applied record
 * instead means only what the controller actually last received counts as
 * the baseline for "did this apply change anything". */
const PROFILE_LAST_APPLIED_VALUES = 'liencamLastAppliedDriftValues'
type ProfileDriftCarrier = {
  [PROFILE_DRIFT_VALUES]?: Record<string, DriftValue>
  [PROFILE_DRIFT_PROVENANCE]?: MachineDefinitionProvenance
  [PROFILE_LAST_APPLIED_VALUES]?: Record<string, DriftValue>
}

/** The bridge's exact WO-1048 drift vocabulary, projected from the definition
 * it will receive. Keep this list value-shaped rather than profile-key-shaped:
 * composite pins are one bridge key, and a homing block contributes keys only
 * when that axis actually carries one. The WO-1073 test derives the other side
 * from Machine.cs so a spelling change cannot pass silently. */
function machineDefinitionDriftValues(
  definition: ControllerDefinition,
): Map<string, DriftValue> {
  const values = new Map<string, DriftValue>()
  for (const axis of definition.axes) {
    const root = `axes.${axis.axis}.`
    values.set(`${root}enabled`, axis.enabled)
    values.set(`${root}stepsPerUnit`, axis.stepsPerUnit)
    values.set(`${root}maxVelocity`, axis.maxVelocity)
    values.set(`${root}acceleration`, axis.acceleration)
    values.set(`${root}softLimitMin`, axis.softLimitMin)
    values.set(`${root}softLimitMax`, axis.softLimitMax)
    values.set(`${root}enableDelayMs`, axis.enableDelayMs)
    values.set(`${root}backlash.enabled`, axis.backlash.enabled)
    values.set(`${root}backlash.distance`, axis.backlash.distance)
    values.set(`${root}slaveAxis`, axis.slaveAxis)
    values.set(`${root}stepPin`, axis.stepPin)
    values.set(`${root}dirPin`, axis.dirPin)
    values.set(`${root}homePin`, axis.homePin)
    values.set(`${root}limitMinusPin`, axis.limitMinusPin)
    values.set(`${root}limitPlusPin`, axis.limitPlusPin)
    values.set(`${root}enablePin`, axis.enablePin)
    const homing = definition.homing.perAxis[axis.axis]
    if (homing) {
      values.set(`${root}homing.direction`, homing.direction)
      values.set(`${root}homing.fastSpeed`, homing.fastSpeed)
      values.set(`${root}homing.slowSpeed`, homing.slowSpeed)
      values.set(`${root}homing.backOff`, homing.backOff)
      values.set(`${root}homing.homingValue`, homing.homingValue)
    }
  }
  values.set('io.estop', definition.io.estop)
  values.set('io.probe', definition.io.probe)
  values.set('io.probe2', definition.io.probe2)
  return values
}

function storedProfileDriftValues(
  definition: ControllerDefinition | null | undefined,
): Map<string, DriftValue> | null {
  if (!definition) return null
  for (const stated of definition.stated ?? []) {
    const stored = (stated as typeof stated & ProfileDriftCarrier)[PROFILE_DRIFT_VALUES]
    if (stored && typeof stored === 'object' && !Array.isArray(stored)) {
      return new Map(Object.entries(stored))
    }
  }
  return null
}

/** The provenance this app has already declared for each drifted key, as of
 * the last successful apply - read back so a later apply can restate it
 * verbatim instead of minting a new stamp for a value nobody just changed. */
function storedProfileDriftProvenance(
  definition: ControllerDefinition | null | undefined,
): MachineDefinitionProvenance | null {
  if (!definition) return null
  for (const stated of definition.stated ?? []) {
    const stored = (stated as typeof stated & ProfileDriftCarrier)[PROFILE_DRIFT_PROVENANCE]
    if (stored && typeof stored === 'object' && !Array.isArray(stored)) return stored
  }
  return null
}

/** The raw drift values as of the last successful apply. See
 * `PROFILE_LAST_APPLIED_VALUES` for why this, not `profile`'s own current
 * values, is the baseline a new apply's provenance decision compares against. */
function storedLastAppliedDriftValues(
  definition: ControllerDefinition | null | undefined,
): Map<string, DriftValue> | null {
  if (!definition) return null
  for (const stated of definition.stated ?? []) {
    const stored = (stated as typeof stated & ProfileDriftCarrier)[PROFILE_LAST_APPLIED_VALUES]
    if (stored && typeof stored === 'object' && !Array.isArray(stored)) {
      return new Map(Object.entries(stored))
    }
  }
  return null
}

/** Persist exactly the provenance map and raw values a successful apply just
 * sent, so the NEXT apply's `machineDefinitionApplyProvenance` can restate an
 * unchanged key's existing stamp instead of overwriting it with today's date.
 * Bridge `SaveDefinitionCache` (Machine.cs) rewrites its whole `provenance`
 * document from whatever this app sends, verbatim and with no per-key merge
 * of its own - the app is the only place this history can live. */
function withMachineDefinitionDriftProvenance(
  definition: ControllerDefinition,
  provenance: MachineDefinitionProvenance,
  lastApplied: Record<string, DriftValue>,
): ControllerDefinition {
  const stated = definition.stated ?? []
  if (stated.length === 0) return definition
  const carrier = {
    ...stated[0],
    [PROFILE_DRIFT_PROVENANCE]: provenance,
    [PROFILE_LAST_APPLIED_VALUES]: lastApplied,
  } as typeof stated[number] & ProfileDriftCarrier
  return {
    ...definition,
    stated: [carrier, ...stated.slice(1)],
  }
}

/** Persist the first profile-stated drift projection exactly once. The draft
 * may already carry it from an earlier Save; in that case its original values
 * win even when `profile` is now the edited saved record. */
export function withMachineDefinitionProfileBaseline(
  profile: ControllerDefinition | null | undefined,
  definition: ControllerDefinition | null | undefined,
): ControllerDefinition | undefined {
  if (!definition) return undefined
  if (!profile || storedProfileDriftValues(definition)) return definition
  const stated = definition.stated ?? []
  if (stated.length === 0) return definition
  const baseline = storedProfileDriftValues(profile) ?? machineDefinitionDriftValues(profile)
  const carrier = {
    ...stated[0],
    [PROFILE_DRIFT_VALUES]: Object.fromEntries(baseline),
  } as typeof stated[number] & ProfileDriftCarrier
  return {
    ...definition,
    stated: [carrier, ...stated.slice(1)],
  }
}

export function machineDefinitionDriftKeys(definition: ControllerDefinition): string[] {
  return [...machineDefinitionDriftValues(definition).keys()]
}

function sameDriftValue(a: DriftValue, b: DriftValue): boolean {
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return Object.is(a, b)
  }
  // Pins are compared as one bridge value. Match Machine.cs's normalisation:
  // every unassigned triple is the same 0/0/not-negated physical input.
  const pin = (value: PinRef): PinRef => value.pin <= 0
    ? { port: 0, pin: 0, negate: false }
    : value
  const left = pin(a)
  const right = pin(b)
  return left.port === right.port && left.pin === right.pin && left.negate === right.negate
}

/** Declare every sent value that differs from the imported profile seed on
 * every Apply. The persisted projection wins over the mutable saved document,
 * so a clean second Apply cannot erase provenance established by the first.
 * A newly sent key absent from the profile projection is also a difference:
 * the bridge checks that key and needs the app to account for its appearance.
 *
 * WO-1558: "differs from the profile seed" only says a key NEEDS a stamp -
 * it does not say THIS apply is the one that earned it. A key that was ALSO
 * already this exact value as of the LAST successful apply (never `profile`'s
 * own raw value, which a Save can rewrite without ever reaching the
 * controller - see `PROFILE_LAST_APPLIED_VALUES`) restates whatever
 * provenance this app already recorded for it, verbatim. Only a key whose
 * number differs from what was last actually applied, or one this app has
 * never declared before, gets today's stamp. */
export function machineDefinitionApplyProvenance(
  profile: ControllerDefinition | null | undefined,
  sent: ControllerDefinition | null | undefined,
  machineName: string,
  at: Date = new Date(),
): MachineDefinitionProvenance {
  if (!profile || !sent) return {}
  const before = storedProfileDriftValues(sent)
    ?? storedProfileDriftValues(profile)
    ?? machineDefinitionDriftValues(profile)
  const after = machineDefinitionDriftValues(sent)
  const changed = [...after].filter(([key, value]) => {
    const profileValue = before.get(key)
    return !before.has(key) || !sameDriftValue(profileValue as DriftValue, value)
  })
  if (changed.length === 0) return {}
  const lastApplied = storedLastAppliedDriftValues(sent) ?? storedLastAppliedDriftValues(profile)
  const existingProvenance = storedProfileDriftProvenance(sent)
    ?? storedProfileDriftProvenance(profile)
    ?? {}
  const source = `${machineName} - LienCAM definition editor - ${at.toLocaleString()}`
  const result: MachineDefinitionProvenance = {}
  for (const [key, value] of changed) {
    const alreadyDeclared = lastApplied?.has(key)
      && sameDriftValue(lastApplied.get(key) as DriftValue, value)
      && existingProvenance[key]
    result[key] = alreadyDeclared || { kind: 'liencam-ui', source }
  }
  return result
}

function applyRefused(reason: string): ApplyActiveDefinitionOutcome {
  return { ok: false, sent: null, refusal: reason, result: null, authorityRefusal: null }
}

/** Receipt correlation uses the exact serialized definition that was sent.
 * Capturing this before the await also catches an illicit in-place mutation. */
function machineDefinitionSignature(definition: ControllerDefinition): string {
  return JSON.stringify(definition)
}

/**
 * Send the ACTIVE machine's definition to the connected controller.
 *
 * Refuses honestly, by name, rather than picking a definition:
 *  - no active definition at all,
 *  - not connected,
 *  - a backend that cannot write settings (the simulator, GRBL).
 *
 * NO GATE MAY EVER BLOCK A STOP: this awaits a reply, holds no lock, disables
 * no control, and sits between the operator and nothing. An E-STOP pressed
 * while an apply is in flight takes its own path exactly as it would with no
 * apply running.
 *
 * NO OPTIMISTIC STATE: nothing here writes success anywhere before the reply
 * arrives, and the caller has no result to render until this promise settles.
 */
export async function applyConnectedMachineDefinition(
  definition: ControllerDefinition,
  provenance: MachineDefinitionProvenance = {},
  machineId = controlMachine(useCamStore.getState()).id,
): Promise<ApplyActiveDefinitionOutcome> {
  if (store().connectionPhase !== 'connected') {
    return applyRefused(
      'Nothing was sent: the machine is not connected. Connect to the machine '
      + 'bridge on the Control page first.',
    )
  }
  const controller = getMachineController()
  const receiptToken = captureBackendReceipt(controller)
  if (typeof controller.applyMachineDefinition !== 'function') {
    return applyRefused(
      'Nothing was sent: this connection cannot write settings to a controller. '
      + 'Only the machine bridge can.',
    )
  }

  const sessionRevision = connectionRevision
  const sessionAtSend = useCamStore.getState().control.sessionMachine
  if (!sessionAtSend || sessionAtSend.id !== machineId) {
    return applyRefused(
      'Nothing was sent: this definition does not belong to the connected machine session.',
    )
  }

  // Build receipt-owned metadata BEFORE recording the wire frame, but do not
  // persist it anywhere until a matched successful receipt arrives. The bridge
  // ignores this metadata and receives provenance separately; including it in
  // the immutable sent document means runtime authority can adopt the exact
  // document the controller acknowledged instead of a post-send mutation of
  // it. App-owned stated facts made this path reachable for fresh definitions
  // as well as imported profiles (WO-1731).
  const machineAtSend = machineRecord(machineId)
  const lastApplied = Object.fromEntries(machineDefinitionDriftValues(definition))
  const stampedProvenance = Object.keys(provenance).length > 0
    ? provenance
    : storedProfileDriftProvenance(definition)
      ?? storedProfileDriftProvenance(machineAtSend?.controllerDefinition)
      ?? {}
  const sentDefinition = withMachineDefinitionDriftProvenance(
    definition, stampedProvenance, lastApplied,
  )
  const sentSignature = machineDefinitionSignature(sentDefinition)

  const result = await controller.applyMachineDefinition(sentDefinition, provenance)
  if (!receiptIsCurrent(receiptToken)) {
    return {
      ok: false,
      sent: sentDefinition,
      refusal: null,
      result,
      authorityRefusal: 'The controller receipt belongs to a replaced backend/session.',
    }
  }
  const current = useCamStore.getState()
  const receiptMatchesSession = controller === getMachineController()
    && connectionRevision === sessionRevision
    && store().connectionPhase === 'connected'
    && current.control.sessionMachine?.id === machineId
    && machineDefinitionSignature(sentDefinition) === sentSignature

  // SAFETY. The backend drops its OWN `homedThisSession` whenever the apply
  // failed or named axes to re-home, because steps/unit, soft limits, homing
  // direction/value and any axis pin change alter WHAT THE POSITION COUNTER
  // MEANS. The store's copy is what the UI reads, and leaving it `true` beside
  // a controller that says otherwise is the same silent-wrong this order
  // exists to remove.
  if (receiptMatchesSession && (!result.ok || result.reHome.length > 0)) store().setHomed(false)

  // WO-1558: Machine.cs's `SaveDefinitionCache` rebuilds its cached
  // `provenance` document from exactly what this apply sent, with no per-key
  // merge of its own - so if this app does not keep its own record of an
  // established stamp, no later apply can restate it and the bridge cache is
  // the only place it ever lived. An apply that declared nothing (`{}`, e.g.
  // a raw profile-import apply, or one where every drifted key landed back on
  // its profile-seed value) leaves the PROVENANCE map alone; it is not this
  // apply's place to erase established authorship it was never told to touch.
  //
  // The RAW last-applied values move on EVERY matched successful apply
  // regardless, declaring or not: `machineDefinitionApplyProvenance`'s NEXT
  // decision compares against them, and leaving them stale after a real apply
  // that sent a different number (e.g. a revert to the seed) makes a LATER
  // apply that returns to the old number read as "already declared" and
  // restate a stamp naming the wrong edit - review FAIL, 2026-09-15.
  //
  // `confirmControlSessionDefinition` below is handed this SAME merged
  // definition, carrier included: it clones its argument straight into
  // `appliedMachine`, which is what the definition panel's authority and
  // Apply-button surfaces compare against the saved library record. Confirming
  // with the pre-persist `definition` leaves `appliedMachine` one carrier
  // behind the record `updateMachineInLibrary`/`setProjectMachine` just wrote,
  // so those surfaces read a false mismatch right after a successful, matched
  // Apply.
  let confirmedDefinition = sentDefinition
  if (receiptMatchesSession && result.ok) {
    const machine = machineRecord(machineId)
    if (machine) {
      // WO-1558 audit: `machine` may be `machineRecord()`'s FALLBACK (the
      // connect-time `controlMachine` snapshot) rather than a library entry -
      // reachable whenever the machine being edited is not (or no longer) in
      // `machineLibrary`. That fallback's `controllerDefinition` is NOT
      // necessarily what was just sent. The carrier is stamped onto the SENT
      // `definition` itself, never onto `machine.controllerDefinition`, so
      // `next.controllerDefinition` - and therefore `confirmedDefinition`,
      // which becomes runtime authority below - can never diverge from what
      // the controller actually received and acknowledged.
      const next = {
        ...machine,
        controllerDefinition: sentDefinition,
      }
      current.updateMachineInLibrary(machineId, next)
      if (current.project.machine.id === machineId) current.setProjectMachine(next)
      confirmedDefinition = next.controllerDefinition
    }
  }

  let authorityRefusal: string | null = null
  if (result.ok) {
    if (!result.configuredThisSession) {
      authorityRefusal = 'The controller readback said success but did not confirm this session as configured.'
    } else if (!receiptMatchesSession) {
      authorityRefusal = 'The controller confirmed the definition, but its receipt belongs to a replaced '
        + 'backend/session or a changed definition. Runtime authority was not changed.'
    } else if (!current.confirmControlSessionDefinition(machineId, confirmedDefinition)) {
      authorityRefusal = 'The controller confirmed the definition, but the connected machine session no '
        + 'longer matches it. Runtime authority was not changed.'
    }
  }

  // The bridge ALSO pushes every one of `result.lines` as its own `console`
  // frame, which lands in the machine console through `onConsole` above.
  // Pushing them again here would double every line of a 23-field report.
  // The caller renders `describeApplyOutcome` into its own surface instead.
  return {
    ok: result.ok && authorityRefusal === null,
    sent: sentDefinition,
    refusal: null,
    result,
    authorityRefusal,
  }
}

export async function applyActiveMachineDefinition(
  provenance: MachineDefinitionProvenance = {},
  definition: ControllerDefinition | null = activeMachineDefinition(),
  machineId = controlMachine(useCamStore.getState()).id,
): Promise<ApplyActiveDefinitionOutcome> {
  if (!definition) {
    return applyRefused(
      "Nothing was sent: this project's machine has no definition yet. "
      + 'Define its axes, homing and pins first.',
    )
  }
  return applyConnectedMachineDefinition(definition, provenance, machineId)
}

/** One line of the apply report, at the severity it was reported with. */
export interface ApplyReportLine {
  text: string
  severity: 'info' | 'warn' | 'error' | 'success'
}

/**
 * The apply outcome as plain lines, for whatever existing surface renders it.
 *
 * The controller's own report is carried VERBATIM, line by line, at the
 * severity the controller gave it - a 23-field mismatch report is the whole
 * point of the readback and must never be collapsed into "failed".
 */
export function describeApplyOutcome(outcome: ApplyActiveDefinitionOutcome): ApplyReportLine[] {
  if (outcome.refusal !== null) return [{ text: outcome.refusal, severity: 'error' }]
  const result = outcome.result
  if (result === null) return [{ text: 'The apply produced no answer.', severity: 'error' }]
  const authorityRefusal = outcome.authorityRefusal ?? null
  const lines: ApplyReportLine[] = [{
    text: authorityRefusal !== null
      ? `The machine definition was NOT adopted: ${authorityRefusal}`
      : outcome.ok
      ? 'Machine definition applied: the controller accepted and read back every value.'
      : `The machine definition was NOT applied: ${result.error ?? 'the controller did not say why.'}`,
    severity: outcome.ok ? 'success' : 'error',
  }]
  for (const line of result.lines) lines.push({ text: line.text, severity: line.severity })
  if (result.reHome.length > 0) {
    lines.push({
      text: `Re-home ${result.reHome.join(', ')} before moving: this apply changed what the `
        + 'position counter means.',
      severity: 'warn',
    })
  }
  if (!result.configuredThisSession) {
    lines.push({
      text: 'The controller is NOT configured for this session and will refuse motion '
        + 'until an apply succeeds.',
      severity: 'warn',
    })
  }
  if (outcome.ok) lines.push({ text: APPLY_PIN_HEDGE, severity: 'info' })
  return lines
}


// ---- WO-416: the simulator's virtual part (simulator only) ----

/** Thin pass-through to the connected simulator's virtual part. A no-op
 *  (returns false) against real hardware or before connect - never throws. */
export function setSimulatedPart(part: SimulatedPart | null): boolean {
  if (!simulatedController) return false
  simulatedController.setSimulatedPart(part)
  return true
}

export function getSimulatedPart(): SimulatedPart | null {
  return simulatedController?.getSimulatedPart() ?? null
}

/** WO-2692: thin pass-through to the connected simulator's fixed tool setter -
 *  connect places the machine's stated one; null takes it off the table. A
 *  no-op (returns false) against real hardware or before connect. */
export function setSimulatedToolSetter(setter: SimulatedToolSetter | null): boolean {
  if (!simulatedController) return false
  simulatedController.setSimulatedToolSetter(setter)
  return true
}

export function getSimulatedToolSetter(): SimulatedToolSetter | null {
  return simulatedController?.getSimulatedToolSetter() ?? null
}

/**
 * WO-416: the simulator's DEFAULT virtual part - reused, not duplicated,
 * from ProgramPreview's `intendedStockWorkBox` math (that module is not
 * imported here: it pulls in CNCViewport/three.js, which would break every
 * machineSession test that runs in the plain 'node' vitest environment; the
 * work-box add is a few lines, mirrored verbatim from ProgramPreview.tsx and
 * from the same `work + WCO` pattern machineEnvelope.ts's
 * `fitProgramToEnvelope` already uses).
 *
 * When a setup's stock is loaded into Control (`programContext` is set),
 * that stock's machine-frame box becomes the part, with a bore and boss
 * sized off its footprint. Otherwise a nominal 100x80x30 block inside the
 * active machine definition's resolved travel, shrunk only when that machine
 * is smaller. The body sits just above the Z floor and its boss stays below
 * the Z ceiling, so an ordinary downward part probe can reach it. Never called
 * automatically (no connectMachine path invokes it) - only the Diagnostics
 * panel's initial placement / Reset actions do.
 */
export function buildDefaultSimulatedPart(): SimulatedPart {
  const stockBox = intendedStockMachineBox()
  if (stockBox) return simulatedPartFromMachineBox(stockBox)
  return simulatedPartInEnvelope(currentResolvedMachineMotion().envelope)
}

/**
 * WO-2712 amendment (Operator 10-09 5:26 PM: "fix it the right way by setting g54
 * offsets logically, and homing correct"): THE ONE PLACE a fresh profile's
 * G54 comes from on the shipped Sample router. Its stated home end puts
 * machine zero at the back-right top, so a G54 left at 0, 0, 0 sends any plain
 * file off the table. The logical zero is the default simulated part's
 * FRONT-LEFT TOP corner - read from the same placement buildDefaultSimulatedPart
 * uses, so the zero and the part always agree.
 *
 * Simulator only, and only for a G54 nothing has set: any stored axis (an
 * operator's entry, a controller's receipt, even an explicit 0) wins, and the
 * default is never written into the durable record. Null otherwise.
 */
export function defaultSimulatorG54(
  machineId: string,
  stored: Partial<MachinePosition> | undefined,
  envelope: MachineEnvelope,
): Partial<MachinePosition> | null {
  if (machineId !== GENERIC_MACHINE_ID) return null
  if (stored && offsetAxes(stored).length > 0) return null
  if (!envelope.x || !envelope.y || !envelope.z) return null
  const part = simulatedPartInEnvelope(envelope)
  return { x: part.origin.x, y: part.origin.y, z: part.topZ }
}

/** WO-416's nominal block inside a resolved envelope (no stock loaded). */
function simulatedPartInEnvelope(envelope: MachineEnvelope): SimulatedPart {
  const fitAxis = (
    axis: typeof envelope.x,
    nominalSize: number,
  ): { origin: number; size: number } => {
    if (!axis) return { origin: -nominalSize / 2, size: nominalSize }
    const span = axis.max - axis.min
    const clearance = Math.min(5, span * 0.05)
    const size = Math.min(nominalSize, Math.max(0, span - clearance * 2))
    return { origin: (axis.min + axis.max - size) / 2, size }
  }
  const fittedX = fitAxis(envelope.x, 100)
  const fittedY = fitAxis(envelope.y, 80)
  const origin = { x: fittedX.origin, y: fittedY.origin }
  const sizeX = fittedX.size
  const sizeY = fittedY.size
  const cx = origin.x + sizeX / 2
  const cy = origin.y + sizeY / 2
  let height = 30
  let bossHeight = 10
  let topZ = -40
  if (envelope.z) {
    const span = envelope.z.max - envelope.z.min
    const clearance = Math.min(5, span * 0.05)
    const usable = Math.max(0, span - clearance * 2)
    const scale = Math.min(1, usable / (height + bossHeight))
    height *= scale
    bossHeight *= scale
    topZ = envelope.z.min + clearance + height
  }
  const xyScale = Math.min(1, sizeX / 100, sizeY / 80)
  return {
    origin,
    sizeX,
    sizeY,
    topZ,
    height,
    bore: { cx, cy, diameter: 20 * xyScale, depth: Math.min(15, height / 2) },
    boss: {
      cx: origin.x + sizeX * 0.25,
      cy: origin.y + sizeY * 0.25,
      diameter: 25 * xyScale,
      height: bossHeight,
    },
  }
}

/** The loaded stock's machine-frame box (min/max, mm) - the same
 *  `intendedStockWorkBox` case split ProgramPreview.tsx uses, then
 *  translated by the active WCS's offset. Null when nothing is loaded, the
 *  box is degenerate, or the active WCS's offset is not yet known. */
function intendedStockMachineBox(): { min: { x: number; y: number; z: number }; max: { x: number; y: number; z: number } } | null {
  const context = loadedProgramContext()
  if (!context) return null
  const { stock, wcs } = context
  let min: { x: number; y: number; z: number }
  let max: { x: number; y: number; z: number }
  if (stock.coordinateSpace === 'world') {
    if (stock.mode === 'explicit') {
      const size = {
        x: stock.bounds.max.x - stock.bounds.min.x,
        y: stock.bounds.max.y - stock.bounds.min.y,
        z: stock.bounds.max.z - stock.bounds.min.z,
      }
      min = { x: stock.position.x, y: stock.position.y, z: stock.position.z }
      max = { x: min.x + size.x, y: min.y + size.y, z: min.z + size.z }
    } else {
      min = { ...stock.bounds.min }
      max = { ...stock.bounds.max }
    }
    min = { x: min.x - wcs.origin.x, y: min.y - wcs.origin.y, z: min.z - wcs.origin.z }
    max = { x: max.x - wcs.origin.x, y: max.y - wcs.origin.y, z: max.z - wcs.origin.z }
  } else {
    min = { x: stock.bounds.min.x + stock.position.x, y: stock.bounds.min.y + stock.position.y, z: stock.bounds.min.z + stock.position.z }
    max = { x: stock.bounds.max.x + stock.position.x, y: stock.bounds.max.y + stock.position.y, z: stock.bounds.max.z + stock.position.z }
  }
  if (!(max.x > min.x) || !(max.y > min.y) || !(max.z > min.z)) return null
  const activeWcs = store().activeWcs
  const wco = activeWcs ? store().offsets[activeWcs] : undefined
  if (!wco || wco.length < 3 || !wco.slice(0, 3).every(Number.isFinite)) return null
  return {
    min: { x: min.x + wco[0], y: min.y + wco[1], z: min.z + wco[2] },
    max: { x: max.x + wco[0], y: max.y + wco[1], z: max.z + wco[2] },
  }
}

/** Build a SimulatedPart from a machine-frame box: bore at the centre,
 *  boss at one corner quarter, both sized off the block's smaller side. */
function simulatedPartFromMachineBox(box: { min: { x: number; y: number; z: number }; max: { x: number; y: number; z: number } }): SimulatedPart {
  const sizeX = box.max.x - box.min.x
  const sizeY = box.max.y - box.min.y
  const height = box.max.z - box.min.z
  const origin = { x: box.min.x, y: box.min.y }
  const topZ = box.max.z
  const cx = origin.x + sizeX / 2
  const cy = origin.y + sizeY / 2
  const minSide = Math.min(sizeX, sizeY)
  const boreDiameter = Math.min(Math.max(minSide * 0.2, 6), 40)
  const bossDiameter = Math.min(Math.max(minSide * 0.22, 6), 45)
  return {
    origin,
    sizeX,
    sizeY,
    topZ,
    height,
    bore: { cx, cy, diameter: boreDiameter, depth: Math.max(1, Math.min(height * 0.5, height - 1)) },
    boss: {
      cx: origin.x + sizeX * 0.75,
      cy: origin.y + sizeY * 0.75,
      diameter: bossDiameter,
      height: Math.max(1, Math.min(height * 0.3, 12)),
    },
  }
}

/**
 * Find tool changes in a program: T words (with or without M6), and the GRBL
 * post dialect's no-M6 pattern - an M0 pause whose line comment mentions the
 * tool ("( change tool ... )"). Scans the ORIGINAL text so comments count.
 */
export function findToolChanges(text: string): ProgramToolChange[] {
  const changes: ProgramToolChange[] = []
  const lines = text.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i]
    const code = stripGcodeComments(raw)
    const tWord = /(?:^|\s)T(\d+)/i.exec(code)
    const isM6 = /(?:^|\s)M0?6(?:\s|$)/i.test(code)
    const isPauseToolChange = /(?:^|\s)M0?0(?:\s|$)/i.test(code) && /change\s*tool|tool\s*change/i.test(raw)
    if (tWord || isM6 || isPauseToolChange) {
      const tool = tWord ? Number(tWord[1]) : null
      const prev = changes[changes.length - 1]
      // The post often pairs a T line with its M0 pause a line or two later -
      // that is ONE tool change, not two.
      if (prev && i + 1 - prev.sourceLine <= 3 && (tool === null || prev.tool === tool || prev.tool === null)) {
        prev.sourceLine = i + 1 // anchor on the last line of the pair (the pause)
        if (prev.tool === null) prev.tool = tool
        continue
      }
      changes.push({
        sourceLine: i + 1,
        tool,
        label: tool !== null ? `T${tool}` : raw.trim().slice(0, 60),
      })
    }
  }
  return changes
}

/** Text controllers do not report an M6 boundary separately. Preserve every
 * source line but stage a controller hold at each M6 reached after motion, so
 * the session can run the native macro before any following line executes. */
function stageExecutableM6Hold(raw: string, optionalStop = false): string {
  let code = ''
  const rawIndexes: number[] = []
  let inParen = false
  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i]
    if (inParen) {
      if (ch === ')') inParen = false
      continue
    }
    if (ch === '(') {
      inParen = true
      continue
    }
    if (ch === ';') break
    code += ch
    rawIndexes.push(i)
  }

  const match = (optionalStop ? /(^|\s)(M0?1)(?=\s|$)/i : /(^|\s)(M0?6)(?=\s|$)/i).exec(code)
  if (!match) return raw
  const wordStart = match.index + match[1].length
  const staged = [...raw]
  // LinuxCNC executes its native M6 and the file pause in source order. The
  // simulator/GRBL substitute one M0 for M6 and keep the file stop in session.
  if (!optionalStop && !('linuxcncToolChange' in getMachineController())) {
    for (const pause of code.matchAll(/(?:^|\s)(M0?[01])(?=\s|$)/gi)) {
      const start = pause.index! + pause[0].length - pause[1].length
      for (let n = 0; n < pause[1].length; n++) staged[rawIndexes[start + n]] = ''
    }
  }
  if (match[2].length === 2) staged[rawIndexes[wordStart + 1]] = '0'
  else staged[rawIndexes[wordStart + 2]] = ''
  return staged.join('')
}

function stageRunningM6HoldLines(rawLines: string[]): string[] {
  let motionBefore = false
  return rawLines.map((raw) => {
    const code = stripGcodeComments(raw)
    const runningM6 = motionBefore && /(?:^|\s)M0?6(?:\s|$)/i.test(code)
    if (/(?:^|\s)G0?[0123](?:\s|$)/i.test(code) && /(?:^|\s)[XYZ](?:[-+.0-9]|\s)/i.test(code)) {
      motionBefore = true
    }
    // There is no optional-stop switch: M1 must hold even on a text reader
    // whose dialect accepts only M0. Keep the source line and comments intact.
    const stop = stageExecutableM6Hold(raw, true)
    return runningM6 ? stageExecutableM6Hold(stop) : stop
  })
}

function stageRunningM6Holds(text: string, fromLine = 1): string {
  const raw = text.split(/\r?\n/)
  // A guided text change resumes at M6+1. An M0 after it is in the file, so the
  // controller stops there (owner ruling 10-04: "if it's there it stops the machine").
  const staged = stageRunningM6HoldLines(raw)
  return keepTextSpindleOffForProbe(raw, staged, fromLine).lines.join('\n')
}

/**
 * WO-2157: A TEXT CONTROLLER RUNS THE FILE'S OWN M3/M4, so the words that would
 * spin a probe are left out of what it is handed: every M3/M4 the file reaches
 * while the tool in effect (the loaded tool, then each M6's T) is a Probe-type
 * library entry. The rest of each line - its S, its moves - is unchanged, and
 * so is every line numbered. An M3 after an M6 to an end mill is sent.
 */
function keepTextSpindleOffForProbe(
  raw: readonly string[],
  staged: readonly string[],
  fromLine = 1,
): { lines: string[]; probe: Tool | null; kept: number[] } {
  return keepSpindleOffForProbe(raw, staged, store().activeTool, (tool) => controlLoadedProbe(tool), fromLine)
}

/** WO-2157: which lines of the loaded text program were staged without their
 *  spindle start, as a key - Cycle Start re-stages when the loaded tool has
 *  changed the answer since (a probe swapped for an end mill after Load). */
let textProgramProbeKey: string | null = null

function textProbeKey(text: string): string {
  const raw = text.split(/\r?\n/)
  return keepTextSpindleOffForProbe(raw, raw).kept.join(',')
}

/** WO-1997: the first source line of the text job the controller now holds -
 * 1 for a whole program, the slice's start after a run-from-line or Step Back.
 * Lines before it were never sent in this job, so no hold is read there. */
let textJobFirstLine = 1

// Source lines whose M6 has been answered but whose own M0 is still a stop.
// Reset on a full load; a guided/kept return preserves this source identity.
const answeredTextM6 = new Set<number>()

export function textToolChangeResumeLine(text: string, line: number): number {
  const code = stripGcodeComments(text.split(/\r?\n/)[line - 1] ?? '')
  // A legacy M0 "change tool" is itself the file's single stop. Only an
  // actual M6 plus a file pause needs a residual stop on this same line.
  return /(?:^|\s)M0?6(?:\s|$)/i.test(code) && PROGRAM_PAUSE.test(code) ? line : line + 1
}

export function textM6WasAnswered(line: number): boolean {
  return answeredTextM6.has(line)
}

function holdSameLineStopAfterM6(ctrl: MachineController): boolean {
  const s = store()
  if (programPartsRun?.controller === ctrl || s.programText === null || ctrl.machineState() !== 'hold') return false
  const line = textProgramHoldLine(s.programText, s.job, s.holdsSeen)
  if (line === null || answeredTextM6.has(line)) return false
  const code = stripGcodeComments(s.programText.split(/\r?\n/)[line - 1] ?? '')
  if (!/(?:^|\s)M0?6(?:\s|$)/i.test(code) || !PROGRAM_PAUSE.test(code)) return false
  answeredTextM6.add(line)
  if ('linuxcncToolChange' in ctrl) return false
  store().pushConsole('rx', `M6 on line ${line} is answered. The file's M0/M1 on that line now holds; press CYCLE START to run the rest.`, 'info')
  return true
}

const PROGRAM_PAUSE = /(?:^|\s)M0?[01](?:\s|$)/i

/**
 * WO-1997: THE LINE A TEXT PROGRAM IS HELD AT - an `M0` of the file or an M6
 * staged as one - or null when the hold is not at a program pause (the
 * operator's Feed Hold). A tool change maps to a hold only when the hold is AT
 * its line. The readiness walk (2026-09-25) found the old cursor window reading
 * the post's `M0` after `T1 M6` as that M6 again, so the guided change parked,
 * measured and resumed onto the same pause, three times and counting.
 *
 * The controller holds at the first pause it reaches: the simulator's cursor
 * sits ON the pause, GRBL's on the line before it (an `M0` is acknowledged only
 * once the operator resumes). A job whose every line is already acknowledged
 * holds at its Nth pause, N counted from the job's own start.
 */
export function textProgramHoldLine(
  text: string,
  job: { phase: string; ackedSourceLine: number; sentSourceLine: number },
  holdsSeen: number,
): number | null {
  const pauses: number[] = []
  stageRunningM6HoldLines(text.split(/\r?\n/)).forEach((raw, index) => {
    if (index + 1 >= textJobFirstLine && PROGRAM_PAUSE.test(stripGcodeComments(raw))) pauses.push(index + 1)
  })
  if (pauses.length === 0) return null
  if (job.phase === 'complete') return pauses[Math.min(Math.max(holdsSeen - 1, 0), pauses.length - 1)]
  if (job.phase !== 'streaming' && job.phase !== 'paused') return null
  const line = pauses.find((pause) => pause >= job.ackedSourceLine)
  return line !== undefined && line <= job.sentSourceLine ? line : null
}

/** The same staging, run over an already-compiled stream instead of ahead of
 * it (WO-1822, ADR-0050 G6). Surface-mesh compensation keys its map to the
 * SOURCE text the operator loaded, so the compiler must be handed that source;
 * the M6 holds are staged into what comes out. Compensation never folds an M
 * word into a motion line - the compiler refuses motion that shares a line
 * with M, S or T - so every M6 arrives here on a pass-through line, exactly as
 * it arrived at the text staging before. */
/** WO-1822 (ADR-0050 G2): the offset's NAME is not its identity.
 *
 * Re-zeroing X, Y or Z on the same G54 after the grid was measured - a
 * `G10 L20` write, or the operator touching off again - slides the program
 * across the measured surface while every name-based check still passes. The
 * mesh records the values it was measured against; this compares them.
 *
 * It reports only what it can KNOW. A controller that never answered `$#`
 * leaves nothing to compare, and a mesh probed before this field existed
 * carries no recorded values, so both cases say nothing rather than ending a
 * map on an absence or passing one off as a match. */
function meshWorkOffsetMove(mesh: SurfaceMeshMap | null): { axis: 'X' | 'Y' | 'Z'; before: number; after: number } | null {
  const probed = mesh?.workOffsetValues
  const now = mesh ? store().offsets[mesh.workOffset] : undefined
  if (!probed || !now) return null
  const axes = ['X', 'Y', 'Z'] as const
  for (let index = 0; index < axes.length; index++) {
    const before = probed[index]
    const after = now[index]
    if (before === undefined || after === undefined) continue
    if (Math.abs(before - after) <= 1e-4) continue
    return { axis: axes[index], before, after }
  }
  return null
}

// ---- WO-2267: the mesh belongs to the work system it was probed in ----
//
// Operator ruling 2026-09-30 at the machine: "it should probe ask you to apply it and it
// should be applied to the work coordinate system and cleared similar to the
// way rotation is done." A Z surface run measures the map; Confirm applies it
// (applySurfaceMesh); Clear ends it (clearSurfaceMesh). Re-zeroing that work
// system on X, Y or Z ends it too - loudly, one info line, and the next load
// runs plain - because the program would no longer sit where the surface was
// measured (ADR-0050: "a stale map must be loud"). The one Z0 move that
// carries it is a tool-length shift the app itself makes (noteToolLengthZShift):
// the tool moved, not the surface.

/** Z values a tool-length write the app just asked for will report, per work
 *  system. Consumed by the first report that lands on one. */
const meshToolLengthZTargets = new Map<string, number>()
/** A mesh ended while a probe routine held the machine: the program is staged
 *  again once the routine lets go, not under it. */
let meshRestageOwed = false

/** WO-2267: the app is about to move `wcs` Z to `targetZ` for TOOL LENGTH (the
 *  guided change's reference-tool shift, or a geometry controller folding a
 *  tool length into Z). An applied mesh carries across that move. */
function noteToolLengthZShift(wcs: string, targetZ: number): void {
  if (store().surfaceMesh?.workOffset !== wcs) return
  meshToolLengthZTargets.set(wcs, targetZ)
}

/** WO-2267: end the mesh with one info console line saying why, and stage the
 *  program plain again when it was compensated. `restage` is false only for
 *  the load that is itself staging the program. */
function endSurfaceMesh(line: string, restage: boolean): void {
  const mesh = store().surfaceMesh
  if (!mesh) return
  meshToolLengthZTargets.clear()
  store().setSurfaceMesh(null)
  store().pushConsole('rx', line, 'info')
  if (!restage || !mesh.active) return
  if (probeCycleActive) meshRestageOwed = true
  // A running program's stream is never swapped under it.
  else if (!getMachineController().hasActiveJob()) restageLoadedProgram()
}

/** WO-2267: when the mesh's work system has been re-zeroed since it was
 *  measured, end the mesh and say so. A tool-length Z shift the app asked for
 *  carries it instead (the recorded values follow the shift). True when it
 *  ended the mesh. */
function endSurfaceMeshIfReZeroed(restage: boolean): boolean {
  const mesh = store().surfaceMesh
  const moved = meshWorkOffsetMove(mesh)
  if (!mesh || !moved) return false
  const now = store().offsets[mesh.workOffset]!
  const toolTarget = meshToolLengthZTargets.get(mesh.workOffset)
  const probed = mesh.workOffsetValues!
  const onlyZ = [0, 1].every((i) => probed[i] === undefined || now[i] === undefined || Math.abs(probed[i] - now[i]) <= 1e-4)
  if (onlyZ && toolTarget !== undefined && now[2] !== undefined && Math.abs(now[2] - toolTarget) <= 1e-4) {
    meshToolLengthZTargets.delete(mesh.workOffset)
    store().setSurfaceMesh({ ...mesh, workOffsetValues: [...now] })
    return false
  }
  const what = mesh.active ? 'compensation ended' : `measured for ${mesh.workOffset} was discarded`
  endSurfaceMesh(
    `Surface mesh ${what}: ${mesh.workOffset} ${moved.axis} was re-zeroed (${machineLengthText(moved.before)} to `
      + `${machineLengthText(moved.after)}), so the measured surface no longer lines up with it.`
      + (mesh.active ? ' The original program is staged.' : ''),
    restage,
  )
  return true
}

/** WO-2267: Confirm on the Z surface result step - apply the measured mesh to
 *  the work system it was probed in, and stage the program compensated. */
export function applySurfaceMesh(): { ok: boolean; message: string } {
  const mesh = store().surfaceMesh
  if (!mesh) return { ok: false, message: 'No surface mesh has been measured - run Z surface first.' }
  if (mesh.active) return { ok: true, message: `The surface mesh is already applied to ${mesh.workOffset}.` }
  if (endSurfaceMeshIfReZeroed(false)) {
    return { ok: false, message: `${mesh.workOffset} was re-zeroed after this mesh was measured - run Z surface again.` }
  }
  store().setSurfaceMesh({ ...mesh, active: true })
  store().pushConsole('rx', `Surface mesh applied to ${mesh.workOffset}: ${mesh.pointsX} x ${mesh.pointsY} points measured.`, 'info')
  restageLoadedProgram()
  return { ok: true, message: `Surface mesh applied to ${mesh.workOffset}; the program is staged compensated.` }
}

/** WO-2267: the strip chip's Clear and Probing's Disable compensation - one
 *  action: the mesh ends, the original program is staged, one console line. */
export function clearSurfaceMesh(): void {
  // Both buttons are disabled while a program runs, as Disable compensation
  // always was: the running stream stays what it was armed as.
  if (!store().surfaceMesh || getMachineController().hasActiveJob()) return
  endSurfaceMesh('Surface mesh compensation cleared; original program armed.', true)
}

// Every offset report or write is where a re-zero of the mesh's work system shows.
useMachineControl.subscribe((state, previous) => {
  if (state.offsets === previous.offsets) return
  const wcs = state.surfaceMesh?.workOffset
  if (!wcs || state.offsets[wcs] === previous.offsets[wcs]) return
  endSurfaceMeshIfReZeroed(true)
})

// WO-2283: the applied mesh belongs to its work system, so a program staged
// while another work system was active is staged again when the operator
// switches - compensated when it now starts in the mesh's, plain when it
// leaves it. Only when that changes what it runs as, never under a running
// program, and after a probe routine that switched it. A door that selects
// the file's work system mid-load is never re-entered: the check runs once
// the switch's own call has returned.
function restageForWorkSystemSwitch(): void {
  const s = store()
  const text = loadedProgramText()
  const stagedFor = meshStagedStartWcs
  if (!s.surfaceMesh?.active || text === null || stagedFor === s.activeWcs) return
  if (getMachineController().hasActiveJob()) return
  const streamOf = (c: SurfaceMeshCompileResult | null) => (c === null ? null : c.ok ? c.lines.map((l) => l.text).join('\n') : c.reason)
  if (streamOf(compileUnderAppliedMesh(text, stagedFor)) === streamOf(compileUnderAppliedMesh(text, s.activeWcs))) return
  if (probeCycleActive) meshRestageOwed = true
  else restageLoadedProgram()
}
useMachineControl.subscribe((state, previous) => {
  if (state.activeWcs === previous.activeWcs || !state.surfaceMesh?.active) return
  queueMicrotask(restageForWorkSystemSwitch)
})

function stageRunningM6HoldStream(lines: StreamLine[]): StreamLine[] {
  const raw = lines.map((line) => line.text)
  const staged = keepTextSpindleOffForProbe(raw, stageRunningM6HoldLines(raw)).lines
  return lines.map((line, index) => (
    staged[index] === line.text ? line : { ...line, text: staged[index] }
  ))
}

// ---- arm epoch (WO-082) ----
//
// Arming is not a store concept, but transient UI that DESCRIBES an armed job
// - the run-from plan card, which reads "the machine will first move to X/Y/Z
// and start at line N" - becomes a lie about MOTION the moment a different arm
// replaces it. Any surface may now arm from the top (the transport row does),
// so the panel that owns that card cannot see it happen. This is the smallest
// honest signal: a counter every load/arm-from-top bumps, which React reads
// through useSyncExternalStore.
let armEpochValue = 0
const armEpochListeners = new Set<() => void>()

export function armEpoch(): number {
  return armEpochValue
}

export function subscribeArmEpoch(listener: () => void): () => void {
  armEpochListeners.add(listener)
  return () => {
    armEpochListeners.delete(listener)
  }
}

function bumpArmEpoch(): void {
  armEpochValue++
  for (const listener of armEpochListeners) listener()
}

// ---- program load epoch (WO-2675) ----
//
// The arm epoch moves for every staging, the session's own included: the file
// staged again after an MDI line (WO-2234), read again at CYCLE START for a
// new offset (WO-1640), Re-arm, a kept stop, a mesh. Those reach the store
// exactly as the operator's Load does, the same file too. The Control 3D view
// keeps his zoom through all of them and re-fits only on his Load (Operator
// 10-08: "keep your zoom on MDI moves and offset/WCS changes; re-fit only on
// Load"), so his Load doors - the file door and the setup doors - and nothing
// else bump this counter, once the program is staged. A refused Load that
// leaves the program before it in place is not counted: it would take his view
// from the program still shown (a Load pressed while it runs).
let programLoadEpochValue = 0
const programLoadEpochListeners = new Set<() => void>()

export function programLoadEpoch(): number {
  return programLoadEpochValue
}

export function subscribeProgramLoadEpoch(listener: () => void): () => void {
  programLoadEpochListeners.add(listener)
  return () => {
    programLoadEpochListeners.delete(listener)
  }
}

function bumpProgramLoadEpoch(): void {
  programLoadEpochValue++
  for (const listener of programLoadEpochListeners) listener()
}

interface TransferReviewSnapshot {
  revision: number
  sourceMachineName: string | null
  targetMachineName: string
  result: TransferCheckResult
  acknowledged: boolean
  acknowledgementRequired: boolean
  summary: string | null
}

interface TransferReviewState extends TransferReviewSnapshot {
  readyAfterAcknowledge: boolean
  reasonAfterAcknowledge: string
}

let transferReviewValue: TransferReviewState = {
  revision: 0,
  sourceMachineName: null,
  targetMachineName: '',
  result: { refusals: [], warnings: [], notes: [] },
  acknowledged: false,
  acknowledgementRequired: false,
  summary: null,
  readyAfterAcknowledge: false,
  reasonAfterAcknowledge: 'Load a program.',
}
const transferReviewListeners = new Set<() => void>()

interface TransferReviewInput {
  sourceProgramText: string
  stagedProgramText: string
  context: ProgramContextV1 | null
  sourceMachine: Pick<MachineConfig, 'id' | 'name' | 'controller'> | null
  baseReadiness: { ready: boolean; reason: string }
}

let transferReviewInput: TransferReviewInput | null = null
let transferReviewProgramKey: string | null = null

export function transferReview(): TransferReviewSnapshot {
  return transferReviewValue
}

function publishTransferReview(next: Omit<TransferReviewState, 'revision'>): void {
  transferReviewValue = { ...next, revision: transferReviewValue.revision + 1 }
  for (const listener of transferReviewListeners) listener()
}

function clearTransferReview(): void {
  transferReviewInput = null
  transferReviewProgramKey = null
  publishTransferReview({
    sourceMachineName: null,
    targetMachineName: '',
    result: { refusals: [], warnings: [], notes: [] },
    acknowledged: false,
    acknowledgementRequired: false,
    summary: null,
    readyAfterAcknowledge: false,
    reasonAfterAcknowledge: 'Load a program.',
  })
}

function currentWorkOffsets(): TransferWorkOffsetTable {
  const state = store()
  const byWcs: TransferWorkOffsetTable['byWcs'] = {}
  for (const wcs of WCS_SLOTS) {
    const raw = state.offsets[wcs]
    if (!raw) continue
    const offset: TransferWorkOffset = {}
    for (const [index, axis] of (['X', 'Y', 'Z'] as const).entries()) {
      const value = raw[index]
      const establishedThisSession = workZeroRevision[wcs][axis] === connectionRevision
      const reportedThisSession = reportedWorkOffsetRevision[wcs][axis] === connectionRevision
      // Provenance is the report stamp, never the numeric value. Thus a real
      // reported zero passes, while a profile-less default zero does not.
      if (Number.isFinite(value) && (establishedThisSession || reportedThisSession)) {
        offset[axis.toLowerCase() as 'x' | 'y' | 'z'] = value
      }
    }
    if (Object.keys(offset).length > 0) byWcs[wcs] = offset
  }
  return { byWcs, activeWcs: state.activeWcs ?? undefined }
}

/** WO-2219: the offsets the transfer / soft-limit check judges a program
 *  against - `currentWorkOffsets` plus each offset's XY rotation as the
 *  controller reports it, so a program in a rotated offset is measured where
 *  it runs. A system with no rotation carries no field (unchanged row). */
function transferWorkOffsets(): TransferWorkOffsetTable {
  const table = currentWorkOffsets()
  const byWcs: TransferWorkOffsetTable['byWcs'] = {}
  for (const [wcs, offset] of Object.entries(table.byWcs) as Array<[WcsId, TransferWorkOffset]>) {
    const rotationDeg = controllerRotationDeg(wcs)
    byWcs[wcs] = rotationDeg === 0 ? offset : { ...offset, rotationDeg }
  }
  return { ...table, byWcs }
}

/** The work offsets a G-code file is read against: every frame whose X, Y and
 *  Z are known this session, plus each definition-enabled independent rotary
 *  coordinate the controller reported. Rotary holes keep canonical indexes. */
type ReaderWorkOffsets = Partial<Record<GcodeWcs, GcodeReaderWorkOffset>>

/**
 * WO-2215: THE XY ROTATION THE CONTROLLER HOLDS FOR `wcs`, degrees (0 = none).
 *
 * The active system's comes from the status frame when the frame carries one
 * (the AXBB-E bridge, WO-2203) - the rotation the positions in that frame were
 * read in; otherwise, and for every other system, the controller's own report
 * (`wcsRotations`: LinuxCNC's status block, the bridge's hello and receipts).
 * The reader states a G53/G28/G30 machine point in the work frame the
 * controller will report it in, and the MDI row names that point, through it.
 */
function controllerRotationDeg(wcs: string): number {
  if (!controller || store().connectionPhase !== 'connected') return 0
  if (wcs === (store().activeWcs ?? 'G54')) {
    const framed = (controller.status() as { workRotation?: unknown }).workRotation
    if (typeof framed === 'number' && Number.isFinite(framed)) return framed
  }
  const reported = controller.wcsRotations?.()?.[wcs]
  return typeof reported === 'number' && Number.isFinite(reported) ? reported : 0
}

function readerWorkOffsets(): ReaderWorkOffsets {
  const state = store()
  const rotary = enabledControlAxes(controlMachine(useCamStore.getState()).controllerDefinition)
    .filter((axis): axis is Extract<ControlAxis, 'A' | 'B' | 'C'> => axis === 'A' || axis === 'B' || axis === 'C')
  const axes: readonly ControlAxis[] = ['X', 'Y', 'Z', ...rotary]
  const indexes: Readonly<Record<ControlAxis, number>> = { X: 0, Y: 1, Z: 2, A: 3, B: 4, C: 5 }
  const offsets: ReaderWorkOffsets = {}
  // WO-2037: a G-code-text controller adds its G43.1 register to every work Z
  // in every frame, as the bridge adds a length folded into the frame's Z, so
  // a machine target (G53/G28/G30) is resolved against both. A geometry
  // controller's length is already in the frame's Z here.
  const lengthMm = controller?.capabilities.gcodeText === true ? toolLengthInForceMm(controller, '') : 0
  for (const wcs of ['G54', 'G55', 'G56', 'G57', 'G58', 'G59'] as const) {
    const row = state.offsets[wcs]
    if (!row) continue
    const point: Partial<GcodeReaderPoint> = {}
    for (const axis of axes) {
      const value = row[indexes[axis]]
      const established = workZeroRevision[wcs][axis] === connectionRevision
        || reportedWorkOffsetRevision[wcs][axis] === connectionRevision
      if (Number.isFinite(value) && established) {
        point[axis.toLowerCase() as keyof GcodeReaderPoint] = value
      }
    }
    if (![point.x, point.y, point.z].every((value) => typeof value === 'number' && Number.isFinite(value))) continue
    // WO-2215: and the rotation the controller runs that system with - only
    // when it has one, so an unrotated table is the table it always was.
    const rotationDeg = controllerRotationDeg(wcs)
    offsets[wcs] = {
      ...point,
      z: point.z! + lengthMm,
      ...(rotationDeg !== 0 ? { rotationDeg } : {}),
    } as GcodeReaderWorkOffset
  }
  return offsets
}

/** The work position a file interpreter may use as its modal starting point.
 *  Rotary coordinates are included only when this machine declares them as
 *  independent control axes. */
function readerPosition(ctrl: MachineController, machine = controlMachine(useCamStore.getState())): GcodeReaderPoint | null {
  const workPos = ctrl.status().workPos
  if (!workPos || ![workPos.x, workPos.y, workPos.z].every((v) => typeof v === 'number' && Number.isFinite(v))) {
    return null
  }
  const position: GcodeReaderPoint = { x: workPos.x, y: workPos.y, z: workPos.z }
  for (const axis of enabledControlAxes(machine.controllerDefinition)) {
    if (axis === 'X' || axis === 'Y' || axis === 'Z') continue
    const key = axis.toLowerCase() as 'a' | 'b' | 'c'
    const value = workPos[key]
    if (typeof value === 'number' && Number.isFinite(value)) position[key] = value
  }
  return position
}

// Reader coordinates mix linear mm and rotary degrees. Only XYZ uses the
// Control length formatter; rotary values retain the existing degree precision.
function readerCoordinateText(value: number | undefined, axis: keyof GcodeReaderPoint): string {
  if (value === undefined) return 'unset'
  return axis === 'x' || axis === 'y' || axis === 'z' ? machineLengthText(value) : positionNumber(value)
}

function readerPositionChanges(before: GcodeReaderPoint, after: GcodeReaderPoint): string[] {
  const changes: string[] = []
  for (const axis of ['x', 'y', 'z', 'a', 'b', 'c'] as const) {
    const was = before[axis]
    const now = after[axis]
    if (was === undefined && now === undefined) continue
    if (was !== undefined && now !== undefined && Math.abs(was - now) < 1e-9) continue
    changes.push(`${axis.toUpperCase()} ${readerCoordinateText(was, axis)} -> ${readerCoordinateText(now, axis)}`)
  }
  return changes
}

/** WO-1640: what moved between two offset tables, as the operator reads it
 *  (`G54 Z 66.57 -> 110`). Empty when nothing did. */
function readerOffsetChanges(before: ReaderWorkOffsets, after: ReaderWorkOffsets): string[] {
  const changes: string[] = []
  for (const wcs of ['G54', 'G55', 'G56', 'G57', 'G58', 'G59'] as const) {
    for (const axis of ['x', 'y', 'z', 'a', 'b', 'c'] as const) {
      const was = before[wcs]?.[axis]
      const now = after[wcs]?.[axis]
      if (was === undefined && now === undefined) continue
      if (was !== undefined && now !== undefined && Math.abs(was - now) < 1e-9) continue
      changes.push(`${wcs} ${axis.toUpperCase()} ${readerCoordinateText(was, axis)} -> ${readerCoordinateText(now, axis)}`)
    }
    // WO-2215: a rotation turns every G53/G28/G30 work point the reader baked.
    const wasDeg = before[wcs]?.rotationDeg ?? 0
    const nowDeg = after[wcs]?.rotationDeg ?? 0
    if (Math.abs(wasDeg - nowDeg) >= 1e-9) changes.push(`${wcs} rotation ${positionNumber(wasDeg)} -> ${positionNumber(nowDeg)} deg`)
  }
  return changes
}

let rereadingForExecutionChange = false

/**
 * WO-1640/WO-1791: A LOADED FILE RUNS IN THE FRAME AND MODAL START IN FORCE
 * WHEN IT RUNS.
 *
 * The file door stages at LOAD, and the bridge bakes the work offset in force
 * into the staged moves at that `loadMoves`; the reader has also resolved each
 * `G53` line into work coordinates against the offset in force then. Operator
 * edits G54 Z between an air run and the real one (09-14: 66.57 -> 110), and
 * a plain `startJob` ran the list baked at 66.57 - every work move 43.43 mm
 * low. So a Cycle Start on a file whose offsets changed since it was staged
 * reads the SAME file again against the offsets now in force - exactly a fresh
 * load - and starts that. Never a refusal asking for a reload (rule 11): the
 * software can do the reload, so it does, and says so once.
 *
 * Returns null when nothing changed (Cycle Start proceeds as it always did),
 * else whether the re-read was accepted; the start itself follows the staging.
 */
function rereadFileForExecutionChange(
  ctrl: MachineController,
  release: () => boolean = startMachineJob,
): boolean | null {
  if (rereadingForExecutionChange) return null
  // WO-2234: an ended MDI line still on the board is never what CYCLE START
  // runs - the file it was typed over is staged first, then started.
  const underMdi = settleProgramAfterMdiLine(ctrl, release)
  if (underMdi !== null) return underMdi
  const reload = toolpathProgramReload
  if (!reload || reload.controller !== ctrl) return null
  const s = store()
  if (s.programText !== null || s.job.name !== reload.name) return null
  // Only a start from the top: a job on the board or a parts run already
  // under way is past its first loadMoves (later parts re-read at staging).
  if (ctrl.hasActiveJob() || (programPartsRun?.controller === ctrl && programPartsRun.started)) return null
  const offsetChanges = readerOffsetChanges(reload.offsets, readerWorkOffsets())
  const positionNow = readerPosition(ctrl)
  const positionChanges = positionNow === null ? [] : readerPositionChanges(reload.position, positionNow)
  if (offsetChanges.length === 0 && positionChanges.length === 0) return null
  const changeDescription = offsetChanges.length > 0
    ? `the new work offset (${offsetChanges.join(', ')})${positionChanges.length > 0
        ? ` and execution position (${positionChanges.join(', ')})`
        : ''}`
    : `the execution position (${positionChanges.join(', ')})`
  const outcome = loadGcodeTextToolpathProgram(reload.name, reload.runFrom?.text ?? reload.text, {
    publishListing: reload.publishListing,
    context: reload.context,
    runThroughOffsetChanges: reload.runThroughOffsetChanges,
    ...(reload.runFrom ? {
      publishListing: false, keepsLoadedProgram: true, runFromFile: reload, fileNumbering: reload.runFrom.numbering,
    } : {}),
    fileReread: true,
    loadLine: () => `"${reload.name}" was read again for ${changeDescription}, so omitted axes, incremental moves, `
      + 'arcs and G53 lines run from the machine state that Cycle Start releases.',
    onStaged: () => {
      rereadingForExecutionChange = true
      try {
        return release()
      } finally {
        rereadingForExecutionChange = false
      }
    },
  })
  return outcome.ok
}

function activeWcsAffectsTransferReview(): boolean {
  if (!transferReviewInput) return false
  const workMoves = transferCheckJobFromProgram(transferReviewInput.stagedProgramText).moves
    .filter((move) => move.coordinateFrame === 'work')
  return workMoves.length > 0 && workMoves.every((move) => !move.workCoordinateSystem)
}

function sameFindings(left: TransferCheckResult, right: TransferCheckResult): boolean {
  return left.refusals.length === right.refusals.length
    && left.warnings.length === right.warnings.length
    && left.notes.length === right.notes.length
    && left.refusals.every((finding, index) => finding === right.refusals[index])
    && left.warnings.every((finding, index) => finding === right.warnings[index])
    && left.notes.every((note, index) => note === right.notes[index])
}

function transferProgramKey(input: TransferReviewInput): string {
  return JSON.stringify([
    input.sourceProgramText,
    input.stagedProgramText,
    input.context?.post.id ?? null,
    input.context?.post.label ?? null,
    input.sourceMachine?.id ?? null,
    input.sourceMachine?.name ?? null,
    input.sourceMachine?.controller ?? null,
  ])
}

/** WO-1182: a warning never gates. Every warning is a console line the
 * operator can read; an "Acknowledge warnings" click made nothing safer and
 * stood between the operator and Cycle Start (Operator: "stop adding so many god
 * damn blockers to the software doing what it is told to do"). Refusals -
 * soft-limit exceedance, controller mismatch - still gate, because those are
 * the crash. */
function acknowledgementReason(result: TransferCheckResult): string | null {
  void result
  return null
}

interface RunTransferCheckOptions {
  baseReadiness: { ready: boolean; reason: string }
  sourceMachine: Pick<MachineConfig, 'id' | 'name' | 'controller'> | null
  stagedProgramText?: string
  /** WO-2689: the reason the controller's text reader refused this load with,
   *  already printed as the Load's one console line. The check still runs and
   *  still owns readiness; a refusal of its own that restates that same reason
   *  is not printed again. A different reason (WO-1289) still is. */
  controllerRefusal?: string | null
}

function runTransferCheck(
  loaded?: RunTransferCheckOptions,
): void {
  const machineState = store()
  if (loaded) {
    if (!machineState.programText) {
      clearTransferReview()
      return
    }
    transferReviewInput = {
      sourceProgramText: machineState.programText,
      stagedProgramText: loaded.stagedProgramText ?? machineState.programText,
      context: machineState.programContext,
      sourceMachine: loaded.sourceMachine
        ? {
            id: loaded.sourceMachine.id,
            name: loaded.sourceMachine.name,
            controller: loaded.sourceMachine.controller,
          }
        : null,
      baseReadiness: { ...loaded.baseReadiness },
    }
  }
  const input = transferReviewInput
  if (!input || machineState.programText !== input.sourceProgramText) return

  const cam = useCamStore.getState()
  const machine = controlMachine(cam)
  const sourceMachineName = input.sourceMachine?.name ?? input.context?.post.label ?? null
  const declared = input.context?.post.id
  const postedController = declared === 'uccnc' || isGrblFamily(declared)
    || declared === 'linuxcnc' || declared === 'generic'
    ? declared
    : null
  // WO-1289: a refused preview is UNKNOWN safety geometry, not an empty job.
  // The renderer, mesh planner and fit trace already fail closed on its empty
  // drawable collections. The transfer check historically treated that same
  // empty move list as "nothing to check", so carry the model's third state
  // into the gate before any bounds verdict can silently pass.
  const preview = buildPreviewModel(input.stagedProgramText)
  const result = preview.refusal !== null
    ? {
        refusals: [
          `${preview.refusal} Program travel and soft-limit checks cannot judge this program, so Cycle Start is refused.`,
        ],
        warnings: [],
        notes: [],
      }
    : checkJobAgainstMachine(
        transferCheckJobFromProgram(input.stagedProgramText, postedController
          ? {
              id: input.sourceMachine?.id ?? input.context?.project.id ?? 'posted-program',
              name: input.sourceMachine?.name ?? input.context?.post.label ?? postedController,
              controller: postedController,
            }
          : undefined),
        machine,
        transferWorkOffsets(),
        currentResolvedMachineMotion(),
      )
  if (preview.notes.length > 0) result.notes.unshift(...preview.notes)
  const nextProgramKey = transferProgramKey(input)
  const findingsUnchanged = sameFindings(transferReviewValue.result, result)
  const sameProgram = transferReviewProgramKey === nextProgramKey
  const acknowledged = sameProgram && findingsUnchanged && transferReviewValue.acknowledged
  const acknowledgement = acknowledgementReason(result)
  const summary = transferCheckSummary(sourceMachineName, machine.name, result)
  const readinessNote = transferCheckReadinessNote(result)
  const qualifiedBaseReadiness = input.baseReadiness.ready && readinessNote
    ? { ready: true, reason: readinessNote }
    : input.baseReadiness
  const previousGateReason = transferReviewValue.result.refusals[0]
    ?? (transferReviewValue.acknowledged ? null : acknowledgementReason(transferReviewValue.result))
  const previousReadinessNote = transferCheckReadinessNote(transferReviewValue.result)
  // WO-2000: a note already told for this program is not told again when
  // another axis is set - an unset axis is one console line, not one per probe.
  const previousNotes = new Set(transferReviewValue.result.notes)
  const currentReadiness = store().programReadiness
  const previousGateOwnedReadiness = previousGateReason !== null
    && !currentReadiness.ready
    && currentReadiness.reason === previousGateReason
  const previousNoteOwnedReadiness = previousReadinessNote !== null
    && currentReadiness.ready
    && currentReadiness.reason === previousReadinessNote
  publishTransferReview({
    sourceMachineName,
    targetMachineName: machine.name,
    result,
    acknowledged,
    acknowledgementRequired: acknowledgement !== null,
    summary,
    readyAfterAcknowledge: qualifiedBaseReadiness.ready,
    reasonAfterAcknowledge: qualifiedBaseReadiness.reason,
  })
  transferReviewProgramKey = nextProgramKey
  if (!sameProgram || !findingsUnchanged) {
    // WO-2689: the preview reader reads the same word table the controller's
    // text reader does, so a word the controller refused came back here as the
    // same sentence ("Line N: <word> is not in the ... table ..." plus "Nothing
    // is drawn ..."), bare - the Load said its reason twice.
    const controllerSaid = loaded?.controllerRefusal ?? null
    for (const refusal of result.refusals) {
      if (controllerSaid !== null && refusal.startsWith(controllerSaid)) continue
      store().pushConsole('rx', refusal, 'error')
    }
    for (const warning of result.warnings) store().pushConsole('rx', warning, 'warn')
    // Notes are not flagged checks: they say what the check could not decide,
    // so they are told plainly and never counted or acknowledged.
    for (const note of result.notes) {
      if (!sameProgram || !previousNotes.has(note)) store().pushConsole('rx', note, 'info')
    }
  }
  if (result.refusals.length > 0) {
    store().setProgramReadiness({ ready: false, reason: result.refusals[0] })
  } else if (acknowledgement && !acknowledged) {
    store().setProgramReadiness({ ready: false, reason: acknowledgement })
  } else if (loaded || previousGateOwnedReadiness || previousNoteOwnedReadiness) {
    store().setProgramReadiness(qualifiedBaseReadiness)
  }
}

useMachineControl.subscribe((state, previous) => {
  if (state.offsets !== previous.offsets
    || (state.activeWcs !== previous.activeWcs && activeWcsAffectsTransferReview())) {
    runTransferCheck()
  }
})

export function acknowledgeTransferWarnings(): boolean {
  const review = transferReviewValue
  const expectedReason = acknowledgementReason(review.result)
  if (review.result.refusals.length > 0 || expectedReason === null) return false
  publishTransferReview({ ...review, acknowledged: true })
  // Lift only the gate this acknowledgement owns. If another live check has
  // made the program unready since load, its newer refusal must survive.
  const readiness = store().programReadiness
  if (!readiness.ready && readiness.reason === expectedReason) {
    store().setProgramReadiness({
      ready: review.readyAfterAcknowledge,
      reason: review.reasonAfterAcknowledge,
    })
  }
  return true
}

/**
 * Load a program into the session (streamer + store snapshot + tool scan).
 *
 * `context` binds the loaded text to a frozen manufacturing-intent snapshot:
 *  - undefined (default): preserve the current context only when the text is
 *    byte-identical (re-arm-from-top, cancel run-from, mesh re-arm), else clear
 *    it - an ordinary program text change never carries the previous context.
 *  - null: explicit no-context (arbitrary file / recent load).
 *  - a ProgramContextV1: the direct setup-load snapshot, built from the same
 *    authoritative inputs that posted this exact text. The store re-validates,
 *    deep-copies, and deep-freezes it at the setProgram boundary, so an arbitrary
 *    mutable caller object cannot reach the stored snapshot.
 */
export function loadMachineProgram(
  name: string,
  text: string,
  context?: ProgramContextV1 | null,
): LoadResult {
  // `false`: never handed on, so the text door always answers.
  return loadTextProgram(name, text, context, false)!
}

/** Whether this controller runs a staged program - the route the WO-1335
 *  file interpreter feeds, and the one the machine bridge runs files through. */
function controllerHasProgramRoute(ctrl: MachineController): boolean {
  return ctrl.capabilities.machineProgram === true && typeof ctrl.loadProgram === 'function'
}

/** Which door an operator's G-code file went through, and its answer. */
export type GcodeFileLoadOutcome =
  | { door: 'text'; load: LoadResult }
  | { door: 'program'; ok: boolean; reason: string | null }

/**
 * THE OPERATOR'S FILE DOOR (WO-1335, WO-1977).
 *
 * A controller with no text route gets the file through the interpreter, as
 * it always did. A controller WITH one gets the text - unless its own text
 * reader refuses a file that carries no LienCAM context and the controller
 * also runs staged programs. Then the file is read by the same interpreter the
 * machine bridge uses, because the software can run it (rule 11).
 *
 * WO-1977, Operator 2026-09-25: on "Simulate LienCNC V2" his Fusion file stopped
 * at line 12 (`G53 G0 Z128.`) - the simulator's text reader takes only the
 * words LienCAM's own UCCNC post emits. The refusal wrote no console row, the
 * store still named the file as loaded, and the Control tab said "The program
 * is not armed. Press Re-arm from start", which re-read the same file into the
 * same refusal. His real LienCNC reads that file through the interpreter.
 */
export function loadGcodeFile(
  name: string,
  text: string,
  context: ProgramContextV1 | null,
  /** WO-2651: an edited program keeps the run-through choice it was loaded with. */
  options: { runThroughOffsetChanges?: boolean } = {},
): GcodeFileLoadOutcome {
  const outcome = ((): GcodeFileLoadOutcome => {
    if (!controllerNeedsToolpathProgram()) {
      // WO-2237: the operator's Load - the same file too - replaces a kept
      // stop's place; its CYCLE START runs the file from its start (rehearsal L3).
      forgetKeptStop()
      const load = loadTextProgram(name, text, context, context === null)
      if (load !== null) return { door: 'text', load }
    }
    // WO-2686 fix round 6: the program door forgets the kept stop only when it
    // accepts the file (`candidate`); a refused Load replaced nothing.
    return {
      door: 'program',
      ...loadGcodeTextToolpathProgram(name, text, {
        publishListing: true, context, runThroughOffsetChanges: options.runThroughOffsetChanges === true, candidate: true,
      }),
    }
  })()
  // WO-1978: the tools this file calls go into the tool table ready to measure,
  // whichever door read it and whether or not it armed - measuring is the
  // operator's preparation for running it (a file refused for a G54 not yet
  // set is still the file he is about to run).
  fillToolTableFromProgram(name, text)
  sayReferenceToolNeeded(name, outcome.door === 'text' ? textFixedPadChanges(name) : programFixedPadChanges(outcome.ok))
  // WO-2675: his Load, the same file too, frames the program in the 3D view.
  // The text door's store holds the file even when the controller refused it;
  // a program-door refusal leaves the program before it where it was.
  if (outcome.door === 'text' || outcome.ok) bumpProgramLoadEpoch()
  return outcome
}

// ---- a reference tool before the run (WO-2016) ----
//
// Operator's 09-25 job: with no reference tool measured on the setter, its first
// mid-program M6 (line 9908 of 49,549) could only print "cannot run the
// fixed-pad tool change" when the machine got there. That was known at Load.
// Load says it once, Cycle Start points back to it while it still stands, and
// measuring the reference ends it. Nothing is refused: the software can run the
// program, and the operator may measure at any time before the change.

/** The load that still needs a reference tool - that program's name and the
 *  M6 that will measure against it - or null. */
let referenceToolNotice: { name: string; line: number; tool: number } | null = null

/** WO-2016: THE ONE ANSWER to "can the fixed-pad change measure the new
 *  tool?" - a reference tool measured on the setter, in `table` (the tool table
 *  of the machine Control runs). The tool-change hold asks it at the change
 *  (`beginProgramM6ToolChange`; the Program panel's automatic M6 and Guided
 *  button); Load asks it before the run. One function, so they cannot disagree. */
export function referenceToolMeasuredIn(table: MachineToolTable): boolean {
  const reference = table.reference === null ? undefined : findTool(table, table.reference)
  return reference?.probedMachineZ !== null && reference?.probedMachineZ !== undefined
}

/** `referenceToolMeasuredIn` for the machine Control runs. */
function referenceToolMeasured(): boolean {
  return referenceToolMeasuredIn(useMachineToolTable.getState().tableFor(controlMachineId()))
}

/** The fixed-pad change a held program boundary runs - the one that measures
 *  the new tool against the reference - or null. Read off what Load staged
 *  (the interpreter, on Control's machine), never off the text a second time:
 *  - `m6`: a posted M6 on a machine with a tool-change park, with or without a
 *    macro bound to M6 run first as its prelude - `beginProgramM6ToolChange`;
 *  - `macro.toolChange`: a bound code whose macro the reader counted as a tool
 *    change - `enterBoundaryMacroToolChange` enters the same change there when
 *    the machine has a tool-change park, whether the macro reaches its
 *    `toolChange()` or ends without it. */
function boundaryFixedPadChange(boundary: ProgramSetupBoundary): { line: number; tool: number } | null {
  if (boundary.m6 !== undefined) return { line: boundary.m6.line, tool: boundary.m6.tool }
  const macro = boundary.macro
  if (macro?.toolChange !== undefined && configuredToolChangePark() !== null) {
    return { line: macro.line, tool: macro.toolChange }
  }
  return null
}

/** The program door's fixed-pad changes, in run order: its held boundaries as
 *  `boundaryFixedPadChange` reads them. None when the load was refused (the
 *  parts run is then still the previous program's). */
function programFixedPadChanges(loaded: boolean): { line: number; tool: number }[] {
  const run = programPartsRun
  if (!loaded || run === null || run.controller !== controller || run.boundaries === undefined) return []
  return [...run.boundaries.entries()]
    .sort(([a], [b]) => a - b)
    .flatMap(([, boundary]) => {
      const change = boundaryFixedPadChange(boundary)
      return change === null ? [] : [change]
    })
}

/** The text door's fixed-pad changes, in run order: each M6 the controller is
 *  held at (`stageRunningM6HoldLines` - the pauses `textProgramHoldLine`
 *  reads) with the tool the job records on that line, on a machine with a
 *  tool-change park - the hold and the tool the Program panel's automatic M6
 *  runs its guided change at. An M6 with no tool known is a manual change. */
function textFixedPadChanges(name: string): { line: number; tool: number }[] {
  const { job, programText } = store()
  if (job.name !== name || programText === null || configuredToolChangePark() === null) return []
  const raw = programText.split(/\r?\n/)
  return stageRunningM6HoldLines(raw).flatMap((staged, index) => {
    if (staged === raw[index]) return []
    const tool = job.toolChanges.find((change) => change.sourceLine === index + 1)?.tool ?? null
    return tool === null ? [] : [{ line: index + 1, tool }]
  })
}

/** At Load: one console line when the loaded program's first fixed-pad change
 *  will measure against a reference tool and none is measured. */
function sayReferenceToolNeeded(name: string, changes: readonly { line: number; tool: number }[]): void {
  referenceToolNotice = null
  const first = changes[0]
  if (first === undefined || referenceToolMeasured()) return
  referenceToolNotice = { name, line: first.line, tool: first.tool }
  store().pushConsole(
    'rx',
    `"${name}": the tool change on line ${first.line} (T${first.tool}) measures the new tool against a reference tool, `
      + 'and none is measured yet. Measure a reference tool on the setter first (Tools / Probe panel).',
    'warn',
  )
}

/** The Load notice while it still stands: the same program is loaded and the
 *  reference is still unmeasured. */
function referenceToolNoticeStanding(): { name: string; line: number; tool: number } | null {
  const notice = referenceToolNotice
  if (notice === null || store().job.name !== notice.name) return null
  return referenceToolMeasured() ? null : notice
}

/** Cycle Start from the top points back to the Load line; it never refuses.
 *  A job already on the board or a parts run under way is past its start. */
function pointToReferenceToolNotice(ctrl: MachineController): void {
  if (ctrl.hasActiveJob() || (programPartsRun?.controller === ctrl && programPartsRun.started)) return
  const notice = referenceToolNoticeStanding()
  if (notice === null) return
  store().pushConsole(
    'tx',
    `Cycle Start: no reference tool is measured yet for the tool change on line ${notice.line} (T${notice.tool}) - `
      + 'measure a reference tool on the setter before the program reaches it (see the load line).',
    'warn',
  )
}

// Measuring the reference ends the notice, with one line saying so.
useMachineToolTable.subscribe(() => {
  const notice = referenceToolNotice
  if (notice === null || !referenceToolMeasured()) return
  referenceToolNotice = null
  if (store().job.name !== notice.name) return
  store().pushConsole(
    'rx',
    `Reference tool measured - the tool change on line ${notice.line} (T${notice.tool}) will measure against it.`,
    'info',
  )
})

/** `loadMachineProgram`'s body. With `handOnRefusedFile`, a text refusal on a
 *  controller that runs staged programs returns null BEFORE anything is
 *  written, so the caller can read the file through the interpreter instead.
 *  `sayRefusal` false (WO-2689): a caller that says the refusal in its own
 *  line (Re-arm from start) does not get the Load's line printed again. */
function loadTextProgram(
  name: string,
  text: string,
  context: ProgramContextV1 | null | undefined,
  handOnRefusedFile: boolean,
  sayRefusal = true,
): LoadResult | null {
  publishNonProgramActionStatus(null)
  clearOperatorStop()
  // Validate explicit context before changing the controller's prepared job.
  // A later store refusal must never leave controller and UI on different text.
  if (context !== undefined) assertProgramContextMatchesProgram(context, text)
  const contextForCheck = context !== undefined
    ? context
    : text === store().programText ? store().programContext : null
  const sourceMachineForCheck = contextForCheck?.source === 'live-setup'
    ? useCamStore.getState().project.machine
    : null
  clearRunFromReview()
  const ctrl = getMachineController()
  // WO-2267: a re-zero of the mesh's work system ends the mesh (one info line)
  // and this load goes ahead plain - it never refuses the program for it.
  endSurfaceMeshIfReZeroed(false)
  // Every later M6 needs a controller boundary. Whether that boundary launches
  // the fixed-pad macro or remains the established manual hold is decided by
  // the explicitly configured TC park in ProgramPanel.
  const nativeM6Text = stageRunningM6Holds(text)
  // WO-2283: the applied mesh belongs to its work system - any program whose
  // moves run there is compiled compensated, a program run in another work
  // system loads plain. WO-1822 (ADR-0050 G6): the compiler gets the SOURCE
  // text the store holds, not the M6-staged copy; the staging runs over the
  // compiled stream below.
  meshStagedStartWcs = store().activeWcs
  const compiled = compileUnderAppliedMesh(text)
  let meshCompileError: string | null = null
  /** A contract v3 refusal from the backend, in its own words. */
  let loadRefusal: string | null = null
  let result: LoadResult
  let controllerProgramReplaced = false
  let stagedProgramText = nativeM6Text
  // WO-422 / ADR-0041 rule 2: a G-code PROGRAM is the text path, and not every
  // controller has one. Say so plainly instead of arming an empty job and
  // blaming the program for having no executable lines.
  if (!ctrl.capabilities.gcodeText) {
    const refusal =
      'G-code file refused: this controller runs setups, not G-code files - load the setup instead.'
    loadNothing(ctrl)
    endToolChangeSequence()
    if (programPartsRun?.controller === ctrl) programPartsRun = null
    if (programPartsTerminal?.controller === ctrl) programPartsTerminal = null
    store().setProgram(null, null, [], null)
    store().applyJobProgress(ctrl.jobProgress())
    store().setProgramReadiness({ ready: false, reason: refusal })
    store().pushConsole('tx', refusal, 'error')
    bumpArmEpoch()
    return { lines: [], skipped: 0, overlongLines: [] }
  }
  if (compiled?.ok) {
    // WO-423: the prepared-line-stream path is the contract's own optional
    // member now (the WO-422 finding is closed), so this asks the interface.
    // A backend without one still fails CLOSED and says which part is missing.
    const meshLines = stageRunningM6HoldStream(compiled.lines)
    const prepared = ctrl.loadPreparedJob?.(meshLines)
    if (prepared?.ok) {
      result = prepared.result
      controllerProgramReplaced = true
      // The transfer gate must measure the exact compensated stream accepted
      // by Control. The source text remains the store/context identity, while
      // this derived text follows every subdivided move the controller can fly.
      stagedProgramText = meshLines.map((line) => line.text).join('\n')
    } else {
      loadNothing(ctrl)
      controllerProgramReplaced = true
      meshCompileError =
        prepared?.ok === false
          ? prepared.reason
          : 'This controller cannot take a mesh-compensated program.'
      result = { lines: [], skipped: 0, overlongLines: [] }
    }
  } else if (compiled && !compiled.ok) {
    // Fail closed: if the operator expects mesh compensation, never quietly
    // arm the uncorrected original as a fallback.
    loadNothing(ctrl)
    controllerProgramReplaced = true
    meshCompileError = compiled.reason
    result = { lines: [], skipped: 0, overlongLines: [] }
  } else {
    // Contract v3: a load either produced a program or was REFUSED in a
    // sentence. `capabilities.gcodeText` is true on this branch, so a refusal
    // here is a controller-state problem (not connected, etc.), and the
    // operator gets the backend's own words rather than "no executable lines".
    const outcome = ctrl.loadJob(nativeM6Text)
    if (outcome.ok) {
      result = outcome.result
      controllerProgramReplaced = true
    } else if (handOnRefusedFile && controllerHasProgramRoute(ctrl)) {
      // A refused loadJob disturbed nothing on the controller, and nothing
      // above has written the store's program, so the interpreter door starts
      // clean. Its load row names the file; this row says why it took it.
      store().pushConsole(
        'rx',
        `"${name}": the controller's text reader cannot run it (${outcome.reason}), so it was read by the `
        + 'file interpreter the machine bridge uses.',
        'info',
      )
      return null
    } else {
      meshCompileError = null
      loadRefusal = outcome.reason
      // WO-1977: a refusal the operator cannot read is a dead end - this one
      // used to reach only the readiness field, under "not armed".
      if (sayRefusal) store().pushConsole('rx', `"${name}" was not loaded: ${outcome.reason}`, 'error')
      result = { lines: [], skipped: 0, overlongLines: [] }
    }
  }
  if (controllerProgramReplaced) {
    answeredTextM6.clear()
    endToolChangeSequence()
    if (programPartsRun?.controller === ctrl) programPartsRun = null
    if (programPartsTerminal?.controller === ctrl) programPartsTerminal = null
    // WO-1275: a G-code TEXT program is not a staged geometry list this session
    // split, so nothing here knows where its cuts are. Back to the conservative
    // answer; the gate is not in this route's path anyway.
    stagedMotionCuts = true
  }
  textJobFirstLine = 1
  store().setProgram(name, text, findToolChanges(text), context)
  store().applyJobProgress(ctrl.jobProgress())
  const wholeTotal = ctrl.jobProgress().totalLines
  textProgramWhole = wholeTotal > 0 ? { controller: ctrl, programText: text, total: wholeTotal } : null
  // WO-2157: Load says once that the file's spindle start will not spin the
  // probe that is loaded. Nothing is refused; the staged text left it out.
  const sourceLines = text.split(/\r?\n/)
  const probeKeptOff = keepTextSpindleOffForProbe(sourceLines, sourceLines)
  textProgramProbeKey = probeKeptOff.kept.join(',')
  if (probeKeptOff.probe !== null && result.lines.length > 0) {
    store().pushConsole('rx', `"${name}": ${probeSpindleRefusal(probeKeptOff.probe)}`, 'info')
  }
  // WO-2464: the readiness check reads comments the way the ACTIVE controller does (same selector as
  // ProgramPanel); an undeclared controller keeps the GRBL reading.
  const lintDialect = resolveDeclaredController(controlMachine(useCamStore.getState()))
  const firstLintError = lintGcode(text, {
    commentStyle: (lintDialect.ok ? lintDialect.dialect : GRBL_CONFIG).capabilities.comment,
  }).find(
    (finding) => finding.level === 'error',
  )
  const readinessReason =
    meshCompileError
      ? `Mesh compensation refused: ${meshCompileError}`
      : loadRefusal
      ? loadRefusal
      : result.lines.length === 0
      ? 'The program has no executable lines.'
      : result.overlongLines.length > 0
        ? `Line ${result.overlongLines[0]} exceeds GRBL's 80-character limit.`
        : firstLintError
          ? `Line ${firstLintError.line}: ${firstLintError.message}`
          : compiled?.ok
            ? `Program checks passed. Surface mesh compensation is ACTIVE (${compiled.generatedMotionLines} compensated motion blocks).`
            : 'Program checks passed.'
  store().setProgramReadiness({
    ready: !meshCompileError && result.lines.length > 0 && result.overlongLines.length === 0 && !firstLintError,
    reason: readinessReason,
  })
  // WO-1008: ARM THE PATH CHECK ON THE PROGRAM THAT WAS ACTUALLY ARMED.
  //
  // This is the wire that makes path fidelity a PRODUCT assertion rather than
  // an instrument someone chose to run: a person opening a file and pressing
  // Cycle Start is checked, with no harness involved. It arms the text the
  // controller was given - the mesh-compensated lines when compensation is
  // active, because those are what the machine will fly - and arms nothing at
  // all when the load produced nothing, so an old queue can never be scored
  // against a new run. The tolerance is re-read here too: it comes off this
  // project's machine, and the project can change between two loads.
  if (result.lines.length === 0) {
    clearPathFidelity()
  } else if (compiled?.ok) {
    // A MESH-COMPENSATED PROGRAM IS NOT SCORED, AND SAYS SO. The controller
    // takes the compiled stream and keeps each move's ORIGINAL source line as
    // its id, so ids derived from the compiled text would land on the wrong
    // blocks - a few of them plausibly, which is worse than none. Requirement 4
    // again: "I could not tell" is the answer, not a guess dressed as one.
    refusePathFidelity(
      'this program is surface-mesh compensated, and the compensated path is not one this '
      + 'check can attribute to the moves the controller reports.',
    )
    refreshPathToleranceFromMachine()
  } else {
    armPathFidelityFromProgram(text)
    refreshPathToleranceFromMachine()
  }
  runTransferCheck({
    baseReadiness: store().programReadiness,
    sourceMachine: sourceMachineForCheck,
    stagedProgramText,
    controllerRefusal: loadRefusal,
  })
  bumpArmEpoch()
  return result
}

// ---------------------------------------------------------------------------
// THE GEOMETRY PROGRAM DOOR (WO-1031; WO-1019 slice 1c)
//
// ADR-0043 sections 3-4 gave the geometry path a builder
// (`src/lib/program/buildMachineProgram.ts`, WO-1029) and an executing backend
// (`MachineController.loadProgram`, WO-1030). Until this block NOTHING in the
// app called either: both halves were landed and unreachable, which is this
// project's signature defect - a capability that reports as present and has no
// door.
//
// THIS IS A SECOND DOOR, NOT A WEAKENED FIRST ONE. `loadMachineProgram` above
// is byte-unchanged by this order: it still refuses G-CODE TEXT on a controller
// with no interpreter, in the same words, because that refusal is TRUE. What
// was untrue was the implication that nothing could be sent at all. A toolpath
// can, and it comes through here. The two doors do not reach into each other's
// state.
//
// THERE IS ONE SOURCE OF TRUTH FOR "IS A PROGRAM STAGED", AND IT IS THE
// CONTROLLER (Operator's rule, and the whole shape of this slice). Three earlier
// attempts kept an app-side staged flag; every audit round found the same
// disease in a new place - a single global that cannot say WHICH controller
// holds the program, diverging from the board across connect, disconnect and
// backend swap, so a Cycle Start could be armed against a controller that never
// received anything. So the flag is GONE. The controller answers
// `programProgress().total` and `hasActiveJob()`; the app does not keep a
// second copy, and there is nothing left to go stale.
//
// CYCLE START IS THE CONTROLLER'S, NOT A FLAG'S - AND THE APP DOES NOT ASSUME
// A GATE THE BACKEND DOES NOT HAVE. `SimulatedController.startJob()` refuses
// when it holds no staged program; `UccncController.startJob()` does NOT (it
// checks only that motion is allowed, then sends the frame), so leaning on the
// backend's own gate alone would have let a start reach a reconnected bridge
// this session never loaded - the audit found exactly that. The app's part is
// to stop CLAIMING a staged program the current controller session does not
// have: `adoptControllerJobStateAtBoundary` (above) re-reads the controller at
// every connection transition, so the store's job state is always the live
// controller's answer and never the previous session's. That is still one
// source of truth - it is copied from the controller, not maintained beside it.
// This door adds no start gate of its own.
//
// WHAT THIS SLICE IS NOT. There is no load-time zero snapshot, no re-zero guard
// on Cycle Start and no active-WCS check here. All three need a fact the AXBB-E
// bridge does not report today - its active register and that register's
// values - and each one was a place the app's guard-state and the controller's
// staged program could disagree, which is where a wrong cut lives. They land as
// one piece on top of WO-1032 (the bridge reporting its work offset in the
// status frame). Until then the bridge path loads and runs WITHOUT the
// stale-zero guard: for a SUPERVISED straight-line benchmark with Operator at the
// machine that is acceptable, and it is SAID here rather than discovered.
//
// There is no UI on this yet, deliberately: which operator control builds the
// active setup's toolpath and calls it is slice 1d, gated on Operator's UX ruling
// (the geometry path has no file to open, so the existing "load a program"
// affordance is a genuine fork). This door is callable and tested; it is not
// wired to a button.
// ---------------------------------------------------------------------------

/**
 * LOAD A TOOLPATH ONTO THE MACHINE AS A PROGRAM - ALL OR NOTHING.
 *
 * `moves` are WORLD coordinates, exactly as an operation produced them; `trace`
 * names the operation and setup they came from, and the setup is what supplies
 * the WCS the builder transforms against. Reading `project.activeSetupId`
 * instead would let a selection change in the UI silently re-resolve a program
 * against a different zero, so the caller STATES the setup and this refuses if
 * it is gone.
 *
 * EVERYTHING IS VALIDATED BEFORE ANYTHING IS SENT. The controller's capability,
 * the program's shape and the build all have to pass first, so a refusal has
 * nothing to take back: there is no staged-then-refused state, because nothing
 * is staged until the last check has passed. A refusal therefore leaves the
 * machine EXACTLY as it found it - including a program a previous load put
 * there, which is still on the board and which the board itself still reports.
 * What the refusal does change is readiness, which goes not-ready with the
 * reason, so the transport verdict (`deriveOperatorTransport`) refuses Cycle
 * Start until an operator loads something that works. Every failure direction
 * is "refuse", never "start something".
 *
 * A SUCCESSFUL LOAD BECOMES THE SESSION'S PROGRAM. The store's program
 * identity is replaced with this one - this name, and no program TEXT, which a
 * toolpath program genuinely does not have - so nothing is left describing the
 * G-code program that was loaded before it. That matters because the text-only
 * actions (re-arm from the top, run-from-line, step back) key off
 * `programText`: leaving the old text standing would leave
 * an ENABLED "Re-arm from start" that quietly replaces this staged toolpath
 * with the previous program. They now refuse instead. Fit Trace is shared: it
 * reads the staged program's existing preview geometry.
 *
 * NOTHING HERE GATES A STOP. This gates LOADING and nothing else; `stop`,
 * `feedHold`, `pause` and `reset` are as reachable in every state this function
 * produces as they are in any other.
 */
export function loadGeometryProgram(
  name: string,
  moves: readonly ToolpathMove[],
  trace: ProgramTrace,
): { ok: boolean; reason: string | null } {
  clearOperatorStop()
  const state = useCamStore.getState()
  const setup = state.project.setups.find((candidate) => candidate.id === trace.setupId)
  const operation = setup?.operations.find((candidate) => candidate.id === trace.opId)
  const tool = operation === undefined
    ? undefined
    : state.toolLibrary.find((candidate) => candidate.id === operation.toolId)
      ?? state.project.toolLibrary.find((candidate) => candidate.id === operation.toolId)
  const feeds = operation && tool
    ? resolveFeedrates(tool, operation.feedrateOverride, controlMachine(state).rapidRate)
    : undefined
  return loadToolpathProgram(
    name,
    [{ opId: trace.opId, moves, ...(feeds ? { feeds } : {}) }],
    trace.setupId,
  )
}

/**
 * ONE OPERATION'S CONTRIBUTION TO A TOOLPATH PROGRAM (WO-1267).
 *
 * A setup is not one operation, and a program built from it must not say it
 * was. Each section carries the moves an operation produced AND that
 * operation's own id, so every step's `ProgramIndex` entry names the operation
 * that actually made it - which is what the executing-move-id readback is
 * attributed against while the machine runs. A single trace stretched across a
 * whole setup would put a plausible, wrong operation name on every move of
 * every operation but the first.
 */
export interface ToolpathProgramSection {
  opId: string
  moves: readonly ToolpathMove[]
  /** Present on the production setup route. Feed-less semantic roles are
   * materialised from these machine-bounded rates before program building. */
  feeds?: ResolvedFeedrates
}

/**
 * THE DOOR ITSELF - one or many operations, one program, one load.
 *
 * `loadGeometryProgram` is the single-operation face of this and is unchanged
 * in behaviour; `loadSetupToolpathProgram` is the operator's face. Both arrive
 * here, so there is ONE load path to the controller and not two that could
 * drift apart on readiness, parts, path fidelity or the store's program
 * identity.
 */
function loadToolpathProgram(
  name: string,
  sections: readonly ToolpathProgramSection[],
  setupId: string,
  spindle?: ProgramSpindle,
  /** WO-2047: the setup's posted context, shown as its intended stock. */
  setupContext: { context: ProgramContextV1; text: string } | null = null,
): { ok: boolean; reason: string | null } {
  publishNonProgramActionStatus(null)
  const refuse = (reason: string): { ok: false; reason: string } => {
    store().setProgramReadiness({ ready: false, reason })
    store().pushConsole('rx', reason, 'error')
    bumpArmEpoch()
    return { ok: false, reason }
  }

  const ctrl = getMachineController()

  // A LOAD NEVER REACHES INTO A RUNNING JOB, and this refusal changes NOTHING
  // AT ALL - not readiness either - because the running program's own truth is
  // what readiness is currently telling the operator.
  if (controllerJobReallyRuns(ctrl)) {
    return refuseActiveProgramLoad()
  }

  // WHAT THE BACKEND SAYS IT CAN DO, ASKED BEFORE IT IS ASKED TO DO IT
  // (WO-1023's rule: `machineProgram === true`, never `!... === false`; absent
  // means false, which is what an old bridge's `hello` frame sends). A backend
  // that cannot RUN a program is refused here rather than handed one to refuse,
  // so a text/GRBL backend never reaches the load at all.
  if (ctrl.capabilities.machineProgram !== true || typeof ctrl.loadProgram !== 'function') {
    return refuse(
      'This controller cannot run a toolpath program - it reports no program route. '
      + 'Connect the machine bridge (or the simulator) and try again.',
    )
  }
  const loadProgram = ctrl.loadProgram.bind(ctrl)

  const project = useCamStore.getState().project
  const setup = project.setups.find((candidate) => candidate.id === setupId)
  if (setup === undefined) {
    return refuse(
      `Setup "${setupId}" is not in this project, so the work zero this program `
      + 'would be built against is unknown.',
    )
  }
  let resolvedSetup: ReturnType<typeof resolveSetupWorkOffset>
  try {
    resolvedSetup = resolveSetupWorkOffset(project, setup)
  } catch (error) {
    return refuse(
      error instanceof WorkOffsetResolutionError
        ? error.message
        : `Setup "${setup.name}" has no work offset this program can select.`,
    )
  }
  const programWcs = `G${resolvedSetup.fixtureOffset}` as WcsId

  // THE MACHINE'S OWN DECLARED RAPID RATE, READ WHERE THE APP ALREADY READS IT
  // (`controlMachine().rapidRate` - the same field the pendant hands to
  // `jogToSafeZ`). One source, and
  // no second reader that could disagree with it. A machine that declares no
  // rapid rate REFUSES: a rapid carries no feed of its own, the bridge refuses
  // a move without one, and inventing a number here is the defect `4dcf9701`
  // is named after.
  const rapidFeedMmMin = controlMachine(useCamStore.getState()).rapidRate
  if (!(typeof rapidFeedMmMin === 'number' && Number.isFinite(rapidFeedMmMin) && rapidFeedMmMin > 0)) {
    return refuse(
      "This machine declares no rapid rate, so a rapid move's feed cannot be resolved - "
      + "set the machine's rapid traverse rate. A feed is never invented here.",
    )
  }

  // ONE BUILD OVER THE WHOLE PROGRAM, so ids and ordinals are the program's own
  // and not per-operation counters that would collide the moment a second
  // operation joined. The trace the builder stamps is then CORRECTED per
  // section below - the builder takes one trace and this program has several.
  const moves = sections.flatMap((section) => {
    const feeds = section.feeds
    return feeds === undefined
      ? section.moves as ToolpathMove[]
      : section.moves.map((move) => applyResolvedMoveFeed(move, feeds))
  })
  const built = buildStraightLineProgram(moves, resolvedSetup.setup.wcs, rapidFeedMmMin, {
    opId: sections[0].opId,
    setupId,
  }, spindle)
  if (!built.ok) return refuse(built.reason)

  // WO-1285: THE EXTENT CHECK NOBODY HAD. The bridge's soft-limit check at
  // load covers ENDPOINTS ONLY (`Machine.cs:5166`); an arc whose ends are on
  // the table and whose bulge is not would be accepted and driven into a hard
  // stop. So a program with an arc is walked here with its TRUE geometry
  // against the resolved travel and the active work offset, before anything
  // is staged. Lines keep today's path: the bridge and the simulator check
  // their ends as they always did. An arc that cannot be checked is refused
  // too, naming what to declare - a bulge nobody can check is exactly what the
  // bridge waves through.
  if (built.program.steps.some((step) => step.kind === 'arc')) {
    const envelope = currentResolvedMachineMotion().envelope
    const wco = store().offsets[programWcs]
    const originKnown = wco !== undefined && wco.length >= 3 && Number.isFinite(wco[0]) && Number.isFinite(wco[1])
    if (!envelope.x || !envelope.y) {
      return refuse(
        arcsNeedTravelMessage('this program'),
      )
    }
    if (!originKnown) {
      return refuse(
        arcsNeedWorkZeroMessage(programWcs),
      )
    }
    // WO-2219: measured where the controller runs it - turned by the
    // rotation it reports for this offset.
    const offence = firstStepOutsideTravel(
      built.program,
      { x: wco[0], y: wco[1], ...(Number.isFinite(wco[2]) ? { z: wco[2] } : {}) },
      envelope,
      ENVELOPE_FIT_TOLERANCE_MM,
      controllerRotationDeg(programWcs),
    )
    if (offence !== null) return refuse(describeTravelOffence(offence, built.program))
  }
  const motionSteps = built.program.steps.filter(isStagedMove)
  const actionSteps = built.program.steps.filter((step) => !isStagedMove(step))
  const firstStep = built.program.steps[0]
  const lastStep = built.program.steps.at(-1)
  const hasOwnedSpindlePair = spindle !== undefined
    && actionSteps.length === 2
    && firstStep?.kind === 'spindle'
    && firstStep.direction === spindle.direction
    && firstStep.rpm === spindle.rpm
    && lastStep?.kind === 'spindle'
    && lastStep.direction === 'off'
  if (actionSteps.length > 0 && !hasOwnedSpindlePair) {
    return refuse('This program contains action steps; action steps are not wired for program parts yet.')
  }
  // EVERY STEP NAMES THE OPERATION THAT MADE IT.
  //
  // The builder takes ONE trace, so a program built from several operations
  // comes back with the first operation's id stamped on all of it. That is a
  // plausible, wrong answer on every move after the first section - and it is
  // the answer `status.executingMoveId` is attributed against while the machine
  // runs. So the index is corrected here, from the section boundaries.
  //
  // A SINGLE-SECTION PROGRAM IS NOT TOUCHED AT ALL: the builder's own trace is
  // already right, so `loadGeometryProgram` reaches the controller through
  // exactly the code it always did.
  if (sections.length > 1) {
    // The builder emits one step per input move in input order, so the sections
    // are ordinal ranges over `steps`. If that ever stops being true, REFUSE -
    // an index that cannot be trusted is worse than no program.
    if (motionSteps.length !== moves.length) {
      return refuse(
        `The built program has ${motionSteps.length} motion steps for ${moves.length} moves, so `
        + 'each step cannot be traced back to the operation that made it. Nothing was sent.',
      )
    }
    let sectionStart = 0
    for (const section of sections) {
      for (let i = 0; i < section.moves.length; i++) {
        const step = motionSteps[sectionStart + i]
        built.program.index[step.id] = { opId: section.opId, setupId, moveOrdinal: sectionStart + i }
      }
      sectionStart += section.moves.length
    }
  }

  // The program owns ordered spindle intent, but today's controllers explicitly
  // accept a motion-only staged list. Execute the intent at the session boundary
  // and hand only staged moves to the board, preserving their original ids and
  // index entries. A spindle frame therefore cannot consume a motion slot.
  const motionIndex: MachineProgram['index'] = {}
  for (const step of motionSteps) motionIndex[step.id] = built.program.index[step.id]
  const motionProgram: MachineProgram = {
    frame: built.program.frame,
    units: built.program.units,
    steps: motionSteps,
    index: motionIndex,
  }

  // WO-1054 materialises WO-1044's rapid-boundary plan. Each controller load
  // remains at or below its declared cap; a program with no safe rapid stays a
  // refusal before the wire. A fitting program takes the old path byte for
  // byte: the original MachineProgram is handed to loadProgram once.
  const partitioned = buildProgramParts(
    motionProgram,
    resolveMaxProgramMoves(ctrl.capabilities),
  )
  const capacity = partitioned.capacity
  if (!partitioned.ok) return refuse(partitioned.reason)
  // WO-1275: and the one boundary the toolpath declares for itself - the first
  // cut. A program this session commands a spindle for is staged as approach
  // then cut, so the approach can run WHILE the spindle comes up to speed
  // instead of waiting behind it. A program with no spindle intent of ours is
  // untouched: there is nothing to spin up and nothing to gate.
  const programs = spindle === undefined
    ? partitioned.parts
    : splitApproachFromFirstCut(partitioned.parts)
  const motion = motionSteps as readonly QueuedMove[]
  // A fitting, unsplit program still takes the old path byte for byte - the
  // original `motionProgram` is handed to `loadProgram` once, including the
  // empty program the plan describes as no parts at all.
  const firstProgram = capacity.fits && programs.length <= 1 ? motionProgram : programs[0]
  const stageSelectedProgram = (): { ok: boolean; reason: string | null } => {
    const previousPartsRun = programPartsRun
    const previousPartsTerminal = programPartsTerminal
    programPartsTerminal = null
    programPartsRun = programs.length > 1
      ? {
          controller: ctrl,
          parts: programs,
          partIndex: 0,
          completedMoves: 0,
          totalMoves: capacity.count,
          completionSignaled: false,
          advancing: false,
          heldBetweenParts: false,
          started: false,
        }
      : null

  // EVERY CHECK HAS PASSED, SO THE PROGRAM GOES TO THE CONTROLLER - which
  // REPLACES whatever it was holding. That is `loadMoves`' own contract (the
  // staged list is overwritten, and the bridge's `Machine.LoadMoves` does the
  // same), so the controller manages its own staged queue and the app never
  // needs a separate disarm step it could get out of order.
  const outcome = loadProgram(firstProgram)
  if (!outcome.ok) {
    programPartsRun = previousPartsRun
    programPartsTerminal = previousPartsTerminal
    // Both backends validate before they stage (`loadProgram` checks the
    // capability and the program, THEN calls `loadMoves`), so a refusal here
    // staged nothing - the board is still holding whatever it held, and it is
    // still the one reporting that.
    return refuse(outcome.reason ?? 'The controller refused this program without giving a reason.')
  }
  // WO-1275: what is on the board NOW - the approach when the program was
  // split, the whole thing when it was not. The release gate asks this.
  stagedMotionCuts = programCuts(firstProgram)
  // WO-1335 fix round 3: a toolpath program states no coolant word, so nothing
  // is pending - and a file loaded before it must not leave one behind.
  geometryProgramCoolant = null
  geometryProgramSpindle = spindle
    ? {
        ...spindle,
        controller: ctrl,
        running: false,
        saidNoSpindleLink: false,
        commandedAgainstStatus: null,
      }
    : null
  sayProbeAtToolpathLoad(name)

  // THIS PROGRAM IS NOW THE SESSION'S PROGRAM, AND THE ONE BEFORE IT IS OVER.
  //
  // The controller's staged queue was just replaced, so anything in the store
  // still describing the PREVIOUS program is a second, contradicting answer to
  // "which program is loaded" - the exact split this order keeps being audited
  // for, arriving through the text door instead of the controller. Left alone,
  // `programText` still held the last G-code program, `deriveReArm` read it and
  // offered an ENABLED "Re-arm from start", and `armProgramFromTop` followed
  // that offer into `loadMachineProgram(job.name, programText)` - quietly
  // replacing the staged toolpath with the old text program. A control that
  // says "re-arm THIS program" must not arm a different one.
  //
  // So the identity moves with the load: this program's name, and NO program
  // text, because a geometry program has none and inventing one would be the
  // same lie in the other direction. That single honest statement closes every
  // text-only path at once - `armProgramFromTop`, `armRunFromLine` and
  // `stepBack` all already refuse on a null `programText` - rather than adding
  // separate guards that could each fall out of step. Fit Trace reads the
  // staged geometry above. It runs ONLY here, after the controller has accepted the
  // program: a refused load leaves the previous program's identity standing,
  // because a refused load leaves the previous program STAGED.
  const listing: StagedProgramView = {
    program: motionProgram,
    setups: motionProgram.steps.length === 0
      ? []
      : [{
          setupName: resolvedSetup.setup.name,
          setupId: resolvedSetup.setup.id,
          wcs: programWcs,
          firstStepId: motionProgram.steps[0].id,
        }],
  }
  const verifiedContext = setupContext ? verifiedStagedContext(name, setupContext.text, setupContext.context) : null
  // A one-setup context: every step is that setup's, so no step maps to a line.
  stagedProgramContextValue = verifiedContext && setupContext
    ? { listing, context: verifiedContext, text: setupContext.text, lineOfStep: () => undefined }
    : null
  store().setProgram(name, null, [], null, listing)
  clearTransferReview()
  // The counters the operator reads come off the controller, so they are
  // RE-READ rather than assumed. A replaced queue still reporting the previous
  // program's total is the same lie one level further down. `setProgram` resets
  // the job to empty, so this re-read is what fills it in - from the controller.
  store().applyJobProgress(wholeProgramProgress(ctrl.jobProgress()))
  // The operator-facing count comes from the BUILDER's steps that occupy a
  // board slot. The controller ring is now a streaming window, not a program
  // length ceiling, so a runnable program's load line does not advertise it.
  const loadedReason = `Toolpath program "${name}" loaded: ${built.motionCount} moves, runs in `
    + `${programWcs}.`
  // THE CAP'S OWN PARTS, NOT WO-1275's APPROACH SPLIT. This sentence answers
  // "does this program fit on the board", so it counts the parts the CAPACITY
  // plan needed. The approach/cut boundary is not a capacity fact and telling
  // an operator that a four-move program "runs in 2 parts" would be a second,
  // wrong answer to the only question this line is asked.
  const partsReason = partitioned.parts.length > 1
    ? `program has ${capacity.count} moves - running in ${partitioned.parts.length} parts`
    : null
  store().setProgramReadiness({ ready: true, reason: partsReason ?? loadedReason })
  store().pushConsole('rx', loadedReason, 'info')
  if (partsReason) store().pushConsole('rx', partsReason, 'info')

  // WO-1008's geometry door, finally reached by a real program. THE WHOLE POINT
  // OF "MEASURE OUR SOFTWARE": a geometry run is observed against the moves the
  // product itself commanded, with the ids the controller reports back, in the
  // frame the program declares.
  armPathFidelityFromMoves(motion, built.program.frame)
  // WO-1874: everything above armed on "accepted for sending". If the board
  // answers that it refused the load, none of it is true and it comes back off.
  watchBoardLoadRefusal(
    ctrl,
    () => loadRevision === geometryProgramLoadRevision,
    (reason) => disarmRefusedProgramLoad(ctrl, reason),
  )
  bumpArmEpoch()
  return { ok: true, reason: null }
  }

  // Work-coordinate moves are not self-locating: the bridge applies whichever
  // WCS it holds when loadMoves arrives. Select this setup's resolved frame and
  // wait for the bridge's reply before staging even the approach. A later load
  // supersedes an older receipt, so two quick operator choices cannot let the
  // first reply stage the wrong program after the second one.
  const loadRevision = ++geometryProgramLoadRevision
  if (typeof ctrl.selectWcsAwait === 'function') {
    const reportedOffset = currentWorkOffsets().byWcs[programWcs]
    if (!reportedOffset || !['x', 'y', 'z'].every((axis) =>
      Number.isFinite(reportedOffset[axis as keyof typeof reportedOffset]))) {
      return refuse(
        `${programWcs} is not fully set on this controller, so nothing was staged. `
        + `Set the X, Y and Z work zero for ${programWcs}, then load the program again.`,
      )
    }
    const receiptToken = captureBackendReceipt(ctrl)
    const receipt = ctrl.selectWcsAwait(programWcs)
    if (receipt === null) {
      return refuse(`The controller would not select ${programWcs}, so nothing was staged.`)
    }
    store().setProgramReadiness({
      ready: false,
      reason: `Waiting for the controller to confirm ${programWcs} before staging this program.`,
    })
    void receipt.then((confirmed) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) return
      if (!confirmed) {
        refuse(`The controller did not confirm ${programWcs}, so nothing was staged.`)
        return
      }
      store().setActiveWcs(programWcs)
      if (controllerJobReallyRuns(ctrl)) {
        refuse('The program started running before its work offset was confirmed; nothing new was staged.')
        return
      }
      stageSelectedProgram()
      ctrl.refreshState()
    }).catch((error) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) return
      const detail = error instanceof Error ? error.message : String(error)
      refuse(`The controller did not confirm ${programWcs} (${detail}), so nothing was staged.`)
    })
    return { ok: true, reason: null }
  }

  if (!ctrl.selectWcs(programWcs)) {
    return refuse(`The controller would not select ${programWcs}, so nothing was staged.`)
  }
  store().setActiveWcs(programWcs)
  return stageSelectedProgram()
}

/**
 * WHICH DOOR THIS CONTROLLER'S PROGRAMS COME THROUGH (WO-1267).
 *
 * ONE QUESTION, ASKED OF THE CONTROLLER: does it execute G-CODE TEXT? A
 * controller that does keeps the text door and everything behind it - the
 * post, the program context, the line list, run-from-line, re-arm from start -
 * byte for byte. A controller that does not has no interpreter to give text
 * to, so a setup can only reach it as a toolpath program.
 *
 * IT IS NOT ASKED AS `machineProgram === true`, and that is deliberate. A
 * controller with neither route is a real machine an operator can be connected
 * to (an un-updated AXBB-E bridge), and sending it G-code so the text door can
 * say "it cannot run this program" answers the wrong question: it CAN run a
 * program, it just has no route to be given one. The toolpath door names that
 * missing route - "it reports no program route, connect the machine bridge" -
 * which is the sentence that tells the operator what to do next.
 */
export function controllerNeedsToolpathProgram(): boolean {
  // WO-1046's rule, kept: the text capability has ONE reader in this module and
  // every panel asks it. This is that reader inverted, not a second copy - and
  // it inherits its "no backend installed means yes, there is a text path"
  // answer, so a render with nothing connected takes the unchanged text route
  // and never installs a backend as a side effect.
  return !controllerTakesGcodeText()
}

/**
 * WHETHER THIS CONTROLLER CAN RUN A TOOLPATH PROGRAM AT ALL (WO-1323).
 *
 * A different question from `controllerNeedsToolpathProgram`, and the right
 * one for the multi-setup entry. "Needs" asks whether the TEXT door is
 * missing; this asks whether the PROGRAM door is present. They differ on
 * exactly one connection - the simulator, which has both - and the multi-setup
 * program is a toolpath program, so it is offered wherever a toolpath program
 * can run. A G-code-only controller sees no such entry: the post's combined
 * program in the Post Process modal is that route's answer, and a second,
 * differently built answer to the same question in the operator's Load menu is
 * how two routes to one machine start disagreeing about what the part is.
 */
export function controllerCanRunToolpathProgram(): boolean {
  const ctrl = getMachineController()
  return ctrl.capabilities.machineProgram === true && typeof ctrl.loadProgram === 'function'
}

/**
 * THE HANDLE ON THE GEOMETRY DOOR (WO-1267).
 *
 * WO-1019 built this door and slice 1c left it deliberately unwired: "which
 * operator control builds the active setup's toolpath and calls it is slice
 * 1d, gated on Operator's UX ruling". Slice 1d never came, so on Operator's AXBB-E -
 * the one machine the door was built for - Load posted G-code the board cannot
 * read, "Re-arm from start" sat lit and did nothing, and CYCLE START could
 * never enable. The capability reported as present and had no handle, which is
 * the defect WO-1019's own comment named one level up.
 *
 * THE UX FORK RESOLVED ITSELF, and this is the decide-and-log: there is no
 * second affordance. The operator picks a setup from the SAME "Load setup"
 * menu they already use, and the controller decides which door that setup goes
 * through. A geometry machine needs no new button and a text machine sees no
 * change at all.
 *
 * THE MOVES ARE THE ONES THE POST WOULD HAVE SENT. `collectToolpathSections`
 * is the post's own collector (`buildPostInput`), so the toolpath door and the
 * text door machine the same operations, in the same order, with the same nest
 * expansion. Two routes to the same machine that disagreed about what the
 * setup IS would be a worse defect than the one this closes.
 *
 * WHAT IT DOES NOT DO, said rather than discovered: no tool change, coolant
 * command, header or footer. `buildStraightLineProgram` emits motion bracketed
 * by one resolved spindle start/stop pair when the machine and live controller
 * declare that path. A multi-TOOL setup would load as continuous motion with
 * no pause to change the tool, so it never goes through this builder.
 *
 * WO-2013 (Operator at the machine, 2026-09-25): that setup used to be REFUSED -
 * "a toolpath program carries motion only - it cannot stop for a tool change"
 * - while the posted .nc of the same setup loaded with "Program checks passed"
 * and held at each change. The software could run it (rule 11). It now does
 * exactly that: the setup is posted and the text goes through the file door
 * (`loadSetupPostedProgram`), so the stops at each M6 - and the post's M0 when
 * "Pause (M0) after tool change" is on - are the file door's, not a second
 * copy.
 */
async function stageSetupToolpathProgram(
  setupId: string,
): Promise<{ ok: boolean; reason: string | null }> {
  forgetKeptStop()
  const collected = await collectSetupProgramSections(setupId)
  if (!collected.ok) {
    return collected.toolChange === true
      ? loadSetupPostedProgram(setupId)
      : refuseProgramLoad(collected.reason)
  }
  // WO-2437: an operator stop (retract, park, message, wait) is written by the
  // post, so a setup with one loads as its posted file - the same door a setup
  // that changes tools takes - and never runs without its stop.
  if (setupHasOperatorStops(collected.value.setup)) return loadSetupPostedProgram(setupId)
  return loadToolpathProgram(
    `${collected.value.setup.name} (toolpath)`,
    collected.value.sections,
    setupId,
    collected.value.spindle,
    setupToolpathContext(setupId),
  )
}

/** The operator's Load of a setup - `stageSetupToolpathProgram`, then the 3D
 *  view frames what it staged (WO-2675). */
export async function loadSetupToolpathProgram(
  setupId: string,
): Promise<{ ok: boolean; reason: string | null }> {
  const loaded = await stageSetupToolpathProgram(setupId)
  if (loaded.ok) bumpProgramLoadEpoch()
  return loaded
}

/** WO-2047: a one-tool setup staged as a toolpath program has no text of its
 *  own, so its intended stock comes from the program the post writes for the
 *  same setup - the moves `collectToolpathSections` gives both doors. Null
 *  when that post refuses; the toolpath still loads, with no intended stock. */
function setupToolpathContext(setupId: string): { context: ProgramContextV1; text: string } | null {
  const state = useCamStore.getState()
  const project = { ...state.project, toolLibrary: state.toolLibrary }
  const setup = project.setups.find((candidate) => candidate.id === setupId)
  if (setup === undefined) return null
  const resolution = resolveDeclaredController(project.machine)
  if (!resolution.ok) return null
  try {
    const posted = postProject(project, [setup], resolution.dialect, {
      mode: 'combined',
      pauseBetweenSetups: false,
      baseName: 'control',
      ext: 'nc',
      modelRefsVerifiedSinceLoad: state.modelRefsVerifiedSinceLoad,
    })
    return postedSetupContext(project, setup, resolution.dialect, posted)
  } catch (err) {
    console.error('[program-context] setup could not be posted for its context:', err)
    return null
  }
}

/**
 * A SETUP THAT CHANGES TOOLS, AS ITS POSTED FILE (WO-2013).
 *
 * Posted the way Control's text route posts a setup (`ProgramPanel`'s
 * `loadFromSetup`: the machine's declared dialect, one combined program) and
 * staged by the file door's own loader, so the program staged here equals,
 * move for move and stop for stop, what loading that posted .nc stages. The
 * file door owns every tool-change behaviour (WO-1335 boundary, WO-1997 one
 * stop per M6); nothing about it is re-decided here.
 */
/** WO-2437: does this setup carry an operator stop the post writes? */
function setupHasOperatorStops(setup: Setup): boolean {
  return Array.isArray(setup.machineActions)
    && setup.machineActions.some((action) => action.kind === 'operator_stop' && action.enabled !== false)
}

/** WO-2437: SETUPS WITH AN OPERATOR STOP, AS ONE POSTED FILE. The stop is the
 *  post's (retract, park, message, M0), so several setups where any carries one
 *  load as the combined program Post Process writes for them, through the file
 *  door, in the order chosen, each staged first as every Control load is. The
 *  Load menu's "Continue through the setups" decides a boundary that only
 *  changes the work offset, as it does on the toolpath route; the post adds no
 *  second pause. */
async function loadSetupsPostedProgram(
  setupIds: readonly string[],
  runThrough: boolean,
): Promise<{ ok: boolean; reason: string | null }> {
  // The recompute every Control load and Post stage before they read the
  // moves (WO-1653), for each chosen setup - so a recoverable edit is
  // regenerated here, not refused - and the project read after it.
  for (const setupId of setupIds) {
    await useCamStore.getState().stageOperationsForEmission(setupId, undefined)
  }
  const state = useCamStore.getState()
  const project = { ...state.project, toolLibrary: state.toolLibrary }
  const setups = setupIds.map((id) => project.setups.find((candidate) => candidate.id === id))
  const missing = setupIds.find((_, index) => setups[index] === undefined)
  if (missing !== undefined) {
    return refuseProgramLoad(`Setup "${missing}" is not in this project, so there is nothing to load.`)
  }
  const resolution = resolveDeclaredController(project.machine)
  if (!resolution.ok) return refuseProgramLoad(resolution.reason)
  const posted = postProject(project, setups as Setup[], resolution.dialect, {
    mode: 'combined',
    pauseBetweenSetups: false,
    baseName: 'control',
    ext: 'nc',
    modelRefsVerifiedSinceLoad: state.modelRefsVerifiedSinceLoad,
  })
  if (!posted.ok || !posted.combined) {
    const firstErrors = posted.diagnostics
      .filter((diagnostic) => diagnostic.level === 'error')
      .slice(0, 3)
      .map((diagnostic) => diagnostic.message)
      .join(' ')
    return refuseProgramLoad(
      `These setups are not ready to post: ${firstErrors || 'post refused'}. `
      + 'Fix it in the Post Process modal, then reload here.',
    )
  }
  const name = `${(setups as Setup[]).map((setup) => setup.name).join(' + ')} (posted)`
  const loaded = loadGcodeTextToolpathProgram(name, posted.combined.gcode, {
    publishListing: true,
    runThroughOffsetChanges: runThrough,
  })
  fillToolTableFromProgram(name, posted.combined.gcode)
  sayReferenceToolNeeded(name, programFixedPadChanges(loaded.ok))
  return loaded
}

function loadSetupPostedProgram(setupId: string): { ok: boolean; reason: string | null } {
  // The same project view `collectSetupProgramSections` just validated - read
  // after its staging, with the live tool library merged, as the post reads it.
  const state = useCamStore.getState()
  const project = { ...state.project, toolLibrary: state.toolLibrary }
  const setup = project.setups.find((candidate) => candidate.id === setupId)
  if (setup === undefined) {
    return refuseProgramLoad(`Setup "${setupId}" is not in this project, so there is nothing to load.`)
  }
  const resolution = resolveDeclaredController(project.machine)
  if (!resolution.ok) return refuseProgramLoad(resolution.reason)
  const posted = postProject(project, [setup], resolution.dialect, {
    mode: 'combined',
    pauseBetweenSetups: false,
    baseName: 'control',
    ext: 'nc',
    modelRefsVerifiedSinceLoad: state.modelRefsVerifiedSinceLoad,
  })
  if (!posted.ok || !posted.combined) {
    const firstErrors = posted.diagnostics
      .filter((diagnostic) => diagnostic.level === 'error')
      .slice(0, 3)
      .map((diagnostic) => diagnostic.message)
      .join(' ')
    return refuseProgramLoad(
      `Setup "${setup.name}" is not ready to post: ${firstErrors || 'post refused'}. `
      + 'Fix it in the Post Process modal, then reload here.',
    )
  }
  // `loadGcodeFile`'s program door, step for step: the file is staged, and the
  // tools it calls go into the tool table ready to measure.
  const name = `${setup.name} (posted)`
  // WO-2047: the context Control's text route binds to this same post, so the
  // staged program shows the setup's intended stock.
  const context = postedSetupContext(project, setup, resolution.dialect, posted)?.context ?? null
  const loaded = loadGcodeTextToolpathProgram(name, posted.combined.gcode, { publishListing: true, context })
  fillToolTableFromProgram(name, posted.combined.gcode)
  sayReferenceToolNeeded(name, programFixedPadChanges(loaded.ok))
  return loaded
}

/**
 * ONE PROGRAM, MORE THAN ONE SETUP (WO-1323).
 *
 * THE CAPABILITY ITEM 5.5 ASKED FOR AND DID NOT HAVE. WO-1312 landed the
 * single-setup half: a setup selects its own work offset, waits for the
 * bridge's receipt, and names the frame on the load line. What no route
 * reached was the one that matters for a part needing two fixtures - ONE
 * program that runs setup 1 at its zero, switches, and runs setup 2 at a
 * different one. The posted combined `.nc` is G-code text this controller has
 * no interpreter for, and the Load menu offered setups singly.
 *
 * HOW THE FRAME SWITCHES, IN ONE SENTENCE: the program is planned as one stage
 * per setup, each a self-contained set of controller-sized parts, and the
 * frame is selected AT THE STAGE BOUNDARY - after the outgoing setup's retract
 * has been REPORTED reached, and before anything of the next setup is staged.
 * `crossSetupBoundary` is where that happens and it is the only place; the
 * selection itself is WO-1312's `selectWcsAwait` receipt, called again rather
 * than reimplemented.
 *
 * WHAT IS REFUSED BEFORE THE FIRST MOVE, whole, naming the setup:
 *  - a setup whose frame the controller does not have set (all of them are
 *    asked, not just the first - a program that discovered an unset G55 after
 *    cutting setup 1 would have already moved the machine),
 *  - two setups sharing one frame, which is not a switch at all,
 *  - a setup whose tool is not in the tool library, because a program that
 *    cannot name its tools cannot tell the operator which one to fit,
 *  - TWO ADJACENT SETUPS ON ONE TOOL ASKING FOR DIFFERENT SPINDLE SPEEDS OR
 *    DIRECTIONS, or one that commands the spindle and one that does not. A run
 *    of setups sharing a tool carries ONE spindle intent. (Until 2026-09-11 any
 *    spindle intent was refused here on the belief that the up-to-speed gate
 *    was armed once per load; it is not - see the loop below - and the refusal
 *    closed the all-setups door on Operator's machine, where every real program
 *    commands the spindle.)
 *
 * WHAT IS NO LONGER REFUSED (WO-1330, Operator at the machine 2026-09-11): TWO
 * SETUPS NEEDING DIFFERENT TOOLS. That boundary is a TOOL-CHANGE SEQUENCE -
 * the retract-clear check, the spindle stopped, a hold that permits jog and the
 * incoming frame's Z work zero and nothing else, then CYCLE START arming the
 * gate for the new tool's speed. The spindle rule above steps aside exactly at
 * such a boundary, because the tool the intent belonged to has just changed.
 *
 * WHETHER IT STOPS BETWEEN THE SETUPS IS THE OPERATOR'S, AND IT DOES NOT BY
 * DEFAULT (WO-1329, Operator from the machine 2026-09-11). `runThrough` is the
 * Load menu's "Continue through the setups" box, which is on unless they turn
 * it off; off gives WO-1323's hold at every boundary, word for word. It can
 * only ever make a SAME-TOOL boundary continuous: a tool-change boundary is
 * never run through whatever the box says, because the thing the box skips is
 * the operator, and a tool change is the operator. The load line says so.
 */
async function stageSetupsToolpathProgram(
  setupIds: readonly string[],
  options: { runThrough?: boolean },
): Promise<{ ok: boolean; reason: string | null }> {
  forgetKeptStop()
  if (setupIds.length === 0) {
    return refuseProgramLoad('No setup was chosen, so there is nothing to load.')
  }
  // ONE SETUP IS THE SINGLE-SETUP DOOR, BYTE FOR BYTE. Item 5.5 runs 1 and 2
  // are that door's measured behaviour and this order does not touch them.
  if (setupIds.length === 1) return stageSetupToolpathProgram(setupIds[0])

  // ON UNLESS THE OPERATOR TURNED IT OFF. A caller that says nothing gets the
  // continuous run, which is what Operator asked the default to be.
  const runThrough = options.runThrough !== false

  // WO-2437: any setup with an operator stop - the program is the posted file.
  const chosen = useCamStore.getState().project.setups.filter((setup) => setupIds.includes(setup.id))
  if (chosen.some(setupHasOperatorStops)) return loadSetupsPostedProgram(setupIds, runThrough)

  const ctrl = getMachineController()
  if (controllerJobReallyRuns(ctrl)) {
    return refuseActiveProgramLoad()
  }
  if (ctrl.capabilities.machineProgram !== true || typeof ctrl.loadProgram !== 'function') {
    return refuseProgramLoad(
      'This controller cannot run a toolpath program - it reports no program route. '
      + 'Connect the machine bridge (or the simulator) and try again.',
    )
  }
  const loadProgram = ctrl.loadProgram.bind(ctrl)

  const state = useCamStore.getState()
  const project = { ...state.project, toolLibrary: state.toolLibrary }
  const rapidFeedMmMin = controlMachine(state).rapidRate
  if (!(typeof rapidFeedMmMin === 'number' && Number.isFinite(rapidFeedMmMin) && rapidFeedMmMin > 0)) {
    return refuseProgramLoad(
      "This machine declares no rapid rate, so a rapid move's feed cannot be resolved - "
      + "set the machine's rapid traverse rate. A feed is never invented here.",
    )
  }

  const inputs: MultiSetupInput[] = []
  const frames: WcsId[] = []
  // ONE SPINDLE INTENT FOR THE WHOLE PROGRAM. The up-to-speed gate is not armed
  // once per load: every startJob and resumeJob goes through
  // runWithGeometryProgramSpindle, so it is re-asked at every boundary. At a
  // HELD boundary the pause stops the spindle and the operator's CYCLE START
  // restarts it and holds motion until it is at speed again; at a WO-1329
  // run-through boundary the spindle was never stopped, so the same gate reads
  // the inverter still at speed and releases the next stage at once. What a
  // two-setup program cannot do either way is change speed or direction at the
  // boundary, so a program that asks for that is refused at the door, naming
  // both setups.
  const spindleIntents: {
    setupName: string
    spindle: ProgramSpindle | undefined
    atToolChange: ProgramSpindle | null
  }[] = []
  for (const setupId of setupIds) {
    const collected = await collectSetupProgramSections(setupId)
    if (!collected.ok) return refuseProgramLoad(collected.reason)
    const { setup, sections, toolIds, spindle } = collected.value

    // THE TOOL THIS SETUP CUTS WITH, BY NAME. The planner compares tools across
    // setups and refuses a program that would have to change one mid-run, and
    // that refusal names the tool the operator would have had to fit - so a tool
    // the library cannot name is refused here rather than leaving a refusal
    // downstream with nothing to say.
    const toolId = toolIds[0]
    const tool = toolId === undefined
      ? undefined
      : project.toolLibrary.find((candidate) => candidate.id === toolId)
    if (toolId === undefined || tool === undefined) {
      return refuseProgramLoad(
        `Setup "${setup.name}" cuts with a tool that is not in the tool library, so this program `
        + 'cannot tell you which tool each setup needs. Nothing was staged.',
      )
    }
    // WO-1330: THE SPEED THIS SETUP'S TOOL RUNS AT, whether or not the machine
    // record names a spindle link. `spindle` is the program's intent and stays
    // gated on the record; this is what a tool-change hold restarts the spindle
    // at when the connection can drive it, and names when it cannot.
    const firstOperation = setup.operations.find((candidate) => candidate.id === sections[0].opId)
    const toolSpindle = firstOperation === undefined
      ? null
      : resolveSpindle(firstOperation, tool, project.machine)
    spindleIntents.push({
      setupName: setup.name,
      spindle,
      atToolChange: toolSpindle === null ? null : { rpm: toolSpindle.rpm, direction: toolSpindle.dir },
    })

    let resolvedSetup: ReturnType<typeof resolveSetupWorkOffset>
    try {
      resolvedSetup = resolveSetupWorkOffset(project, setup)
    } catch (error) {
      return refuseProgramLoad(
        error instanceof WorkOffsetResolutionError
          ? error.message
          : `Setup "${setup.name}" has no work offset this program can select.`,
      )
    }
    const wcsId = `G${resolvedSetup.fixtureOffset}` as WcsId
    frames.push(wcsId)
    inputs.push({
      setupId,
      setupName: setup.name,
      wcsId,
      wcs: resolvedSetup.setup.wcs,
      tool: { id: toolId, label: describeProgramTool(tool) },
      // The feeds each section is entitled to, materialised before the build -
      // the same step the single-setup load takes, in the same place relative
      // to it, so both routes hand the builder identical moves.
      sections: sections.map((section) => ({
        opId: section.opId,
        moves: section.feeds === undefined
          ? section.moves
          : section.moves.map((move) => applyResolvedMoveFeed(move, section.feeds!)),
      })),
    })
  }

  // EVERY FRAME, ASKED BEFORE THE FIRST MOVE. A program that discovered an
  // unset G55 at the boundary would already have cut setup 1 and moved the
  // machine, so the whole program is refused here instead - naming the setup
  // AND the frame, which is what tells the operator where to go next.
  // WO-1330: ADJACENT PAIRS, AND A TOOL CHANGE IS WHERE THE RULE STEPS ASIDE.
  // A run of setups sharing one tool still carries one spindle intent, because
  // nothing between them stops the inverter to change it. A boundary that DOES
  // change tool stops the spindle by definition, and the operator's CYCLE START
  // out of that hold arms the up-to-speed gate for the incoming tool's speed -
  // so two setups separated by a change may ask for different speeds, and a
  // 3 mm ball asked to run at a 6 mm flat's RPM is the thing this used to force.
  for (let i = 1; i < spindleIntents.length; i++) {
    const first = spindleIntents[i - 1]
    const candidate = spindleIntents[i]
    if (inputs[i - 1].tool.id !== inputs[i].tool.id) continue
    if (first.spindle === undefined && candidate.spindle === undefined) continue
    if (first.spindle === undefined || candidate.spindle === undefined) {
      const commands = first.spindle === undefined ? candidate : first
      const silent = first.spindle === undefined ? first : candidate
      return refuseProgramLoad(
        `"${commands.setupName}" would command the spindle and "${silent.setupName}" would not, so this `
        + 'program cannot say what the spindle should do between them. Run these setups one at a time.',
      )
    }
    if (first.spindle.rpm !== candidate.spindle.rpm || first.spindle.direction !== candidate.spindle.direction) {
      return refuseProgramLoad(
        `"${first.setupName}" asks for the spindle at ${first.spindle.rpm} RPM ${first.spindle.direction.toUpperCase()} `
        + `and "${candidate.setupName}" at ${candidate.spindle.rpm} RPM ${candidate.spindle.direction.toUpperCase()}. `
        + 'A program spanning setups keeps one spindle speed and direction; run these setups one at a time.',
      )
    }
  }
  const programSpindle = spindleIntents[0]?.spindle

  const reportedOffsets = currentWorkOffsets().byWcs
  const offsetOf = (wcs: WcsId): { x: number; y: number; z: number } | null => {
    const reported = reportedOffsets[wcs]
    if (!reported) return null
    const { x, y, z } = reported
    if (![x, y, z].every((value) => typeof value === 'number' && Number.isFinite(value))) return null
    return { x: x!, y: y!, z: z! }
  }
  for (const input of inputs) {
    if (offsetOf(input.wcsId as WcsId) === null) {
      return refuseProgramLoad(
        `Setup "${input.setupName}" runs in ${input.wcsId}, which is not fully set on this controller, `
        + `so nothing was staged. Set the X, Y and Z work zero for ${input.wcsId}, then load the `
        + 'program again.',
      )
    }
  }

  const cap = resolveMaxProgramMoves(ctrl.capabilities)
  const planned = planMultiSetupProgram(inputs, rapidFeedMmMin, cap)
  if (!planned.ok) return refuseProgramLoad(planned.reason)
  const plan = planned.plan

  // WO-1285's extent check, ONCE PER STAGE, against THAT stage's own offset.
  // A single check against one frame would measure setup 2's arcs from setup
  // 1's zero - which is the same class of mistake this order is about.
  const envelope = currentResolvedMachineMotion().envelope
  for (const stage of plan.stages) {
    const steps = plan.parts
      .slice(stage.firstPartIndex, stage.firstPartIndex + stage.partCount)
      .flatMap((part) => part.steps)
    if (!steps.some((step) => step.kind === 'arc')) continue
    if (!envelope.x || !envelope.y) {
      return refuseProgramLoad(
        arcsNeedTravelMessage(`setup "${stage.setupName}"`),
      )
    }
    const wco = offsetOf(stage.wcsId as WcsId)!
    const offence = firstStepOutsideTravel(
      { frame: 'work', units: 'mm', steps, index: plan.program.index },
      wco,
      envelope,
      ENVELOPE_FIT_TOLERANCE_MM,
      controllerRotationDeg(stage.wcsId),
    )
    if (offence !== null) {
      return refuseProgramLoad(
        `Setup "${stage.setupName}": ${describeTravelOffence(offence, plan.program)}`,
      )
    }
  }

  // THE BOUNDARIES, AS THE RUN WILL MEET THEM. `clearMachineZ` is the outgoing
  // stage's retract height carried into MACHINE coordinates with that stage's
  // own offset - machine = work + offset - because that is the frame the
  // machine reports its position in, and comparing a reported machine Z against
  // a work-frame number is how the check would pass while the tool was down.
  const boundaries = new Map<number, ProgramSetupBoundary>()
  for (let i = 1; i < plan.stages.length; i++) {
    const finished = plan.stages[i - 1]
    const next = plan.stages[i]
    const finishedOffset = offsetOf(finished.wcsId as WcsId)!
    // WO-1330: THE BOX IS NOT CONSULTED AT A TOOL CHANGE. `runThrough` is what
    // the operator asked for; a boundary that changes tool overrides it here,
    // once, so no later code has to remember to.
    const changesTool = finished.tool.id !== next.tool.id
    boundaries.set(next.firstPartIndex, {
      finishedName: finished.setupName,
      nextName: next.setupName,
      fromWcs: finished.wcsId as WcsId,
      wcs: next.wcsId as WcsId,
      clearMachineZ: finished.retractWorkZ === null
        ? null
        : finished.retractWorkZ + finishedOffset.z,
      runThrough: runThrough && !changesTool,
      ...(changesTool
        ? {
            toolChange: {
              leaving: finished.tool.label,
              fit: next.tool.label,
              spindle: spindleIntents[i].spindle ?? spindleIntents[i].atToolChange,
            },
          }
        : {}),
    })
  }

  const name = `${plan.stages.map((stage) => stage.setupName).join(' + ')} (toolpath)`
  const loadedReason = describeMultiSetupLoad(name, plan, runThrough, spindleRoute(ctrl) === 'calls')
  // WO-1330: "This program does not stop between setups" is FALSE of a program
  // that changes tool, and the load line has already said where it stops. A
  // sentence the operator can read as a promise of a continuous run is worse
  // than silence, so a tool-change program does not get this one.
  const continuationLine = runThrough && !planChangesTool(plan)
    ? describeSetupContinuation(plan)
    : null
  const firstPart = plan.parts[0]

  const stagePlannedProgram = (): { ok: boolean; reason: string | null } => {
    const previousPartsRun = programPartsRun
    const previousPartsTerminal = programPartsTerminal
    programPartsTerminal = null
    programPartsRun = {
      controller: ctrl,
      parts: plan.parts,
      partIndex: 0,
      completedMoves: 0,
      totalMoves: plan.motionCount,
      completionSignaled: false,
      advancing: false,
      heldBetweenParts: false,
      started: false,
      boundaries,
      ...(continuationLine === null
        ? {}
        : { continuation: { line: continuationLine, saidAtMs: sessionElapsedNowMs() } }),
    }
    const outcome = loadProgram(firstPart)
    if (!outcome.ok) {
      programPartsRun = previousPartsRun
      programPartsTerminal = previousPartsTerminal
      return refuseProgramLoad(
        outcome.reason ?? 'The controller refused this program without giving a reason.',
      )
    }
    stagedMotionCuts = programCuts(firstPart)
    // The program's one spindle intent, if it has one. This route does not
    // split an approach off the first cut, so the gate holds the whole first
    // stage until the spindle is at speed - one approach slower than the
    // single-setup route, never less safe. Nothing is left over from a previous
    // program: this assignment replaces it.
    geometryProgramSpindle = programSpindle
      ? {
          ...programSpindle,
          controller: ctrl,
          running: false,
          saidNoSpindleLink: false,
          commandedAgainstStatus: null,
        }
      : null
    sayProbeAtToolpathLoad(name)
    store().setProgram(name, null, [], null, {
      program: plan.program,
      setups: plan.stages.map((stage) => ({
        setupName: stage.setupName,
        setupId: stage.setupId,
        wcs: stage.wcsId as WcsId,
        firstStepId: plan.parts[stage.firstPartIndex].steps[0].id,
      })),
    })
    clearTransferReview()
    store().applyJobProgress(wholeProgramProgress(ctrl.jobProgress()))
    store().setProgramReadiness({ ready: true, reason: loadedReason })
    store().pushConsole('rx', loadedReason, 'info')
    // WO-1329 requirement 4: the frames are named and the operator is told that
    // confirming their zeros is theirs to do. A console line, once, at load - it
    // gates nothing, and CYCLE START repeats it only if the load has aged.
    if (continuationLine !== null) store().pushConsole('rx', continuationLine, 'info')
    // Path fidelity follows the WHOLE program in WORK coordinates. Each stage's
    // work coordinates are relative to the frame that stage runs in, and the
    // reported work position follows the same active frame, so the comparison
    // stays true across the switch.
    armPathFidelityFromMoves(
      plan.program.steps.filter(isStagedMove) as readonly QueuedMove[],
      'work',
    )
    // WO-1874: the board's own answer to this staging, on the same terms as the
    // single-setup door - an explicit refusal takes the whole arm back.
    watchBoardLoadRefusal(
      ctrl,
      () => loadRevision === geometryProgramLoadRevision,
      (reason) => disarmRefusedProgramLoad(ctrl, reason),
    )
    bumpArmEpoch()
    return { ok: true, reason: null }
  }

  // THE FIRST STAGE'S FRAME, SELECTED AND CONFIRMED BEFORE ANYTHING IS STAGED -
  // WO-1312's rule, unchanged, applied to stage one. Every later stage's frame
  // is selected at its boundary by `crossSetupBoundary`.
  const loadRevision = ++geometryProgramLoadRevision
  const firstWcs = frames[0]
  if (typeof ctrl.selectWcsAwait === 'function') {
    const receiptToken = captureBackendReceipt(ctrl)
    const receipt = ctrl.selectWcsAwait(firstWcs)
    if (receipt === null) {
      return refuseProgramLoad(`The controller would not select ${firstWcs}, so nothing was staged.`)
    }
    store().setProgramReadiness({
      ready: false,
      reason: `Waiting for the controller to confirm ${firstWcs} before staging this program.`,
    })
    void receipt.then((confirmed) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) return
      if (!confirmed) {
        refuseProgramLoad(`The controller did not confirm ${firstWcs}, so nothing was staged.`)
        return
      }
      store().setActiveWcs(firstWcs)
      if (controllerJobReallyRuns(ctrl)) {
        refuseProgramLoad(
          'The program started running before its work offset was confirmed; nothing new was staged.',
        )
        return
      }
      stagePlannedProgram()
      ctrl.refreshState()
    }).catch((error) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) return
      const detail = error instanceof Error ? error.message : String(error)
      refuseProgramLoad(`The controller did not confirm ${firstWcs} (${detail}), so nothing was staged.`)
    })
    return { ok: true, reason: null }
  }

  if (!ctrl.selectWcs(firstWcs)) {
    return refuseProgramLoad(`The controller would not select ${firstWcs}, so nothing was staged.`)
  }
  store().setActiveWcs(firstWcs)
  return stagePlannedProgram()
}

/** The operator's Load of several setups - `stageSetupsToolpathProgram`, then
 *  the 3D view frames what it staged (WO-2675). */
export async function loadSetupsToolpathProgram(
  setupIds: readonly string[],
  options: { runThrough?: boolean } = {},
): Promise<{ ok: boolean; reason: string | null }> {
  const loaded = await stageSetupsToolpathProgram(setupIds, options)
  if (loaded.ok) bumpProgramLoadEpoch()
  return loaded
}

/**
 * THE FILE DOOR ON A GEOMETRY CONTROLLER (WO-1335).
 *
 * OPERATOR'S REQUIREMENT, 2026-09-11, third time of asking: "the software has to be
 * able to run a g code and run it on ours - if you need to build a translator or
 * do whatever you got to goddamn do... A CNC control software that cannot load
 * the most standard file format for controlling a CNC is not complete." Until
 * this order, Load -> Open file... on his AXBB-E was a SILENT NO-OP: the text
 * door handed the program to a controller with no interpreter, nothing staged,
 * and the previously loaded program stayed loaded.
 *
 * THE WIRE IS UNCHANGED AND THE CAPABILITY IS STILL HONEST. `gcodeText: false`
 * means the bridge takes no text, and it still does not: the text is
 * interpreted HERE, in the app, into the same staged program the toolpath route
 * builds. ADR-0043's "declares gcodeText: false and always will" is amended by
 * this order to say what it meant - the wire takes geometry, the app interprets
 * text into it.
 *
 * WHAT THIS DOOR IS, IN ONE SENTENCE: `interpretGcodeProgram` turns posted text
 * into stages - a run of moves in one frame, ended by the next frame or by an
 * M0/M1 hold - and from there every step is the toolpath route's own code:
 * `buildStraightLineProgram` makes the steps, `buildProgramParts` cuts them to
 * the board's ceiling, `firstStepOutsideTravel` checks the table, and the parts
 * run is WO-1323's, so the frame is selected at a boundary only after the
 * machine has REPORTED reaching the height the file lifted to.
 *
 * WHY IT DOES NOT GO THROUGH `planMultiSetupProgram`: that planner APPENDS an
 * inter-stage retract to a global safe height, because a toolpath has no
 * postamble and something has to lift the tool between fixtures. A posted file
 * already contains its own lift - it is a line in the file - so appending a
 * second one would stage a move the operator never asked for and make the two
 * routes disagree about what the file says. The boundary clearance here is the
 * height THE FILE lifted to, which is the only height this route can honestly
 * claim the file intends.
 */
interface GcodeTextLoadOptions {
  /** WO-2608: a restart's synthetic M6 owns the manual spindle start in
   * its prelude. Later spindle changes in the file keep their own holds. */
  restartToolChangePreludeLines?: number
  /** Publish the accepted geometry as the read-only ProgramPanel listing.
   * Used by the file door only: MDI uses this loader too, but a typed
   * command must not replace the operator's loaded-program listing. */
  publishListing?: boolean
  /** WO-2598: preserve the loaded file while staging an operator line start. */
  runFromFile?: ToolpathProgramReload
  /** Includes asynchronous frame refusals; ok means staged, never started. */
  onStageResult?: (outcome: { ok: boolean; reason: string | null }) => void
  /** WO-1336: the console row this load writes, when the caller has a better
   *  sentence for it than "Program ... loaded". An MDI line is one line and
   *  reads as one, but it is the SAME load, so the sentence is the only thing
   *  that changes. Absent, the file's own load line is written.
   *
   *  `started` is what `onStaged` reported, and the row is written after it, so
   *  a sentence that claims the line ran is only written when it ran. Null
   *  writes no row now (WO-2153: MDI waits for the board's own answer). */
  loadLine?: (program: GcodeInterpretedProgram, started: boolean) => string | null
  /** WO-1336: run the instant the program is actually on the board - which is
   *  AFTER the frame receipt on a controller that confirms one, so a caller
   *  cannot start a program that has not been staged yet. This is the whole of
   *  what MDI adds to the file door: Enter runs the line. Returns whether the
   *  follow-on succeeded; the gates it passes through are the program's own and
   *  any of them may refuse after the program is staged. */
  onStaged?: (program: GcodeInterpretedProgram) => boolean
  /** WO-1640: this is the file door staging the SAME file again (for a work
   *  offset edited since it was staged), so it stays the file Stop re-stages,
   *  even though `onStaged` starts it. */
  fileReread?: boolean
  /** WO-2234: an MDI line staged over the loaded file. It goes to the board
   *  exactly as any MDI line does, but the loaded program's identity - job
   *  name, listing, preview context, readiness - stays the file's. */
  keepsLoadedProgram?: boolean
  /** WO-2237: handed the staged step -> text line map before `onStaged`, so a
   *  kept stop's return can say which line of the file a later pause is on. */
  lineOfStep?: (lineOfStep: (stepId: number) => number | undefined) => void
  /** WO-2047: the file's LienCAM context (its LCX1 block, or the setup it was
   *  posted from). Kept with the published listing; see `stagedProgramContext`. */
  context?: ProgramContextV1 | null
  /** WO-2256: this text is the rest of the loaded file - a kept stop's return,
   *  its prelude and then the file from a line. What the operator reads names
   *  the FILE: every line the console names, every section, and the staged
   *  program's progress and move ids (`StagedNumbering`). What is staged and
   *  sent is unchanged. */
  fileNumbering?: FileNumbering
  /** WO-2437: Setups loaded together as their posted file, with the Load menu's
   *  "Continue through the setups" on. A boundary that holds ONLY because the
   *  work offset changes is crossed rather than held - the retract-clear
   *  readback, the frame selection and the next section's start, as the
   *  toolpath route's WO-1329 run-through does. A boundary with any other
   *  reason to hold (an M0/M1, a tool change, a macro, a spindle this machine
   *  cannot start) holds as before. */
  runThroughOffsetChanges?: boolean
  /** WO-2686 fix round 6: the operator's Load of a file (`loadGcodeFile`), a
   *  candidate for the program before it. Over a loaded program, refused, it
   *  writes one console line and changes nothing else; accepted, it replaces
   *  that program's kept stop, stop report and file waiting for offsets. */
  candidate?: boolean
}

/** WO-2256: how a program staged as the rest of the loaded file reads as it. */
interface FileNumbering {
  /** A line of the staged text as the file's own line; null for the prelude. */
  lineOf: (line: number) => number | null
  /** The file line the return carries on from - what a prelude line reads as. */
  startLine: number
  /** A file line's section, 0-based, as the file's own listing numbers them;
   *  null when the listing does not say. */
  sectionOf: ((fileLine: number) => number) | null
  /** The staged program's numbering, from its steps and each motion step's
   *  line of the staged text. */
  numberingOf: (staged: {
    steps: readonly QueuedMove[]
    lineOfStep: (stepId: number) => number | undefined
    stagedTotal: number
    partFirstStepIds: readonly number[]
  }) => StagedNumbering | null
}

/** WO-2256: the interpreted program with every line it names read through
 *  `lineOf` - the console sentences, holds, tool changes and macro calls a
 *  load builds from it then name the file's lines. */
function fileNumberedProgram(
  program: GcodeInterpretedProgram,
  lineOf: (line: number) => number,
): GcodeInterpretedProgram {
  const at = <T extends { line: number }>(entry: T): T => ({ ...entry, line: lineOf(entry.line) })
  const maybe = <T extends { line: number }>(entry: T | null): T | null => (entry === null ? null : at(entry))
  return {
    ...program,
    stages: program.stages.map((stage) => ({
      ...stage,
      firstLine: lineOf(stage.firstLine),
      moveLines: stage.moveLines.map(lineOf),
      dwells: stage.dwells.map(at),
      ends: stage.ends.kind === 'end' ? stage.ends : at(stage.ends),
      spindle: maybe(stage.spindle),
      heldBefore: maybe(stage.heldBefore),
      macroBefore: maybe(stage.macroBefore),
      toolChangeBefore: maybe(stage.toolChangeBefore),
      coolantBefore: maybe(stage.coolantBefore),
    })),
    spindle: maybe(program.spindle),
    spindleSpeeds: program.spindleSpeeds.map(at),
    holdsWithNoMotion: program.holdsWithNoMotion.map(lineOf),
    macros: program.macros.map(at),
    preselects: program.preselects.map(at),
    tableCodeMacroBindings: program.tableCodeMacroBindings.map(at),
    accepted: program.accepted.map(at),
    toolLengthOffsets: program.toolLengthOffsets.map(at),
  }
}

/** WO-2256: the part each file-door listing was staged in, by its first
 *  step id - so a resumed run's parts count on from the file's. */
let filePartsOfListing: { listing: StagedProgramView; firstStepIds: number[] } | null = null

/** WO-1636: machine home in machine coordinates, for the reader's `G28`, from
 *  what the active definition declares (the coordinate read at each home
 *  switch). WO-1644: NOT gated on homing - UCCNC and LinuxCNC run `G28` on an
 *  unhomed machine, to the stored position in the machine coordinates the
 *  controller holds. A definition that declares no home leaves the reader at
 *  machine zero, the controllers' own stored default. Both routes pass it. */
function machineHomeForReader(
  machine: MachineConfig,
): { x: number; y: number; z: number } | undefined {
  // WO-1664 (machine, 2026-09-17 19:51 CDT): `G28 Z18` on Operator's imported
  // definition resolved home as machine Z 0 - the BOTTOM of his Z travel - and
  // rapid-plunged at the tool setter into a drive fault. His definition had no
  // `homeConvention`, so the reader was handed nothing and fell back to zero.
  // THE DEFINITION ALREADY KNOWS WHERE EACH AXIS HOMES: the UCCNC importer reads
  // `Homingvalue`, the machine coordinate the controller assigns at the home
  // switch (his profile: X 738, Y 724.5, Z 128.9), into `homing.perAxis`. That
  // number IS UCCNC's G28 target. A hand-entered `homeConvention` is the
  // operator's own statement and wins when present; the imported per-axis
  // value answers for every machine that has none (his does not).
  //
  // WO-1701 (ADR-0049): an axis whose homing the definition STATES takes its
  // G28 target from the same derivation the motion resolver homes it by
  // (`machineHomeConvention`), so a Machine-area home-at / homing-value edit
  // moves G28 and the resolver together and a stored `homeConvention` can
  // never freeze it. WO-1755: GRBL-family firmware owns the zero coordinate
  // even when an axis comes only from the stored CAM lens, so those axes also
  // use this derivation. Every other controller resolves exactly as before.
  const convention = machine.homeConvention
  const derived = machineHomeConvention(machine)
  const statedTravel = machineTravel(machine)
  const perAxis = machine.controllerDefinition?.homing?.perAxis
  const axisHome = (key: 'x' | 'y' | 'z'): number | undefined => {
    const statedEnd = derived?.[key]
    if ((homeEndFromDefinition(machine, key) || controllerZeroIsHomeSwitch(machine.controller)) && statedEnd) {
      return resolveAxisHomePosition(statedEnd, statedTravel[key])
    }
    if (convention) return resolveAxisHomePosition(convention[key], machine.travel[key])
    const v = perAxis?.[key.toUpperCase() as 'X' | 'Y' | 'Z']?.homingValue
    return typeof v === 'number' && Number.isFinite(v) ? v : undefined
  }
  if (!convention && !perAxis) return undefined
  const home = { x: axisHome('x'), y: axisHome('y'), z: axisHome('z') }
  return home.x !== undefined && home.y !== undefined && home.z !== undefined
    && [home.x, home.y, home.z].every(Number.isFinite)
    ? { x: home.x, y: home.y, z: home.z }
    : undefined
}

// ---- a file loaded before its work offset is set (WO-1980) ----
//
// Operator ruling 2026-09-25: "If I have homed, set WCS, and the program is loaded...
// why are we stopping the operator in the first place?" He loaded his Fusion
// file on "Simulate LienCNC V2" BEFORE typing G54, and Load refused it: "Line
// 12: G53 cannot be resolved because G54 offset is unknown". The software can
// run that file the moment G54 is known (rule 11), so the file door keeps it:
// the panel names it, nothing is staged, the console says once what it waits
// for, and it is read against the offset the instant that offset is set - the
// same read a load after the offset would do. A Cycle Start while it still
// waits is the one press refused, by name: "set G54 first".

/** The file the door keeps until the frames it runs in are known. */
interface ProgramAwaitingOffsets {
  controller: MachineController
  /** The connection it was loaded on; a file never stages onto another. */
  revision: number
  name: string
  text: string
  publishListing: boolean
  context: ProgramContextV1 | null
  /** Every frame the file runs in that this session does not know yet. */
  frames: GcodeWcs[]
  runThroughOffsetChanges: boolean
}
let programAwaitingOffsets: ProgramAwaitingOffsets | null = null
let awaitedOffsetsCheckQueued = false

/** The frames a file runs in that are not known yet - but only when knowing
 *  them is ALL the file needs: it is read once more with every unknown frame
 *  standing at zero, and a file that still refuses (a word it cannot run, a
 *  tool length it cannot know) is refused as before. Empty otherwise. */
function framesAFileAwaits(text: string, options: GcodeInterpretOptions, known: ReaderWorkOffsets): GcodeWcs[] {
  const standIn: ReaderWorkOffsets = { ...known }
  for (const wcs of ['G54', 'G55', 'G56', 'G57', 'G58', 'G59'] as const) standIn[wcs] ??= { x: 0, y: 0, z: 0 }
  const read = interpretGcodeProgram(text, { ...options, workOffsets: standIn })
  if (!read.ok) return []
  return [...new Set(read.program.stages.map((stage) => stage.wcs as GcodeWcs))]
    .filter((wcs) => known[wcs] === undefined)
}

function framesInWords(frames: readonly string[]): string {
  return frames.join(' and ')
}

/** Keep the file, stage nothing, and say once what it waits for. Whatever the
 *  controller held before is no longer the loaded program. */
function keepProgramAwaitingOffsets(
  ctrl: MachineController,
  name: string,
  text: string,
  options: GcodeTextLoadOptions,
  context: ProgramContextV1 | null,
  frames: GcodeWcs[],
  why: string,
): { ok: true; reason: null } {
  ++geometryProgramLoadRevision
  loadNothing(ctrl)
  endToolChangeSequence()
  if (programPartsRun?.controller === ctrl) programPartsRun = null
  if (programPartsTerminal?.controller === ctrl) programPartsTerminal = null
  stagedMotionCuts = true
  geometryProgramSpindle = null
  geometryProgramCoolant = null
  toolpathProgramReload = null
  stagedProgramContextValue = null
  clearTransferReview()
  programAwaitingOffsets = {
    controller: ctrl,
    revision: connectionRevision,
    name,
    text,
    publishListing: options.publishListing === true,
    context,
    frames,
    runThroughOffsetChanges: options.runThroughOffsetChanges === true,
  }
  const list = framesInWords(frames)
  store().setProgram(name, null, [], null)
  store().applyJobProgress(ctrl.jobProgress())
  store().setProgramReadiness({ ready: false, reason: `"${name}" waits for ${list} - set ${list} first.` })
  store().pushConsole(
    'rx',
    `"${name}" is loaded and waits for ${list} (${why}). Setting ${list} reads it against that work zero; `
      + 'nothing else is needed.',
    'info',
  )
  bumpArmEpoch()
  return { ok: true, reason: null }
}

/** An offset became known (or changed): look again once the write settles. */
function scheduleAwaitedOffsetsCheck(): void {
  if (programAwaitingOffsets === null || awaitedOffsetsCheckQueued) return
  awaitedOffsetsCheckQueued = true
  queueMicrotask(() => {
    awaitedOffsetsCheckQueued = false
    resolveProgramAwaitingOffsets()
  })
}

/** Read the kept file against the offsets now known. 'waiting' while one of
 *  its frames is still unknown; 'gone' when another load replaced it. */
function resolveProgramAwaitingOffsets(): 'staged' | 'refused' | 'waiting' | 'gone' {
  const waiting = programAwaitingOffsets
  if (waiting === null) return 'gone'
  const s = store()
  if (
    waiting.controller !== controller
    || waiting.revision !== connectionRevision
    || s.job.name !== waiting.name
    || s.programText !== null
  ) {
    programAwaitingOffsets = null
    return 'gone'
  }
  const known = readerWorkOffsets()
  if (waiting.frames.some((wcs) => known[wcs] === undefined)) return 'waiting'
  // Never staged over motion that is running; looked at again when it ends.
  if (controllerJobReallyRuns(waiting.controller)) return 'waiting'
  programAwaitingOffsets = null
  const outcome = loadGcodeTextToolpathProgram(waiting.name, waiting.text, {
    publishListing: waiting.publishListing,
    context: waiting.context,
    runThroughOffsetChanges: waiting.runThroughOffsetChanges,
  })
  if (programAwaitingOffsets !== null) return 'waiting'
  if (!outcome.ok) {
    // Its refusal is on the console; the panel stops naming a file that is
    // not on the controller.
    store().setProgram(null, null, [], null)
    store().applyJobProgress(waiting.controller.jobProgress())
    store().setProgramReadiness({ ready: false, reason: outcome.reason ?? 'Load a program.' })
    return 'refused'
  }
  sayReferenceToolNeeded(waiting.name, programFixedPadChanges(true))
  return 'staged'
}

/** Cycle Start on a file still waiting for a frame: refused by name, once per
 *  press. Null when no file waits (or the one that waited is now staged). */
function awaitedOffsetsCycleStartRefusal(ctrl: MachineController): string | null {
  if (programAwaitingOffsets?.controller !== ctrl) return null
  const waiting = programAwaitingOffsets
  if (resolveProgramAwaitingOffsets() !== 'waiting' || programAwaitingOffsets === null) return null
  const list = framesInWords(programAwaitingOffsets.frames)
  return `Cycle Start: set ${list} first - "${waiting.name}" is loaded and waits for ${list}. Nothing moved.`
}

// Any offset write or report is where a waiting file may become runnable, and
// the end of whatever motion ran while its offset was set.
useMachineControl.subscribe((state, previous) => {
  if (state.offsets !== previous.offsets || state.job.phase !== previous.job.phase) scheduleAwaitedOffsetsCheck()
})

/** WO-1677: the length `G43 H<n>` shifts Z by in frame `wcs` - see `fileReaderOptions`. */
function readerToolLengthMm(ctrl: MachineController, h: number, wcs: string): number {
  return resolveG43ToolLengthMm(h).deltaMm - toolLengthInForceMm(ctrl, wcs)
}

/** What the file door's reader reads a file against: one set, shared by the
 *  Load and by WO-2686's derived fit of the loaded file (`loadedFileFitRefusal`). */
function fileReaderOptions(
  state: ReturnType<typeof useCamStore.getState>,
  activeMachine: ReturnType<typeof controlMachine>,
  dialect: GcodeDialect,
  sessionWcs: GcodeWcs,
  startedAt: GcodeReaderPoint,
  readerOffsets: ReaderWorkOffsets,
  toolLengthMm: (h: number, wcs: string) => number,
): GcodeInterpretOptions {
  // The definition carrier is live even while the connection identity is
  // pinned. G30.1 writes point 1 here and a subsequent G30 in the same session
  // must see it; no controller reconnect is needed because the app, rather
  // than UCCNC, resolves the word into ordinary machine-frame moves.
  const definitionCarrier = state.machineLibrary.find((machine) => machine.id === activeMachine.id)
    ?? (state.project.machine.id === activeMachine.id ? state.project.machine : activeMachine)
  return {
    dialect,
    sessionWcs,
    initialPosition: startedAt,
    machineUnits: 'mm',
    workOffsets: readerOffsets,
    referencePositions: machineReferencePositions(definitionCarrier),
    // WO-1644: `G28` resolves to the home position the definition declares,
    // homed or not - see `machineHomeForReader`.
    machineHome: machineHomeForReader(activeMachine),
    // WO-1559: the file's G4/G82 P unit is the MACHINE'S own setting
    // (`Generalsettings.Dwellinseconds`), read off the same definition carrier
    // the reference positions come from - not a dialect constant. The dialect
    // default applies only when this machine states nothing.
    machineDefinition: definitionCarrier,
    // WO-1677: `G43 H<n>` shifts Z by the length THIS machine's tool table
    // holds for tool n - the length the tool-length measure writes and G43.1
    // applies from the panel - folded into the staged Z, so the moves reach
    // the controller already carrying it and no work offset is ever written
    // (or left shifted) by a program. Unmeasured: zero, as UCCNC's table
    // answers, and the load line says so once. NET of the length already in
    // force in that frame (the panel's Apply, a guided tool change): a real
    // controller's G43 H REPLACES that length, it does not add to it.
    toolLengthMm,
  }
}

export function loadGcodeTextToolpathProgram(
  name: string,
  text: string,
  options: GcodeTextLoadOptions = {},
): { ok: boolean; reason: string | null } {
  // WO-2686 fix round 6: a candidate refused over a loaded program leaves that
  // program - its readiness, arm epoch, chosen start, kept stop, stop report,
  // file waiting for offsets - exactly as it was: one console line, nothing
  // else. Until `accept` runs; past it the controller is being changed.
  let keepsProgramBefore = options.candidate === true && programIsLoaded()
  const refuse = (reason: string) => {
    const outcome = keepsProgramBefore ? refuseCandidateProgramLoad(reason) : refuseProgramLoad(reason)
    options.onStageResult?.(outcome)
    return outcome
  }
  const accept = () => {
    keepsProgramBefore = false
    // WO-2237: the operator's Load replaces a kept stop's place.
    if (options.candidate) forgetKeptStop()
    // WO-2234: an MDI line over the loaded program leaves the operator's stop
    // report and a file waiting for its offsets exactly where they were.
    if (!rearmingAfterOperatorStop && !options.keepsLoadedProgram) clearOperatorStop()
    // WO-1980: whatever this load does, the file that waited is no longer it.
    if (!options.keepsLoadedProgram) programAwaitingOffsets = null
  }
  publishNonProgramActionStatus(null)
  if (!keepsProgramBefore) accept()
  const ctrl = getMachineController()
  if (controllerJobReallyRuns(ctrl)) {
    const outcome = refuseActiveProgramLoad()
    options.onStageResult?.(outcome)
    return outcome
  }
  if (ctrl.capabilities.machineProgram !== true || typeof ctrl.loadProgram !== 'function') {
    return refuse(
      'This controller cannot run a program - it reports no program route. '
      + 'Connect the machine bridge (or the simulator) and try again.',
    )
  }
  const loadProgram = ctrl.loadProgram.bind(ctrl)
  const fileContext = options.publishListing ? verifiedStagedContext(name, text, options.context) : null
  // WO-2642: the tools this load names are its own context's (none for a file from disk), never the previous program's.
  const namingContext = options.publishListing ? fileContext : loadedProgramContext()
  // WO-2104 / WO-2283: a file run in the applied mesh's work system is read compensated.
  const meshed = options.publishListing
    ? meshCompensatedFileText(text)
    : { text, sourceLineOf: null, compensatedBlocks: null, refusal: null }
  if (meshed.refusal !== null) {
    const reason = `Mesh compensation refused: ${meshed.refusal}`
    if (keepsProgramBefore) return refuse(reason)
    // The text door's words and shape (readiness only, no console line):
    // this door had no such refusal before WO-2283.
    store().setProgramReadiness({ ready: false, reason })
    bumpArmEpoch()
    options.onStageResult?.({ ok: false, reason })
    return { ok: false, reason }
  }

  const state = useCamStore.getState()
  const activeMachine = controlMachine(state)
  const rapidFeedMmMin = activeMachine.rapidRate
  if (!(typeof rapidFeedMmMin === 'number' && Number.isFinite(rapidFeedMmMin) && rapidFeedMmMin > 0)) {
    return refuse(
      "This machine declares no rapid rate, so a G0 in this file has no feed to run at - "
      + "set the machine's rapid traverse rate. A feed is never invented here.",
    )
  }

  // THE DIALECT IS THE MACHINE'S DECLARED CONTROLLER, never a guess. It reaches
  // both the reader's dwell arithmetic and the typed dwell step staged below;
  // a file read under the wrong dialect is a file read wrong. Generic is a
  // real declared dialect with the plain RS-274 table; only an unknown legacy
  // declaration is refused rather than silently defaulted.
  const declared = state.project.machine?.controller
  const dialect: GcodeDialect | null = gcodeTableDialectOf(declared)
  if (dialect === null) {
    return refuse(
      `This machine's declared controller "${String(declared)}" has no G-code reader dialect, so `
      + 'the file was not loaded.',
    )
  }

  const sessionWcs = store().activeWcs
  if (sessionWcs === null || sessionWcs === undefined) {
    return refuse(
      'The controller has not said which work offset is active, so a file that names none of its own '
      + 'has no frame to run in. Connect and select a work offset, then load the file again.',
    )
  }

  const startedAt = readerPosition(ctrl, activeMachine)
  if (startedAt === null) {
    return refuse(
      'The controller has not reported where the tool is, so a file whose first move leaves an axis '
      + 'unstated cannot be placed. Wait for a position report, then load the file again.',
    )
  }

  const readerOffsets = readerWorkOffsets()
  const offsetOf = (wcs: string): GcodeReaderPoint | null => (
    readerOffsets[wcs as GcodeWcs] ?? null
  )

  // WO-1677: every (H, frame) the reader asked, with the answer it was given.
  // A later section is re-resolved only when one of these answers changed.
  const toolLengthAnswer = (h: number, wcs: string): number => readerToolLengthMm(ctrl, h, wcs)
  const toolLengthAsked = new Map<string, { h: number; wcs: string; mm: number }>()
  const interpretOptions = fileReaderOptions(state, activeMachine, dialect, sessionWcs as GcodeWcs, startedAt, readerOffsets,
    (h, wcs) => {
      const mm = toolLengthAnswer(h, wcs)
      toolLengthAsked.set(`${h}|${wcs}`, { h, wcs, mm })
      return mm
    })
  // WO-1980: a FILE (never a typed MDI line, never a re-read Cycle Start is
  // about to run) that needs only a frame nobody has set yet is kept for it.
  const keepsForOffsets = options.onStaged === undefined
  const interpreted = interpretGcodeProgram(meshed.text, interpretOptions)
  if (!interpreted.ok) {
    const frames = keepsForOffsets ? framesAFileAwaits(meshed.text, interpretOptions, readerOffsets) : []
    if (frames.length > 0) {
      accept()
      return keepProgramAwaitingOffsets(ctrl, name, text, options, fileContext, frames, interpreted.refusal.message)
    }
    return refuse(
      `"${name}" was not loaded. ${interpreted.refusal.message}`,
    )
  }
  // WO-2256: a return's lines are the file's wherever the operator reads them;
  // the step -> line map (`lineByStepId`) stays on the staged text's own lines.
  const fileNumbering = options.fileNumbering
  const fileLine = (line: number): number => (
    fileNumbering === undefined ? line : fileNumbering.lineOf(line) ?? fileNumbering.startLine
  )
  const program = fileNumbering === undefined ? interpreted.program : fileNumberedProgram(interpreted.program, fileLine)
  // WO-2580: a stop-only section is no section of the file; finished, it is
  // the section before it, next, the section after it.
  const sectionIndexOf = (stage: GcodeStage, index: number, finished = false): number => (
    fileNumbering?.sectionOf?.(stage.moveLines[0] ?? stage.firstLine)
      ?? (finished && !listedStage[index] ? Math.max(0, listedSectionBefore[index] - 1) : listedSectionBefore[index])
  )

  // EVERY FRAME THE FILE USES, ASKED BEFORE THE FIRST MOVE. A program that
  // discovered an unset G55 at the boundary would already have cut the first
  // section and moved the machine - the same rule, and the same sentence, the
  // multi-setup door applies to setups.
  const unsetFrames = [...new Set(program.stages.map((stage) => stage.wcs as GcodeWcs))]
    .filter((wcs) => offsetOf(wcs) === null)
  if (keepsForOffsets && unsetFrames.length > 0) {
    const first = program.stages.find((stage) => offsetOf(stage.wcs) === null)!
    accept()
    return keepProgramAwaitingOffsets(
      ctrl, name, text, options, fileContext, unsetFrames, `it runs in ${first.wcs} from line ${first.firstLine}`,
    )
  }
  for (const stage of program.stages) {
    if (offsetOf(stage.wcs) !== null) continue
    return refuse(
      `"${name}" runs in ${stage.wcs} from line ${stage.firstLine}, and ${stage.wcs} is not fully set `
      + `on this controller, so nothing was staged. Set the X, Y and Z work zero for ${stage.wcs}, `
      + 'then load the file again.',
    )
  }

  // ONE BUILD FOR THE WHOLE FILE, SLICED INTO STAGES AFTERWARDS. The builder
  // numbers steps from 1 in input order, so building once is what makes every
  // step id unique across the whole program - which `validateMachineProgram`
  // requires and which the executing-move-id readback depends on to name one
  // move and not two. The stages' coordinates are each in their own frame; the
  // whole program is never staged as one list, exactly as the multi-setup plan
  // is not.
  const allMoves = program.stages.flatMap((stage) => stage.moves)
  const allLines = interpreted.program.stages.flatMap((stage) => stage.moveLines)
  const built = buildStraightLineProgram(allMoves, GCODE_TEXT_WORK_FRAME, rapidFeedMmMin, {
    opId: GCODE_TEXT_OP_ID,
    setupId: name,
  }, undefined, startedAt)
  if (!built.ok) {
    // The builder names the offending move by its ordinal; the operator is
    // standing at a FILE, so the ordinal becomes its line number.
    const ordinal = /Move (\d+)/.exec(built.reason)
    const line = ordinal ? allLines[Number(ordinal[1])] : undefined
    return refuse(
      line === undefined
        ? `"${name}" was not loaded: ${built.reason}`
        : `"${name}" was not loaded. Line ${fileLine(line)}: ${built.reason.replace(/^Move \d+ /, '')}`,
    )
  }
  const motionSteps = built.program.steps.filter(isStagedMove) as QueuedMove[]
  if (motionSteps.length !== allMoves.length) {
    return refuse(
      `"${name}" built ${motionSteps.length} staged moves for ${allMoves.length} commanded ones, so a move `
      + 'cannot be traced back to its line. Nothing was staged.',
    )
  }

  // G4 IS ALREADY A TYPED GEOMETRY-QUEUE STEP. The interpreter carries each
  // dwell's position among its stage's moves, so insert it here without parsing
  // the file a second time. Motion ids stay exactly as the builder assigned
  // them; dwell ids start above that range and receive action index entries,
  // keeping every executing id unique and attributable on the board.
  // Keep this constant-stack for posted programs with hundreds of thousands
  // of moves. Spreading every id into Math.max makes the JS argument-count
  // limit an accidental ceiling on the size of a file the load door accepts.
  let maxMotionId = 0
  for (const step of motionSteps) {
    if (step.id > maxMotionId) maxMotionId = step.id
  }
  let nextDwellId = maxMotionId + 1
  let motionCursor = 0
  const stagedIndex: ProgramIndex = { ...built.program.index }
  // Listing-only provenance: never substitute file lines for controller ids.
  const listingDwellLines = new Map<number, number>()
  // WO-2580: the fences below are no line of the file - no display shows them.
  const fenceIds = new Set<number>()
  const stageSteps = program.stages.map((stage, stageIndex): QueuedMove[] => {
    const stageMotion = motionSteps.slice(motionCursor, motionCursor + stage.moves.length)
    motionCursor += stage.moves.length
    const ordered: QueuedMove[] = []
    for (let afterMove = 0; afterMove <= stageMotion.length; afterMove++) {
      for (const dwell of stage.dwells.filter((entry) => entry.afterMove === afterMove)) {
        const step: QueuedMove = { id: nextDwellId++, kind: 'dwell', seconds: dwell.seconds }
        const line = interpreted.program.stages[stageIndex].dwells[stage.dwells.indexOf(dwell)].line
        listingDwellLines.set(step.id, meshed.sourceLineOf?.(line) ?? line)
        ordered.push(step)
        stagedIndex[step.id] = { action: true }
      }
      const motion = stageMotion[afterMove]
      if (motion !== undefined) ordered.push(motion)
    }
    // WO-2556: command-only sections and the final stop need a completion
    // readback just like moving sections. A zero-second queue fence moves no
    // axis; its receipt keeps M6, output starts and M0 in source order.
    if (ordered.length === 0) {
      const fence: QueuedMove = { id: nextDwellId++, kind: 'dwell', seconds: 0 }
      ordered.push(fence)
      stagedIndex[fence.id] = { action: true }
      fenceIds.add(fence.id)
    }
    return ordered
  })
  // A stop-only section (a fence alone) is no section of the file: the file's
  // sections are numbered without it (machine seat 10-04: "File section 4" was
  // the M0 after `T1 M6`, and the file's 4 sections read as 5).
  const listedStage = stageSteps.map((stepsOfStage) => stepsOfStage.some((step) => !fenceIds.has(step.id)))
  let listedSoFar = 0
  const listedSectionBefore = listedStage.map((listed) => (listed ? listedSoFar++ : listedSoFar))
  const isFenceOnly = (part: MachineProgram): boolean => (
    part.steps.length > 0 && part.steps.every((step) => fenceIds.has(step.id))
  )
  const steps = stageSteps.flat()
  const stagedProgram: MachineProgram = {
    frame: built.program.frame,
    units: built.program.units,
    steps,
    index: stagedIndex,
  }
  // WO-2104: a compensated file's lines are its compiled stream's; the operator's
  // "stopped at line N" and the context's spans name the file's own lines.
  const lineByStepId = new Map(motionSteps.map((step, index) => [
    step.id,
    meshed.sourceLineOf?.(allLines[index]) ?? allLines[index],
  ]))

  const cap = resolveMaxProgramMoves(ctrl.capabilities)
  const envelope = currentResolvedMachineMotion().envelope
  const parts: MachineProgram[] = []
  const boundaries = new Map<number, ProgramSetupBoundary>()
  const spindleWords = new Map<number, GcodeSpindleWord>()
  const coolantWords = new Map<number, GcodeCoolantWord>()
  const lastMachineZBeforeStage = (beforeStageIndex: number): number => {
    for (let priorIndex = beforeStageIndex - 1; priorIndex >= 0; priorIndex--) {
      const prior = program.stages[priorIndex]
      const lastMove = prior.moves.at(-1)
      if (lastMove !== undefined) return lastMove.z + offsetOf(prior.wcs)!.z
    }
    const reportedMachineZ = ctrl.status().machinePos?.z
    if (typeof reportedMachineZ === 'number' && Number.isFinite(reportedMachineZ)) return reportedMachineZ
    return startedAt.z + offsetOf(sessionWcs)!.z
  }
  // WHETHER THIS CONNECTION CAN DRIVE THE FILE'S SPINDLE AT ALL - the SAME gate
  // the toolpath route applies, machine record AND live controller. It is
  // decided here rather than below because a file that starts its spindle
  // mid-run on a machine with no link has to HOLD there (the audit's second
  // blocking finding), and that is a decision about a BOUNDARY.
  const drivesSpindle = state.project.machine !== null
    && machineSpindleIsDrivable(state.project.machine, ctrl)
  for (let stageIndex = 0; stageIndex < program.stages.length; stageIndex++) {
    const stage = program.stages[stageIndex]
    const stepsForStage = stageSteps[stageIndex]
    const stageProgram: MachineProgram = {
      frame: 'work',
      units: 'mm',
      steps: stepsForStage,
      index: Object.fromEntries(
        stepsForStage.map((step) => [step.id, stagedIndex[step.id]]).filter(([, v]) => v !== undefined),
      ) as ProgramIndex,
    }

    // WO-1285's extent check, ONCE PER STAGE, against THAT stage's own offset.
    // One check against one frame would measure the G55 section's arcs from the
    // G54 zero, which is the same class of mistake as running it there.
    const wco = offsetOf(stage.wcs)!
    if (stepsForStage.some((step) => step.kind === 'arc') && (!envelope.x || !envelope.y)) {
      return refuse(
        arcsNeedTravelMessage(`"${name}"`),
      )
    }
    // WO-2219: turned by the rotation the controller reports for that offset.
    const offence = firstStepOutsideTravel(stageProgram, wco, envelope, ENVELOPE_FIT_TOLERANCE_MM, controllerRotationDeg(stage.wcs))
    if (offence !== null) {
      // THE OFFENDING STEP'S OWN LINE. The operator is standing at a FILE, so
      // "step 2 of the program" is not where they go to fix it.
      const stagedLine = lineByStepId.get(offence.stepId)
      const line = stagedLine === undefined ? stage.firstLine : fileLine(stagedLine)
      return refuse(
        `"${name}", line ${line}: ${describeTravelOffence(offence, stageProgram)}`,
      )
    }

    const partitioned = buildProgramParts(stageProgram, cap)
    if (!partitioned.ok) {
      return refuse(`"${name}", from line ${stage.firstLine}: ${partitioned.reason}`)
    }
    if (partitioned.parts.length === 0) {
      return refuse(
        `"${name}" planned no program parts for the section starting at line ${stage.firstLine}, so `
        + 'running it would skip that section entirely. Nothing was staged.',
      )
    }

    if (stageIndex > 0) {
      const previous = program.stages[stageIndex - 1]
      // A HOLD IS WHAT THE FILE ASKS FOR (an M0/M1, wherever it sits relative
      // to the moves around it) OR WHAT A FRAME CHANGE DEMANDS (WO-1323's rule:
      // the tool must be REPORTED clear before a new zero applies). A boundary
      // that is only the file's own M5 is NEITHER: the file runs straight on
      // through it, so the program advances by itself and the operator is not
      // asked to press a button the file never asked for.
      //
      // WO-1335 re-scope adds three more reasons to hold, and each is a thing
      // the operator has to DO before the moves after it are allowed to run:
      //  - a TOOL CHANGE. WO-1330's shape for the toolpath route; until it
      //    lands, the file loads and holds at the change with the console
      //    naming both tools, instead of being refused at the door.
      //  - a MACRO CALL (`M2001`). WO-1652: the machine's macro bound to it runs
      //    there; with none bound, the operator does at
      //    the machine what the macro would have done.
      //  - a SPINDLE START THIS MACHINE CANNOT COMMAND. The audit's second
      //    blocking finding: without this the console said "start it at the
      //    machine" and `releasePart()` ran the cut in the same breath, so the
      //    instruction named something nobody could carry out in time.
      //
      // A CHANGE OF SPEED COUNTS AS A START. On a machine the app cannot
      // command, cutting the next section at the previous section's speed is
      // the same class of wrong as cutting it with the spindle off. A STOP
      // deliberately does not hold: the file asked for less spindle, not more,
      // and the console still names it at the line.
      const restartSpindle = options.restartToolChangePreludeLines !== undefined
        && interpreted.program.stages[stageIndex].firstLine <= options.restartToolChangePreludeLines
      const startsUndrivenSpindle = !drivesSpindle && !restartSpindle
        && stage.spindleOn
        && (!previous.spindleOn
          || stage.spindle?.rpm !== previous.spindle?.rpm
          || stage.spindle?.direction !== previous.spindle?.direction)
      const holdsForOperator = previous.ends.kind === 'hold'
        || previous.ends.kind === 'tool-change'
        || previous.ends.kind === 'macro'
        || stage.heldBefore !== null
        || stage.macroBefore !== null
        || stage.toolChangeBefore !== null
        || startsUndrivenSpindle
      const holds = stage.wcs !== previous.wcs || holdsForOperator
      if (holds) {
        const macro = gcodeBoundaryMacro(previous, stage)
        const change = gcodeBoundaryToolChange(previous, stage)
        const nativeM6 = change !== null && configuredToolChangePark() !== null
        const restartIntent = !drivesSpindle && restartSpindle
          ? interpreted.program.stages.slice(stageIndex).find(candidate => candidate.spindleOn && candidate.spindle !== null
            && candidate.spindle.line <= options.restartToolChangePreludeLines!)?.spindle ?? null
          : null
        // THE HEIGHT THE FILE LIFTED TO, in MACHINE coordinates with the
        // OUTGOING stage's own offset, because that is the frame the machine
        // reports its position in. A reported machine Z compared against a
        // work-frame number is how this check would pass while the tool was
        // still down.
        boundaries.set(parts.length, {
          finishedName: sectionName(previous, sectionIndexOf(previous, stageIndex - 1, true)),
          nextName: sectionName(stage, sectionIndexOf(stage, stageIndex)),
          fromWcs: previous.wcs as WcsId,
          wcs: stage.wcs as WcsId,
          // A G4 can be the whole outgoing stage. Clearance is the machine Z
          // left by the latest geometric move, not an assumed move on the
          // immediately previous stage.
          clearMachineZ: lastMachineZBeforeStage(stageIndex),
          holdMessage: describeGcodeBoundaryHold(name, previous, stage, drivesSpindle, state.toolLibrary),
          ...(macro === null
            ? {}
            : {
                macro,
                macroToolChange: {
                  from: previous.tool,
                  to: [...program.preselects].reverse().find((select) => select.line <= macro.line)?.tool ?? null,
                  spindle: stage.spindleOn && stage.spindle !== null ? { ...stage.spindle } : null,
                },
              }),
          ...(!nativeM6 || change === null
            ? {}
            : {
                toolChange: {
                  leaving: describeGcodeTool(change.from, state.toolLibrary, namingContext),
                  fit: describeGcodeTool(change.to, state.toolLibrary, namingContext),
                  spindle: restartIntent ?? (stage.spindleOn && stage.spindle !== null ? { ...stage.spindle } : null),
                },
                m6: { line: change.line, tool: change.to },
              }),
          ...(change === null ? {} : { postedM6: { line: change.line, tool: change.to } }),
          // WO-2437: only the frame changes here, and the operator asked to
          // continue through the setups - crossed, not held.
          ...(options.runThroughOffsetChanges === true && !holdsForOperator ? { runThrough: true } : {}),
        })
      }
      // THE FILE'S OWN M3/M4/M5, at the part its motion starts. Read off the two
      // stages rather than off the end kind, so an `M5` that shares a boundary
      // with a `G55` or an `M0` is honoured just the same - and so a CHANGE OF
      // SPEED with the spindle running either side is honoured too, which the
      // re-scope allows and an `on !== on` test would have missed.
      const spindleChanged = stage.spindleOn !== previous.spindleOn
        || stage.spindle?.rpm !== previous.spindle?.rpm
        || stage.spindle?.direction !== previous.spindle?.direction
      if (spindleChanged) {
        spindleWords.set(parts.length, {
          on: stage.spindleOn,
          line: gcodeSpindleChangeLine(previous, stage),
          intent: stage.spindleOn && stage.spindle !== null
            ? { rpm: stage.spindle.rpm, direction: stage.spindle.direction }
            : null,
        })
      }
      // THE FILE'S OWN M7/M8/M9, the same way.
      // WO-1650: and every listed output the file switches (a pump on M10).
      if (!sameGcodeCoolantState(stage.coolant, previous.coolant)) {
        coolantWords.set(parts.length, {
          line: previous.ends.kind === 'coolant' ? previous.ends.line : stage.firstLine,
          ...stage.coolant,
        })
      }
    }
    for (const part of partitioned.parts) parts.push(part)
  }

  const loadedReason = describeGcodeTextLoad(name, program, drivesSpindle, state.toolLibrary, namingContext)
    + (meshed.compensatedBlocks === null
      ? ''
      : ` Surface mesh compensation is ACTIVE (${meshed.compensatedBlocks} compensated motion blocks).`)
  const firstWcs = program.stages[0].wcs as WcsId

  // WO-1677: A SECTION STAGED LATER CARRIES THE LENGTHS IN FORCE WHEN IT IS
  // STAGED. The board bakes the work offset into a section at loadMoves, and a
  // guided M6 at the hold measures the new tool and applies its length into
  // that offset before the next section is staged. So each later section is
  // answered again - tool n's delta NOW, net of the length in force NOW - and
  // its Z moved by exactly the change, so the length counts once. Same file,
  // same frames, same offsets: only the folded Z can differ.
  //
  // WO-1640: AND THE WORK OFFSETS IN FORCE WHEN IT IS STAGED. The board bakes
  // the new offset into a work move by itself, but a `G53` line was resolved
  // into work coordinates against the offset at load, so an edit made at a
  // hold would carry its machine target with it. Re-read against the offsets
  // now in force, a work move keeps its file numbers and a G53 move keeps its
  // machine target - the moves are moved by exactly the difference.
  let freshMoves: { key: string; moves: readonly { x: number; y: number; z: number }[] } | null = null
  let moveIndexByStepId: Map<number, number> | null = null
  const restage = (part: MachineProgram): MachineProgram | string => {
    const answers = [...toolLengthAsked.values()].map((asked) => toolLengthAnswer(asked.h, asked.wcs))
    const lengthsUnchanged = [...toolLengthAsked.values()].every((asked, i) => Math.abs(answers[i] - asked.mm) < 1e-9)
    const offsetsNow = readerWorkOffsets()
    const offsetsUnchanged = readerOffsetChanges(readerOffsets, offsetsNow).length === 0
    if (lengthsUnchanged && offsetsUnchanged) return part
    const key = `${answers.join('|')}#${JSON.stringify(offsetsNow)}`
    if (freshMoves?.key !== key) {
      const reread = interpretGcodeProgram(text, {
        ...interpretOptions,
        workOffsets: offsetsNow,
        toolLengthMm: toolLengthAnswer,
      })
      const moves = reread.ok ? reread.program.stages.flatMap((stage) => stage.moves) : []
      if (moves.length !== allMoves.length) {
        return 'the tool lengths or work offsets changed since the file was loaded and it could not be read '
          + 'again against them. Load the file again.'
      }
      freshMoves = { key, moves }
    }
    moveIndexByStepId ??= new Map(motionSteps.map((step, index) => [step.id, index]))
    const fresh = freshMoves.moves
    const indexOf = moveIndexByStepId
    return {
      ...part,
      steps: part.steps.map((step) => {
        if (step.kind !== 'line' && step.kind !== 'arc') return step
        const index = indexOf.get(step.id)
        if (index === undefined || typeof step.to.z !== 'number') return step
        const dx = fresh[index].x - allMoves[index].x
        const dy = fresh[index].y - allMoves[index].y
        const dz = fresh[index].z - allMoves[index].z
        if (dx === 0 && dy === 0 && dz === 0) return step
        const shift = <P extends { x?: number; y?: number; z?: number }>(p: P): P => ({
          ...p,
          ...(typeof p.x === 'number' ? { x: p.x + dx } : {}),
          ...(typeof p.y === 'number' ? { y: p.y + dy } : {}),
          ...(typeof p.z === 'number' ? { z: p.z + dz } : {}),
        })
        return step.kind === 'arc'
          ? { ...step, to: shift(step.to), centre: shift(step.centre) }
          : { ...step, to: shift(step.to) }
      }),
    }
  }

  const stagePlannedProgram = (): { ok: boolean; reason: string | null } => {
    const previousPartsRun = programPartsRun
    const previousPartsTerminal = programPartsTerminal
    programPartsTerminal = null
    // ONE PART TAKES THE UNCHANGED SINGLE-LOAD PATH, byte for byte, exactly as
    // `loadGeometryProgram` does: a parts run installed over a program with
    // nothing to advance TO would put a second progress authority in front of
    // the controller's own for no gain. A one-section file that fits the board
    // is therefore indistinguishable downstream from any other single load.
    programPartsRun = parts.length > 1
      ? {
          controller: ctrl,
          parts,
          partIndex: 0,
          completedMoves: 0,
          totalMoves: steps.length,
          completionSignaled: false,
          advancing: false,
          heldBetweenParts: false,
          started: false,
          boundaries,
          spindleWords,
          coolantWords,
          // WO-1335 fix round 3: the first section's coolant is what the file
          // has ALREADY asked for by the time its first move runs, so the next
          // word is measured against it rather than against "off".
          coolantApplied: { ...program.stages[0].coolant },
          spindleIntent: program.spindle
            ? { rpm: program.spindle.rpm, direction: program.spindle.direction }
            : null,
          spindleDriven: drivesSpindle,
          restage,
          ...(fenceIds.size > 0
            ? { unlistedParts: new Set(parts.flatMap((part, index) => (isFenceOnly(part) ? [index] : []))) }
            : {}),
        }
      : null
    const outcome = loadProgram(parts[0])
    if (!outcome.ok) {
      programPartsRun = previousPartsRun
      programPartsTerminal = previousPartsTerminal
      return refuse(
        outcome.reason ?? 'The controller refused this program without giving a reason.',
      )
    }
    stagedMotionCuts = programCuts(parts[0])
    // The file's one spindle intent, if this connection can drive a spindle at
    // all. THE SAME GATE THE TOOLPATH ROUTE APPLIES, word for word: a machine
    // record and the live controller must BOTH declare the VFD path, and
    // absence on either side leaves the program on the no-spindle path. A file
    // whose M3 cannot be driven is not silently dropped - the load line says
    // the spindle is the operator's to start (see `describeGcodeTextLoad`).
    //
    // ONLY IF THE FIRST SECTION ACTUALLY RUNS WITH IT ON. A file whose M3 comes
    // after some positioning has the spindle commanded at THAT line instead,
    // through `spindleWords` - CYCLE START must not start a spindle the file
    // has not started yet.
    //
    // THE SAME RULE FOR THE FILE'S PREAMBLE COOLANT, and for the same reason:
    // an `M8` above the first move is a word the file states, and it falls due
    // when that move is RELEASED, not when the program is loaded.
    geometryProgramCoolant =
      program.stages[0].coolant.flood || program.stages[0].coolant.mist
        || (program.stages[0].coolant.outputs?.length ?? 0) > 0
        ? {
            controller: ctrl,
            word: {
              line: program.stages[0].coolantBefore?.line ?? program.stages[0].firstLine,
              ...program.stages[0].coolant,
            },
            rpm: program.spindle?.rpm ?? 0,
          }
        : null
    geometryProgramSpindle = drivesSpindle && program.spindle && program.stages[0].spindleOn
      ? {
          rpm: program.spindle.rpm,
          direction: program.spindle.direction,
          controller: ctrl,
          running: false,
          saidNoSpindleLink: false,
          commandedAgainstStatus: null,
        }
      : null
    // WO-2157: Load says once that the file's spindle start will not spin the
    // probe that is loaded (the release keeps it off and runs on).
    if (drivesSpindle && options.publishListing) {
      const sourceLines = text.split(/\r?\n/)
      const probe = keepTextSpindleOffForProbe(sourceLines, sourceLines).probe
      if (probe !== null) store().pushConsole('rx', `"${name}": ${probeSpindleRefusal(probe)}`, 'info')
    }
    // WO-1347: the file door publishes the SAME accepted staged program the
    // posted-toolpath door publishes. Its listing therefore uses step ids -
    // the exact ids the controller reports as executing - instead of pretending
    // the geometry queue is streaming source-line numbers. MDI shares this
    // loader but opts out, because a typed command is not a newly opened file.
    const listingSetups = program.stages.flatMap((stage, index) => (listedStage[index]
      ? [{
          setupName: `File section ${listedSectionBefore[index] + 1}`,
          wcs: stage.wcs as WcsId,
          firstStepId: stageSteps[index][0].id,
        }]
      : []))
    const listing = options.publishListing
      ? {
          program: stagedProgram, setups: listingSetups,
          sourceLines: Object.fromEntries([...lineByStepId, ...listingDwellLines]),
          ...(fenceIds.size > 0 ? { unlistedStepIds: [...fenceIds] } : {}),
        }
      : null
    if (!options.keepsLoadedProgram) {
      stagedProgramContextValue = listing && fileContext
        ? { listing, context: fileContext, text, lineOfStep: (stepId) => lineByStepId.get(stepId) }
        : null
      store().setProgram(name, null, [], null, listing)
      if (listing) {
        filePartsOfListing = {
          listing,
          firstStepIds: parts.filter((part) => !isFenceOnly(part)).map((part) => part.steps[0]?.id ?? 0),
        }
      }
    }
    // WO-1663: the file door remembers what it staged, so the operator's own
    // Stop can stage it again from the top. MDI's typed line is not a file.
    toolpathProgramReload = options.runFromFile && fileNumbering
      ? {
          ...options.runFromFile,
          offsets: readerOffsets,
          position: startedAt,
          lineOfStep: (stepId) => {
            const line = lineByStepId.get(stepId)
            return line === undefined ? undefined : fileLine(line)
          },
          runFrom: { text, numbering: fileNumbering },
        }
      : options.onStaged && !options.fileReread
      ? null
      : {
          controller: ctrl,
          name,
          text,
          publishListing: options.publishListing === true,
          lineOfStep: (stepId) => lineByStepId.get(stepId),
          offsets: readerOffsets,
          position: startedAt,
          context: fileContext,
          runThroughOffsetChanges: options.runThroughOffsetChanges === true,
        }
    clearTransferReview()
    // WO-2256: what this load staged reads as itself - unless it is the rest
    // of the loaded file, which reads as the file.
    store().setStagedNumbering(fileNumbering?.numberingOf({
      steps,
      lineOfStep: (stepId) => lineByStepId.get(stepId),
      stagedTotal: wholeProgramProgress(ctrl.jobProgress()).totalLines,
      partFirstStepIds: parts.map((part) => part.steps[0]?.id ?? 0),
    }) ?? null)
    store().applyJobProgress(wholeProgramProgress(ctrl.jobProgress()))
    if (!options.keepsLoadedProgram) store().setProgramReadiness({ ready: true, reason: loadedReason })
    armPathFidelityFromMoves(steps, 'work', startedAt)
    // WO-2598 desk D2: keep execution ids even when scoring a line restart
    // is refused. This also survives the execution-position/offset reread.
    if (options.runFromFile && pathFidelityArmed?.kind === 'geometry') {
      pathFidelityArmed.refusal = RUN_FROM_LINE_NOT_CHECKED
    }
    // WO-1874: the file door arms on the same "accepted for sending" the other
    // two do, so it takes the same answer back from the board.
    watchBoardLoadRefusal(
      ctrl,
      () => loadRevision === geometryProgramLoadRevision,
      (reason) => disarmRefusedProgramLoad(ctrl, reason),
    )
    bumpArmEpoch()
    options.lineOfStep?.((stepId) => lineByStepId.get(stepId))
    // ONLY ONCE THE BOARD ACTUALLY HOLDS IT. Everything above this line can
    // still refuse, and a caller that started on the door's `ok` alone would
    // be starting the program that was staged BEFORE.
    const started = options.onStaged?.(program) ?? false
    // THE ROW IS WRITTEN LAST, AFTER THE FOLLOW-ON, BECAUSE IT DESCRIBES WHAT
    // HAPPENED. Written above `onStaged` it could only describe what was about
    // to be attempted, and MDI's sentence ends in "staged and started" - a
    // green row that survives a Cycle Start the homing gate refused, which is
    // the readout lying about the wire. The file route has no follow-on, so
    // `started` is false and its own load line is unchanged. WO-2153: a null
    // row is the caller holding its sentence until the board answers.
    const row = options.loadLine ? options.loadLine(program, started) : loadedReason
    if (row !== null) store().pushConsole('rx', row, 'info')
    options.onStageResult?.({ ok: true, reason: null })
    return { ok: true, reason: null }
  }

  // THE FIRST STAGE'S FRAME, SELECTED AND CONFIRMED BEFORE ANYTHING IS STAGED -
  // WO-1312's rule, unchanged. Every later stage's frame is selected at its
  // boundary by `crossSetupBoundary`. WO-2686: the file is read and fits; from
  // here the controller is changed, so it replaces the program before it.
  accept()
  const loadRevision = ++geometryProgramLoadRevision
  if (typeof ctrl.selectWcsAwait === 'function') {
    const receiptToken = captureBackendReceipt(ctrl)
    const receipt = ctrl.selectWcsAwait(firstWcs)
    if (receipt === null) {
      return refuse(`The controller would not select ${firstWcs}, so nothing was staged.`)
    }
    if (!options.keepsLoadedProgram) {
      store().setProgramReadiness({
        ready: false,
        reason: `Waiting for the controller to confirm ${firstWcs} before staging "${name}".`,
      })
    }
    void receipt.then((confirmed) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) {
        options.onStageResult?.({ ok: false, reason: RE_ARM_REFUSAL.changed })
        return
      }
      if (!confirmed) {
        refuse(`The controller did not confirm ${firstWcs}, so nothing was staged.`)
        return
      }
      store().setActiveWcs(firstWcs)
      if (controllerJobReallyRuns(ctrl)) {
        refuse(
          'The program started running before its work offset was confirmed; nothing new was staged.',
        )
        return
      }
      stagePlannedProgram()
      ctrl.refreshState()
    }).catch((error) => {
      if (!receiptIsCurrent(receiptToken) || loadRevision !== geometryProgramLoadRevision) {
        options.onStageResult?.({ ok: false, reason: RE_ARM_REFUSAL.changed })
        return
      }
      const detail = error instanceof Error ? error.message : String(error)
      refuse(`The controller did not confirm ${firstWcs} (${detail}), so nothing was staged.`)
    })
    return { ok: true, reason: null }
  }

  if (!ctrl.selectWcs(firstWcs)) {
    return refuse(`The controller would not select ${firstWcs}, so nothing was staged.`)
  }
  store().setActiveWcs(firstWcs)
  return stagePlannedProgram()
}

/** The work frame a posted file is already written in. The interpreter emits
 *  each stage's moves in the WORK coordinates of the frame that stage runs in -
 *  the file's own numbers - so the builder's world->work transform is the
 *  identity here. It is not a project WCS and never becomes one. */
const GCODE_TEXT_WORK_FRAME: WCS = {
  id: 'gcode-text',
  label: 'file',
  fixtureOffset: 54,
  origin: { x: 0, y: 0, z: 0 },
  xAxis: { x: 1, y: 0, z: 0 },
  yAxis: { x: 0, y: 1, z: 0 },
  zAxis: { x: 0, y: 0, z: 1 },
}

/** Every step of a file-loaded program traces to the file, not to an operation:
 *  there is no project operation behind a posted `.nc`, and a plausible wrong
 *  operation name on the readout is worse than none. */
const GCODE_TEXT_OP_ID = 'gcode-file'

/** What one section of a file is called where the operator reads it. Plain
 *  words with the one fact that distinguishes it: the frame it runs in. */
function sectionName(stage: GcodeStage, index: number): string {
  return `Section ${index + 1} (${stage.wcs})`
}

/** The M6 attached to one interpreted boundary, independent of whether it
 * closed the outgoing stage or opened the incoming one. */
function gcodeBoundaryToolChange(
  finished: GcodeStage,
  next: GcodeStage,
): { line: number; from: number; to: number } | null {
  return finished.ends.kind === 'tool-change' ? finished.ends : next.toolChangeBefore
}

/** An automatic M6 is opt-in: an ordinary sole park may be for stock loading,
 * while only a macro flagged `usedForToolChange` (WO-1681 fix round - the one
 * source; the pre-1681 wiring-store designation fallback is gone, WO-1681 fix
 * round 2) says this park is over the fixed probe pad. */
function configuredToolChangePark(): ParkPosition | null {
  // WO-2657: a hidden macro is off - neither a park nor the tool-change park;
  // with the flagged macro hidden the session runs as with none flagged.
  const machine = withoutHiddenMacros(parkCarrierMachine(useCamStore.getState()))
  const config = useMachineActions.getState().configFor(machine?.id ?? 'default')
  const parks = machineParkList(machine, config)
  return toolChangeMacroPark(machine, parks)
}

/**
 * WHAT WAS LOADED, BEFORE CYCLE START IS OFFERED - the file, the move count,
 * the frames in order and the spindle speed, which is what the toolpath load
 * line says about a setup.
 *
 * The coolant sentence is here because the file COMMANDS coolant and this route
 * has no coolant to command: the staged move list the board runs carries
 * motion, so M8 is something the operator has to do at the machine. Saying so
 * is the difference between a route that does what the file says and one that
 * quietly does most of it.
 */
/** WO-2106: the tools in the order the sections run them, a tool named again
 *  each time it comes back. `program.tools` names each tool once; when the
 *  sections do not account for every one of them it is said as before. */
function toolRunOrder(program: GcodeInterpretedProgram): number[] {
  const order: number[] = []
  for (const stage of program.stages) {
    if (stage.tool !== null && order[order.length - 1] !== stage.tool) order.push(stage.tool)
  }
  return program.tools.every((tool) => order.includes(tool)) ? order : program.tools
}

function describeGcodeTextLoad(
  name: string,
  program: GcodeInterpretedProgram,
  drivesSpindle: boolean,
  library: readonly Tool[],
  namingContext: ProgramContextV1 | null,
): string {
  const frames = program.frames.join(', then ')
  const speeds = program.spindleSpeeds
    .map((entry) => `${entry.rpm} RPM ${entry.direction.toUpperCase()}`)
    .join(', then ')
  const spindle = program.spindle === null
    ? 'no spindle command'
    : drivesSpindle
      ? `the spindle at ${speeds}`
      : `the spindle at ${speeds}, which this machine has no link to drive - start it yourself before `
        + 'CYCLE START'
  const sections = program.stages.length === 1
    ? `in ${frames}`
    : `in ${program.stages.length} sections - ${frames}`
  // COOLANT THIS MACHINE HAS NO OUTPUT FOR IS SAID ONCE, HERE. A channel the
  // record DOES state is commanded at the line that states it
  // (`applyGcodeCoolantWord`) and needs no sentence at load.
  const machine = controlMachine(useCamStore.getState())
  // A pin-switching controller answers the word from the definition's outputs
  // (finding h, 2026-09-17): a channel the resolver names a pin for is wired,
  // whatever the older HAS IT flag says.
  const ctrl = getMachineController()
  const pinSwitched = (channel: 'flood' | 'mist'): boolean =>
    !ctrl.capabilities.gcodeText && typeof ctrl.setOutput === 'function'
    && resolveMachineOutputWord(machine, coolantChannelWord(machine, channel))?.kind === 'switch'
  const unwired = ([['flood', program.coolant.flood], ['mist', program.coolant.mist]] as const)
    .filter(([channel, wanted]) => wanted && !pinSwitched(channel) && statedCoolantCapability(machine, channel) !== true)
    .map(([channel]) => channel)
  const coolant = unwired.length > 0
    ? ` The file commands ${unwired.join(' and ')} coolant, and this machine states no such output - `
      + 'switch it on at the machine.'
    : ''
  const holds = program.holdsWithNoMotion.length > 0
    ? ` The M0 on line ${program.holdsWithNoMotion.join(', ')} has no motion after it and was not staged.`
    : ''
  // A STOP BEFORE THE FIRST MOVE IS ALREADY HONOURED, and saying so is the
  // difference between honouring it and appearing to ignore it: a loaded
  // program moves nothing until the operator presses CYCLE START, which is
  // exactly what the file asked for at that line.
  const held = program.stages[0].heldBefore
  const heldFirst = held === null
    ? ''
    : ` The M${held.optional ? 1 : 0} on line ${held.line} comes before the first move - this program `
      + 'is loaded and holds there until CYCLE START.'
  // THE TOOLS, NAMED. More than one means the program holds at a tool change,
  // and the operator is choosing cutters on a bench - a bare number is not
  // enough to pick one up with.
  // WO-2106: named in the order they run, so a tool that comes back is named
  // again - T19, T1, T19 read "T19, then T1" (rehearsal 2026-09-27).
  const runOrder = toolRunOrder(program)
  const tools = program.tools.length === 0
    ? ''
    : ` It runs ${program.tools.length === 1 ? 'one tool' : `${program.tools.length} tools`}: `
      + `${runOrder.map((number) => describeGcodeTool(number, library, namingContext)).join(', then ')}`
      + `${program.tools.length > 1 ? ' - it holds at each change.' : '.'}`
  // WHAT `G43 H` RESOLVED TO, SAID OUT LOUD, because an offset applied
  // invisibly is an offset nobody can check. Each H is resolved against THIS
  // machine's tool table (WO-1677): a measured tool's length difference to
  // the reference tool is folded into every Z the H governs, so the staged
  // moves already carry it; a tool with no measured length applies zero - what the
  // operator's own controller answers for an unmeasured row - and the row
  // says so, once, here.
  const offsets = program.toolLengthOffsets.length === 0
    ? ''
    : ` Tool length: ${program.toolLengthOffsets
      .map((entry) => {
        const resolved = resolveG43ToolLengthMm(entry.h)
        return resolved.measured
          ? `G43 H${entry.h} on line ${entry.line} shifts Z by ${machineLengthText(resolved.deltaMm)}, `
            + `tool ${entry.h}'s measured length on this machine`
          : `G43 H${entry.h} on line ${entry.line} shifts Z by zero - tool ${entry.h} has no measured `
            + 'length on this machine'
      })
      .join('; ')}.`
  // WORDS READ AND HONOURED BY DOING NOTHING, said ONCE (architect re-scope) -
  // so the operator learns they were read rather than wondering.
  const accepted = program.accepted.length === 0
    ? ''
    : ` Read and carried by this route without changing it: ${program.accepted
      .map((entry) => `${entry.word} (${entry.note})`)
      .join('; ')}.`
  // WO-1652: a code one of this machine's macros carries runs that macro, at
  // any number. Every other number remains a named generic hold.
  const boundMacros = program.macros.flatMap((entry) => {
    const macro = boundMacro(entry.code)
    return macro === null ? [] : [{ ...entry, name: macro.name }]
  })
  // WO-2657: a code whose only macro is hidden from the panel is not run - the
  // program holds there as for any code no macro carries, naming the macro.
  const hiddenMacros = program.macros.flatMap((entry) => {
    const macro = hiddenBoundMacro(entry.code)
    return macro === null ? [] : [{ ...entry, name: macro.name }]
  })
  const unknownMacros = program.macros.filter((entry) => boundMacro(entry.code) === null
    && hiddenBoundMacro(entry.code) === null)
  const boundMacroSentence = boundMacros.length === 0
    ? ''
    : ` The file calls ${boundMacros
      .map((entry) => `M${entry.code} on line ${entry.line} (this machine's macro "${entry.name}")`)
      .join(', ')} - the program holds there and runs ${boundMacros.length === 1 ? 'it' : 'them'}.`
  const hiddenMacroSentence = hiddenMacros.length === 0
    ? ''
    : ` The file calls ${hiddenMacros
      .map((entry) => `M${entry.code} on line ${entry.line} (this machine's macro "${entry.name}", hidden from the `
        + 'Macros panel)')
      .join(', ')} - hidden, ${hiddenMacros.length === 1 ? 'it does' : 'they do'} not run; the program holds there.`
  const unknownMacro = unknownMacros.length === 0
    ? ''
    : ` The file calls ${unknownMacros.length === 1 ? 'a macro' : 'macros'} this app cannot run `
      + `(${unknownMacros.map((entry) => `M${entry.code} on line ${entry.line}`).join(', ')}) - the `
      + 'program holds there so you can do it at the machine.'
  // WO-1652: A CODE WITH A STANDARD MEANING ALWAYS KEEPS IT in a program (fix
  // round 4). A macro on M6 runs first, as a prelude, and the tool change
  // follows however it ends; a macro on any other such code is not run by a
  // program. Said once per code, naming the macro.
  const unusedBindings = program.tableCodeMacroBindings.flatMap((entry, index, all) => {
    if (all.findIndex((other) => other.code === entry.code) !== index) return []
    const macro = boundMacro(entry.code)
    if (macro === null) return []
    if (entry.code === 6) {
      return [`At each tool change (M6) the program holds, runs this machine's macro "${macro.name}" first, `
        + 'then the tool change itself - however the macro ends.']
    }
    return [`M${entry.code} on line ${entry.line} keeps its standard meaning; the macro "${macro.name}" bound to `
      + `M${entry.code} runs only from its button or a typed M${entry.code}.`]
  })
  const unusedBindingSentence = unusedBindings.length === 0 ? '' : ` ${unusedBindings.join(' ')}`
  return `Program "${name}" loaded: ${program.moveCount} moves ${sections} - ${spindle}.`
    + `${tools}${offsets}${coolant}${boundMacroSentence}${hiddenMacroSentence}${unknownMacro}${unusedBindingSentence}`
    + `${describeGcodeSpindleWords(program)}${heldFirst}${holds}${accepted}`
}

/** A tool number in the words the operator reads - the library's name when it
 *  has one, because a person at the spindle is choosing between cutters on a
 *  bench and `T2` is not enough to pick one up with (WO-1323's rule).
 *  WO-2642: a program posted live from the open project ('live-setup') carries
 *  its own tools in its context, each with the number it posts as (WO-2637);
 *  that tool is named, never a library tool that merely shares the number. A
 *  file opened from disk (verified export or not) reads the library, as before. */
function describeGcodeTool(
  number: number,
  library: readonly Tool[],
  context: ProgramContextV1 | null = loadedProgramContext(),
): string {
  const ownTools = new Map<string, string>()
  for (const op of context?.source === 'live-setup' ? context.operations : []) {
    if (op.tool.toolNumber === number) ownTools.set(op.tool.id, op.tool.name)
  }
  if (ownTools.size === 1) return `T${number} (${[...ownTools.values()][0]})`
  const matches = library.filter((tool) => tool.toolNumber === number)
  return matches.length === 1 ? `T${number} (${matches[0].name})` : `T${number}`
}

/**
 * WO-2401: THE FILE LINE A SPINDLE CHANGE BETWEEN TWO STAGES IS NAMED BY. A
 * start or a new speed names the M3/M4 that set the speed the moves after it
 * run at. The word that closed the stage is not it when a post puts `M5`,
 * `T1 M6`, `M0` and then `M3 S18000` between two moves: the M5 closed the
 * stage, and the console named the M5's line for the M3 (desk rehearsal
 * 2026-10-02, D2). A stop keeps the word that closed the stage.
 */
function gcodeSpindleChangeLine(previous: GcodeStage, stage: GcodeStage): number {
  if (stage.spindleOn && stage.spindle !== null) return stage.spindle.line
  return previous.ends.kind === 'spindle' ? previous.ends.line : stage.firstLine
}

/**
 * WHERE THE FILE CHANGES ITS SPINDLE, AND WHAT RUNS EITHER SIDE (WO-1335 fix
 * round). It is also why the frame list can read "G55, then G55": a section
 * ends at an M3/M5 as well as at a frame change, because that is the only
 * instant this route can command the inverter at.
 */
function describeGcodeSpindleWords(program: GcodeInterpretedProgram): string {
  const stops: number[] = []
  const starts: number[] = []
  for (let i = 1; i < program.stages.length; i++) {
    const stage = program.stages[i]
    const previous = program.stages[i - 1]
    // A CHANGE OF SPEED counts too, now that a file may carry more than one:
    // it is a start as far as the operator and the up-to-speed gate are
    // concerned, because the moves behind it wait for the new speed.
    const changed = stage.spindleOn !== previous.spindleOn
      || stage.spindle?.rpm !== previous.spindle?.rpm
      || stage.spindle?.direction !== previous.spindle?.direction
    if (!changed) continue
    ;(stage.spindleOn ? starts : stops).push(gcodeSpindleChangeLine(previous, stage))
  }
  if (stops.length === 0 && starts.length === 0) return ''
  if (starts.length === 0) {
    return ` The file stops the spindle on line ${stops.join(', ')} - the moves after it run with the `
      + 'spindle off.'
  }
  if (stops.length === 0) {
    return ` The file starts the spindle on line ${starts.join(', ')} - the moves before it run with `
      + 'the spindle off.'
  }
  return ` The file stops the spindle on line ${stops.join(', ')} and starts it again on line `
    + `${starts.join(', ')} - the moves in between run with the spindle off.`
}

/** The macro attached to one interpreted boundary, independent of whether it
 * closed the outgoing stage or opened the incoming one. */
function gcodeBoundaryMacro(
  finished: GcodeStage,
  next: GcodeStage,
): { line: number; code: number; toolChange?: number } | null {
  return finished.ends.kind === 'macro' ? finished.ends : next.macroBefore
}

/** What the operator is told AT a file's boundary. A frame change and an M0 are
 *  the same hold with different reasons, and the reason is the whole value of
 *  the sentence - a bare pause is what forces an operator to guess. */
function describeGcodeBoundaryHold(
  name: string,
  finished: GcodeStage,
  next: GcodeStage,
  drivesSpindle: boolean,
  library: readonly Tool[],
): string {
  // The interpreter gives each file pause its own boundary, before or after
  // a tool change or macro. Name only the action at this boundary.
  const change = gcodeBoundaryToolChange(finished, next)
  if (change !== null && change !== undefined) {
    const from = describeGcodeTool(change.from, library)
    const to = describeGcodeTool(change.to, library)
    // AND THE FRAME, WHEN IT ALSO CHANGES. Our own two-setup post puts the tool
    // change and the `G55` at the same boundary, and an operator told to fit a
    // cutter still has to know the next section runs at a different zero.
    const frame = next.wcs === finished.wcs ? '' : ` The rest runs in ${next.wcs}.`
    return `"${name}" has finished everything it cuts with ${from} and asks for ${to} on line `
      + `${change.line}. The spindle is stopped and the tool is where the file left it: fit `
      + `${to}, set its Z zero, then press CYCLE START to run the rest.${frame}`
  }
  // WO-1652: a code one of this machine's macros carries runs that macro here.
  // Any adjacent M0 belongs to a separate boundary and separate release.
  const macro = gcodeBoundaryMacro(finished, next)
  if (macro !== null && macro !== undefined) {
    const bound = boundMacro(macro.code)
    if (bound !== null) {
      return `"${name}" reached M${macro.code} on line ${macro.line}: running this machine's macro `
        + `"${bound.name}".`
    }
    const hidden = hiddenBoundMacro(macro.code)
    if (hidden !== null) {
      return `"${name}" stopped at M${macro.code} on line ${macro.line}: this machine's macro "${hidden.name}" is `
        + 'hidden from the Macros panel, so it was not run. Press CYCLE START to run the rest.'
    }
    return `"${name}" stopped at the M${macro.code} macro call on line ${macro.line}, which this app `
      + 'cannot run. Do at the machine whatever that macro does, then press CYCLE START to run the rest.'
  }
  // THE FILE'S STOP NAMES THE HOLD wherever it sits: an M0 with the frame
  // change or the M5 between it and the last move is still the line the
  // operator is standing at, and the first round reported it as "not staged".
  const stated = finished.ends.kind === 'hold' ? finished.ends : next.heldBefore
  if (stated !== null && stated !== undefined) {
    return `"${name}" stopped at the M${stated.optional ? 1 : 0} on line `
      + `${stated.line}. Press CYCLE START to run the rest in ${next.wcs}.`
  }
  // A SPINDLE THIS MACHINE CANNOT COMMAND, started mid-file. The audit's second
  // blocking finding: the console used to say "start it at the machine" and
  // then release the cut immediately, so the instruction named something nobody
  // could carry out before the move it governed. It is a hold like every other.
  if (!drivesSpindle && next.spindleOn && next.spindle !== null
    && (!finished.spindleOn
      || finished.spindle?.rpm !== next.spindle.rpm
      || finished.spindle?.direction !== next.spindle.direction)) {
    const line = gcodeSpindleChangeLine(finished, next)
    const verb = finished.spindleOn ? 'Set the spindle' : 'Start the spindle'
    return `"${name}" asks for the spindle at ${next.spindle.rpm} RPM `
      + `${next.spindle.direction.toUpperCase()} on line ${line}, and this machine has no link to `
      + `${finished.spindleOn ? 'change' : 'start'} it. ${verb} at the machine, then press CYCLE `
      + 'START to run the rest.'
  }
  return `"${name}" has finished everything it runs in ${finished.wcs} and the tool has lifted to `
    + `where the file left it. Set up for ${next.wcs}, then press CYCLE START to run the rest.`
}

/**
 * THE TOOL, IN THE WORDS THE OPERATOR READS ON THE MACHINE (WO-1323).
 *
 * A tool number alone is what the posted file says because G-code has nothing
 * else to say it with; a person standing at the spindle is choosing between
 * cutters on a bench, so the name comes too. A tool with no number in the
 * library is named without one rather than given a made-up `T0`.
 */
function describeProgramTool(tool: Tool): string {
  return typeof tool.toolNumber === 'number' && Number.isFinite(tool.toolNumber)
    ? `T${tool.toolNumber} (${tool.name})`
    : tool.name
}

/** The one refusal shape every toolpath door uses: readiness says why, the
 *  console says why, and the arm epoch moves so every control re-reads. */
function refuseProgramLoad(reason: string): { ok: false; reason: string } {
  store().setProgramReadiness({ ready: false, reason })
  store().pushConsole('rx', reason, 'error')
  bumpArmEpoch()
  return { ok: false, reason }
}

/** WO-2686 fix round 6: a candidate Load refused over a loaded program. The
 *  refusal is about the file he tried to load, not the one still loaded:
 *  one console line, and that program's readiness, arm epoch and chosen start
 *  stay exactly as they were. */
function refuseCandidateProgramLoad(reason: string): { ok: false; reason: string } {
  store().pushConsole('rx', reason, 'error')
  return { ok: false, reason }
}

/** WO-2686: an accepted program a refused candidate Load must not disturb -
 *  staged and ready on this controller (armed from line 1 or line N), a start
 *  the operator chose (kept stop, Step Back, a hold, or one a reconnect
 *  destroyed), or a file waiting for its offsets. Fix round 7: a file merely
 *  retained across a reconnect is not staged anywhere ("Reconnect and reload
 *  the program."), so a refusal takes readiness there as on main; CYCLE START
 *  still reads that file's fit for itself. */
function programIsLoaded(): boolean {
  return store().programReadiness.ready || store().job.phase === 'paused'
    || operatorHasChosenStart() || operatorChosenStartLost() || programAwaitingOffsets !== null
}

/** Refuse a replacement load without rewriting the running program's
 * readiness. The console still owns one durable row for the refusal. */
function refuseActiveProgramLoad(): { ok: false; reason: string } {
  const reason = 'The program is still running - Feed Hold, then Stop, before loading another.'
  store().pushConsole('rx', reason, 'error')
  return { ok: false, reason }
}

/** One setup, validated and resolved into the sections a program is built
 *  from. Split out of `loadSetupToolpathProgram` by WO-1323 with its refusals
 *  word for word: a multi-setup program asks each of its setups exactly the
 *  same questions, and two copies of these gates are how one door would start
 *  accepting a setup the other refuses. */
interface CollectedSetupSections {
  setup: Setup
  sections: ToolpathProgramSection[]
  /** Distinct tools across the setup's sections - one, or the setup refused. */
  toolIds: string[]
  spindle: ProgramSpindle | undefined
}

async function collectSetupProgramSections(
  setupId: string,
): Promise<
  | { ok: true; value: CollectedSetupSections }
  /** `toolChange`: every other gate passed; the setup needs a tool change. */
  | { ok: false; reason: string; toolChange?: true }
> {
  const refuse = (reason: string): { ok: false; reason: string } => ({ ok: false, reason })

  // WO-1653: THE MOMENT CODE LEAVES THE APP. An operation genuinely outdated
  // (a real edit or a real disable already sitting in the project) is
  // recomputed here and now instead of refusing the whole load - the same
  // recompute Post stages before it builds its program. A Control run has no
  // per-operation selection (every enabled operation goes), so nothing here
  // is excluded on this call's own account; `includedOpIds: undefined` means
  // exactly that.
  await useCamStore.getState().stageOperationsForEmission(setupId, undefined)

  // THE SAME PROJECT VIEW THE POST RESOLVES AGAINST - the live tool library
  // merged over the project, exactly as `ProgramPanel` builds it for
  // `postProject`. The freshness fingerprint hashes the tool, so a different
  // view here would answer "out of date" for a setup the post calls current.
  // Read AFTER staging, so a just-recomputed operation is seen fresh.
  const state = useCamStore.getState()
  const project = { ...state.project, toolLibrary: state.toolLibrary }
  const setup = project.setups.find((candidate) => candidate.id === setupId)
  if (setup === undefined) {
    return refuse(`Setup "${setupId}" is not in this project, so there is nothing to load.`)
  }

  const enabled = setup.operations.filter((operation) => operation.enabled)
  const sections = collectToolpathSections(enabled, project.geometry, project.nests)
  if (sections.reduce((total, section) => total + section.moves.length, 0) === 0) {
    return refuse(
      `Setup "${setup.name}" has no computed toolpath to send - generate its operations, `
      + 'then load it again.',
    )
  }
  // A STALE TOOLPATH IS REFUSED ON BOTH ROUTES OR ON NEITHER.
  //
  // The post refuses an operation whose generated moves no longer match its
  // inputs (`buildPostInput` -> OP_OUTDATED), and it is right to: those moves
  // describe a part that is no longer the one on the screen. The toolpath door
  // reaches the same machine with the same consequence, so it asks the same
  // question with the same function. A door that skipped it would be the
  // shorter route to cutting last version's part.
  const stale = enabled.find((operation) => !operationGenerationIsCurrent(project, setup, operation))
  if (stale !== undefined) {
    return refuse(
      `Operation "${stale.name}" is out of date - recompute it before loading "${setup.name}".`,
    )
  }

  // AN ENABLED OPERATION THAT PRODUCED NOTHING IS REFUSED, NOT SKIPPED.
  //
  // `collectToolpathSections` DROPS an operation whose moves are empty
  // (`nestRuntime.ts` - `if (local.length === 0) continue`), and the
  // sum-is-zero guard above only fires when EVERY section is empty. So one
  // moveless operation among survivors armed as if the setup were complete:
  // readiness ready, CYCLE START enabled, `motionCount` honestly reported for
  // a program that is missing a cut. That is the software doing less than it
  // was asked and saying nothing.
  //
  // The staleness gate above cannot catch it and is not meant to:
  // `savedToolpathMatchesHeightSnapshot(..., allowEmpty = true)`
  // (`generationFingerprint.ts`) passes a current operation that legitimately
  // produced no moves ON PURPOSE, on the understanding that a separate
  // per-operation check refuses it. On the text door that check exists - the
  // CAM-12 block in `buildPostInput` re-adds every dropped op with empty moves
  // so `validateOpsReady` refuses with OP_NO_TOOLPATH. This is that check on
  // this door, said directly rather than by round trip through the post's
  // validators: two doors to the same machine refuse the same setup.
  //
  // It is a CANNOT, not a caution (Operator 2026-09-07): there are no moves for
  // that operation, so its cut genuinely cannot be sent. The operator is told
  // WHICH operation, so the choice - generate it, or turn it off and machine
  // the rest deliberately - stays theirs.
  //
  // An operation that has moves but no section of its own is not missing: a
  // computed nest seed folds its copies into the nest's expansion under the
  // nest's FIRST operation, which is the same exemption CAM-12 makes.
  const emittedOpIds = new Set(sections.map((section) => section.opId))
  const missing = enabled.find(
    (operation) =>
      !emittedOpIds.has(operation.id) && (operation.toolpathMoves?.length ?? 0) === 0,
  )
  if (missing !== undefined) {
    return refuse(
      `Operation "${missing.name}" has no moves to send, so loading "${setup.name}" would machine `
      + 'it without that cut. Generate the operation, or turn it off, then load again.',
    )
  }

  // A TOOL CHANGE IS A PROGRAM STEP THIS BUILDER CANNOT EMIT, so a setup that
  // needs one never becomes a motion-only program here: it would run as one
  // uninterrupted pass with whichever tool happens to be in the spindle. The
  // answer is flagged, not refused - WO-2013: the single-setup door posts such
  // a setup and stages it through the file door, which stops at each M6
  // (`loadSetupPostedProgram`). Only a caller with no such route (the
  // multi-setup door) turns this into the operator's refusal.
  const toolIds = [...new Set(sections.map((section) => section.toolId))]
  if (toolIds.length > 1) {
    return {
      ok: false,
      toolChange: true,
      reason: `Setup "${setup.name}" uses ${toolIds.length} tools, and a toolpath program carries motion `
        + 'only - it cannot stop for a tool change. Run one tool at a time.',
    }
  }

  // THE SAME RESOLVED SPINDLE THE TEXT PROGRAM USES. A machine record and the
  // live controller must both declare the VFD path; absence on either side
  // keeps this motion program byte-for-byte on its previous no-spindle path.
  // The current geometry slice can start once and stop once, so differing
  // per-operation settings are refused rather than silently collapsing them.
  let programSpindle: ProgramSpindle | undefined
  const ctrl = getMachineController()
  if (machineSpindleIsDrivable(project.machine, ctrl)) {
    const resolved = new Map<string, ProgramSpindle>()
    for (const section of sections) {
      if (resolved.has(section.opId)) continue
      const operation = enabled.find((candidate) => candidate.id === section.opId)
      const tool = project.toolLibrary.find((candidate) => candidate.id === section.toolId)
      if (!operation || !tool) {
        return refuse(
          `Operation "${section.opId}" has no resolvable tool, so its spindle speed cannot be `
          + 'determined. Nothing was sent.',
        )
      }
      const spindle = resolveSpindle(operation, tool, project.machine)
      resolved.set(section.opId, { rpm: spindle.rpm, direction: spindle.dir })
    }
    const settings = [...resolved.values()]
    programSpindle = settings[0]
    const mismatch = settings.find(
      (candidate) => candidate.rpm !== programSpindle?.rpm
        || candidate.direction !== programSpindle.direction,
    )
    if (mismatch) {
      return refuse(
        `Setup "${setup.name}" asks for more than one spindle speed or direction, and this `
        + 'toolpath program can command only one. Run those operations as separate setups.',
      )
    }
  }

  return {
    ok: true,
    value: {
      setup,
      toolIds,
      spindle: programSpindle,
      sections: sections.map((section) => {
        const operation = enabled.find((candidate) => candidate.id === section.opId)
        const tool = project.toolLibrary.find((candidate) => candidate.id === section.toolId)
        return {
          opId: section.opId,
          moves: section.moves,
          ...(operation && tool
            ? {
                feeds: resolveFeedrates(
                  tool,
                  operation.feedrateOverride,
                  controlMachine(useCamStore.getState()).rapidRate,
                ),
              }
            : {}),
        }
      }),
    },
  }
}

/** The plain reasons re-arming is refused. Exported so the transport verdict
 *  that renders the control and the action that performs it cannot drift into
 *  telling the operator two different stories. */
export const RE_ARM_REFUSAL = {
  noProgram: 'No program is loaded - open or post one first.',
  alarm: 'The machine is in alarm - clear the alarm before re-arming.',
  running: 'The program is still running - Feed Hold, then Stop/Reset, before re-arming.',
  changed: 'Another program was loaded during the controller reset, so nothing was re-armed.',
  /** WO-087. Prefix for a controller that would not come back to a known idle
   *  state; resetToIdle()'s own sentence is appended so the operator is told
   *  WHICH way it failed to answer. */
  notReset: 'The controller could not be returned to a known idle state, so nothing was re-armed.',
} as const

type ArmFromTopResult = { ok: true } | { ok: false; reason: string }

/**
 * Whether re-arming has to flush the controller first (WO-087).
 *
 * The question is not "does the app think the run is over" - WO-082 asked that
 * one and shipped the defect. It is "has GRBL SAID it is idle and empty since
 * that run started", which is exactly what verifiedIdle() answers and nothing
 * else in the app can. A failed cycle leaves the machine in Hold with the rest
 * of the run buffered, so it never says Idle, so the flush always happens.
 *
 * Disconnected is the one honest no-op: there is no controller holding
 * anything, arming is a local act (WO-082), and a reconnect re-reads the
 * banner anyway. Everything else defaults to flushing, because "we have not
 * been told" and "it is safe" are not the same sentence.
 */
function reArmNeedsFlush(ctrl: MachineController): boolean {
  if (ctrl.connectionPhase() !== 'connected') return false
  return !ctrl.verifiedIdle()
}

/**
 * Re-arm the CURRENT program from its BEGINNING (WO-082) - "run the part
 * again", the most basic thing a CNC does. Before this the ONLY re-arm path
 * was armRunFromLine(), and runFromLine correctly refuses the first sendable
 * line, so after a completed, failed, or stopped cycle every route back to the
 * top was closed and the operator had to reload the file.
 *
 * The three safety rules, all non-negotiable:
 *  - IT ARMS ONLY. Nothing that can start motion is sent. CYCLE START remains
 *    the sole gesture that begins motion, exactly as it is after a fresh load.
 *  - IT IS A FRESH START, not a mid-program reconstruction: no prelude, no
 *    inherited modal state, no leftover progress or error from the finished
 *    run. It runs the same loadMachineProgram() a file load runs, so the armed
 *    state is indistinguishable from having just opened the program.
 *  - IT IS REFUSED, with a plain reason, during a live cycle or an alarm. A
 *    second arm mid-stream is exactly how a spindle gets crashed.
 *
 * WO-087 - and "indistinguishable from having just loaded that program" is a
 * statement about the CONTROLLER, not only about this app. WO-082 replaced the
 * local streamer bookkeeping and stopped there, so after a FAILED cycle the
 * operator could re-arm while GRBL was still in Hold with the rest of the
 * first run queued inside it; CYCLE START then either sat blocked in Hold or
 * ran stale first-run lines ahead of the new program. So when the controller
 * could still be holding motion from the last run, this now brings it back to
 * a VERIFIED idle first (GrblController.resetToIdle, which derives its
 * sequence from the protocol doc) and REFUSES if that cannot be proven.
 * Refusing is always safe; arming on top of an unknown controller is not.
 */
export async function armProgramFromTop(
  /** WO-2689: false when the caller says the refusal in its own line (CYCLE
   *  START's "Cycle Start: refused - ...", run-from-line's "Run from line N
   *  refused: ...") - one press, one line. The Re-arm button says it here. */
  options: { sayRefusal?: boolean } = {},
): Promise<ArmFromTopResult> {
  const s = store()
  if (!s.programText) return { ok: false, reason: RE_ARM_REFUSAL.noProgram }
  if (s.machineState === 'alarm') return { ok: false, reason: RE_ARM_REFUSAL.alarm }
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const phase = ctrl.jobProgress().phase
  if (controllerJobReallyRuns(ctrl) || (!ctrl.hasActiveJob() && phase === 'streaming') || phase === 'paused') {
    return { ok: false, reason: RE_ARM_REFUSAL.running }
  }
  if (reArmNeedsFlush(ctrl)) {
    const reset = await ctrl.resetToIdle()
    if (!receiptIsCurrent(receiptToken)) return { ok: false, reason: RE_ARM_REFUSAL.changed }
    if (!reset.ok) return { ok: false, reason: `${RE_ARM_REFUSAL.notReset} ${reset.reason}` }
    // The reset is a controller-level event the store has to see before the
    // program is armed on top of it - a refused re-arm must not leave the UI
    // showing an armed job.
    store().applyJobProgress(ctrl.jobProgress())
    // Re-check after every reset await and immediately before load. Another
    // authority may have started or loaded work while this call was waiting;
    // overwriting it would make this stale caller falsely report success.
    const afterReset = store()
    const afterResetPhase = ctrl.jobProgress().phase
    if (
      controllerJobReallyRuns(ctrl) ||
      (ctrl.hasActiveJob() === false && afterResetPhase === 'streaming') ||
      afterResetPhase === 'paused'
    ) {
      return { ok: false, reason: RE_ARM_REFUSAL.running }
    }
    if (afterReset.programText !== s.programText || afterReset.job.name !== s.job.name) {
      return { ok: false, reason: RE_ARM_REFUSAL.changed }
    }
  }
  // WO-1996: the reload can refuse (the controller's reader, a mesh, a line it
  // cannot stream). That used to return ok, so Re-arm silently did nothing.
  // A lint caution on an armed program is not a refusal and still returns ok.
  // WO-2689: the reload is not a Load. Its refusal is said once below, in
  // Re-arm's own line; the Load's '"<name>" was not loaded: <reason>' line is
  // the Load's, and printing it again here doubled it on every Re-arm or
  // CYCLE START after a refused Load.
  const reload = loadTextProgram(s.job.name ?? 'program', s.programText, undefined, false, false)!
  if (reload.lines.length === 0 || reload.overlongLines.length > 0) {
    const reason = `Re-arm from start did not arm the program: ${store().programReadiness.reason}`
    if (options.sayRefusal !== false) store().pushConsole('rx', reason, 'error')
    return { ok: false, reason }
  }
  // WO-2237: the operator chose the top; a kept place is not what runs.
  forgetKeptStop()
  return { ok: true }
}

type ArmFromLineResult =
  | { ok: true; from: 'line'; plan: RunFromLinePlan }
  | { ok: true; from: 'top' }
  | { ok: false; reason: string }

/**
 * The OPERATOR's "start at line N" entry point (WO-082). A request that lands
 * on the program's first sendable line is not a mid-program start, and the
 * planner is right to refuse it - but refusing the PLANNER and refusing the
 * OPERATOR are different things. When the only thing wrong is "there is no
 * prefix to reconstruct", the answer is to arm a normal start, so this routes
 * that one refusal to armProgramFromTop() instead of returning a dead end.
 * Every other refusal (G91, arc modal, out of range) still refuses, unchanged.
 *
 * armRunFromLine() itself is deliberately NOT changed: the guided tool change
 * and clamp-pause flows re-arm at a computed resume line and must keep getting
 * the planner's literal verdict.
 */
export async function armProgramFromLine(requestedLine: number): Promise<ArmFromLineResult> {
  // WO-2609 kit: opened files need no CAM context to plan their own lines.
  // The file-door record checks controller and loaded-program identity.
  if (store().programText === null && currentFileDoorProgram() !== null) {
    return armPostedProgramFromLine(requestedLine)
  }
  const planned = armRunFromLine(requestedLine)
  if (planned.ok) {
    // WO-2237: the operator chose this line; a kept place is not what runs.
    forgetKeptStop()
    return { ok: true, from: 'line', plan: planned.plan }
  }
  if (!planned.atProgramStart) return { ok: false, reason: planned.reason }
  const top = await armProgramFromTop({ sayRefusal: false })
  return top.ok ? { ok: true, from: 'top' } : { ok: false, reason: top.reason }
}

/**
 * WO-2686: arm the loaded program from line 1, through the door that took it -
 * the text door's re-arm, or the file door staging its file from the top. The
 * operator's CYCLE START on a loaded program that is not armed (after a
 * complete, failed or stopped run, a reconnect, an alarm). It arms only; the
 * start is the caller's, through the same verdict a fresh load gets.
 */
export async function armLoadedProgramFromLine1(): Promise<ArmFromTopResult> {
  if (store().programText !== null) return armProgramFromTop({ sayRefusal: false })
  if (fileDoorProgramForLine1() === null) return { ok: false, reason: RE_ARM_REFUSAL.noProgram }
  const armed = await armPostedProgramFromLine(1, true)
  return armed.ok ? { ok: true } : armed
}

/**
 * WO-2686 (machine-seat desk row, case 1, 10-08): the file the file door
 * staged survives a reconnect as the loaded program - the header still names
 * it - but its record names the controller it was staged on, so every door
 * that asks for "the file on this controller" answers null and CYCLE START
 * had nothing to arm ("No program is armed.") after Disconnect, Connect, Home
 * All and an offset that now fits. Arming from line 1 is a fresh staging of
 * that same file through the file door, so it takes the file from the record
 * whichever controller staged it, while the session still names it and
 * nothing else is loaded. Every other door keeps asking for the live file.
 */
function fileDoorProgramForLine1(): ToolpathProgramReload | null {
  const live = currentFileDoorProgram()
  if (live) return live
  const reload = toolpathProgramReload
  const s = store()
  if (!reload || !reload.publishListing || reload.controller === controller) return null
  if (s.programText !== null || s.job.name !== reload.name) return null
  return reload
}

/**
 * WO-2686 fix round 4: WHETHER THE LOADED FILE FITS THE MACHINE AS IT STANDS -
 * DERIVED, NEVER REMEMBERED. Three cached refusals each outlived the thing
 * that made them true (a name, a busy machine, a corrected G30 point), so
 * CYCLE START's verdict on a loaded file that is not armed reads the file
 * again here, with the file door's own reader and inputs (offsets, position,
 * G28/G30 points, tool lengths, definition, travel), and refuses with the
 * Load's own sentence exactly while that reading refuses it: the reader, arcs
 * with no declared travel, a move outside the travel. Every other refusal
 * (no rapid rate, an unset frame, the controller's own) stays the staging's
 * at the press, with its own sentence. Null when it fits, or nothing is loaded.
 *
 * Memoized on every input it read, so a verdict re-render costs a comparison.
 * It has no session effects: it reads, it never stages, publishes or ends anything.
 */
export function loadedFileFitRefusal(): string | null {
  const file = fileDoorProgramForLine1()
  if (file === null) return null
  const ctrl = getMachineController()
  const state = useCamStore.getState()
  const activeMachine = controlMachine(state)
  const rapidFeedMmMin = activeMachine.rapidRate
  const dialect = gcodeTableDialectOf(state.project.machine?.controller)
  const sessionWcs = store().activeWcs
  const startedAt = readerPosition(ctrl, activeMachine)
  if (!(typeof rapidFeedMmMin === 'number' && Number.isFinite(rapidFeedMmMin) && rapidFeedMmMin > 0)
    || dialect === null || !sessionWcs || startedAt === null) return null
  // Under an applied surface mesh the file is compiled at staging, which also
  // ends a re-zeroed mesh - session effects a verdict must not have. The
  // press's staging reads it there and refuses in its own words.
  if (store().surfaceMesh?.active) return null
  const readerOffsets = readerWorkOffsets()
  const envelope = currentResolvedMachineMotion().envelope
  const options = fileReaderOptions(state, activeMachine, dialect, sessionWcs as GcodeWcs, startedAt, readerOffsets,
    (h, wcs) => readerToolLengthMm(ctrl, h, wcs))
  const key = [file.name, file.text, ctrl, rapidFeedMmMin, JSON.stringify([options.dialect, options.sessionWcs,
    options.initialPosition, options.workOffsets, options.referencePositions, options.machineHome, envelope]),
  options.machineDefinition]
  const memo = loadedFileFit
  if (memo !== null && memo.key.length === key.length && memo.key.every((value, i) => value === key[i])
    && memo.toolLengths.every((asked) => Math.abs(readerToolLengthMm(ctrl, asked.h, asked.wcs) - asked.mm) < 1e-9)) {
    return memo.refusal
  }
  const toolLengths: { h: number; wcs: string; mm: number }[] = []
  const refusal = fileFitRefusal(file.name, file.text, {
    ...options,
    toolLengthMm: (h, wcs) => {
      const mm = readerToolLengthMm(ctrl, h, wcs)
      toolLengths.push({ h, wcs, mm })
      return mm
    },
  }, rapidFeedMmMin, startedAt, readerOffsets, envelope)
  loadedFileFit = { key, toolLengths, refusal }
  return refusal
}

let loadedFileFit: {
  key: unknown[]
  toolLengths: { h: number; wcs: string; mm: number }[]
  refusal: string | null
} | null = null

/** The file door's fit refusals, word for word (`loadGcodeTextToolpathProgram`):
 *  the reader's, arcs that need declared travel, and the first move outside it. */
function fileFitRefusal(
  name: string,
  text: string,
  options: GcodeInterpretOptions,
  rapidFeedMmMin: number,
  startedAt: GcodeReaderPoint,
  readerOffsets: ReaderWorkOffsets,
  envelope: ReturnType<typeof currentResolvedMachineMotion>['envelope'],
): string | null {
  const interpreted = interpretGcodeProgram(text, options)
  if (!interpreted.ok) return `"${name}" was not loaded. ${interpreted.refusal.message}`
  const program = interpreted.program
  const allMoves = program.stages.flatMap((stage) => stage.moves)
  const allLines = program.stages.flatMap((stage) => stage.moveLines)
  const built = buildStraightLineProgram(allMoves, GCODE_TEXT_WORK_FRAME, rapidFeedMmMin, {
    opId: GCODE_TEXT_OP_ID,
    setupId: name,
  }, undefined, startedAt)
  if (!built.ok) return null
  const motionSteps = built.program.steps.filter(isStagedMove) as QueuedMove[]
  if (motionSteps.length !== allMoves.length) return null
  let cursor = 0
  for (const stage of program.stages) {
    const steps = motionSteps.slice(cursor, cursor + stage.moves.length)
    const firstIndex = cursor
    cursor += stage.moves.length
    const wco = readerOffsets[stage.wcs as GcodeWcs]
    if (wco === undefined) return null
    if (steps.some((step) => step.kind === 'arc') && (!envelope.x || !envelope.y)) {
      return arcsNeedTravelMessage(`"${name}"`)
    }
    const stageProgram: MachineProgram = {
      frame: 'work',
      units: 'mm',
      steps,
      index: Object.fromEntries(
        steps.map((step) => [step.id, built.program.index[step.id]]).filter(([, v]) => v !== undefined),
      ) as ProgramIndex,
    }
    const offence = firstStepOutsideTravel(stageProgram, wco, envelope, ENVELOPE_FIT_TOLERANCE_MM, controllerRotationDeg(stage.wcs))
    if (offence === null) continue
    const index = steps.findIndex((step) => step.id === offence.stepId)
    const stagedLine = index < 0 ? undefined : allLines[firstIndex + index]
    const line = stagedLine ?? stage.firstLine
    return `"${name}", line ${line}: ${describeTravelOffence(offence, stageProgram)}`
  }
  return null
}

/** WO-2686: whether a file the file door took is the loaded program CYCLE
 *  START can arm from line 1 - the live one, or the one a reconnect left named. */
export function loadedFileArmableFromLine1(): boolean {
  return fileDoorProgramForLine1() !== null
}

/** WO-2598: one planner, staged through the same file door as a kept return.
 * The full listing/text remain the authority for another line, Cancel and Stop.
 * `fromTop` (WO-2686) stages the whole file: no plan, so no planner refusal. */
async function armPostedProgramFromLine(requestedLine: number, fromTop = false): Promise<ArmFromLineResult> {
  clearRunFromReview()
  const s = store()
  const ctrl = getMachineController()
  const fileOf = fromTop ? fileDoorProgramForLine1 : currentFileDoorProgram
  const file = fileOf()
  if (!file) return { ok: false, reason: RE_ARM_REFUSAL.noProgram }
  if (s.machineState === 'alarm') return { ok: false, reason: RE_ARM_REFUSAL.alarm }
  if (controllerJobReallyRuns(ctrl) || ctrl.jobProgress().phase === 'paused') {
    return { ok: false, reason: RE_ARM_REFUSAL.running }
  }
  if (!fromTop && loadedTextRunsCompensated(file.text)) {
    return { ok: false, reason: 'Run from line is disabled while surface mesh compensation is active. Re-arm from the top or disable the mesh.' }
  }
  const planned: RunFromLineResult = fromTop
    ? { ok: false, reason: 'The program start.', atProgramStart: true }
    : buildRunFromLinePlan(file.text, requestedLine, runFromLineMachineOptions())
  if (!planned.ok && !planned.atProgramStart) {
    if (ctrl.jobProgress().phase === 'ready' && file.runFrom) restageLoadedProgram()
    return planned
  }
  const program = planned.ok ? toolWordsBefore(file.text, planned.plan.startLine) : null
  // A file's prefix names the tool it NEEDS, never proof that it is fitted.
  // Seed the reader with the reported spindle tool, then run the missing M6
  // through its existing fence/boundary/guided setter flow before the prelude.
  const fitted = s.activeTool ?? 0
  const needsFit = program?.inSpindle !== null && program?.inSpindle !== undefined
    && program.inSpindle !== fitted
  const plan = planned.ok ? {
    ...planned.plan,
    // The file reader must know the fitted tool and any pending preselect,
    // otherwise a later bare M6 can be mistaken for the file's first tool.
    prelude: [
      ...(needsFit ? [`T${fitted}`, 'G4 P0', `T${program!.inSpindle} M6`] : []),
      ...fileReturnToolWords(program!, program!.inSpindle), ...planned.plan.prelude,
    ],
  } : null
  const numbering = plan ? returnFileNumbering({ controller: ctrl, sourceLineOf: (line) => line }, plan) : undefined
  const text = plan
    ? [...plan.prelude, ...applyResumeMotion(file.text, plan).split(/\r?\n/).slice(plan.startLine - 1)].join('\n')
    : file.text
  const token = captureBackendReceipt(ctrl)
  if (reArmNeedsFlush(ctrl)) {
    const reset = await ctrl.resetToIdle()
    if (!receiptIsCurrent(token) || fileOf() !== file) return { ok: false, reason: RE_ARM_REFUSAL.changed }
    if (!reset.ok) return { ok: false, reason: `${RE_ARM_REFUSAL.notReset} ${reset.reason}` }
    if (controllerJobReallyRuns(ctrl) || ctrl.jobProgress().phase === 'paused') return { ok: false, reason: RE_ARM_REFUSAL.running }
  }
  const readiness = store().programReadiness
  store().setProgramReadiness({ ready: false, reason: `Staging the program from line ${requestedLine}.` })
  let stagedRevision = -1
  // The frame receipt can complete asynchronously. Report an arm only after
  // staging; a refusal or superseding load must settle this caller too.
  const staged = await new Promise<{ ok: boolean; reason: string | null }>((resolve) => {
    const outcome = loadGcodeTextToolpathProgram(file.name, text, {
      ...(plan ? { keepsLoadedProgram: true, runFromFile: file, fileNumbering: numbering } : {
        publishListing: true, context: file.context,
      }),
      fileReread: true,
      runThroughOffsetChanges: file.runThroughOffsetChanges,
      ...(needsFit && plan ? { restartToolChangePreludeLines: plan.prelude.length } : {}),
      onStageResult: (outcome) => { stagedRevision = geometryProgramLoadRevision; resolve(outcome) },
      // A missing offset is an arm refusal here, not a new waiting file.
      onStaged: () => false,
      loadLine: () => null,
    })
    if (!outcome.ok) resolve(outcome)
  })
  if (!receiptIsCurrent(token) || stagedRevision !== geometryProgramLoadRevision) return { ok: false, reason: RE_ARM_REFUSAL.changed }
  if (!staged.ok) {
    if (ctrl.jobProgress().phase === 'ready' && currentFileDoorProgram() === file && file.runFrom) restageLoadedProgram()
    return { ok: false, reason: staged.reason ?? 'The controller did not stage the program.' }
  }
  const verdict = await boardLoadVerdict(ctrl)
  if (!receiptIsCurrent(token) || stagedRevision !== geometryProgramLoadRevision) return { ok: false, reason: RE_ARM_REFUSAL.changed }
  if (verdict?.ok === false) return { ok: false, reason: verdict.reason ?? 'The controller refused the program.' }
  if (plan) store().setProgramReadiness({
    ready: true,
    reason: readiness.ready ? readiness.reason : `Program "${file.name}" is armed from line ${plan.startLine}.`,
  })
  forgetKeptStop()
  if (plan) {
    store().setArmedFromLine(plan.startLine)
    chosenStartAtEpoch = armEpochValue
    for (const line of plan.notSetUp) store().pushConsole('rx', line, 'warn')
    return { ok: true, from: 'line', plan }
  }
  return { ok: true, from: 'top' }
}

/**
 * Re-arm the CURRENT program for a mid-program start. Plans the modal
 * restore/positioning prelude (the operator's line always starts - Operator's
 * ruling 2026-09-26; what it cannot set up is a console line), loads the sliced job,
 * and returns the plan for the UI to show BEFORE the operator starts it.
 */
export function armRunFromLine(requestedLine: number, answeredM6Line?: number): RunFromLineResult {
  clearRunFromReview()
  const s = store()
  if (!s.programText) return { ok: false, reason: 'No program is loaded.' }
  if (loadedTextRunsCompensated(s.programText)) {
    return {
      ok: false,
      reason: 'Run from line is disabled while surface mesh compensation is active. Re-arm from the top or disable the mesh.',
    }
  }
  const programText = s.programText
  const options = runFromLineMachineOptions()
  const planned = buildRunFromLinePlan(programText, requestedLine, options)
  const ctrl = getMachineController()
  if (!planned.ok) {
    // SAFETY (WO-006, d20f0892e audit finding 1): a failed (re-)plan must not
    // leave a previously armed sliced job sendable behind the canonical CYCLE
    // START. Restore the full program - the same state Cancel produces. When
    // the streamer holds no ready job (e.g. a guided flow after a controlled
    // stop) there is nothing armed, so nothing is restored.
    restoreFullProgramIfArmed(ctrl, programText)
    return planned
  }
  // WO-1008: a mid-program start flies a PRELUDE plus a slice of the program,
  // not the program that was loaded. The check has no derivation for either, so
  // it refuses in words rather than score the run against a path it was never
  // given - the whole-program queue armed at load would report the skipped part
  // as a divergence.
  refusePathFidelity(RUN_FROM_LINE_NOT_CHECKED)
  // WO-1997: the slice keeps the load's M6 holds. Re-arming the raw text after
  // a guided change let the NEXT M6 run straight by - the readiness walk's
  // missing last tool change.
  const loaded = loadRunFromSlice(ctrl, programText, planned.plan, options, (o) =>
    buildRunFromLinePlan(programText, requestedLine, o), answeredM6Line)
  if (!loaded.ok) {
    restoreFullProgramIfArmed(ctrl, programText)
    return loaded
  }
  textJobFirstLine = loaded.plan.startLine
  store().applyJobProgress(ctrl.jobProgress())
  chosenStartAtEpoch = armEpochValue
  return { ok: true, plan: loaded.plan }
}

type StepBackResult =
  | { ok: true; plan: RunFromLinePlan; controlledStop: boolean }
  | { ok: false; reason: string }

const STEP_BACK_REFUSAL = {
  noProgram: 'No program is loaded.',
  disconnected: 'Connect to the machine before stepping back.',
  singleBlock: 'Turn Single Block on before stepping back.',
  moving: 'Feed Hold and wait for Hold before stepping back.',
  changed: 'The program or cursor changed during the controlled stop, so Back was cancelled.',
  busy: 'A Step Back controlled stop is already in progress.',
  stop: 'The machine did not come to a clean stop - resolve its state, then retry Back.',
} as const

/**
 * Re-arm one sendable source line behind the live cursor. This action never
 * starts motion. If GRBL is holding mid-block, it first uses the same
 * decelerate/settle/reset controlled-stop sequence as guided clamp recovery;
 * the returned run-from plan is then the operator's confirmation card and
 * canonical CYCLE START remains the only gesture that can move the machine.
 */
export async function stepBackOneLine(): Promise<StepBackResult> {
  const before = store()
  const fail = (reason: string): StepBackResult => {
    publishRunFromReview('step-back', null, reason)
    return { ok: false, reason }
  }
  if (!before.programText) return fail(STEP_BACK_REFUSAL.noProgram)
  if (loadedTextRunsCompensated(before.programText)) {
    return fail('Step Back is disabled while surface mesh compensation is active. Re-arm the compensated program from the top.')
  }
  if (stepBackInProgressValue) return fail(STEP_BACK_REFUSAL.busy)
  const ctrl = getMachineController()
  if (ctrl.connectionPhase() !== 'connected') return fail(STEP_BACK_REFUSAL.disconnected)
  // Operator 2026-09-14 ("A: Flash, all motion off"): Back re-runs a line - motion.
  // After the connection check: every disconnect re-arms the latch, so testing
  // it first would hide "connect to the machine" behind the E-STOP sentence.
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  if (!ctrl.singleBlockMode() || !before.singleBlock) return fail(STEP_BACK_REFUSAL.singleBlock)
  if (ctrl.machineState() !== 'idle' && ctrl.machineState() !== 'hold') {
    return fail(STEP_BACK_REFUSAL.moving)
  }

  const liveBefore = ctrl.jobProgress()
  const initialPlan = buildStepBackPlan(before.programText, liveBefore.ackedSourceLine, runFromLineMachineOptions())
  if (!initialPlan.ok) return fail(initialPlan.reason)

  const controlledStop = ctrl.machineState() === 'hold'
  const sessionRevision = connectionRevision
  const receiptToken = captureBackendReceipt(ctrl)
  setStepBackInProgress(true)
  try {
    const stoppedProgress = controlledStop ? await controlledStopForStepBack(ctrl) : liveBefore
    if (!receiptIsCurrent(receiptToken)) {
      return { ok: false, reason: STEP_BACK_REFUSAL.changed }
    }
    if (connectionRevision !== sessionRevision || ctrl.connectionPhase() !== 'connected') {
      // The connection callback already cleared every review surface. Return
      // the refusal to the caller without publishing a stale card into the
      // disconnected or replacement controller session.
      return { ok: false, reason: STEP_BACK_REFUSAL.changed }
    }
    if (!stoppedProgress) return fail(STEP_BACK_REFUSAL.stop)

    const after = store()
    const liveAfter = controlledStop ? stoppedProgress : ctrl.jobProgress()
    if (
      after.programText !== before.programText ||
      after.job.name !== before.job.name ||
      (!controlledStop && liveAfter.ackedSourceLine !== liveBefore.ackedSourceLine) ||
      !ctrl.singleBlockMode() ||
      !after.singleBlock
    ) {
      return fail(STEP_BACK_REFUSAL.changed)
    }

    // A Hold can acknowledge additional buffered lines during the settle.
    // Re-plan from the controller's final pre-reset cursor rather than from
    // the render store or the cursor observed before the await.
    const options = runFromLineMachineOptions()
    const planned = buildStepBackPlan(after.programText, liveAfter.ackedSourceLine, options)
    if (!planned.ok) return fail(planned.reason)
    // WO-1008: same as run-from-line - a stepped-back run is a slice, not the
    // loaded program.
    refusePathFidelity(RUN_FROM_LINE_NOT_CHECKED)
    const programText = after.programText
    const loaded = loadRunFromSlice(ctrl, programText, planned.plan, options, (o) =>
      buildStepBackPlan(programText, liveAfter.ackedSourceLine, o))
    if (!loaded.ok) {
      restoreFullProgramIfArmed(ctrl, programText)
      return fail(loaded.reason)
    }
    textJobFirstLine = loaded.plan.startLine
    store().applyJobProgress(ctrl.jobProgress())
    forgetKeptStop()
    publishRunFromReview('step-back', loaded.plan, null)
    return { ok: true, plan: loaded.plan, controlledStop }
  } finally {
    setStepBackInProgress(false)
  }
}

// ---- WO-2237: a move out of a pause is a kept stop --------------------------

/**
 * WO-2237: MOVE DURING A PAUSE, THEN RESUME AT THE PAUSE POINT.
 *
 * Operator ruling 2026-09-29, card Q-JOG-MDI-DURING-A-PAUSE-PICK-ONE: "1 - kept stop,
 * return to the pause point". In chat: "I need it to be able to when it's in a
 * pause, be able to accept commands and then resume. It essentially needs to
 * save its place and perform the tasks that I'm asking and then it can resume
 * from where the pause was." And: "An MDI move should not behave different
 * than a jog move or anything else."
 *
 * Our board runs a new move only AFTER the held program's buffered moves
 * (measured 2026-08-24; docs/research/MDI-JOG-DURING-PAUSE.md s3), so the first
 * operator command in a pause - a jog, Safe Z, an MDI line, the spindle, an
 * output, a macro - first stops the held program. The machine is already
 * standing still, so nothing is lost: the program stays loaded, and its place
 * is kept - the interrupted line, the exact point, the program text. Then the
 * command runs. CYCLE START (`startMachineJob`) goes back to the point - the
 * run-from prelude: the program's own state, safe Z, X/Y, down at the capped
 * approach feed - finishes the interrupted move from there and carries on.
 * UCCNC's own pattern (Operator's M6 macro: Stop, move, back to the saved point,
 * Cycle Start); on LinuxCNC it is abort + run-from-line.
 *
 * A pause with no command in it is untouched: nothing here runs until a
 * command arrives, and CYCLE START resumes on the board exactly as before.
 * Nothing restarts or re-arms by itself. Feed Hold, Stop and E-STOP act on the
 * return exactly as on any program - it is one.
 */
interface KeptStop {
  controller: MachineController
  /** The loaded program's name, and the text the machine was running. */
  name: string
  door: KeptStopDoorKind
  /** The text the machine RAN - the surface-mesh compensated stream when a
   *  mesh is armed - which the return is planned on, so a meshed program
   *  comes back to its compensated point and carries on compensated. */
  text: string
  /** The loaded program's own text (its identity on screen). */
  sourceText: string
  /** A line of `text` as the loaded program's own line number. */
  sourceLineOf: (line: number) => number
  /** The line of `text` the pause stopped inside. */
  line: number
  /** Where the tool stood, work millimetres in `wcs`, on that line's path;
   *  null when it was not on it (CYCLE START then starts the line). WO-2243:
   *  with the angle (degrees) of each rotary axis that line turns. */
  pointMm: { x: number; y: number; z: number; a?: number; b?: number; c?: number } | null
  wcs: WcsId | null
  /** Set once CYCLE START has sent the return. Until the resumed run reaches
   *  the interrupted line a new pause keeps this same point. WO-2242:
   *  `startLine` is the line of `text` the return's program part starts on -
   *  the kept line, or the one after a tool change that is done. */
  resumed: {
    preludeLines: number
    startLine: number
    lineOfStep: ((stepId: number) => number | undefined) | null
    /** WO-2580: the controller has named a move past the prelude - the way
     *  back is over, whatever its cursor reads after (an M0 further on names
     *  no move, which read as "still in the prelude"). */
    reached: boolean
  } | null
  /** Keep the paused file's readouts while its return awaits a WCS receipt. */
  returnStaging?: ReturnType<typeof store>['programReadiness']
  /** WO-2239: the tool the operator put in the spindle during the stop (a
   *  typed `T2 M6`, `M61 Q2`, the guided change) - the return cuts with it,
   *  at its length. Null: the tool was not changed here. */
  toolNow: number | null
  /** When `toolNow` was set: a Tools-panel measure after it wins. */
  toolNowAt: number
  /** WO-2519: where the screen says the program stands while it is in this
   *  stop and on the way back to it. */
  shown: KeptStopShown
}
/** WO-2519: the paused program's place as the screen reads it - the loaded
 *  program's line, the listing row (a staged step id, or the text line) and
 *  the file's move count at it. */
interface KeptStopShown {
  line: number
  cursor: number | null
  done: number
  total: number
}
let keptStop: KeptStop | null = null
/** The commands that arrived while a pause was being turned into the stop -
 *  run in order once it is. A jog cancel drops the jogs among them; Stop and
 *  E-STOP drop them all. */
let keptStopTaking: {
  controller: MachineController
  commands: Array<{ run: () => void; jog: boolean; drop?: () => void }>
  /** WO-2519: the first command's name and the place the pause read. */
  what: string
  shown: KeptStopShown | null
} | null = null
/** WO-2519: the last operator command sent in the stop, for the screen -
 *  only until that command has run and the machine is at rest again. */
let keptStopCommand: { controller: MachineController; what: string; at: number; ran: boolean } | null = null
/** A named command that has not set the machine moving by now was refused
 *  (or ran at rest, as a spindle word does) - its name is forgotten. */
const KEPT_STOP_COMMAND_START_MS = 3000
let startingKeptStopResume = false
/** Counts the operator's Stops, Resets and E-STOPs: one during the taking of
 *  a kept stop abandons it. */
let operatorStopsSeen = 0
/** Counts the terminal job edges (stopped, completed, failed) the controller
 *  has reported: the kept stop's re-arm on the text door waits for its stop's. */
let terminalJobEventsSeen = 0
/** How long the text door's re-arm waits for that edge before it goes anyway. */
const KEPT_STOP_END_EVENT_WAIT_MS = 5000
/** How far off the interrupted move's path a reported point may sit and still
 *  be on it: a board decelerates along its path, and reports to 0.001 mm. */
const KEPT_STOP_ON_PATH_MM = 0.25
/** How far back from the controller's cursor to look for the move that was
 *  running - a text streamer's cursor runs ahead of its motion. */
const KEPT_STOP_LOOK_BACK_LINES = 64

/** The kept stop in force for this controller and this loaded program, or null
 *  (and forgotten) once another program, connection or start owns the screen. */
function liveKeptStop(ctrl: MachineController): KeptStop | null {
  const kept = keptStop
  if (kept === null) return null
  const door = keptStopDoor(ctrl)
  if (kept.controller !== ctrl || controller !== ctrl || door === null || door.text !== kept.sourceText || door.name !== kept.name) {
    keptStop = null
    return null
  }
  return kept
}

/** The loaded program the pause belongs to, through whichever door took it. */
type KeptStopDoorKind = 'text' | 'file' | 'toolpath'
interface KeptStopDoor {
  door: KeptStopDoorKind
  text: string
  name: string
  /** The board's step id as a line of `text` (the file and toolpath doors). */
  lineOfStep: ((stepId: number) => number | undefined) | null
}

function keptStopDoor(ctrl: MachineController): KeptStopDoor | null {
  const s = store()
  if (s.programText !== null) return { door: 'text', text: s.programText, name: s.job.name ?? 'program', lineOfStep: null }
  const file = currentFileDoorProgram()
  if (file !== null) {
    if (file.controller !== ctrl) return null
    return { door: 'file', text: file.text, name: file.name, lineOfStep: file.lineOfStep }
  }
  const toolpath = toolpathProgramAsText()
  if (toolpath === null || s.job.name === null) return null
  return { door: 'toolpath', text: toolpath.text, name: s.job.name, lineOfStep: toolpath.lineOfStep }
}

/**
 * WO-2237: THE TOOLPATH DOOR'S PROGRAM, WRITTEN AS THE G-CODE IT IS. A setup
 * loaded through `loadSetupToolpathProgram` reaches the board as staged steps
 * and has no text; its return is planned the same way as a file's, on the
 * same program written one line per step (each setup's work offset at its
 * first step), and sent through the file door. Null for a program with a step
 * that has no plain line here (a tool change, a dwell, a length offset, air,
 * a rotary or non-XY-plane move): its pause keeps its lock.
 */
type ToolpathAsText = { text: string; lineOfStep: (stepId: number) => number | undefined }
let toolpathTextMemo: { listing: StagedProgramView; spindle: string | null; value: ToolpathAsText | null } | null = null
function toolpathProgramAsText(): ToolpathAsText | null {
  const listing = store().stagedProgram
  if (listing === null) return null
  // The program's spindle is the session's intent, not a step of the listing
  // (CYCLE START starts it before the first move): written as the program's
  // own M3/M4 at its top, so the return restores it like any file's spindle.
  const intent = geometryProgramSpindle !== null && geometryProgramSpindle.controller === controller
    ? geometryProgramSpindle
    : null
  const spindle = intent === null ? null : `${intent.direction === 'ccw' ? 'M4' : 'M3'} S${intent.rpm}`
  if (toolpathTextMemo?.listing === listing && toolpathTextMemo.spindle === spindle) return toolpathTextMemo.value
  const value = writeToolpathAsText(listing, spindle)
  toolpathTextMemo = { listing, spindle, value }
  return value
}

function writeToolpathAsText(listing: StagedProgramView, spindle: string | null): ToolpathAsText | null {
  const f = (v: number) => Number(v.toFixed(4))
  const lines: string[] = ['G21 G90 G17']
  if (spindle !== null) lines.push(spindle)
  const lineOf = new Map<number, number>()
  const firstOf = new Map(listing.setups.map((setup) => [setup.firstStepId, setup.wcs]))
  const pos: { x?: number; y?: number; z?: number } = {}
  for (const step of listing.program.steps) {
    const wcs = firstOf.get(step.id)
    if (wcs !== undefined) lines.push(wcs)
    let line: string | null = null
    if (step.kind === 'line') {
      if (step.to.a !== undefined || step.to.b !== undefined || step.to.c !== undefined) return null
      const words: string[] = []
      for (const a of ['x', 'y', 'z'] as const) {
        const v = step.to[a]
        if (v === undefined) continue
        pos[a] = v
        words.push(`${a.toUpperCase()}${f(v)}`)
      }
      if (words.length > 0) line = step.rapid ? `G0 ${words.join(' ')}` : `G1 ${words.join(' ')} F${f(step.feedMmMin)}`
    } else if (step.kind === 'arc') {
      if (step.plane !== 'xy' || pos.x === undefined || pos.y === undefined) return null
      line = `${step.clockwise ? 'G2' : 'G3'} X${f(step.to.x)} Y${f(step.to.y)} Z${f(step.to.z)} `
        + `I${f(step.centre.x - pos.x)} J${f(step.centre.y - pos.y)} F${f(step.feedMmMin)}`
      pos.x = step.to.x
      pos.y = step.to.y
      pos.z = step.to.z
    } else if (step.kind === 'spindle') {
      line = step.direction === 'off' ? 'M5' : `${step.direction === 'cw' ? 'M3' : 'M4'} S${step.rpm}`
    } else if (step.kind === 'coolant') {
      if (step.channel === 'air') return null
      line = !step.on ? 'M9' : step.channel === 'flood' ? 'M8' : 'M7'
    } else if (step.kind === 'workOffset' && step.op === 'select') {
      line = step.wcs
    } else if (step.kind !== 'marker') {
      return null
    }
    if (line !== null) lines.push(line)
    lineOf.set(step.id, Math.max(1, lines.length))
  }
  lines.push('M30')
  return { text: lines.join('\n'), lineOfStep: (stepId) => lineOf.get(stepId) }
}

/** A program standing still in a pause that a command may turn into a kept
 *  stop. Every hold another flow owns (a tool change, a probe routine, a
 *  boundary macro, the clamp card, Step Back, the fit trace) is not one, and
 *  neither is the operator's own MDI line held over the file. */
function pauseAtRestKeepsStop(ctrl: MachineController): boolean {
  if (ctrl !== controller || ctrl.connectionPhase() !== 'connected' || estopNeedsReset()) return false
  if (ctrl.machineState() !== 'hold' || !hasActiveProgramJob(ctrl)) return false
  if (toolChangeHold !== null || pauseHeldByAnotherFlow(ctrl)) return false
  if (programOwnActionInFlight || programBoundaryMacroSending) return false
  if (mdiLineOverLoadedProgram(ctrl) && !keptStopResumeRunning(ctrl)) return false
  return keptStopDoor(ctrl) !== null
}

/** WO-2237: the panels' one question - does the pause standing now take a
 *  jog, Safe Z, MDI, spindle or output command (turning it into a kept stop)?
 *  False in every hold another flow owns and in a pause this session cannot
 *  keep, where the panels stay locked exactly as before this order. */
export function pausedProgramTakesCommands(): boolean {
  const ctrl = controller
  return ctrl !== null && (keptStopTakingFor(ctrl) || pauseAtRestKeepsStop(ctrl))
}

export function subscribePausedProgramTakesCommands(listener: () => void): () => void {
  const offs = [
    useMachineControl.subscribe(listener),
    subscribeToolChangeHold(listener),
    subscribeStepBackInProgress(listener),
    subscribeProbeCycleActive(listener),
  ]
  return () => { for (const off of offs) off() }
}

/** A hold another flow owns and answers for itself: the clamp card or guided
 *  tool change, the fit trace, Step Back, a probe routine, a boundary macro. */
function pauseHeldByAnotherFlow(ctrl: MachineController): boolean {
  return store().toolChange !== null
    || store().fitTrace?.step === 'tracing'
    || stepBackInProgressValue
    || isProbeCycleActive()
    || probeCycleHeldByOperator(ctrl)
    || programBoundaryMacroBlocksCycleStart(ctrl)
    || programClampPauseBlocksCycleStart(ctrl)
    || programGuidedToolChangeBlocksCycleStart(ctrl)
}

/** A pause is being turned into a kept stop on this controller. Every command
 *  that arrives meanwhile joins the queue, in order - the stop may already
 *  read Idle before the kept place is written. */
function keptStopTakingFor(ctrl: MachineController): boolean {
  return keptStopTaking !== null && keptStopTaking.controller === ctrl
}

/** WO-2237: a program paused at rest that this session cannot keep - the
 *  operator's own MDI line held (alone or over the loaded file), or a toolpath
 *  program with a step no plain G-code line here writes (a rotary or a
 *  non-XY-plane move). Its pause keeps the lock it always had: our board runs
 *  a move sent now only AFTER the held line's buffered moves (research s3), so
 *  a jog would wait and run when the line resumes. The tool-change hold still
 *  lends jog (WO-1330). A hold another flow owns, and an E-STOP, go on exactly
 *  as before this order - that flow answers for its own hold. */
function pausedProgramKeepsItsLock(ctrl: MachineController): boolean {
  if (ctrl !== controller || ctrl.connectionPhase() !== 'connected' || estopNeedsReset()) return false
  if (ctrl.machineState() !== 'hold' || !hasActiveProgramJob(ctrl)) return false
  if (toolChangeHold !== null || keptStopTakingFor(ctrl) || pauseHeldByAnotherFlow(ctrl)) return false
  // The program's own words (its spindle as CYCLE START releases a pause, a
  // boundary macro's lines) are the program, not an operator command.
  if (programOwnActionInFlight || programBoundaryMacroSending) return false
  return !pauseAtRestKeepsStop(ctrl)
}
const PAUSED_PROGRAM_JOG_LOCK = 'A program is running - jogging is locked out.'

/** The run on the board is the return this session sent from a kept stop. */
function keptStopResumeRunning(ctrl: MachineController): boolean {
  const kept = keptStop
  return kept !== null && kept.controller === ctrl && kept.resumed !== null
}

/**
 * The one door every operator command takes while a program may be paused:
 * true when the command was taken - to run once the pause is a kept stop -
 * and false when there is no pause to keep (the caller carries on as before).
 */
function commandThroughKeptStop(
  ctrl: MachineController,
  what: string,
  run: () => void,
  jog = false,
  drop?: () => void,
): boolean {
  // The program's own words are never an operator command (see above).
  if (programOwnActionInFlight || programBoundaryMacroSending) return false
  // WO-2519: every operator command asks here first - in a kept stop the
  // screen names the one running.
  nameKeptStopCommand(ctrl, what)
  const taking = keptStopTaking
  if (taking !== null && taking.controller === ctrl) {
    taking.commands.push({ run, jog, drop })
    return true
  }
  if (!pauseAtRestKeepsStop(ctrl)) return false
  const door = keptStopDoor(ctrl)
  const entry = {
    controller: ctrl,
    commands: [{ run, jog, drop }],
    what,
    shown: door === null ? null : keptStopShownAtPause(ctrl, door),
  }
  keptStopTaking = entry
  void takeKeptStop(ctrl, entry.shown).then((kept) => {
    if (keptStopTaking === entry) keptStopTaking = null
    if (!kept) {
      for (const command of entry.commands) command.drop?.()
      if (entry.commands.length > 0) {
        store().pushConsole(
          'tx',
          `${what}: the paused program did not come to a clean stop, so nothing was sent - check the machine.`,
          'error',
        )
      }
      return
    }
    keptStopCommand = { controller: ctrl, what, at: Date.now(), ran: false }
    for (const command of entry.commands) command.run()
  })
  return true
}

/**
 * WO-2519: THE SCREEN READS THE PAUSED PROGRAM, NOT THE STOP UNDER IT.
 *
 * A kept stop stops the held program and arms it again, an MDI line runs as
 * a program of its own, and the return is staged as its own program from a
 * prelude - so in the stop the job, cursor and listing read as a fresh
 * program ("Program checks passed. CYCLE START begins the program.", 0/20, no
 * row), an MDI line as 0/1 or a failed cycle, and the way back counted its
 * prelude moves (machine session 2026-10-03, F4-F6). The place the pause read
 * is kept with the stop, and these readouts show it - with what is happening
 * now - until the return reaches the line again. Nothing sent changes.
 */
export interface PausedProgramReadout {
  /** The loaded program's line the program is paused in. */
  line: number
  /** The listing row: a staged step id, or the text line. */
  cursor: number | null
  done: number
  total: number
  doing: 'paused' | 'command' | 'returning'
  /** The header's words: "paused at line 15", "returning to line 15". */
  state: string
  /** The line under the transport: what is happening and what comes next. */
  sentence: string
}

/** The place the pause reads now - before the stop zeroes the controller's
 *  cursors. On the way back the place kept is still the first one. */
function keptStopShownAtPause(ctrl: MachineController, door: KeptStopDoor): KeptStopShown | null {
  const kept = keptStop
  if (kept !== null && kept.controller === ctrl && kept.resumed !== null && keptStopReturnInPrelude(ctrl, kept)) return kept.shown
  const s = store()
  if (door.door === 'text') {
    if (s.job.ackedSourceLine <= 0) return null
    return { line: s.job.ackedSourceLine, cursor: s.job.ackedSourceLine, done: s.job.ackedLines, total: s.job.totalLines }
  }
  const cursor = s.executingMoveId ?? (s.job.ackedSourceLine > 0 ? s.job.ackedSourceLine : null)
  const line = cursor === null ? undefined : door.lineOfStep?.(cursor)
  if (cursor === null || line === undefined) return null
  return { line, cursor, done: s.job.ackedLines, total: s.job.totalLines }
}

/** The place a kept stop shows: the line it keeps, as the listing's row and
 *  the file's moves before it. The pause's own reading fills what the
 *  listing cannot say. */
function keptStopShownAt(door: KeptStopDoor, line: number, atPause: KeptStopShown | null): KeptStopShown {
  const s = store()
  if (door.door === 'text') {
    return { line, cursor: line, done: atPause?.done ?? s.job.ackedLines, total: atPause?.total ?? s.job.totalLines }
  }
  const moves = s.stagedProgram?.program.steps.filter(isStagedMove) ?? []
  const onLine = door.lineOfStep === null ? [] : moves.filter((step) => door.lineOfStep!(step.id) === line)
  const step = onLine.find((candidate) => candidate.id === atPause?.cursor) ?? onLine[0]
  if (step === undefined) {
    return { line, cursor: atPause?.cursor ?? null, done: atPause?.done ?? 0, total: atPause?.total ?? moves.length }
  }
  return { line, cursor: step.id, done: moves.indexOf(step), total: moves.length }
}

/** On the way back from a kept stop and not yet on the kept line: the
 *  return's prelude (its own state, safe Z, X/Y, down to the point). */
function keptStopReturnInPrelude(ctrl: MachineController, kept: KeptStop): boolean {
  const resumed = kept.resumed
  if (resumed === null || resumed.reached) return false
  if (resumed.lineOfStep === null) {
    // The text door streams the return's lines from the kept line: its
    // cursor names the prelude as 0.
    const cursor = ctrl.jobProgress().ackedSourceLine
    return cursor <= 0 || cursor < resumed.startLine
  }
  if (pathFidelityArmed && geometryStepMotionSeen.get(pathFidelityArmed) !== true) return true
  const s = store()
  const id = (s.stagedNumbering === null ? s.executingMoveId : s.stagedExecutingMoveId) ?? stagedJobCounts().ackedSourceLine
  if (id <= 0) return true
  const line = resumed.lineOfStep(id)
  return line !== undefined && line <= resumed.preludeLines
}

/** WO-2580: every status frame on the way back asks whether the controller
 *  has named a move of the program part (past the prelude). Once it has, the
 *  way back is over for good: a later M0 or tool change that names no move
 *  is the program's own stop, not the return (machine seat 10-04, UCCNC: at
 *  the M0 on line 20 the header read "returning to line 15", row 15 lit). */
function settleKeptStopReturn(ctrl: MachineController): void {
  const kept = keptStop
  const resumed = kept?.resumed
  if (!kept || kept.controller !== ctrl || !resumed || resumed.reached) return
  if (resumed.lineOfStep === null) {
    const cursor = ctrl.jobProgress().ackedSourceLine
    resumed.reached = cursor > 0 && cursor >= resumed.startLine
    return
  }
  const s = store()
  const id = s.stagedNumbering === null ? s.executingMoveId : s.stagedExecutingMoveId
  const line = id === null || id <= 0 ? undefined : resumed.lineOfStep(id)
  resumed.reached = line !== undefined && line > resumed.preludeLines
}

/** WO-2519 fix round: a kept stop's command takes the screen's name only
 *  when nothing runs in the stop - one asked while another runs is refused by
 *  the controller (or joins it), and the one running keeps its name. */
function nameKeptStopCommand(ctrl: MachineController, what: string): void {
  if (keptStop?.controller !== ctrl || keptStop.resumed !== null) return
  if (keptStopBusy(ctrl)) return
  keptStopCommand = { controller: ctrl, what, at: Date.now(), ran: false }
}

/** Something runs in the stop: a job (an MDI line, the return) or motion. */
function keptStopBusy(ctrl: MachineController): boolean {
  return ctrl.hasActiveJob() || !['idle', 'alarm', 'door'].includes(ctrl.machineState())
}

/** WO-2519 audit round 2: a command's name lasts as long as its run. Every
 *  status frame asks: once the named command has run and the machine is at
 *  rest again - or it never started - the name is forgotten, so the next
 *  command, whichever door sent it, is never read as the one before it (a
 *  finished jog named a configured action's two-line program "Jog running"). */
function settleKeptStopCommand(ctrl: MachineController): void {
  const named = keptStopCommand
  if (named === null || named.controller !== ctrl) return
  if (keptStopBusy(ctrl)) named.ran = true
  else if (named.ran || Date.now() - named.at > KEPT_STOP_COMMAND_START_MS) keptStopCommand = null
}

/** What an operator command in the stop is called on screen. */
function keptStopCommandWords(what: string | null, ctrl: MachineController): string {
  if (ctrl.machineState() === 'jog' || (what !== null && what.startsWith('Jog'))) return 'Jog'
  if (what === 'MDI' || mdiLineOverLoadedProgram(ctrl)) return 'MDI line'
  return what ?? 'Move'
}

let pausedReadoutMemo: PausedProgramReadout | null = null
/** WO-2519: the paused program's readouts while a pause is turned into a kept
 *  stop, while it stands and while CYCLE START goes back to it; null at every
 *  other time (the job's own readouts are true then). Same object while
 *  nothing in it changed, so a render can subscribe to it. */
export function pausedProgramReadout(): PausedProgramReadout | null {
  const next = pausedProgramReadoutNow()
  const same = next !== null && pausedReadoutMemo !== null
    && (Object.keys(next) as Array<keyof PausedProgramReadout>).every((key) => next[key] === pausedReadoutMemo![key])
  if (!same) pausedReadoutMemo = next
  return pausedReadoutMemo
}

function pausedProgramReadoutNow(): PausedProgramReadout | null {
  const ctrl = controller
  if (ctrl === null) return null
  const taking = keptStopTaking
  const kept = keptStop
  const busy = keptStopBusy(ctrl)
  if (taking !== null && taking.controller === ctrl) {
    if (taking.shown === null) return null
    const doing = `${keptStopCommandWords(taking.what, ctrl)} running`
    return {
      ...taking.shown,
      doing: 'command',
      state: `paused at line ${taking.shown.line} - ${doing}`,
      sentence: `${doing} - program paused at line ${taking.shown.line}.`,
    }
  }
  if (kept === null || kept.controller !== ctrl || store().job.name !== kept.name) return null
  const { shown } = kept
  if (kept.returnStaging && store().programReadiness !== kept.returnStaging && !store().programReadiness.ready) kept.returnStaging = undefined
  if (kept.resumed !== null || kept.returnStaging) {
    if (!kept.returnStaging && !keptStopReturnInPrelude(ctrl, kept)) return null
    return {
      ...shown,
      doing: 'returning',
      state: `returning to line ${shown.line}`,
      sentence: `Returning to line ${shown.line}, where the program paused - Feed Hold pauses motion; Stop/Reset abandons the cycle.`,
    }
  }
  if (busy) {
    const command = keptStopCommand !== null && keptStopCommand.controller === ctrl ? keptStopCommand.what : null
    const doing = `${keptStopCommandWords(command, ctrl)} running`
    return {
      ...shown,
      doing: 'command',
      state: `paused at line ${shown.line} - ${doing}`,
      sentence: `${doing} - program paused at line ${shown.line}.`,
    }
  }
  return {
    ...shown,
    doing: 'paused',
    state: `paused at line ${shown.line}`,
    sentence: `Program paused at line ${shown.line}. ${keptStopCycleStartSentence(kept)}`,
  }
}

/** Stop, Reset or E-STOP while a pause is being turned into a kept stop: the
 *  commands that were waiting for it never run. The session's own stop (the
 *  kept stop itself) is not one of these. */
function dropCommandsWaitingForKeptStop(ctrl: MachineController, jogsOnly = false): void {
  const taking = keptStopTaking
  if (taking === null || taking.controller !== ctrl) return
  const dropped = taking.commands.filter((command) => !jogsOnly || command.jog)
  taking.commands = taking.commands.filter((command) => !dropped.includes(command))
  for (const command of dropped) command.drop?.()
}

/** The lines the controller's cursor says could be running, most likely first. */
function keptStopCandidateLines(
  ctrl: MachineController,
  door: KeptStopDoorKind,
  text: string,
  doorLineOfStep: ((stepId: number) => number | undefined) | null,
): number[] | 'prelude' {
  const raw = text.split(/\r?\n/)
  const out: number[] = []
  const push = (line: number | undefined) => {
    if (line === undefined || !Number.isInteger(line) || line < 1 || line > raw.length) return
    if (!isSendableGcodeLine(raw[line - 1]) || out.includes(line)) return
    out.push(line)
  }
  const nextAfter = (line: number): number | undefined => {
    for (let n = line + 1; n <= raw.length; n++) if (isSendableGcodeLine(raw[n - 1])) return n
    return undefined
  }
  const kept = keptStop
  const resumed = kept !== null && kept.controller === ctrl && kept.resumed !== null ? kept : null
  let cursor: number
  let ahead: number
  if (door !== 'text') {
    // The board names the move it is executing (UCCNC) or the one it finished
    // (the simulator): both, and the one after.
    const progress = ctrl.programProgress?.()
    const ids = [progress?.executingId ?? null, ctrl.jobProgress().ackedSourceLine]
      .filter((id): id is number => id !== null && id > 0)
    const lineOf = resumed?.resumed?.lineOfStep ?? doorLineOfStep
    if (lineOf === null) return out
    const toProgramLine = (textLine: number | undefined): number | undefined => {
      if (textLine === undefined || resumed === null) return textLine
      // The return's text is its prelude, then the program from the line.
      const preludeLines = resumed.resumed!.preludeLines
      return textLine <= preludeLines ? 0 : textLine - preludeLines + resumed.resumed!.startLine - 1
    }
    const lines = ids.flatMap((id) => [toProgramLine(lineOf(id)), toProgramLine(lineOf(id + 1))])
    if (resumed !== null && lines.every((line) => line === undefined || line <= 0 || line < resumed.resumed!.startLine)) return 'prelude'
    for (const line of lines) push(line)
    cursor = out[0] ?? 0
    ahead = cursor
  } else {
    const progress = ctrl.jobProgress()
    cursor = progress.ackedSourceLine
    ahead = Math.max(progress.sentSourceLine, cursor)
    // A run-from start reports its prelude as line 0.
    if (resumed !== null && (cursor <= 0 || cursor < resumed.resumed!.startLine)) return 'prelude'
    push(cursor)
  }
  // The lines after the cursor up to the last one sent, and one more (a
  // cursor that names the last FINISHED line) ...
  for (let n = nextAfter(cursor); n !== undefined; n = nextAfter(n)) {
    push(n)
    if (n > ahead) break
  }
  // ... and back, for a cursor that runs ahead of the motion.
  let back = 0
  for (let n = cursor - 1; n >= 1 && back < KEPT_STOP_LOOK_BACK_LINES; n--) {
    if (!isSendableGcodeLine(raw[n - 1])) continue
    push(n)
    back++
  }
  return out
}

/** The text a loaded program runs as: under an applied surface mesh whose work
 *  system its moves run in, the compensated stream both doors stage
 *  (`loadMachineProgram`, `meshCompensatedFileText`) - compiled for the work
 *  system the program was staged to start in (WO-2283) - and the map from the
 *  program's own lines to that stream's. */
function keptStopRunText(sourceText: string): {
  text: string
  toRun: ((sourceLine: number) => number[]) | null
  sourceLineOf: (line: number) => number
} {
  const plain = { text: sourceText, toRun: null, sourceLineOf: (line: number) => line }
  if (meshWorkOffsetMove(store().surfaceMesh) !== null) return plain
  const compiled = compileUnderAppliedMesh(sourceText, meshStagedStartWcs)
  if (!compiled?.ok) return plain
  const bySource = new Map<number, number[]>()
  compiled.lines.forEach((line, index) => {
    const lines = bySource.get(line.sourceLine) ?? []
    lines.push(index + 1)
    bySource.set(line.sourceLine, lines)
  })
  return {
    text: compiled.lines.map((line) => line.text).join('\n'),
    toRun: (sourceLine) => bySource.get(sourceLine) ?? [],
    sourceLineOf: (line) => compiled.lines[line - 1]?.sourceLine ?? line,
  }
}

/** Turn the pause into a kept stop: stop the held program (the machine is
 *  already still), then keep the line, the point and the program. */
async function takeKeptStop(ctrl: MachineController, atPause: KeptStopShown | null): Promise<boolean> {
  const door = keptStopDoor(ctrl)
  if (door === null) return false
  const previous = keptStop !== null && keptStop.controller === ctrl && keptStop.sourceText === door.text ? keptStop : null
  // A return under way runs the kept stream itself, numbered as that stream;
  // a program's own run reports the program's lines.
  const resumedRun = previous !== null && previous.resumed !== null ? previous : null
  const run = resumedRun !== null
    ? { text: resumedRun.text, toRun: null, sourceLineOf: resumedRun.sourceLineOf }
    : keptStopRunText(door.text)
  // Read before the stop: a controller zeroes its cursors when it stops.
  const cursorLines = keptStopCandidateLines(ctrl, door.door, resumedRun !== null ? run.text : door.text, door.lineOfStep)
  const candidates = cursorLines === 'prelude' || run.toRun === null
    ? cursorLines
    : [...new Set(cursorLines.flatMap(run.toRun))]
  const receiptToken = captureBackendReceipt(ctrl)
  const revision = connectionRevision
  // The toolpath door's parts run ends with "no later part was loaded"; the
  // program is still the loaded one, so its readiness is what it was.
  const readinessBefore = store().programReadiness
  const operatorStopsBefore = operatorStopsSeen
  const stillCurrent = () => receiptIsCurrent(receiptToken) && connectionRevision === revision && controller === ctrl
    && operatorStopsSeen === operatorStopsBefore
  const settledIdle = () => !ctrl.hasActiveJob() && !ctrl.resetInProgress() && ctrl.machineState() === 'idle'
  let stopped: boolean
  if (door.door === 'text') {
    // LinuxCNC clears its job at once on the stop, but its gateway refuses a
    // load until the stopped program is reported finished ("The last program
    // has not been reported finished yet") - the re-arm then lost the program
    // (rehearsal 2026-09-30, r2/r5). The re-arm waits for that stopped edge,
    // then goes anyway after KEPT_STOP_END_EVENT_WAIT_MS.
    const endsBefore = terminalJobEventsSeen
    const endOwed = ctrl.hasActiveJob()
    stopped = (await controlledStopForStepBack(ctrl)) !== null
    if (stopped && endOwed) {
      await waitForMachine(() => terminalJobEventsSeen !== endsBefore || !stillCurrent(), KEPT_STOP_END_EVENT_WAIT_MS)
    }
  } else {
    stopJobForSession(ctrl)
    if (ctrl.capabilities.gcodeText === true) {
      stopped = await waitForMachine(settledIdle, 8000)
    } else {
      // A board that runs staged moves (the AXBB-E bridge) keeps its feed hold
      // through the stop: StopJob empties the queue with StopWithDeccel and
      // never releases it (Machine.cs StopJob). SimUC100 then stays held; the
      // real board reads Idle while it drops every move it is given (measured
      // 2026-08-24 after a socket-loss hold) - so "Idle" proves nothing and
      // the hold is ALWAYS released, with the bridge's own Stop/Reset
      // sequence: Stop() empties the queue, then SetFeedHold(false), so
      // nothing can resume (WO-2103). Rehearsal 2026-09-30 F1.
      stopped = await waitForMachine(() => !ctrl.hasActiveJob() && !ctrl.resetInProgress(), 8000)
        && stillCurrent()
        && !estopNeedsReset()
        && (await ctrl.resetToIdle()).ok
        && await waitForMachine(settledIdle, 8000)
    }
  }
  if (!stillCurrent()) return false
  if (!stopped) return false
  const wcs = store().activeWcs
  let line: number
  let pointMm: KeptStop['pointMm']
  if (candidates === 'prelude' && previous !== null) {
    // Paused again on the way back: the place kept is still the first one.
    line = previous.line
    pointMm = previous.pointMm
  } else {
    const at = ctrl.status().workPos
    const lines = candidates === 'prelude' ? [] : candidates
    // WO-2243: the rotary axes the controller reports place a move that turns.
    const turned = at ? Object.fromEntries((['a', 'b', 'c'] as const).filter((k) => Number.isFinite(at[k])).map((k) => [k, at[k]!])) : {}
    const found = at ? locatePausedLine(run.text, lines, { x: at.x, y: at.y, z: at.z, ...turned }, KEPT_STOP_ON_PATH_MM) : null
    if (found === null && lines.length === 0) {
      store().pushConsole('rx', 'The program is stopped, but the controller did not say which line it was on, so CYCLE START runs it from the start.', 'warn')
      keptStop = null
      await waitForMachine(rearmKeptStopProgram(ctrl, door, readinessBefore), 8000)
      return stillCurrent()
    }
    line = found?.line ?? lines[0]
    // WO-2242: a controller whose own M6 moves (LinuxCNC's tool-change
    // position) stops off every path; a stop in that change keeps the place
    // the program reached it.
    pointMm = found !== null ? found.pointMm : toolChangeStartOf(run.text, line)
    // WO-2437 fix round 4: held on the program's own stop (an operator stop's
    // M0 at its park), the place kept is where the machine stands at it.
    if (pointMm === null && at && programStopAt(run.text, line)) pointMm = { x: at.x, y: at.y, z: at.z }
    // LinuxCNC names the last motion line (the park's G53) while it holds on
    // the M0 after it: the machine at that line's end, the stop is the line.
    const following = pointMm === null && at ? programStopFollowing(run.text, line) : null
    if (following !== null && following.endOf !== null && at) {
      const frame = following.endOf.frame === 'machine' ? ctrl.status().machinePos : at
      const atEnd = frame !== null && (['x', 'y', 'z'] as const).every((axis) => {
        const target = following.endOf!.at[axis]
        return target === undefined || Math.abs(frame[axis] - target) <= SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM
      })
      if (atEnd) {
        line = following.stopLine
        pointMm = { x: at.x, y: at.y, z: at.z }
      }
    }
  }
  // WO-2521: the T words the program ran up to and including the kept line
  // select - that line was executing at the hold, so its T was already given
  // (it runs again on the return). Paused again in the prelude: none ran.
  if (candidates !== 'prelude' || previous === null) {
    const from = resumedRun?.resumed ? run.sourceLineOf(resumedRun.resumed.startLine) : 1
    selectProgramToolWord(ctrl, door.text, from, run.sourceLineOf(line))
  }
  // Read before the re-arm, against the listing the pause was read on.
  const shown = keptStopShownAt(door, run.sourceLineOf(line), atPause)
  const rearmed = rearmKeptStopProgram(ctrl, door, readinessBefore)
  keptStop = {
    controller: ctrl,
    name: door.name,
    door: door.door,
    text: run.text,
    sourceText: door.text,
    sourceLineOf: run.sourceLineOf,
    line,
    pointMm,
    wcs,
    resumed: null,
    ...toolCarriedToKeptStop(previous, run.text, line),
    shown,
  }
  store().pushConsole(
    'rx',
    `Stopped at line ${run.sourceLineOf(line)} so you can move; ${keptStopCycleStartSentence(keptStop)}`,
    'info',
  )
  // The waiting commands run once the program is back on the board. A bridge
  // stages it only after its frame receipt, and an MDI line loaded first
  // replaced that staging: CYCLE START then waited for a G54 confirmation
  // that never came (rehearsal 2026-09-30 F2).
  await waitForMachine(rearmed, 8000)
  return stillCurrent()
}

/** What CYCLE START does from a kept stop, in the operator's words. */
function keptStopCycleStartSentence(kept: KeptStop): string {
  const shown = kept.sourceLineOf(kept.line)
  const point = kept.pointMm
  const where = point === null
    ? `the start of line ${shown} (the tool was not on that line's path)`
    : keptStopPointText(kept, point)
  return `CYCLE START goes back to ${where} and carries on from line ${shown}.`
}

/** WO-1667: the kept point through the one position formatter - work
 *  millimetres in the frame the controller reported it in ("G54 X 38.4696 Y 0
 *  Z -2"); the return reaches it at the approach feed, a work-coordinate move. */
function keptStopPointText(kept: KeptStop, pointMm: NonNullable<KeptStop['pointMm']>): string {
  // WO-2243: and the angle of each rotary axis the line turns.
  const turned = (['a', 'b', 'c'] as const).filter((k) => pointMm[k] !== undefined)
    .map((k) => ` ${k.toUpperCase()} ${positionNumber(pointMm[k]!)}`).join('')
  return formatPosition({ wcs: kept.wcs ?? 'work', work: pointMm, withMachine: false }) + turned
}

/** After the stop the loaded program is armed again from its top so CYCLE
 *  START is offered; the start itself is the kept stop's (`startMachineJob`).
 *  The file door's board already holds the stopped file. Answers whether the
 *  program is on the board again - a bridge stages it only once its frame
 *  receipt arrives - or its load has answered otherwise. */
function rearmKeptStopProgram(
  ctrl: MachineController,
  door: KeptStopDoor,
  readinessBefore: ReturnType<typeof store>['programReadiness'],
): () => boolean {
  if (door.door === 'text') {
    loadMachineProgram(door.name, door.text)
    return () => true
  }
  let staged = false
  const loadLine = () => {
    staged = true
    return null
  }
  let loaded: { ok: boolean }
  // The toolpath door has no record to stage again: the same program, written
  // as its G-code, goes on the board through the file door under the loaded
  // name and listing - from here on it is that file (an MDI line keeps it,
  // WO-2234), and CYCLE START from the kept stop never runs it from its top.
  // Keeping the loaded program keeps its readiness too, which the stop of its
  // parts run replaced ("no later part was loaded"): the program is loaded and
  // CYCLE START is offered, as the kept stop's line says.
  if (door.door === 'toolpath') {
    rearmingAfterOperatorStop = true
    try {
      loaded = loadGcodeTextToolpathProgram(door.name, door.text, {
        publishListing: true,
        keepsLoadedProgram: true,
        loadLine,
      })
      if (loaded.ok && readinessBefore.ready) store().setProgramReadiness(readinessBefore)
    } finally {
      rearmingAfterOperatorStop = false
    }
  } else {
    // The file door stages the same file again, as the operator's Stop does
    // (WO-1663) - silently: the kept stop's own line says what CYCLE START does.
    const reload = currentFileDoorProgram()
    if (reload === null || reload.controller !== ctrl) return () => true
    rearmingAfterOperatorStop = true
    try {
      loaded = loadGcodeTextToolpathProgram(reload.name, reload.text, {
        publishListing: reload.publishListing,
        context: reload.context,
        runThroughOffsetChanges: reload.runThroughOffsetChanges,
        loadLine,
      })
    } finally {
      rearmingAfterOperatorStop = false
    }
  }
  // A load refused after its receipt writes its own readiness.
  const readiness = store().programReadiness
  return () => staged || !loaded.ok || store().programReadiness !== readiness
}

/** CYCLE START from a kept stop: back to the point, the rest of the move, and
 *  on through the program. */
function startFromKeptStop(ctrl: MachineController, kept: KeptStop, start: () => boolean = startMachineJob): boolean {
  // WO-2239: a guided change typed in the stop is still fitting or measuring
  // the tool - its card's Continue finishes it (main's sentence for the M6).
  if (keptStopGuidedChangeOpen(ctrl)) {
    store().pushConsole(
      'tx',
      'Cycle Start: the M6 tool change is waiting for the cutter to be fitted and Continue to run the fixed-pad probe.',
      'error',
    )
    return false
  }
  if (ctrl.hasActiveJob() || ctrl.machineState() !== 'idle') {
    store().pushConsole(
      'tx',
      'Cycle Start: the machine is still moving - press CYCLE START again once it reads Idle. Nothing moved.',
      'error',
    )
    return false
  }
  const wcsNumber = kept.wcs === null ? null : Number(kept.wcs.slice(1))
  // WO-2239: the tool changed during the stop; LinuxCNC's own tool is
  // otherwise unknown here (the store's active tool stays null there). Tool 0
  // is an empty spindle, which has no length to name: the program's stands.
  const toolNow = keptStopToolNow(kept)
  const machineOptions = runFromLineMachineOptions()
  const options: RunFromLineOptions = {
    ...machineOptions,
    // WO-2437 fix round 4: X/Y never travel below the point kept - a program
    // stop's park can stand above the machine's safe Z (operator example: Z128 over 120).
    safeZMachine: liftNotBelowKeptPoint(ctrl, kept, machineOptions.safeZMachine),
    frameAtPause: wcsNumber,
    toolNow: toolNow !== null && toolNow > 0 ? toolNow : null,
  }
  const planAt = (o: RunFromLineOptions): RunFromLineResult => {
    if (kept.pointMm !== null) {
      const at = buildResumeAtPointPlan(kept.text, kept.line, kept.pointMm, o)
      if (at.ok) return at
    }
    return buildRunFromLinePlan(kept.text, kept.line, o)
  }
  const planned = planAt(options)
  if (!planned.ok) {
    if (planned.atProgramStart) {
      // Line N is the program's first line and not one plain move: the
      // program is armed from its top, which is the same start.
      keptStop = null
      store().pushConsole('rx', `Line ${kept.sourceLineOf(kept.line)} is the start of the program, so CYCLE START runs it from the start.`, 'info')
      return start()
    }
    store().pushConsole('tx', `Cycle Start: the stop at line ${kept.sourceLineOf(kept.line)} cannot be resumed - ${planned.reason} Nothing moved.`, 'error')
    return false
  }
  if (kept.pointMm !== null && planned.plan.resumeAt === undefined) {
    store().pushConsole('rx', `Line ${kept.sourceLineOf(kept.line)} is not one plain move, so CYCLE START runs it again from its start.`, 'warn')
  }
  return kept.door === 'text'
    ? startKeptStopOnTextDoor(ctrl, kept, planned.plan, options, planAt, start)
    : startKeptStopOnFileDoor(kept, planned.plan, start)
}

/** WO-2437 fix round 4: the return's machine lift - the safe Z, or the kept
 *  point's own machine Z when that stands higher (the controller's own offset
 *  now: machine less work). No safe Z stays none. */
function liftNotBelowKeptPoint(
  ctrl: MachineController,
  kept: KeptStop,
  safeZMachine: number | null | undefined,
): number | null {
  if (typeof safeZMachine !== 'number' || !Number.isFinite(safeZMachine)) return null
  const status = ctrl.status()
  const point = kept.pointMm
  if (point === null || !status.machinePos || !status.workPos) return safeZMachine
  const pointMachineZ = point.z + (status.machinePos.z - status.workPos.z)
  return Number.isFinite(pointMachineZ) ? Math.max(safeZMachine, Number(pointMachineZ.toFixed(4))) : safeZMachine
}

function startKeptStopOnTextDoor(
  ctrl: MachineController,
  kept: KeptStop,
  plan: RunFromLinePlan,
  options: RunFromLineOptions,
  replan: (o: RunFromLineOptions) => RunFromLineResult,
  start: () => boolean,
): boolean {
  refusePathFidelity(RUN_FROM_LINE_NOT_CHECKED)
  kept.returnStaging = store().programReadiness
  const loaded = loadRunFromSlice(ctrl, kept.text, plan, options, replan)
  if (!loaded.ok) {
    kept.returnStaging = undefined
    restoreFullProgramIfArmed(ctrl, kept.text)
    store().pushConsole('tx', `Cycle Start: ${loaded.reason} Nothing moved.`, 'error')
    return false
  }
  textJobFirstLine = loaded.plan.startLine
  store().applyJobProgress(ctrl.jobProgress())
  sayKeptStopReturn(kept, loaded.plan)
  let started: boolean
  startingKeptStopResume = true
  try {
    started = start()
  } finally {
    startingKeptStopResume = false
  }
  if (started) kept.resumed = { preludeLines: loaded.plan.prelude.length, startLine: loaded.plan.startLine, lineOfStep: null, reached: false }
  kept.returnStaging = undefined
  return started
}

function startKeptStopOnFileDoor(kept: KeptStop, fromPlan: RunFromLinePlan, start: () => boolean): boolean {
  // WO-2400: the return is read as the rest of the file, so it opens with the
  // tools the run had at the pause - else a later `T1 M6` reads as the file's
  // first tool and the change it asks for never holds.
  const plan = { ...fromPlan, prelude: [...keptStopToolWords(kept, fromPlan.startLine), ...fromPlan.prelude] }
  const text = applyResumeMotion(kept.text, plan).split(/\r?\n/)
  const resumeText = [...plan.prelude, ...text.slice(plan.startLine - 1)].join('\n')
  // The return is staged as a run of the file - its sections, boundaries and
  // holds are the file's - while the screen keeps the file's name, listing
  // and readiness, and the door's record goes back to the FILE once it runs:
  // the operator's Stop after this stages the file from its first line, as
  // after any run of it (WO-1663).
  const file = currentFileDoorProgram()
  const readinessBefore = store().programReadiness
  let lineOfStep: ((stepId: number) => number | undefined) | null = null
  kept.returnStaging = store().programReadiness
  const outcome = loadGcodeTextToolpathProgram(kept.name, resumeText, {
    keepsLoadedProgram: true,
    fileReread: true,
    runThroughOffsetChanges: file?.runThroughOffsetChanges === true,
    fileNumbering: returnFileNumbering(kept, plan),
    lineOfStep: (map) => { lineOfStep = map },
    loadLine: (_program, started) => (started ? keptStopReturnSentence(kept, plan) : null),
    onStaged: () => {
      let started: boolean
      startingKeptStopResume = true
      try {
        // Started against the return's own record: its position is now, so
        // the start never re-reads the file from its top (WO-1791).
        started = start()
      } finally {
        startingKeptStopResume = false
      }
      // The file's own record (null for the toolpath door, which has none).
      toolpathProgramReload = file
      if (started) kept.resumed = { preludeLines: plan.prelude.length, startLine: plan.startLine, lineOfStep, reached: false }
      kept.returnStaging = undefined
      return started
    },
  })
  if (!outcome.ok) {
    kept.returnStaging = undefined
    store().setProgramReadiness(readinessBefore)
    toolpathProgramReload = file
  }
  return outcome.ok
}

/** WO-2400: the T words a file-door return opens with - the tool in the
 *  spindle (one changed in the stop, else the program's at `startLine`), then
 *  the program's own preselect when it differs - read as the file reads them:
 *  the first T is the tool the moves run on, the last is what a bare M6 fits. */
function keptStopToolWords(kept: KeptStop, startLine: number): string[] {
  const program = toolWordsBefore(kept.text, startLine)
  const fitted = kept.toolNow !== null ? keptStopToolNow(kept) : program.inSpindle
  return fileReturnToolWords(program, fitted)
}

function fileReturnToolWords(program: ReturnType<typeof toolWordsBefore>, fitted: number | null): string[] {
  const words: string[] = []
  if (fitted !== null && Number.isInteger(fitted) && fitted >= 0) words.push(`T${fitted}`)
  if (program.selected !== null && program.selected !== fitted) words.push(`T${program.selected}`)
  return words
}

/** WO-2256: a kept stop's return - its prelude, then the file from
 *  `plan.startLine` - read as the file it is the rest of. The file's listing
 *  (the staged steps on screen) and the door's step -> line map say which of
 *  the file's steps each staged step is: one file line's steps are matched
 *  from that line's end, so a move finished from the pause point is the move
 *  it finishes; the prelude reads as the step it goes back to. */
function returnFileNumbering(kept: Pick<KeptStop, 'controller' | 'sourceLineOf'>, plan: RunFromLinePlan): FileNumbering {
  const preludeLines = plan.prelude.length
  const lineOf = (line: number): number | null => (
    line <= preludeLines ? null : kept.sourceLineOf(line - preludeLines + plan.startLine - 1)
  )
  const startLine = kept.sourceLineOf(plan.startLine)
  const listing = store().stagedProgram
  // Only an armed posted remainder has replaced the file door's step ids.
  // A direct toolpath context has no source map; keep its existing door map.
  const listingLineOf = (currentFileDoorProgram()?.runFrom ? stagedProgramContext()?.lineOfStep : null)
    ?? keptStopDoor(kept.controller)?.lineOfStep ?? null
  if (listing === null || listingLineOf === null) {
    return { lineOf, startLine, sectionOf: null, numberingOf: () => null }
  }
  const steps = listing.program.steps
  const indexOfId = new Map(steps.map((step, index) => [step.id, index]))
  const lineAt = steps.map((step) => listingLineOf(step.id))
  const indexesOnLine = new Map<number, number[]>()
  lineAt.forEach((line, index) => {
    if (line !== undefined) indexesOnLine.set(line, [...(indexesOnLine.get(line) ?? []), index])
  })
  const sectionFirstLines = listing.setups.map((setup) => {
    for (let index = indexOfId.get(setup.firstStepId) ?? steps.length; index < steps.length; index++) {
      if (lineAt[index] !== undefined) return lineAt[index]!
    }
    return Infinity
  })
  const sectionOf = (fileLine: number): number => {
    let section = 0
    sectionFirstLines.forEach((first, index) => { if (first <= fileLine) section = index })
    return section
  }
  const fileTotal = steps.filter(isStagedMove).length
  const parts = filePartsOfListing?.listing === listing ? filePartsOfListing.firstStepIds : null
  return {
    lineOf,
    startLine,
    sectionOf: listing.setups.length > 0 ? sectionOf : null,
    numberingOf: ({ steps: staged, lineOfStep, stagedTotal, partFirstStepIds }) => {
      // undefined: a step with no line (a dwell); null: the prelude.
      const order = staged.map((step) => {
        const textLine = lineOfStep(step.id)
        return { id: step.id, line: textLine === undefined ? undefined : lineOf(textLine) }
      })
      const stagedOnLine = new Map<number, number[]>()
      for (const { id, line } of order) {
        if (typeof line === 'number') stagedOnLine.set(line, [...(stagedOnLine.get(line) ?? []), id])
      }
      const fileStep = new Map<number, number>()
      for (const [line, ids] of stagedOnLine) {
        const fileIndexes = indexesOnLine.get(line) ?? []
        if (fileIndexes.length === 0) continue
        ids.forEach((id, k) => {
          fileStep.set(id, steps[fileIndexes[Math.max(0, fileIndexes.length - ids.length + k)]].id)
        })
      }
      // A step with no line of its own (a dwell) is the file's step after the
      // one before it, when that one has no line either.
      let lastIndex = -1
      let startId: number | null = null
      for (const { id, line } of order) {
        const mapped = fileStep.get(id)
        if (mapped !== undefined) {
          lastIndex = indexOfId.get(mapped)!
          startId ??= mapped
        } else if (line === undefined && lastIndex >= 0 && lastIndex + 1 < steps.length && lineAt[lastIndex + 1] === undefined) {
          lastIndex += 1
          fileStep.set(id, steps[lastIndex].id)
        }
      }
      if (startId !== null) for (const { id, line } of order) if (line === null) fileStep.set(id, startId)
      // The file's part the return carries on in, and the return's own.
      let partsBefore = 0
      let stagedPartsBefore = 0
      const startIndex = startId === null ? undefined : indexOfId.get(startId)
      if (parts !== null && startIndex !== undefined) {
        parts.forEach((firstId, index) => {
          const at = indexOfId.get(firstId)
          if (at !== undefined && at <= startIndex) partsBefore = index
        })
        const stagedIndexOf = new Map(staged.map((step, index) => [step.id, index]))
        const stagedStart = order.findIndex(({ id, line }) => line !== null && fileStep.get(id) === startId)
        partFirstStepIds.forEach((firstId, index) => {
          const at = stagedIndexOf.get(firstId)
          if (at !== undefined && stagedStart >= 0 && at <= stagedStart) stagedPartsBefore = index
        })
      }
      return { stagedTotal, fileTotal, stepOf: (id) => fileStep.get(id) ?? null, partsBefore, stagedPartsBefore }
    },
  }
}

function keptStopReturnSentence(kept: KeptStop, plan: RunFromLinePlan): string {
  const at = plan.resumeAt
  // WO-2241: a canned cycle goes back to the start of the hole's cycle it was
  // part way through and drills that hole again. WO-2242: a tool change runs
  // again from its start, or - done - the program carries on after it.
  if (at === undefined) {
    return `"${kept.name}": going back to the start of line ${kept.sourceLineOf(plan.startLine)} and carrying on from there.`
  }
  const back = `"${kept.name}": going back to ${keptStopPointText(kept, at.pointMm)} (safe Z, then X/Y, then down at the approach feed)`
  if (at.programStop !== undefined) {
    return `${back} and carrying on after the stop on line ${kept.sourceLineOf(at.programStop.on)}.`
  }
  const change = at.toolChange
  if (change !== undefined) {
    const which = `${change.tool === null ? 'the tool change' : `the T${change.tool} change`} on line ${kept.sourceLineOf(change.on)}`
    return change.done
      ? `${back} and carrying on after ${which} with T${change.tool}.`
      : `${back} and running ${which} again from its start.`
  }
  return `${back} and carrying on from ${at.cycle === undefined ? 'inside' : `the start of the G${at.cycle} cycle on`} line ${kept.sourceLineOf(at.line)}.`
}

function sayKeptStopReturn(kept: KeptStop, plan: RunFromLinePlan): void {
  store().pushConsole('rx', keptStopReturnSentence(kept, plan), 'info')
}

/** The operator's own re-arm (from the top, from a line, Step Back) replaces
 *  the kept place with the start they chose. */
function forgetKeptStop(): void {
  keptStop = null
}

/** The operator's Stop, Reset or E-STOP: nothing that waited for a kept stop
 *  runs, a return under way ends like any program, and the kept place is
 *  forgotten - after a Stop, CYCLE START runs the program from its start,
 *  exactly as a plain pause -> Stop does (HARD LIMIT: Stop unchanged;
 *  rehearsal 2026-09-30 L3). A stop being taken now is abandoned too. */
function forgetKeptStopOnOperatorStop(ctrl: MachineController): void {
  operatorStopsSeen++
  dropCommandsWaitingForKeptStop(ctrl)
  if (keptStop !== null && keptStop.controller === ctrl) keptStop = null
}

/**
 * WO-2239: A TOOL CHANGE IN A KEPT STOP. Operator's same ask as WO-2237 ("save its
 * place and perform the tasks that I'm asking"); its architect default: "A
 * tool changed during the stop: resume uses the tool now in the spindle, with
 * its measured length."
 *
 * - LinuxCNC runs a typed `T2 M6` itself and holds at it (WO-2100): CYCLE
 *   START answers it (`answerKeptStopToolChange`), and the next CYCLE START is
 *   the return. A typed `M61 Q2` is LinuxCNC's too. LinuxCNC does not report
 *   the tool in its spindle here, so the tool the operator typed is kept on
 *   the stop and the return's `G43 H` names it (LinuxCNC's own length).
 * - The AXBB-E bridge has no M6 of its own: the typed `T2 M6` runs the same
 *   guided change a program's M6 runs (park, fit, measure, apply) when the
 *   machine has one, else the tool is set as fitted and its measured length
 *   applied, as UCCNC's M6 macro sets the current tool. `M61 Q2` sets it.
 */
function keptStopControllerToolChange(ctrl: MachineController): LinuxcncToolChange | null {
  const read = (ctrl as { linuxcncToolChange?: () => LinuxcncToolChange | null }).linuxcncToolChange
  if (typeof read !== 'function') return null
  const wait = read.call(ctrl)
  // A program's own M6 carries its line (WO-2100); an MDI M6 has none.
  if (wait === null || wait.line !== null || ctrl.machineState() !== 'hold') return null
  const kept = liveKeptStop(ctrl)
  return kept !== null && kept.resumed === null ? wait : null
}

function answerKeptStopToolChange(ctrl: MachineController, waiting: LinuxcncToolChange, answer: () => boolean): boolean {
  const kept = liveKeptStop(ctrl)
  const answered = answer()
  if (answered) selectToolWord(ctrl, waiting.tool)
  if (answered && kept !== null) {
    if (waiting.tool > 0) keepStopTool(kept, waiting.tool)
    const fitted = waiting.tool > 0 ? `T${waiting.tool} is in the spindle` : 'the spindle is empty'
    store().pushConsole(
      'rx',
      `Cycle Start answered the tool change: ${fitted}. Once the machine reads Idle, ${keptStopCycleStartSentence(kept)}`,
      'info',
    )
  }
  return answered
}

/** A guided change typed in a kept stop (bridge), until its card finishes. */
let keptStopGuidedChange: { kept: KeptStop; tool: number } | null = null

function keptStopGuidedChangeOpen(ctrl: MachineController): boolean {
  const change = keptStopGuidedChange
  if (change === null || change.kept.controller !== ctrl) return false
  const card = store().toolChange
  return card !== null && card.mode === 'toolChange' && card.tool === change.tool
}

/** A tool changed in an earlier stop of this program still holds at a new
 *  stop, unless the program changed tools itself between the two. */
function toolCarriedToKeptStop(previous: KeptStop | null, text: string, line: number): KeptStopTool {
  const none: KeptStopTool = { toolNow: null, toolNowAt: 0 }
  if (previous === null || previous.toolNow === null) return none
  const raw = text.split(/\r?\n/)
  for (let n = Math.min(previous.line, line) + 1; n <= Math.max(previous.line, line); n++) {
    const code = (raw[n - 1] ?? '').replace(/\([^)]*\)/g, ' ').replace(/;.*$/, '')
    if (/(?:^|[^A-Z])M0*6(?:1)?(?![0-9])/i.test(code)) return none
  }
  return { toolNow: previous.toolNow, toolNowAt: previous.toolNowAt }
}

type KeptStopTool = Pick<KeptStop, 'toolNow' | 'toolNowAt'>

/** Tool n went into the spindle in the stop (typed, answered, guided). */
function keepStopTool(kept: KeptStop, tool: number): void {
  kept.toolNow = tool
  kept.toolNowAt = Date.now()
}

/** The tool the return cuts with: the latest word on the spindle. A tool
 *  changed in the stop stands until the Tools panel's Measure Tn says
 *  otherwise - it measures only the tool in the spindle, and records when.
 *  The store's tool cannot say it: a controller's own tool report (the
 *  simulator's T0, GRBL's T) overwrites the Tools panel's mark there. */
function keptStopToolNow(kept: KeptStop): number | null {
  if (kept.toolNow === null) return store().activeTool
  const table = useMachineToolTable.getState().tableFor(controlMachine(useCamStore.getState()).id)
  let latest: { tool: number; at: number } | null = null
  for (const entry of table.tools) {
    const at = entry.measuredAt
    if (typeof at === 'number' && at > (latest?.at ?? kept.toolNowAt)) latest = { tool: entry.tool, at }
  }
  return latest?.tool ?? kept.toolNow
}

type TypedToolChange = { kind: 'select' | 'm6' | 'm61'; tool: number | null }

/** The tool words of an MDI line: `T2` alone selects, `T2 M6` / `M6` fits,
 *  `M61 Q2` sets the tool in the spindle. Null for any other line. */
function typedToolChange(words: readonly GcodeWord[]): TypedToolChange | null {
  const said = words.filter((w) => w.letter !== 'N')
  const whole = (w: GcodeWord | undefined) => (w !== undefined && Number.isInteger(w.value) && w.value >= 0 ? w.value : null)
  const t = said.find((w) => w.letter === 'T')
  if (said.some((w) => w.letter === 'M' && w.value === 61)) {
    const q = whole(said.find((w) => w.letter === 'Q'))
    return said.length === 2 && q !== null ? { kind: 'm61', tool: q } : null
  }
  if (said.some((w) => w.letter === 'M' && w.value === 6)) {
    return said.length === (t === undefined ? 1 : 2) ? { kind: 'm6', tool: whole(t) } : null
  }
  return t !== undefined && said.length === 1 ? { kind: 'select', tool: whole(t) } : null
}

/** The kept stop a typed tool line belongs to: live, not yet resumed. */
function keptStopForTypedTool(ctrl: MachineController, typed: TypedToolChange | null): KeptStop | null {
  if (typed === null) return null
  const kept = liveKeptStop(ctrl)
  return kept !== null && kept.resumed === null ? kept : null
}

/** A text controller ran the operator's tool line itself: its T selects (in a
 *  stop or not, WO-2521), and in a stop the tool is kept. */
function noteKeptStopToolTyped(
  ctrl: MachineController,
  kept: KeptStop | null,
  typed: TypedToolChange | null,
  sent: boolean,
): boolean {
  if (!sent || typed === null) return sent
  const tool = typed.kind === 'm61' ? typed.tool : typed.tool ?? selectedToolWordOf(ctrl)
  if (typed.kind !== 'm61') selectToolWord(ctrl, typed.tool)
  if (kept !== null && typed.kind !== 'select' && tool !== null) keepStopTool(kept, tool)
  return sent
}

/**
 * The bridge's tool change in a kept stop. The spindle stops first, as
 * UCCNC's M6 macro does. With a tool-change park, a measured reference and a
 * safe Z the guided change runs (its card's Continue measures and applies);
 * otherwise the tool is set as fitted, at the length the table holds for it.
 * Null when the line is not one this door takes (a bare `M6` with no tool
 * named): it goes on as before.
 */
function runKeptStopToolChangeOnBoard(
  text: string,
  ctrl: MachineController,
  kept: KeptStop,
  typed: TypedToolChange,
): boolean | null {
  if (typed.kind === 'select') {
    if (typed.tool === null) return null
    store().pushConsole('tx', text, 'info')
    selectToolWord(ctrl, typed.tool)
    mdiSaid(text, `T${typed.tool} is selected; M6 fits it.`, 'info')
    return true
  }
  const tool = typed.kind === 'm61' ? typed.tool : typed.tool ?? selectedToolWordOf(ctrl)
  if (tool === null) return null
  store().pushConsole('tx', text, 'info')
  if (typed.kind === 'm61') return setKeptStopTool(text, kept, tool, 'is now the tool in the spindle')
  // WO-2521: the T word on `T2 M6` selects T2 too, for a later bare M6.
  selectToolWord(ctrl, typed.tool)
  commandSpindle('off', 0, () => ['M5'], ctrl)
  const { park, safeZMachine } = typedToolChangePark(ctrl)
  if (park === null || safeZMachine === null) {
    return setKeptStopTool(text, kept, tool, 'is fitted (the spindle is stopped - fit it now)')
  }
  keptStopGuidedChange = { kept, tool }
  void beginGuidedToolChange({ tool, resumeLine: kept.sourceLineOf(kept.line), park, safeZMachine })
  mdiSaid(
    text,
    `moving to "${park.label}". Fit T${tool}; Continue will probe it and apply its measured length, then `
      + `${keptStopCycleStartSentence(kept)}`,
    'info',
  )
  return true
}

/** The guided change's park and safe Z when a typed M6 can run it (a
 *  tool-change park, a measured reference, a safe Z and a datum); both null
 *  when the tool is set as fitted instead. */
function typedToolChangePark(ctrl: MachineController): { park: ParkPosition | null; safeZMachine: number | null } {
  const park = configuredToolChangePark()
  const safeZMachine = machineSafeZValue(
    parkCarrierMachine(useCamStore.getState()),
    useMachineActions.getState().configFor(controlMachine(useCamStore.getState()).id),
  )
  const guided = park !== null && guidedChangeWillMeasure() && safeZMachine !== null
    && homingRefusal(ctrl, undefined, 'the tool change parks at a machine coordinate.') === null
  return guided ? { park, safeZMachine } : { park: null, safeZMachine: null }
}

/** Tool n is the one in the spindle now: the store's, the stop's, and its
 *  measured length applied (the same Apply the Tools panel's button sends). */
function setKeptStopTool(text: string, kept: KeptStop | null, tool: number, what: string): boolean {
  store().setActiveTool(tool)
  if (kept !== null) keepStopTool(kept, tool)
  const length = resolveG43ToolLengthMm(tool)
  const applied = length.measured && applyToolLengthOffset(length.deltaMm)
  const lengthSaid = applied
    ? `its measured length (${machineLengthText(length.deltaMm)} from the reference tool) is applied`
    : length.measured
      ? 'its measured length could not be applied - check the machine before CYCLE START'
      : `it has no measured length in this machine's tool table - measure T${tool} (Tools) or set its Z work zero first`
  mdiSaid(text, `T${tool} ${what}; ${lengthSaid}.${kept === null ? '' : ` ${keptStopCycleStartSentence(kept)}`}`, 'info')
  return true
}

/**
 * WO-2521: THE SELECTED TOOL. A bare `M6` fits the tool named by the most
 * recent T word, by ANY route - an MDI line with no program, one typed in a
 * pause, the program's own lines as they ran, a controller's tool change
 * answered in a stop. Two audits found a bare M6 fitting an older T: each
 * route kept its own record. One record per connection; every route writes
 * it, and a newer T replaces it whichever route gave it.
 */
let selectedToolWord: { controller: MachineController; tool: number } | null = null

function selectToolWord(ctrl: MachineController, tool: number | null): void {
  if (tool !== null && Number.isInteger(tool) && tool >= 0) selectedToolWord = { controller: ctrl, tool }
}

function selectedToolWordOf(ctrl: MachineController): number | null {
  return selectedToolWord?.controller === ctrl ? selectedToolWord.tool : null
}

/** The program's T words count as it runs them: the last whole T among the
 *  source lines `from`..`to` (inclusive) of `text` is the selected tool. */
function selectProgramToolWord(ctrl: MachineController, text: string, from: number, to: number): void {
  const lines = text.split(/\r?\n/)
  for (let n = Math.min(to, lines.length); n >= Math.max(from, 1); n--) {
    const t = tokenizeLine(stripGcodeComments(lines[n - 1]), n).words.findLast((w) => w.letter === 'T')
    if (t !== undefined && Number.isInteger(t.value) && t.value >= 0) {
      selectToolWord(ctrl, t.value)
      return
    }
  }
}

/** A program run that ended (completed, stopped, failed): the T words it ran
 *  select. An MDI line's job is not the program's; a kept stop being taken
 *  reads its own line (`takeKeptStop`). */
function selectToolWordsTheProgramRan(ctrl: MachineController, event: JobLifecycleEvent): void {
  if (event !== 'completed' && event !== 'stopped' && event !== 'failed') return
  const s = store()
  if (mdiLineOverLoadedProgram(ctrl) || (mdiStagedLine !== null && s.job.name === mdiStagedLine)) return
  if (keptStopTaking?.controller === ctrl) return
  const door = keptStopDoor(ctrl)
  if (door === null) return
  const returning = keptStop !== null && keptStop.controller === ctrl && keptStop.sourceText === door.text
    && keptStop.resumed !== null ? keptStop : null
  const from = returning === null ? 1 : returning.sourceLineOf(returning.resumed!.startLine)
  selectProgramToolWord(ctrl, door.text, from, event === 'completed' ? Number.POSITIVE_INFINITY : s.job.ackedSourceLine)
}

const MDI_M6_NAMES_NO_TOOL = 'M6 fits the tool named by T, and no tool has been named - type it on the line '
  + '(T19 M6) or select it first (T19). Nothing on this line was sent.'

/**
 * WO-2521: A TOOL CHANGE TYPED WITH NO PROGRAM. Operator, 10-03 (F9): `T19 M6`
 * on the MDI line with no program was refused ("it runs inside a loaded
 * program") while the same line typed in a pause parked and measured on his
 * board. The software can do it (rule 11), so it does - the pause route's own
 * steps, with no stop to keep: `T19` selects, `T19 M6` / `M6 T19` / `M6` after
 * a `T19` stops the spindle and runs the guided change (park, fit, Continue
 * measures and applies), or with no park sets the tool as fitted at its
 * measured length; `M61 Q19` sets the tool in the spindle. Null when the line
 * is not one this door takes: it goes on as before.
 */
function runIdleToolChangeOnBoard(
  text: string,
  ctrl: MachineController,
  typed: TypedToolChange,
  words: readonly GcodeWord[],
): boolean | null {
  // `T1.5 M6` names no whole tool: refused by word as before, never read as
  // the tool selected earlier.
  if (typed.tool === null && words.some((w) => w.letter === 'T')) return null
  // WO-1644: a word the operator removed from the table (M6) is refused by the
  // table's own sentence, as on every other route. A word the dialect never
  // listed (M61 on UCCNC) is this door's own, as in a pause.
  const table = mdiWordTable()
  const builtIn = table === null ? null : builtInGcodeWordTable(table.dialect)
  const listed = words.filter((w) => builtIn !== null && gcodeWordEntry(builtIn, w.letter, w.value) !== null)
  if (mdiTableRefusal(listed) !== null) return null
  if (typed.kind === 'select') {
    if (typed.tool === null) return null
    store().pushConsole('tx', text, 'info')
    selectToolWord(ctrl, typed.tool)
    mdiSaid(text, `T${typed.tool} is selected; M6 fits it.`, 'info')
    return true
  }
  const tool = typed.kind === 'm61' ? typed.tool : typed.tool ?? selectedToolWordOf(ctrl)
  store().pushConsole('tx', text, 'info')
  if (ctrl.connectionPhase() !== 'connected') return refuseMdiLine(text, 'not connected to a machine, so nothing was sent.')
  if (tool === null) return refuseMdiLine(text, MDI_M6_NAMES_NO_TOOL)
  if (typed.kind === 'm61') return setKeptStopTool(text, null, tool, 'is now the tool in the spindle')
  const card = store().toolChange
  if (card !== null && card.step !== 'failed') {
    return refuseMdiLine(text, 'a tool change is already open on the tool-change card - finish or cancel it '
      + 'first. Nothing on this line was sent.')
  }
  // The T word on an accepted `T19 M6` selects T19 too, so a later bare `M6`
  // fits T19, never a tool selected before it.
  selectToolWord(ctrl, typed.tool)
  commandSpindle('off', 0, () => ['M5'], ctrl)
  const { park, safeZMachine } = typedToolChangePark(ctrl)
  if (park === null || safeZMachine === null) {
    return setKeptStopTool(text, null, tool, 'is fitted (the spindle is stopped - fit it now)')
  }
  void stopAndPark({
    tool,
    resumeLine: 0,
    park,
    safeZMachine,
    mode: 'toolChange',
    typedOnMdi: true,
    awaitingMessage: `Insert T${tool} and snug it. Then press Continue: the tool is measured at the tool setter `
      + '(right here if this machine has none) and its length offset applied.',
  })
  mdiSaid(text, `moving to "${park.label}". Fit T${tool}; Continue will probe it and apply its measured length.`, 'info')
  return true
}

/** The guided change a typed M6 started with no program, until it ends. */
let mdiGuidedChange: { controller: MachineController; tool: number } | null = null

function mdiGuidedChangeOpen(ctrl: MachineController): boolean {
  const change = mdiGuidedChange
  if (change === null || change.controller !== ctrl) return false
  const card = store().toolChange
  return card !== null && card.mode === 'toolChange' && card.tool === change.tool
}

/** WO-2533: a program is loaded behind the typed change. An MDI line's own
 *  finished job is not one (desk kit, 10-04: after `G0 X10 Y10` the job read
 *  'complete' under the line's name, and the top line said "Program held"
 *  with no program) - read as `selectToolWordsTheProgramRan` reads it. Only
 *  a finished line: CYCLE START is dark there either way, and a line still
 *  staged keeps the card as the owner, so no press changes what it does. */
function programLoadedUnderTypedChange(ctrl: MachineController): boolean {
  const s = store()
  if (s.job.phase === 'empty') return false
  if (mdiLineOverLoadedProgram(ctrl)) return true
  const mdiLineOwnJob = mdiStagedLine !== null && s.job.name === mdiStagedLine
  return !(mdiLineOwnJob && (s.job.phase === 'complete' || s.job.phase === 'failed'))
}

/** True while the card belongs to the guided change a typed M6 started with
 *  no program - its words name the typed line, not a program's M6. Every
 *  other flow clears the claim as it starts (`stopAndPark`). */
function guidedChangeIsTyped(base: { tool: number | null }): boolean {
  return mdiGuidedChange !== null && mdiGuidedChange.tool === base.tool
}

/**
 * Toggle Single Block MODE. The controller flag is the enforced boundary
 * (start/resume refuse while on); the store flag is its render mirror. Both
 * always move together, so no UI path can hold a mode the controller ignores.
 */
export function setMachineSingleBlock(on: boolean): void {
  if (stepBackInProgressValue) return
  getMachineController().setSingleBlockMode(on)
  store().setSingleBlock(on)
}

/** Select G54-G59 and re-read modal state + offsets.
 *  WO-1181: the operator's press IS the selection. The store's `activeWcs`
 *  used to be written only by a typed G5x ack or a grbl `$G` report; the UCCNC
 *  bridge has neither (no G-code text path, no `wcs` in its state frame), so
 *  on the AXBB-E this button never registered and Goto XY0 refused forever
 *  ("select the active work offset ... first"). Same trust basis as the typed
 *  ack; grbl's `$G` refresh still confirms or corrects it. */
export function selectWorkOffset(wcs: WcsId): void {
  const c = getMachineController()
  if (!c.selectWcs(wcs)) return
  store().setActiveWcs(wcs)
  c.refreshState()
}

/** What a work-zero press actually achieved, per axis. `refused` is the list an
 *  operator has to act on; `ok` means nothing was refused.
 *
 *  WO-1022: the return shape is additive - every caller today
 *  (`src/components/machine/ControlPage.tsx`, `pendantMachine.ts`) ignores it -
 *  so no caller changed here. Those callers reporting success unconditionally
 *  is the next order's problem, and it is a real one: the pendant answers
 *  `{ ok: true }` to a zero-axes command whatever this returns. */
interface WorkZeroResult {
  ok: boolean
  /** Axes the controller confirmed it zeroed, in the order they were asked. */
  zeroed: ControlAxis[]
  /** Axes the controller refused. */
  refused: ControlAxis[]
}

/**
 * Zero one or more axes in the ACTIVE WCS through the INTERFACE INTENT, then
 * re-read offsets.
 *
 * WO-1022. This used to build `G10 L20 P0 X0 Y0 Z0` and push it through
 * `sendCommand`, which is G-code text above the machine-control boundary. The
 * AXBB-E backend refuses text, so on Operator's machine the button did nothing and
 * (until WO-1021) reported success while doing it. `zeroWorkAxis(axis)` has
 * existed on the interface since ADR-0041 and EVERY backend implements it:
 * GRBL sends that same G10 line itself, the simulator writes its own WCO, and
 * the bridge has a `ZeroWorkAxis` call. So there is no capability to branch on
 * - the session says WHAT it wants and the backend decides HOW. That is the
 * boundary rule in its purest form.
 *
 * A refusal does not abort the remaining axes: a half-zeroed machine is only
 * worse than a refused one if nobody says so, and this says so - one plain
 * console line naming the refused axes. `refreshState()` runs either way, so
 * the readout shows what is TRUE rather than what was asked for.
 *
 * Nothing here gates on the E-STOP latch, exactly as before: this writes an
 * offset register, it starts no motion, and no gate may ever be added on the
 * path of a stop.
 */
export function zeroWorkAxes(
  axes: ControlAxis[],
  injected?: MachineController,
): WorkZeroResult {
  const c = injected ?? getMachineController()
  const wcs = store().activeWcs
  const zeroed: ControlAxis[] = []
  const refused: ControlAxis[] = []
  const receiptWrites: Array<{ axis: ControlAxis; receipt: Promise<ZeroWorkAxisReceipt> }> = []
  // An empty ask is not a refusal and not a write - nothing is sent, nothing
  // is re-read, and no console line claims either happened.
  if (axes.length === 0) return { ok: true, zeroed, refused }
  // WO-1330: the one answer - see the table above `workOffsetWriteRefusal`.
  const held = workOffsetWriteRefusal(wcs, axes)
  if (held !== null) {
    store().pushConsole('tx', held, 'error')
    return { ok: false, zeroed, refused: [...axes] }
  }
  const machineId = controlMachineId()
  // WO-1042, the one-in-flight rule: a zero is ONE operation however many axes
  // it names, and it holds the machine's single offset-write slot for all of
  // them. A zero that arrives while another offset write is still awaiting its
  // receipt is refused with one console line - never queued behind it.
  if (machineWorkOffsetWriteInFlight(machineId)) {
    refuseOverlappingWorkOffsetWrite()
    return { ok: false, zeroed, refused: [...axes] }
  }
  // Only the receipt-bearing form has anything to wait for; the fire-and-forget
  // form completes inside this call and never holds the slot.
  const takesSlot = typeof c.zeroWorkAxisAwait === 'function'
  if (takesSlot) setWorkOffsetWriteInFlight(machineId, true)
  for (const axis of axes) {
    if (c.zeroWorkAxisAwait) {
      const receipt = c.zeroWorkAxisAwait(axis)
      if (receipt) {
        zeroed.push(axis)
        receiptWrites.push({ axis, receipt })
      } else refused.push(axis)
      continue
    }
    if (c.zeroWorkAxis(axis)) {
      zeroed.push(axis)
      markWorkZeroSet(wcs, axis)
    } else refused.push(axis)
  }
  if (refused.length > 0) {
    const alsoSet = zeroed.length > 0 ? ` Work zero was set for ${describeAxisList(zeroed)}.` : ''
    store().pushConsole(
      'rx',
      `The machine would not set work zero for ${describeAxisList(refused)}.${alsoSet}`,
      'error',
    )
  }
  if (receiptWrites.length > 0) {
    const revision = connectionRevision
    const generation = captureBackendGeneration(c)
    void Promise.all(receiptWrites.map(async ({ axis, receipt }) => ({ axis, receipt: await receipt })))
      .then((results) => {
        if (revision !== connectionRevision || !backendGenerationIsCurrent(generation)) return
        storeZeroedAxesFromReceipts(machineId, wcs, results, revision)
        c.refreshState()
      })
      .catch((error) => {
        if (revision !== connectionRevision || !backendGenerationIsCurrent(generation)) return
        store().pushConsole(
          'rx',
          `The machine did not confirm work zero - ${error instanceof Error ? error.message : 'the receipt failed'}.`,
          'error',
        )
      })
      // Accepted or refused, the receipt releases the slot - and so does a
      // rejected promise, so a dead bridge can never leave the offset controls
      // disabled for the rest of the session.
      .finally(() => {
        if (revision === connectionRevision && backendGenerationIsCurrent(generation)) {
          setWorkOffsetWriteInFlight(machineId, false)
        }
      })
  } else {
    if (takesSlot) setWorkOffsetWriteInFlight(machineId, false)
    c.refreshState()
  }
  return { ok: refused.length === 0, zeroed, refused }
}

/**
 * THE ONLY PATH FROM A ZERO INTO THE DURABLE STORE. See the write table above
 * `storeWorkOffset`: the value is `receipt.offset[axis]`, for the ONE axis the
 * call named, and it comes from the backend that applied the write.
 *
 * A receipt that confirms without an `offset` is a bridge older than WO-1083
 * saying "applied, cannot say what it became". That writes NOTHING and says so
 * once - it does not fall back to a status frame, which is the inference that
 * cost this order ten audit rounds.
 */
function storeZeroedAxesFromReceipts(
  machineId: string,
  activeWcs: WcsId | null,
  results: ReadonlyArray<{ axis: ControlAxis; receipt: ZeroWorkAxisReceipt }>,
  revision: number,
): void {
  const mute: ControlAxis[] = []
  for (const { axis, receipt } of results) {
    if (!receipt.confirmed) continue
    // The bridge names the system it zeroed in. Believe it over the app's idea
    // of the active one: a disagreement is the app being wrong about the
    // machine, and storing it under the machine's answer is what keeps the
    // WO-1017 gate honest about which WCS was actually established.
    const wcs = receipt.wcs ?? activeWcs
    if (!wcs) continue
    // WO-1017's gate is armed by the OPERATOR ACTION, not by the bookkeeping:
    // the machine confirmed this zero in this session, so a work-coordinate
    // goto is as safe as it has ever been - even on a bridge too old to say
    // what number resulted. What that older bridge costs is durability, below,
    // and the console says so rather than quietly disarming a gate the
    // operator satisfied.
    markConfirmedWorkZero(wcs, axis, revision)
    if (!receipt.offset) {
      mute.push(axis)
      continue
    }
    storeWorkOffset(machineId, wcs, { [offsetAxisKey(axis)]: receipt.offset[offsetAxisKey(axis)] }, 'sent')
  }
  if (mute.length === 0) return
  store().pushConsole(
    'rx',
    `Work zero was set on the machine for ${describeAxisList(mute)}, but this bridge version does not `
      + 'report the resulting offset, so this computer will not remember it - update the bridge.',
    'warn',
  )
}

/** Ask for one axis of one work offset. The axes of a single synchronous pass
 * (a probe confirmation, the pendant) join ONE intent; anything arriving while
 * a write already awaits its receipt is refused, never queued. The store is
 * written by the receipt - see the one-in-flight rule above. Text-only backends
 * keep the acknowledged `G10 L2` route; UCCNC uses the typed call. */
export function setWorkOffsetValue(
  wcs: WcsId,
  axis: ControlAxis,
  valueMm: number,
  injected?: MachineController,
): boolean {
  return requestWorkOffsetValue(wcs, axis, valueMm, injected) !== null
}

/** `setWorkOffsetValue`, returning the write whose receipt decides it - true
 *  from here only means the write is on its way (WO-2042). */
function requestWorkOffsetValue(
  wcs: WcsId,
  axis: ControlAxis,
  valueMm: number,
  injected?: MachineController,
): OpenWorkOffsetWrite | null {
  if (!WCS_SLOTS.includes(wcs) || !Number.isFinite(valueMm)) return null
  const held = workOffsetWriteRefusal(wcs, [axis])
  if (held !== null) {
    store().pushConsole('tx', held, 'error')
    return null
  }
  const c = injected ?? getMachineController()
  const text = !c.setWorkOffset
  if (text && !c.capabilities?.gcodeText) return null
  const machineId = controlMachineId()
  const write = joinOrOpenWorkOffsetWrite(machineId, wcs, axis, valueMm, c, text)
  if (!write) {
    refuseOverlappingWorkOffsetWrite()
    return null
  }
  workOffsetWriteWatch?.(write)
  return write
}

/** Jog to work X0 Y0 (Z never moves). Cancellable like any jog.
 *  WO-328: gated behind the E-STOP latch like every other motion-initiating
 *  function in this module - a fresh, never-reset session must refuse this
 *  exactly like it refuses CYCLE START. */
export function gotoWorkXYZero(feedMmMin: number): boolean {
  if (estopNeedsReset()) {
    // WO-1181: this was the one refusal here with no console line - a fresh
    // connect answered the first Goto XY0 press with total silence.
    store().pushConsole('tx', `Goto work XY zero: refused - ${ESTOP_BLOCKS_MOTION}`, 'error')
    return false
  }
  const zeroRefusal = workGotoZeroRefusal(['X', 'Y'])
  if (zeroRefusal) {
    store().pushConsole('tx', `Goto work XY zero: refused - ${zeroRefusal}`, 'error')
    return false
  }
  const ctrl = getMachineController()
  // X AND Y. A work offset is measured from machine zero, so G54 X0 Y0 is
  // not a physical place until both machine-coordinate counters have a datum.
  const xyRefusal = homingRefusal(ctrl, ['X', 'Y'], 'a work offset is measured from machine zero.')
  if (xyRefusal) {
    store().pushConsole('tx', `Goto work XY zero: refused - ${xyRefusal}`, 'error')
    return false
  }
  return ctrl.jogToWorkXY(0, 0, feedMmMin)
}

/**
 * Safe-Z macro: jog Z to the machine-coordinate safe height. Uses the jog
 * protocol, so soft limits still apply, G90/G91 modal state is untouched,
 * and the move cancels like any jog. HOMING-GUARDED like every
 * machine-coordinate move.
 */
export function jogToSafeZ(
  safeZMachine: number | null | undefined,
  feedMmMin: number,
): { ok: boolean; reason?: string } {
  if (estopNeedsReset()) return { ok: false, reason: ESTOP_BLOCKS_MOTION }
  const ctrl = getMachineController()
  if (ctrl.connectionPhase() !== 'connected') return { ok: false, reason: 'Not connected to a machine.' }
  if (safeZMachine === null || safeZMachine === undefined || !Number.isFinite(safeZMachine)) {
    return { ok: false, reason: "Set this machine's Safe Z on the Machine tab of its definition first." }
  }
  // Z ALONE. This macro moves Z and nothing else, so asking about X or Y
  // would be a NEW refusal on a machine whose Z is referenced - the exact
  // "gate that suddenly refuses" WO-930 forbids. It is still never more
  // permissive than before: homing X alone used to open this and now does not.
  const zRefusal = homingRefusal(ctrl, ['Z'], 'safe Z is a machine coordinate.')
  if (zRefusal) return { ok: false, reason: zRefusal }
  if (!ctrl.jogToMachineZ(safeZMachine, feedMmMin)) {
    return { ok: false, reason: 'The controller refused the jog (machine busy or alarmed).' }
  }
  return { ok: true }
}

/**
 * Begin the controller's staged program only after every axis the program may
 * address has a machine datum. This is the app-side twin of the bridge's
 * RequireHomed gate, shared by every backend through the controller contract.
 */
export function startMachineJob(): boolean {
  const review = transferReviewValue
  if (review.result.refusals.length > 0) {
    store().pushConsole('tx', `Cycle Start: refused - ${review.result.refusals[0]}`, 'error')
    return false
  }
  // WO-1182: warnings were already told in the console at load; they never
  // hold Cycle Start.
  const ctrl = getMachineController()
  // WO-2237: CYCLE START from a kept stop goes back to where the pause was.
  if (!startingMdiLine && !startingKeptStopResume) {
    const kept = liveKeptStop(ctrl)
    if (kept !== null && kept.resumed === null) return startFromKeptStop(ctrl, kept)
  }
  // WO-1980: the one refusal a file kept for its work offset has. WO-2234: an
  // MDI line typed while it waits is not that file, and runs.
  const awaiting = startingMdiLine ? null : awaitedOffsetsCycleStartRefusal(ctrl)
  if (awaiting) {
    store().pushConsole('tx', awaiting, 'error')
    return false
  }
  const refusal = programHomingRefusal(ctrl)
  if (refusal) {
    store().pushConsole('tx', `Cycle Start: refused - ${refusal}`, 'error')
    return false
  }
  const reread = rereadFileForExecutionChange(ctrl)
  if (reread !== null) return reread
  // WO-2157: the text staged at Load left out the spindle starts a loaded probe
  // would have run. A tool change since (probe out, end mill in - or the other
  // way) changes that answer, so the program is staged again for the tool that
  // is loaded NOW. Only a start from the top of a whole program.
  const s = store()
  if (
    ctrl.capabilities.gcodeText && textJobFirstLine === 1 && !ctrl.hasActiveJob()
    && s.programText !== null && textProgramProbeKey !== null
    && textProbeKey(s.programText) !== textProgramProbeKey
  ) {
    restageLoadedProgram()
  }
  // WO-2016: said before the run, never refused.
  pointToReferenceToolNotice(ctrl)
  return ctrl.startJob()
}

/** Why the controller did not start its program, from its own state. */
function controllerStartRefusal(ctrl: MachineController): string {
  if (ctrl.connectionPhase() !== 'connected') return 'the machine is not connected. Nothing moved.'
  if (ctrl.machineState() === 'alarm') return 'the machine is in alarm - clear it, then press CYCLE START again. Nothing moved.'
  if (ctrl.jobProgress().phase === 'empty') {
    return store().programText !== null
      ? `the controller holds no armed program - press "Re-arm from start", then CYCLE START. Nothing moved.`
      : 'the controller holds no armed program - load it again, then CYCLE START. Nothing moved.'
  }
  if (ctrl.singleBlockMode()) return 'Single Block is on, so the program starts one block at a time. Nothing moved.'
  return `the controller did not start it (it reads ${ctrl.machineState()}). Nothing moved.`
}

/** Why the controller did not take a jog, from its own state. `deltaMm` is
 *  null for a run-until-released jog, which has no end point to check. */
function controllerJogRefusal(ctrl: MachineController, axis: ControlAxis, deltaMm: number | null): string {
  if (ctrl.connectionPhase() !== 'connected') return 'the machine is not connected. Nothing moved.'
  const state = ctrl.machineState()
  if (state === 'alarm') return 'the machine is in alarm - clear it, then jog again. Nothing moved.'
  if (state === 'home') return 'the machine is homing - wait for it to finish, then jog. Nothing moved.'
  if (ctrl.hasActiveJob()) return 'a program is running or held - Feed Hold, then Stop/Reset, before jogging. Nothing moved.'
  const key = axis.toLowerCase()
  const env = key === 'x' || key === 'y' || key === 'z' ? currentResolvedMachineMotion().envelope[key] : null
  const at = ctrl.status().machinePos
  if (env && at && deltaMm !== null) {
    const end = at[key as 'x' | 'y' | 'z'] + deltaMm
    if (end < env.min - ENVELOPE_FIT_TOLERANCE_MM || end > env.max + ENVELOPE_FIT_TOLERANCE_MM) {
      return `this ${deltaMm > 0 ? '+' : ''}${machineLengthText(deltaMm)} step would end at machine ${axis} ${machineLengthText(end)}, `
        + `outside ${axis} travel (${machineLengthText(env.min)} to ${machineLengthText(env.max)}). Nothing moved - jog the other way or use a smaller step.`
    }
  }
  if (deltaMm === null) {
    return `the controller did not start the jog (it reads ${state}) - most often the axis is already at the end of its travel in that direction. Nothing moved.`
  }
  return `the controller did not take the jog (it reads ${state}) - most often this step would carry ${axis} past the end of its travel. Nothing moved - try a smaller step or the other way.`
}

/** Untyped MDI text retains the long-standing M5/M9 escape hatch. Built-in
 *  actions use identity instead: a configured stop remains a stop regardless
 *  of its text, while a configured start never inherits an exemption merely
 *  because one of its lines happens to resemble a default stop. */
const ESTOP_EXEMPT_ACTION_LINE = /^\s*M0?[59]\s*$/i
const ESTOP_EXEMPT_ACTIONS: ReadonlySet<BuiltinActionId> = new Set([
  'spindleOff',
  'coolantOff',
])

/**
 * Run a machine action: send its lines in order down the MDI path. Stops at
 * the first refusal (disconnected or a job streaming - the RX-buffer rule)
 * and reports plainly. Lines echo in the console like any manual command.
 * WO-328/WO-477: while the E-STOP needs reset, a built-in stop action stays
 * available by identity. Untyped MDI input retains only the pure M5/M9 escape
 * hatch above; every typed non-stop action remains interlocked.
 */
export const ACTION_REFUSAL = {
  estop: ESTOP_BLOCKS_MOTION,
  alarm: 'The machine is in alarm - clear the alarm, then run this again. Nothing was sent or queued.',
  notSent: 'That could not be sent to the machine.',
} as const

/** WO-963. The same shape `commandSpindle` got in WO-474 item 1, for the same
 *  reason, on the function that carries far more traffic: every macro button,
 *  both coolant buttons, the text spindle route and the park moves.
 *
 *  Before this, both refusal paths returned a bare `{ ok: false, sent }`, so
 *  SpindlePanel's coolant half INFERRED the cause - it called
 *  `estopNeedsReset()` itself and fell back to a generic sentence. That is a
 *  second opinion about something this function already knows for certain,
 *  and it fails silently: a refusal path added here that the panel has never
 *  heard of simply arrives wearing the generic sentence.
 *
 *  THE TWO REFUSALS MUST DISAGREE. WO-474 item 1's best finding was that
 *  `notSent` and `estop` are different refusals on the same route. A line the
 *  transport could not send must NOT blame the E-STOP - the operator would go
 *  reset a button that was never the problem. The E-STOP branch is checked
 *  first precisely because it is the one that IS true when both could look it. */
export type MachineActionResult =
  | { ok: true; sent: number }
  | { ok: false; sent: number; reason: string }

export function runMachineAction(
  lines: string[],
  options: { action?: BuiltinActionId } = {},
): MachineActionResult {
  let sent = 0
  const actionIsStop = options.action !== undefined
    && ESTOP_EXEMPT_ACTIONS.has(options.action)
  for (const unit of actionUnits(lines)) {
    // WO-1637: an accessory's own off word is a stop as M9 is.
    const untypedLineIsStop = options.action === undefined
      && unit.length === 1
      && (ESTOP_EXEMPT_ACTION_LINE.test(unit[0])
        || (!getMachineController().capabilities.gcodeText && mdiLineOnlySwitchesOutputsOff(unit[0])))
    // WO-1635 safety round 2: the stop exemption covers the stop WORDS only.
    // The door rule (`mdiLineMayPassEstopLatch`, also enforced inside
    // sendMdiLine / sendMdiProgram) is asked here first so the refusal names
    // the E-STOP rather than "could not be sent", and nothing of this unit or
    // any later one leaves.
    const ctrl = getMachineController()
    const unitIsStopWords = unit.every((line) => mdiLineMayPassEstopLatch(line, ctrl))
    if (estopNeedsReset() && (!unitIsStopWords || (!actionIsStop && !untypedLineIsStop))) {
      return { ok: false, sent, reason: ACTION_REFUSAL.estop }
    }
    // WO-2002: the alarm door (`mdiLineRefusedByAlarm`, also enforced inside
    // sendMdiLine / sendMdiProgram) is asked here so the refusal names the
    // alarm rather than "could not be sent".
    if (unit.some((line) => mdiLineRefusedByAlarm(line, ctrl))) {
      return { ok: false, sent, reason: ACTION_REFUSAL.alarm }
    }
    const ok = unit.length === 1 ? sendMdiLine(unit[0]) : sendMdiProgram(unit)
    if (!ok) {
      return { ok: false, sent, reason: ACTION_REFUSAL.notSent }
    }
    sent += unit.length
  }
  return { ok: true, sent }
}

/** WO-1635: how an action's lines are dispatched. On a text controller, one
 *  line at a time, exactly as always. On a geometry controller the board holds
 *  ONE staged program and a started move locks MDI out until it ends, so a run
 *  of consecutive move/dwell lines (`G53 G0 Z120` then `G53 G0 X0 Y0`) is
 *  staged as ONE program - otherwise the second line would be refused while
 *  the first is still moving. A line after such a run is still sent in order,
 *  and is refused by the lockout if the moves have not finished. */
function actionUnits(lines: readonly string[]): string[][] {
  if (getMachineController().capabilities.gcodeText) return lines.map((line) => [line])
  const units: string[][] = []
  let run: string[] | null = null
  for (const line of lines) {
    if (!mdiWordsStageAProgram(tokenizeLine(line, 1).words)) {
      run = null
      units.push([line])
      continue
    }
    if (run === null) {
      run = [line]
      units.push(run)
    } else {
      run.push(line)
    }
  }
  return units
}

/** Several consecutive move/dwell lines of one configured action, staged and
 *  started as one program through the same door a typed motion line takes. */
function sendMdiProgram(lines: readonly string[]): boolean {
  const ctrl = getMachineController()
  if (estopNeedsReset() && !lines.every((line) => mdiLineMayPassEstopLatch(line, ctrl))) {
    return refuseMdiLine(lines.join(' / '), ESTOP_BLOCKS_MOTION)
  }
  if (lines.some((line) => mdiLineRefusedByAlarm(line, ctrl))) {
    return refuseMdiLine(lines.join(' / '), MDI_ALARM_REFUSAL)
  }
  // WO-2146: the probe door (`mdiLineWaitsForProbeCycle`).
  if (lines.some((line) => mdiLineWaitsForProbeCycle(line, ctrl))) {
    return holdMdiLineForProbeCycle(lines.join(' / '))
  }
  if ((hasActiveProgramJob(ctrl) || keptStopTakingFor(ctrl)) && !programOwnActionInFlight) {
    // WO-2237: as a typed line - after the pause becomes a kept stop.
    if (commandThroughKeptStop(ctrl, 'MDI', () => { sendMdiProgram(lines) })) return true
    store().pushConsole('tx', 'A program is running - MDI is locked out.', 'error')
    return false
  }
  const label = lines.join(' / ')
  store().pushConsole('tx', label, 'info')
  if (ctrl.connectionPhase() !== 'connected') {
    return refuseMdiLine(label, 'not connected to a machine, so nothing was sent.')
  }
  const between = programOwnActionBetweenParts(label)
  if (between !== null) return between
  // WO-2519: an action's lines in a kept stop read as MDI, as one line does.
  nameKeptStopCommand(ctrl, 'MDI')
  return stageMdiMotion(label, lines.join('\n'))
}

/** Which route a spindle command actually took, so the UI can say so rather
 *  than leaving the operator to guess why a button did nothing. */
export type SpindleRoute = 'calls' | 'text' | 'unsupported'

/** The route this connection offers, in preference order: a controller that
 *  takes spindle CALLS, else G-code TEXT, else nothing. */
export function spindleRoute(injected?: MachineController): SpindleRoute {
  const ctrl = injected ?? getMachineController()
  if (ctrl.capabilities.spindleCommands && ctrl.spindleOn && ctrl.spindleOff) return 'calls'
  if (ctrl.capabilities.gcodeText) return 'text'
  return 'unsupported'
}

/** The single answer used by both posted-file and generated-toolpath routes.
 * A non-manual definition plus any controller spindle route means S/M3/M4/M5
 * are commands, not instructions for a manual-start hold. */
export function machineSpindleIsDrivable(
  machine: Pick<MachineConfig, 'spindleDrive' | 'spindleLinkDefinition'>,
  injected?: MachineController,
): boolean {
  return machineDrivesSpindle(machine) && spindleRoute(injected) !== 'unsupported'
}

/**
 * Command the spindle by whichever route this controller actually has.
 *
 * WO-905/UI: the panel used to emit `M3`/`M5` unconditionally, and the AXBB
 * backend refuses text - so on the machine we ran to 24,000 RPM the button
 * did nothing. Text stays the route for GRBL, where it is correct AND where
 * the machine-action abstraction lets a user override the codes for their own
 * wiring. The call route takes RPM and the backend does the scaling.
 *
 * `off` is never refused for lack of a route: a stop that cannot be expressed
 * is still attempted on every route there is.
 */
/** The plain reasons a spindle command is refused. Exported so the panel that
 *  reports them and the tests asserting their text stay one string - the same
 *  rule ESTOP_RESET_REFUSAL and RE_ARM_REFUSAL follow.
 *
 *  WO-474 item 1. Before this existed `commandSpindle` returned only
 *  { ok, route }, so SpindlePanel INFERRED the cause: it called
 *  `estopNeedsReset()` itself and fell back to a generic sentence when that
 *  came back false. An inference is a second opinion about something this
 *  function already knows for certain, and it fails SILENTLY the moment a
 *  refusal path is added here that the panel has never heard of - the new
 *  refusal simply arrives wearing the generic sentence and nobody can tell.
 *  The reason now travels with the refusal.
 *
 *  `estop` is ESTOP_BLOCKS_MOTION rather than a spindle-specific sentence, on
 *  that constant's own rule: "the E-STOP is why this refused" reads identically
 *  everywhere it can appear. */
export const SPINDLE_REFUSAL = {
  estop: ESTOP_BLOCKS_MOTION,
  unsupported: 'This controller has no spindle control.',
  controllerRefused: 'The controller would not start the spindle.',
  notSent: 'The spindle command could not be sent to the machine.',
} as const

/** `reason` exists ONLY on the refusal branch, so a caller cannot read one off
 *  a success and cannot forget to handle one on a failure - the compiler makes
 *  the same point WO-474 was opened to make. */
export type SpindleCommandResult =
  | { ok: true; route: SpindleRoute }
  | { ok: false; route: SpindleRoute; reason: string; severity?: 'info' | 'error' }

export function commandSpindle(
  direction: 'cw' | 'ccw' | 'off',
  rpm: number,
  textLines: () => string[],
  injected?: MachineController,
): SpindleCommandResult {
  const ctrl = injected ?? getMachineController()
  const route = spindleRoute(ctrl)
  // WO-2237: in a pause the spindle is switched after the pause becomes a kept
  // stop, and CYCLE START puts the program's own spindle back.
  if (commandThroughKeptStop(ctrl, 'Spindle', () => { commandSpindle(direction, rpm, textLines, injected) })) {
    return { ok: true, route }
  }
  // A pause that cannot be kept keeps its lock on a START; a stop is never gated.
  if (direction !== 'off' && pausedProgramKeepsItsLock(ctrl)) {
    const reason = 'A program is running - the spindle is locked out.'
    store().pushConsole('tx', `Spindle: refused - ${reason}`, 'error')
    return { ok: false, route, reason }
  }

  if (direction === 'off') {
    if (activeSpindleCommand?.controller === ctrl) activeSpindleCommand = null
    // NOTHING GATES A STOP. Try the call if there is one, and still run the
    // text lines when that is this machine's route - the same rule Vfd.cs and
    // the bridge keep, carried up to the button.
    ctrl.spindleOff?.()
    switchSpindleRelays(ctrl, 5)
    if (route === 'text') {
      // A stop is never refused BY THE LATCH. Its action identity, rather than
      // the configured text, carries that rule through this shared gate.
      return runMachineAction(textLines(), { action: 'spindleOff' }).ok
        ? { ok: true, route }
        : { ok: false, route, reason: SPINDLE_REFUSAL.notSent }
    }
    return { ok: true, route }
  }

  // WO-2157: a Probe-type tool in the spindle is not spun, by any route. Asked
  // fresh on every start, so the moment another tool is loaded this is gone.
  // Said as information, not as a red line (fix round): `severity` tells the
  // caller how to print it; `ok:false` still keeps the panel from latching.
  const probe = controlLoadedProbe()
  if (probe !== null) return { ok: false, route, reason: probeSpindleRefusal(probe), severity: 'info' }

  if (route === 'calls') {
    if (estopNeedsReset()) return { ok: false, route, reason: SPINDLE_REFUSAL.estop }
    if (!spindleOverrideUsesExternalSetpoint(ctrl)) {
      return ctrl.spindleOn!(direction, rpm)
        ? { ok: true, route }
        : { ok: false, route, reason: SPINDLE_REFUSAL.controllerRefused }
    }
    const machine = controlMachine(useCamStore.getState())
    const reportedPercent = ctrl.status().overrides?.spindle ?? null
    const maximumRpm = machine.maxSpindleRpm
    const initial = maximumRpm === undefined ? null : resolveLiveSpindleOverride(
      rpm, maximumRpm, reportedPercent,
      { kind: 'spindle', to: 'percent', percent: reportedPercent ?? 100 },
    )
    const unboundedPercent = reportedPercent !== null && Number.isFinite(reportedPercent) ? reportedPercent : 100
    const effectiveRpm = initial?.effectiveRpm ?? rpm * unboundedPercent / 100
    if (!ctrl.spindleOn!(direction, effectiveRpm)) {
      return { ok: false, route, reason: SPINDLE_REFUSAL.controllerRefused }
    }
    activeSpindleCommand = {
      controller: ctrl,
      baseRpm: rpm,
      direction,
      overridePercent: initial?.appliedPercent ?? unboundedPercent,
      maximumNoticeSaid: initial?.clamped === true,
    }
    if (initial?.clamped) {
      store().pushConsole('rx', spindleMaximumNotice(maximumRpm!), 'warn')
      ctrl.setOverride({ kind: 'spindle', to: 'percent', percent: initial.appliedPercent })
    }
    switchSpindleRelays(ctrl, direction === 'cw' ? 3 : 4)
    return { ok: true, route }
  }
  if (route === 'text') {
    // Two different failures share this branch and the operator needs them
    // apart: a spindle START is NOT latch-exempt, so with the latch set this
    // is the E-STOP; otherwise the line did not go. The distinction is made
    // HERE, in the module that owns the latch, rather than by a panel asking
    // the latch a second question and hoping it means the same thing.
    const action: BuiltinActionId = direction === 'cw' ? 'spindleCw' : 'spindleCcw'
    if (runMachineAction(textLines(), { action }).ok) return { ok: true, route }
    return {
      ok: false,
      route,
      reason: estopNeedsReset() ? SPINDLE_REFUSAL.estop : SPINDLE_REFUSAL.notSent,
    }
  }
  return { ok: false, route, reason: SPINDLE_REFUSAL.unsupported }
}

/** WO-2157: the loaded tool when it is a Probe-type library entry, else null.
 *  The Probing screen's resolver (the one entry with that T, duplicates
 *  settled by the machine's tool table). Read fresh by every spindle-on route,
 *  never cached: nothing outlives the probe being the loaded tool. */
function controlLoadedProbe(tool: number | null = store().activeTool): Tool | null {
  if (tool === null) return null
  const library = useCamStore.getState().toolLibrary ?? []
  // Nothing to settle unless the library has a Probe with this T at all.
  if (!library.some((entry) => entry.toolNumber === tool && entry.type === 'probe')) return null
  const tableDiaMm = findTool(useMachineToolTable.getState().tableFor(controlMachineId()), tool)?.dia ?? null
  return loadedProbeTool(tool, library, tableDiaMm)
}

/** WO-2157: a toolpath program that starts the spindle, loaded while a probe
 *  is the loaded tool, says once that the probe will not be spun. */
function sayProbeAtToolpathLoad(name: string): void {
  if (geometryProgramSpindle === null) return
  const probe = controlLoadedProbe()
  if (probe !== null) store().pushConsole('rx', `"${name}": ${probeSpindleRefusal(probe)}`, 'info')
}

/** WO-2157: the one line a spindle-on request with a probe loaded says. */
function sayProbeKeepsSpindleOff(probe: Tool): void {
  store().pushConsole('rx', probeSpindleRefusal(probe), 'info')
}

/** WO-1637: the M3/M4 spindle relays, when the machine definition assigns
 *  them, switched BESIDE the spindle call (M5 clears both). A machine whose
 *  profile assigns none resolves nothing and nothing is sent. A text controller
 *  switches its own relays from the words. */
function switchSpindleRelays(ctrl: MachineController, code: 3 | 4 | 5): void {
  if (ctrl.capabilities.gcodeText || typeof ctrl.setOutput !== 'function') return
  const resolved = resolveMachineOutputWord(controlMachine(useCamStore.getState()), code)
  if (resolved === null || resolved.kind !== 'switch') return
  for (const sw of resolved.switches) {
    const receipt = switchOutputPin(ctrl, sw)
    if (sw.on && sw.delayMs > 0) holdMotionForOutputOnDelay(sw.delayMs)
    void receipt?.then((r) => {
      if (!r.ok && !r.superseded) {
        store().pushConsole('rx', `M${code}: ${describeOutputSwitch(sw)} was refused: ${r.reason}`, 'warn')
      }
    })
  }
}

export type ZProbeMode = 'workZero' | 'measureTool'

/**
 * WO-2059: THE SENSING CHOICE, ONE PER ROUTINE, PER MACHINE. The side
 * routines, the Z surface mesh (its first contact writes work Z0) and work Z0
 * itself each remember whether the probe touches the part or a plate held
 * against it. Absent is the first-time default, the probe (0 mm). A choice is
 * not a machine position, so a disconnect keeps it; it is setup on this
 * computer, so it lives in the persisted UI-prefs record (beside the
 * per-machine link settings) and an app reload keeps it too.
 */
export type ProbeSensingRoutine = ProbeFeatureKind | 'zSurface' | 'workZero'

export type MachineProbeSensing = Readonly<Partial<Record<ProbeSensingRoutine, ProbeSensing>>>

export function probeSensingFor(machineId: string, routine: ProbeSensingRoutine): ProbeSensing {
  return useUiPrefs.getState().probeSensingByMachine[machineId]?.[routine] ?? DEFAULT_PROBE_SENSING
}

export function setProbeSensing(machineId: string, routine: ProbeSensingRoutine, sensing: ProbeSensing): void {
  useUiPrefs.getState().setProbeSensingChoice(machineId, routine, sensing)
}

/** The machine's remembered choices, for a panel to render; absent routines
 *  read as the first-time default. */
export function useMachineProbeSensing(machineId: string): MachineProbeSensing | undefined {
  return useUiPrefs((s) => s.probeSensingByMachine[machineId]) as MachineProbeSensing | undefined
}

/** The pad a Z touch on the control machine is sensed through: T for a plate,
 *  0 when the probe touches the part. */
function controlZPlateMm(routine: 'zSurface' | 'workZero', config: ZProbeConfig): number {
  return sensedPlateMm(probeSensingFor(controlMachineId(), routine), resolveProbeConfig(null, config))
}

export type ProbeAxis = 'X' | 'Y' | 'Z'
export type ProbeDirection = '+' | '-'

interface ProbeContactObservations {
  /** Machine coordinate from the fast-pass receipt; null when that route cannot report it faithfully. */
  fastMachinePosition: number | null
  /** Machine coordinate from the fine-pass receipt. */
  fineMachinePosition: number
}

interface DirectionalProbeResult {
  ok: boolean
  /** Plain-language outcome / recovery text for the calling routine. */
  message: string
  /** Machine coordinate of the fine-pass contact on the requested axis; null on failure. */
  probedMachinePosition: number | null
  /** Receipt coordinates from a completed two-pass touch. Absent on failure/cancellation. */
  contacts?: ProbeContactObservations
  /** WO-2071: Stop/Reset ended it; `message` is the stopped sentence. */
  stopped?: true
}

interface ZProbeResult {
  ok: boolean
  /** Plain-language outcome / recovery text for the panel and console. */
  message: string
  /** Machine Z of the fine-pass contact (the tool length datum); null on failure. */
  probedMachineZ: number | null
  /** Receipt coordinates from a completed Z touch. Absent on failure/cancellation. */
  contacts?: {
    fastMachineZ: number | null
    fineMachineZ: number
  }
  /** WO-2071: Stop/Reset ended it; `message` is the stopped sentence. */
  stopped?: true
}

// WO-2560: this is an action result, not a program phase. Keep it outside
// the job so a probe or typed move cannot rename/re-arm the loaded file.
let nonProgramStatus: string | null = null
const nonProgramStatusListeners = new Set<() => void>()
export function nonProgramActionStatus(): string | null { return nonProgramStatus }
export function subscribeNonProgramActionStatus(listener: () => void): () => void {
  nonProgramStatusListeners.add(listener)
  return () => { nonProgramStatusListeners.delete(listener) }
}
function publishNonProgramActionStatus(message: string | null): void {
  if (nonProgramStatus === message) return
  nonProgramStatus = message
  for (const listener of nonProgramStatusListeners) listener()
}
function publishProbeActionResult(result: { ok: boolean; message: string; stopped?: true }, label: string): void {
  publishNonProgramActionStatus(result.ok
    ? `${label} finished. Ready.`
    : `${label} ${/already touching/i.test(result.message) && /not sent/.test(result.message) ? 'did not start' : result.stopped ? 'stopped' : 'did not finish'}: ${result.message}`)
}

let probeCycleActive = false
const probeCycleActiveListeners = new Set<() => void>()

/** WO-2138: every edge of the probe lock goes through here, so Main's Feed
 *  Hold (useSyncExternalStore) is live for the whole routine - its gaps
 *  between moves included - and dark again the moment it ends. */
function setProbeCycleActive(active: boolean): void {
  if (probeCycleActive === active) return
  probeCycleActive = active
  for (const listener of probeCycleActiveListeners) listener()
  // WO-2267: a mesh a re-zero ended under the routine stages the program now.
  if (!active && meshRestageOwed) {
    meshRestageOwed = false
    restageLoadedProgram()
  }
}

export function subscribeProbeCycleActive(listener: () => void): () => void {
  probeCycleActiveListeners.add(listener)
  return () => { probeCycleActiveListeners.delete(listener) }
}

// ---- WO-2071: Stop/Reset cancels a running probe routine ----
//
// WO-2063 measured it: Stop/Reset halted the move in flight and the runner
// carried on - on the simulator an Edge sent `G38.2 X20` after the Stop and
// moved 20 mm more; a Z0 waited forever on a search the reset had dropped; on
// the native board an Edge failed only after a 30 s "did not settle" wait.
// The session's Stop/Reset wrappers now end the routine that holds the probe
// lock: nothing more is sent through it, every wait it is in returns at once,
// and it ends as stopped with one console line naming the routine and step.

interface ProbeCycleRun {
  stopSource: 'Stop' | 'Stop/Reset'
  paused: boolean
  pauseEpoch: number
  cancelMotion: Promise<void>
  cancelFailure: string | null
  resumeMove: (() => boolean) | null
  /** The routine's name in the operator's sentence ("Edge probe", "Probe work Z0"). */
  routine: string
  /** The routine's step in flight, when it has steps. */
  step: string | null
  /** The part of that step (or of a lone touch) in flight. */
  phase: string | null
  stopped: boolean
  reported: boolean
  /** Settles when Stop/Reset ends this run. */
  stop: Promise<null>
  release: () => void
  /** WO-2517: the controller this run moves. */
  controller: MachineController
  /** WO-2517: an intended touch (the probe call, a G38 line) is in flight -
   *  the one time the probe input may come on. */
  touching: boolean
  /** WO-2517: a touch just ended at a contact. The input may read ON until
   *  the back-off clears it: the first OFF frame, or the back-off settling,
   *  ends this. */
  releasing: boolean
  /** WO-2517: motion commands sent since that touch ended. */
  movesSinceTouch: number
  /** WO-2517: the motion command in flight, in the operator's words. */
  move: string | null
  /** WO-2517: set when the probe input ended the run. */
  contact: ProbeCycleContact | null
  /** WO-2533: settles once the move a touch stopped has come to rest (or
   *  the wait for it ended); null when no move was stopped. */
  contactRest: Promise<void> | null
}

/** WO-2517: how the probe input ended a run. `touched` - it came on during a
 *  move that was not a touch, and that move was stopped; `touching` - it was
 *  already on when the next command would have started, and that command
 *  was not sent. */
interface ProbeCycleContact {
  kind: 'touched' | 'touching'
  at: MachineVec3 | null
  move: string | null
  /** WO-2533: where a stopped move came to rest - read after motion ended,
   *  not at the touch. Null until then, and when it was never read. */
  rest: MachineVec3 | null
}

let activeProbeCycle: ProbeCycleRun | null = null
const probeControllerResets = new WeakMap<MachineController, () => void>()
const probeControlledResets = new WeakSet<MachineController>()

/** Claimed alongside `probeCycleActive = true` by the routine that owns the lock. */
function claimProbeCycleRun(routine: string): ProbeCycleRun {
  let release: () => void = () => {}
  const stop = new Promise<null>((resolve) => { release = () => resolve(null) })
  const run: ProbeCycleRun = {
    stopSource: 'Stop/Reset',
    paused: false,
    pauseEpoch: 0,
    cancelMotion: Promise.resolve(),
    cancelFailure: null,
    resumeMove: null,
    routine,
    step: null,
    phase: null,
    stopped: false,
    reported: false,
    stop,
    release,
    controller: getMachineController(),
    touching: false,
    releasing: false,
    movesSinceTouch: 0,
    move: null,
    contact: null,
    contactRest: null,
  }
  activeProbeCycle = run
  return run
}

function releaseProbeCycleRun(run: ProbeCycleRun | null): void {
  if (run !== null && activeProbeCycle === run) activeProbeCycle = null
  for (const listener of probeCycleActiveListeners) listener()
}

export function isProbeCyclePaused(): boolean {
  return activeProbeCycle?.paused === true && !activeProbeCycle.stopped
}

/** WO-2600: cancel only this move, retaining its absolute endpoint. After
 * contact the native probe must finish its cycle without ProbeStop. */
export function pauseProbing(): void {
  const run = activeProbeCycle
  if (!run || run.stopped || run.paused) return
  run.paused = true
  if (!(run.touching && probeInputOn(run.controller.status()))) {
    run.pauseEpoch++
    cancelProbingMove(run)
  }
  for (const listener of probeCycleActiveListeners) listener()
}

export function resumeProbing(): void {
  if (!isProbeCyclePaused()) return
  activeProbeCycle!.paused = false
  for (const listener of probeCycleActiveListeners) listener()
}

export function stopProbing(): void {
  const run = activeProbeCycle
  if (!run || run.stopped) return
  run.stopSource = 'Stop'
  stopRunningProbeCycle()
  cancelProbingMove(run)
  for (const listener of probeCycleActiveListeners) listener()
}

/** G38 and a routine's G0/G1 positioning are MDI motion, not jogs.
 * WO-2615: Stop must cancel both, including back-off/retract and final park.
 * Pause keeps its existing touch/jog routing. GRBL's controlled reset and the
 * simulator's routine cancellation retain the staged program; UCCNC keeps
 * its measured StopNow door. */
function cancelProbingMove(run: ProbeCycleRun): void {
  const ctrl = run.controller
  if ((run.stopped || run.touching) && (ctrl.capabilities.gcodeText || 'cancelProbe' in ctrl)) {
    if ('cancelProbe' in ctrl && typeof ctrl.cancelProbe === 'function') {
      ctrl.cancelProbe()
      run.cancelMotion = Promise.resolve()
    } else if ('softReset' in ctrl && typeof ctrl.softReset === 'function') {
      probeControlledResets.add(ctrl)
      run.cancelMotion = ctrl.resetToIdle().then(result => {
        if (result.ok) return
        // A failed controlled stop proves neither idle nor safe replay. End
        // this routine with the controller's own reason, even after Stop.
        run.cancelFailure = result.reason
        run.stopped = true
        run.release()
        for (const listener of probeCycleActiveListeners) listener()
      }).finally(() => probeControlledResets.delete(ctrl))
    } else {
      probeControllerResets.get(ctrl)!()
      run.cancelMotion = Promise.resolve()
    }
  } else {
    ctrl.jogCancel()
  }
}

/** Called by the Stop/Reset wrappers BEFORE the controller is told. */
function stopRunningProbeCycle(): void {
  const run = activeProbeCycle
  if (run === null || run.stopped) return
  run.stopped = true
  run.release()
}

function probeCycleStopped(): boolean {
  return activeProbeCycle?.stopped === true
}

// ---- WO-2517: the probe input stops every probing move ----
//
// Real board 2026-10-03 (Bore, a carried nominal of 64 in a 43.5 mm bore): the
// sideways positioning at depth was a plain move, and the probe input read ON
// on every frame from X357.98 to X342.72 - the probe pushed the block 15 mm.
// Operator ruling 2026-10-03, at the machine: "If it senses a probe at any point during the probing
// it needs to stop because that's how you damage probes." So for the whole of
// a running probe cycle the input is watched on every status frame. It may be
// ON only while an intended touch is in flight (the probe call, a G38 line),
// and while the back-off from that touch clears it. Anywhere else the move in
// flight is stopped at once and the cycle ends, saying where. A motion command
// that would start with the input already ON is not sent. Outside a probe
// cycle nothing here runs: jogs, programs and MDI lines are untouched.

/** True while the probe circuit reads closed (the pin, polarity applied). */
function probeInputOn(status: MachineStatus): boolean {
  return status.inputs?.probe === true
}

/** Halts the move in flight: the bridge's jog stop (StopNow, the axis stopped
 *  by number and by Stop()), or the session's own reset on a controller that
 *  takes text - the queued lines go with it. Not the operator's Stop/Reset. */
function stopProbeCycleMotion(ctrl: MachineController): void {
  if (ctrl.connectionPhase() !== 'connected') return
  if (nativeProbeRoute(ctrl)) ctrl.jogCancel()
  else resetForSession(ctrl)
}

function endProbeCycleOnContact(
  run: ProbeCycleRun,
  kind: ProbeCycleContact['kind'],
  at: MachineVec3 | null,
  move: string | null,
): void {
  if (run.stopped) return
  run.contact = { kind, at: at ? { ...at } : null, move, rest: null }
  run.stopped = true
  run.release()
  // After the frame that said so has been handled: a stop issued from inside
  // the controller's own status event would run under its motion step.
  if (kind === 'touched') {
    queueMicrotask(() => stopProbeCycleMotion(run.controller))
    run.contactRest = readProbeContactRest(run, run.contact)
  }
}

/** WO-2533: how long the stopped move may take to come to rest before the
 *  line says only where it touched. */
const PROBE_CONTACT_REST_WAIT_MS = 3000

/**
 * WO-2533: WHERE THE STOPPED MOVE CAME TO REST. Desk kit, 10-04: the line said
 * "stopped at" the frame that read the input ON, and the machine coasted
 * 1.56 mm past it. The rest is the position once the board reports it is no
 * longer moving and two reads agree. Its first read waits a poll, so the stop
 * goes out before anything else is asked of the board.
 */
async function readProbeContactRest(run: ProbeCycleRun, contact: ProbeCycleContact): Promise<void> {
  const ctrl = run.controller
  const receiptToken = captureBackendReceipt(ctrl)
  const deadline = sessionElapsedNowMs() + PROBE_CONTACT_REST_WAIT_MS
  let previous: MachineVec3 | null = null
  while (sessionElapsedNowMs() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 50))
    if (!receiptIsCurrent(receiptToken) || ctrl.connectionPhase() !== 'connected') return
    const status = ctrl.status()
    const position = status.machinePos
    if (MOVING_STATES.has(status.state) || position === null) {
      previous = null
    } else if (previous !== null && sameMachinePosition(previous, position)) {
      contact.rest = { ...position }
      return
    } else {
      previous = { ...position }
    }
    ctrl.queryStatus()
  }
}

/**
 * WO-2517: every status frame of a running probe cycle. ON outside a touch and
 * outside the back-off from one stops the machine and ends the cycle; OFF ends
 * the back-off's allowance. The waits of a cycle read the same frame too.
 */
function watchProbeInput(ctrl: MachineController | null, status: MachineStatus): void {
  const run = activeProbeCycle
  if (run === null || run.stopped || ctrl !== run.controller || run.touching) return
  const on = status.inputs?.probe
  if (on === false) {
    run.releasing = false
    return
  }
  if (on !== true || run.releasing) return
  // At rest, the input came on between commands (a back-off that never
  // cleared it): nothing is in flight to name.
  const moving = MOVING_STATES.has(status.state)
  endProbeCycleOnContact(run, moving ? 'touched' : 'touching', status.machinePos, moving ? run.move : null)
}

/**
 * WO-2517: before a probe cycle sends a motion command (`move`, in the
 * operator's words). True when it must not be sent - the probe input reads ON
 * and this is not the back-off from a touch - and the run has ended saying
 * so; the caller returns as stopped. Outside a probe cycle, always false.
 */
function probeInputBlocksMove(ctrl: MachineController, move: string): boolean {
  const run = activeProbeCycle
  if (run === null || run.stopped || ctrl !== run.controller) return false
  const status = ctrl.status()
  if (probeInputOn(status) && !run.releasing) {
    // Still moving (a queued line runs): that move is stopped; at rest, this
    // one is not sent.
    const moving = MOVING_STATES.has(ctrl.machineState())
    endProbeCycleOnContact(run, moving ? 'touched' : 'touching', status.machinePos, moving ? run.move : move)
    return true
  }
  run.move = move
  if (run.releasing) run.movesSinceTouch += 1
  return false
}

/** WO-2517: an intended touch starts - checked like any move, then the input
 *  may come on until it ends. False when it must not be sent. */
function openProbeTouch(ctrl: MachineController, move: string): boolean {
  if (probeInputBlocksMove(ctrl, move)) return false
  const run = activeProbeCycle
  if (run !== null && run.controller === ctrl) run.touching = true
  return true
}

/** WO-2517: the touch ended. A contact (or an input still ON) starts the
 *  back-off allowance; the next command is the back-off. */
function closeProbeTouch(ctrl: MachineController, touched: boolean): void {
  const run = activeProbeCycle
  if (run === null || run.controller !== ctrl || !run.touching) return
  run.touching = false
  if (touched || probeInputOn(ctrl.status())) {
    run.releasing = true
    run.movesSinceTouch = 0
  }
}

/** WO-2517: a cycle's wait saw the machine settle. Once the back-off has
 *  run, the allowance ends - a probe still touching now ends the cycle. */
function noteProbeMotionSettled(ctrl: MachineController): void {
  const run = activeProbeCycle
  if (run === null || run.stopped || run.controller !== ctrl) return
  run.resumeMove = null
  if (run.releasing && run.movesSinceTouch >= 1) run.releasing = false
  watchProbeInput(ctrl, ctrl.status())
}

/** WO-2517: the words for a machine move a cycle sends. */
function probeCycleMoveText(target: Partial<MachineVec3>): string {
  return `the move to ${machinePositionText(target)}`
}

// ---- WO-2103: Feed Hold during a probe routine pauses it ----
//
// Rehearsal 2026-09-27 (native kit): Feed Hold mid-probe failed the routine
// on its own timeouts while the machine sat held, and CYCLE START had no
// routine left to resume. A hold now pauses the routine where it is: its waits
// stop the clock while the machine reports Hold, CYCLE START releases the hold
// (programHoldCycleStartDecision's 'probe-cycle'), and Stop/Reset ends the
// routine as it always did.

/** A Feed Hold the operator put on a running probe routine. */
function probeCycleHeldByOperator(ctrl: MachineController): boolean {
  return probeCycleActive && ctrl.connectionPhase() === 'connected' && (ctrl.machineState() === 'hold' || isProbeCyclePaused())
}

/** Waits while the machine is held; returns once it is not, or once Stop/Reset,
 *  the E-STOP or the connection ends the wait. The caller re-checks its gates. */
async function waitOutProbeCycleHold(ctrl: MachineController): Promise<void> {
  const receiptToken = captureBackendReceipt(ctrl)
  while (probeCycleHeldByOperator(ctrl)) {
    if (!receiptIsCurrent(receiptToken) || probeCycleStopped() || estopNeedsReset()) return
    if (ctrl.connectionPhase() !== 'connected') return
    ctrl.queryStatus()
    await new Promise((resolve) => setTimeout(resolve, 50))
  }
}

function noteProbeStep(step: string): void {
  if (activeProbeCycle === null) return
  activeProbeCycle.step = step
  activeProbeCycle.phase = null
}

function noteProbePhase(phase: string): void {
  if (activeProbeCycle !== null) activeProbeCycle.phase = phase
}

/** Stands in for a probe call or line the Stop ended; the owning routine
 *  replaces it with the stopped sentence. */
const PROBE_CYCLE_STOPPED = 'Stop/Reset ended the probe cycle.'

/** `pending`, unless Stop/Reset ends the running cycle first: then null. */
function untilProbeStop<T>(pending: Promise<T>): Promise<T | null> {
  const run = activeProbeCycle
  if (run === null) return pending
  if (run.stopped) return Promise.resolve(null)
  // A reply the reset itself produced (an alarm, a dropped line) is the Stop's,
  // never a probe that ran and missed.
  return Promise.race([pending, run.stop]).then(async (value) => {
    if (!run.stopped) return value
    // The routine's modal restore must not send MDI during GRBL's controlled
    // reset settle; that newer activity would correctly make it refuse reset.
    await run.cancelMotion
    return null
  })
}

// ---- WO-2138: the gaps between a routine's moves are part of the routine ----
//
// Rehearsal 2026-09-28 bite 5: a Feed Hold pressed in the short gap between two
// of a routine's moves did nothing - the button was dark and the routine
// carried on. The button is now live while a routine runs (subscribeProbeCycleActive),
// and every move, probe call and line a probe cycle sends waits out an operator
// hold first, so a hold that lands between moves keeps the NEXT one from
// starting until CYCLE START resumes it or Stop/Reset ends it.

/** A line a probe cycle sends: nothing once Stop/Reset ended the cycle, and a
 *  line still awaited when it does settles as not sent (null). WO-2138: held
 *  between moves, the line waits for CYCLE START. */
function probeCycleSend(line: string, ctrl: MachineController): Promise<AppCommandOutcome | null> | null {
  if (probeCycleStopped()) return null
  if (probeCycleHeldByOperator(ctrl)) {
    const run = activeProbeCycle
    return untilProbeStop(waitOutProbeCycleHold(ctrl).then(() => (
      run?.stopped || probeCycleStopped() || estopNeedsReset() ? null : sendProbeCycleLine(line, ctrl)
    )))
  }
  const pending = sendProbeCycleLine(line, ctrl)
  return pending === null ? null : untilProbeStop(pending)
}

/** A G38.2-G38.5 probe move: a touch, where the probe input may come on. */
const PROBE_TOUCH_LINE = /\bG38\.[2-5](?![\d])/i
/** A G0 or G1 move (not G10, G17, G21...). */
const PROBE_MOVE_LINE = /\bG0*[01](?![.\d])/i

/** WO-2517: the line goes out unless the probe input says it must not; a
 *  touch line opens the touch for as long as it runs. Null when not sent. */
function sendProbeCycleLine(line: string, ctrl: MachineController): Promise<AppCommandOutcome | null> | null {
  if (PROBE_TOUCH_LINE.test(line)) {
    // A text controller acks a line when it is queued: plain moves queued
    // ahead of this touch (the setter's lift and crossing) are still moves,
    // so they finish watched before the touch opens. The fine pass also waits
    // for its retract: its absolute bound must start at the actual position.
    const run = activeProbeCycle
    if (run !== null && run.controller === ctrl && MOVING_STATES.has(ctrl.machineState())) {
      return waitForProbePositioningIdle(ctrl).then((settled) => (
        // The Stop race can release the active lock before this wait wakes.
        // Its owning run still forbids the delayed touch after that release.
        settled && !run.stopped ? sendProbeTouchLine(line, ctrl) : null
      ))
    }
    return sendProbeTouchLine(line, ctrl)
  }
  if (PROBE_MOVE_LINE.test(line) && probeInputBlocksMove(ctrl, `the line "${line}"`)) return null
  return sendAppCommandAwait(line, ctrl)
}

async function sendProbeTouchLine(line: string, ctrl: MachineController): Promise<AppCommandOutcome | null> {
  const run = activeProbeCycle
  const receipt = captureBackendReceipt(ctrl)
  // All production touch lines are incremental mm. Capture the bound after
  // positioning/retract has settled, including LinuxCNC's rotated XY frame.
  const from = ctrl.status().machinePos
  const words = new Map(Array.from(line.matchAll(/([XYZ])\s*([+-]?(?:\d+\.?\d*|\.\d+))/gi), m => [m[1].toUpperCase(), Number(m[2])]))
  const turn = controllerWorkRotation(ctrl, ctrl.status())
  const xy = rotateXY(turn, words.get('X') ?? 0, words.get('Y') ?? 0)
  const delta = { x: xy.x, y: xy.y, z: words.get('Z') ?? 0 }
  const target = from ? { x: from.x + delta.x, y: from.y + delta.y, z: from.z + delta.z } : null
  let replay = line
  while (!probeCycleStopped() && receiptIsCurrent(receipt) && !estopNeedsReset()) {
    await run?.cancelMotion
    await waitOutProbeCycleHold(ctrl)
    if (probeCycleStopped() || !receiptIsCurrent(receipt) || estopNeedsReset()) return null
    if (!openProbeTouch(ctrl, `the line "${replay}"`)) return null
    const epoch = run?.pauseEpoch
    const pending = sendAppCommandAwait(replay, ctrl)
    if (pending === null) { closeProbeTouch(ctrl, false); return null }
    const outcome = await untilProbeStop(pending)
    const touched = outcome?.ok === true && store().probe?.success === true
    closeProbeTouch(ctrl, touched)
    // A real contact wins a simultaneous Pause. A cancelled seek stays on
    // this step until Resume, with exactly the remaining travel to its bound.
    if (touched || run?.pauseEpoch === epoch || probeCycleStopped()) return outcome
    await run?.cancelMotion
    await waitOutProbeCycleHold(ctrl)
    const now = ctrl.status().machinePos
    if (probeCycleStopped() || !receiptIsCurrent(receipt) || estopNeedsReset()) return null
    if (!target || !now) return outcome
    const remaining = { x: target.x - now.x, y: target.y - now.y, z: target.z - now.z }
    const along = remaining.x * delta.x + remaining.y * delta.y + remaining.z * delta.z
    if (along <= 0) {
      // The original seek was sent and reached its bound; no replay is sent.
      // G38.3 retains its existing quiet guarded-arrival meaning.
      const guarded = /\bG38\.3(?!\d)/i.test(line)
      return { ok: guarded, sent: true, translated: null, modal: null,
        message: guarded ? null : 'The probe reached the end of its travel without touching off.' }
    }
    const n = (v: number) => Number(v.toFixed(4))
    const axes = words.has('X') || words.has('Y') ? machineStepXYWords(turn, remaining.x, remaining.y, n) : ''
    // Axis fragments here are G-code wire words, never position sentences.
    const z = words.has('Z') ? ' Z' + n(remaining.z) : ''
    replay = `G21 G91 ${PROBE_TOUCH_LINE.exec(line)![0]} ${axes}${z} ${/\bF\s*[\d.]+/i.exec(line)?.[0] ?? ''}`.trim()
  }
  return null
}

/** WO-2517: the controller's probe call, as a touch the input may end. */
async function probeCallAsTouch(
  ctrl: MachineController,
  axis: ProbeAxis,
  targetMm: number,
  feedMmMin: number,
): Promise<Awaited<ReturnType<MachineController['probe']>> | null> {
  const run = activeProbeCycle
  const receipt = captureBackendReceipt(ctrl)
  while (!probeCycleStopped() && receiptIsCurrent(receipt) && !estopNeedsReset()) {
    await waitOutProbeCycleHold(ctrl)
    await run?.cancelMotion
    if (probeCycleStopped() || !receiptIsCurrent(receipt) || estopNeedsReset()) return null
    if (!openProbeTouch(ctrl, `the probe move toward ${machinePositionText({ [axis.toLowerCase()]: targetMm })}`)) return null
    const epoch = run?.pauseEpoch
    try {
      const touch = await untilProbeStop(ctrl.probe(axis, targetMm, feedMmMin))
      closeProbeTouch(ctrl, touch !== null && touch.ok && touch.at !== null)
      // A successful contact wins a simultaneous Pause; hold before the next
      // move. A cancelled seek repeats toward the SAME endpoint, never farther.
      if (touch?.ok || run?.pauseEpoch === epoch || probeCycleStopped()) return touch
    } catch (error) {
      closeProbeTouch(ctrl, false)
      if (run?.pauseEpoch === epoch) throw error
    }
  }
  return null
}

/** The controller's probe call inside a cycle: not made once Stop/Reset ended
 *  the cycle, and null if the Stop lands while it runs. WO-2138: held between
 *  moves, the call waits for CYCLE START. WO-2517: not made, as stopped, when
 *  the probe input is already ON. */
function probeCallUnlessStopped(
  ctrl: MachineController,
  axis: ProbeAxis,
  targetMm: number,
  feedMmMin: number,
): Promise<Awaited<ReturnType<MachineController['probe']>> | null> {
  if (probeCycleStopped()) return Promise.resolve(null)
  if (probeCycleHeldByOperator(ctrl)) {
    return waitOutProbeCycleHold(ctrl).then(() => {
      if (probeCycleStopped()) return null
      // The E-STOP pressed while it waited: nothing is sent.
      if (estopNeedsReset()) return { ok: false, at: null, reason: ESTOP_BLOCKS_MOTION }
      return probeCallAsTouch(ctrl, axis, targetMm, feedMmMin)
    })
  }
  return probeCallAsTouch(ctrl, axis, targetMm, feedMmMin)
}

// ---- WO-2106: a guarded move that reaches its target is not a miss ----
//
// Rehearsal 2026-09-27 (native kit): "[bridge] probe on Z toward 38.78 found no
// contact: the machine came to rest ..." after every descent to probing depth.
// On the native route a GUARDED move (the descent to depth, a guarded line, the
// setter approach) is the controller's probe call, because that is the move
// that stops on contact - but reaching its target without one is the plan, the
// text route's G38.3 (UCCNC and LinuxCNC end a G38.3 quietly at its target).
// The bridge cannot tell a guarded move from a probe that must touch, so it
// prints its miss line for both. The session can: the line about a guarded
// call's own axis and target is held until the call is judged. Arriving at the
// target drops it; any other ending prints it word for word. A probe that must
// touch is not a guarded call and its miss prints exactly as before.

/** Group 1 the axis, group 2 the target, as Machine.cs ProbeCore writes them. */
const BRIDGE_PROBE_CAME_TO_REST = /^\[bridge\] probe on ([A-Za-z]) toward (\S+) found no contact: the machine came to rest /

interface GuardedProbeCall {
  readonly controller: MachineController
  readonly axis: string
  readonly target: string | null
  readonly held: ConsoleEntry[]
}
let guardedProbeCalls: GuardedProbeCall[] = []

/** True when `entry` is the bridge's miss line about a guarded call in flight:
 *  the call keeps it to be judged. */
function holdGuardedProbeMiss(target: MachineController | null, entry: ConsoleEntry): boolean {
  if (entry.dir !== 'rx' || target === null) return false
  const said = BRIDGE_PROBE_CAME_TO_REST.exec(entry.text)
  if (said === null) return false
  const call = guardedProbeCalls.find((pending) => pending.controller === target
    && pending.axis === said[1].toUpperCase()
    && pending.target !== null && pending.target === moveNumber(said[2]))
  if (call === undefined) return false
  call.held.push(entry)
  return true
}

/** A guarded move's probe call. `arrived` settles the held miss line: dropped
 *  when the move reached its target without contact, printed otherwise. */
async function guardedProbeCallUnlessStopped(
  ctrl: MachineController,
  axis: ProbeAxis,
  targetMm: number,
  feedMmMin: number,
): Promise<{ touch: Awaited<ReturnType<MachineController['probe']>> | null; settle: (arrived: boolean) => void }> {
  const call: GuardedProbeCall = { controller: ctrl, axis: axis.toUpperCase(), target: moveNumber(targetMm), held: [] }
  guardedProbeCalls.push(call)
  const settle = (arrived: boolean) => {
    const lines = call.held.splice(0)
    if (arrived) return
    for (const line of lines) store().pushConsole(line.dir, line.text, line.severity)
  }
  try {
    const touch = await probeCallUnlessStopped(ctrl, axis, targetMm, feedMmMin)
    // Only a reply that ran and touched nothing can be a guarded move arriving.
    if (touch === null || touch.reason || (touch.ok && touch.at !== null)) settle(false)
    return { touch, settle }
  } finally {
    guardedProbeCalls = guardedProbeCalls.filter((pending) => pending !== call)
  }
}

/** The one console line and result sentence for a stopped run. */
function probeCycleStoppedMessage(run: ProbeCycleRun): string {
  const where = run.step !== null
    ? run.phase !== null ? `${run.step} (${run.phase})` : run.step
    : run.phase ?? 'its start'
  const contact = run.contact
  // WO-2517: the probe input ended it - where it touched, and what was stopped or not sent.
  const at = contact?.at ? machinePositionText(contact.at) : 'an unreported machine position'
  // WO-2533: and where the stopped move came to rest, once that was read.
  const rest = contact?.rest ? machinePositionText(contact.rest) : null
  const stoppedMove = contact?.move ? ` - ${contact.move}` : ''
  const touched = rest === null
    ? `the probe touched at ${at} during ${where}${stoppedMove}.`
    : rest === at
      ? `the probe touched during ${where}${stoppedMove} - stopped at ${at}, where it touched.`
      : `the probe touched during ${where}${stoppedMove} - stopped at ${rest}. It touched at ${at}.`
  // WO-2664 (the operator 10-07 8:06 PM: "We should only say what the problem is"):
  // already touching says where, and the move it was not sent - never the
  // positioning step's own label ("during Cross over for Descend to ...").
  const crossing = run.step?.replace(/^Cross over for /, '') ?? null
  const unsentMove = contact?.move
    ? crossing !== null && /^Descend to probing depth/.test(crossing)
      ? ` before the move to probing depth, so that move was not sent`
      : ` during ${where}, before ${contact.move}, so that move was not sent`
    : ` during ${where}`
  const message = run.cancelFailure ?? (contact === null
    ? `${run.routine}: stopped by ${run.stopSource} during ${where}. No further probe or move was sent.`
    : contact.kind === 'touched'
      ? `${run.routine}: ${touched} No further probe or move was sent.`
      : `${run.routine}: the probe was already touching at ${at}${unsentMove}. No further probe or move was sent.`)
  if (!run.reported) {
    run.reported = true
    store().pushConsole('rx', message, contact === null && run.cancelFailure === null ? 'info' : 'error')
  }
  return message
}

/** WO-2533: the stopped run's line, once a move the probe stopped has come to
 *  rest - so it can say where. Stop/Reset's line is not held back. */
async function probeCycleStoppedMessageAtRest(run: ProbeCycleRun): Promise<string> {
  // A positioning wait can end before controlled cancellation has answered.
  // Its failure must win the stopped sentence just as it does for a seek.
  await run.cancelMotion
  if (run.contactRest !== null) await run.contactRest
  return probeCycleStoppedMessage(run)
}

/** WO-1672: the machine Z of the last fine-pass tool measurement, held as the
 *  active tool length (datum) when probed with whatever is in the collet. */
let activeToolLengthDatumValue: number | null = null

export function activeToolLengthDatum(): number | null {
  return activeToolLengthDatumValue
}

export function setActiveToolLengthDatum(datum: number | null): void {
  activeToolLengthDatumValue = datum
}

/** True while any directional probe touch is between its first and last command. */
export function isProbeCycleActive(): boolean {
  return probeCycleActive
}

interface DirectionalProbeOptions {
  afterContact?: (
    /** WO-2071: null (or a null outcome) once Stop/Reset ended the cycle. */
    send: (line: string) => Promise<AppCommandOutcome | null> | null,
    round: (value: number) => number,
    /** Machine coordinate of the fine-pass contact on the probed axis. */
    contact: number,
  ) => Promise<string | null>
  successMessage?: (position: number) => string
  /** Feature-aware cycles own the outer lock and modal restore. */
  cycleOwned?: boolean
  /** WO-2021 audit: a cycle-owned touch whose positioning moves were each
   *  waited to Idle (the surface mesh cycle), so the reported machine Z is
   *  where the touch starts and the Z floor can be applied on the text route. */
  startSettled?: boolean
  /** Feature-aware expected-surface search, always <= configured maxTravel. */
  travelMm?: number
  /** WO-1798: the work-Z search resolved from this machine's stated bottom
   *  and explicit operator override. No other directional route may use it. */
  partZSearch?: PartProbeSearchPlan
  /** WO-1546, WO-1613: the tool setter measure, worked out by
   *  planToolSetterMeasure from the setter routine's inputs - where the tool
   *  crosses, the setter, the guarded approach, the search floor and the
   *  routine's own speeds and distances. WO-2021: every route runs it - the
   *  native probe call, and G53/G38.2 lines on a controller that takes text. */
  toolSetter?: ToolSetterPlan
  /** WO-1673: the name this probe is known by in the operator's row when it
   *  ends without contact ("Probe work Z0", "Measure tool", "Probe X+").
   *  Defaults to `Probe <axis><direction>`. */
  probeLabel?: string
  /** WO-2061: a Z touch that ends higher than its final back-off - the
   *  machine Z it rises to afterwards, worked out from the fine contact.
   *  Probe work Z0 ends at top + clearance. Ignored when not above the back-off. */
  endMachineZ?: (contact: number) => number
  /** WO-2061: what the operator is told when that rise stops - the touch's
   *  own result (Z0 already written) comes first. */
  endRiseFailure?: (contact: number, reason: string) => string
  /** WO-2108: what the operator is told when the search ends at its distance
   *  without contact - in place of the probe-wiring advice. The feature
   *  cycle's top touch says no top was found within that distance. */
  searchMissMessage?: (searchMm: number) => string
  /** WO-2258: when the search ends at its distance without contact, Z goes
   *  back up to the machine Z the search started from before the miss is
   *  reported, and the sentence says where Z is now. The feature cycle's top
   *  touch only (real board 2026-09-30: left 9.4 mm down inside a hole). */
  riseToStartOnMiss?: boolean
  /** WO-2664: a feature routine sensed with the probe touching the part (no
   *  plate). A fine-pass miss says only what happened - no pad advice. */
  sensedByPart?: boolean
}

/** WO-2258: what a top-search miss adds once the rise back to the start has
 *  run (`failure` null) or stopped - where Z is now, read from the controller. */
function missRiseSentence(ctrl: MachineController, startZ: number, failure: string | null): string {
  const nowZ = ctrl.status().machinePos?.z
  const now = typeof nowZ === 'number' && Number.isFinite(nowZ)
    ? machinePositionText({ z: Number(nowZ.toFixed(4)) })
    : 'an unreported machine Z'
  return failure === null
    ? `Z went back up to where the search started: ${now}.`
    : `Going back up to ${machinePositionText({ z: startZ })} stopped: ${failure} - Z was left at ${now}.`
}

// ---------------------------------------------------------------------------
// WO-1546 - PROBING RUNS THROUGH THE CONTROLLER'S NATIVE PROBE
// ---------------------------------------------------------------------------
//
// WO-1545 slice 2. A controller that takes geometry instead of text (UCCNC)
// has a probe CALL: `probe(axis, targetMm, feedMmMin)`, where the target is an
// ABSOLUTE machine coordinate and the reply carries the contact point. It has
// no built-in retract, so every retract and approach is a typed machine move
// that is waited on until the board reports idle at its target. The G38.2
// lines stay the route for a controller that takes text (GRBL, the simulator).
//
// A probe that RAN and found nothing is "no contact within N mm"; a probe call
// that did not run is reported as the refusal it was, naming the command.
// The bridge's probe-CYCLE-active flag is `status.probeCycle`, and nothing
// here reads it. `status.inputs.probe` is the pin (WO-1632): WO-2517 watches
// it for the whole of a cycle, and the probe call is the one move it may end.
// ---------------------------------------------------------------------------

/** True when probing on this controller runs through its native probe call. */
function nativeProbeRoute(ctrl: MachineController): boolean {
  return !ctrl.capabilities.gcodeText && typeof ctrl.probe === 'function'
}

/**
 * WO-2021 audit: whether the dialect the session machine declares has G38.3,
 * the probe move that stops on contact and ends quietly at its target without
 * it - the only text line that can run the tool setter's guarded approach.
 */
function textSetterApproachWordStated(): boolean {
  const machine = controlMachine(useCamStore.getState())
  const dialect = gcodeTableDialectOf(machine.controller)
  return dialect !== null && gcodeWordEntry(gcodeWordTableForMachine(gcodeWordTable(dialect), machine), 'G', 38.3) !== null
}

/**
 * WO-2021 (09-25 simulator rehearsal: a measure searched 100 mm down from where
 * the tool stood and ended at machine Z -36.48, below Z min 0): the machine Z a
 * downward Z search may not pass. The setter plan's floor, the work-zero
 * search's stated bottom, else the bottom the machine definition states. Null
 * on any other axis or direction, or when no bottom is stated. `positionKnown`
 * is false for a text-route touch inside a feature cycle that did not wait its
 * positioning to Idle: those lines are queued, not arrived, so the reported Z
 * is not where it starts. The surface mesh cycle waits, so its touches are known.
 */
function probeSearchZFloor(
  axis: ProbeAxis,
  direction: ProbeDirection,
  options: DirectionalProbeOptions,
  positionKnown: boolean,
): number | null {
  if (axis !== 'Z' || direction !== '-') return null
  if (options.toolSetter) return options.toolSetter.searchFloorZ
  if (options.partZSearch) return options.partZSearch.bottomMachineZ
  return positionKnown ? partProbeMachineBottom(controlMachine(useCamStore.getState())) : null
}

/** A downward target rounded to the command's four decimals, never below the floor. */
function downTargetAboveFloor(
  requested: number,
  floor: number | null,
  partZSearch: PartProbeSearchPlan | undefined,
): number {
  if (partZSearch) return partProbeTargetAtOrAboveBottom(requested, partZSearch.bottomMachineZ)
  const target = Number(requested.toFixed(4))
  return floor === null ? target : Math.max(target, floor)
}

/** WO-2020: the bridge's post-contact failures already state what happened and
 * what the operator must do. Preserve that sentence at every native-probe
 * phase; wrappers describing a refused or unstarted probe are only true before
 * contact. Machine.cs owns this prefix and emits it for stop, alarm, feed hold,
 * and probe-cycle timeout after GetProbeState reported a touch. */
function nativeProbeFailureMessage(reason: string, beforeContact: string): string {
  return reason.startsWith('the probe touched ') ? reason : `${beforeContact}: ${reason}`
}

/**
 * The fixed tool setter's machine position, from the app-owned machine
 * definition fact. A present but partial fact stays incomplete: it never
 * borrows missing coordinates from a controller profile alias. UCCNC's
 * Probing.FixedProbePos tuple is decoded only by the profile importer; this
 * production reader is controller-neutral. Null when the fact is absent,
 * incomplete or non-finite.
 */
export function fixedToolSetterPosition(machine: MachineConfig | null | undefined): MachineVec3 | null {
  const stated = machine?.probing?.toolSetter
  if (stated === undefined || stated === null) return null
  const { x, y, z } = stated
  return typeof x === 'number' && Number.isFinite(x)
    && typeof y === 'number' && Number.isFinite(y)
    && typeof z === 'number' && Number.isFinite(z)
    ? { x, y, z }
    : null
}

/** How far below the top of Z travel a setter crossing runs, so the move
 *  never ends on the soft limit itself. */
const SETTER_CROSSING_BELOW_Z_TOP_MM = 1

/** WO-1613 (Operator 2026-09-16): the approach clearance above the expected touch. */
const SETTER_APPROACH_CLEARANCE_MM = 5

/**
 * WO-1613: the defaults the machine definition and the probe profile give the
 * factory tool setter routine - the setter X/Y (the app-owned machine fact), the
 * crossing height (top of Z travel less 1 mm, never below the setter's Z), the
 * search depth (the whole Z travel), and the profile's speeds and retract. The
 * approach speed defaults to the FAST PROBE speed (Operator's ruling); the fine
 * search to twice the retract, the distance WO-1546's fine pass searched.
 */
export function toolSetterDefaultsForMachine(
  machine: MachineConfig | null | undefined,
  config: ZProbeConfig,
): Partial<ToolSetterDefaults> {
  const effective = resolveProbeConfig(null, config)
  const defaults: Partial<ToolSetterDefaults> = {
    clearanceMm: SETTER_APPROACH_CLEARANCE_MM,
    approachFeed: effective.fastFeed,
    fastFeed: effective.fastFeed,
    fineFeed: effective.slowFeed,
    retractMm: effective.retract,
    fineSearchMm: effective.retract * 2,
  }
  const setter = fixedToolSetterPosition(machine)
  if (setter) {
    defaults.setterX = setter.x
    defaults.setterY = setter.y
  }
  const zTop = definitionMachineZMax(machine)
  const zMin = definitionMachineZMin(machine)
  if (zTop !== null) {
    defaults.crossingZ = setter ? Math.max(setter.z, zTop - SETTER_CROSSING_BELOW_Z_TOP_MM) : zTop - SETTER_CROSSING_BELOW_Z_TOP_MM
    if (zMin !== null) defaults.maxSearchMm = zTop - zMin
  }
  return defaults
}

/**
 * The tool setter routine a measure runs with: the one given, else the
 * preferred one in the library (a user copy before the factory). The factory
 * routine takes its defaults from this machine's definition, and needs the
 * definition to name a setter - without one it is null, and a measure touches
 * down where the tool stands, as it always has. A user copy carries its own
 * setter position and runs wherever the definition is silent.
 */
export function toolSetterRoutineToRun(
  machine: MachineConfig | null | undefined,
  config: ZProbeConfig,
  choice?: ProbeRoutine | null,
): ProbeRoutine | null {
  const routine = choice ?? preferredToolSetterRoutine(useProbeRoutineStore.getState())
  if (routine.provenance.kind === 'factory') {
    const defaults = toolSetterDefaultsForMachine(machine, config)
    if (defaults.setterX === undefined || defaults.crossingZ === undefined) return null
    return toolSetterRoutineForMachine(routine, defaults)
  }
  return routine
}

/**
 * Plan a tool setter measure against the live session: where the tool stands,
 * the definition's bottom of Z travel, the machine's X/Y/Z travel, and the active tool's recorded setter
 * touch from the tool table (the known length the approach descends toward).
 */
export function planToolSetterForSession(
  routine: ProbeRoutine,
  config: ZProbeConfig,
): ReturnType<typeof planToolSetterMeasure> {
  return planToolSetterMeasure(routine, {}, toolSetterPlanContext(config))
}

/** The live facts a tool setter plan reads (the Routines tab previews with the same). */
export function toolSetterPlanContext(config: ZProbeConfig): ToolSetterPlanContext {
  const machine = controlMachine(useCamStore.getState())
  const tool = store().activeTool
  const entry = tool === null || tool === undefined
    ? undefined
    : findTool(useMachineToolTable.getState().tableFor(controlMachineId()), tool)
  const startZ = getMachineController().status().machinePos?.z
  return {
    startZ: typeof startZ === 'number' && Number.isFinite(startZ) ? startZ : null,
    zMinMm: definitionMachineZMin(machine),
    envelope: currentResolvedMachineMotion().envelope,
    expectedContactZ: entry?.probedMachineZ ?? null,
    tool: tool ?? null,
    positioningFeedMmMin: setterTravelFeed(resolveProbeConfig(null, config).positioningFeed),
  }
}

/**
 * WO-2017 (Operator 2026-09-25: "when it moved over to the tool setter it went
 * exceedingly slow"): the setter trip's lift to the crossing height and its XY
 * crossing run at the machine's rapid rate - the same number a park move or a
 * G0 runs at - not the probe positioning feed. Only a machine that declares no
 * rapid rate keeps the positioning feed, as every measure did before.
 */
function setterTravelFeed(positioningFeed: number): number {
  const rapid = controlMachine(useCamStore.getState()).rapidRate
  return typeof rapid === 'number' && Number.isFinite(rapid) && rapid > 0 ? rapid : positioningFeed
}

/** The top of the machine's Z travel from its definition, or null. */
function definitionMachineZMax(machine: MachineConfig | null | undefined): number | null {
  const z = machine?.controllerDefinition?.axes.find((axis) => axis.axis === 'Z')
  return z && Number.isFinite(z.softLimitMax) ? z.softLimitMax : null
}

/** The bottom of the machine's Z travel from its definition, or null. */
function definitionMachineZMin(machine: MachineConfig | null | undefined): number | null {
  const z = machine?.controllerDefinition?.axes.find((axis) => axis.axis === 'Z')
  return z && Number.isFinite(z.softLimitMin) ? z.softLimitMin : null
}

/** Long enough for the move at its feed, with room for acceleration and the
 *  status frames that confirm it settled. */
function nativeMoveTimeoutMs(distanceMm: number, feedMmMin: number): number {
  const travelMs = feedMmMin > 0 ? (distanceMm / feedMmMin) * 60_000 : 0
  return Math.max(PROBE_ROUTINE_MOVE_TIMEOUT_MS, travelMs * 1.5 + 10_000)
}

/**
 * One typed machine-coordinate move for a probe cycle, waited on until the
 * board is idle at the target. Z alone goes by `jogToMachineZ`; X/Y go by
 * `jogToWorkXY` through the frame the controller reports. A move naming both
 * lifts first when it rises and lowers last when it descends, so the tool
 * never crosses XY below where it started or ended. Null on success,
 * otherwise what did not happen.
 */
async function nativeProbeMachineMove(
  ctrl: MachineController,
  target: Partial<MachineVec3>,
  feedMmMin: number,
): Promise<string | null> {
  const round = (value: number) => Number(value.toFixed(4))
  const moveZ = async (z: number): Promise<string | null> => {
    // WO-2138: a Feed Hold between the moves holds this one until CYCLE START.
    if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
    const from = ctrl.status().machinePos?.z
    if (estopNeedsReset()) return ESTOP_BLOCKS_MOTION
    if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
    // WO-2517: not with the probe input ON, unless it backs off a touch.
    if (probeInputBlocksMove(ctrl, probeCycleMoveText({ z: round(z) }))) return PROBE_CYCLE_STOPPED
    if (!ctrl.jogToMachineZ(round(z), feedMmMin)) return `the controller refused the move to ${machinePositionText({ z: round(z) })}`
    const distance = typeof from === 'number' ? Math.abs(z - from) : 0
    return (await waitForProbeRoutineMove(ctrl, { z: round(z) }, nativeMoveTimeoutMs(distance, feedMmMin)))
      ? null
      : `the move to ${machinePositionText({ z: round(z) })} did not settle idle at its target`
  }
  const moveXY = async (x: number | undefined, y: number | undefined): Promise<string | null> => {
    if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
    const status = ctrl.status()
    const { machinePos, workPos } = status
    if (machinePos === null || workPos === null) {
      return 'the controller has not reported both machine and work position, so a machine XY target cannot be sent as its work-frame move'
    }
    const tx = round(x ?? machinePos.x)
    const ty = round(y ?? machinePos.y)
    if (estopNeedsReset()) return ESTOP_BLOCKS_MOTION
    if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
    // WO-2203: a machine target, whatever the work rotation.
    const work = workXYForMachineXY(status, tx, ty, round)
    // WO-2517 (real board 10-03, F1): this move pushed the block 15 mm with
    // the probe ON. It is not sent ON, and every frame of it is watched.
    if (probeInputBlocksMove(ctrl, probeCycleMoveText({ x: tx, y: ty }))) return PROBE_CYCLE_STOPPED
    if (!ctrl.jogToWorkXY(work.x, work.y, feedMmMin)) {
      return `the controller refused the move to ${machinePositionText({ x: tx, y: ty })}`
    }
    const distance = Math.hypot(tx - machinePos.x, ty - machinePos.y)
    return (await waitForProbeRoutineMove(ctrl, { x: tx, y: ty }, nativeMoveTimeoutMs(distance, feedMmMin)))
      ? null
      : `the move to ${machinePositionText({ x: tx, y: ty })} did not settle idle at its target`
  }
  const hasXY = target.x !== undefined || target.y !== undefined
  if (!hasXY) return target.z === undefined ? null : moveZ(target.z)
  if (target.z === undefined) return moveXY(target.x, target.y)
  const startZ = ctrl.status().machinePos?.z
  if (typeof startZ !== 'number') return 'the controller has not reported its machine Z position'
  if (target.z > startZ) {
    const up = await moveZ(target.z)
    if (up) return up
    return moveXY(target.x, target.y)
  }
  const across = await moveXY(target.x, target.y)
  if (across) return across
  return moveZ(target.z)
}

/**
 * WO-1673: A PROBE THAT ENDED WITHOUT CONTACT PRINTS ONE ROW OF THE APP'S OWN.
 *
 * On the board 2026-09-17 the only record of a deliberate miss was the bridge's
 * own console frame ("[bridge] probe on Z toward 78.9 found no contact...");
 * the app said nothing, so the operator had no row naming the probe or where it
 * came to rest. This is that row - CONSOLE ONLY, no notice and no banner. The
 * end position is the machine's on the axis that was probed, stated in both
 * frames through WO-1667's one formatter ("G54 Z -31.1 (machine Z 78.9)").
 */
function noteProbeEndedWithoutContact(
  ctrl: MachineController,
  axis: ProbeAxis,
  direction: ProbeDirection,
  options: DirectionalProbeOptions,
): void {
  const machinePos = ctrl.status().machinePos
  const key = axis.toLowerCase() as keyof MachineVec3
  const end = machinePos?.[key]
  const at = typeof end === 'number' && Number.isFinite(end)
    ? machinePositionText({ [key]: end })
    : machinePos ? machinePositionText(machinePos) : 'an unreported machine position'
  const label = options.probeLabel ?? `Probe ${axis}${direction}`
  store().pushConsole('rx', `${label}: no contact - ended at ${at}.`, 'info')
}

/**
 * WO-2258: on a controller that takes text, the rise back to where a top
 * search started once it ended without contact. GRBL (and the simulator)
 * alarm on that miss with the position kept (ALARM:4/5); `$X` is its way out,
 * so the unlock goes first and the rise waits until the controller reports it
 * left the alarm. Null once Z is idle at the start; otherwise why it stopped -
 * nothing more is sent after a Stop, the E-STOP or a refused line.
 */
async function riseToStartAfterTextMiss(
  ctrl: MachineController,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
  startZ: number,
  feedMmMin: number,
): Promise<string | null> {
  const changed = 'the machine connection changed'
  if (estopNeedsReset()) return ESTOP_BLOCKS_MOTION
  if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
  if (ctrl.machineState() === 'alarm') {
    if (!ctrl.unlock()) return 'the controller did not take the unlock ($X)'
    // GRBL reports the unlock on its next status frame, not on the line.
    for (let waited = 0; ctrl.machineState() === 'alarm'; waited += 50) {
      if (waited >= 5_000) return 'the controller stayed in alarm after the unlock ($X)'
      ctrl.queryStatus()
      await new Promise((resolve) => setTimeout(resolve, 50))
      if (!receiptIsCurrent(receiptToken)) return changed
      if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
      if (estopNeedsReset()) return ESTOP_BLOCKS_MOTION
    }
  }
  const from = ctrl.status().machinePos?.z
  const up = await probeCycleSend(`G21 G90 G53 G0 Z${startZ}`, ctrl)
  if (!receiptIsCurrent(receiptToken)) return changed
  if (!up) return probeCycleStopped() ? PROBE_CYCLE_STOPPED : 'the controller refused the move'
  const unsent = unsentReason(up)
  if (unsent) return unsent
  if (!up.ok) return up.message ?? 'the controller refused the move'
  const distance = typeof from === 'number' ? Math.abs(startZ - from) : 0
  if (await waitForProbeRoutineMove(ctrl, { z: startZ }, nativeMoveTimeoutMs(distance, feedMmMin))) return null
  if (!receiptIsCurrent(receiptToken)) return changed
  if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
  return `the move to ${machinePositionText({ z: startZ })} did not settle idle at its target`
}

/** The two-pass touch through the controller's native probe call. */
async function executeNativeProbeTouch(
  ctrl: MachineController,
  axis: ProbeAxis,
  direction: ProbeDirection,
  effective: ReturnType<typeof resolveProbeConfig>,
  travelMm: number,
  options: DirectionalProbeOptions,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
): Promise<DirectionalProbeResult> {
  const fail = (message: string): DirectionalProbeResult => ({ ok: false, message, probedMachinePosition: null })
  const changed = 'The machine connection changed during the probe cycle.'
  const n = (value: number) => Number(value.toFixed(4))
  const key = axis.toLowerCase() as keyof MachineVec3
  const sign = direction === '-' ? -1 : 1
  const positioningFeed = n(effective.positioningFeed)

  // WO-1613: a setter measure runs on the routine's own speeds and distances;
  // every other native touch keeps the profile's.
  const setter = options.toolSetter
  const zFloor = probeSearchZFloor(axis, direction, options, true)
  const fastFeed = n(setter ? setter.values.fastFeed : effective.fastFeed)
  const fineFeed = n(setter ? setter.values.fineFeed : effective.slowFeed)
  const retract = setter ? setter.values.retractMm : effective.retract
  const fineSearch = setter ? setter.values.fineSearchMm : effective.retract * 2
  /** Set when the guarded approach touched the setter early: that touch is the fast pass. */
  let approachContact: MachineVec3 | null = null
  let earlyTouchNote: string | null = null
  let earlyTouchSummary = ''

  // WO-2017: the lift and the crossing are travel above everything, at the
  // plan's crossing feed (the machine's rapid rate); the descent stays a probe.
  const travelFeed = setter ? n(setter.positioningFeedMmMin) : positioningFeed

  if (setter) {
    noteProbePhase('the move to the tool setter')
    const nowZ = ctrl.status().machinePos?.z
    const lift = typeof nowZ === 'number' && setter.crossingZ > nowZ
      ? await nativeProbeMachineMove(ctrl, { z: setter.crossingZ }, travelFeed)
      : null
    if (!receiptIsCurrent(receiptToken)) return fail(changed)
    if (lift) return fail(`Raising Z before moving to the tool setter stopped: ${lift} - the probe was not started.`)
    // At or above the crossing height, so this crosses XY where the tool is.
    const across = await nativeProbeMachineMove(ctrl, { x: setter.setter.x, y: setter.setter.y }, travelFeed)
    if (!receiptIsCurrent(receiptToken)) return fail(changed)
    if (across) return fail(`Moving to the tool setter stopped: ${across} - the probe was not started.`)
    if (setter.approach) {
      // Operator 2026-09-16: a wrong tool table length must not drive the tool into
      // the setter. The descent is a PROBE move - it stops on contact at any
      // speed the routine asks for - never an unguarded move.
      const approach = setter.approach
      const fromZ = ctrl.status().machinePos?.z
      if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
      noteProbePhase('the approach toward the tool setter')
      const { touch: guarded, settle } = await guardedProbeCallUnlessStopped(ctrl, 'Z', n(approach.targetZ), n(approach.feedMmMin))
      if (!receiptIsCurrent(receiptToken)) { settle(false); return fail(changed) }
      if (guarded === null) return fail(PROBE_CYCLE_STOPPED)
      if (guarded.reason) return fail(nativeProbeFailureMessage(guarded.reason, 'The approach toward the tool setter did not run'))
      if (guarded.ok && guarded.at !== null) {
        approachContact = { ...guarded.at }
        const tool = setter.tool === null ? 'the active tool' : `T${setter.tool}`
        const above = n(approachContact.z - approach.expectedContactZ)
        earlyTouchNote = `The setter triggered early, at ${machinePositionText({ z: approachContact.z })} - ${machineLengthText(above)} above where `
          + `${tool}'s tool table length put it (${machinePositionText({ z: approach.expectedContactZ })}). The approach stopped there. `
          + `A ${machineLengthText(retract)} retract was requested.`
        earlyTouchSummary = `Setter triggered early at ${machinePositionText({ z: approachContact.z })}, ${machineLengthText(above)} above `
          + `${tool}'s table length prediction (${machinePositionText({ z: approach.expectedContactZ })}); approach stopped and tool retracted ${machineLengthText(retract)}`
      } else {
        const distance = typeof fromZ === 'number' ? Math.abs(fromZ - approach.targetZ) : 0
        const arrived = await waitForProbeRoutineMove(ctrl, { z: n(approach.targetZ) }, nativeMoveTimeoutMs(distance, approach.feedMmMin))
        settle(arrived)
        if (!receiptIsCurrent(receiptToken)) return fail(changed)
        if (!arrived) {
          return fail(`The approach toward the tool setter did not settle at ${machinePositionText({ z: n(approach.targetZ) })} - the probe was not started.`)
        }
      }
    }
  }

  const start = ctrl.status().machinePos?.[key]
  if (typeof start !== 'number' || !Number.isFinite(start)) {
    return fail(`The controller has not reported its machine ${axis} position, which the probe target is measured from - nothing was sent.`)
  }
  let fastAt: MachineVec3
  if (approachContact) {
    fastAt = approachContact
  } else {
    const requestedFastTarget = setter
      ? setter.searchFloorZ
      : options.partZSearch?.targetMachineZ ?? start + sign * travelMm
    const fastTarget = setter ? n(requestedFastTarget) : downTargetAboveFloor(requestedFastTarget, zFloor, options.partZSearch)
    const searchMm = n(Math.abs(fastTarget - start))
    if (!(searchMm > 0) || Math.sign(fastTarget - start) !== sign) {
      return fail(`The probe search from machine ${axis} ${machineLengthText(start)} to ${machineLengthText(fastTarget)} does not run ${axis}${direction} - nothing was sent.`)
    }
    if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
    noteProbePhase('the search')
    const fast = await probeCallUnlessStopped(ctrl, axis, fastTarget, fastFeed)
    if (!receiptIsCurrent(receiptToken)) return fail(changed)
    if (fast === null) return fail(PROBE_CYCLE_STOPPED)
    if (fast.reason) return fail(nativeProbeFailureMessage(fast.reason, 'The probe did not run'))
    if (!fast.ok || fast.at === null) {
      noteProbeEndedWithoutContact(ctrl, axis, direction, options)
      if (options.searchMissMessage) {
        const miss = `${options.searchMissMessage(searchMm)} (searched machine ${axis} ${machineLengthText(start)} to ${machineLengthText(fastTarget)}).`
        if (!options.riseToStartOnMiss || axis !== 'Z') return fail(miss)
        // WO-2258: back up to where the search started before anything else
        // can move X/Y; a Stop, E-STOP or fault ends the rise where it is.
        noteProbePhase('the rise back to where the search started')
        const back = await nativeProbeMachineMove(ctrl, { z: n(start) }, positioningFeed)
        if (!receiptIsCurrent(receiptToken)) return fail(changed)
        return fail(`${miss} ${missRiseSentence(ctrl, n(start), back)}`)
      }
      return fail(
        `The probe never made contact within ${machineLengthText(searchMm)} (searched machine ${axis} ${machineLengthText(start)} to ${machineLengthText(fastTarget)}). ` +
          (setter ? 'Nothing was recorded. Check the tool setter wiring and position.'
            : axis === 'Z' ? 'Check the probe wiring and the pad position.'
              : 'Check the probe wiring and the start position.'),
      )
    }
    fastAt = fast.at
  }

  const retracted = n(fastAt[key] - sign * retract)
  noteProbePhase('the retract between passes')
  const away = await nativeProbeMachineMove(ctrl, { [key]: retracted }, positioningFeed)
  if (!receiptIsCurrent(receiptToken)) return fail(changed)
  if (away) return fail(`The retract between probe passes failed: ${away}.`)
  // Operator ruling 10-06 7:20 PM: no warning on an early touch - the success line already says what happened.

  const boundedFineSearch = partProbeFineSearchMm(retracted, fineSearch, zFloor)
  if (!(boundedFineSearch > 0)) {
    return fail('The fine probe pass has no downward travel remaining above the machine Z limit.')
  }
  const requestedFineTarget = retracted + sign * boundedFineSearch
  const fineTarget = downTargetAboveFloor(requestedFineTarget, zFloor, options.partZSearch)
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  noteProbePhase('the fine pass')
  const fine = await probeCallUnlessStopped(ctrl, axis, fineTarget, fineFeed)
  if (!receiptIsCurrent(receiptToken)) return fail(changed)
  if (fine === null) return fail(PROBE_CYCLE_STOPPED)
  if (fine.reason) return fail(nativeProbeFailureMessage(fine.reason, 'The fine probe pass did not run'))
  if (!fine.ok || fine.at === null) {
    return fail((
      // A miss after an early setter touch says the touch came early (machine seat 10-06 a4 finding; operator 10:44 PM: fix it).
      (setter && earlyTouchSummary ? `${earlyTouchSummary}. ` : '') +
      `The fine pass lost contact: no touch within ${machineLengthText(boundedFineSearch)} (machine ${axis} ${machineLengthText(retracted)} to ${machineLengthText(fineTarget)}). ` +
        (setter
          ? `Nothing was recorded. The tool backed off ${machineLengthText(retract)} before the fine pass. Check that the tool setter is seated and held still.`
          : options.sensedByPart ? '' : 'Check that the pad is stable.')).trimEnd(),
    )
  }
  const contact = fine.at[key]

  const afterContactFailure = await options.afterContact?.(
    (line: string) => probeCycleSend(line, ctrl),
    n,
    contact,
  )
  if (!receiptIsCurrent(receiptToken)) return fail(changed)
  if (afterContactFailure) return fail(afterContactFailure)

  noteProbePhase('the retract off the contact')
  const off = await nativeProbeMachineMove(ctrl, { [key]: n(contact - sign * retract) }, positioningFeed)
  if (!receiptIsCurrent(receiptToken)) return fail(changed)
  if (off) return fail(`The final retract off the ${setter ? 'tool setter' : 'pad'} failed: ${off}.`)

  const endZ = axis === 'Z' && options.endMachineZ ? n(options.endMachineZ(contact)) : null
  if (endZ !== null && endZ > n(contact - sign * retract)) {
    noteProbePhase('the rise after the touch')
    const rise = await nativeProbeMachineMove(ctrl, { z: endZ }, positioningFeed)
    if (!receiptIsCurrent(receiptToken)) return fail(changed)
    if (rise) {
      return fail(options.endRiseFailure?.(contact, rise) ?? `Rising to ${machinePositionText({ z: endZ })} after the touch stopped: ${rise}.`)
    }
  }

  if (setter) {
    // WO-2017 (09-26 native rehearsal): the measure used to end 2 mm above the
    // setter, and a resumed program's next rapid crossed the table diagonally
    // from there. Come back up to the crossing height before anything else
    // moves XY - UCCNC's own M6 lifts Z first the same way.
    const endZ = ctrl.status().machinePos?.z
    const up = typeof endZ !== 'number' || setter.crossingZ > endZ
      ? await nativeProbeMachineMove(ctrl, { z: setter.crossingZ }, travelFeed)
      : null
    if (!receiptIsCurrent(receiptToken)) return fail(changed)
    if (up) {
      return fail(
        `The setter touched at ${machinePositionText({ z: contact })}, but raising Z back to the crossing height `
          + `stopped: ${up} - the measurement was not recorded.`,
      )
    }
  }

  const base = options.successMessage?.(contact) ?? `Probe contact at machine ${axis} ${machineLengthText(contact)}.`
  return {
    ok: true,
    message: earlyTouchNote
      ? `${earlyTouchSummary}. The fine touch measured the tool at ${machinePositionText({ z: contact })} and replaces the table's length.`
      : base,
    probedMachinePosition: contact,
    contacts: {
      fastMachinePosition: fastAt[key],
      fineMachinePosition: contact,
    },
  }
}

async function executeDirectionalProbeTouch(
  axis: ProbeAxis,
  direction: ProbeDirection,
  config: ZProbeConfig,
  options: DirectionalProbeOptions = {},
): Promise<DirectionalProbeResult> {
  /** WO-2071: set when this touch holds the probe lock itself (not cycle-owned). */
  let ownRun: ProbeCycleRun | null = null
  // WO-2533: a stopped run says so once the move it stopped has come to rest.
  const fail = (message: string): DirectionalProbeResult | Promise<DirectionalProbeResult> => (ownRun?.stopped
    ? probeCycleStoppedMessageAtRest(ownRun)
      .then((said): DirectionalProbeResult => ({ ok: false, message: said, probedMachinePosition: null, stopped: true }))
    : { ok: false, message, probedMachinePosition: null })

  const cycleOwned = options.cycleOwned === true
  // WO-328: gates BOTH public entry points that share this implementation.
  // WO-372's atomic feature runner owns the same gates once around all steps.
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  const valid = validateZProbeConfig(config)
  if (!valid.ok) return fail(valid.reason)
  const effective = resolveProbeConfig(null, config)
  const travelMm = options.travelMm ?? effective.maxTravel
  const partZSearch = options.partZSearch
  if (options.toolSetter === undefined && (
    !Number.isFinite(travelMm)
    || travelMm <= 0
    || (partZSearch === undefined && travelMm > effective.maxTravel)
  )) {
    return fail(`Probe travel must be greater than zero and no more than ${machineLengthText(effective.maxTravel)}.`)
  }
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  // WO-433: checked BEFORE machineState() - this app's own probeCycleActive
  // flag is the most specific, most actionable reason a concurrent probe call
  // is refused, and it must win regardless of how fast a particular backend's
  // machineState() flips off 'idle'. GrblController (real hardware and the
  // retired GRBL-protocol simulator) only updates its cached state on the
  // NEXT async status report, so the old ordering happened to read 'idle'
  // long enough for this flag to be reached first; the native
  // SimulatedController sets state SYNCHRONOUSLY inside sendCommandAwait, so
  // the generic 'must be idle' gate below could win the race and report a
  // less specific reason for the exact same refusal. Reordering fixes the
  // message for every backend, not only the simulator - discovered live once
  // the simulator's synchronous timing exercised the race for the first time
  // (zProbeRunner.test.ts).
  if (probeCycleActive && !cycleOwned) return fail('A probe cycle is already running.')
  if (ctrl.hasActiveJob()) return fail('A program is running - probing is locked out.')
  // WO-2103: a Feed Hold between a cycle's moves and this touch pauses it here.
  if (cycleOwned) {
    await waitOutProbeCycleHold(ctrl)
    if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED)
    if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  }
  if (ctrl.machineState() !== 'idle') return fail('The machine must be idle to start a probe cycle.')

  const prevUnitsInch = store().parserModal?.units === 'inch'
  const send = (line: string) => probeCycleSend(line, ctrl)
  const n = (value: number) => Number(value.toFixed(4))
  const probeSign = direction === '-' ? '-' : ''
  const retractSign = direction === '-' ? '' : '-'
  // WO-2212: a touch travels along its MACHINE axis. A controller that turns a
  // G91 X Y by the work rotation (LinuxCNC) gets the words it turns back onto
  // that axis; unrotated, the one word it always was.
  const turn = axis === 'Z' ? 0 : controllerWorkRotation(ctrl, ctrl.status())
  const alongAxis = (sign: string, distance: number) => {
    if (turn === 0) return `${axis}${sign}${n(distance)}`
    const mm = sign === '-' ? -distance : distance
    return machineStepXYWords(turn, axis === 'X' ? mm : 0, axis === 'Y' ? mm : 0, n)
  }
  const probeWord = (distance: number) => alongAxis(probeSign, distance)
  const retractWord = (distance: number) => alongAxis(retractSign, distance)
  const axisIndex = axis === 'X' ? 0 : axis === 'Y' ? 1 : 2

  if (!cycleOwned) {
    setProbeCycleActive(true)
    ownRun = claimProbeCycleRun(options.probeLabel ?? `Probe ${axis}${direction}`)
  }
  store().clearProbe()
  try {
    if (nativeProbeRoute(ctrl)) {
      const touched = await executeNativeProbeTouch(ctrl, axis, direction, effective, travelMm, options, receiptToken)
      return ownRun?.stopped ? fail(PROBE_CYCLE_STOPPED) : touched
    }
    // WO-2021: a setter measure runs the routine's own speeds and distances
    // here too; every other touch keeps the profile's.
    const setter = options.toolSetter
    const fastFeed = n(setter ? setter.values.fastFeed : effective.fastFeed)
    const fineFeed = n(setter ? setter.values.fineFeed : effective.slowFeed)
    const retract = setter ? setter.values.retractMm : effective.retract
    const fineSearch = setter ? setter.values.fineSearchMm : effective.retract * 2
    const zFloor = probeSearchZFloor(axis, direction, options, !cycleOwned || options.startSettled === true)
    const startZ = ctrl.status().machinePos?.z
    const startKnown = typeof startZ === 'number' && Number.isFinite(startZ)
    if ((setter || zFloor !== null) && !startKnown) {
      return fail('The controller has not reported its machine Z position, which keeps the probe search above the machine Z limit - nothing was sent.')
    }
    let fastTravel = travelMm
    /** Set when the guarded approach touched the setter early: that touch is the fast pass. */
    let approachContactZ: number | null = null
    if (setter && startKnown) {
      // WO-2021 (09-25 simulator rehearsal): the measure goes to the setter on
      // this route as on the native one - lift to the crossing height (never
      // lower), cross XY there, both at the rapid rate (G53 G0, machine
      // coordinates), then search down to the plan's floor.
      noteProbePhase('the move to the tool setter')
      if (setter.crossingZ > startZ) {
        const lift = await send(`G21 G90 G53 G0 Z${n(setter.crossingZ)}`)
        if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
        if (!lift || !lift.ok) {
          return fail(`Raising Z before moving to the tool setter stopped: ${unsentReason(lift) ?? lift?.message ?? 'the controller refused the move'} - the probe was not started.`)
        }
      }
      const across = await send(`G21 G90 G53 G0 X${n(setter.setter.x)} Y${n(setter.setter.y)}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
      if (!across || !across.ok) {
        return fail(`Moving to the tool setter stopped: ${unsentReason(across) ?? across?.message ?? 'the controller refused the move'} - the probe was not started.`)
      }
      let travelZ = Math.max(startZ, setter.crossingZ)
      const approach = setter.approach
      if (approach && approach.targetZ < travelZ && textSetterApproachWordStated()) {
        // WO-2021 audit: the planned guarded approach (Operator 2026-09-16: a wrong
        // tool table length must not drive the tool into the setter). G38.3 is
        // a probe move that stops on contact and ends quietly at its target
        // without it - the native route's approach, at the plan's approach feed.
        store().clearProbe()
        noteProbePhase('the approach toward the tool setter')
        const guarded = await send(`G21 G91 G38.3 Z-${n(travelZ - approach.targetZ)} F${n(approach.feedMmMin)}`)
        if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
        if (!guarded) return fail('The controller refused the approach toward the tool setter - the probe was not started.')
        const guardedUnsent = unsentReason(guarded)
        if (guardedUnsent) return fail(guardedUnsent)
        if (guarded.ok) {
          const touched = store().probe
          if (touched?.success && Number.isFinite(touched.values[axisIndex])) {
            approachContactZ = touched.values[axisIndex]
          } else {
            travelZ = approach.targetZ
          }
        } else {
          // The controller did not take the line (nothing moved): the fast
          // search below runs the whole descent, from the crossing height.
          store().pushConsole(
            'rx',
            `Measure tool: the controller did not take the guarded approach (${guarded.message ?? 'G38.3 refused'}); `
              + `the fast probe searches down from ${machinePositionText({ z: travelZ })} instead.`,
            'warn',
          )
        }
      }
      fastTravel = partProbeFineSearchMm(travelZ, travelZ - setter.searchFloorZ, setter.searchFloorZ)
    } else if (zFloor !== null && startKnown) {
      fastTravel = partProbeFineSearchMm(startZ, travelMm, zFloor)
    }
    let fastMachinePosition: number | undefined
    if (approachContactZ !== null) {
      // The approach touched the setter: that touch is the fast pass.
      fastMachinePosition = approachContactZ
    } else {
      if (!(fastTravel > 0)) {
        return fail(`The probe search has no downward travel left above the machine Z limit (${machinePositionText({ z: zFloor ?? 0 })}) - nothing was sent.`)
      }
      // Everything below runs in mm and relative moves; modal state is restored
      // at the end whatever happens.
      store().clearProbe()
      noteProbePhase('the search')
      const fast = await send(`G21 G91 G38.2 ${probeWord(fastTravel)} F${fastFeed}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
      if (!fast) return fail('The controller refused the probe command.')
      // WO-1545 rule 4: a command that never ran is reported as itself, never as
      // a probe that ran and missed.
      const fastUnsent = unsentReason(fast)
      if (fastUnsent) return fail(fastUnsent)
      if (!fast.ok) {
        noteProbeEndedWithoutContact(ctrl, axis, direction, options)
        if (options.searchMissMessage) {
          const miss = `${options.searchMissMessage(n(fastTravel))} (${String(fast.message ?? '').replace(/\.$/, '')}).`
          if (!options.riseToStartOnMiss || axis !== 'Z' || !startKnown) return fail(`${miss} Unlock ($X) - position was not lost.`)
          noteProbePhase('the rise back to where the search started')
          const back = await riseToStartAfterTextMiss(ctrl, receiptToken, n(startZ), n(effective.positioningFeed))
          if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
          // Still in alarm when the rise could not run: the unlock is still his.
          const unlock = back !== null && ctrl.machineState() === 'alarm' ? ' Unlock ($X) - position was not lost.' : ''
          return fail(`${miss} ${missRiseSentence(ctrl, n(startZ), back)}${unlock}`)
        }
        return fail(
          `The probe never made contact within ${machineLengthText(fastTravel)} (${fast.message}). ` +
            (setter
              ? 'Nothing was recorded. Check the tool setter wiring and position. Unlock ($X) - position was not lost.'
              : axis === 'Z' ? 'Check the probe wiring and pad position, then Unlock ($X) - position was not lost.'
                : 'Check the probe wiring and start position, then Unlock ($X) - position was not lost.'),
        )
      }
      const fastProbe = store().probe
      fastMachinePosition = fastProbe?.success ? fastProbe.values[axisIndex] : undefined
    }
    // WO-2021 audit: the same early-touch warning as the native route - a
    // contact above the approach's end is a contact the approach would have
    // stopped on, whether the approach ran as its own line or the fast search
    // covered that height.
    const approachPlan = setter?.approach
    let earlyTouchNote: string | null = null
    let earlyTouchSummary = ''
    if (approachPlan && typeof fastMachinePosition === 'number' && fastMachinePosition > approachPlan.targetZ) {
      const tool = setter!.tool === null ? 'the active tool' : `T${setter!.tool}`
      const above = n(fastMachinePosition - approachPlan.expectedContactZ)
      earlyTouchNote = `The setter triggered early, at ${machinePositionText({ z: fastMachinePosition })} - ${machineLengthText(above)} above where `
        + `${tool}'s tool table length put it (${machinePositionText({ z: approachPlan.expectedContactZ })}). The approach stopped there. `
        + `A ${machineLengthText(retract)} retract was requested.`
      earlyTouchSummary = `Setter triggered early at ${machinePositionText({ z: fastMachinePosition })}, ${machineLengthText(above)} above `
        + `${tool}'s table length prediction (${machinePositionText({ z: approachPlan.expectedContactZ })}); approach stopped and tool retracted ${machineLengthText(retract)}`
    }
    noteProbePhase('the retract between passes')
    const away = await send(`G91 G0 ${retractWord(retract)}`)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
    if (!away || !away.ok) return fail(unsentReason(away) ?? 'The retract between probe passes failed.')
    const fineSearchMm = zFloor !== null
      ? typeof fastMachinePosition === 'number' && Number.isFinite(fastMachinePosition)
        ? partProbeFineSearchMm(fastMachinePosition + retract, fineSearch, zFloor)
        : null
      : fineSearch
    if (fineSearchMm === null) {
      return fail('The controller did not report the fast probe contact needed to keep the fine pass above the machine Z limit.')
    }
    if (!(fineSearchMm > 0)) {
      return fail('The fine probe pass has no downward travel remaining above the machine Z limit.')
    }
    noteProbePhase('the fine pass')
    // Operator ruling 10-06 7:20 PM: no warning on an early touch - the success line already says what happened.
    const beforeFine = store().probe
    const slow = await send(`G91 G38.2 ${probeWord(fineSearchMm)} F${fineFeed}`)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
    if (!slow) return fail('The controller refused the fine probe pass.')
    const slowUnsent = unsentReason(slow)
    if (slowUnsent) return fail(slowUnsent)
    if (!slow.ok) {
      return fail(setter
        // A miss after an early setter touch says the touch came early (machine seat 10-06 a4 finding).
        ? (earlyTouchSummary ? `${earlyTouchSummary}. ` : '')
          + `The fine pass lost contact: no touch within ${machineLengthText(fineSearchMm)} `
          + `(machine ${axis} ${machineLengthText(n(fastMachinePosition! + retract))} to ${machineLengthText(n(fastMachinePosition! + retract - fineSearchMm))}). `
          + `Nothing was recorded. The tool backed off ${machineLengthText(retract)} before the fine pass. Check that the tool setter is seated and held still. Unlock ($X) - position was not lost.`
        : options.sensedByPart && !(store().probe !== beforeFine && store().probe?.success === false)
          // WO-2664 audit: no [PRB:...:0] for this pass - not a miss. The
          // controller's own reply is what happened.
          ? `The fine pass did not finish (${String(slow.message ?? 'the controller refused it').replace(/\.$/, '')}).`
        : options.sensedByPart
          // WO-2664: a miss ([PRB:...:0]), as the native route says it - no pad advice.
          ? `The fine pass lost contact: no touch within ${machineLengthText(fineSearchMm)}${typeof fastMachinePosition === 'number' && Number.isFinite(fastMachinePosition)
            ? ` (machine ${axis} ${machineLengthText(n(fastMachinePosition - (direction === '+' ? 1 : -1) * retract))} to ${machineLengthText(n(fastMachinePosition - (direction === '+' ? 1 : -1) * (retract - fineSearchMm)))})`
            : ''}. Unlock ($X) - position was not lost.`
          : `The fine pass lost contact (${slow.message}). Check that the pad is stable, then Unlock ($X) - position was not lost.`,
      )
    }
    const prb = store().probe
    const probedMachinePosition = prb?.values[axisIndex]
    if (!prb?.success || probedMachinePosition === undefined || !Number.isFinite(probedMachinePosition)) {
      return fail('The controller did not report a probe contact ([PRB]).')
    }

    const afterContactFailure = await options.afterContact?.(send, n, probedMachinePosition)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
    if (afterContactFailure) return fail(afterContactFailure)

    noteProbePhase('the retract off the contact')
    const off = await send(`G91 G0 ${retractWord(retract)}`)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
    if (!off || !off.ok) return fail(unsentReason(off) ?? `The final retract off the ${setter ? 'tool setter' : 'pad'} failed.`)

    const endZ = axis === 'Z' && options.endMachineZ ? n(options.endMachineZ(probedMachinePosition)) : null
    if (endZ !== null && endZ > n(probedMachinePosition + retract)) {
      noteProbePhase('the rise after the touch')
      // WO-2061: machine coordinates, so the rise ends where the plan says
      // whatever the work offset the touch just wrote.
      const rise = await send(`G21 G90 G53 G0 Z${endZ}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
      if (!rise || !rise.ok) {
        const reason = unsentReason(rise) ?? rise?.message ?? 'the controller refused the move'
        return fail(options.endRiseFailure?.(probedMachinePosition, reason) ?? `Rising to ${machinePositionText({ z: endZ })} after the touch stopped: ${reason}.`)
      }
    }

    if (setter && setter.crossingZ > probedMachinePosition + retract) {
      // WO-2017's rule on this route too: back up to the crossing height
      // before anything else can move XY.
      const up = await send(`G21 G90 G53 G0 Z${n(setter.crossingZ)}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe cycle.')
      if (!up || !up.ok) {
        return fail(
          `The setter touched at ${machinePositionText({ z: probedMachinePosition })}, but raising Z back to the crossing height `
            + `stopped: ${unsentReason(up) ?? up?.message ?? 'the controller refused the move'} - the measurement was not recorded.`,
        )
      }
    }

    // WO-2615: queued is not arrived. Keep Stop live through the final
    // retract/rise (and a setter's return), including a cycle-owned touch.
    // Normal completion uses reported Idle, as the touch's entry gate does;
    // it must not add a verifiedIdle requirement to a completed touch.
    if (ctrl.machineState() !== 'idle' && !(await waitForProbePositioningIdle(ctrl, 30_000, true))) {
      return fail(probeCycleStopped() ? PROBE_CYCLE_STOPPED : 'The final probe move did not settle to Idle.')
    }
    // WO-2071: every line went out, but the Stop halted the last of them.
    if (ownRun?.stopped) return fail(PROBE_CYCLE_STOPPED)
    const base = options.successMessage?.(probedMachinePosition) ??
      `Probe contact at machine ${axis} ${machineLengthText(probedMachinePosition)}.`
    return {
      ok: true,
      message: earlyTouchNote
        ? `${earlyTouchSummary}. The fine touch measured the tool at ${machinePositionText({ z: probedMachinePosition })} and replaces the table's length.`
        : base,
      probedMachinePosition,
      contacts: {
        // Text controllers expose only the final [PRB] record here. A status
        // sample or the later retract position is not a fast-contact receipt.
        fastMachinePosition: null,
        fineMachinePosition: probedMachinePosition,
      },
    }
  } finally {
    // WO-2615: positioning waits also stop; modal restore must wait for the
    // controlled cancellation, or GRBL sees new activity and refuses it.
    await ownRun?.cancelMotion
    if (!cycleOwned) setProbeCycleActive(false)
    releaseProbeCycleRun(ownRun)
    // Restore absolute mode + the operator's units, then re-read state. In
    // ALARM (probe miss) the controller refuses everything but $X/$H, so the
    // restore waits for recovery - recoverFromProbeAlarm finishes the job.
    if (receiptIsCurrent(receiptToken) && !cycleOwned && ctrl.machineState() !== 'alarm' && ctrl.connectionPhase() === 'connected') {
      sendAppCommand('G90', ctrl)
      if (prevUnitsInch) sendAppCommand('G20', ctrl)
      ctrl.refreshState()
    }
  }
}

/**
 * One signed probe touch on X, Y, or Z. The same fail-loud two-pass sequence
 * and recovery boundary used by the fixed-pad Z flow applies on every axis.
 */
export async function runDirectionalProbeTouch(
  axis: ProbeAxis,
  direction: ProbeDirection,
  config: ZProbeConfig,
  /** WO-2036: the search distance, when shorter than the profile's maximum
   *  travel (the maximum stays the validated bound). */
  travelMm?: number,
): Promise<DirectionalProbeResult> {
  const ctrl = getMachineController()
  // Awaited only when there is something to wait for: an idle machine's touch
  // claims the probe lock synchronously, as it always has.
  if (probeTouchMustSettle(ctrl)) {
    const unsettled = await settleBeforeProbeTouch(ctrl)
    if (unsettled) return { ok: false, message: unsettled, probedMachinePosition: null }
  }
  return executeDirectionalProbeTouch(axis, direction, config, travelMm === undefined ? {} : { travelMm })
}

/** WO-1998: a touch the operator starts right after the previous one (or any
 *  other app-queued move) can find the controller still finishing it - an MDI
 *  'ok' means accepted, not arrived (the WO-416 finding). Motion about to end
 *  is not a reason to refuse: wait for Idle BEFORE anything is planned from
 *  the position. Only 'run' outside a program and outside a probe cycle waits;
 *  a live jog, hold, alarm or door goes straight on to the touch's own idle
 *  gate, which still refuses it. */
function probeTouchMustSettle(ctrl: MachineController): boolean {
  return ctrl.connectionPhase() === 'connected'
    && !ctrl.hasActiveJob()
    && !probeCycleActive
    && ctrl.machineState() === 'run'
}

/** Null when the touch may go on to its own gate. */
async function settleBeforeProbeTouch(ctrl: MachineController): Promise<string | null> {
  const receiptToken = captureBackendReceipt(ctrl)
  const settled = await waitForProbePositioningIdle(ctrl)
  if (!receiptIsCurrent(receiptToken)) return 'The machine connection changed during the probe cycle.'
  if (!settled && ctrl.machineState() === 'run') {
    return 'The machine was still moving and did not report Idle - no probe move was sent.'
  }
  return null
}

interface FeatureProbeCycleResult {
  ok: boolean
  message: string
  touches: Partial<Record<ProbeCycleTouchKey, number>>
  /** WO-2055: machine Z of the top the cycle touched first; null when it touched none. */
  topMachineZ?: number | null
  /** WO-2071: Stop/Reset ended it; `message` is the stopped sentence. */
  stopped?: true
}

interface SurfaceMeshProbeCycleInput {
  points: SurfaceMeshPoint[]
  bounds: SurfaceMeshMap['bounds']
  cutBounds: SurfaceMeshMap['cutBounds']
  pointsX: number
  pointsY: number
  fadeMm: number
  /** Where the operator stood when Run was pressed: the height of the move to
   *  point 1 and of point 1's search. */
  safeMachineZ: number
  /** WO-2064: the largest height change expected between point 1 and any other
   *  point (editable; DEFAULT_MESH_HEIGHT_CHANGE_MM when absent). */
  largestHeightChangeMm?: number
  sourceProgramText: string
  sourceName: string | null
  workOffset: string
}

interface SurfaceMeshProbeCycleResult {
  ok: boolean
  message: string
  samples: SurfaceMeshSample[]
  mesh: SurfaceMeshMap | null
  /** WO-2071: Stop/Reset ended it; `message` is the stopped sentence. */
  stopped?: true
}

async function waitForProbePositioningIdle(
  ctrl: MachineController,
  timeoutMs = 30_000,
  acceptReportedIdle = false,
): Promise<boolean> {
  const receiptToken = captureBackendReceipt(ctrl)
  let deadline = sessionElapsedNowMs() + timeoutMs
  const run = activeProbeCycle
  let epoch = run?.pauseEpoch
  while (sessionElapsedNowMs() < deadline) {
    ctrl.queryStatus()
    const before = sessionElapsedNowMs()
    await new Promise((resolve) => setTimeout(resolve, 50))
    if (!receiptIsCurrent(receiptToken)) return false
    // WO-2071: Stop/Reset ended the cycle this wait belongs to.
    if (probeCycleStopped()) return false
    // WO-2517: the frame this wait reads is watched like any other.
    watchProbeInput(ctrl, ctrl.status())
    if (probeCycleStopped()) return false
    // WO-2103: time the operator holds the machine is not time the move took.
    if (probeCycleHeldByOperator(ctrl)) {
      deadline += sessionElapsedNowMs() - before
      continue
    }
    if (run && run.pauseEpoch !== epoch) {
      if (!ctrl.verifiedIdle()) continue
      epoch = run.pauseEpoch
      if (run.resumeMove && !run.resumeMove()) return false
      continue
    }
    if (ctrl.verifiedIdle() || (acceptReportedIdle && ctrl.machineState() === 'idle')) {
      noteProbeMotionSettled(ctrl)
      return !probeCycleStopped()
    }
    if (ctrl.connectionPhase() !== 'connected' || ctrl.machineState() === 'alarm') return false
  }
  return false
}

/** Probe a full work-coordinate surface grid under one authority lock. The
 * move to point 1 and its search run from the operator-confirmed starting
 * machine Z; point 1's contact becomes work Z0. WO-2064: every later move
 * between points, and the end of the cycle, runs at point 1's top +
 * clearance, and each later point searches down only clearance + the largest
 * height change expected (meshPointSearchMm). Every point uses the established
 * two-pass Z touch, and the relative height field is compiled into the
 * already-loaded program only after every point succeeds. */
export async function runSurfaceMeshProbeCycle(
  input: SurfaceMeshProbeCycleInput,
  config: ZProbeConfig,
  pathClearConfirmed: boolean,
  onSample?: (sample: SurfaceMeshSample) => void,
): Promise<SurfaceMeshProbeCycleResult> {
  const samples: SurfaceMeshSample[] = []
  let run: ProbeCycleRun | null = null
  // WO-2533: a stopped run says so once the move it stopped has come to rest.
  const fail = (message: string): SurfaceMeshProbeCycleResult | Promise<SurfaceMeshProbeCycleResult> => (run?.stopped
    ? probeCycleStoppedMessageAtRest(run)
      .then((said): SurfaceMeshProbeCycleResult => ({ ok: false, message: said, samples, mesh: null, stopped: true }))
    : { ok: false, message, samples, mesh: null })
  // WO-1330: point 1 writes the mesh frame's Z zero; ask before anything moves
  // or the loaded program is disarmed.
  const held = workOffsetWriteRefusal(WCS_SLOTS.find((wcs) => wcs === input.workOffset) ?? null, ['Z'])
  if (held !== null) return fail(held)
  if (!pathClearConfirmed) return fail('Confirm the mesh area, safe travel plane, and probe path before running.')
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  const valid = validateZProbeConfig(config)
  if (!valid.ok) return fail(valid.reason)
  if (input.points.length !== input.pointsX * input.pointsY || input.points.length < 9) {
    return fail('The surface mesh grid is incomplete.')
  }
  if (!Number.isFinite(input.safeMachineZ)) return fail('A known safe machine Z is required for mesh travel.')
  const heightChange = input.largestHeightChangeMm ?? DEFAULT_MESH_HEIGHT_CHANGE_MM
  if (!Number.isFinite(heightChange) || heightChange < 0) {
    return fail('The largest height change must be a number of millimetres, zero or more.')
  }
  if (fingerprintProgram(input.sourceProgramText) !== fingerprintProgram(loadedProgramText() ?? '')) {
    return fail('The loaded program changed after the mesh plan was reviewed.')
  }
  // WO-2104: a file the file door staged (the UCCNC bridge's only route) is
  // staged again through it once the mesh is armed; noted before anything moves.
  const fileDoor = currentFileDoorProgram()

  // Validate the eventual compiler before physical motion using a flat dummy
  // surface. Modal incompatibilities must be found before the first probe.
  const dummySamples = input.points.map((point) => ({ ...point, machineZ: input.safeMachineZ }))
  const dummyMesh: SurfaceMeshMap = {
    bounds: input.bounds,
    cutBounds: input.cutBounds,
    pointsX: input.pointsX,
    pointsY: input.pointsY,
    fadeMm: input.fadeMm,
    referenceMachineZ: input.safeMachineZ,
    samples: dummySamples,
    sourceFingerprint: fingerprintProgram(input.sourceProgramText),
    sourceName: fileDoor?.name ?? input.sourceName,
    workOffset: input.workOffset,
    probedAt: 0,
    active: true,
  }
  const preflight = compileSurfaceCompensatedProgram(input.sourceProgramText, dummyMesh)
  if (!preflight.ok) return fail(`Mesh compensation cannot arm this program: ${preflight.reason}`)

  const effective = resolveProbeConfig(null, config)
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const zeroWcs = store().activeWcs
  if (!zeroWcs || zeroWcs !== input.workOffset) {
    return fail(`Activate ${input.workOffset} before running this mesh probe cycle.`)
  }
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  if (ctrl.hasActiveJob()) return fail('A program is running - probing is locked out.')
  if (ctrl.machineState() !== 'idle') return fail('The machine must be idle to start a mesh probe cycle.')
  // ALL THREE. The cycle positions in X and Y by machine coordinate between
  // points and retracts to a machine-coordinate safe Z; one unreferenced axis
  // is one axis driven to a meaningless number, unattended, at every point.
  const meshRefusal = homingRefusal(ctrl, undefined, 'an automatic mesh probe cycle moves every axis by machine coordinate.')
  if (meshRefusal) return fail(meshRefusal)
  if (probeCycleActive) return fail('A probe cycle is already running.')
  // WO-1545 rule 4: on a controller whose native call for this cycle is not
  // wired yet, say so BEFORE the disarm below - otherwise the loaded program is
  // left disarmed behind a "cycle in progress" reason for a cycle that never ran.
  // WO-1548: the moves run; the touch is asked about too, so a cycle whose touch
  // cannot run yet is named before anything is disarmed or moved.
  const unwired = appCommandUnsentHere(
    ctrl,
    `G21 G90 G53 G1 Z${Number(input.safeMachineZ.toFixed(4))} F${Number(effective.positioningFeed.toFixed(4))}`,
  ) ?? probeTouchUnsentHere(ctrl, `G21 G91 G38.2 Z-${Number(effective.maxTravel.toFixed(4))} F${Number(effective.fastFeed.toFixed(4))}`)
  if (unwired) return fail(unwired)

  // A replacement cycle invalidates the old height field as soon as point 1
  // is allowed to rewrite work Z0. Disarm both the old map and the send queue
  // before any physical move; only a complete new map is allowed to re-arm.
  store().setSurfaceMesh(null)
  loadNothing(ctrl)
  store().applyJobProgress(ctrl.jobProgress())
  store().setProgramReadiness({
    ready: false,
    reason: 'Surface mesh cycle in progress. The program remains disarmed until every point succeeds.',
  })

  const previousUnitsInch = store().parserModal?.units === 'inch'
  const send = (line: string) => probeCycleSend(line, ctrl)
  const number = (value: number) => Number(value.toFixed(4))
  const zeroRevision = connectionRevision
  const pointSearchMm = meshPointSearchMm(effective, heightChange)
  /** Point 1's top + clearance, once point 1 has been touched. */
  let traverseMachineZ: number | null = null
  // WO-2059: point 1's Z0 is the contact less the plate, when there is one.
  const plateMm = controlZPlateMm('zSurface', config)
  setProbeCycleActive(true)
  run = claimProbeCycleRun('Surface mesh probe')
  try {
    for (let index = 0; index < input.points.length; index++) {
      const point = input.points[index]
      const travelZ = traverseMachineZ ?? input.safeMachineZ
      noteProbeStep(`mesh point ${index + 1} of ${input.points.length}`)
      noteProbePhase('the safe Z move')
      const lift = await send(`G21 G90 G53 G1 Z${number(travelZ)} F${number(effective.positioningFeed)}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
      if (!lift || !lift.ok) return fail(unsentReason(lift) ?? `Safe Z move before mesh point ${index + 1} failed.`)
      if (!(await waitForProbePositioningIdle(ctrl))) {
        if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
        return fail(`Safe Z move before mesh point ${index + 1} did not settle to Idle.`)
      }
      noteProbePhase('the XY move')
      const position = await send(`G21 G90 G1 X${number(point.x)} Y${number(point.y)} F${number(effective.positioningFeed)}`)
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
      if (!position || !position.ok) return fail(unsentReason(position) ?? `XY move to mesh point ${index + 1} failed.`)
      if (!(await waitForProbePositioningIdle(ctrl))) {
        if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
        return fail(`XY move to mesh point ${index + 1} did not settle to Idle.`)
      }
      const touch = await executeDirectionalProbeTouch('Z', '-', effective, {
        cycleOwned: true,
        // Point 1 is searched from wherever the operator stood; every later
        // point from point 1's top + clearance.
        ...(traverseMachineZ === null ? {} : { travelMm: pointSearchMm }),
        // Both positioning moves above were waited to Idle: the reported Z is
        // where this touch starts, so its search is held above Z min.
        startSettled: true,
        afterContact: index === 0
          ? async (sendContact, n) => {
              const zero = await sendContact(`G10 L20 P0 Z${n(plateMm)}`)
              if (!receiptIsCurrent(receiptToken)) return 'The machine connection changed during the mesh probe cycle.'
              if (!zero || !zero.ok) return unsentReason(zero) ?? 'Setting work Z0 at the first mesh point failed.'
              markConfirmedWorkZero(zeroWcs, 'Z', zeroRevision)
              return null
            }
          : undefined,
      })
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
      if (!touch.ok || touch.probedMachinePosition === null) {
        return fail(`Mesh point ${index + 1} stopped: ${touch.message}`)
      }
      const sample: SurfaceMeshSample = { ...point, machineZ: touch.probedMachinePosition }
      samples.push(sample)
      onSample?.(sample)
      if (traverseMachineZ === null) traverseMachineZ = touch.probedMachinePosition + effective.surfaceClearance
    }
    noteProbeStep('the final return to safe Z')
    const finalLift = await send(`G21 G90 G53 G1 Z${number(traverseMachineZ ?? input.safeMachineZ)} F${number(effective.positioningFeed)}`)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
    if (!finalLift || !finalLift.ok) {
      return fail(unsentReason(finalLift) ?? 'The final return to safe Z failed; the mesh was not armed.')
    }
    if (!(await waitForProbePositioningIdle(ctrl))) {
      if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the mesh probe cycle.')
      return fail('The final return to safe Z did not settle to Idle; the mesh was not armed.')
    }
    if (run.stopped) return fail(PROBE_CYCLE_STOPPED)
    const mesh: SurfaceMeshMap = {
      bounds: input.bounds,
      cutBounds: input.cutBounds,
      pointsX: input.pointsX,
      pointsY: input.pointsY,
      fadeMm: input.fadeMm,
      referenceMachineZ: samples[0].machineZ,
      samples,
      sourceFingerprint: fingerprintProgram(input.sourceProgramText),
      sourceName: fileDoor?.name ?? input.sourceName,
      workOffset: input.workOffset,
      // WO-1822 / ADR-0050 G2. Read AFTER the cycle, because point 1 wrote
      // work Z0 itself: these are the values the map is measured against, and
      // any later move of them invalidates it.
      workOffsetValues: store().offsets[input.workOffset] ?? null,
      probedAt: Date.now(),
      active: true,
    }
    const compiled = compileSurfaceCompensatedProgram(input.sourceProgramText, mesh)
    if (!compiled.ok) return fail(`The measured mesh could not be armed: ${compiled.reason}`)
    // WO-2267 (Operator ruling 2026-09-30): the run measures; Confirm applies. Until
    // then the mesh is held unapplied and the program is staged plain again.
    store().pushConsole(
      'rx',
      `Surface mesh measured: ${mesh.pointsX} x ${mesh.pointsY} points. Confirm applies it to ${mesh.workOffset}.`,
      'info',
    )
    store().setSurfaceMesh({ ...mesh, active: false })
    if (fileDoor) {
      loadGcodeTextToolpathProgram(fileDoor.name, fileDoor.text, {
        publishListing: true,
        context: fileDoor.context,
        runThroughOffsetChanges: fileDoor.runThroughOffsetChanges,
      })
    } else {
      loadMachineProgram(input.sourceName ?? 'program', input.sourceProgramText)
    }
    return {
      ok: true,
      message: `${samples.length} points measured; nothing is compensated until Confirm.`,
      samples,
      mesh: { ...mesh, active: false },
    }
  } finally {
    await run?.cancelMotion
    setProbeCycleActive(false)
    releaseProbeCycleRun(run)
    if (receiptIsCurrent(receiptToken) && ctrl.machineState() !== 'alarm' && ctrl.connectionPhase() === 'connected') {
      sendAppCommand('G90', ctrl)
      if (previousUnitsInch) sendAppCommand('G20', ctrl)
      ctrl.refreshState()
    }
  }
}

/** The routine's name in an operator sentence. */
const FEATURE_PROBE_NAMES: Record<ProbeFeatureKind, string> = {
  edge: 'Edge',
  corner: 'Corner',
  insideCorner: 'Inside corner',
  outsideCorner: 'Outside corner',
  bore: 'Bore',
  boss: 'Boss',
  rectPocket: 'Rect pocket',
  rectBoss: 'Rect boss',
  angle: 'Angle',
}

/**
 * WO-2055: the descent to probing depth is a PROBE move - it stops on
 * contact, like the setter's guarded approach - never a blind move. It runs
 * from a known height, so the text route's relative distance is known.
 * Returns the contact Z when it touched, null when it arrived, or the failure.
 * WO-2073: shared by the feature cycles and the probe routine runner.
 */
async function guardedZDescent(
  ctrl: MachineController,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
  label: string,
  fromZ: number,
  depthZ: number,
  feed: number,
  changed: string,
): Promise<{ touchedZ: number | null } | { failed: string }> {
  const n = (value: number) => Number(value.toFixed(4))
  noteProbeStep(label)
  if (nativeProbeRoute(ctrl)) {
    if (estopNeedsReset()) return { failed: ESTOP_BLOCKS_MOTION }
    const fromZ = ctrl.status().machinePos?.z
    const { touch: guarded, settle } = await guardedProbeCallUnlessStopped(ctrl, 'Z', depthZ, feed)
    if (!receiptIsCurrent(receiptToken)) { settle(false); return { failed: changed } }
    if (guarded === null) return { failed: PROBE_CYCLE_STOPPED }
    if (guarded.reason) return { failed: nativeProbeFailureMessage(guarded.reason, `${label} did not run`) }
    if (guarded.ok && guarded.at !== null) return { touchedZ: guarded.at.z }
    const distance = typeof fromZ === 'number' ? Math.abs(fromZ - depthZ) : 0
    const arrived = await waitForProbeRoutineMove(ctrl, { z: depthZ }, nativeMoveTimeoutMs(distance, feed))
    settle(arrived)
    if (!receiptIsCurrent(receiptToken)) return { failed: changed }
    return arrived
      ? { touchedZ: null }
      : { failed: `${label} did not settle at ${machinePositionText({ z: depthZ })}.` }
  }
  // G38.3: a probe move that stops on contact and ends quietly at its
  // target without one (the setter approach's text line, WO-2021). A
  // dialect without it runs the older plan and never descends.
  store().clearProbe()
  const guarded = await probeCycleSend(`G21 G91 G38.3 Z-${n(fromZ - depthZ)} F${feed}`, ctrl)
  if (!receiptIsCurrent(receiptToken)) return { failed: changed }
  if (!guarded) return { failed: `${label} stopped: the controller refused the probe move.` }
  const guardedUnsent = unsentReason(guarded)
  if (guardedUnsent) return { failed: `${label} stopped: ${guardedUnsent}` }
  if (!guarded.ok) {
    // WO-2055 audit: a plain move cannot stop on the part, so the cycle
    // stops here, at safe height over the step-out point.
    return {
      failed: `${label} stopped: the controller did not take the probe move (${guarded.message ?? 'G38.3 refused'}), `
        + 'so it cannot make the guarded descent. The probe stays at safe height.',
    }
  }
  const touched = store().probe
  const touchedZ = touched?.success && Number.isFinite(touched.values[2]) ? touched.values[2] : null
  // A text controller acks a line when it is queued, and the side touch after
  // a descent is refused while the machine still runs: wait for Idle, as the
  // surface mesh cycle does.
  const settled = await waitForProbePositioningIdle(ctrl)
  if (!receiptIsCurrent(receiptToken)) return { failed: changed }
  return settled ? { touchedZ } : { failed: `${label} did not settle to Idle.` }
}

/**
 * WO-2088: a routine move that stops on contact and travels in X and/or Y (an
 * angled or sideways guarded move) - the probe move along the straight line
 * from `from` to `target`. On a controller that takes text it is one G38.3
 * line naming every moved axis; on the native route it is the probe call,
 * which moves one axis (probeRoutineExecutionRefusal names a combined one
 * before the run). Returns the contact point when it touched, null when it
 * arrived at its target, or the failure.
 */
async function guardedLineMove(
  ctrl: MachineController,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
  label: string,
  from: MachineVec3,
  target: MachineVec3,
  axes: readonly ProbeAxis[],
  feed: number,
  changed: string,
): Promise<{ contact: MachineVec3 | null } | { failed: string }> {
  const n = (value: number) => Number(value.toFixed(4))
  const keys = axes.map((axis) => axis.toLowerCase() as keyof MachineVec3)
  const moving = keys.filter((key) => n(target[key] - from[key]) !== 0)
  noteProbeStep(label)
  // Already at its target: nothing to probe toward.
  if (moving.length === 0) return { contact: null }
  if (nativeProbeRoute(ctrl)) {
    if (keys.length !== 1) return { failed: `${label} did not run: this controller's probe call moves one axis at a time.` }
    const key = keys[0]
    if (estopNeedsReset()) return { failed: ESTOP_BLOCKS_MOTION }
    const { touch: guarded, settle } = await guardedProbeCallUnlessStopped(ctrl, axes[0], target[key], feed)
    if (!receiptIsCurrent(receiptToken)) { settle(false); return { failed: changed } }
    if (guarded === null) return { failed: PROBE_CYCLE_STOPPED }
    if (guarded.reason) return { failed: nativeProbeFailureMessage(guarded.reason, `${label} did not run`) }
    if (guarded.ok && guarded.at !== null) return { contact: { ...guarded.at } }
    const arrived = await waitForProbeRoutineMove(
      ctrl, { [key]: target[key] }, nativeMoveTimeoutMs(Math.abs(target[key] - from[key]), feed),
    )
    settle(arrived)
    if (!receiptIsCurrent(receiptToken)) return { failed: changed }
    return arrived
      ? { contact: null }
      : { failed: `${label} did not settle at ${machinePositionText({ [key]: target[key] })}.` }
  }
  // G38.3 in G91: every moved axis's distance from where the probe stands, so
  // the line runs straight to the target and ends quietly there without a contact.
  store().clearProbe()
  // WO-2212: along the MACHINE line from `from` to `target`, also where the
  // controller turns a G91 X Y by the work rotation (LinuxCNC).
  const turn = moving.some((key) => key !== 'z') ? controllerWorkRotation(ctrl, ctrl.status()) : 0
  const step = (key: keyof MachineVec3) => (moving.includes(key) ? target[key] - from[key] : 0)
  const words = turn === 0
    ? moving.map((key) => `${key.toUpperCase()}${n(target[key] - from[key])}`).join(' ')
    : [
        machineStepXYWords(turn, step('x'), step('y'), n),
        ...(moving.includes('z') ? [gcodeAxisWord('Z', n(target.z - from.z))] : []),
      ].join(' ')
  const guarded = await probeCycleSend(`G21 G91 G38.3 ${words} F${feed}`, ctrl)
  if (!receiptIsCurrent(receiptToken)) return { failed: changed }
  if (!guarded) return { failed: `${label} stopped: the controller refused the probe move.` }
  const guardedUnsent = unsentReason(guarded)
  if (guardedUnsent) return { failed: `${label} stopped: ${guardedUnsent}` }
  if (!guarded.ok) {
    return { failed: `${label} stopped: the controller did not take the probe move (${guarded.message ?? 'G38.3 refused'}).` }
  }
  const touched = store().probe
  const contact = touched?.success && touched.values.slice(0, 3).every((v) => Number.isFinite(v))
    ? { x: touched.values[0], y: touched.values[1], z: touched.values[2] }
    : null
  const settled = await waitForProbePositioningIdle(ctrl)
  if (!receiptIsCurrent(receiptToken)) return { failed: changed }
  return settled ? { contact } : { failed: `${label} did not settle to Idle.` }
}

/** Execute one already-planned feature routine under one authority lock.
 *  Position steps are absolute machine-coordinate G1 moves at the configured
 *  clear feed. Touch steps retain the established two-pass G38.2 sequence. */
export async function runFeatureProbeCycle(
  plan: ProbeFeatureCyclePlan,
  config: ZProbeConfig,
  pathClearConfirmed: boolean,
  onTouch?: (key: ProbeCycleTouchKey, positionMm: number) => void,
): Promise<FeatureProbeCycleResult> {
  const programOwned = store().toolChange !== null || programPartsRun !== null || loadedProgramText() !== null
  const receipt = captureBackendReceipt(getMachineController())
  const result = await runFeatureProbeCycleOnce(plan, config, pathClearConfirmed, onTouch)
  if (!programOwned && receiptIsCurrent(receipt)) publishProbeActionResult(result, `${FEATURE_PROBE_NAMES[plan.kind]} probe`)
  return result
}

async function runFeatureProbeCycleOnce(
  plan: ProbeFeatureCyclePlan,
  config: ZProbeConfig,
  pathClearConfirmed: boolean,
  onTouch?: (key: ProbeCycleTouchKey, positionMm: number) => void,
): Promise<FeatureProbeCycleResult> {
  const touches: Partial<Record<ProbeCycleTouchKey, number>> = {}
  let topMachineZ: number | null = null
  let run: ProbeCycleRun | null = null
  // WO-2533: a stopped run says so once the move it stopped has come to rest.
  const fail = (message: string): FeatureProbeCycleResult | Promise<FeatureProbeCycleResult> => (run?.stopped
    ? probeCycleStoppedMessageAtRest(run)
      .then((said): FeatureProbeCycleResult => ({ ok: false, message: said, touches, topMachineZ, stopped: true }))
    : { ok: false, message, touches, topMachineZ })
  if (!pathClearConfirmed) {
    return fail('Confirm that the positioning path and cross-over lift are clear before running.')
  }
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  const valid = validateZProbeConfig(config)
  if (!valid.ok) return fail(valid.reason)
  const effective = resolveProbeConfig(null, config)
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  if (ctrl.hasActiveJob()) return fail('A program is running - probing is locked out.')
  if (ctrl.machineState() !== 'idle') return fail('The machine must be idle to start a probe cycle.')
  // ALL THREE. Positioning steps have absolute machine-coordinate endpoints,
  // so any axis a routine names must have a datum - and the cycle runs
  // unattended once started, which is why this is the conservative reading
  // rather than the per-step one.
  const probeRefusal = homingRefusal(ctrl, undefined, 'an automatic probe cycle positions by machine coordinate.')
  if (probeRefusal) return fail(probeRefusal)
  if (probeCycleActive) return fail('A probe cycle is already running.')
  // WO-1548: positioning moves run on every controller now; a touch that
  // cannot run yet is named before the first of them moves the machine.
  const touchUnsent = probeTouchUnsentHere(
    ctrl,
    `G21 G91 G38.2 Z-${Number(effective.maxTravel.toFixed(4))} F${Number(effective.fastFeed.toFixed(4))}`,
  )
  if (touchUnsent) return fail(touchUnsent)
  // WO-2055 (architect 09-27): the descent to probing depth must stop on
  // contact. A text controller does that only with G38.3, never a plain move,
  // so without it Edge and Angle run the older plan - every touch from the
  // height where the probe stands, no top touch and no descent - and say so.
  let cycle = plan
  if (plan.fromTop && !nativeProbeRoute(ctrl) && !textSetterApproachWordStated()) {
    const beside = plan.fromTop.besideTheFace
    if (!beside.ok) return fail(beside.reason)
    cycle = beside.plan
    store().pushConsole(
      'rx',
      `${FEATURE_PROBE_NAMES[plan.kind]} probe: this controller has no G38.3 probe move that stops on contact, `
        + `so it probes from the height where the probe stands now - ${plan.fromTop.topTouch ? 'no top touch, ' : ''}no descent.`,
      'info',
    )
  }

  const previousUnitsInch = store().parserModal?.units === 'inch'
  const send = (line: string) => probeCycleSend(line, ctrl)
  const n = (value: number) => Number(value.toFixed(4))
  const changed = 'The machine connection changed during the probe cycle.'
  /** WO-2110: the ack means queued, not arrived (the WO-416 finding), and the
   *  next touch's idle gate refused the move this routine had just commanded.
   *  Its 'run' waits for Idle (WO-1998's rule); a hold, alarm or door goes on
   *  to the next step's own gates, which still refuse it. Null when settled. */
  const settleOwnMove = async (label: string): Promise<string | null> => {
    if (ctrl.machineState() === 'run' && !(await waitForProbePositioningIdle(ctrl))) {
      if (!receiptIsCurrent(receiptToken)) return changed
      if (probeCycleStopped()) return PROBE_CYCLE_STOPPED
      if (ctrl.machineState() === 'run') return `${label} did not settle to Idle.`
    }
    return null
  }
  /** One absolute machine-coordinate positioning move. Null on success,
   *  otherwise the failure sentence. */
  const moveTo = async (label: string, target: Partial<MachineVec3>): Promise<string | null> => {
    noteProbeStep(label)
    if (nativeProbeRoute(ctrl)) {
      // WO-1546: the machine-coordinate positioning a G53 line meant, as typed moves.
      const moved = await nativeProbeMachineMove(ctrl, target, n(effective.positioningFeed))
      if (!receiptIsCurrent(receiptToken)) return changed
      return moved ? `${label} stopped: ${moved}.` : null
    }
    const words = (['x', 'y', 'z'] as const)
      .filter((key) => target[key] !== undefined)
      .map((key) => `${key.toUpperCase()}${n(target[key]!)}`)
      .join(' ')
    const ack = await send(`G21 G90 G53 G1 ${words} F${n(effective.positioningFeed)}`)
    if (!receiptIsCurrent(receiptToken)) return changed
    const positionUnsent = unsentReason(ack)
    if (positionUnsent) return `${label} stopped: ${positionUnsent}`
    if (!ack || !ack.ok) return `${label} failed${ack ? ` (${ack.message})` : ': controller refused the move'}.`
    return settleOwnMove(label)
  }
  const guardedDescent = (label: string, fromZ: number, depthZ: number) =>
    guardedZDescent(ctrl, receiptToken, label, fromZ, depthZ, n(effective.fastFeed), changed)
  // WO-2664: Sensed by = Probe touches part - a fine miss names no pad.
  const sensedByPart = probeSensingFor(controlMachineId(), plan.kind) === 'probe'

  setProbeCycleActive(true)
  run = claimProbeCycleRun(`${FEATURE_PROBE_NAMES[plan.kind]} probe`)
  try {
    const fromTop = cycle.fromTop ?? null
    if (fromTop?.topTouch) {
      // WO-2055: the first move touches the top where the operator left the
      // probe. Nothing has moved yet and the machine was idle, so the reported
      // Z is where this search starts and it is held above the Z limit.
      noteProbeStep(fromTop.topTouch.label)
      const top = await executeDirectionalProbeTouch('Z', '-', effective, {
        cycleOwned: true,
        startSettled: true,
        sensedByPart,
        travelMm: fromTop.topTouch.travelMm,
        probeLabel: fromTop.topTouch.label,
        // WO-2108 (Operator 2026-09-27): the search stops at the operator's
        // distance and says it found no top - not "check the probe wiring".
        searchMissMessage: (searchMm) => `no top found within ${machineLengthText(searchMm)} below where the probe started`,
        // WO-2258 (real board 2026-09-30): a miss over a hole left the tip
        // inside it; it now goes back up to where it started first.
        riseToStartOnMiss: true,
      })
      if (!receiptIsCurrent(receiptToken)) return fail(changed)
      if (!top.ok || top.probedMachinePosition === null) {
        return fail(`${fromTop.topTouch.label} stopped: ${top.message}`)
      }
      topMachineZ = top.probedMachinePosition
    } else if (fromTop?.knownTop?.source === 'rim') {
      // WO-2057: the rim the operator touched before Run.
      topMachineZ = fromTop.knownTop.machineZ
    } else if (fromTop?.knownTop?.source === 'workZero') {
      // WO-2057: the hole is in the face work Z0 was probed on. Machine Z of
      // work Z 0 is the controller's own machine Z less its work Z - every
      // offset it applies, read from the same status frame.
      const { machinePos, workPos } = ctrl.status()
      if (!machinePos || !workPos || !Number.isFinite(machinePos.z) || !Number.isFinite(workPos.z)) {
        return fail(
          `${FEATURE_PROBE_NAMES[cycle.kind]} probe: the top is work Z0, but the controller reports no work position, `
            + 'so the depth below it is unknown - nothing moved. Touch the rim first.',
        )
      }
      topMachineZ = n(machinePos.z - workPos.z)
    }
    let lastWall: { axis: 'X' | 'Y'; direction: '+' | '-' } | null = null
    for (const step of cycle.steps) {
      if (step.kind === 'descend' || step.kind === 'rise') {
        // WO-2057: a hole routine's way down and back up, from its known top.
        if (!fromTop || topMachineZ === null) {
          return fail(`${step.label}: the plan works from the top, but it carries no top.`)
        }
        const safeZ = n(topMachineZ + fromTop.clearanceMm)
        const standing = ctrl.status().machinePos?.z
        if (typeof standing !== 'number' || !Number.isFinite(standing)) {
          return fail(`${step.label}: the controller reports no machine position.`)
        }
        if (step.kind === 'rise') {
          if (standing < safeZ) {
            const rise = await moveTo(step.label, { z: safeZ })
            if (rise) return fail(rise)
          }
          continue
        }
        // Below safe height it rises straight up first; above it, it crosses
        // where it stands (higher still) and the guarded descent runs the
        // whole way down - never a plain move toward the part.
        let fromZ = standing
        if (standing < safeZ) {
          const rise = await moveTo(`Rise to safe height before ${step.label}`, { z: safeZ })
          if (rise) return fail(rise)
          fromZ = safeZ
        }
        const over = await moveTo(`Cross over for ${step.label}`, { x: step.target.x, y: step.target.y })
        if (over) return fail(over)
        const depthZ = n(topMachineZ - fromTop.depthMm)
        const descent = await guardedDescent(step.label, fromZ, depthZ)
        if ('failed' in descent) return fail(descent.failed)
        if (descent.touchedZ !== null) {
          const landed = `${step.label}: the descent touched at ${machinePositionText({ z: descent.touchedZ })}, `
            + `above probing depth ${machinePositionText({ z: depthZ })} - start over the open hole, or check the top `
            + `(${fromTop.knownTop?.source === 'rim' ? 'the rim touch' : 'work Z0'}).`
          store().pushConsole('rx', landed, 'warn')
          return fail(landed)
        }
        continue
      }
      if (step.kind === 'position') {
        // WO-2554: a back-off can already pass the starting line in a small
        // hole started off-centre. Never return toward the wall just touched.
        if ((cycle.kind === 'bore' || cycle.kind === 'rectPocket') && lastWall) {
          const key = lastWall.axis.toLowerCase() as 'x' | 'y'
          const standing = ctrl.status().machinePos?.[key]
          if (typeof standing === 'number' && (step.target[key] - standing) * (lastWall.direction === '+' ? 1 : -1) > 0) continue
        }
        const target: Partial<MachineVec3> = {}
        for (const axis of step.axes) {
          const key = axis.toLowerCase() as keyof MachineVec3
          target[key] = step.target[key]
        }
        const moved = await moveTo(step.label, target)
        if (moved) return fail(moved)
        continue
      }
      let safeZ: number | null = null
      if (step.descendFromTop) {
        if (!fromTop || topMachineZ === null) {
          return fail(`${step.label}: the plan works from the top, but it carries no top touch.`)
        }
        safeZ = n(topMachineZ + fromTop.clearanceMm)
        const depthZ = n(topMachineZ - fromTop.depthMm)
        // WO-2266: a top it did not touch (Boss / Rect boss on work Z0) is
        // approached as a hole routine's: above safe height it steps out where
        // it stands and the guarded descent runs the whole way down - never a
        // plain move toward the part. After a top touch it is always below.
        const standing = fromTop.topTouch ? null : ctrl.status().machinePos?.z
        let fromZ = safeZ
        if (typeof standing === 'number' && Number.isFinite(standing) && standing > safeZ) {
          fromZ = n(standing)
        } else {
          const rise = await moveTo(`Rise to safe height before ${step.label}`, { z: safeZ })
          if (rise) return fail(rise)
        }
        const out = await moveTo(`Step out for ${step.label}`, { x: step.expectedStart.x, y: step.expectedStart.y })
        if (out) return fail(out)
        const descent = await guardedDescent(`Descend to probing depth for ${step.label}`, fromZ, depthZ)
        if ('failed' in descent) return fail(descent.failed)
        if (descent.touchedZ !== null) {
          // Nothing refused up front (rule 11): the descent is bounded, and
          // when it lands on the part it stops there and says so.
          const landed = `${step.label}: the descent touched at ${machinePositionText({ z: descent.touchedZ })}, `
            + `above probing depth ${machinePositionText({ z: depthZ })} - start closer to the edge.`
          store().pushConsole('rx', landed, 'warn')
          return fail(landed)
        }
      }
      noteProbeStep(step.label)
      let travelMm = step.travelMm
      const key = step.axis.toLowerCase() as 'x' | 'y'
      const bounds = cycle.internalSearchEnvelope?.[key]
      const standing = ctrl.status().machinePos?.[key]
      if (bounds && typeof standing === 'number') {
        const room = step.direction === '+' ? bounds.max - standing : standing - bounds.min
        travelMm = n(Math.min(travelMm, Math.max(0, room)))
        if (!(travelMm > 0)) return fail(`${step.label} stopped: no wall found before the ${step.axis}${step.direction} machine limit.`)
      }
      const result = await executeDirectionalProbeTouch(step.axis, step.direction, effective, {
        cycleOwned: true,
        sensedByPart,
        travelMm,
        ...((cycle.kind === 'bore' || cycle.kind === 'rectPocket' || cycle.kind === 'insideCorner') ? {
          searchMissMessage: (searchMm: number) => `no wall found within ${machineLengthText(searchMm)} along ${step.axis}${step.direction}`,
        } : {}),
      })
      if (!receiptIsCurrent(receiptToken)) return fail(changed)
      if (!result.ok || result.probedMachinePosition === null) {
        return fail(`${step.label} stopped: ${result.message}`)
      }
      lastWall = { axis: step.axis, direction: step.direction }
      touches[step.key] = result.probedMachinePosition
      onTouch?.(step.key, result.probedMachinePosition)
      if (safeZ !== null) {
        const rise = await moveTo(`Rise to safe height after ${step.label}`, { z: safeZ })
        if (rise) return fail(rise)
      }
      // WO-2116: the touch ends with its own retract off the contact, acked
      // when queued. Inside corner's Y touch follows its X touch with no move
      // between them, and its idle gate refused that retract.
      const retracted = await settleOwnMove(step.label)
      if (retracted) return fail(retracted)
    }
    if (run.stopped) return fail(PROBE_CYCLE_STOPPED)
    return {
      ok: true,
      message: `${plan.kind} cycle recorded ${Object.keys(touches).length} touch${Object.keys(touches).length === 1 ? '' : 'es'}.`,
      touches,
      topMachineZ,
    }
  } finally {
    await run?.cancelMotion
    setProbeCycleActive(false)
    releaseProbeCycleRun(run)
    if (receiptIsCurrent(receiptToken) && ctrl.machineState() !== 'alarm' && ctrl.connectionPhase() === 'connected') {
      sendAppCommand('G90', ctrl)
      if (previousUnitsInch) sendAppCommand('G20', ctrl)
      ctrl.refreshState()
    }
  }
}


// ---------------------------------------------------------------------------
// WO-411 slice 3 - the probe ROUTINE runner (MACHINE CODE).
//
// Executes an EXPANDED routine through the controller contract's typed motion
// verbs. There is deliberately no G-code rendering in this path: every backend
// receives the same jog/probe intent, including the AXBB bridge whose controller
// has no text interpreter. Calcs, checks and branches are re-evaluated with the
// REAL contacts; a touch-dependent move endpoint is re-evaluated and envelope-
// checked before its typed move is issued. The runner writes NOTHING: it returns
// touches, calcs and EVALUATED proposals, and the Confirm button in the Routines
// tab stays the only writer (setWorkOffsetValue, confirmProbeRoutineToolLength).
// ---------------------------------------------------------------------------

interface ProbeRoutineRunTouch {
  name: string
  axis: 'X' | 'Y' | 'Z'
  /** Machine mm of the fine-pass contact on the probed axis. */
  positionMm: number
  /** The full contact point: tracked position with the probed axis replaced. */
  contact: ExpandPoint
}

export type ProbeRoutineEvaluatedProposal =
  | {
      kind: 'workOffset'
      wcs: string
      activeWcs: string | null
      /** Machine mm per axis, evaluated with the real contacts. */
      axes: Partial<Record<'X' | 'Y' | 'Z', number>>
      label: string
      compensationNote: string | null
    }
  | { kind: 'toolLength'; tool: 'active' | number; machineZ: number; label: string }
  | { kind: 'report'; items: Array<{ label: string; value: number; unit: string }> }

export interface ProbeRoutineRunResult {
  ok: boolean
  /** Plain-language outcome / recovery text. Names the step that stopped the run. */
  message: string
  /** The step (1-based number, label) the run stopped at, or null when it finished. */
  stoppedAt: { number: number; label: string } | null
  touches: ProbeRoutineRunTouch[]
  calcs: Record<string, number>
  /** Only on ok: every output evaluated with the real contacts. Empty otherwise. */
  proposals: ProbeRoutineEvaluatedProposal[]
  /** WO-2071: Stop/Reset ended it; `message` is the stopped sentence. */
  stopped?: true
}

export type ProbeRoutineRunEvent =
  /** WO-1667: a move is about to be sent. `target` is machine coordinates;
   *  `frame` is the active work frame, so the row can state both. */
  | { kind: 'moving'; step: ExpandedStep; target: Partial<ExpandPoint>; frame: ActiveWorkFrame }
  | { kind: 'move'; step: ExpandedStep; target: ExpandPoint }
  | { kind: 'touch'; step: ExpandedStep; touch: ProbeRoutineRunTouch; frame: ActiveWorkFrame }
  | { kind: 'calc'; step: ExpandedStep; name: string; value: number }
  | { kind: 'check'; step: ExpandedStep; passed: boolean }
  | { kind: 'branch'; step: ExpandedStep; arm: 'then' | 'else' }

interface ProbeRoutineRunOptions {
  /** The live machine envelope the preview was checked against; a touch-
   *  dependent endpoint is re-checked against it before the move is sent. */
  envelope: MachineEnvelope
  onStep?: (event: ProbeRoutineRunEvent) => void
}

export const PROBE_ROUTINE_PREVIEW_STALE =
  'The preview is out of date (the routine, its inputs, the start position or the probe settings changed since you checked it). Check it again before running.'

const PROBE_ROUTINE_MOVE_TIMEOUT_MS = 30_000
const PROBE_ROUTINE_TARGET_TOLERANCE_MM = 0.01
const PROBE_ROUTINE_STABLE_TOLERANCE_MM = 0.0001

function allExpandedSteps(steps: readonly ExpandedStep[]): ExpandedStep[] {
  const out: ExpandedStep[] = []
  for (const step of steps) {
    out.push(step)
    if (step.kind === 'branch') {
      out.push(...allExpandedSteps(step.then), ...allExpandedSteps(step.else))
    }
  }
  return out
}

/**
 * Static/live preflight for the typed doors a routine needs. This is exported
 * so the Run control can carry the exact same refusal in its title. A move that
 * combines Z with X/Y is not split: doing so would replace one previewed line
 * with a different dog-leg path.
 */
export function probeRoutineExecutionRefusal(
  expanded: ExpandedRoutine,
  ctrl: MachineController = getMachineController(),
): string | null {
  for (const step of allExpandedSteps(expanded.steps)) {
    if (step.kind === 'move') {
      const movesXY = step.axes.some((axis) => axis === 'X' || axis === 'Y')
      const movesZ = step.axes.includes('Z')
      if (!movesXY && !movesZ) {
        return `${step.label}: this move names no executable axis.`
      }
      if (step.stopOnContact && movesXY) {
        // WO-2088: an angled or sideways move that stops on contact. On a
        // controller that takes text it is one G38.3 line along the straight
        // path (GRBL and LinuxCNC probe along any X/Y/Z line). The native probe
        // call is UC100 ProbeStart(Axis, ...): one axis per call.
        if (nativeProbeRoute(ctrl) && step.axes.length > 1) {
          return `${step.label}: this controller's probe call moves one axis at a time, so it cannot make one straight `
            + `${step.axes.join(' ')} move that stops on contact.`
        }
        continue
      }
      if (movesXY && movesZ) {
        return `${step.label}: this controller has separate XY and Z move verbs, so it cannot execute one combined XYZ move without changing the previewed path.`
      }
      if (movesXY && typeof ctrl.jogToWorkXY !== 'function') {
        return `${step.label}: this controller has no typed work-frame XY move verb.`
      }
      if (movesZ && typeof ctrl.jogToMachineZ !== 'function') {
        return `${step.label}: this controller has no typed machine-frame Z move verb.`
      }
    }
    if (step.kind === 'touch') {
      if (typeof ctrl.probe !== 'function') {
        return `${step.label}: this controller has no typed probe verb.`
      }
      if (typeof ctrl.jog !== 'function') {
        return `${step.label}: this controller has no typed jog verb for the probe retract and back-off.`
      }
    }
  }

  // A move that stops on contact goes in the machine frame (the probe call or
  // relative G38.3), never by the work-frame XY verb.
  const firstXY = allExpandedSteps(expanded.steps).find(
    (step) => step.kind === 'move' && !step.stopOnContact && step.axes.some((axis) => axis === 'X' || axis === 'Y'),
  )
  if (firstXY?.kind === 'move') {
    const zeroRefusal = workGotoZeroRefusal(['X', 'Y'])
    if (zeroRefusal) return `${firstXY.label}: ${zeroRefusal}`
    const status = ctrl.status()
    if (status.machinePos === null || status.workPos === null) {
      return `${firstXY.label}: the controller has not reported both machine and work position, so its machine endpoint cannot be translated to the typed work-frame XY move.`
    }
  }
  return null
}

function sameMachinePosition(a: MachineVec3, b: MachineVec3): boolean {
  return (['x', 'y', 'z'] as const).every(
    (axis) => Math.abs(a[axis] - b[axis]) <= PROBE_ROUTINE_STABLE_TOLERANCE_MM,
  )
}

async function waitForProbeRoutineMove(
  ctrl: MachineController,
  target: Partial<MachineVec3>,
  timeoutMs = PROBE_ROUTINE_MOVE_TIMEOUT_MS,
): Promise<boolean> {
  const receiptToken = captureBackendReceipt(ctrl)
  let deadline = sessionElapsedNowMs() + timeoutMs
  let previous: MachineVec3 | null = null
  let stableFrames = 0
  const run = activeProbeCycle
  let epoch = run?.pauseEpoch
  while (sessionElapsedNowMs() < deadline) {
    ctrl.queryStatus()
    const before = sessionElapsedNowMs()
    await new Promise((resolve) => setTimeout(resolve, 50))
    if (!receiptIsCurrent(receiptToken)) return false
    if (probeCycleStopped()) return false
    // WO-2517: the frame this wait reads is watched like any other.
    watchProbeInput(ctrl, ctrl.status())
    if (probeCycleStopped()) return false
    if (ctrl.connectionPhase() !== 'connected' || ctrl.machineState() === 'alarm') return false
    // WO-2103: time the operator holds the machine is not time the move took.
    if (probeCycleHeldByOperator(ctrl)) {
      deadline += sessionElapsedNowMs() - before
      continue
    }
    if (run && run.pauseEpoch !== epoch) {
      if (!ctrl.verifiedIdle()) continue
      epoch = run.pauseEpoch
      if (run.resumeMove && !run.resumeMove()) return false
      previous = null
      stableFrames = 0
      continue
    }
    const position = ctrl.status().machinePos
    const atTarget = position !== null && (Object.keys(target) as Array<keyof MachineVec3>).every(
      (axis) => Math.abs(position[axis] - target[axis]!) <= PROBE_ROUTINE_TARGET_TOLERANCE_MM,
    )
    if (!ctrl.verifiedIdle() || position === null || !atTarget) {
      previous = position
      stableFrames = 0
      continue
    }
    stableFrames = previous !== null && sameMachinePosition(previous, position) ? stableFrames + 1 : 1
    previous = position
    if (stableFrames >= 2) {
      noteProbeMotionSettled(ctrl)
      return !probeCycleStopped()
    }
  }
  return false
}

function round4Value(value: number): number {
  return Number(value.toFixed(4))
}

/**
 * Run one expanded probe routine under one authority lock. Shaped exactly like
 * runFeatureProbeCycle: the same gates in the same order (path-clear, E-stop
 * latch, config valid, connected, no job, idle, homed, no other cycle). Refuses
 * before ANY motion when the preview hash is stale, the controller lacks a
 * required typed verb, or a touch asks for a retract / back-off / feed different
 * from the preview (the preview must show exactly what the machine will do).
 */
export async function runProbeRoutine(
  expanded: ExpandedRoutine,
  config: ZProbeConfig,
  pathClearConfirmed: boolean,
  previewHash: string,
  options: ProbeRoutineRunOptions,
): Promise<ProbeRoutineRunResult> {
  const programOwned = store().toolChange !== null || programPartsRun !== null || loadedProgramText() !== null
  const receipt = captureBackendReceipt(getMachineController())
  const result = await runProbeRoutineOnce(expanded, config, pathClearConfirmed, previewHash, options)
  if (!programOwned && receiptIsCurrent(receipt)) publishProbeActionResult(result, 'Probe routine')
  return result
}

async function runProbeRoutineOnce(
  expanded: ExpandedRoutine,
  config: ZProbeConfig,
  pathClearConfirmed: boolean,
  previewHash: string,
  options: ProbeRoutineRunOptions,
): Promise<ProbeRoutineRunResult> {
  const touches: ProbeRoutineRunTouch[] = []
  const calcs: Record<string, number> = {}
  let cycleRun: ProbeCycleRun | null = null
  const failWith = (message: string, step: ExpandedStep | null, stopped: boolean): ProbeRoutineRunResult => ({
    ok: false,
    message,
    stoppedAt: step ? { number: step.number, label: step.label } : null,
    touches,
    calcs,
    proposals: [],
    ...(stopped ? { stopped: true as const } : {}),
  })
  // WO-2533: a stopped run says so once the move it stopped has come to rest.
  const fail = (
    message: string,
    step: ExpandedStep | null = null,
  ): ProbeRoutineRunResult | Promise<ProbeRoutineRunResult> => (cycleRun?.stopped
    ? probeCycleStoppedMessageAtRest(cycleRun).then((said) => failWith(said, step, true))
    : failWith(message, step, false))
  if (!pathClearConfirmed) {
    return fail('Confirm that the positioning path and cross-over lift are clear before running.')
  }
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  const valid = validateZProbeConfig(config)
  if (!valid.ok) return fail(valid.reason)
  const effective = resolveProbeConfig(null, config)
  if (previewHash !== expanded.hash) return fail(PROBE_ROUTINE_PREVIEW_STALE)
  // The preview promised these numbers; the touch primitive sends the
  // profile's. Anything else would run differently from what was shown.
  const profileMismatch = (step: ExpandedStep): string | null => {
    if (step.kind !== 'touch') return null
    if (Math.abs(step.retractMm - effective.retract) > 1e-6) {
      return `${step.label}: a retract of ${machineLengthText(step.retractMm)} differs from the profile's ${machineLengthText(effective.retract)} - this build sends only the profile's retract.`
    }
    if (Math.abs(step.backoffMm - effective.retract) > 1e-6) {
      return `${step.label}: a back-off of ${machineLengthText(step.backoffMm)} differs from the profile's ${machineLengthText(effective.retract)} - this build sends only the profile's back-off.`
    }
    if (Math.abs(step.searchFeedMmMin - effective.fastFeed) > 1e-6) {
      return `${step.label}: the previewed search feed ${step.searchFeedMmMin} mm/min differs from the profile's ${effective.fastFeed} mm/min - this build sends only the profile's search feed.`
    }
    if (Math.abs(step.finalFeedMmMin - effective.slowFeed) > 1e-6) {
      return `${step.label}: the previewed final feed ${step.finalFeedMmMin} mm/min differs from the profile's ${effective.slowFeed} mm/min - this build sends only the profile's final feed.`
    }
    return null
  }
  const walk = (steps: readonly ExpandedStep[]): string | null => {
    for (const step of steps) {
      const m = profileMismatch(step)
      if (m) return m
      if (step.kind === 'branch') {
        const inner = walk(step.then) ?? walk(step.else)
        if (inner) return inner
      }
    }
    return null
  }
  const mismatch = walk(expanded.steps)
  if (mismatch) return fail(mismatch)

  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const executionRefusal = probeRoutineExecutionRefusal(expanded, ctrl)
  if (executionRefusal) {
    store().pushConsole('tx', `Probe routine: refused - ${executionRefusal}`, 'error')
    return fail(executionRefusal)
  }
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  if (ctrl.hasActiveJob()) return fail('A program is running - probing is locked out.')
  if (ctrl.machineState() !== 'idle') return fail('The machine must be idle to start a probe cycle.')
  // ALL THREE. Positioning steps are absolute `G53 G1` moves, so any axis a
  // routine names must have a datum - and the cycle runs unattended once
  // started, which is why this is the conservative reading rather than the
  // per-step one.
  const probeRefusal = homingRefusal(ctrl, undefined, 'an automatic probe cycle positions by machine coordinate (G53).')
  if (probeRefusal) return fail(probeRefusal)
  if (probeCycleActive) return fail('A probe cycle is already running.')

  // The expression scope the runner evaluates with: inputs (numbers), the
  // profile namespace the preview saw, the start, and the REAL contacts.
  const numericInputs: Record<string, number> = {}
  for (const [k, v] of Object.entries(expanded.inputs)) if (typeof v === 'number') numericInputs[k] = v
  const scope: {
    input: Record<string, number>
    touch: Record<string, { x: number; y: number; z: number; value: number }>
    calc: Record<string, number>
    probe: ExprEvalScope['probe']
    start: ExpandPoint
  } = {
    input: numericInputs,
    touch: {},
    calc: calcs,
    probe: {
      tipRadiusMm: expanded.profile.tipRadiusMm,
      retractMm: expanded.profile.retractMm,
      surfaceClearanceMm: expanded.profile.surfaceClearanceMm,
      overtravelMm: expanded.profile.overtravelMm,
      maxTravelMm: expanded.profile.maxTravelMm,
      crossOverLiftMm: expanded.profile.crossOverLiftMm,
    },
    start: { ...expanded.start },
  }
  const evalNumber = (ast: ExprAst): { ok: true; value: number } | { ok: false; fault: string } => {
    const r = evaluateExpr(ast, scope)
    return r.ok ? { ok: true, value: r.value } : { ok: false, fault: r.fault.sentence }
  }

  const n = (value: number) => Number(value.toFixed(4))
  const envelope = options.envelope
  let position: ExpandPoint = { ...expanded.start }
  const previousUnitsInch = store().parserModal?.units === 'inch'
  const changed = 'The machine connection changed during the probe routine.'
  /** True once a guarded descent went out as G91 text: the finally puts G90 back. */
  let textDescentSent = false
  /**
   * WO-2073: a routine's descent that stops on contact - the feature cycles'
   * guarded descent (the native probe call, or G38.3 on the text route), never
   * a plain move. Meeting nothing, it ends at its target. Meeting the part, it
   * stops there, backs off the previewed retract and the routine carries on
   * with that Z known (touch.<name>). Null when the routine carries on.
   */
  const runGuardedStep = async (step: ExpandedMoveStep, target: ExpandPoint): Promise<ProbeRoutineRunResult | null> => {
    if (step.axes.some((axis) => axis === 'X' || axis === 'Y')) return runGuardedLine(step, target)
    const standing = ctrl.status().machinePos?.z
    const fromZ = typeof standing === 'number' && Number.isFinite(standing) ? standing : position.z
    if (!(target.z < fromZ)) {
      return fail(
        `${step.label}: the descent would end at ${machinePositionText({ z: target.z })}, not below where the probe stands `
          + `(${machinePositionText({ z: fromZ })}) - a move that stops on contact only goes down. The run stopped before that move.`,
        step,
      )
    }
    if (!nativeProbeRoute(ctrl) && !textSetterApproachWordStated()) {
      // What the feature cycles do on such a controller (WO-2055): no descent, and say so.
      store().pushConsole(
        'rx',
        `${expanded.routineName}: ${step.label} - this controller has no G38.3 probe move that stops on contact, `
          + 'so it does not descend; the routine carries on from the height where the probe stands.',
        'info',
      )
      return null
    }
    options.onStep?.({ kind: 'moving', step, target: { z: target.z }, frame: activeWorkFrame() })
    if (!nativeProbeRoute(ctrl)) textDescentSent = true
    const descent = await guardedZDescent(
      ctrl, receiptToken, `step ${step.number} (${step.label})`, fromZ, target.z, step.feedMmMin, changed,
    )
    if ('failed' in descent) return fail(descent.failed, step)
    if (descent.touchedZ === null) {
      position = { ...position, z: target.z }
      if (step.name) scope.touch[step.name] = { x: position.x, y: position.y, z: target.z, value: target.z }
      options.onStep?.({ kind: 'move', step, target: position })
      return null
    }
    const contact: ExpandPoint = { x: position.x, y: position.y, z: descent.touchedZ }
    const touch: ProbeRoutineRunTouch = { name: step.name ?? step.label, axis: 'Z', positionMm: contact.z, contact }
    touches.push(touch)
    if (step.name) scope.touch[step.name] = { x: contact.x, y: contact.y, z: contact.z, value: contact.z }
    const retract = step.contactRetractMm ?? effective.retract
    store().pushConsole(
      'rx',
      `${step.label}: touched at ${machinePositionText({ z: contact.z })}, above its target ${machinePositionText({ z: target.z })} `
        + `- backing off ${machineLengthText(retract)} and carrying on.`,
      'info',
    )
    options.onStep?.({ kind: 'touch', step, touch, frame: activeWorkFrame() })
    const riseZ = n(contact.z + retract)
    // WO-2138: a Feed Hold between the moves holds the back-off until CYCLE START.
    if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
    if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
    if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
    noteProbePhase('the back-off')
    if (probeInputBlocksMove(ctrl, probeCycleMoveText({ z: riseZ }))) return fail(PROBE_CYCLE_STOPPED, step)
    if (!ctrl.jogToMachineZ(riseZ, effective.positioningFeed)) {
      return fail(`${step.label} stopped: the controller refused the typed back-off.`, step)
    }
    if (!(await waitForProbeRoutineMove(ctrl, { z: riseZ }))) {
      if (!receiptIsCurrent(receiptToken)) return fail(changed, step)
      return fail(`${step.label} stopped: the back-off did not settle idle across two status frames.`, step)
    }
    position = { ...contact, z: riseZ }
    options.onStep?.({ kind: 'move', step, target: position })
    return null
  }

  /**
   * WO-2088: a move that stops on contact and travels in X and/or Y - angled
   * or sideways. It runs as a probe move at the previewed search feed along
   * the straight line to its target (guardedLineMove). Meeting nothing, it
   * ends at its target. Meeting the part, it stops there, backs off the
   * previewed retract straight back along its path and the routine carries on
   * with the contact known as touch.<name>.
   */
  const runGuardedLine = async (step: ExpandedMoveStep, target: ExpandPoint): Promise<ProbeRoutineRunResult | null> => {
    const standing = ctrl.status().machinePos
    const from: ExpandPoint = standing && [standing.x, standing.y, standing.z].every(Number.isFinite)
      ? { x: standing.x, y: standing.y, z: standing.z }
      : { ...position }
    const keys = step.axes.map((axis) => axis.toLowerCase() as ExpandAxisKey)
    const moved: Partial<ExpandPoint> = {}
    for (const key of keys) moved[key] = target[key]
    if (!nativeProbeRoute(ctrl) && !textSetterApproachWordStated()) {
      // As a descent on such a controller (WO-2073): no move, and say so.
      store().pushConsole(
        'rx',
        `${expanded.routineName}: ${step.label} - this controller has no G38.3 probe move that stops on contact, `
          + 'so it does not make this move; the routine carries on from where the probe stands.',
        'info',
      )
      return null
    }
    options.onStep?.({ kind: 'moving', step, target: moved, frame: activeWorkFrame() })
    if (!nativeProbeRoute(ctrl)) textDescentSent = true
    const line = await guardedLineMove(
      ctrl, receiptToken, `step ${step.number} (${step.label})`, from, target, step.axes, step.feedMmMin, changed,
    )
    if ('failed' in line) return fail(line.failed, step)
    if (line.contact === null) {
      position = { ...position, ...moved }
      if (step.name) scope.touch[step.name] = { x: position.x, y: position.y, z: position.z, value: position.z }
      options.onStep?.({ kind: 'move', step, target: position })
      return null
    }
    const contact: ExpandPoint = { ...line.contact }
    // The probed axis: the one it moved, else Z when it descends too, else the first.
    const axis: ProbeAxis = step.axes.length === 1 ? step.axes[0] : step.axes.includes('Z') ? 'Z' : step.axes[0]
    const touch: ProbeRoutineRunTouch = { name: step.name ?? step.label, axis, positionMm: contact[axis.toLowerCase() as ExpandAxisKey], contact }
    touches.push(touch)
    if (step.name) scope.touch[step.name] = { x: contact.x, y: contact.y, z: contact.z, value: contact.z }
    const retract = step.contactRetractMm ?? effective.retract
    // Straight back toward where it came from, the retract's length.
    const length = Math.hypot(...keys.map((key) => target[key] - from[key]))
    const back: ExpandPoint = { ...contact }
    for (const key of keys) back[key] = n(contact[key] - ((target[key] - from[key]) / length) * retract)
    const at = (p: ExpandPoint) => {
      const out: Partial<ExpandPoint> = {}
      for (const key of keys) out[key] = n(p[key])
      return out
    }
    store().pushConsole(
      'rx',
      `${step.label}: touched at ${machinePositionText(at(contact))}, before its target ${machinePositionText(moved)} `
        + `- backing off ${machineLengthText(retract)} along its path and carrying on.`,
      'info',
    )
    options.onStep?.({ kind: 'touch', step, touch, frame: activeWorkFrame() })
    if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
    if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
    if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
    noteProbePhase('the back-off')
    // To the machine point `back`, never a distance from where it stopped: a
    // real controller decelerates past the trip point, so a relative back-off
    // would land short of it by that overshoot (WO-2088 audit).
    if (nativeProbeRoute(ctrl)) {
      const status = ctrl.status()
      if (status.machinePos === null || status.workPos === null) {
        return fail(`${step.label} stopped: the controller has not reported both machine and work position for the back-off.`, step)
      }
      const x = keys.includes('x') ? back.x : status.machinePos.x
      const y = keys.includes('y') ? back.y : status.machinePos.y
      // WO-2203: the machine point `back`, whatever the work rotation.
      const work = workXYForMachineXY(status, x, y, n)
      if (probeInputBlocksMove(ctrl, probeCycleMoveText({ x, y }))) return fail(PROBE_CYCLE_STOPPED, step)
      if (!ctrl.jogToWorkXY(work.x, work.y, effective.positioningFeed)) {
        return fail(`${step.label} stopped: the controller refused the typed back-off.`, step)
      }
    } else {
      const words = keys.map((key) => `${key.toUpperCase()}${n(back[key])}`).join(' ')
      const ack = await probeCycleSend(`G21 G90 G53 G1 ${words} F${n(effective.positioningFeed)}`, ctrl)
      if (!receiptIsCurrent(receiptToken)) return fail(changed, step)
      if (!ack) return fail(`${step.label} stopped: the controller refused the typed back-off.`, step)
      const unsent = unsentReason(ack)
      if (unsent) return fail(`${step.label} stopped: ${unsent}`, step)
      if (!ack.ok) return fail(`${step.label} stopped: the controller refused the back-off (${ack.message ?? 'refused'}).`, step)
    }
    if (!(await waitForProbeRoutineMove(ctrl, at(back)))) {
      if (!receiptIsCurrent(receiptToken)) return fail(changed, step)
      return fail(`${step.label} stopped: the back-off did not settle idle across two status frames.`, step)
    }
    position = back
    options.onStep?.({ kind: 'move', step, target: position })
    return null
  }

  setProbeCycleActive(true)
  cycleRun = claimProbeCycleRun(expanded.routineName)
  try {
    const run = async (steps: readonly ExpandedStep[]): Promise<ProbeRoutineRunResult | null> => {
      for (const step of steps) {
        noteProbeStep(`step ${step.number} (${step.label})`)
        if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
        // The routine owns the cycle lock, but it does not own the E-STOP or
        // controller state. Re-check those live gates at every expanded step;
        // the old G-code runner got the same per-touch checks by entering the
        // shared touch primitive once for each touch.
        if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
        // WO-2103: a Feed Hold between steps pauses the routine here.
        await waitOutProbeCycleHold(ctrl)
        if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
        if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
        if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.', step)
        if (ctrl.machineState() !== 'idle') return fail('The machine must be idle to continue the probe cycle.', step)
        if (step.kind === 'move') {
          let target: ExpandPoint = { ...step.target }
          if (step.touchDependent) {
            // Re-evaluate the endpoint with the real contacts and re-check it.
            target = { ...position }
            for (const key of ['x', 'y', 'z'] as ExpandAxisKey[]) {
              const expr = step.exprs[key]
              if (!expr) continue
              const r = evalNumber(expr.ast)
              if (!r.ok) return fail(`${step.label}: ${r.fault}`, step)
              target[key] = n(step.frame === 'start' ? expanded.start[key] + r.value : r.value)
            }
            const outside = pointOutsideEnvelope(target, envelope)
            if (outside) {
              return fail(
                `${step.label}: with the real contacts the endpoint (${machinePositionText(target)}) is outside the table - ${outside}. The run stopped before that move.`,
                step,
              )
            }
          }
          if (step.stopOnContact) {
            const guarded = await runGuardedStep(step, target)
            if (guarded) return guarded
            continue
          }
          const movesXY = step.axes.some((axis) => axis === 'X' || axis === 'Y')
          const moved = movesXY ? { x: target.x, y: target.y } : { z: target.z }
          if (probeInputBlocksMove(ctrl, probeCycleMoveText(moved))) return fail(PROBE_CYCLE_STOPPED, step)
          options.onStep?.({ kind: 'moving', step, target: moved, frame: activeWorkFrame() })
          const accepted = movesXY
            ? (() => {
                const status = ctrl.status()
                if (status.machinePos === null || status.workPos === null) return false
                // WO-2203: a machine target, whatever the work rotation.
                // WO-2212: LinuxCNC's rotation is in its report, not the frame.
                const work = workXYForMachineXY(status, target.x, target.y, n, controllerWorkRotation(ctrl, status))
                return ctrl.jogToWorkXY(work.x, work.y, step.feedMmMin)
              })()
            : ctrl.jogToMachineZ(target.z, step.feedMmMin)
          if (!accepted) return fail(`${step.label} failed: the controller refused the typed move.`, step)
          const completionTarget = movesXY ? { x: target.x, y: target.y } : { z: target.z }
          if (!(await waitForProbeRoutineMove(ctrl, completionTarget))) {
            if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
            return fail(`${step.label} did not reach its target and settle idle across two status frames.`, step)
          }
          // WO-2073 audit: only the axes this move sent change. The axes it does
          // not name keep the live position (a contact's backed-off Z), never
          // the plan's nominal value.
          position = { ...position, ...completionTarget }
          options.onStep?.({ kind: 'move', step, target: position })
          continue
        }
        if (step.kind === 'touch') {
          let searchMm = step.searchMm
          // WO-2554: real-contact branch returns can leave the start different
          // from the preview. Bound each wall seek from that live position.
          if (step.touchDependent || step.axis !== 'Z') {
            const r = evalNumber(step.searchExpr.ast)
            if (!r.ok) return fail(`${step.label}: ${r.fault}`, step)
            searchMm = n(r.value)
            if (!(searchMm > 0) || searchMm > effective.maxTravel + 1e-9) {
              return fail(`${step.label}: with the real contacts the search would be ${machineLengthText(searchMm)}; it must be more than 0 and no more than ${machineLengthText(effective.maxTravel)}.`, step)
            }
            searchMm = n(boundProbeRoutineWallSearch(step.axis, step.direction, searchMm, position, envelope))
            if (!(searchMm > 0)) {
              return fail(`${step.label} stopped: no wall found before the ${step.axis}${step.direction} machine limit.`, step)
            }
            const key = step.axis.toLowerCase() as ExpandAxisKey
            const far = { ...position, [key]: n(position[key] + (step.direction === '+' ? 1 : -1) * searchMm) }
            const outside = pointOutsideEnvelope(far, envelope)
            if (outside) return fail(`${step.label}: with the real contacts the far end of the search is outside the table - ${outside}.`, step)
          }
          const key = step.axis.toLowerCase() as ExpandAxisKey
          const direction = step.direction === '+' ? 1 : -1
          const searchTarget = n(position[key] + direction * searchMm)
          noteProbePhase('the search')
          const fast = await probeCallUnlessStopped(ctrl, step.axis, searchTarget, step.searchFeedMmMin)
          if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
          if (fast === null) return fail(PROBE_CYCLE_STOPPED, step)
          if (!fast.ok || fast.at === null) {
            return fail(
              fast.reason
                ? nativeProbeFailureMessage(fast.reason, `${step.label} stopped`)
                : `${step.label} stopped: the search pass found no probe contact.`,
              step,
            )
          }

          const fastContact = { ...fast.at }
          const retractTarget = n(fastContact[key] - direction * step.retractMm)
          // WO-2138: a Feed Hold between the moves holds the retract until CYCLE START.
          if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
          if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
          if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
          noteProbePhase('the retract between passes')
          if (probeInputBlocksMove(ctrl, probeCycleMoveText({ [key]: retractTarget }))) return fail(PROBE_CYCLE_STOPPED, step)
          if (!ctrl.jog(step.axis, -direction * step.retractMm, effective.positioningFeed)) {
            return fail(`${step.label} stopped: the controller refused the typed retract.`, step)
          }
          if (!(await waitForProbeRoutineMove(ctrl, { [key]: retractTarget }))) {
            if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
            return fail(`${step.label} stopped: the retract did not settle idle across two status frames.`, step)
          }

          const fineTarget = n(fastContact[key] + direction * step.retractMm)
          if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
          noteProbePhase('the fine pass')
          const fine = await probeCallUnlessStopped(ctrl, step.axis, fineTarget, step.finalFeedMmMin)
          if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
          if (fine === null) return fail(PROBE_CYCLE_STOPPED, step)
          if (!fine.ok || fine.at === null) {
            return fail(
              fine.reason
                ? nativeProbeFailureMessage(fine.reason, `${step.label} stopped`)
                : `${step.label} stopped: the fine pass lost probe contact.`,
              step,
            )
          }
          const contact: ExpandPoint = { ...fine.at }
          const touch: ProbeRoutineRunTouch = {
            name: step.name,
            axis: step.axis,
            positionMm: contact[key],
            contact,
          }
          touches.push(touch)
          scope.touch[step.name] = { x: contact.x, y: contact.y, z: contact.z, value: contact[key] }
          const backoffTarget = n(contact[key] - direction * step.backoffMm)
          if (probeCycleHeldByOperator(ctrl)) await waitOutProbeCycleHold(ctrl)
          if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION, step)
          if (probeCycleStopped()) return fail(PROBE_CYCLE_STOPPED, step)
          noteProbePhase('the back-off')
          if (probeInputBlocksMove(ctrl, probeCycleMoveText({ [key]: backoffTarget }))) return fail(PROBE_CYCLE_STOPPED, step)
          if (!ctrl.jog(step.axis, -direction * step.backoffMm, effective.positioningFeed)) {
            return fail(`${step.label} stopped: the controller refused the typed back-off.`, step)
          }
          if (!(await waitForProbeRoutineMove(ctrl, { [key]: backoffTarget }))) {
            if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
            return fail(`${step.label} stopped: the back-off did not settle idle across two status frames.`, step)
          }
          position = { ...contact, [key]: backoffTarget }
          options.onStep?.({ kind: 'touch', step, touch, frame: activeWorkFrame() })
          continue
        }
        if (step.kind === 'calc') {
          const r = evalNumber(step.ast)
          if (!r.ok) return fail(`${step.label}: ${r.fault}`, step)
          calcs[step.name] = r.value
          options.onStep?.({ kind: 'calc', step, name: step.name, value: r.value })
          continue
        }
        if (step.kind === 'check') {
          const r = evaluateExpandedCondition(step.condition, scope)
          if (!r.ok) return fail(`${step.label}: ${r.fault}`, step)
          options.onStep?.({ kind: 'check', step, passed: r.result })
          if (!r.result) return fail(`${step.label}: ${step.message}`, step)
          continue
        }
        // branch
        const r = evaluateExpandedCondition(step.condition, scope)
        if (!r.ok) return fail(`${step.label}: ${r.fault}`, step)
        const arm = r.result ? 'then' : 'else'
        options.onStep?.({ kind: 'branch', step, arm })
        const inner = await run(r.result ? step.then : step.else)
        if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.', step)
        if (inner) return inner
      }
      return null
    }
    const stopped = await run(expanded.steps)
    if (!receiptIsCurrent(receiptToken)) return fail('The machine connection changed during the probe routine.')
    if (stopped) return stopped
    if (cycleRun.stopped) return fail(PROBE_CYCLE_STOPPED)

    // Outputs, evaluated with the real contacts. Nothing is written here.
    const proposals: ProbeRoutineEvaluatedProposal[] = []
    for (const p of expanded.proposals as ExpandedProposal[]) {
      if (p.kind === 'workOffset') {
        const axes: Partial<Record<'X' | 'Y' | 'Z', number>> = {}
        for (const axis of ['X', 'Y', 'Z'] as const) {
          const e = p.axes[axis]
          if (!e) continue
          const r = evalNumber(e.ast)
          if (!r.ok) return fail(`Proposal '${p.label}': ${r.fault}`)
          axes[axis] = round4Value(r.value)
        }
        proposals.push({ kind: 'workOffset', wcs: p.wcs, activeWcs: p.activeWcs, axes, label: p.label, compensationNote: p.compensationNote })
      } else if (p.kind === 'toolLength') {
        const r = evalNumber(p.machineZ.ast)
        if (!r.ok) return fail(`Proposal '${p.label}': ${r.fault}`)
        proposals.push({ kind: 'toolLength', tool: p.tool, machineZ: round4Value(r.value), label: p.label })
      } else {
        const items: Array<{ label: string; value: number; unit: string }> = []
        for (const item of p.items) {
          const r = evalNumber(item.expr.ast)
          if (!r.ok) return fail(`Report '${item.label}': ${r.fault}`)
          items.push({ label: item.label, value: round4Value(r.value), unit: item.unit })
        }
        proposals.push({ kind: 'report', items })
      }
    }
    return {
      ok: true,
      message: `${expanded.routineName} recorded ${touches.length} touch${touches.length === 1 ? '' : 'es'}. Nothing has been written - review the proposal and press Confirm.`,
      stoppedAt: null,
      touches,
      calcs,
      proposals,
    }
  } finally {
    await cycleRun?.cancelMotion
    setProbeCycleActive(false)
    releaseProbeCycleRun(cycleRun)
    if (receiptIsCurrent(receiptToken) && ctrl.machineState() !== 'alarm' && ctrl.connectionPhase() === 'connected') {
      // WO-2073: a guarded descent's G38.3 line is incremental (G91).
      if (textDescentSent) sendAppCommand('G90', ctrl)
      // GrblController.probe uses G21 internally. Restore the operator's inch
      // modal through the translator, which holds it locally where needed.
      if (previousUnitsInch) sendAppCommand('G20', ctrl)
      ctrl.refreshState()
    }
  }
}

/**
 * The toolLength proposal's writer (Routines tab Confirm) - the sibling of
 * setWorkOffsetValue above. Records the measured machine Z into the tool
 * table against the tool the proposal names, through the same
 * recordProbedZ + toolOffsetLine pair the guided tool change already uses
 * (ProgramPanel.tsx). 'active' resolves through the live spindle tool
 * number; with none reported there is no T number to record against - one
 * genuine refusal. The other: the resolved T number has never been added to
 * the table (WO-1370 review) - there is no existing row to update, so this
 * writer never creates one behind the operator's back. Add the tool on the
 * Tools tab first, then this writer records its measured Z.
 */
export function confirmProbeRoutineToolLength(
  proposal: Extract<ProbeRoutineEvaluatedProposal, { kind: 'toolLength' }>,
): { ok: true; tool: number; message: string } | { ok: false; reason: string } {
  const tool = proposal.tool === 'active' ? store().activeTool : proposal.tool
  if (tool === null || tool === undefined) {
    return {
      ok: false,
      reason: 'No tool is active on the controller, so "active" names no T number to record the measurement against - make the measured tool active, or rerun the routine with an explicit T number.',
    }
  }
  const machineId = controlMachineId()
  if (!findTool(useMachineToolTable.getState().tableFor(machineId), tool)) {
    return {
      ok: false,
      reason: `T${tool} is not in the tool table yet, so there is no row to record this measurement against - add T${tool} on the Tools tab, then run this routine again.`,
    }
  }
  useMachineToolTable.getState().recordProbedZ(machineId, tool, proposal.machineZ, Date.now())
  saveMachineToolRecord(controlMachine(useCamStore.getState()))
  const line = toolOffsetLine(useMachineToolTable.getState().tableFor(machineId), tool)
  const message = line.ok
    ? `T${tool} pad Z recorded at ${machinePositionText({ z: proposal.machineZ }, machineLengthText)} `
      + `(${line.deltaMm >= 0 ? '+' : ''}${machineLengthText(line.deltaMm)} from the reference tool).`
    : `T${tool} pad Z recorded at ${machinePositionText({ z: proposal.machineZ }, machineLengthText)}.`
  return { ok: true, tool, message }
}

/**
 * Fixed-pad Z probe cycle (stage 10, Operator's M31 pattern): the operator jogs
 * the tool over the pad, then this sequences fast G38.2 -> retract -> slow
 * G38.2 and reads the [PRB] contact. 'workZero' also sets work Z0 at the
 * contact, less the plate when the machine's Z0 sensing choice is a plate
 * (G10 L20 P0 Z{plate or 0}, WO-2059); 'measureTool' just returns the contact
 * for the caller to record in the tool table. Fail-loud: any refused command,
 * failed ack, or missed contact stops the cycle with plain recovery text -
 * never an auto-retry.
 */
export async function runZProbeCycle(
  mode: ZProbeMode,
  config: ZProbeConfig,
  /** WO-1613: the tool setter routine to measure with; omitted, the preferred one. */
  setterRoutineChoice?: ProbeRoutine | null,
): Promise<ZProbeResult> {
  const programOwned = store().toolChange !== null || programPartsRun !== null || loadedProgramText() !== null
  const receipt = captureBackendReceipt(getMachineController())
  const result = await runZProbeCycleOnce(mode, config, setterRoutineChoice)
  if (!programOwned && receiptIsCurrent(receipt)) publishProbeActionResult(result, 'Z probe')
  // WO-2146: A MEASURE NEVER GOES SILENT. Pin rehearsal 2026-09-28: Tools >
  // Measure T19 ended "not recorded" and the console said nothing - that
  // screen shows a failure only in its own status line. A measure that
  // records nothing says so here, with why. The Probing screen's Tool Z (the
  // one caller that picks a setter routine) prints its own result line, and a
  // Stop/Reset ending was already said by the stopped sentence.
  if (mode === 'measureTool' && !result.ok && result.stopped !== true && setterRoutineChoice === undefined) {
    store().pushConsole('rx', `Measure tool: nothing was recorded. ${result.message}`, 'warn')
  }
  return result
}

async function runZProbeCycleOnce(
  mode: ZProbeMode,
  config: ZProbeConfig,
  setterRoutineChoice?: ProbeRoutine | null,
): Promise<ZProbeResult> {
  // WO-1330: the pad zero writes the ACTIVE frame's Z, so it asks before the
  // probe moves - never a touch whose zero is then refused.
  const held = mode === 'workZero' ? workOffsetWriteRefusal(store().activeWcs, ['Z']) : null
  if (held !== null) return { ok: false, message: held, probedMachineZ: null }
  const ctrl = getMachineController()
  // WO-1998: settle first - the part search below is planned from where Z is.
  if (probeTouchMustSettle(ctrl)) {
    const unsettled = await settleBeforeProbeTouch(ctrl)
    if (unsettled) return { ok: false, message: unsettled, probedMachineZ: null }
  }
  const receiptToken = captureBackendReceipt(ctrl)
  const zeroRevision = connectionRevision
  // WO-2059: work Z0 is the contact less the plate the operator chose to
  // sense the top through; the probe touching the part subtracts nothing.
  const zeroPlateMm = mode === 'workZero' ? controlZPlateMm('workZero', config) : 0
  // WO-1546: on the native probe a tool measure goes to the fixed setter the
  // machine definition names, and searches down to the bottom of the Z travel
  // the definition declares - never a default search depth.
  // WO-1613: the measure is the tool setter ROUTINE - the one the operator
  // picked, else their own copy, else the factory one filled from the
  // definition - planned from its inputs and the tool table.
  const native = nativeProbeRoute(ctrl)
  const machine = controlMachine(useCamStore.getState())
  const partZSearch = mode === 'workZero'
    ? planPartProbeSearch(machine, ctrl.status().machinePos?.z, resolveProbeConfig(null, config).maxTravel)
    : null
  // WO-2021: on EVERY controller - a text controller used to skip the setter
  // and probe down wherever the tool stood.
  const setterRoutine = mode === 'measureTool' ? toolSetterRoutineToRun(machine, config, setterRoutineChoice) : null
  if (setterRoutine && !native && !ctrl.capabilities.gcodeText) {
    return {
      ok: false,
      message: `${setterRoutine.name}: this controller has neither a probe call nor G-code probing (G38.2), so it cannot run the tool setter measure. Nothing moved.`,
      probedMachineZ: null,
    }
  }
  // The same gate the feature cycles keep: the setter is a machine coordinate.
  const setterRefusal = setterRoutine
    ? homingRefusal(ctrl, undefined, 'the tool setter is a machine-coordinate position.')
    : null
  if (setterRefusal) return { ok: false, message: setterRefusal, probedMachineZ: null }
  const planned = setterRoutine ? planToolSetterForSession(setterRoutine, config) : null
  if (planned && !planned.ok) return { ok: false, message: `${setterRoutine!.name}: ${planned.reason} Nothing moved.`, probedMachineZ: null }
  // WO-2061: work Z0 ends at top + clearance (the top is contact less the
  // plate WO-2059 subtracts - none when the probe touched the part), ready
  // for the next routine - no longer 2 mm above the touch.
  const effectiveZ0 = resolveProbeConfig(null, config)
  const workZeroEnd = mode === 'workZero'
    ? (contact: number) => workZeroEndMachineZ({
        contactMachineZ: contact,
        padThicknessMm: zeroPlateMm,
        surfaceClearanceMm: effectiveZ0.surfaceClearance,
        retractMm: effectiveZ0.retract,
        zTopMachineZ: definitionMachineZMax(machine),
      })
    : null
  const result = await executeDirectionalProbeTouch('Z', '-', config, {
    ...(partZSearch ? { travelMm: partZSearch.travelMm, partZSearch } : {}),
    toolSetter: planned?.ok ? planned.plan : undefined,
    afterContact:
      mode === 'workZero'
        ? async (send, n, contact) => {
            // G10 L20 P0 targets the WCS active when this contact-time write
            // is issued, which may differ from the WCS active at cycle start.
            // On the native probe the register is written from the contact the
            // probe reply carried (L2), not from a status frame that may not
            // have caught up with the stop yet. The contact is in mm, so the
            // line says G21: with no units word the translator reads it in the
            // operator's display units, and an inch session wrote 25.4x the Z.
            const zeroWcs = store().activeWcs
            const zero = await send(
              native
                ? `G21 G10 L2 P0 Z${n(contact - zeroPlateMm)}`
                : `G10 L20 P0 Z${n(zeroPlateMm)}`,
            )
            if (!receiptIsCurrent(receiptToken)) return 'The machine connection changed during the probe cycle.'
            if (!zero || !zero.ok) return unsentReason(zero) ?? (zeroPlateMm > 0 ? 'Setting work Z0 through the pad failed.' : 'Setting work Z0 at the contact failed.')
            markConfirmedWorkZero(zeroWcs, 'Z', zeroRevision)
            return null
          }
        : undefined,
    ...(workZeroEnd
      ? {
          endMachineZ: workZeroEnd,
          endRiseFailure: (contact: number, reason: string) =>
            (zeroPlateMm > 0 ? `Work Z0 was set through the ${machineLengthText(zeroPlateMm)} pad (contact at ` : 'Work Z0 was set at the contact (contact at ')
              + `${formatPosition({ machine: { z: contact }, format: machineLengthText })}), but rising to top + clearance at `
              + `${machinePositionText({ z: workZeroEnd(contact) }, machineLengthText)} stopped: ${reason}. The probe is `
              + `${machineLengthText(effectiveZ0.retract)} above the touch.`,
        }
      : {}),
    successMessage: (probedMachineZ) =>
      mode === 'workZero'
        ? (zeroPlateMm > 0
            ? `Work Z0 set through the ${machineLengthText(zeroPlateMm)} pad (contact at ${formatPosition({ machine: { z: probedMachineZ }, format: machineLengthText })}). `
            : `Work Z0 set at the contact - the probe touched the part (contact at ${formatPosition({ machine: { z: probedMachineZ }, format: machineLengthText })}). `)
          + `Probe left ${machineLengthText(workZeroEnd!(probedMachineZ) - (probedMachineZ - zeroPlateMm))} above that top `
          + `(clearance ${machineLengthText(effectiveZ0.surfaceClearance)}), at ${machinePositionText({ z: workZeroEnd!(probedMachineZ) }, machineLengthText)}.`
        : `Tool length probed: contact at ${machinePositionText({ z: probedMachineZ }, machineLengthText)}.`,
    probeLabel: mode === 'workZero' ? 'Probe work Z0' : 'Measure tool',
  })
  if (!receiptIsCurrent(receiptToken)) {
    return { ok: false, message: 'The machine connection changed during the probe cycle.', probedMachineZ: null }
  }
  if (result.ok && result.probedMachinePosition !== null && mode === 'measureTool') {
    activeToolLengthDatumValue = result.probedMachinePosition
  }
  return {
    ok: result.ok,
    message: result.message,
    probedMachineZ: result.probedMachinePosition,
    ...(result.stopped ? { stopped: true as const } : {}),
    ...(result.contacts
      ? {
          contacts: {
            fastMachineZ: result.contacts.fastMachinePosition,
            fineMachineZ: result.contacts.fineMachinePosition,
          },
        }
      : {}),
  }
}

/**
 * One-gesture recovery from a failed probe (ALARM:4/5, position retained):
 * unlock, restore absolute mode + the operator's units (the cycle left the
 * controller in relative mm mode), and re-read state.
 */
export function recoverFromProbeAlarm(): boolean {
  const ctrl = getMachineController()
  if (!ctrl.unlock()) return false
  sendAppCommand('G90', ctrl)
  if (store().parserModal?.units === 'inch') sendAppCommand('G20', ctrl)
  ctrl.refreshState()
  return true
}

/**
 * Park move (stage 11): raise to the machine's safe Z, then rapid to a stored
 * machine-coordinate XY. HOMING-GUARDED - machine coordinates mean nothing
 * before $H, so an unhomed park is refused loudly, never attempted.
 */
export function runParkMove(
  park: ParkPosition,
  safeZMachine: number | null | undefined,
): { ok: boolean; reason?: string } {
  const hiddenPark = hiddenParkNotRun(park)
  if (hiddenPark !== null) return { ok: false, reason: hiddenPark }
  if (estopNeedsReset()) return { ok: false, reason: ESTOP_BLOCKS_MOTION }
  const ctrl = getMachineController()
  if (ctrl.connectionPhase() !== 'connected') return { ok: false, reason: 'Not connected to a machine.' }
  if (ctrl.hasActiveJob()) return { ok: false, reason: 'A program is running - parking is locked out.' }
  if (ctrl.machineState() !== 'idle') return { ok: false, reason: 'The machine must be idle to park.' }
  // ALL THREE. A park is a machine-coordinate XY at a machine-coordinate Z.
  const parkRefusal = homingRefusal(ctrl, undefined,
    'park positions are machine coordinates and are meaningless unhomed.')
  if (parkRefusal) return { ok: false, reason: parkRefusal }
  const built = buildParkSequence(park, safeZMachine)
  if (!built.ok) return { ok: false, reason: built.reason }
  const seq = { lines: parkLinesStillToRun(built.lines, ctrl.status().machinePos) }
  if (seq.lines.length === 0) {
    store().pushConsole('tx', `Park "${park.label}": already there (machine coordinates) - nothing to move.`, 'info')
    return { ok: true }
  }
  // WO-1670: every park says where it is going, in machine coordinates.
  store().pushConsole('tx', `Park "${park.label}": ${seq.lines.join(', then ')} (machine coordinates).`, 'info')
  // The park lines say G21 G90 (their numbers are mm, G53 is absolute); the
  // operator's units and distance mode come back afterwards, however it ends.
  const receiptToken = captureBackendReceipt(ctrl)
  const held = operatorModal(ctrl)
  if (!ctrl.capabilities.gcodeText) {
    // WO-1548: geometry moves run one at a time - each waits for the board to
    // report idle at its target before the next is issued. A line that cannot
    // run is named before anything moves; a later failure reaches the console.
    const refusal = seq.lines.map((line) => appCommandUnsentHere(ctrl, line)).find((r) => r !== null)
    if (refusal) {
      store().pushConsole('tx', refusal, 'error')
      return { ok: false, reason: refusal }
    }
    void (async () => {
      try {
        for (const line of seq.lines) {
          const outcome = await sendAppCommandAwait(line, ctrl)
          if (!outcome?.ok) return
        }
      } finally {
        restoreOperatorModal(ctrl, receiptToken, held)
      }
    })()
    return { ok: true }
  }
  try {
    for (const line of seq.lines) {
      const sent = sendAppCommand(line, ctrl)
      if (!sent.ok) return { ok: false, reason: unsentReason(sent) ?? 'The controller refused the park command.' }
    }
    return { ok: true }
  } finally {
    restoreOperatorModal(ctrl, receiptToken, held)
  }
}

/** WO-2437 fix round 4: the machine already stands at every stated axis of a
 *  park leg (within the boundary tolerance). A leg it stands at is not sent:
 *  on a travel limit the bridge reads a zero-length move as a soft-limit trip
 *  and latches buffered motion. An unknown position is never "reached". */
function parkLegReached(
  at: MachinePosition | null | undefined,
  leg: Partial<Record<'x' | 'y' | 'z', number>>,
): boolean {
  if (!at) return false
  return (['x', 'y', 'z'] as const).every((axis) => {
    const target = leg[axis]
    if (target === undefined) return true
    const now = at[axis]
    return Number.isFinite(now) && Math.abs(now - target) <= SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM
  })
}

/** WO-2657: a park read from a macro hidden from the Macros panel is that
 *  macro's movement, and a hidden macro is off - whichever caller resolved the
 *  park (pendant Rear, program panel M6 or clamp pause). One console line says
 *  so; the text is returned for the caller's own refusal. Null = not hidden. */
function hiddenParkNotRun(park: ParkPosition): string | null {
  const macro = hiddenParkMacro(park)
  if (macro === null) return null
  const text = hiddenMacroNotRunText({ ...macro, mCode: undefined })
  store().pushConsole('rx', text, 'info')
  return text
}

/** The park lines (buildParkSequence's G53 legs) the machine is not already at. */
function parkLinesStillToRun(lines: string[], at: MachinePosition | null | undefined): string[] {
  return lines.filter((line) => {
    const leg: Partial<Record<'x' | 'y' | 'z', number>> = {}
    for (const [, axis, value] of line.matchAll(/\b([XYZ])(-?\d+(?:\.\d+)?)/g)) {
      leg[axis.toLowerCase() as 'x' | 'y' | 'z'] = Number(value)
    }
    return !parkLegReached(at, leg)
  })
}

/** The units and distance mode the operator holds now: the board's parser
 *  state on a controller that takes text, the locally held modal otherwise. */
function operatorModal(ctrl: MachineController): { inch: boolean; incremental: boolean } {
  const modal = ctrl.capabilities.gcodeText ? store().parserModal : appCommandModal(ctrl)
  return { inch: modal?.units === 'inch', incremental: modal?.distanceMode === 'incremental' }
}

/** Put back what an app sequence that says G21 G90 took from the operator.
 *  Not across a new connection (it starts from its own modal state), and not
 *  to a text controller in ALARM, which refuses everything but $X/$H. */
function restoreOperatorModal(
  ctrl: MachineController,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
  held: { inch: boolean; incremental: boolean },
): void {
  if (!receiptIsCurrent(receiptToken) || ctrl.connectionPhase() !== 'connected') return
  if (ctrl.capabilities.gcodeText && ctrl.machineState() === 'alarm') return
  if (held.incremental) sendAppCommand('G91', ctrl)
  if (held.inch) sendAppCommand('G20', ctrl)
}

// ---- Material-fit trace (Operator's M20002) ----
//
// Trace the loaded program's cutting-move XY outline at the machine's safe Z
// with a dwell at each corner, so the operator can verify stock and clamps
// BEFORE cutting. Two explicit gestures: prepare (shows the confirm card with
// the bounds and the exact commands) and start (sends them). Homing-guarded
// like every machine-coordinate move.

function stagedGeometryCutBounds(): ReturnType<typeof computeCutBounds> {
  const path = stagedGeometryProgramPath()
  if (!path || path.moves.length === 0) {
    return { ok: false, reason: 'The program has no cutting moves to outline.' }
  }
  const moves = sampleArcMovesForLinearConsumers(path.moves)
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  const include = (move: ToolpathMove) => {
    minX = Math.min(minX, move.x)
    minY = Math.min(minY, move.y)
    maxX = Math.max(maxX, move.x)
    maxY = Math.max(maxY, move.y)
  }
  for (let i = 0; i < moves.length; i++) {
    const move = moves[i]
    if (move.role === 'rapid' || move.type === 'rapid') continue
    if (i > 0) include(moves[i - 1])
    include(move)
  }
  return Number.isFinite(minX)
    ? { ok: true, bounds: { minX, minY, maxX, maxY } }
    : { ok: false, reason: 'The program has no cutting moves to outline.' }
}

/**
 * Plan the trace and open the confirm card. Refuses loudly when any
 * prerequisite is missing; never moves the machine.
 */
export function prepareMaterialFitTrace(
  safeZMachine: number | null | undefined,
  feedMmMin: number,
): { ok: boolean; reason?: string } {
  const ctrl = getMachineController()
  const s = store()
  if (ctrl.connectionPhase() !== 'connected') return { ok: false, reason: 'Not connected to a machine.' }
  if (!s.programText && !s.stagedProgram) return { ok: false, reason: 'No program is loaded.' }
  if (ctrl.hasActiveJob()) return { ok: false, reason: 'A program is running - the trace is locked out.' }
  if (ctrl.machineState() !== 'idle') return { ok: false, reason: 'The machine must be idle to trace.' }
  // ALL THREE. The trace raises to a machine-coordinate safe Z and then walks
  // the outline in X and Y.
  const traceRefusal = homingRefusal(ctrl, undefined,
    'the trace raises to a machine-coordinate safe Z and then moves in X and Y.')
  if (traceRefusal) return { ok: false, reason: traceRefusal }
  if (s.fitTrace && s.fitTrace.step === 'tracing') {
    return { ok: false, reason: 'A trace is already running.' }
  }
  const cut = s.programText
    ? computeCutBounds(buildPreviewModel(s.programText))
    : stagedGeometryCutBounds()
  if (!cut.ok) return { ok: false, reason: cut.reason }
  const seq = buildFitTraceSequence(cut.bounds, safeZMachine, feedMmMin)
  if (!seq.ok) return { ok: false, reason: seq.reason }
  const wcs = s.activeWcs ?? 'the active work offset'
  s.setFitTrace({
    step: 'confirm',
    bounds: cut.bounds,
    lines: seq.lines,
    message:
      `The machine will raise to safe Z, then trace the job's cutting outline in ${wcs}, ` +
      'pausing briefly at each corner. Watch that the path stays on the stock and clear of clamps.',
  })
  return { ok: true }
}

/** Canonical CYCLE START accepted the confirm card: send the trace sequence. */
export async function startMaterialFitTrace(): Promise<boolean> {
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const tc = store().fitTrace
  if (!tc || tc.step !== 'confirm') return false
  const base = { bounds: tc.bounds, lines: tc.lines }
  const fail = (message: string): false => {
    store().setFitTrace({ ...base, step: 'failed', message })
    return false
  }
  if (estopNeedsReset()) return fail(ESTOP_BLOCKS_MOTION)
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  if (ctrl.hasActiveJob() || ctrl.machineState() !== 'idle') {
    return fail('The machine must be idle to start the trace.')
  }
  // The trace lines say G21 G90; the operator's units and distance mode come
  // back when it ends, including when it stops part-way (WO-1548).
  const held = operatorModal(ctrl)
  const stopped = (message: string): false => {
    restoreOperatorModal(ctrl, receiptToken, held)
    return fail(message)
  }
  store().setFitTrace({
    ...base,
    step: 'tracing',
    message: 'Tracing the outline - watch the machine. Use Hold or E-STOP to interrupt.',
  })
  for (const line of tc.lines) {
    const ack = await sendAppCommandAwait(line, ctrl)
    if (!receiptIsCurrent(receiptToken)) return false
    if (!ack) return stopped('The controller refused a trace command.')
    if (!ack.ok) return stopped(unsentReason(ack) ?? `The trace stopped: ${ack.message}`)
  }
  // Acks mean buffered, not done - wait for motion to finish like a park does.
  await new Promise((r) => setTimeout(r, 1200))
  if (!receiptIsCurrent(receiptToken)) return false
  const done = await waitForMachine(
    () => ctrl.machineState() === 'idle' || ctrl.connectionPhase() !== 'connected',
    180000,
  )
  if (!receiptIsCurrent(receiptToken)) return false
  if (ctrl.connectionPhase() !== 'connected') return fail('The connection dropped during the trace.')
  if (!done) return stopped('The trace never finished - check the machine.')
  restoreOperatorModal(ctrl, receiptToken, held)
  ctrl.refreshState()
  store().setFitTrace({
    ...base,
    step: 'done',
    message:
      'Outline traced - the machine is back at the first corner at safe Z. ' +
      'If the path missed the stock or hit a clamp shadow, fix the setup before cutting.',
  })
  return true
}

/** Close/abandon the fit-trace card (never interrupts motion by itself). */
export function cancelMaterialFitTrace(): void {
  store().setFitTrace(null)
}

// ---- Guided tool change (stage 12) - Operator's signature M6 workflow ----
//
// The character-counting streamer keeps lines PAST the tool-change pause in
// GRBL's buffer, so injecting commands mid-hold would queue them in the wrong
// place. The guided flow therefore does a CONTROLLED STOP (hold + settle +
// soft reset - machine position survives), parks over the probe pad, walks
// the operator through the swap, probes the new tool, re-applies the length
// offset, and re-arms the program via run-from-line. Every motion stays an
// explicit gesture; every failure ends the flow loudly with recovery text.

function setToolChange(tc: Parameters<ReturnType<typeof store>['setToolChange']>[0]): void {
  store().setToolChange(tc)
  // A program's clamp pause lends jog while its card waits (toolChangeHoldActive).
  for (const listener of toolChangeHoldListeners) listener()
}

async function waitForMachine(cond: () => boolean, timeoutMs: number): Promise<boolean> {
  const started = sessionElapsedNowMs()
  while (sessionElapsedNowMs() - started < timeoutMs) {
    if (cond()) return true
    await new Promise((r) => setTimeout(r, 100))
  }
  return cond()
}

/** Controlled stop without the park phase. Kept beside the guided-flow wait
 * helper because both paths intentionally share the same hold/settle/reset
 * behavior and timeout. */
async function controlledStopForStepBack(ctrl: MachineController): Promise<StreamerProgress | null> {
  if (ctrl.hasActiveJob()) {
    stopJobForSession(ctrl)
    const stopped = await waitForMachine(() => !ctrl.hasActiveJob() && ctrl.machineState() === 'idle', 8000)
    return stopped ? ctrl.stoppedJobProgress() : null
  }
  // A short job may already be fully acked while GRBL remains physically in
  // Hold with planner motion buffered. Settle before reset just like the
  // clamp-pause path, so position is preserved.
  await new Promise((r) => setTimeout(r, 600))
  const stoppedProgress = ctrl.jobProgress()
  resetForSession(ctrl)
  const stopped = await waitForMachine(() => ctrl.machineState() === 'idle', 8000)
  return stopped ? stoppedProgress : null
}

interface GuidedToolChangeBegin {
  /** The tool the program asks for (from the program's tool-change scan). */
  tool: number | null
  /** First line to stream after the change (the pause line + 1). */
  resumeLine: number
  park: ParkPosition
  safeZMachine: number | null | undefined
  /** The geometry-program boundary has already completed its outgoing part,
   * stopped its spindle and reached idle. Resetting there would retire the
   * multipart run that owns the resume. */
  alreadyStoppedAtProgramBoundary?: boolean
}

type GuidedParkResult = { ok: true } | { ok: false; reason: string }

// ---- WO-2259: a Feed Hold on the tool-change park pauses it ----
//
// Native kit, 2026-09-30 (WO-2242 n2/n3): Feed Hold pressed while the guided
// change parked left the board in Hold with the park move cut short (the
// bridge: "THE MOVE WAS TRUNCATED AND IT REPORTED SUCCESS"); CYCLE START was
// dark, and the card failed after 30 s or sat at 'parking'. A hold now pauses
// the park where it is, as WO-2103 pauses a probe routine: the leg's wait stops
// the clock, CYCLE START releases the hold (programHoldCycleStartDecision's
// 'tool-change-park') and the leg carries on to its own target. Stop/Reset,
// the E-STOP, an alarm or a lost connection end the pause and the leg's wait
// goes on exactly as it did before.

interface GuidedParkRun {
  readonly controller: MachineController
  /** The leg's wait has seen the operator's hold and waits for CYCLE START. */
  paused: boolean
  /** CYCLE START carried the paused park on; the leg's wait takes it. */
  resumed: boolean
  /** Stop/Reset or the E-STOP was pressed during this park. */
  stopped: boolean
}
let guidedParkRun: GuidedParkRun | null = null

/** The board holds a park leg in flight, and nothing has stopped the park. */
function guidedParkHeld(ctrl: MachineController, run: GuidedParkRun): boolean {
  return !run.stopped && ctrl.connectionPhase() === 'connected' && !estopNeedsReset()
    && ctrl.machineState() === 'hold'
}

/** A Feed Hold the operator put on a guided park, not yet carried on. */
function guidedParkPausedByOperator(ctrl: MachineController): boolean {
  const run = guidedParkRun
  if (run === null || run.controller !== ctrl || run.resumed) return false
  if (guidedParkHeld(ctrl, run)) return true
  return run.paused && !run.stopped && ctrl.connectionPhase() === 'connected' && !estopNeedsReset()
    && ctrl.machineState() === 'idle'
}

/** CYCLE START on a paused park: release the board's hold, and the leg's wait
 *  carries the park on. Nothing of a loaded program is released. */
function carryOnGuidedPark(ctrl: MachineController, release: () => boolean): boolean {
  const run = guidedParkRun!
  if (ctrl.machineState() === 'hold' && !release()) return false
  run.resumed = true
  return true
}

/** Waits, with no clock, while the park is paused. True once CYCLE START has
 *  carried it on; false once Stop/Reset, the E-STOP, an alarm, the connection
 *  or a new controller ends the pause. */
async function waitOutGuidedParkPause(ctrl: MachineController, run: GuidedParkRun): Promise<boolean> {
  const receiptToken = captureBackendReceipt(ctrl)
  run.paused = true
  try {
    while (!run.resumed) {
      if (run.stopped || estopNeedsReset() || !receiptIsCurrent(receiptToken) || ctrl !== controller) return false
      if (ctrl.connectionPhase() !== 'connected') return false
      const state = ctrl.machineState()
      if (state !== 'hold' && state !== 'idle') return false
      await new Promise((resolve) => setTimeout(resolve, 50))
    }
    run.resumed = false
    return true
  } finally {
    run.paused = false
  }
}

type GuidedParkLeg = 'done' | 'timeout' | 'changed' | 'refused'

/** One park leg already commanded: settles idle in 30 s, as it always has.
 *  WO-2259: a hold the operator puts on it pauses it; after CYCLE START a
 *  geometry controller is given the leg again (`again`) - the same absolute
 *  target, so nothing moves where the board carried it on - and a text
 *  controller carries its own queued lines on. */
async function settleGuidedParkLeg(
  ctrl: MachineController,
  run: GuidedParkRun,
  again: (() => boolean) | null,
): Promise<GuidedParkLeg> {
  for (;;) {
    await new Promise((resolve) => setTimeout(resolve, 1200))
    if (ctrl !== controller) return 'changed'
    const settled = await waitForMachine(() => ctrl.machineState() === 'idle' || guidedParkHeld(ctrl, run), 30000)
    if (!guidedParkHeld(ctrl, run)) return settled ? 'done' : 'timeout'
    if (!(await waitOutGuidedParkPause(ctrl, run))) {
      return (await waitForMachine(() => ctrl.machineState() === 'idle', 30000)) ? 'done' : 'timeout'
    }
    if (again === null) continue
    await new Promise((resolve) => setTimeout(resolve, 1200))
    if (ctrl !== controller) return 'changed'
    const released = await waitForMachine(() => ctrl.machineState() === 'idle' || guidedParkHeld(ctrl, run), 30000)
    if (guidedParkHeld(ctrl, run)) continue
    if (!released) return 'timeout'
    if (run.stopped || estopNeedsReset()) return 'done'
    if (!again()) return 'refused'
  }
}

/** Park for a guided flow on either controller shape. Text controllers keep
 * the established G53 sequence. A geometry-only controller uses its native
 * machine-Z and work-XY jog calls, converting the configured machine XY from
 * the controller's own simultaneous machine/work readback. */
async function parkForGuidedStop(
  ctrl: MachineController,
  park: ParkPosition,
  safeZMachine: number | null | undefined,
): Promise<GuidedParkResult> {
  const hiddenPark = hiddenParkNotRun(park)
  if (hiddenPark !== null) return { ok: false, reason: hiddenPark }
  const run: GuidedParkRun = { controller: ctrl, paused: false, resumed: false, stopped: false }
  const offStop = subscribeMotionStop(() => { run.stopped = true })
  guidedParkRun = run
  try {
    return await parkLegsForGuidedStop(ctrl, run, park, safeZMachine)
  } finally {
    offStop()
    if (guidedParkRun === run) guidedParkRun = null
  }
}

async function parkLegsForGuidedStop(
  ctrl: MachineController,
  run: GuidedParkRun,
  park: ParkPosition,
  safeZMachine: number | null | undefined,
): Promise<GuidedParkResult> {
  if (ctrl.capabilities.gcodeText) {
    const started = runParkMove(park, safeZMachine)
    if (!started.ok) return { ok: false, reason: started.reason ?? 'The park move was refused.' }
    const leg = await settleGuidedParkLeg(ctrl, run, null)
    if (leg === 'changed') return { ok: false, reason: 'The machine connection changed during the park.' }
    return leg === 'done'
      ? { ok: true }
      : { ok: false, reason: 'The park move never finished - check the machine, then retry.' }
  }

  if (estopNeedsReset()) return { ok: false, reason: ESTOP_BLOCKS_MOTION }
  const sequence = buildParkSequence(park, safeZMachine)
  if (!sequence.ok) return sequence
  const parkRefusal = homingRefusal(
    ctrl,
    undefined,
    'park positions are machine coordinates and are meaningless unhomed.',
  )
  if (parkRefusal) return { ok: false, reason: parkRefusal }

  const rapidFeedMmMin = controlMachine(useCamStore.getState()).rapidRate
  if (!(Number.isFinite(rapidFeedMmMin) && rapidFeedMmMin > 0)) {
    return {
      ok: false,
      reason: "This machine declares no rapid rate, so the park cannot run without inventing one.",
    }
  }
  const status = ctrl.status()
  const machine = status.machinePos
  const work = status.workPos
  if (
    machine === null
    || work === null
    || !Number.isFinite(machine.x)
    || !Number.isFinite(machine.y)
    || !Number.isFinite(work.x)
    || !Number.isFinite(work.y)
  ) {
    return {
      ok: false,
      reason:
        'The controller did not report both machine and work XY, so the configured machine-coordinate '
        + 'park position could not be resolved.',
    }
  }

  // WO-2437 fix round 4: Z goes to the park's own machine Z, else the safe Z -
  // the height buildParkSequence gives the text route - so the clamp pause
  // stands where atClampPausePark and the section boundary look for it.
  const parkZ = typeof park.z === 'number' && Number.isFinite(park.z) ? park.z : safeZMachine!
  const zName = parkZ === park.z ? `the park's Z` : 'safe Z'
  const zLeg = () => ctrl.jogToMachineZ(parkZ, rapidFeedMmMin)
  const zRefused = { ok: false as const, reason: `The controller refused the ${zName} move for the park.` }
  if (!parkLegReached(machine, { z: parkZ })) {
    if (!zLeg()) return zRefused
    const zSettled = await settleGuidedParkLeg(ctrl, run, zLeg)
    if (zSettled === 'changed') return { ok: false, reason: 'The machine connection changed during the park.' }
    if (zSettled === 'refused') return zRefused
    if (zSettled === 'timeout') {
      return { ok: false, reason: `The ${zName} move for the park never finished - check the machine.` }
    }
  }

  const reachedZ = ctrl.status().machinePos?.z ?? null
  if (reachedZ === null || !Number.isFinite(reachedZ)) {
    const reason = `The park stopped because the controller did not report machine Z after the `
      + `retract to ${zName} at ${machinePositionText({ z: parkZ }, machineLengthText)}. XY was not commanded.`
    store().pushConsole('rx', reason, 'error')
    return { ok: false, reason }
  }
  if (reachedZ < parkZ - SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM) {
    const reason = `The park stopped because the retract did not reach ${zName} at `
      + `${machinePositionText({ z: parkZ }, machineLengthText)}; the tool is at `
      + `${machinePositionText({ z: reachedZ }, machineLengthText)}. XY was not commanded.`
    store().pushConsole('rx', reason, 'error')
    return { ok: false, reason }
  }

  // WO-2437 fix round 4: an XY leg the tool already stands at is not sent - on
  // a travel limit the bridge reads a zero-length move as a soft-limit trip.
  if (parkLegReached(ctrl.status().machinePos, { x: park.x, y: park.y })) return { ok: true }
  // WO-2203: the park is a machine position, whatever the work rotation.
  const parkWork = workXYForMachineXY(status, park.x, park.y)
  const xyLeg = () => ctrl.jogToWorkXY(parkWork.x, parkWork.y, rapidFeedMmMin)
  const xyRefused = { ok: false as const, reason: 'The controller refused the configured XY park move.' }
  if (!xyLeg()) return xyRefused
  const xySettled = await settleGuidedParkLeg(ctrl, run, xyLeg)
  if (xySettled === 'changed') return { ok: false, reason: 'The machine connection changed during the park.' }
  if (xySettled === 'refused') return xyRefused
  return xySettled === 'done'
    ? { ok: true }
    : { ok: false, reason: 'The XY park move never finished - check the machine.' }
}

/**
 * Phase 1 (shared by the tool change and the clamp pause): controlled stop +
 * park. Leaves the flow at 'awaiting-swap' for the operator, or 'failed'
 * with a plain reason.
 */
async function stopAndPark(
  args: GuidedToolChangeBegin & { mode: 'toolChange' | 'clampPause'; awaitingMessage: string; typedOnMdi?: boolean },
): Promise<boolean> {
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const fail = (message: string): false => {
    setToolChange({
      step: 'failed',
      mode: args.mode,
      tool: args.tool,
      resumeLine: args.resumeLine,
      message,
      warnings: [],
    })
    return false
  }
  if (ctrl.connectionPhase() !== 'connected') return fail('Not connected to a machine.')
  if (store().toolChange && store().toolChange!.step !== 'failed') {
    return fail('A guided stop is already in progress.')
  }
  // WO-2657: a hidden park macro is off - nothing is stopped and nothing moves;
  // a held program stays held at its own plain hold.
  if (hiddenParkNotRun(args.park) !== null) return false

  const base = { mode: args.mode, tool: args.tool, resumeLine: args.resumeLine, warnings: [] as string[] }
  guidedMeasure = null
  guidedToolChangePark = null
  // WO-2521: every other flow starting here ends a typed change's claim.
  mdiGuidedChange = args.typedOnMdi === true && args.tool !== null ? { controller: ctrl, tool: args.tool } : null
  setToolChange({
    ...base,
    step: 'stopping',
    // WO-2520: the program's stop names the park it goes to.
    message: args.typedOnMdi === true
      ? 'Stopping the spindle...'
      : `Stopping the program cleanly, then parking at "${args.park.label}"...`,
  })
  if (args.alreadyStoppedAtProgramBoundary) {
    if (ctrl.machineState() !== 'idle') {
      return fail('The M6 boundary did not reach idle, so the tool-change park was not started.')
    }
  } else if (ctrl.hasActiveJob()) {
    stopJobForSession(ctrl)
    const stopped = await waitForMachine(
      () => !ctrl.hasActiveJob() && ctrl.machineState() === 'idle',
      8000,
    )
    if (!receiptIsCurrent(receiptToken)) return false
    if (!stopped) return fail('The machine did not come to a clean stop - resolve its state, then retry.')
  } else if (ctrl.machineState() === 'hold') {
    // Every line was already acked into the controller (short program / change
    // near the end), so there is no active job to stop - but the MACHINE is
    // holding at the pause with flushable moves possibly still buffered.
    // Same controlled stop: hold is already active, settle, then reset.
    await new Promise((r) => setTimeout(r, 600))
    if (!receiptIsCurrent(receiptToken)) return false
    resetForSession(ctrl)
    const stopped = await waitForMachine(() => ctrl.machineState() === 'idle', 8000)
    if (!receiptIsCurrent(receiptToken)) return false
    if (!stopped) return fail('The machine did not come to a clean stop - resolve its state, then retry.')
  } else if (ctrl.machineState() !== 'idle') {
    return fail('The machine must be idle (or holding in a job) to start a tool change.')
  }
  // ALL THREE, and it is a RE-check: the flow parks next, and the controlled
  // stop above can drop the datum. The message says so, because losing homing
  // here is a different event from never having homed.
  const changeRefusal = homingRefusal(ctrl, undefined,
    'the tool change parks at a machine coordinate. Re-home, then restart the tool change from the program panel.')
  if (changeRefusal) return fail(changeRefusal)

  setToolChange({ ...base, step: 'parking', message: `Parking at "${args.park.label}"...` })
  const parked = await parkForGuidedStop(ctrl, args.park, args.safeZMachine)
  if (!receiptIsCurrent(receiptToken)) return false
  if (!parked.ok) return fail(parked.reason)

  if (args.mode === 'toolChange') guidedToolChangePark = { park: args.park, safeZMachine: args.safeZMachine }
  setToolChange({ ...base, step: 'awaiting-swap', message: args.awaitingMessage })
  return true
}

export function beginGuidedToolChange(args: GuidedToolChangeBegin): Promise<boolean> {
  const pending = programGuidedToolChange
  const spindle = pending?.run.boundaries?.get(pending.boundaryIndex)?.toolChange?.spindle
  const manualSpindle = spindle && !machineSpindleIsDrivable(controlMachine(useCamStore.getState()), getMachineController())
    ? ` Start the spindle at the machine at ${spindle.rpm} RPM ${spindle.direction.toUpperCase()} before cutting.` : ''
  return stopAndPark({
    ...args,
    mode: 'toolChange',
    awaitingMessage:
      `Insert ${args.tool !== null ? `T${args.tool}` : 'the next tool'} and snug it${manualSpindle ? '; then' : '. Then'} `
        + 'press Continue: the tool is measured at the tool setter (right here if this machine has none) and the program resumes.' + manualSpindle,
  })
}

/**
 * Park + clamp pause (Operator's UCCNC "park + clamp material + resume"):
 * controlled stop mid-job, park clear of the work, operator repositions
 * clamps/material, then Continue re-arms the program via run-from-line. The
 * resume line is captured by the CALLER before the stop (typically the last
 * acked source line - a few already-executed buffered lines may re-run,
 * which cuts air: the safe direction).
 */
export function beginClampPause(
  args: Omit<GuidedToolChangeBegin, 'tool'> & { awaitingMessage?: string },
): Promise<boolean> {
  return stopAndPark({
    ...args,
    tool: null,
    mode: 'clampPause',
    awaitingMessage: args.awaitingMessage
      ?? 'Reposition your clamps/material - do NOT move the part itself or its zero. '
        + 'Then press Continue to re-arm the program where it left off.',
  })
}

/** Phase 2 for the clamp pause: no probe - just re-arm at the resume line.
 *  A program's clamp pause runs the rest from its held boundary, continuously
 *  or (CYCLE START with Single Block on) one block. */
export function continueClampPause(startMode: 'continuous' | 'single-block' = 'continuous'): boolean {
  const tc = store().toolChange
  if (!tc || tc.mode !== 'clampPause' || tc.step !== 'awaiting-swap') return false
  const pending = programClampPause
  if (pending !== null) {
    if (canContinueProgramClampPause(pending)) {
      // WO-2437 fix round: jog, Safe Z and the rest work at this stop
      // (WO-2237's pause -> move -> resume). The rest of the program starts
      // from the park, as it does when nobody moved: back there first.
      if (pending.park !== undefined && !atClampPausePark(pending.park)) {
        void returnToClampParkThenContinue(pending, pending.park, startMode)
        return true
      }
      programClampPause = null
      setToolChange(null)
      return continueProgramClampPause(pending, startMode)
    }
    programClampPause = null
  }
  const base = { mode: tc.mode, tool: tc.tool, resumeLine: tc.resumeLine, warnings: [] as string[] }
  setToolChange({ ...base, step: 'arming', message: 'Re-arming the program at the resume line...' })
  const armed = armRunFromLine(tc.resumeLine)
  if (!armed.ok) {
    setToolChange({ ...base, step: 'failed', message: `Could not re-arm the program: ${armed.reason}` })
    return false
  }
  setToolChange({
    ...base,
    step: 'ready',
    warnings: armed.plan.warnings,
    message:
      `The program is armed at line ${armed.plan.startLine} - a few already-cut lines may ` +
      'run again (cutting air). Review the cautions, then press CYCLE START.',
  })
  return true
}

type GuidedToolChangeBase = {
  mode: 'toolChange'
  tool: number | null
  resumeLine: number
  warnings: string[]
}
/** `commit` (WO-2042) records what the apply held back - the Ref's new reading -
 *  once the machine has accepted every work-offset write the apply queued. */
type ApplyToolOffset = (probedMachineZ: number) => {
  ok: boolean
  reason?: string
  report?: string
  commit?: () => void
}

/** WO-2025: the measured/applied line, held until the controller has confirmed the
 * offset (geometry write receipt) or the text route has re-armed. */
let guidedMeasureReport: string | null = null
/** WO-2042: the controller's own answer to the work-offset write(s) the
 *  measure's apply queued - accept, refusal, or its own call timeout. The
 *  program resumes only on true. */
let guidedMeasureWrite: { accepted: Promise<boolean> } | null = null

function awaitGuidedMeasureWrites(
  writes: readonly OpenWorkOffsetWrite[],
  commit: (() => void) | undefined,
): { accepted: Promise<boolean> } | null {
  if (writes.length === 0) {
    commit?.()
    return null
  }
  let answer!: (accepted: boolean) => void
  const accepted = new Promise<boolean>((resolve) => { answer = resolve })
  let waiting = writes.length
  let refused = false
  for (const write of writes) {
    write.settled.push((took) => {
      if (refused) return
      if (!took) {
        refused = true
        answer(false)
        return
      }
      waiting -= 1
      if (waiting > 0) return
      commit?.()
      answer(true)
    })
  }
  return { accepted }
}

function guidedToolChangeBase(tc: { tool: number | null; resumeLine: number }): GuidedToolChangeBase {
  return { mode: 'toolChange', tool: tc.tool, resumeLine: tc.resumeLine, warnings: [] }
}

/** Probe the fitted tool on the setter and hand its length to `applyOffset`.
 * True only once the offset is applied. WO-1996: a probe that does not return
 * a contact leaves the card at its M6 with Retry measure - never a dead end
 * that disarms the program. */
async function measureGuidedTool(
  base: GuidedToolChangeBase,
  probeConfig: ZProbeConfig,
  applyOffset: ApplyToolOffset,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
): Promise<boolean> {
  guidedMeasure = { probing: true, missAlarm: false, measured: false }
  setToolChange({ ...base, step: 'probing', message: 'Measuring the new tool on the tool setter...' })
  const probe = await runZProbeCycle('measureTool', probeConfig)
  if (!receiptIsCurrent(receiptToken)) {
    guidedMeasure = null
    return false
  }
  if (!probe.ok || probe.probedMachineZ === null) {
    guidedMeasure = {
      probing: false,
      missAlarm: getMachineController().machineState() === 'alarm'
        && !estopNeedsReset()
        && store().alarm?.positionLost !== true,
      measured: false,
    }
    const tool = base.tool === null ? 'The tool' : `T${base.tool}`
    const typed = guidedChangeIsTyped(base)
    setToolChange({
      ...base,
      step: 'awaiting-swap',
      message: `${probe.message} ${typed
        ? 'The typed tool change stays open.'
        : `The program is still held at the M6 on line ${base.resumeLine - 1}.`} `
        + `Retry measure ${guidedMeasure.missAlarm ? 'clears the probe alarm, ' : ''}raises Z and measures again at the setter.`,
    })
    store().pushConsole(
      'rx',
      `${tool} was not measured; ${typed
        ? 'the typed tool change stays open'
        : `the program stays at the M6 on line ${base.resumeLine - 1}`}. Retry measure is on the tool-change card.`,
      'warn',
    )
    return false
  }

  const writes: OpenWorkOffsetWrite[] = []
  workOffsetWriteWatch = (write) => {
    if (!writes.includes(write)) writes.push(write)
  }
  let applied: ReturnType<ApplyToolOffset>
  try {
    applied = applyOffset(probe.probedMachineZ)
  } finally {
    workOffsetWriteWatch = null
  }
  if (!applied.ok) {
    guidedMeasure = null
    setToolChange({ ...base, step: 'failed', message: applied.reason ?? 'Applying the tool length offset failed.' })
    return false
  }
  guidedMeasureReport = applied.report ?? null
  guidedMeasureWrite = awaitGuidedMeasureWrites(writes, applied.commit)
  return true
}

/**
 * Phase 2 (operator pressed Continue): probe the new tool, hand its length to
 * `applyOffset` (the UI records it in the tool table and sends G43.1), then
 * re-arm the program at the resume line. Ends at 'ready' - the operator
 * reviews the warnings and presses the canonical CYCLE START.
 */
export async function continueGuidedToolChange(
  probeConfig: ZProbeConfig,
  applyOffset: ApplyToolOffset,
): Promise<boolean> {
  const receiptToken = captureBackendReceipt(getMachineController())
  const tc = store().toolChange
  if (!tc || tc.mode !== 'toolChange' || tc.step !== 'awaiting-swap' || guidedMeasure !== null) return false
  const base = guidedToolChangeBase(tc)
  if (!(await measureGuidedTool(base, probeConfig, applyOffset, receiptToken))) return false
  return resumeAfterGuidedMeasure(base, receiptToken)
}

/**
 * WO-1996 Retry measure: after a miss, the same tool is measured by the same
 * setter routine - clear the miss's own probe alarm, then let the routine
 * raise Z and approach the setter. WO-2555: no extra tool-change park trip.
 * A hit applies the length and stops at 'ready' for a program's M6, or finishes
 * a typed change; a miss leaves Retry live. Nothing here resumes the program.
 */
export async function retryGuidedToolMeasure(
  probeConfig: ZProbeConfig,
  applyOffset: ApplyToolOffset,
): Promise<boolean> {
  const ctrl = getMachineController()
  const receiptToken = captureBackendReceipt(ctrl)
  const tc = store().toolChange
  const miss = guidedMeasure
  if (!tc || tc.mode !== 'toolChange' || tc.step !== 'awaiting-swap' || miss === null || miss.measured) return false
  const base = guidedToolChangeBase(tc)
  const refuse = (reason: string): false => {
    setToolChange({ ...base, step: 'awaiting-swap', message: `Retry measure did not run: ${reason}` })
    store().pushConsole('rx', `Retry measure did not run: ${reason}`, 'error')
    return false
  }
  if (ctrl.connectionPhase() !== 'connected') return refuse('not connected to a machine.')
  if (estopNeedsReset()) return refuse(ESTOP_BLOCKS_MOTION)
  if (ctrl.machineState() === 'alarm') {
    if (!miss.missAlarm || store().alarm?.positionLost === true) {
      return refuse('the machine is in an alarm the measure did not raise - clear it, then retry.')
    }
    miss.missAlarm = false
    if (!recoverFromProbeAlarm()) return refuse('the controller would not clear the probe alarm.')
    const cleared = await waitForMachine(() => ctrl.machineState() === 'idle', 5000)
    if (!receiptIsCurrent(receiptToken)) return false
    if (!cleared) return refuse('the controller did not return to idle after clearing the probe alarm.')
  }

  if (!(await measureGuidedTool(base, probeConfig, applyOffset, receiptToken))) return false
  // A dropped link can leave a kept-stop claim behind. Only its live stop
  // may finish here; a program M6 still waits for the operator's Continue.
  if (guidedChangeIsTyped(base) || (keptStopGuidedChange !== null
    && keptStopGuidedChange.tool === base.tool
    && programGuidedToolChange === null
    && liveKeptStop(ctrl) === keptStopGuidedChange.kept)) {
    return resumeAfterGuidedMeasure(base, receiptToken)
  }
  guidedMeasure = { probing: false, missAlarm: false, measured: true }
  setToolChange({
    ...base,
    step: 'ready',
    message: `${base.tool === null ? 'The tool' : `T${base.tool}`} measured and its length offset applied. `
      + `Continue resumes the program after the M6 on line ${base.resumeLine - 1}.`,
  })
  return true
}

/** WO-1996 Continue from the M6, once Retry measure has measured the tool. */
export async function continueGuidedToolChangeAfterRetry(): Promise<boolean> {
  const tc = store().toolChange
  if (!tc || tc.mode !== 'toolChange' || tc.step !== 'ready' || guidedMeasure?.measured !== true) return false
  return resumeAfterGuidedMeasure(guidedToolChangeBase(tc), captureBackendReceipt(getMachineController()))
}

/**
 * WO-2017: Z alone to a machine height at the machine's rapid, on either
 * controller shape, waited on until the board reports it there - the same
 * G53 G0 a park's Z leg is. Null on success, otherwise what did not happen.
 */
async function riseToMachineZAtRapid(ctrl: MachineController, z: number): Promise<string | null> {
  if (!ctrl.capabilities.gcodeText) {
    return nativeProbeMachineMove(ctrl, { z }, setterTravelFeed(resolveProbeConfig().positioningFeed))
  }
  if (estopNeedsReset()) return ESTOP_BLOCKS_MOTION
  const receiptToken = captureBackendReceipt(ctrl)
  const held = operatorModal(ctrl)
  const line = `G21 G90 G53 G0 Z${Number(z.toFixed(4))}`
  let sent: ReturnType<typeof sendAppCommand>
  try {
    sent = sendAppCommand(line, ctrl)
  } finally {
    restoreOperatorModal(ctrl, receiptToken, held)
  }
  if (!sent.ok) return unsentReason(sent) ?? `the controller refused ${line}`
  const there = await waitForMachine(() => {
    const at = ctrl.status().machinePos?.z
    return ctrl.machineState() === 'idle' && typeof at === 'number' && at >= z - SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM
  }, 30000)
  return there ? null : `the move to ${machinePositionText({ z })} did not settle idle at its target`
}

/** The tool's length is applied: release the held M6 boundary (geometry) or
 * re-arm the text program at the resume line. */
async function resumeAfterGuidedMeasure(
  base: GuidedToolChangeBase,
  receiptToken: ReturnType<typeof captureBackendReceipt>,
): Promise<boolean> {
  guidedMeasure = null
  const fail = (message: string): false => {
    setToolChange({ ...base, step: 'failed', message })
    return false
  }
  const sayMeasured = (): void => {
    if (guidedMeasureReport !== null) store().pushConsole('rx', guidedMeasureReport, 'info')
    guidedMeasureReport = null
  }

  // WO-2017: a measure made at the park (no setter routine) ends just above
  // the pad, and a park stated below safe Z leaves the tool there; the program
  // resumes with its own rapid, which would cross XY from that height. Rise to
  // the machine's safe Z first, at rapid, the way the park itself rose.
  const ctrl = getMachineController()
  const safeZ = guidedToolChangePark?.safeZMachine
  const nowZ = ctrl.status().machinePos?.z
  if (typeof safeZ === 'number' && Number.isFinite(safeZ)
    && (typeof nowZ !== 'number' || nowZ < safeZ - SETUP_BOUNDARY_CLEARANCE_TOLERANCE_MM)) {
    setToolChange({ ...base, step: 'arming', message: 'Raising Z to safe Z before the program resumes...' })
    const up = await riseToMachineZAtRapid(ctrl, safeZ)
    if (!receiptIsCurrent(receiptToken)) return false
    if (up) return fail(`Raising Z to safe Z after the measure stopped: ${up}. The program remains held.`)
  }

  // WO-2042: a queued offset write is not an applied one. The program resumes
  // only once the machine has taken it. No timer of ours here: the controller
  // always answers - accept, refusal, or its own call timeout (8 s on the
  // UC100) - and a late accept is still an accept. On a refusal the Ref's new
  // reading was never recorded, and the program stays held.
  const measureWrite = guidedMeasureWrite
  if (measureWrite !== null) {
    const accepted = await measureWrite.accepted
    if (!receiptIsCurrent(receiptToken) || guidedMeasureWrite !== measureWrite) return false
    guidedMeasureWrite = null
    if (!accepted) {
      guidedMeasureReport = null
      return fail('The controller refused the new tool offset, so its length is not applied; the program remains held.')
    }
  }

  // WO-2239: a change typed in a kept stop ends here - the tool is in and
  // measured, and the kept stop's CYCLE START is the return (no re-arm).
  const keptChange = keptStopGuidedChange
  if (keptChange !== null && keptChange.tool === base.tool) {
    keptStopGuidedChange = null
    const settled = await waitForMachine(
      () => !machineWorkOffsetWriteInFlight(controlMachineId()) && !ctrl.resetInProgress() && ctrl.machineState() === 'idle',
      5000,
    )
    if (!receiptIsCurrent(receiptToken)) return false
    if (!settled) return fail('The controller did not return to idle after the measure and offset write.')
    const kept = liveKeptStop(ctrl)
    if (kept === keptChange.kept && kept.resumed === null) {
      sayMeasured()
      keepStopTool(kept, base.tool)
      guidedToolChangePark = null
      setToolChange(null)
      store().pushConsole('rx', `T${base.tool} is fitted and measured. ${keptStopCycleStartSentence(kept)}`, 'info')
      return true
    }
  }

  // WO-2521: a change typed with no program ends here - the tool is in and
  // measured, and there is nothing to re-arm.
  const typedChange = mdiGuidedChange
  if (typedChange !== null && typedChange.controller === ctrl && guidedChangeIsTyped(base)) {
    mdiGuidedChange = null
    const settled = await waitForMachine(
      () => !machineWorkOffsetWriteInFlight(controlMachineId()) && !ctrl.resetInProgress() && ctrl.machineState() === 'idle',
      5000,
    )
    if (!receiptIsCurrent(receiptToken)) return false
    if (!settled) return fail('The controller did not return to idle after the measure and offset write.')
    sayMeasured()
    store().setActiveTool(typedChange.tool)
    guidedToolChangePark = null
    setToolChange(null)
    store().pushConsole('rx', `T${typedChange.tool} is fitted and measured; its length offset is applied.`, 'info')
    return true
  }

  const programPending = programGuidedToolChange
  if (programPending !== null) {
    if (machineWorkOffsetWriteInFlight(controlMachineId())) {
      const confirmed = await waitForMachine(
        () => !machineWorkOffsetWriteInFlight(controlMachineId()),
        5000,
      )
      if (!receiptIsCurrent(receiptToken)) return false
      if (!confirmed) return fail('The controller did not confirm the new tool offset; the program remains held.')
    }
    const settled = await waitForMachine(
      () => !programPending.run.controller.resetInProgress()
        && programPending.run.controller.machineState() === 'idle',
      5000,
    )
    if (!receiptIsCurrent(receiptToken)) return false
    if (!settled) {
      return fail('The controller did not return to idle after the M6 probe and offset write; the program remains held.')
    }
    sayMeasured()
    setToolChange({ ...base, step: 'arming', message: 'Tool offset confirmed. Resuming the program after M6...' })
    if (!continueProgramM6ToolChange(programPending)) {
      const reason = programM6ResumeRefusal(programPending)
      return fail(
        `The M6 probe finished, but the held program boundary could not be resumed${
          reason === null ? '' : ` because ${reason}`
        }. Nothing moved.`,
      )
    }
    return true
  }

  setToolChange({ ...base, step: 'arming', message: 'Re-arming the program at the resume line...' })
  // Resume at the line after the M6. An M0 that follows is in the file, so the
  // program stops there (owner ruling 10-04: "if it's there it stops the machine").
  const rawResume = stripGcodeComments(store().programText?.split(/\r?\n/)[base.resumeLine - 1] ?? '')
  const sameLineStop = /(?:^|\s)M0?6(?:\s|$)/i.test(rawResume) && PROGRAM_PAUSE.test(rawResume)
  const armed = armRunFromLine(base.resumeLine, sameLineStop ? base.resumeLine : undefined)
  if (!armed.ok) return fail(`Could not re-arm the program: ${armed.reason}`)

  sayMeasured()
  setToolChange({
    ...base,
    step: 'ready',
    warnings: armed.plan.warnings,
    message:
      `Tool measured and its length offset applied. The program is armed at line ${armed.plan.startLine} - ` +
      'review the cautions, then press CYCLE START.',
  })
  return true
}

/** WO-2565: only an operator's card press reports cancellation. Cleanup callers
 * stay silent, and the fitted tool record survives even after a confirmed swap.
 * A ready/failed card may already have measured, so it cannot claim otherwise. */
export function cancelGuidedToolChangeByOperator(): void {
  if (programToolChangeCanStop()) {
    const ctrl = getMachineController()
    if (ctrl.hasActiveJob()) ctrl.stopJob()
    else ctrl.reset()
    return
  }
  const { toolChange, activeTool } = store()
  cancelGuidedToolChange()
  if (toolChange === null || toolChange.mode !== 'toolChange') return
  const change = toolChange.tool === null ? 'Tool change' : `Tool change to T${toolChange.tool}`
  const action = toolChange.step === 'failed' ? 'closed' : 'cancelled'
  const measurement = toolChange.step === 'awaiting-swap' ? ' - nothing was measured' : ''
  const spindle = activeTool === null ? '' : ` T${activeTool} is still the tool in the spindle.`
  store().pushConsole('rx', `${change} ${action}${measurement}.${spindle}`, 'info')
}

/** Abandon the flow (the job stays stopped; the machine stays where it is). */
export function cancelGuidedToolChange(): void {
  programClampPause = null
  programGuidedToolChange = null
  keptStopGuidedChange = null
  mdiGuidedChange = null
  guidedMeasure = null
  guidedMeasureReport = null
  guidedMeasureWrite = null
  guidedToolChangePark = null
  setToolChange(null)
}

/** Apply a tool length offset (G43.1, from the tool table's reference math).
 *  WO-1611: the offset is mm; with no units word the line is read in the
 *  operator's held units, so an inch session read a 12.5 mm offset as 12.5
 *  inch. G21 prefixes the line (same fix as the pad probe's work-Z0 write,
 *  WO-1546) and G20 restores after - the operator stays in inch throughout.
 *
 *  WO-2042: `workZeroShiftMm` also moves the active frame's Z work zero - the
 *  reference tool re-measured at a guided M6. Every tool's offset is its setter
 *  reading minus the reference's, and the work zero was set against the
 *  reference's reading, so a new reference reading moves the work zero by the
 *  same difference and leaves every other tool cutting where it did. */
export function applyToolLengthOffset(deltaMm: number, workZeroShiftMm = 0): boolean {
  const c = getMachineController()
  lastToolLengthWorkZWrite = null
  if (!Number.isFinite(deltaMm) || !Number.isFinite(workZeroShiftMm)) return false
  if (c.capabilities.gcodeText !== true) return applyGeometryToolLengthOffset(c, deltaMm, workZeroShiftMm)
  const inch = store().parserModal?.units === 'inch'
  const applied = sendAppCommand(`${inch ? 'G21 ' : ''}G43.1 Z${Number(deltaMm.toFixed(4))}`, c)
  if (inch) sendAppCommand('G20', c)
  if (applied.sent) c.refreshState()
  if (!applied.ok || workZeroShiftMm === 0) return applied.ok
  // Audit: the frame the HELD program resumes in, as the geometry route
  // does - never whichever offset happens to be selected during the hold.
  const wcs = pendingToolChange?.hold.wcs ?? store().activeWcs
  const currentZ = wcs === null ? undefined : store().offsets[wcs]?.[2]
  if (wcs === null || typeof currentZ !== 'number' || !Number.isFinite(currentZ)) return false
  // WO-2267: the reference tool's shift moves Z0 by the tool, not the surface,
  // so an applied surface mesh carries across it.
  noteToolLengthZShift(wcs, currentZ + workZeroShiftMm)
  if (!setWorkOffsetValue(wcs, 'Z', currentZ + workZeroShiftMm, c)) return false
  // The length itself is in G43.1 here, so no tool length is in this write.
  lastToolLengthWorkZWrite = { wcs, fromZ: currentZ, toZ: currentZ + workZeroShiftMm, toolLengthPartMm: 0 }
  return true
}

/** WO-2522: a work offset's Z write queued by a tool-length apply. `toZ - fromZ`
 *  is what the offsets table shows the offset move by; `toolLengthPartMm` is the
 *  part of that which is tool length (a geometry controller folds the length
 *  into Z, taking the last tool's out), the rest is `workZeroShiftMm`. */
export type ToolLengthWorkZWrite = { wcs: WcsId; fromZ: number; toZ: number; toolLengthPartMm: number }

/** WO-2522: the work offset's Z write the most recent `applyToolLengthOffset`
 *  queued - null when it wrote none (the text route's G43.1 alone, or a
 *  refused apply). The write is queued, not yet taken: the guided measure
 *  prints its line only once the controller has accepted it. */
export function lastToolLengthWorkOffsetWrite(): ToolLengthWorkZWrite | null {
  return lastToolLengthWorkZWrite
}

/** Clear the tool length offset (G49). G49 carries no number, so there is no
 *  value for a missing units word to misread; the operator's units are left
 *  exactly as G43.1 above leaves them - tested alongside it (WO-1611). */
export function clearToolLengthOffset(): boolean {
  const c = getMachineController()
  // WO-1548: a geometry controller holds the offset in the work offset's Z.
  if (c.capabilities.gcodeText !== true) return clearGeometryToolLengthOffset(c)
  const cleared = sendAppCommand('G49', c)
  if (cleared.sent) c.refreshState()
  return cleared.ok
}

export type { ControlAxis, JogAxis } from './controller'
export type { WcsId } from './types'
